(window.GIM_TP=window.GIM_TP||{})["Z.Shlach.0"]={"from":0,"a":[[[],[],[]],[["(במדבר י״ג:א׳-ב׳) וַיְדַבֵּר יְיָ אֶל מֹשֶׁה לֵאמֹר, שְׁלַח לְךָ אֲנָשִׁים וְיָתוּרוּ אֶת אֶרֶץ כְּנַעַן וְגוֹ'. רִבִּי חִיָּיא פָּתַח, (איוב ל״ח:י״ב) הֲמִיָּמֶיךָ צִוִּיתָ בֹּקֶר יִדַּעְתָּ הַשַּׁחַר מְקוֹמוֹ. שַׁחַר כְּתִיב, הֵ\"א אִתְרַחֲקָא מִשַּׁחַר. מַאי טַעְמָא. אֶלָּא אָמַר רִבִּי חִיָּיא, בְּשַׁעֲתָא דְּנָטֵי עֵרֶב, וְשִׁמְּשָׁא נָטֵי לְמֵיעַל, כְּדֵין אִתְחֲלָשׁ תּוּקְפֵּיהּ, כְּדֵין שַׁלְטָא שְׂמָאלָא, וּמִשְׁתְּכַח דִּינָא בְּעָלְמָא, וְאִתְפָּשַּׁט (לעילא). וּכְדֵין בָּעֵי בַּר נָשׁ לְצַלָּאָה, וּלְכַוְּנָא רְעוּתָא (ס\"א לצלאה דישכח רעותא) קַמֵּי מָארֵיהּ.","דְּאָמַר רִבִּי יֵיסָא, כַּד נָטֵי שִׁמְשָׁא, וְאִתְחַלָּשׁ, כְּדֵין אִתְפְּתַח חַד פְּתִיחוּ בְּשִׁמְשָׁא, וְאִתְכְּנִישׁ חֵילֵיהּ, וּשְׂמָאלָא שַׁלִּיט. וְיִצְחָק כָּרֵי בֵּירָא תְּחוֹתֵיהּ.","כֵּיוָן דְּעָאל לֵילְיָא, פִּתְקָא דְּקוּטְפָא בְּאַחֲמָתֵיהּ שְׁכִיחַ. וְכַמָּה חֲבִילִין טְרִיקָן (אזדריקו) אִתְפָּשָׁטוּ בְּעָלְמָא, וְכֻלְּהוּ שָׁטָאן בְּעִרְבּוּבְיָא, וְאָזְלֵי וְחַיְיכָאן בְּנַפְשָׁן דְּרַשִּׁיעַיָּיא, (ס\"א דבני נשא) וּמוֹדְעִין לוֹן מִלִּין, מִנְּהוֹן כְּדִיבָן, וּמִנְּהוֹן קְשׁוֹט, וּמַאן דְּאִשְׁתְּכַח בֵּינַיְיהוּ, אִתְיְיהִיב לוֹן רְשׁוּ לְחַבְּלָא, וְכֻלְּהוּ בְּנֵי עָלְמָא נַיְימִין, (ואתכנשו) וְטַעֲמִין טַעֲמָא דְּמוֹתָא, וְהָא אוֹקִימְנָא.","תָּא חֲזֵי, כַּד אִתְּעַר רוּחַ צָפוֹן, כְּדֵין אִתְקַבְּלָא כְּנֶסֶת יִשְׂרָאֵל בִּשְׂמָאלָא, וְאִתְחַבָּרוּ כַּחֲדָא וְשַׁרְיָא בִּדְרוֹעָא בְּאַתְרָהָא. וְקוּדְשָׁא בְּרִיךְ הוּא אָתֵי לְאִשְׁתַּעְשְׁעָא עִם צַדִּיקַיָּיא דִּבְגִנְתָּא דְּעֵדֶן, וּכְדֵין כָּל מַאן דְּיִתְּעַר לְמִלְעֵי בְּאוֹרַיְיתָא בְּהַהוּא שַׁעֲתָא. הָא אִשְׁתְּתַּף בַּהֲדָהּ, בְּגִין דְּהִיא (יתבת) וְכָל אֻכְלוּסִין דִּילָהּ, מְשַׁבְּחָן לְמַלְכָּא עִלָּאָה, וְכָל אִינּוּן דְּאִשְׁתְּכָחוּ (נ\"א דאשתתפו בהדה) בְּתוּשְׁבַּחְתָּא דְּאוֹרַיְיתָא, כֻּלְּהוּ כְּתִיבִין בִּבְנֵי הֵיכָלָא, וְאִקְרוּן בִּשְׁמֵהוֹן, וְאִלֵּין רְשִׁימִין בִּימָמָא.","תָּא חֲזֵי שְׁמָא חֲדָא קַדִּישָׁא אִית בִּגְלוּפֵי אַתְוָון, דְּהוּא שַׁלְטָא מִפַּלְגוּ לֵילְיָא וְאֵילָךְ, וְאִינּוּן אַתְוָון (כל\"ך סעפ\"ה יאעוצ\"ה) ם דְּמַנְצַפָּךְ כָּלִיל לוֹן, אוּקְמוּהָ, (ישעיה ט) לְםַרְבֵּה הַמִשְׂרָה. נ' הֲוָה אַסְתִּים לְהַאי וּלְהַאי, כְּדֵין כִּתְרִין כְּלִילָן הוּא ו' (נ\"א י') דִּשְׁמָא קַדִּישָׁא אַתְקִין לֵיהּ. וְסָתִים מַבּוּעָהָא. בָּתַר דְּאוֹלִידַת, פְּתִיחָא הֲוַת בְּחַד רֵישָׁא דְּפִתְחָא.","כַּד אִתְחֲרִיב בֵּי מַקְדְּשָׁא, אַסְתִּימוּ מַבּוּעִין מִכָּל סִטְרִין. (ס\"א את דאכליל אתוון) וְאַכְלִיל אַתְוָון אַחֲרָן, וְאִינּוּן שִׁבְעָה. תְּלַת מֵהַאי סִטְרָא, ואַרְבַּע מֵהַאי סִטְרָא. כל\"ך. וְסִימָן (שיר השירים ד׳:ז׳) כֻּלָּךְ יָפָה רַעְיָתִי וּמוּם אֵין בָּךָ, ן' דְּכַר וְנוּקְבָּא כָּלִיל כַּחֲדָא, דָּא כָּלִיל תְּלַת מִכָּאן וּתְלַת מִכָּאן וְאִינּוּן שִׁית. וְאוֹקִימְנָא בְּאִלֵּין תְּרֵין אַתְוָון ם' ן' (נ\"א ס' ו') אִתְכְּלָלוּ (תליסר) תְּרֵיסָר אַתְוָון סָלִיק מִנַּיְיהוּ תְּרֵי. חַד לַאֲתָר חַד, וְחַד לַאֲתָר חַד. (נ\"א לאת חד וחד לאת חד)","כל\"ך סעפ\"ה יאע\"וצה, הָכִי אִתְגְּלִיפוּ אַתְוָון, וְרָזָא דָּא בְּכִי תֵצֵא לַמִּלְחָמָה, קְרָא דִּכְתִּיב, (דברים כ״ב:כ״ג) כִּי יִהְיֶה נַעֲרָה בְתוּלָה. נַעֲר כְּתִיב, בָּתַר דְּאִסְתָּלַק לֵילְיָא, וְצַפְרָא נָהִיר, כְּדֵין ה' סַלְּקָא וְאִתְכְּלִילַת בִּנְהוֹרָא עִלָּאָה. וּכְדֵין יִדַּעְתָּ הַשַּׁחַר מְקוֹמוֹ, דְּיָדַע (דודאי) שַׁחַר מְקוֹמוֹ דְּהֵ\"א, וְאִתְכְּלִילַת בְּגַוִיהּ."],[[0,"וידבר וגו׳ שלח לך אנשים וגו׳:","רבי חייא פתח, המימיך צוית בקר ידעת השחר מקומו. שחר כתוב, בלי ה׳ הידיעה, \u0003ה׳\u0004 נתרחקה משחר, מהו הטעם. אלא אמר ר׳ חייא בשעה שינטו צללי ערב והשמש שהוא ז״א, נוטה לבא, דהיינו אחר חצות היום, אז נחלש תוקפו של השמש, שהוא ז״א, אז שולט השמאל ונמצא הדין בעולם ומתפשט, ואז צריך האדם להתפלל, ולכוון רצונו, לפני אדונו."],[1,"דאמר רבי ייסא וכו׳:","דאר״י, כשנוטה השמש, שהוא ז״א, לבא, ונחלש, דהיינו אחר חצות היום, אז נפתח פתח אחד בהשמש, דהיינו הפתח של שליטת השמאל, ונאסף כחו של השמש, שהוא ז״א, וקו האמצעי. והשמאל שולט. ויצחק, שהוא קו השמאל, כורה באר תחתיו, שהיא המלכות שיניקתה משמאל. ואז הוא מיסד אותה."],[2,"כיון דעאל ליליא וכו׳:","כיון שנכנס הלילה, כתבי הגזירות שכיחים בכיס שלהם. וכמה גדודי חבלה מתפשטים בעולם, וכולם משוטטים בערבוביא, והולכים ומצחקים בנפשות הרשעים, ומודיעים להם דברים, מהם שקרים ומהם אמיתים. ומי שימצא ביניהם מבני אדם, ניתנה להם רשות לחבל. וכל בני העולם ישנים וטועמים טעם מות. וכבר העמדנו. \u0003פתקא\u0004 פירושו כתב. \u0003קוטפא,\u0004 פירושו גזירה, מלשון וקטפת מלילות (דברים כ״ג) שפירושו כריתה וגזירה. \u0003אחמתא\u0004 פירושו כיס, כמו והשתכח באחמתא (עזרא ו׳ ב׳) שפירושו חמת וכיס."],[3,"ת״ח כד אתער וכו׳:","בוא וראה, כשמתעורר רוח צפון, אז מתקבלת כנסת ישראל, שהיא המלכות, בשמאל של ז״א, ומתחברים יחד, ושורה בזרוע שמאל במקומה. והקב״ה בא להשתעשע עם הצדיקים שבגן עדן (כמ\"ש ויקהל אות ט״ו ע\"ש) ואז כל מי שיתעורר לעסוק בתורה בשעה ההיא, הוא משתתף עם המלכות, משום שהיא וכל המוניה משבחים למלך העליון, שהוא ז״א. וכל אלו הנמצאים אז בתשבחה של התורה, כולם כתובים בין בני ההיכל, ונקראים שם בשמותיהם. ואלו רשומים ביום, דהיינו שרשומים לקבל חסדים, שהוא מדת היום, שהוא ז\"א."],[4,"ת״ח שמא חדא וכו׳:","בוא וראה, שם אחד קדוש יש באותיות חקוקות השולט מחצות לילה והלאה, והם האותיות \u0003כל״ך סעפ״ה יאע״וצה,\u0004 ד \u0003ם״ן\u0004 דמנצפ״ך כולל אותם. \u0003ם׳\u0004 העמידוהו, בסו״ה, ל \u0003ם\u0004 רבה המשרה, ש \u0003ם'\u0004 סתומה כתובה באמצע המלה, שהיא רומזת לבינה בעת שליטת השמאל שהאורות סתומים בה. \u0003נ׳\u0004 היתה סותמת לזו ולזו, היינו ה \u0003נ׳\u0004 כפופה בסוד נפלה ולא תוסיף, סתמה הבינה והמלכות. כי אז הספירות היו כלולות, דהיינו שהמלכות והבינה נכללו זו בזו, והיתה גם הבינה בנפילה כמו המלכות, ה \u0003ו׳\u0004 של השם הקדוש התקין את המלכות שה״ס \u0003נ׳\u0004 והמשיך לה קו השמאל בצורת \u0003ו׳,\u0004 שאז קמה מנפילתה, אבל, וסתם המבועים שלה. כי ע״י שליטת השמאל נסתמו האורות ונקפאו. (כנ״ל ב\"א דף צ׳ ד״ה כתיב) ועד״ז היתה הבינה נסתמת בשליטת קו שמאל. שע״כ נקראת הבינה אז \u0003ם׳\u0004 סתומה. ואחר שהולידה הבינה את ה \u0003ו׳\u0004 דהויה שהוא ז״א, שה״ס קו האמצעי או המלכות הולידה את הנשמה, אז נעשתה פתוחה בראש פתח אחד, דהיינו שה \u0003ם׳\u0004 סתומה נפתחה מלמטה ונעשתה ל \u0003מ׳\u0004 פתוחה."],[4,"","פירוש, שהזהר מדבר כאן מבינה ומלכות בבת אחת, כי מטעם עלית המלכות לבינה נתכללו זה בזה, כמו שמביא הזהר עצמו. \u0003נ׳ הוה אסתים להאי ולהאי, כדין כתרין כלילן הוא.\u0004 וע״כ ה \u0003ם'\u0004 סתומה הרומזת על בינה בעת שהיא בשליטת השמאל, מפרשה הזהר גם על המלכות. ולא עוד, אלא אפילו הצורה של \u0003ם׳\u0004 סתומה מפרשה בצורת \u0003נ׳\u0004 כפופה שהיא המלכות, עם \u0003ו',\u0004 שה״ס זרוע השמאל של ה \u0003ו',\u0004 המתחברת עם צורת ה \u0003נ׳\u0004 וסותמתה, ועושית אותה לצורה מרובעת כמו \u0003ם׳\u0004 סתומה. ואח״כ חוזר לבינה, שנאמר בתקונים, כי אחר שהבינה הולידה את ה \u0003ו׳\u0004 שה״ס ז״א נפתחה ה \u0003ם׳\u0004 סתומה ונעשתה ל \u0003מ׳\u0004 פתוחה, שהיא ג״כ צורת \u0003נ\u0004 בחבור עם \u0003ו׳,\u0004 אלא שיש לה פתח מלמטה. הרומז שנפתחה מסתימתה ומשפעת אורותיה לתחתינים. ואח״כ חוזר ומדבר ממלכות, שאומר בדבור שלאחר מכאן, \u0003כד אתחריב בי מקדשא\u0004 וכו' שחזר שוב לדבר מ \u0003ם׳\u0004 סתומה שבמלכות."],[5,"כד אתחריב בי וכו׳:","כשנחרב בית המקדש, דהיינו בעת שאין זווג ז״א ומלכות שאז נחרב בית המקדש, שהיא המלכות. נסתמו המבועים של המלכות מכל הצדדים. דהיינו שנעשתה ל \u0003ם'\u0004 סתומה שנקפאו כל אורותיה (כנ״ל ב״א דף צ׳ ד״ה כתיב) וה \u0003ם׳\u0004 סתומה כוללת אותיות אחרות, והם שבע אותיות, משם הקדוש הנ״ל, ג׳ מצד זה, שהן \u0003סע״ו\u0004 וארבע מצד זה, שהן \u0003אעצ״ה.\u0004 כלך יפה, הנשארות מהשם הקדוש, והסימן, כלך יפה רעיתי ומום אין בך, ה״ס \u0003ן׳\u0004 הרומזת על דכר ונוקבא שהם זו\"ן, כלולים יחד. ו \u0003ן'\u0004 זו כלולה ג׳ אותיות מכאן, שהן \u0003כל\"ך,\u0004 וג' מכאן, שהן \u0003יפ״ה.\u0004 והם שש אותיות. והעמדנו שבאלו ב׳ אותיות \u0003ם׳ ן׳,\u0004 נכללות י״ג אותיות השם הקדוש, \u0003כל\"ך סעפ״ה יאעוצ״ה\u0004. כי עולה מהן שתי בחינות, בחינה אחת באות אחת, שהיא \u0003ם׳,\u0004 ואחת באות אחת שהיא \u0003ן׳.\u0004"],[6,"כל״ך סעפ״ה וכו׳:","כל\"ך סעפ\"ה יאעוצ״ה, כך נחקקו האותיות. וזה סוד בפרשת כי תצא למלחמה בהמקרא שכתוב, כי יהיה נערה בתולה, שכתוב נער, בלי \u0003ה׳.\u0004 ואחר שנסתלק הלילה והבוקר מאיר, אז עולה ה \u0003ה׳\u0004 ונכללת באות העליון. ואז נאמר, \u0003ידעת השחר מקומו\u0004 ששחר, שהוא ז״א ידע מקומו של ה \u0003ה׳,\u0004 והיא נכללת בתוכו."],[6,"","פירוש המאמר, כי ב׳ בחינות הם בלילה, האחת היא, חצי לילה הראשון, שאז המלכות בלי זווג עם ז״א וה״ס \u0003ם'\u0004 סתומה, שכל אורותיה נקפאים. וז״ש (באות ג') \u0003כיון דעאל ליליא\u0004 וכו'. ובחינה השניה היא חצי לילה השני דהיינו מחצות לילה ואילך, שאז יש זווג זו״ן בסוד שמאלו תחת לראשי. ובסוד הקב״ה, שהוא ז״א נכנס בגן עדן, שהוא המלכות, ונכללו דכר ונוקבא יחד שע״ז רומזת \u0003ן׳.\u0004"],[6,"","והצרופים היוצאים מן השם בן י״ג אותיות, \u0003כל״ך סעפ״ה יאעוצ״ה,\u0004 השולט בחצות לילה, הם \u0003סעו אעצה כלך יפה.\u0004 והיינו בדרך זה, \u0003כלך\u0004 סע \u0003פה י\u0004 אעוצה. והפירוש הוא ע״ד שהיה ביציאת מצרים, שהיתה הנוקבא בסוד \u0003ם׳\u0004 סתומה, וישראל נמצאו בצרה גדולה, אז יעץ לו הקב״ה למשה דבר אל בני ישראל \u0003ויסעו,\u0004 דהיינו שע״י נסיעתם למטה יעוררו למעלה סוד הנסיעה בג' קוין והמלכות תתיחד עם קו אמצעי, שמזה נפתחה המלכות מסתימתה, ונעשה להם נס של קריעת ים סוף. וגם כאן בחצות לילה שה \u0003ם׳\u0004 סתומה שולטת שה״ס שמאל בלי ימין, וצריכים להעביר הדינים מן המלכות, שולט השם \u0003סעו אעצה,\u0004 שפירושו, שהקב״ה מיעץ לנסוע ולהמשיך ג׳ קוין בסוד הזווג עם הנוקבא, המרומז ב \u0003ן׳\u0004 דמנצפ״ך, ואז, \u0003אתער רוח צפון\u0004 (באות ד') שה״ס שמאלו תחת לראשי, וז״ש \u0003כדין אתקבלא כנסת ישראל בשמאלא ואתחברו כחדא.\u0004 דהיינו בסוד \u0003ן׳\u0004 דמנצפ״ך. ואז יוצא הצירוף \u0003כל״ך יפ״ה.\u0004 שפירושו, בסו\"ה \u0003כלך יפה\u0004 רעיתי ו \u0003מום\u0004 אין בך. \u0003ומום\u0004 רומז על \u0003ם׳\u0004 סתומה שע״י הזווג עם ז״א נעברה ה \u0003ם'\u0004 סתומה, ואינה עוד בה."],[6,"","וז״ש (באות ה') \u0003שמא חדא\u0004 וכו' \u0003שלטא מפלגו ליליא\u0004 וכו' \u0003כל״ך סעפ״ה יאעוצ״ה\u0004 ד \u0003ם' ן׳ דמנצפ״ך כליל לון,\u0004 כי ה \u0003ם'\u0004 סתומה כוללת הצירוף של ז׳ אותיות \u0003סע״ו אעצ״ה,\u0004 כי מחמת שליטת הדינים שבה, נגלה שם הזה, \u0003המיעץ\u0004 לעורר סוד \u0003הנסיעה.\u0004 וז״ש (באות ו') \u0003ואכליל אתוון אחרן ואינון שבעה, תלת מהאי סטרא וארבע מהאי סטרא,\u0004 דהיינו כזה. \u0003סעו ם׳ אעצה,\u0004 שזה יורה, שבסבת ה \u0003ם׳\u0004 סתומה נתעוררו ב׳ צירופים אלו בני ז׳ אותיות. וה \u0003ן׳\u0004 כוללת הזווג שנעשה מסוד הנסיעה, שעל ידיהם מתגלים ב׳ הצירופים \u0003כל״ך יפ״ה,\u0004 וה \u0003ם'\u0004 סתומה נעברה. וז״ש, \u0003ן׳ דכר ונוקבא כליל כחדא,\u0004 דהיינו שרומז על הזווג דחצות שנעשה בסבת הנסיעה, \u0003דא כליל תלת מכאן ותלת מכאן,\u0004 דהיינו כזה. כל\"ך \u0003ן׳\u0004 יפ״ה. שהוא רומז שה \u0003ן׳\u0004 שה״ס הזווג של זו״ן, גילה זה השם במלכות שיורה \u0003שכולה יפה,\u0004 ואין עוד בה הדינים ד \u0003ם'.\u0004 וז״ש (באות ו') \u0003כלך יפה, וסימן, כלך יפה רעיתי ומום אין בך,\u0004 דהיינו כמבואר. והמלה \u0003מום\u0004 מורה על מם סתומה, שעברה ממנה ואין בה. ונמצא שה \u0003ם׳\u0004 כוללת ב׳ צירופים מן השם שהם ז׳ אותיות, וה \u0003ן׳\u0004 כוללת ב׳ צירופים מן השם, שהם שש אותיות. וז״ש, \u0003באלין תרין אתוון ם׳ ן׳ אתכללו תליסר אתוון.\u0004 דהיינו כל השם הקדוש. וז״ש \u0003סליק מנייהו תרי\u0004 דהיינו ב׳ בחינות שבלילה, \u0003חד לאת חד,\u0004 בחינת חצי לילה הראשונה לאות \u0003ם׳. וחד לאת חד,\u0004 ובחינת מחצות לילה ואילך, היא לאות \u0003ן׳.\u0004 כנ״ל."],[6,"","ועכ״ז הזווג דחצות אינו מספיק להשלים המלכות, וכל השלמתה הוא בזווג הבקר שאז מקבלת החסדים. וז״ש (באות ז׳) \u0003ורזא דא וכו׳ כי יהיה נערה בתולה נער כתיב,\u0004 כי בלילה נקראת המלכות נער בלי ה׳, כי \u0003ה'\u0004 יורה שהיא מלאה בחסדים. וז״ש, \u0003בתר דאסתלק ליליא וצפרא נהיר כדין ה׳ סלקא ואתכלילת בנהורא עלאה,\u0004 דהיינו שנכללת בחסדים דז״א ואז נקרא נערה עם \u0003ה׳.\u0004 וז״ש, \u0003דידע שחר מקומו דה׳ ואתכלילת בגויה,\u0004 שזה תירוץ על מה ששואל (באות א׳) \u0003שחר כתיב ה׳ אתרחקא משחר מאי טעמא.\u0004 ובהאמור מתורץ זה, כי בלילה שנקראת נער בלי \u0003ה'\u0004 אז \u0003ה׳\u0004 אתרחקא משחר, שהוא ז״א. וביום שנקראת נערה ב \u0003ה׳,\u0004 אז קוראים, \u0003השחר\u0004 עם ה', משום \u0003דידע שחר מקומו דה׳.\u0004 כמבואר."]],[[0,"","וַיְדַבֵּר ה' אֶל מֹשֶׁה לֵּאמֹר שְׁלַח לְךְ אֲנָשִׁים וְיָתֻרוּ אֶת אֶרֶץ כְּנַעַן וְגוֹ'. רַבִּי חִיָּיא פָּתַח, (איוב לח) הֲמִיָּמֶיךְ צִוִּיתָ בֹּקֶר יִדַּעְתָּה שַׁחַר מְקֹמוֹ. כָּתוּב שַׁחַר, הֵ\"א הִתְרַחֲקָה מִשַּׁחַר. מָה הַטַּעַם? אֶלָּא אָמַר רַבִּי חִיָּיא, בְּשָׁעָה שֶׁנּוֹטֶה הָעֶרֶב וְהַשֶּׁמֶשׁ נוֹטֶה לְהִכָּנֵס, אָז נֶחֱלָשׁ כֹּחוֹ, וְאָז שׁוֹלֵט, הַשְּׂמֹאל וְנִמְצָא דִּין בָּעוֹלָם וּמִתְפַּשֵּׁט (למעלה). וְאָז צָרִיךְ הָאָדָם לְהִתְפַּלֵּל וּלְכַוֵּן רָצוֹן (להתפלל שימצא רצון) לִפְנֵי רִבּוֹנוֹ."],[1,"","שֶׁאָמַר רַבֵּי יֵיסָא, כְּשֶׁנּוֹטֶה הַשֶּׁמֶשׁ וְנֶחֱלָשׁ, אָז נִפְתָּח פֶּתַח אֶחָד בַּשֶּׁמֶשׁ וּמִתְכַּנֵּס כֹּחוֹ, וְהַשְּׂמֹאל שׁוֹלֵט, וְיִצְחָק כּוֹרֶה בְּאֵר תַּחְתָּיו."],[2,"","כֵּיוָן שֶׁנִּכְנָס הַלַּיְלָה, הַשְּׁטָר שֶׁל הַכְּרִיתָה מָצוּי בְּאוֹצָרוֹ, וְכַמָּה קְבוּצוֹת מְחַבְּלִים מַזִּיקִים (נזרקים) מִתְפַּשְּׁטִים בָּעוֹלָם, וְכֻלָּם מְשׁוֹטְטִים בְּעִרְבּוּבְיָה, וְהוֹלְכִים וְצוֹחֲקִים בְּנַפְשׁוֹת הָרְשָׁעִים (שלבני אדם) וּמוֹדִיעִים לָהֶם דְּבָרִים, מֵהֶם כּוֹזְבִים וּמֵהֶם אֱמֶת, וּמִי שֶׁנִּמְצָא בֵינֵיהֶם, נִתְּנָה לוֹ רְשׁוּת לְחַבֵּל, וְכָל בְּנֵי הָעוֹלָם יְשֵׁנִים (והתכנסו) וְטוֹעֲמִים טַעַם מָוֶת, וַהֲרֵי בֵּאַרְנוּ."],[3,"","בֹּא וּרְאֵה, כְּשֶׁמִתְעוֹרֶרֶת רוּחַ צָפוֹן, אָז מִתְקַבֶּלֶת כְּנֶסֶת יִשְׂרָאֵל בִּשְׂמֹאל, (ומתחברים כאחד) וְשׁוֹרֶה בַּזְּרוֹעַ בִּמְקוֹמָהּ. וְהַקָּדוֹשׁ בָּרוּךְ הוּא בָּא לְהִשְׁתַּעֲשֵׁעַ עִם הַצַּדִּיקִים שֶׁבְּגַן עֵדֶן, וְאָז כָּל מִי שֶׁמִּתְעוֹרֵר לַעֲסֹק בַּתּוֹרָה בְּאוֹתָהּ שָׁעָה מִשְׁתַּתֵּף יַחַד אִתָּהּ, מִשּׁוּם שֶׁהִיא (יושבת) וְכָל אוּכְלוּסֶיהָ מְשַׁבְּחִים לַמֶּלֶךְ הָעֶלְיוֹן, וְכָל אֵלּוּ שֶׁנִּמְצָאִים (שהשתתפו אתה) בְּתִשְׁבְּחוֹת הַתוֹרָה, כֻּלָּם כְּתוּבִים בִּבְנֵי הַהֵיכָל וְנִקְרָאִים בִּשְׁמוֹתָם, וְאֵלֶּה רְשׁוּמִים בַּיּוֹם."],[4,"","בֹּא וּרְאֵה, שֵׁם קָדוֹשׁ אֶחָד יֵשׁ בְּאוֹתִיּוֹת חֲקוּקוֹת, שֶׁהוּא שׁוֹלֵט מֵחֲצוֹת הַלַּיְלָה וְאֵילָךְ, וְהֵן אוֹתִיּוֹת (כל\"ך סעפ\"ה יאעוצ\"ה) ם' שֶׁל מנצפ\"ךָּ כּוֹלֵל אוֹתָם. ם פֵּרְשׁוּהָ (ישעיה ט) לְםַרְבֵּה הַמִּשְׂרָה. נ' הָיְתָה סְתוּמָה לָזֶה וְלָזֶה, וְאָז כְּתָרִים כְּלוּלִים הוּא ו' (י') שֶׁל הַשֵּׁם הַקָּדוֹשׁ הִתְקִינוֹ, וְסָתַם מַבּוּעֶיהָ. אַחַר שֶׁיָּלְדָה, פְּתוּחָה הָיְתָה בְרֹאשׁ אֶחָד שֶׁל הַפֶּתַח."],[5,"","כְּשֶׁחָרַב בֵּית הַמִּקְדָּשׁ נִסְתְּמוּ הַמַּבּוּעִים מִכָּל הַצְּדָדִים, (אות זו כוללת אותיות) וְנִכְלְלוּ אוֹתִיּוֹת אֲחֵרוֹת, וְהֵן שֶׁבַע. שָׁלֹשׁ מִצַּד זֶה, וְאַרְבַּע מִצַּד זֶה. כל\"ךָּ. וְסִימָן - (שיר השירים ד) כֻּלָּךְ יָפָה רַעְיָתִי וּמוּם אֵין בָּךְ. ן' זָכָר וּנְקֵבָה כְּלוּלִים כְּאֶחָד, זֶה כּוֹלֵל שָׁלֹשׁ מִכָּאן וְשָׁלֹשׁ מִכָּאן, וְהֵם שֵׁשׁ. וּבֵאַרְנוּ, בִּשְׁתֵּי אוֹתִיּוֹת אֵלֶּה, ם' ן', נִכְלְלוּ שְׁתֵּים עֶשְׂרֵה אוֹתִיּוֹת. הָסֵר מֵהֶן שְׁתַּיִם, אַחַת לְמָקוֹם אֶחָד, וְאַחַת לְמָקוֹם אֶחָד."],[6,"","כל\"ך סעפ\"ה יאעוצ\"ה, כָּךְ נֶחְקְקוּ הָאוֹתִיּוֹת, וְסוֹד זֶה בְּכִי תֵצֵא לַמִּלְחָמָה, פָּסוּק שֶׁכָּתוּב (דברים כב) כִּי יִהְיֶה נַעֲרָה בְתוּלָה. נַעֲרָ כָּתוּב. אַחַר שֶׁהִסְתַּלֵּק הַלַּיְלָה וְהַבֹּקֶר מֵאִיר, אָז ה' עוֹלָה וְנִכְלֶלֶת בְּאוֹר עֶלְיוֹן, וְאָז - יִדַּעְתָּה שַּׁחַר מְקוֹמוֹ, שֶׁיָּדַע (שודאי) שַׁחַר מְקוֹמוֹ שֶׁל הֵ\"א, וְנִכְלָל בְּתוֹכוֹ."]]],[["תָּא חֲזֵי, מֹשֶׁה הֲוָה שִׁמְשָׁא, וּבָעָא לְאַעְלָאָה לְאַרְעָא. אָמַר לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא, מֹשֶׁה, כַּד אָתֵי נְהוֹרָא דְּשִׁמְשָׁא, אִתְכְּלִיל סִיהֲרָא בְּגַוִּויהּ, הַשְׁתָּא דְּאַנְתְּ שִׁמְשָׁא, הֵיךְ יְקוּמוּן כַּחֲדָא שִׁמְשָׁא וְסִיהֲרָא, לָא נָהִיר סִיהֲרָא אֶלָּא בְּשַׁעֲתָא דְּאִתְכְּנִישׁ שִׁמְשָׁא, אֲבָל הַשְׁתָּא לֵית אַנְּתְּ יָכִיל. אִי תִּבְעֵי לְמִנְדַּע מִנָּהּ שְׁלַח לְךָ אֲנָשִׁים, לְגַרְמָךְ, בְּגִין לְמִנְדַּע.","תָּא חֲזֵי, מֹשֶׁה, אִי תֵּימָא דְּהוּא לָא יָדַע דְּלָא יֵיעוּל לְאַרְעָא בְּזִמְנָא דָּא. לָאו הָכִי, אֶלָּא יָדַע, וַהֲוָה בָּעֵי לְמִנְדַּע מִנָּהּ, עַד לָא יִסְתָּלַק, וְשִׁלַּח לְאִלֵּין מְאַלְלֵי, כֵּיוָן דְּלָא אָתִיבוּ מִלָּה כַּדְּקָא יָאוּת, לָא שָׁלַח זִמְנָא אַחֲרָא, עַד דְקוּדְשָׁא בְּרִיךְ הוּא אַחְזֵי לֵיהּ, דִּכְתִּיב, (דברים ל״ב:מ״ט) עֲלֵה אֶל הַר הָעֲבָרִים הַזֶּה וּרְאֵה אֶת הָאָרֶץ. וּכְתִיב (דברים ל״ד:א׳) וַיַּרְאֵהוּ יְיָ אֶת כָּל הָאָרֶץ. וְלָא דָּא בִּלְחוֹדוֹי, אֶלָּא כָּל אִינּוּן דִּזְמִינִין לְמֵיקָם בְּכָל דָּרָא וְדָרָא, כֻּלְּהוּ אַחְזֵי לֵיהּ לְמֹשֶׁה. וְאִתְּמַר, וְאוֹקְמוּהָ חַבְרַיָּיא.","כֵּיוָן דְּשָׁארִי מֹשֶׁה לְמִשְׁלַח, מַה אָמַר לוֹן. הֲיֵשׁ בָּהּ עֵץ. וְכִי מַה הוּא דְּקָאָמַר, וְאִי תֵּימָא דְּלָא יָדַע. (לקמן יימא מלה אבל הכא) אֶלָּא הָכִי אָמַר מֹשֶׁה, אִם יֵשׁ בָּהּ עֵץ, הָא יְדַעְנָא דַּאֲנָא אִיעוּל לְתַמָן. מַאי עֵץ. דָּא אִילָנָא דְּחַיֵּי. וְתַמָּן לָא הֲוָה אֶלָּא בְּגַּן עֵדֶן דְּאַרְעָא. אָמַר אִם יֵשׁ בָּהּ עֵץ דָּא, אֲנָא אִיעוּל לְתַמָן. וְאִי לָא, לָאו אֲנָא יָכִיל לְמֵיעַל.","אָמַר רִבִּי חִיָיא, כְּתִיב (במדבר ט״ו:ל״ב) וַיִּמְצְאוּ אִישׁ מְקוֹשֵׁשׁ עֵצִים בְּיוֹם הַשַּׁבָּת. מַאן עֵצִים הָכָא. וּמַאן הוּא דָּא. אֶלָּא דָּא צְלָפְחָד, וַהֲוָה דָּיִיק עַל אִלֵּין אִילָנִין, הֵי מִנַּיְיהוּ רַב עַל אַחֲרָא, וְלָא חָשַׁשׁ לִיקָרָא דְּמָארֵיהּ, וְאַחְלַף שַׁבָּת לְשַׁבָּת. הֲדָא הוּא דִכְתִיב, (במדבר כ״ז:ג׳) כִּי בְחֶטְאוֹ מֵת, בְּחֵטְא ו' מֵת. (ורזא דכלא ודאי מקושש עצים) בְּגִין כַּךְ, הֲוָה דִּינֵיהּ סָתִים, וְלָא אִתְפְּרַשׁ דִּינֵיהּ. כְּדִינִין אַחֲרָנִין. בְּגִין דְּמִלָּה דָּא בָּעֵי בַּחֲשַׁאי וְסָתִים וְלָא גַּלְיָיא. וְעַל דָּא לָא אִתְּמַר בְּאִתְגַּלְיָיא, וְקוּדְשָׁא בְּרִיךְ הוּא עֲבַד יְקָר לִיקָרֵיהּ.","רִבִּי יוֹסֵי אָמַר, שְׁאַר עֵצִים בַּהֲדֵי שַׁבָּת הֲוָה מְקוֹשֵׁשׁ, וְקַבִּיל עוֹנְשָׁא לְפוּם שַׁעֲתָא, וְאִתְכְּפַר חוֹבֵיהּ. וְעַל דָּא אִתְקָשֵּׁי מֹשֶׁה בְּדִינָא דִּבְנָתָא, דְּלָא יָדַע אִי אִתְכַּפָּר לְמֶהֱוִי לִבְנָתֵיהּ חוּלָק וְאַחֲסָנָא אִי לָאו. כֵּיוָן דְּדָכַר שְׁמֵיהּ (דצלפחד) קוּדְשָׁא בְּרִיךְ הוּא, דִּכְתִּיב כֵּן בְּנוֹת צְלָפְחָד דּוֹבְרוֹת, אִתְיְדַע דְּהָא אִתְכַּפָּר חוֹבֵיהּ.","תָּא חֲזֵי, ב' אִילָנִין אִינּוּן, חַד לְעֵילָּא, וְחַד לְתַתָּא, בְּדָא חַיִּין, וּבְדָא מוֹתָא. מַאן דְּאַחְלָף לוֹן, גָּרִים לֵיהּ מוֹתָא בְּהַאי עָלְמָא, וְלֵית לֵיהּ חוּלָקָא בְּהַהוּא עָלְמָא. וְעַל דָּא אָמַר שְׁלֹמֹה, (משלי כ״ה:ט״ז) דְּבַשׁ מָצָאתָ אֱכוֹל דַּיֶּךָּ וְגוֹ'.","אָרוֹן וְתוֹרָה בְּחַד קַיְימֵי. תּוֹרָה עִקָּרָא, אֲרוֹן בֵּיתָא. וְעַל דָּא, אָרֹן חָסֵר בְּלָא וָא\"ו בְּכָל אֲתָר, אֲרֹן הַבְּרִית, אֲרֹן הָעֵדוּת. בְּכָל אֲתָר אַהֲרֹן דְּרוֹעָא יְמִינָא, בַּר בְּחַד, דִּכְתִּיב (במדבר ג׳:ל״ט) כָּל פְּקּוּדֵי הַלְוִיִּם אֲשֶׁר פָּקַד מֹשֶׁה וְאַהֲרֹן, נָקוּד לְעֵילָּא.","אָמַר רִבִּי יִצְחָק, מֹשֶׁה אִילָנָא דְּחַיֵּי נָקַט, וְעַל דָּא בָּעָא לְמִנְדַּע, אִי הֲוָה שְׁכִיחַ בְּאַרְעָא, אִי לָאו, וּבְגִין כָּךְ אָמַר, הֲיֵשׁ בָּהּ עֵץ אִם אַיִן וְהִתְחַזַּקְתֶּם וּלְקַחְתֶּם מִפְּרִי הָאָרֶץ. דְּהָא אִילָנָא דְּחַיֵּי אִתְחֲמָד לְכֹלָּא. וְאִינּוּן לָא אַיְיתִיאוּ אֶלָּא עֲנָבִים וְרִמּוֹנִים וּתְאֵנִים, בְּאִילָנָא אַחֲרָא תַּלְיָין וַאֲחִידָן.","תָּא חֲזֵי, (במדבר י״ג:ב׳) שְׁלַח לְךָ אֲנָשִׁים: בְּגִינָךְ. רִבִּי יְהוּדָה פָּתַח, (משלי כ״ה:י״ג) כְּצִנַּת שֶׁלֶג בְּיוֹם קָצִיר צִיר נֶאֱמָן לְשׁוֹלְחָיו וְנֶפֶשׁ אֲדוֹנָיו יָשִׁיב. כְּצִנַּת שֶׁלֶג בְּיוֹם קָצִיר, דְּאַהֲנֵי לְגוּפָא וּלְנַפְשָׁא. צִיר נֶאֱמָן לְשׁוֹלְחָיו, אֵלּוּ כָּלֵב וּפִנְחָס דַּהֲווֹ שְׁלִיחֵי מְהֵימְנֵי לְגַבֵּי יְהוֹשֻׁעַ. וְנֶפֶשׁ אֲדוֹנָיו יָשִׁיב, דְּאָהַדְרוּ שְׁכִינְתָּא לְדַיְּירָא בְּהוּ בְּיִשְׂרָאֵל, וְלָא אִסְתָּלְקָא מִנַּיְיהוּ.","וְאִלֵּין דְּשָׁדַר מֹשֶׁה, גְּרִימוּ בְּכִיָיה לְדָרִין בַּתְרָאִין, וְגָרִימוּ לְאִסְתַּלְּקָא מִיִשְׂרָאֵל כַּמָּה אֶלֶף וְרִבְּבָן. וְגָרִימוּ לְסַלְּקָא שְׁכִינְתָּא מֵאַרְעָא מִבֵּינַיְיהוּ דְּיִשְׂרָאֵל. אִינּוּן דְּשָׁדַר יְהוֹשֻׁעַ, וְנֶפֶשׁ אֲדוֹנָיו יָשִׁיב.","רִבִּי חִזְקִיָּה וְרִבִּי יֵיסָא הֲווֹ אָזְלֵי בְּאָרְחָא, אָמַר רִבִּי יֵיסָא לְרִבִּי חִזְקִיָּה. חֲמֵינָא בְּאַפָּךְ דְּהִרְהוּרָא אִית בְּגַוָּוךְ. אָמַר לֵיהּ, הָא וַדַּאי הַאי קְרָא אִסְתַּכַּלְנָא בֵּיהּ, כֵּיוָן דְּאָמַר שְׁלֹמֹה, (קהלת ג׳:י״ט) כִּי מִקְּרֶה בְנֵי הָאָדָם וּמִקְרֶה הַבְּהֵמָה וּמִקְּרֶה אֶחָד לָהֶם וְגוֹ'. וְתָנֵינָן, דְּכָל מִלּוֹי דִּשְׁלֹמֹה מַלְכָּא, כֻּלְּהוּ סְתִימִין מִדַּרְגִּין דְּחָכְמְתָא. אִי הָכִי, הַאי קְרָא אִית בֵּיהּ לְאִסְתַּכְּלָא, דְּהָא פִּתְחָא לְאִינּוּן דְּלָאו בְּנֵי מְהֵימְנוּתָא אִשְׁתְּכַח בֵּיהּ."],[[0,"ת״ח משה הוה וכו׳:","בוא וראה, משה היה בחינת השמש, שהוא ז״א, ורצה להכנס לארץ. אמר לו הקב״ה, משה, כשבא אור השמש, הרי נכללה הלבנה, שהיא מלכות, בתוכו, ובחינתה אינה נראה. עתה שאתה הוא השמש, ותכנס לארץ שה״ס הלבנה, דהיינו המלכות, איך יעמדו יחד השמש והלבנה, הרי הלבנה אינה מאירה אלא בשעה שנאסף השמש. אבל עתה אינך יכול להכנס לארץ. ואם תרצה לדעת ממנה, שלח לך אנשים, \u0003לך,\u0004 היינו לעצמך, כדי שתדע."],[1,"ת״ח משה אי וכו׳:","בוא וראה, משה, אם תאמר שהוא לא היה יודע, שלא יכנס לארץ, בעת הזאת. אינו כן, אלא ידע, והיה רוצה לדעת ממנה בטרם שיסתלק, ושלח אלו המרגלים. כיון שלא השיבו לו דבר כראוי, לא שלח עוד בזמן אחר, עד שהקב״ה הראה אותה לו. שכתוב, עלה אל הר העברים הזה וראה את הארץ. וכתוב, ויראהו ה׳ את כל הארץ. ולא זה בלבד הראה לו, אלא כל אלו המנהיגים העתידים לקום בכל דור ודור, הראה אותם כולם למשה. ולמדנו. וכבר העמידוהו החברים."],[2,"כיון דשארי משה וכו׳:","כיון שהתחיל משה לשלוח. מה אמר להם. היש בה עץ. וכי מה הוא שאמר זה, וכי תאמר שלא ידע אם יש בה עץ. אלא כך אמר משה, אם יש בה עץ אני יודע שאכנס שמה. מהו עץ. זהו עץ החיים. והוא לא היה שם אלא בגן עדן הארץ. אמר משה, אם יש בה עץ הזה, אני אכנס שמה, ואם לא, איני יכול לכנס."],[3,"אמר ר׳ חייא וכו׳:","אר״ח, כתוב וימצאו איש מקושש עצים ביום השבת. מה הם העצים שבכאן ומי הוא זה האיש. ומשיב, אלא זה צלפחד, שהיה מדייק לדעת באלו האילנות, שהם ז״א ומלכות, איזה מהם גדול מן האחר, ולא חשש לכבוד אדונו והחליף בין שבת לשבת. הה״ד כי בחטא \u0003ו\u0004 מת, שפירושו בחטא \u0003ו׳\u0004 שהוא פגם בז״א שנקרא \u0003ו׳\u0004 דהויה, הוא מת. ומשום זה היה דינו סתום ולא נתפרש דינו, כדינים אחרים. כי כתוב מקושש עצים סתם. משום שדבר זה צריך להיות בחשאי, וצריך להיות סתום ולא גלוי. וע״כ לא נאמר בגלוי, והקב״ה עשה כבוד לכבודו."],[3,"","פירוש. כי יש בנוקבא ב׳ מצבים, מצב א׳ כשהוא גדולה כמו ז״א, כלומר ששניהם במדרגה אחת, שז״א מלביש קו ימין דבינה והנוקבא מלבשת קו שמאל דבינה, ואז אינה בזווג עם ז״א, כי מקבלת הכל מבינה, ואינה צריכה לז״א. ומצב ב', אחר המיעוט, שחזרה לבחינת נקודה תחת היסוד דז״א, ונבנית משם לפרצוף שלם פב״פ עם ז״א, אמנם נחשבת כבר למדרגה תחתונה מז\"א, ששורשה בנקודת החזה דז״א (כמ\"ש ב״א מאות ק״י עד אות קט״ו ע״ש). ובמצב א׳ הנוקבא בפרודא מז״א והיא באחורים ומלאה דינים. ובמצב הב׳ היא מלאה בכל השלמות. וביום השבת היא בזווג עם ז״א פנים בפנים ומלבישים לאו״א עלאין. והחטא של צלפחד היה, שביום השבת שז״א ונוקבא הם בתכלית קומתם פנים בפנים היה הוא מקושש עצים, \u0003עצים,\u0004 פירושו ב׳ העצים, שהם \u0003עץ\u0004 החיים שהוא ז״א, \u0003ועץ\u0004 הדעת שהוא הנוקבא. \u0003מקושש,\u0004 פירושו שהיה \u0003מקיש\u0004 ומשוה העצים. שהם ז\"א ונוקבא שיהיו שוים זה לזה, כמו שהיתה הנוקבא במצב הא׳. ונמצא בזה שהפריד הנוקבא מזווג פב״פ עם ז״א שביום השבת, והחזירה לפירוד ואחורים כמו שהיתה במצב הא'. ולא עוד אלא שהחשיב מצב הא׳ של הנוקבא על בחינת הזווג דפנים בפנים שביום השבת, כי דחה זווג הזה דפב״פ, והחזיר הנוקבא לפירוד ואחורים, ובזה עשה פגם גדול במדרגת ז״א, ובכל מדרגת השבת, כי החשיב האחורים דנוקבא יותר מפב״פ של ז״א. וז״ש, \u0003והוה דייק על אלין אילנין הי מנייהו רב על אחרא,\u0004 שהיה רוצה להחזיר הנוקבא למצב הא', והתבונן לדעת אם מצב הא' והפרודא של הנוקבא אינה חשובה יותר מפב״פ של ז״א. \u0003ולא חשש ליקרא דמאריה,\u0004 ולא איכפת לו שמבזה בזה כבוד ז״א, \u0003ואחלף שבת לשבת,\u0004 כלומר שהחליף חשיבות הגדול של זווג פב״פ ביום השבת, על בחינת שבת של חול (ועי' פרשת קרח אות נ״ו) שהיא הג״ר דאחורים של הנוקבא שבמצב הא׳, שה״ס עצה״ד טוב ורע."],[3,"","וז״ש \u0003בגין כך הוה דיניה סתים\u0004 וכו' \u0003בגין דמלה דא בעי בחשאי\u0004 וכו׳: כי ענין חטא הזה שהיה מחשיב מדרגת הנוקבא על ז\"א, אינו לכבוד לנוקבא, \u0003וקב\"ה עבד יקר ליקריה,\u0004 שז״א עשה כבוד לכבודו. דהיינו שעשה כבוד למלכות הנקרא \u0003כבוד,\u0004 שלא לגלות ההקפדה והחטא על מי שמחשיב הנוקבא ביותר. שזה אינו לכבוד הנוקבא. וסוד החטא הזה מרומז בשמו שנקרא \u0003צלפחד,\u0004 שהוא אותיות \u0003צל פחד.\u0004 כי מאחר שז״א ממעט הג״ר דשמאל ומשאיר רק הו״ק דג״ר (כנ״ל ב״א דף ס׳ ד״ה מחלוקת) נבחן שעושה צל על הג״ר דשמאל. אמנם על צל הזה נאמר, שהנוקבא אמרה, \u0003בצלו חמדתי וישבתי,\u0004 כי מקודם לכן במצב הא׳, אע״פ שלא היה לה אז צל על הג״ר, עכ״ז היתה סתומה ולא עשתה פירות. אבל עתה כשקבלה הצל מז״א, \u0003ופריו מתוק לחכי,\u0004 כי עתה יש לה פירות ממנו. אמנם צלפחד, \u0003פחד\u0004 מן ה \u0003צל\u0004 הזה, והיה רוצה לבחור מצב הא', שאז לא היה שום צל על הנוקבא. ובשביל זה מת."],[4,"רבי יוסי אמר וכו׳:","רי״א, שאר עצים, שהם ע׳ שרים החיצונים, עם שבת היה מקושש שהיה מקיש ומשוה מעלת ע׳ שרים למעלת יום השבת, וקבל עונשו בשעתו, ונתכפר עונו. וע״כ נתקשה משה בדין בנותיו, שלא היה יודע אם נתכפר עונו, ויהיה לבנותיו חלק ונחלה בארץ, או לא. כיון שהקב״ה הזכיר שמו, שכתוב, כן בנות \u0003צלפחד\u0004 דוברות. נודע שנתכפר עונו."],[5,"ת״ח כ׳ אילנין וכו׳:","בוא וראה, ב׳ עצים הם, אחד למעלה, שהוא עץ החיים, ז״א. ואחד למטה, שהוא עץ הדעת, הנוקבא. בזה חיים, ובזה מות. מי שמחליף אותם, דהיינו שמחשיב הנוקבא כשהיא בפרודא, יותר מז״א, שהוא עץ החיים, גורם לעצמו מות בעולם הזה, ואין לו חלק לעולם הבא. וע״ז אמר שלמה, דבש מצאת אכול דייך וגו'."],[5,"","פירוש. אע״פ שמצב הא׳ של הנוקבא היא בחינת פרוד ואחורים (כנ״ל באות י״א) עכ\"ז לולא מצב הא׳ לא היתה הנוקבא יכולה לקבל חכמה בעת שהיא במצב הב׳, כי הכלים של מצב הא׳ נשארים בה במצב הב׳ שבהם היא מקבלת החכמה (כנ״ל ויקהל אות נ״ג ע״ש) ולפיכך אחר שאדם זכה לקבל ממצב הא׳ דנוקבא, מחויב להעלות מ״ן לצורך מצב הב׳ דנוקבא ואז יהיה לו כל השלמות חכמה וחסדים יחדיו. אבל אם אינו עושה כן אלא בוחר במצב הא׳ דפרודא. עונשו מיתה. וז\"ש, \u0003דבש מצאת,\u0004 שה״ס מצב הא׳ דנוקבא, \u0003אכול דייך.\u0004 ואח״כ תמשיך את מצב הב', שאל״כ, \u0003פן תשבענו והקאתו.\u0004 דהיינו שיסתלקו ממנו אורות החיים."],[6,"ארון ותורה בחד וכו׳:","ארון ותורה. שהם מלכות הנקראת ארון וז\"א הנקרא תורה, נמצאים באחד, דהיינו בזווג. התורה שבארון היא העיקר, והארון הוא בית לתורה. וע״כ ארן בכל מקום חסר \u0003ו׳,\u0004 דהיינו ארן הברית ארן העדות, כי התורה שבתוך הארון ה״ס \u0003ו'.\u0004 בכל מקום, אהרן, הוא זרוע ימין, חוץ מאחד, שכתוב כל פקודי הלוים אשר פקד משה ואהרן, שהוא מנוקד למעלה. להורות שאינו כאן זרוע ימין שהוא חסד. אלא הוא בחינת מלכות שנקראת ארן, כנ״ל."],[7,"אמר ר׳ יצחק וכו׳:","משה היה אחוז בעץ החיים, וע״כ רצה לדעת אם הוא נמצא בארץ או לא. ומשום זה אמר היש בה עץ אם אין והתחזקתם ולקחתם מפרי הארץ. כי עץ החיים נחמד לכל. והם לא הביאו אלא ענבים ורמונים ותאנים שהם תלוים ואחוזים בעץ האחר, דהיינו בנוקבא. ולא בז״א שהוא עץ החיים."],[8,"ת״ח, שלח לך:","בוא וראה שלח לך אנשים. לך, פירושו בשבילך. ר׳ יהודה פתח, כצנת שלג ביום קציר ציר נאמן לשולחיו ונפש אדוניו ישיב. \u0003כצנת שלג ביום קציר.\u0004 שאז הצנה מועילה לגוף ונפש. \u0003ציר נאמן לשולחיו,\u0004 אלו הם כלב ופנחס, שהיו שליחים נאמנים אל יהושע. בעת ששלחם לרגל את ירחו. \u0003ונפש אדוניו ישיב,\u0004 שהחזירו השכינה שתשכון בישראל, ולא נסתלקה מהם."],[9,"ואלין דשדר משה וכו׳:","ואלו המרגלים ששלח משה, גרמו בכיה לדורות האחרונים כי ביום הזה נחרבו בית המקדש הראשון והשני, וגרמו להסתלק מישראל כמה אלפים ורבבות, וגרמו לסלק השכינה מן הארץ מבין ישראל. אלו ששלח יהושע, נאמר בהם ונפש אדוניו ישיב."],[10,"ר׳ חזקיה ור׳ ייסא וכו׳:","ר׳״ח ור״י היו הולכים בדרך, אמר ר׳ ייסא לר׳ חזקיה אני רואה בפניך שיש בך הרהור. אמר ליה הרי ודאי. מקרא זה הסתכלתי בו, כיון שאמר שלמה כי מקרה בני האדם ומקרה הבהמה ומקרה אחד להם וגו׳. ולמדנו, שכל דבריו של שלמה המלך כולם סתומים ממדרגות החכמה. א״כ, מקרא זה יש להסתכל בו, כי נמצא כאן פתח לאלו שאינם בני אמונה."]],[[0,"","בֹּא וּרְאֵה, מֹשֶׁה הָיָה הַשֶּׁמֶשׁ, וְרָצָה לְהִכָּנֵס לָאָרֶץ. אָמַר לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא, מֹשֶׁה, כְּשֶׁבָּא אוֹר הַשֶּׁמֶשׁ, נִכְלֶלֶת הַלְּבָנָה בְתוֹכוֹ. כָּעֵת שֶׁאַתָּה שֶׁמֶשׁ, אֵיךְ יָקוּמוּ כְאֶחָד שֶׁמֶשׁ וּלְבָנָה? הַלְּבָנָה אֵינָהּ מְאִירָה אֶלָּא בְּשָׁעָה שֶׁמִּתְכַּנֶּסֶת הַשֶּׁמֶשׁ, אֲבָל כָּעֵת אֵינְךְ יָכוֹל. אִם תִּרְצֶה לָדַעַת מִמֶּנָּה, שְׁלַח לְךְ אֲנָשִׁים, לְעַצְמְךְ, כְּדֵי לָדַעַת."],[1,"","בֹּא וּרְאֵה, מֹשֶׁה, אִם תֹּאמַר שֶׁהוּא לֹא יָדַע שֶׁלֹּא יִכָּנֵס לָאָרֶץ בִּזְמַן זֶה - לֹא כָּךְ, אֶלָּא יָדַע, וְרָצָה לָדַעַת מִמֶּנָּה עַד שֶׁלֹּא יִסְתַּלֵּק, וְשָׁלַח אֶת הַמְרַגְּלִים הַלָּלוּ. כֵּיוָן שֶׁלֹּא הֵשִׁיבוּ דָבָר כָּרָאוּי, לֹא שָׁלַח פַּעַם אַחֶרֶת, עַד שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא הֶרְאָה לוֹ, שֶׁכָּתוּב (דברים לב) עֲלֵה אֶל הַר הָעֲבָרִים הַזֶּה וּרְאֵה אֶת הָאָרֶץ. וְכָתוּב (שם לד) וַיַּרְאֵהוּ ה' אֶת כָּל הָאָרֶץ. וְלֹא זֶה בִּלְבַדּוֹ, אֶלָּא כָּל אֵלּוּ שֶׁעֲתִידִים לַעֲמֹד בְּכָל דּוֹר וָדוֹר, כֻּלָּם הֶרְאָה לְמֹשֶׁה. וְנִתְבָּאֵר, וּפֵרְשׁוּהָ הַחֲבֵרִים."],[2,"","כֵּיוָן שֶׁהֻתַּר מֹשֶׁה לִשְׁלֹחַ, מָה אָמַר לָהֶם? הֲיֶשׁ בָּהּ עֵץ. וְכִי מַהוּ שֶׁאָמַר? וְאִם תֹּאמַר שֶׁלֹּא יָדַע? אֶלָּא (לפנינויאמר דבר, אבלכאן) כָּךְ אָמַר מֹשֶׁה: אִם יֵשׁ בָּהּ עֵץ, הֲרֵי יָדַעְתִּי שֶׁאֲנִי אֶכָּנֵס לְשָׁם. אֵיזֶה עֵץ? זֶה עֵץ הַחַיִּים. וְשָׁם לֹא הָיָה, אֶלָּא בְּגַן עֵדֶן שֶׁבָּאָרֶץ. אָמַר, אִם יֵשׁ בָּהּ עֵץ זֶה, אֲנִי אֶכָּנֵס לְשָׁם. וְאִם לֹא, לֹא אוּכַל אֲנִי לְהִכָּנֵס."],[3,"","אָמַר רַבִּי חִיָּיא, כָּתוּב (במדבר טו) וַיִּמְצְאוּ אִישׁ מְקוֹשֵׁשׁ עֵצִים בְּיוֹם הַשַּׁבָּת. אֵיזֶה עֵצִים כָּאן? וּמַה הוּא זֶה? אֶלָּא זֶה צְלָפְחָד, וְהָיָה מְדַקְדֵּק עַל הָעֵצִים הַלָּלוּ אֵיזֶה גָדוֹל מֵהָאַחֵר, וְלֹא חָשַׁשׁ לִכְבוֹד רִבּוֹנוֹ, וְהֶחֱלִיף שַׁבָּת לְשַׁבָּת. זֶהוּ שֶׁכָּתוּב (שם כז) כִּי בְחֶטְאוֹ מֵת, בְּחֵטְא ו' מֵת. (וסוד הכל ודאי מקושש עצים) בִּגְלַל זֶה הָיָה דִינוֹ סָתוּם, וְלֹא הִתְפָּרֵשׁ דִּינוֹ כְּדִינִים אֲחֵרִים, מִשּׁוּם שֶׁדָּבָר זֶה צָרִיךְ בַּחֲשַׁאי וְנִסְתָּר וְלֹא גָלוּי, וְעַל זֶה לֹא נֶאֱמַר בְּגָלוּי, וְהַקָּדוֹשׁ בָּרוּךְ הוּא עָשָׂה כָבוֹד לִכְבוֹדוֹ."],[4,"","רַבִּי יוֹסֵי אָמַר, שְׁאָר הָעֵצִים יַחַד עִם שַׁבָּת הָיָה מְקוֹשֵׁשׁ, וְקִבֵּל עֹנֶשׁ לְפִי שָׁעָה וְהִתְכַּפֵּר חֶטְאוֹ. וְעַל זֶה הִתְקַשָּׁה מֹשֶׁה בְּדִין הַבָּנוֹת, שֶׁלֹּא יָדַע אִם הִתְכַּפֵּר לִהְיוֹת לִבְנוֹתָיו חֵלֶק וְנַחֲלָה אִם לֹא. כֵּיוָן שֶׁהִזְכִּיר שְׁמוֹ (של צלפחד) הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁכָּתוּב (שם) כֵּן בְּנוֹת צְלָפְחָד דּבְרֹת, נוֹדַע שֶׁהִתְכַּפֵּר חֶטְאוֹ."],[5,"","בֹּא וּרְאֵה, שְׁנֵי עֵצִים הֵם, אֶחָד לְמַעְלָה וְאֶחָד לְמַטָּה, בָּזֶה חַיִּים וּבָזֶה מָוֶת. מִי שֶׁמַּחֲלִיפָם, גּוֹרֵם לוֹ מָוֶת בָּעוֹלָם הַזֶּה, וְאֵין לוֹ חֵלֶק לָעוֹלָם הַבָּא. וְעַל זֶה אָמַר שְׁלֹמֹה, (משלי כה) דְּבַשׁ מָצָאתָ אֱכֹל דַּיֶּךָּ וְגוֹ'."],[6,"","אָרוֹן וְתוֹרָה בְּאֶחָד עוֹמְדִים. תּוֹרָה הָעִקָּר. הָאָרוֹן הַבַּיִת. וְעַל זֶה אָרֹן חָסֵר בְּלִי וָא\"ו בְּכָל מָקוֹם; אֲרֹן הַבְּרִית, אֲרֹן הָעֵדֻת. בְּכָל מָקוֹם אַהֲרֹן זְרוֹעַ יָמִין, פְּרָט לְאֶחָד, שֶׁכָּתוּב (במדבר ג) כָּל פְּקוּדֵי הַלְוִיִּם אֲשֶׁר פָּקַד מֹשֶׁה וְאַהֲרֹן, נָקוּד לְמַעְלָה."],[7,"","אָמַר רַבִּי יִצְחָק, מֹשֶׁה נָקַט עֵץ הַחַיִּים, וְלָכֵן רָצָה לָדַעַת אִם הָיָה מָצוּי בָּאָרֶץ אִם לֹא, וּמִשּׁוּם זֶה אָמַר הֲיֶשׁ בָּהּ עֵץ אִם אַיִן וְהִתְחַזַּקְתֶּם וּלְקַחְתֶּם מִפְּרִי הָאָרֶץ. שֶׁהֲרֵי עֵץ הַחַיִּים נֶחְמָד לַכֹּל. וְהֵם לֹא הֵבִיאוּ אֶלָּא עֲנָבִים וְרִמּוֹנִים וּתְאֵנִים, בְּאִילָן אַחֵר תְּלוּיִים וַאֲחוּזִים."],[8,"","בֹּא וּרְאֵה, שְׁלַח לְךְ אֲנָשִׁים, בִּשְׁבִילְךְ. רַבִּי יְהוּדָה פָּתַח, (משלי כה) כְּצִנַּת שֶׁלֶג בְּיוֹם קָצִיר צִיר נֶאֱמָן לְשֹׁלְחָיו וְנֶפֶשׁ אֲדנָיו יָשִׁיב. כְּצִנַּת שֶׁלֶג בְּיוֹם קָצִיר, שֶׁמְּהַנֶּה אֶת הַגּוּף וְאֶת הַנֶּפֶשׁ. צִיר נֶאֱמָן לְֹשלְחָיו, אֵלּוּ כָּלֵב וּפִנְחָס שֶׁהָיוּ שְׁלִיחִים נֶאֱמָנִים לִיהוֹשֻׁעַ. וְנֶפֶשׁ אֲדנָיו יָשִׁיב, שֶׁהֶחֱזִירוּ שְׁכִינָה לָדוּר בָּהֶם בְּיִשְׂרָאֵל, וְלֹא הִסְתַּלְּקָה מֵהֶם."],[9,"","וְאֵלּו שֶׁשָּׁלַח מֹשֶׁה גָּרְמוּ בְכִיָּה לְדוֹרוֹת אַחֲרוֹנִים, וְגָרְמוּ לְהִסְתַּלֵּק מִיִּשְׂרָאֵל כַּמָּה אֲלָפִים וּרְבָבוֹת, וְגָרְמוּ לְסַלֵּק שְׁכִינָה מֵהָאָרֶץ מִבֵּין יִשְׂרָאֵל. אוֹתָם שֶׁשָּׁלַח יְהוֹשֻׁעַ, וְנֶפֶשׁ אֲדנָיו יָשִׁיב."],[10,"","רַבִּי חִזְקִיָּה וְרַבִּי יֵיסָא הָיוּ הוֹלְכִים בַּדֶּרֶךְ. אָמַר רַבִּי יֵיסָא לְרַבִּי חִזְקִיָּה, אֲנִי רוֹאֶה בְפָנֶיךְ שֶׁבְּתוֹכְךְ יֵשׁ הִרְהוּר. אָמַר לוֹ, הֲרֵי וַדַּאי בְּפָסוּק זֶה הִסְתַּכַּלְתִּי בוֹ. כֵּיוָן שֶׁאָמַר שְׁלֹמֹה, (קהלת ג) כִּי מִקְרֶה בְנֵי הָאָדָם וּמִקְרֶה הַבְּהֵמָה מִקְרֶה אֶחָד לָהֶם וְגוֹ'. וְשָׁנִינוּ, שֶׁכָּל דִּבְרֵי שְׁלֹמֹה הַמֶּלֶךְ כֻּלָּם נִסְתָּרִים מִדַּרְגוֹת הַחָכְמָה. אִם כָּךְ, בְּפָסוּק זֶה יֵשׁ לְהִסְתַּכֵּל, שֶׁהֲרֵי נִמְצָא בּוֹ פֶּתַח לְאוֹתָם שֶׁאֵינָם בְּנֵי הָאֱמוּנָה."]]],[["אָמַר לֵיהּ וַדַּאי הָכִי הוּא, וְאִית בֵּיהּ לְמִנְדַּע וּלְאִסְתַּכְּלָא. אַדְּהָכִי חָמוּ חַד בַּר נָשׁ דְּהֲוָה אָתֵי, שָׁאַל לוֹן מַיָּיא, דְּהֲוָה צָחֵי, וַהֲוָה לָאֵי בְּתוּקְפָּא דְּשִׁמְשָׁא. אָמְרוּ לֵיהּ, מַאן אַתְּ. אָמַר לוֹן יוּדָאי אֲנָא, וַאֲנָא לָאֵי וְצָחֵינָא. אָמְרוּ לָעִית בְּאוֹרַיְיתָא, אָמַר לוֹן, עַד דַּאֲנָא עִמְּכוֹן בְּמִלִּין, אֶסְלַּק לְהַאי טוּרָא, וְתַמָּן אֶסַּב מַיָּיא וְאִשְׁתֵּי.","אַפִּיק רִבִּי יֵיסָא חַד זְפִירָא מָלֵי מַיִין, וִיהַב לֵיהּ. בָּתַר דְּשָׁתָה, אָמַר נְסַלֵּק עִמָּךְ לְמַיָּיא. סְלִיקוּ לְטוּרָא, וְאִשְׁתְּכָחוּ חַד חוּטָא דְּמַיָיא דָּקִיק, וּמַלֵּי קַטְפוּרָא חַד. יָתְבוּ. אָמַר לוֹן הַהוּא בַּר נָשׁ, הַשְׁתָּא שָׁאִילוּ, דְּהָא אֲנָא אִשְׁתָּדַּלְּנָא בְּאוֹרַיְיתָא, עַל יְדוֹי דְּחַד בְּרִי, דַּאֲנָא עַיְילִית לֵיהּ לְבֵי רַב, וּבְגִינֵיהּ רָוַוחְנָא בְּאוֹרַיְיתָא. אָמַר רִבִּי חִזְקִיָּה אִי עַל יְדָא דִּבְרָךְ, טַב הוּא. אֲבָל מִלָּה דַּאֲנָן בֵּיהּ, אֲנָא חֲמֵינָא דְּלַאֲתָר אַחֲרָא בָּעֵי לְאִסְתַּלְּקָא. אָמַר הַהוּא בַּר נָשׁ, אֵימָא מִלָּךְ, דִּלְזִמְנִין בְּאָפַּרְקָסָתָא דְּעַנְיָיא תִּשְׁכַּח מַרְגָּנִיתָא.","אָמַר לֵיהּ הַאי קְרָא דְּאָמַר שְׁלֹמֹה, סַח לֵיהּ. אָמַר לֵיהּ, וְכִי (נ\"א כמה) בְּמָה אַתּוּן פְּרִישָׁן מִשְּׁאַר בְּנֵי נָשָׁא דְּלָא יַדְעֵי. אָמְרוּ לֵיהּ וּבְמָּה. אָמַר לוֹן, עַל דָּא אָמַר שְׁלֹמֹה הַאי קְרָא, וְלָא אָמַר הַאי מִגַּרְמֵיהּ, כִּשְׁאַר אִינּוּן מִלִּין. אֶלָּא אַהְדָּר אִינּוּן מִלִּין דְּטִפְּשָׁאֵי עָלְמָא דְּאַמְרֵי כַּךְ, וּמַאי אַמְרֵי. כִּי מִקְרֶה הָאָדָם וּמִקְּרֶה הַבְּהֵמָה וְגוֹ', טִפְּשָׁאֵי דְּלָא יַדְעֵי וְלָא מִסְתַּכְּלָן בְּחָכְמְתָא אַמְרֵי דְּהַאי עָלְמָא אָזִיל בְּמִקְרֶה, וְקוּדְשָׁא בְּרִיךְ הוּא לָא אַשְׁגַּח עָלַיְיהוּ, אֶלָּא מִקְרֶה הָאָדָם וּמִקְרֶה הַבְּהֵמָה וּמִקְרֶה אֶחָד וְגוֹ'.","וְכַד שְׁלֹמֹה אִסְתָּכַּל בְּאִלֵּין טִפְּשָׁאִין דְּקָאַמְרֵי דָּא קָרָא לוֹן בְּהֵמָה, דְּאִינּוּן עַבְדִּין גַּרְמַיְיהוּ בְּהֵמָה מַמָּשׁ, בְּגִין דְּאַמְרֵי מִלִּין אִלֵּין. וּמְנָלָן. קְרָא דְּעָלֵיהּ אוֹכַח, דִּכְתִּיב, (קהלת ג׳:י״ח) אָמַרְתִּי אֲנִי בְּלִבִּי עַל דִּבְרַת בְּנֵי הָאָדָם לְבָרָם הָאֱלֹהִים וְלִרְאוֹת שְׁהֶם בְּהֵמָה הֵמָּה לָהֶם. אָמַרְתִּי אֲנִי בְּלִבִּי וַחֲשִׁיבְנָא בְּהַאי לְאִסְתַּכְּלָא עַל מָה, עַל דִּבְרַת בְּנֵי הָאָדָם. עַל הַהוּא מִלָּה דְּטִפְּשׁוּתָא, דְּאִינּוּן אַמְרֵי לְבָרָם הָאֱלֹהִים בִּלְחוֹדַיְיהוּ, וְלָא יִתְחַבְּרוּן בַּהֲדֵי בְּנֵי נָשָׁא אַחֲרָנִין דְּאִית לוֹן מְהֵימְנוּתָא, וְלִרְאוֹת שְׁהֶם בְּהֵמָה הֵמָּה לָהֶם. וְלִרְאוֹת בְּהוּ אִינּוּן בְּנֵי מְהֵימְנוּתָא, שֶׁהֵם בְּהֵמָה מַמָּשׁ, וְדַעְתַּיְיהוּ כִּבְעִירָא. הֵמָּה לָהֶם בִּלְחוֹדַיְיהוּ, וְלָא לְאַעֲלָאה לִבְנֵי מְהֵימְנוּתָא בְּדַעְתָּא דְּטִפְּשׁוּתָא דָּא, וְעַל דָּא הֵמָּה לָהֶם, וְלָא לְאַחֲרָנִין. וּמַה דַּעְתָּא דִּלְהוֹן. כִּי מִקְּרֶה בְנֵי הָאָדָם וּמִקְרֶה הַבְּהֵמָה וּמִקְּרֶה אֶחָד לְכֻלָּם וְגוֹ'. תִּיפַּח רוּחֵיהוֹן דְּאִינּוּן בְּעִירֵי. אִינּוּן טִפְּשָׁאֵי. אִינּוּן מְחוּסְרֵי מְהֵימְנוּתָא. וַוי לוֹן וַוי לְנַפְשַׁיְיהוּ. טַב לְהוּ דְּלָא יֵיתוּן לְעָלְמָא.","וּמַה אָתִיב לוֹן שְׁלֹמֹה עַל דָּא. קְרָא אֲבַּתְרֵיהּ, וְאָמַר, וּמִי יוֹדֵעַ רוּחַ בְּנֵי הָאָדָם הָעוֹלָה הִיא לְמַעְלָה וְרוּחַ הַבְּהֵמָה הַיּוֹרֶדֶת הִיא לְמַטָּה לָאָרֶץ. מִי יוֹדֵעַ בְּאִינּוּן טִפְּשָׁאֵי, דְּלָא יַדְעֵי בִּיקָרָא דְּמַלְכָּא עִלָּאָה, וְלָא מִסְתַּכְּלֵי בְּאוֹרַיְיתָא, רוּחַ בְּנֵי הָאָדָם הָעוֹלָה, הִיא לְמַעְלָה, לַאֲתָר עִלָּאָה, לַאֲתָר יְקָר, לַאֲתָר קַדִּישָׁא, לְאִתְּזְנָא מִנְּהִירוּ עִלָּאָה, מִנְּהִירוּ דְּמַלְכָּא קַדִּישָׁא, לְמֶהֱוִי צְרוֹרָא בִּצְרוֹרָא דְּחַיֵּי, וְאִשְׁתְּכָחַת קַמֵּי מַלְכָּא קַדִּישָׁא עוֹלָה תְּמִימָה וְדָא הוּא הָעוֹלָה הִיא לְמַעְלָה.","וְרוּחַ הַבְּהֵמָה הַיּוֹרֶדֶת הִיא לְמַטָּה לָאָרֶץ, וְלַאו לְהַהוּא אֲתָר דְּהַוָה כָּל בַּר נָשׁ, דִּכְתִּיב בֵּיהּ (בראשית ט׳:ו׳) בְּצֶלֶם אֱלֹהִים עָשָׂה אֶת הָאָדָם, וּכְתִיב (משלי כ׳:כ״ז) נֵר יְיָ נִשְׁמַת אָדָם. הֵיךְ אַמְרֵי אִינּוּן טִפְּשָׁאֵי דְּלָאו מִבְּנֵי מְהֵימְנוּתָא, וְרוּחַ אֶחָד לַכֹּל, תִּיפַּח רוּחֵיהוֹן, עָלַיְיהוּ כְּתִיב, (תהילים ל״ה:ה׳) יִהְיוּ כְּמוֹץ לִפְנֵי רוּחַ וּמַלְאַךְ יְיָ דּוֹחֶה. אִלֵּין יִשְׁתַּאֲרוּן בַּגֵיהִנָּם, לְאִינּוּן דַּרְגִּין תַּתָּאִין, וְלָא יִסְתַּלְּקוּן לְדָרֵי דָּרִין. עָלַיְיהוּ כְּתִיב (תהילים ק״ד:ל״ה) יִתַּמּוּ חַטָּאִים מִן הָאָרֶץ וּרְשָׁעִים עוֹד אֵינָם בָּרַכִי נַפְשִׁי אֶת יְיָ הַלְלוּיָהּ. אָתוּ רִבִּי חִזְקִיָּה וְרִבִּי יֵיסָא, וְנַשְׁקוּ רֵישֵׁיהּ, אָמְרוּ וּמַה כָּל כַּךְ הֲוָה עִמָּךְ וְלָא יְדַעְנָא, זַכָּאָה הַאי שַׁעֲתָא דְּאַעְרַעְנָא בָּךְ."],[[0,"א״ל ודאי הכי וכו׳:","א״ל, ודאי כך הוא, שיש בזה פתח לבלתי מאמינים, ויש לדעת ולהסתכל בו. בתוך כך ראו אדם אחד שהיה בא, ובקש מהם מים, כי היה צמא, והיה עיף מתוקף השמש. אמרו לו מי אתה. אמר להם, יהודי אני ואני עיף וצמא. אמרו לו אתה עוסק בתורה. אמר להם, עד שאני עוסק עמכם בדיבורים, אעלה להר הזה, ושם אקח מים ואשתה."],[1,"אפיק ר׳ ייסא וכו׳:","הוציא ר״י נאד אחד מלא מים ונתן לו. אחר ששתה אמר נעלה עמך להר, למים. עלו להר ומצאו חוט אחד דק של מים ומילא כלי אחד. ישבו. אמר להם אותו האדם, עתה שאלו. כי אני משתדל בתורה על ידי בני אחד שהכנסתי אותו לבית רב, והוא למדני תורה. ובשבילו הרוחתי בתורה. אמר ר׳ חזקיה, אם זכית בתורה ע״י בנך יפה הוא, אבל הדבר שאנו עומדים בו, אני רואה שלמקום אחר אני צריך להעלותו, כלומר, שאין הוא מתאים לתרץ להם שאלתם. אמר אותו אדם, אמור דבריך כי לפעמים באפרכסת של עני, דהיינו כלי שעל הריחים, תמצא מרגליות. \u0003קטפורא,\u0004 פירושו כלי לפי הענין. \u0003זפירא,\u0004 פירושו נאד בלשון ערבי."],[2,"א״ל האי קרא וכו׳:","אמר לו, מקרא זה שאמר שלמה, ושח לו כל השאלה. אמר לו, וכי במה נשתניתם משאר בני אדם שאינם יודעים. אמרו לו, ובמה, אתה מעמיד המקרא. אמר להם, על זה אמר שלמה מקרא הזה, ולא אמר זה ממחשבתו עצמו כשאר הדברים שאמר, אלא שחזר על אלו הדברים שטפשי עולם אומרים. ומה אומרים, היינו, כי מקרה האדם ומקרה הבהמה וגו׳. הטפשים שאינם יודעים ואינם מסתכלים בחכמה, אומרים שהעולם הזה הולך במקרה, ואין הקב״ה משגיח עליהם, אלא מקרה האדם ומקרה הבהמה ומקרה אחד וגו׳."],[3,"וכד שלמה אסתכל וכו׳:","וכששלמה הסתכל בטפשים אלו, שאומרים זה, קרא אותם בהמה, שהם עושים את עצמם בהמה ממש, במה שאומרים דברים אלו. ומאין לנו זה, הפסוק שלפניו מוכיח, שכתוב, אמרתי אני בלבי על דברת בני האדם לברם האלקים ולראות שהם בהמה המה להם. \u0003אמרתי אני בלבי,\u0004 וחשבתי להסתכל. על מה. היינו \u0003על דברת בני האדם,\u0004 על הדבור ההוא של טפשות שהם אומרים, שהעולם מתנהג במקרה, \u0003לברם האלקים,\u0004 היינו, שברר אותם אלקים שיהיו לבדם, ולא יתחברו עם בני אדם אחרים שיש להם אמונה, \u0003ולראות שהם בהמה המה להם,\u0004 ולראות היינו שאלו בני האמונה יראו בהם שהם בהמה ממש, ודעתם כבהמות. \u0003המה להם,\u0004 היינו שהם בפני עצמם, שלא יביאו דעה טפשית הזו לבני האמונה, וע\"כ, \u0003המה להם,\u0004 ולא לאחרים. ומהו הדעה שלהם, על זה מסיים הכתוב, כי מקרה בני האדם ומקרה הבהמה ומקרה אחד לכולם וגו'. תיפח רוחם של אלו הבהמות, אלו הטפשים, אלו מחוסרי האמונה. אוי להם ואוי לנפשם, טוב להם, שלא היו באים לעולם."],[4,"ומה אתיב לון וכו׳:","ומה השיב להם שלמה, על זה בא המקרא שלאחריו ואמר, ומי יודע רוח בני האדם העולה היא למעלה ורוח הבהמה היורדת היא למטה לארץ. \u0003מי יודע,\u0004 את אלו הטפשים, שאינם יודעים כבוד המלך העליון, ואינם מסתכלים בתורה, \u0003רוח בני האדם העולה, היא למעלה,\u0004 היינו למקום עליון, למקום יקר, למקום קדוש, להזון מאור העליון, מאור המלך הקדוש, להיות צרור בצרור החיים, ולהיות נמצאת לפני המלך הקדוש עולה תמימה. וזה הוא \u0003העולה היא למעלה.\u0004"],[5,"ורוח הבהמה היורדת וגו׳:","ורוח בהמה היורדת היא למטה לארץ. ואינו לאותו מקום שהוא לכל בני האדם. שכתוב בו, בצלם אלקים עשה את האדם. וכתוב, נר ה׳ נשמת אדם. ואיך אומרים אלו הטפשים שאינם מבני האמונה, \u0003ורוח אחד לכל,\u0004 תפח רוחם, עליהם כתוב, יהיו כמוץ לפני רוח ומלאך ה׳ דוחה. אלו ישארו בגיהנם באלו מדרגות התחתונות, ולא יעלו משם לדורי דורות. עליהם כתוב, יתמו חטאים מן הארץ ורשעים עוד אינם ברכי נפשי את ה׳ הללויה. באו ר׳ חזקיה ור׳ ייסא ונשקו ראשו. אמרו, ומה כל כך היה עמך ולא ידענו. אשרי שעה זו שפגשנו בך."]],[[0,"","אָמַר לוֹ, וַדַּאי כָּךְ זֶה, וְיֵשׁ בּוֹ לָדַעַת וּלְהִסְתַּכֵּל. בֵּין כָּךְ רָאוּ אָדָם שֶׁהָיָה בָּא, וּבִקֵּשׁ מֵהֶם מַיִם, שֶׁהָיָה צָמֵא וְעָיֵף מֵחֹזֶק הַשֶּׁמֶשׁ. אָמְרוּ לוֹ, מִי אַתָּה? אָמַר לָהֶם? יְהוּדִי אֲנִי, וַאֲנִי עָיֵף וְצָמֵא. אָמְרוּ, עָסַקְתָּ בַּתּוֹרָה? אָמַרלָהֶם, עַד שֶׁאֲנִי אִתְּכֶם בִּדְבָרִים, אֶעֱלֶה לָהָר הַזֶּה, וְשָׁם אֶקַּח מַיִם וְאֶשְׁתֶּה."],[1,"","הוֹצִיא רַבִּי יֵיסָא כְּלִי אֶחָד מָלֵא מַיִם וְנָתַן לוֹ. אַחַר שֶׁשָּׁתָה, אָמַר, נַעֲלֶה אִתְּךְ לַמַּיִם. עָלָה לָהָר, וְנִמְצְאוּ חוּט מַיִם דַּקִּיק, וּמִלְּאוּ כְלִי אֶחָד. יָשְׁבוּ. אָמַר לָהֶם אוֹתוֹ הָאָדָם, כָּעֵת תִּשְׁאֲלוּ, שֶׁהֲרֵי אֲנִי הִשְׁתַּדַּלְתִּי בַתּוֹרָה עַל יְדֵי בְּנִי אֶחָד, שֶׁאֲנִי הִכְנַסְתִּיו לְבֵית רַב וּבִגְלָלוֹ הִרְוַחְתִּי בַתּוֹרָה. אָמַר רַבִּי חִזְקִיָּה, אִם עַל יְדֵי בִנְךְ - טוֹב הוּא. אֲבָל הַדָּבָר שֶׁאָנוּ בוֹ, אֲנִי רוֹאֶה שֶׁלְּמָקוֹם אַחֵר רוֹצֶה לַעֲלוֹת. אָמַר אוֹתוֹ הָאָדָם, אֱמֹר דְּבָרְךְ, שֶׁלִּפְעָמִים בְּתַרְמִיל הֶעָנִי תִּמְצָא מַרְגָּלִית."],[2,"","אָמַר לוֹ פָּסוּק זֶה שֶׁאָמַר שְׁלֹמֹה. סָח לוֹ. אָמַר לוֹ, וְכִי (כמו) בַּמָּה אַתֶּם נִפְרָדִים מִשְּׁאָר בְּנֵי אָדָם שֶׁלֹּא יוֹדְעִים? אָמְרוּ לוֹ, וּבַמֶּה? אָמַר לָהֶם, עַל זֶה אָמַר שְׁלֹמֹה פָּסוּק זֶה, וְלֹא אָמַר זֶה מֵעַצְמוֹ כִּשְׁאָר אוֹתָם דְּבָרִים, אֶלָּא חָזַר עַל אוֹתָם דְּבָרִים שֶׁל טִפְּשֵׁי הָעוֹלָם שֶׁאוֹמְרִים כָּךְ. וּמָה אוֹמְרִים? כִּי מִקְרֶה (בני) הָאָדָם וּמִקְרֶה הַבְּהֵמָה וְגוֹ'. טִפְּשִׁים שֶׁלֹּא יוֹדְעִים וְלֹא מִסְתַּכְּלִים בַּחָכְמָה, אוֹמְרִים שֶׁהָעוֹלָם הַזֶּה הוֹלֵךְ בְּמִקְרֶה, וְהַקָּדוֹשׁ בָּרוּךְ הוּא לֹא מַשְׁגִּיחַ עֲלֵיהֶם, אֶלָּא מִקְרֶה (בני) הָאָדָם וּמִקְרֶה הַבְּהֵמָה וּמִקְרֶה אֶחָד וְגוֹ'."],[3,"","וּכְשֶׁשְּׁלֹמֹה הִסְתַּכֵּל בַּטִּפְּשִׁים הַלָּלוּ שֶׁאוֹמְרִים אֶת זֶה, קָרָא לָהֶם בְּהֵמָה, שֶׁהֵם עוֹשִׂים עַצְמָם בְּהֵמָה מַמָּשׁ מִשּׁוּם שֶׁאוֹמְרִים דְּבָרִים אֵלּוּ. וּמִנַּיִן לָנוּ? הַפָּסוּק שֶׁעָלָיו מוֹכִיחַ, שֶׁכָּתוּב (קהלת ג) אָמַרְתִּי אֲנִי בְּלִבִּי עַל דִּבְרַת בְּנֵי הָאָדָם לְבָרָם הָאֱלֹהִים וְלִרְאוֹת שְׁהֶם בְּהֵמָה הֵמָּה לָהֶם. אָמַרְתִּי אֲנִי בְּלִבִּי, וְחָשַׁבְתִּי בָזֶה לְהִסְתַּכֵּל עַל מָה? עַל דִּבְרַת בְּנֵי הָאָדָם, עַל אוֹתוֹ דְּבַר טִפְּשׁוּת שֶׁהֵם אוֹמְרִים לְבָרָם הָאֱלֹהִים לְבַדָּם, וְלֹא יִתְחַבְּרוּ יַחַד עִם בְּנֵי אָדָם אֲחֵרִים שֶׁיֵּשׁ לָהֶם אֱמוּנָה, וְלִרְאוֹת שְׁהֶם בְּהֵמָה הֵמָּה לָהֶם. וְלִרְאוֹת בָּהֶם אוֹתָם בְּנֵי אֱמוּנָה שֶׁהֵם בְּהֵמָה מַמָּשׁ, וְדַעְתָּם כַּבְּהֵמָה. הֵמָּה לָהֶם - בִּלְבַדָּם, וְלֹא לְהַכְנִיס אֶת בְּנֵי הָאֱמוּנָה בְּדַעַת וְטִפְּשׁוּת זוֹ, וְעַל כָּךְ הֵמָּה לָהֶם, וְלֹא לַאֲחֵרִים. וּמַה דַּעְתָּם? כִּי מִקְרֶה בְנֵי הָאָדָם וּמִקְרֶה הַבְּהֵמָה וּמִקְרֶה אֶחָד לְכֻלָּם וְגוֹ'. תִּפַּח רוּחָם שֶׁל אוֹתָן בְּהֵמוֹת, אוֹתָם טִפְּשִׁים אוֹ מְחֻסְּרֵי אֱמוּנָה. אוֹי לָהֶם! אוֹי לְנַפְשָׁם! טוֹב לָהֶם שֶׁלֹּא יָבוֹאוּ לָעוֹלָם!"],[4,"","וּמַה הֱשִׁיבָם שְׁלֹמֹה עַל זֶה? הַפָּסוּק אַחֲרָיו, וְאָמַר, וּמִי יוֹדֵעַ רוּחַ בְּנֵי הָאָדָם הָעֹלָה הִיא לְמָעְלָה וְרוּחַ הַבְּהֵמָה הַיֹּרֶדֶת הִיא לְמַטָּה לָאָרֶץ. מִי יוֹדֵעַ בְּאוֹתָם טִפְּשִׁים שֶׁלֹּא יוֹדְעִים בִּכְבוֹד הַמֶּלֶךְ הָעֶלְיוֹן וְלֹא מִסְתַּכְּלִים בַּתּוֹרָה, רוּחַ בְּנֵי הָאָדָם הָעֹלָה הִיא לְמָעְלָה, לְמָקוֹם עֶלְיוֹן, לְמָקוֹם נִכְבָּד, לְמָקוֹם קָדוֹשׁ, לְהִזּוֹן מֵאוֹר עֶלְיוֹן, מֵאוֹר הַמֶּלֶךְ הַקָּדוֹשׁ, לִהְיוֹת צָרוּר בִּצְרוֹר הַחַיִּים, וְנִמְצָא לִפְנֵי הַמֶּלֶךְ הַקָּדוֹשׁ עוֹלָה תְמִימָה, וְזוֹהִי הָעֹלָה הִיא לְמָעְלָה."],[5,"","וְרוּחַ הַבְּהֵמָה הַיֹּרֶדֶת הִיא לְמַטָּה לָאָרֶץ, וְלֹא לְאוֹתוֹ מָקוֹם שֶׁהָיָה כָּל אָדָם, שֶׁכָּתוּב בּוֹ (בראשית ט) בְּצֶלֶם אֱלֹהִים עָשָׂה אֶת הָאָדָם, וְכָתוּב (משלי כ) נֵר ה' נִשְׁמַת אָדָם. אֵיךְ אוֹמְרִים אוֹתָם טִפְּשִׁים שֶׁאֵינָם מִבְּנֵי הָאֱמוּנָה, וְרוּחַ אֶחָד לַכֹּל (קהלת ג) ? תִּפַּח רוּחָם! עֲלֵיהֶם כָּתוּב (תהלים לה) יִהְיוּ כְּמֹץ לִפְנֵי רוּחַ וּמַלְאַךְ ה' דּוֹחֶה. אֵלֶּה יִשָּׁאֲרוּ בַגֵּיהִנֹּם לְאוֹתָן דְּרָגוֹת תַּחְתּוֹנוֹת, וְלֹא יַעֲלוּ לְדוֹרֵי דוֹרוֹת. עֲלֵיהֶם כָּתוּב (שם קד) יִתַּמּוּ חַטָּאִים מִן הָאָרֶץ וּרְשָׁעִים עוֹד אֵינָם בָּרְכִי נַפְשִׁי אֶת ה' הַלְלוּיָהּ. בָּאוּ רַבִּי חִזְקִיָּה וְרַבִּי יֵיסָא וְנָשְׁקוּ רֹאשׁוֹ. אָמְרוּ, וּמַה כָּל זֶה הָיָה אִתְּךְ וְלֹא יָדַעְנוּ? אַשְׁרֵי הַשָּׁעָה הַזּוֹ שֶׁפָּגַשְׁנוּ אוֹתְךְ."]]],[["תּוּ אָמַר, וְכִי עַל דָּא בִּלְחוֹדוֹי תָּוָּה שְׁלֹמֹה, וְהָא בַּאֲתָר אַחֲרָא אָמַר כְּגַוְונָא דָּא, פָּתַח וְאָמַר, (קהלת ט׳:ג׳) זֶה רָע בְּכֹל אֲשֶׁר נַעֲשָׂה תַּחַת הַשֶּׁמֶשׁ. זֶה רָע וַדַּאי. מַאי זֶה רָע. דָּא הוּא מַאן דְּאוֹשִׁיד זַרְעָא בְּרֵיקָנַיָּא, וְחָבִיל אוֹרְחוֹי, בְּגִין דְּהַאי לָאו מָדוֹרֵיהּ בְּקוּדְשָׁא בְּרִיךְ הוּא, וְלָא יְהֵא לֵיהּ חוּלָקָא בְּעָלְמָא דְּאָתֵי. הֲדָא הוּא דִכְתִיב, (תהילים ה׳:ה׳) כִּי לֹא אֵל חָפֵץ רֶשַׁע אָתָּה לֹא יְגוּרְךָ רָע. עַל דָּא אָמַר, זֶה רָע, דְּלָא יְהֵא לֵיהּ מָדוֹרָא לְעֵילָּא. כִּי מִקְרֶה אֶחָד לַכֹּל וְגַם לֵב בְּנֵי הָאָדָם מָלֵא רָע (בגין דא) וְהוֹלֵלוֹת בִּלְבָבָם. בְּחַיֵּיהֶם שְׁטּוּתָא תָּקִיעַ בְּלִבַּיְיהוּ, וְאִינּוּן מְחוּסְרֵי מְהֵימְנוּתָא, וְלֵית לוֹן חוּלָקָא בְּקוּדְשָׁא בְּרִיךְ הוּא, וּבְאִינּוּן בְּנֵי מְהֵימְנוּתָא, לָאו בְּעָלְמָא דֵּין, וְלָא בְּעָלְמָא דְּאָתֵי, הֲדָא הוּא דִכְתִיב, (קהלת ט׳:ג׳) וְאַחֲרָיו אֶל הַמֵּתִים.","תָּא חֲזֵי, קוּדְשָׁא בְּרִיךְ הוּא אַזְהַר לִבְנֵי עָלְמָא וְאָמַר, (דברים ל׳:י״ט) וּבָחַרְתָּ בַּחַיִּים לְמַעַן תִּחְיֶה, (בהאי עלמא, ובעלמא דאתי) וְחַיִּין דְּהַהוּא עָלְמָא נִינְהוּ. אִינּוּן חַיָּיבִין מְחוּסְרֵי מְהֵימְנוּתָא מַאי קָא אַמְרֵי. (קהלת ט) כִּי מִי אֲשֶׁר יִבְחַר וְגוֹ'. אַף עַל גַּב דְּיִבְחַר בַּר נָשׁ בְּהַאי עָלְמָא (ס\"א בההוא עלמא) כְּמָה דְּאָמַר, לָאו הוּא כְּלוּם, דְּהָא מְסִירָא דָּא בִּידָנָא, (קהלת ט׳:ד׳) אֶל כָּל הַחַיִּים יֵשׁ בִּטָּחוֹן, וּמְסִירָא דָּא בִּידַיְיהוּ, (קהלת ט׳:ד׳) כִּי לְכֶלֶב חַי הוּא טוֹב מִן הָאַרְיֵה הַמֵּת. הֵיךְ יְהֵא לָן חַיִּין בְּהַהוּא עָלְמָא. וְעַל דָּא זֶה רָע ודַּאי, דְּלָא יְדוּרוּן בְּמַלְכָּא עִלָּאָה, וְלָא יְהֵא לוֹן חוּלָקָא בֵּיהּ. וְאַף עַל גַּב דְּכָל הָנֵי קְרָאֵי תִּשְׁכַּח סְמִיכִין לְחַבְרַיָּיא בְּמִלִּין אַחֲרָנִין, אֲבָל וַדַּאי שְׁלֹמֹה קָא אָתָא לְגַלָּאָה עַל אִינּוּן חַיָּיבִין מְחוּסְרֵי מְהֵימְנוּתָא, דְּלֵית לוֹן חוּלָקָא בְּקוּדְשָׁא בְּרִיךְ הוּא בְּעָלְמָא דֵּין וּבְעָלְמָא דְּאָתֵי.","אָמַר לֵיהּ, תִּבְעֵי דְּנִתְחַבָּר בַּהֲדָךְ וְתֵזִיל בַּהֲדָן. אָמַר לְהוּ, אִי עֲבִידְנָא הָכִי, אוֹרַיְיתָא יִקְרֵי עָלַי כְּסִיל, וְלֹא עוֹד אֶלָּא דְּאִתְחָיַיבְנָא בְּנַפְשָׁאי. אָמְרוּ לֵיהּ לָמָּה. אָמַר לוֹן דְּהָא שְׁלִיחָא אֲנָא, וְשַׁדְרוּ לִי בִּשְׁלִיחוּתָא, וּשְׁלֹמֹה מַלְכָּא אָמַר, (משלי כ״ו:ו׳) מְקַצֶּה רַגְלַיִם חָמָס שׁוֹתֶה שׁוֹלֵחַ דְּבָרִים בְּיַד כְּסִיל. תָּא חֲזֵי, מְרַגְּלִים עַל דְּלָא אִשְׁתְּכָחוּ בְּנֵי מְהֵימְנוּתָא וּשְׁלוּחֵי מְהֵימְנוּתָא, אִתְחָיָיבוּ בְּנַפְשַׁיְיהוּ בְּעָלְמָא דֵּין וּבְעָלְמָא דְּאָתֵי. נָשַׁק לוֹן, וְאָזַל לֵיהּ.","אַזְלוּ רִבִּי חִזְקִיָּה וְרִבִּי יֵיסָא, עַד דַּהֲווֹ אָזְלוּ פָּגְעוּ בְּאִינּוּן בְּנֵי נָשָׁא. שָׁאִילוּ רִבִּי חִזְקִיָּה וְרִבִּי יֵיסָא עָלֵיהּ, אָמְרוּ מַה שְׁמֵיהּ דְּהַהוּא בַּר נָשׁ. אָמְרוּ, רִבִּי חַגַּי הוּא, וְחַבְרָא דְּבֵין חַבְרַיָּיא הוּא, וְשַׁדְרוּ לֵיהּ חַבְרַיָּיא דְּבָבֶל, לְמִנְדַּע מִלִּין מֵרִבִּי שִׁמְעוֹן בֶּן יוֹחָאי וּשְׁאַר חַבְרַיָּיא. אָמַר רִבִּי יֵיסָא, ודַּאי דָּא הוּא רִבִּי חַגַּי, דְּכָל יוֹמוֹי לָא בָּעָא לְאַחֲזָאָה גַּרְמֵיהּ בְּמַה דְּיָדַע, וְעַל דָּא אָמַר לָן דְּהָא בְּרֵיהּ זָכָה לֵיהּ בְּאוֹרַיְיתָא, בְּגִין דְּאָמַר קְרָא, (משלי כ״ו:י״ב-י״ג) רָאִיתָ אִישׁ חָכָם בְּעֵינָיו תִּקְּוָה לִכְסִיל מִמֶּנּוּ. וַדַּאי שְׁלִיחָא מְהֵימָנָא אִיהוּ, (וזכאה הוא שליחא מהימנא) וְזַכָּאָה אִיהוּ מַאן דְּשָׁדַר מִלּוֹי בִּידָא דִּשְׁלִיחָא מְהֵימָנָא.","תָּא חֲזֵי, אֱלִיעֶזֶר עֶבֶד אַבְרָהָם מִבְּנֵי כְּנַעַן הֲוָה, כְּמָה דְאַתְּ אָמֵר, (הושע י״ב:ח׳) כְּנַעַן בְּיָדוֹ מֹאזְנֵי מִרְמָה. וּכְנַעַן כְּתִיב עָלֵיהּ, (בראשית ט׳:כ״ה) אָרוּר כְּנָעַן עֶבֶד עֲבָדִים יִהְיֶה לְאֶחָיו. וּבְגִין דְּהֲוָה שְׁלִיחָא מְהֵימָנָא, מַה כְּתִיב בֵּיהּ. (בראשית כ״ד:כ״ז) בֹּא בְּרוּךְ יְיָ. בְּרוּךְ יְיָ מַמָּשׁ. וְעַל דָּא אַכְתִּיב הָכִי בְּאוֹרַיְיתָא, בְּגִין דְּנָפַק מֵהַהִיא קְלָלָה, וְאִתְבְּרַךְ. וְלָא דַּי לֵיהּ דְּנָפִיק מִנָּהּ, אֶלָּא דְּאִתְבְּרַך בִּשְׁמֵיהּ דְקוּדְשָׁא בְּרִיךְ הוּא. וְאוֹלִיפְנָא דְּאָתָא מַלְאָךְ, וְאָעִיל מִלָּה דָּא בְּפוּמֵיהּ דְּלָבָן.","וַיִשְׁלַח אוֹתָם מֹשֶׁה וְגוֹ', כֻּלָּם אֲנָשִׁים. כֻּלְּהוּ זַכָּאִין הֲווֹ, וְרֵישֵׁי דְּיִשְׂרָאֵל הֲווֹ. אֲבָל אִינּוּן דִּבְּרוּ לְגַרְמַיְיהוּ עֵיטָא בִּישָׁא. אֲמַאי נַטְלֵי עֵיטָא דָּא. אֶלָּא אָמְרוּ, אִי יֵיעֲלוּן יִשְׂרָאֵל לְאַרְעָא, נִתְעֲבָר אֲנָן מִלְּמֶהֱוִי רֵישִׁין, וְיִמְנֵי מֹשֶׁה רֵישִׁין אַחֲרָנִין, דְּהָא אֲנָן זָכֵינָן בְּמַדְבְּרָא לְמֶהֱוִי רֵישִׁין, אֲבָל בְּאַרְעָא לָא נִזְכֵּי. וְעַל דְּנַטְלֵי עֵיטָא בִּישָׁא לְגַרְמַיְיהוּ, מִיתוּ אִינּוּן, וְכָל אִינּוּן דְּנַטְלָן מִלַּיְיהוּ."],[[0,"תו אמר וכי וכו׳:","עוד אמר, וכי על זה בלבד תמה שלמה, והרי במקום אחר אמר כעין זה, פתח ואמר, זה רע בכל אשר נעשה תחת השמש. זה רע ודאי. מהו \u0003זה רע\u0004 זהו מי ששופך זרע בחנם ומשחית דרכו. כי זה אין מדורו עם הקב״ה, ולא יהיה לו חלק לעולם הבא. זה שכתוב, כי לא אל חפץ רשע אתה לא יגורך רע. על זה אמר \u0003זה רע,\u0004 שלא יהיה לו מדור למעלה. \u0003כי מקרה אחד לכל וגם לב בני האדם מלא רע והוללות בלבבם.\u0004 כי בחייהם שטות תקועה בלבם, והם מחוסרי אמונה, ואין להם חלק בהקב״ה, ובאלו בני האמונה לא בעולם הזה ולא בעולם הבא. ז״ש, ואחריו אל המתים."],[1,"ת״ח קב״ה אזהר וכו׳:","בוא וראה הקב״ה מזהיר לבני העולם ואמר, \u0003ובחרת בחיים למען תחיה,\u0004 והיינו החיים של עולם ההוא. ואלו הרשעים מחוסרי אמונה מה אומרים, \u0003כי מי אשר יבחר אל כל החיים יש בטחון.\u0004 שאע״פ שיבחר האדם בעולם ההוא, כמו שאומר, אינו כלום, כי מסורת זה בידינו, \u0003אל כל החיים יש בטחון,\u0004 דהיינו החיים בעולם הזה. ומסורת זה בידיהם, \u0003כי לכלב חי הוא טוב מן האריה המת,\u0004 ואיך יהיה לנו חיים בעולם ההוא. וע״כ זה רע ודאי, שלא ידורו במלך העליון, ולא יהיה להם חלק בו. ואע״פ שכל אלו המקראות תמצא סמוכות, דהיינו דרשות, לחברים, בדברים אחרים. אבל ודאי ששלמה בא לגלות על אלו הרשעים מחוסרי אמונה, שאין להם חלק בהקב\"ה בעולם הזה ובעולם הבא."],[2,"א״ל תבעי דנתחבר וכו׳:","אמרו לו, תרצה שנתחבר עמך ותלך עמנו. אמר להם, אם אעשה כך, יקרא עלי התורה, כסיל. ולא עוד אלא שאהיה מתחייב בנפשי. אמרו לו למה. אמר להם, כי שליח אני ששלחו אותי בשליחות, ושלמה המלך אמר, מקצה רגלים חמס שותה שולח דברים ביד כסיל. בוא וראה, המרגלים, על שלא נמצאו בני אמונה, ושליחים נאמנים, נתחייבו בנפשם בעולם הזה ובעולם הבא. נשק להם והלך לו."],[3,"אזלו רבי חזקיה וכו׳:","הלכו ר״ח ור׳ ייסא. בעוד שהיו הולכים פגשו בני אדם. שאלו ר׳ חזקיה ור׳ ייסא עליו, אמרו מה שמו של אדם ההוא. אמרו, ר׳ חגי הוא, וחבר שבין החברים הוא. ושלחו אותו החברים מבבל, לדעת דברים מר׳ שמעון בן יוחאי ושאר החברים. א״ר ייסא, ודאי זהו ר׳ חגי שכל ימיו לא רצה להראות את עצמו במה שיודע, וע״כ אמר לנו שבנו זיכה אותו בתורה. משום שאמר הכתוב, ראית איש חכם בעיניו תקוה לכסיל ממנו. ודאי שליח נאמן הוא. ואשרי הוא מי ששולח דבריו ביד שליח נאמן."],[4,"ת״ח אליעזר עבד וכו׳:","בוא וראה, אליעזר עבד אברהם, מבני כנען היה, כש״א, כנען בידו מאזני מרמה. וכנען, כתוב עליו, ארור כנען עבד עבדים יהיה לאחיו. ומשום שהיה שליח נאמן, מה כתוב בו, בא ברוך ה'. ברוך ה׳ ממש. וע״כ נכתב כך בתורה, משום שיצא מקללה הזו של כנען, ונתברך. ולא די לו שיצא מקללה, אלא שנתברך בשמו של הקב״ה. ולמדתי שבא מלאך והכניס דבר זה, דהיינו שיקראהו ברוך ה', בפיו של לבן."],[5,"וישלח אותם משה","וגו' \u0003כלם אנשים:\u0004 היינו שכולם היו צדיקים וראשי ישראל היו, אבל הם נטלו לעצמם עצה רעה. למה נטלו עצה זו. אלא שאמרו, אם יכנסו ישראל לארץ יעברו אותנו מלהיות ראשים, ומשה ימנה ראשים אחרים, כי אנו זכינו להיות ראשים רק במדבר, אבל בארץ לא נוכה להיות ראשים. ועל שנטלו עצה רעה לעצמם, מתו, הם, וכל אלו שקבלו דבריהם."]],[[0,"","עוֹד אָמַר, וְכִי עַל זֶה בִּלְבַד תָּמַהּ שְׁלֹמֹה, וַהֲרֵי בְּמָקוֹם אַחֵר אָמַר כְּמוֹ זֶה? פָּתַח וְאָמַר, (קהלת ט) זֶה רָע בְּכֹל אֲשֶׁר נַעֲשָׂה תַּחַת הַשֶּׁמֶשׁ. זֶה רָע וַדַּאי. מַהוּ זֶה רָע? זֶהוּ מִי שֶׁשּׁוֹפֵךְ זֶרַע בְּרֵיקָנוּת וּמְחַבֵּל דְּרָכָיו, מִשּׁוּם שֶׁזֶּה אֵין מְדוֹרוֹ בַּקָּדוֹשׁ-בָּרוּךְ-הוּא, וְלֹא יִהְיֶה לוֹ חֵלֶק לָעוֹלָם הַבָּא. זֶהוּ שֶׁכָּתוּב (תהלים ה) כִּי לֹא אֵל חָפֵץ רֶשַׁע אָתָּה לֹא יְגֻרְךְ רָע. עַל זֶה אָמַר, זֶה רָע, שֶׁלֹּא יִהְיֶה לוֹ מָדוֹר לְמַעְלָה. כִּי מִקְרֶה אֶחָד לַכֹּל וְגַם לֵב בְּנֵי הָאָדָם מָלֵא רָע (משום זה) וְהוֹלֵלוֹת בִּלְבָבָם בְּחַיֵּיהֶם (קהלת ט). שְׁטוּת תְּקוּעָה בְּלִבָּם, וְהֵם מְחֻסְּרֵי אֱמוּנָה, וְאֵין לָהֶם חֵלֶק בַּקָּדוֹשׁ-בָּרוּךְ-הוּא וּבְאוֹתָם בְּנֵי אֱמוּנָה, לֹא בָּעוֹלָם הַזֶּה וְלֹא בָּעוֹלָם הַבָּא. זֶהוּ שֶׁכָּתוּב (שם) וְאַחֲרָיו אֶל הַמֵּתִים."],[1,"","בֹּא וּרְאֵה, הַקָּדוֹשׁ בָּרוּךְ הוּא מַזְהִיר לִבְנֵי הָעוֹלָם וְאָמַר, (דברים ל) וּבָחַרְתָּ בַּחַיִּים לְמַעַן תִּחְיֶה, (בעולם הזה, ובעולם הבא) וְהַחַיִּים שֶׁל אוֹתוֹ עוֹלָם הֵם. אוֹתָם רְשָׁעִים מְחֻסְּרֵי אֱמוּנָה מָה אוֹמְרִים? כִּי מִי אֲשֶׁר יִבְחַר וְגוֹ'. אַף עַל גַּב שֶׁיִּבְחַר אָדָם בְּזֶה הָעוֹלָם (באותו עולם) כְּמוֹ שֶׁאָמַר - לֹא כְלוּם הוּא, שֶׁהֲרֵי מָסוּר בְּיָדֵינוּ, (קהלת שם) אֶל כָּל הַחַיִּים יֵשׁ בִּטָּחוֹן, וּמָסוּר הוּא בְיָדֵינוּ, (שם) כִּי לְכֶלֶב חַי הוּא טוֹב מִן הָאַרְיֵה הַמֵּת. אֵיךְ יִהְיֶה לָנוּ חַיִּים בְּאוֹתוֹ עוֹלָם? וְעַל כֵּן זֶה רָע וַדַּאי, שֶׁלֹּא יָדוּרוּ בַּמֶּלֶךְ הָעֶלְיוֹן וְלֹא יִהְיֶה לָהֶם בּוֹ חֵלֶק. וְאַף עַל גַּב שֶׁכָּל הַפְּסוּקִים הַלָּלוּ תִּמְצָא סִמּוּכִין לַחֲבֵרִים בִּדְבָרִים אֲחֵרִים, אֲבָל שְׁלֹמֹה בָּא לְגַלּוֹת עַל אוֹתָם רְשָׁעִים מְחֻסְּרֵי אֱמוּנָה שֶׁאֵין לָהֶם חֵלֶק בַּקָּדוֹשׁ-בָּרוּךְ- הוּא בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא."],[2,"","אָמַר לוֹ, הֲתִרְצֶה שֶׁנִּתְחַבֵּר אִתְּךְ וְתֵלֵךְ אִתָּנוּ? אָמַר לָהֶם, אִם אֶעֱשֶׂה כָּךְ, הַתּוֹרָה תִּקְרָא עָלַי כְּסִיל! וְלֹא עוֹד, אֶלָּא שֶׁאֶתְחַיֵּב בְּנַפְשִׁי. אָמְרוּ לוֹ, לָמָּה? אָמַר לָהֶם, שֶׁהֲרֵי אֲנִי שָׁלִיחַ, וּשְׁלָחוּנִי בִשְׁלִיחוּת, וּשְׁלֹמֹה הַמֶּלֶךְ אָמַר, (משלי כו) מְקַצֶּה רַגְלַיִם חָמָס שּתֶה שֹׁלֵחַ דְּבָרִים בְּיַד כְּסִיל. בּא וּרְאֵה, הַמְרַגְּלִים, עַל שֶׁלֹּא נִמְצְאוּ בְּנֵי הָאֱמוּנָה וּשְׁלוּחֵי אֱמוּנָה, הִתְחַיְּבוּ בְנַפְשָׁם בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא. נְשָׁקָם וְהָלַךְ לוֹ."],[3,"","הָלְכוּ רַבִּי חִזְקִיָּה וְרַבִּי יֵיסָא. עַד שֶׁהָיוּ הוֹלְכִים פָּגְעוּ בְּאוֹתָם בְּנֵי אָדָם. שָׁאֲלוּ אֶת רַבִּי חִזְקִיָּה וְרַבִּי יֵיסָא עָלָיו. אָמְרוּ, מַה שְּׁמוֹ שֶׁל אוֹתוֹ אָדָם? אָמְרוּ, רַבִּי חַגַּי הוּא, וְחָבֵר בֵּין הַחֲבֵרִים הוּא, וּשְׁלָחוּהוּ הַחֲבֵרִים מִבָּבֶל לָדַעַת דְּבָרִים מֵרַבִּי שִׁמְעוֹן בֶּן יוֹחַאי וּשְׁאָר הַחֲבֵרִים. אָמַר רַבִּי יֵיסָא, וַדַּאי זֶהוּ רַבִּי חַגַּי, שֶׁכָּל יָמָיו לֹא רָצָה לְהַרְאוֹת עַצְמוֹ בְּמַה שֶּׁיָּדַע, וְעַל זֶה אָמַר לָנוּ שֶׁהֲרֵי בְּנוֹ זָכָה לוֹ בַּתּוֹרָה, מִשּׁוּם שֶׁאָמַר הַפָּסוּק, (שם) רָאִיתָ אִישׁ חָכָם בְּעֵינָיו תִּקְוָה לִכְסִיל מִמֶּנּוּ. וַדַּאי שָׁלִיחַ נֶאֱמָן הוּא, (ואשריו הוא שליח נאמן) וְאַשְׁרָיו מִי שֶׁשָּׁלַח דְּבָרָיו בִּידֵי שָׁלִיחַ נֶאֱמָן."],[4,"","בֹּא וּרְאֵה, אֱלִיעֶזֶר עֶבֶד אַבְרָהָם מִבְּנֵי כְנַעַן הָיָה, כְּמוֹ שֶׁנֶּאֱמַר (הושע יב) כְּנַעַן בְּיָדוֹ מֹאזְנֵי מִרְמָה. וְעַל כְּנַעַן כָּתוּב, (בראשית ט) אָרוּר כְּנָעַן עֶבֶד עֲבָדִים יִהְיֶה לְאֶחָיו. וּמִשּׁוּם שֶׁהָיָה שָׁלִיחַ נֶאֱמָן, מַה כָּתוּב בּוֹ? (שם כד) בּא בְּרוּךְ ה'. בְּרוּךְ ה' מַמָּשׁ. וְעַל זֶה נִכְתַּב כָּךְ בַּתּוֹרָה, מִשּׁוּם שֶׁיָּצָא מֵאוֹתָהּ קְלָלָה וְהִתְבָּרֵךְ. וְלֹא דַי לוֹ שֶׁיָּצָא מִמֶּנָּה, אֶלָּא שֶׁהִתְבָּרֵךְ בְּשֵׁם הַקָּדוֹשׁ בָּרוּךְ הוּא. וְלָמַדְנוּ שֶׁבָּא מַלְאָךְ, וְהִכְנִיס דָּבָר זֶה בְּפִי לָבָן."],[5,"","וַיִּשְׁלַח אֹתָם מֹשֶׁה וְגוֹ', כֻּלָּם אֲנָשִׁים. כֻּלָּם צַדִּיקִים הָיוּ וְרָאשֵׁי יִשְׂרָאֵל הָיוּ, אֲבָל הֵם לָקְחוּ לְעַצְמָם עֵצָה רָעָה. מַדּוּעַ נָטְלוּ עֵצָה זוֹ? אֶלָּא אָמְרוּ, אִם יִכָּנְסוּ יִשְׂרָאֵל לָאָרֶץ - יַעֲבִירוּ אוֹתָנוּ מִלִּהְיוֹת רָאשִׁים, וִימַנֶּה מֹשֶׁה רָאשִׁים אֲחֵרִים, שֶׁהֲרֵי אָנוּ זָכִינוּ בַמִּדְבָּר לִהְיוֹת רָאשִׁים, אֲבָל בָּאָרֶץ לֹא נִזְכֶּה. וְעַל שֶׁלָּקְחוּ עֵצָה רָעָה לְעַצְמָם, מֵתוּ הֵם וְכָל אוֹתָם שֶׁלָּקְחוּ דִבְרֵיהֶם."]]],[["אֵלֶּה שְׁמוֹת הָאֲנָשִׁים אֲשֶׁר שָׁלַח מֹשֶׁה וְגוֹ', אָמַר רִבִּי יִצְחָק, מֹשֶׁה אִסְתָּכַּל וְיָדַע דְּלָא יִצְלְחוּן בְּאָרְחַיְיהוּ, כְּדֵין צַלֵּי עָלֵיהּ דִּיהוֹשֻׁעַ. כְּדֵין כָּלֵב הֲוָה בְּדוֹחֲקָא, אָמַר, מַה אַעְבִּיד, הָא יְהוֹשֻׁעַ אָזִיל בְּסִיַיעְתָּא עִלָּאָה דְּמֹשֶׁה, דְּשָׁדַר בֵּיהּ נְהִירוּ דְּסִיהֲרָא, וְהוּא אַנְהִיר עָלֵיהּ בִּצְלוֹתֵיהּ, בְּגִין דְּאִיהוּ שִׁמְשָׁא. מָה עֲבַד כָּלֵב. אִשְׁתְּמִיט מִנַּיְיהוּ, וְאָתֵי לְגַבֵּי קִבְרַיָּיא דַּאֲבָהָן, וְצַלֵּי תַּמָּן צְלוֹתֵיהּ.","אָמַר רִבִּי יְהוּדָה, אֹרַח אַחֲרָא נָטִיל, וְעָקִים שְׁבִילִין, וּמָטָא עַל קִבְרֵי דַּאֲבָהָן, וְאִסְתָּכַּן בְּגַרְמֵיהּ, דְּהָא כְּתִיב וְשָׁם אֲחִימָן שֵׁשַׁי וְתַלְמַי יְלִידֵי הָעֲנָק. אֲבָל מַאן דְּאִיהוּ בְּדוֹחֲקָא, לָא אִסְתָּכַּל מִדִי. כַּךְ כָּלֵב, בְּגִין דְּהֲוָה בְּדוֹחֲקָא, לָא אִסְתָּכַּל מִדִי, וְאָתָא לְצַלָּאָה עַל קִבְרֵי אֲבָהָן, לְאִשְׁתְּזָבָא מְעֵיטָא דָּא.","(במדבר י״ג:ט״ז) וַיִּקְרָא מֹשֶׁה לְהוֹשֵׁעַ בִּן נוּן יְהוֹשֻׁעַ. רִבִּי יִצְחָק אָמַר, וְכִי הוֹשֵׁעַ קְרָאֵיהּ קְרָא, וְהָא כְּתִיב (שמות י״ז:ט׳) וַיֹּאמֶר מֹשֶׁה אֶל יְהוֹשֻׁעַ. (שמות ל״ג:י״ב) וִיהוֹשֻׁעַ בִּן נוּן נַעַר. (שמות י״ז:י״ג) וַיַּחֲלוֹשׁ יְהוֹשֻׁעַ. אֶלָּא אָמַר לֵיהּ מֹשֶׁה, יָהּ יוֹשִׁיעֲךָ מִנַּיְיהוּ.","רִבִּי אַבָּא אָמַר, כֵּיוָן דְּשַׁדְרֵיהּ לְמֵיעַל לְתַמָן, אִצְטְרִיךְ לְמֶהֱוִי שְׁלִים. וּבְמָּה. בִּשְׁכִינְתָּא. דְּעַד הַהִיא שַׁעֲתָא נַעַר אִקְרֵי, כְּמָה דְּאוֹקִימְנָא. וּבְהַהִיא שַׁעֲתָא קָשִׁיר לֵיהּ מֹשֶׁה בַּהֲדָהּ, וְאַף עַל גַּב דְּאַשְׁכְּחָן יְהוֹשֻׁעַ בְּקַדְמִיתָא, קְרָא קַרְיֵיהּ הָכִי עַל הַהוּא דְּזַמִּין לְמִקְרְיֵיהּ. אָמַר מֹשֶׁה, וַדַּאי לָא אִצְטְרִיךְ דָּא לְמֵיעַל תַּמָּן, אֶלָּא בִּשְׁכִינְתָּא, וְהָכִי אִתְחֲזֵי.","(במדבר י״ג:כ׳) הֲיֵשׁ בָּהּ עֵץ אִם אַיִן וְגוֹ', רִבִּי חִיָּיא אָמַר, וְכִי לָא הֲוָה יָדַע מֹשֶׁה דְּאִית בָּהּ כַּמָה אִילָנִין מְשַׁנְיָין דָּא מִן דָּא, וְהָא הוּא שִׁבַּח לָהּ לְיִשְׂרָאֵל בְּכַמָּה זִמְנִין, וְהוּא אִסְתָּפַּק בְּדָא. וְהָא קוּדְשָׁא בְּרִיךְ הוּא קָאָמַר לֵיהּ לְמֹשֶׁה בְּקַדְמִיתָא, דְּהִיא אֶרֶץ זָבַת חָלָב וּדְבַשׁ. אָמַר רִבִּי יוֹסֵי, הָא אַתְּעֲרוּ חַבְרַיָּיא, דִּכְתִּיב, (איוב א׳:א׳) אִישׁ הָיָה בְאֶרֶץ עוּץ אִיּוֹב שְׁמוֹ.","אָמַר רִבִּי שִׁמְעוֹן, רָמַז לָהֶם רְמִיזָא דְּחָכְמְתָא, עַל מַה דְּשָׁאִילוּ בְּקַדְמִיתָא. דִּכְתִּיב, (שמות י״ז:ז׳) הֲיֵשׁ יְיָ בְּקִרְבֵּנוּ אִם אָיִן. אָמַר, תַּמָּן, תֶּחֱמוּן, אִי הִיא אִתְחַזְיָא לְהַאי, אוֹ לְהַאי. אָמַר לוֹן, אִי תֶּחֱמוּן דְּאִיבָא דְּאַרְעָא כִּשְׁאַר אַרְעֵי דְּעָלְמָא, יֵשׁ בָּהּ עֵץ אִילָנָא דְּחַיֵּי, וְלָא מֵאֲתָר עִלָּאָה יַתִּיר. וְאִי תֶּחֱמוּן דְּאִיבָא דְּאַרְעָא יַתִּיר וּמְשַׁנְיָיא מִכָּל אֲתָר דְּעָלְמָא, תִּנְדְּעוּן, דְּהָא מֵעַתִּיקָא קַדִּישָׁא קָא נָגִיד וְאִתְמְשַׁךְ הַהוּא שִׁנוּיָיא עִלָּאָה, מִכָּל אַתְרֵי דְּעָלְמָא. וּבְדָא תִּנְדְּעוּן, הֲיֵשׁ בָּהּ עֵ\"ץ, אִם אַיִ\"ן, וְדָא בָּעִיתוּן בְּקַדְמִיתָא (דבמעיכון בעיתון) לְמִנְדַּע דָּא, דִּכְתִּיב, (שמות י״ז:ז׳) הֲיֵשׁ יְיָ בְּקִרְבֵּנוּ. בְּקִרְבֵּנוּ דַּיְיקָא, אוֹ אִם אַיִן. וְעַל דָּא וְהִתְחַזַּקְתֶּם וּלְקַחְתֶּם מִפְּרִי הָאָרֶץ, לְמִנְדַּע שִׁנּוּיָיא דִּילֵיהּ.","וְהַיָּמִים יְמֵי בִּכּוּרֵי עֲנָבִים. וְהַיָּמִים, מַאי קָא מַיְירֵי, דְּהָא וְאָז בִּכּוּרֵי עֲנָבִים סַגִּי לֵיהּ. אֶלָּא וְהַיָּמִים, אִינּוּן דְּאִשְׁתְּמוֹדְעָן, כֻּלְּהוּ הֲווֹ מִתְחַבְּרָן בְּהַהוּא זִמְנָא בְּהַהוּא אִילָנָא דְּחָטָא בֵּיהּ אָדָם הָרִאשׁוֹן. כְּמָה דְּתָנֵינָן עֲנָבִים הָיוּ וְעַל דָּא, וְהַיָּמִים: אִינּוּן דְּאִשְׁתְּמוֹדְעָן, יְמֵי בִּכּוּרֵי עֲנָבִים דַּיְיקָא.","(במדבר י״ג:כ״ב) וַיַּעֲלוּ בַנֶּגֶב וַיָבֹא עַד חֶבְרוֹן. וַיָבֹאוּ מִבָּעֵי לֵיהּ. אֶלָּא אָמַר רִבִּי יוֹסֵי, כָּלֵב הוּא דְּאָתָא לְצַלָּאָה עַל קִבְרֵי אֲבָהָתָא. אָמַר כָּלֵב, יְהוֹשֻׁעַ הָא בָּרְכֵיה מֹשֶׁה בְּסִיוּעָא עִלָּאָה קַדִּישָׁא, וְיָכִיל לְאִשְׁתְּזָבָא מִנַּיְיהוּ, וַאֲנָא מַה אַעְבִּיד. אִימְלָךְ, לְמִבָּעֵי בָּעוּתָא עַל קִבְרֵי אֲבָהָתָא, בְּגִין דְּיִשְׁתְּזִיב מְרָזֵיהוֹן (ס\"א מעיטא בישא) דִּשְׁאַר מְאַלְלִין.","רִבִּי יִצְחָק אָמַר, מַאן דְּהַוָה רָשִׁים מִכֻּלְּהוּ דָּא עָאל בְּגַוִּויהּ דְּבֵיהּ תַּלְיָא כֹּלָּא. וְתָּא חֲזֵי, מַאן הוּא מִשְּׁאַר אָחֳרִי דְּיֵכוּל לְאַעֲלָא תַּמָּן, דְּהָא כְּתִיב וְשָׁם אֲחִימָן שֵׁשַׁי וְתַלְמַי, וּמִדְּחִילוּ דִּלְהוֹן מַאן יָכִיל לְאַעְלָאָה בִּמְעַרְתָּא. אֶלָּא שְׁכִינְתָּא עָאלַת תַּמָּן בְּכָלֵב, לְבַשְּׂרָא לַאֲבָהָן, דְּהָא מָטָא זִמְנָא לְאַעֲלָא בְּנַיְיהוּ לְאַרְעָא, דְּאוֹמֵי לוֹן קוּדְשָׁא בְּרִיךְ הוּא, וְדָא הוּא וַיָּבֹא עַד חֶבְרוֹן."],[[0,"אלה שמות האנשים וגו׳:","אמר ר׳ יצחק, משה הסתכל וידע שלא יצליחו המרגלים בדרכם. אז התפלל על יהושע. היה אז כלב בצרה, אמר מה אעשה, הרי יהושע הולך בעזרה עליונה של משה, ששלח בו אור הלבנה, שהיא המלכות, והוא האיר עליו בתפלתו, משום שהוא בחינת השמש. שהוא ז״א. מה עשה כלב, נשמט מהם, מן המרגלים, ובא לקברי האבות והתפלל שם תפלתו."],[1,"א״ר יהודה ארח וכו׳:","אר״י, דרך אחר לקח כלב, והעקים שבילים, כלומר שהלך דרך שבילים עקומים, והגיע על קברי האבות. ונסתכן בנפשו, שהרי כתוב, ושם אחימן ששי ותלמי ילידי הענק. אבל מי שהוא בצרה אינו מסתכל כלום. כך כלב, משום שהיה בצרה לא הסתכל כלום ובא להתפלל על קברי אבות, להנצל מעצה זו של המרגלים."],[2,"ויקרא משה להושע בן נון יהושע:","רבי יצחק אמר, וכי קראו הכתוב הושע, והרי כתוב, ויאמר משה אל יהושע. ויהושע בן נון נער. ויחלוש יהושע. ומשיב, אלא אמר לו משה יה יושיעך מהם. כי יהושע היא אותיות יה יושיע."],[3,"רבי אבא אמר וכו׳:","רא״א, כיון שמשה שלח את יהושע לבא שמה, לארץ ישראל, היה צריך להיות שלם. ובמה בשכינה. כי ארץ ישראל ה״ס השכינה. ועד שעה ההיא היה נקרא נער, כמו שהעמדנו, דהיינו שהיה אחוז במטטרון שנקרא נער. ובשעה ההיא קשר אותו משה בהשכינה. ואע\"פ שנמצא בכתוב, מקודם לכן יהושע. הוא שהכתוב קראו על מה שעתיד לקרות אותו. אמר משה ודאי אינו ראוי לבא שמה אלא בהשכינה. וכך ראוי, ע״כ קראו יהושע, שהוסיף \u0003י׳\u0004 לשמו, שה״ס השכינה."],[4,"היש בה עץ:","רבי חייא אמר, וכי לא היה יודע משה, שיש בה כמה אילנות משונים זה מזה, והרי הוא שיבח את הארץ לישראל בכמה פעמים, בזית גפן ורמון וכו'. והוא היה מסופק בזה. והרי הקב\"ה אמר למשה בתחילה שהיא ארץ זבת חלב ודבש, אמר ר׳ יוסי. כבר העירו החברים, שכתוב איש היה בארץ \u0003עוץ\u0004 איוב שמו. דהיינו שהיה שואל מהם שיראו, אם יש שם איוב. שיגין עליהם, ועץ, הוא כמו עוץ."],[5,"אמר ר׳ שמעון וכו׳:","אר״ש רמז להם רמז החכמה, על מה ששאלו תחילה. שכתוב, היש ה׳ בקרבנו אם אין. שפירושו אם ז״א שוכן בקרבם שנקרא \u0003הויה,\u0004 או א״א שוכן בקרבם, שנקרא \u0003אין\u0004 (כנ״ל באדרא רבא אות ל״ב) אמר, שם, בארץ, תראו אם הוא ראויה לזה, לז״א שנקרא \u0003עץ\u0004 או לזה, לא״א שנקרא \u0003אין.\u0004 אמר להם אם תראו שפירות הארץ הם כבשאר ארצות שבעולם, הרי יש בה \u0003עץ,\u0004 שהוא עץ החיים, דהיינו ז״א, ולא ממקום עליון יותר. ואם תראו שפירות הארץ משונים יותר מבכל המקומות שבעולם, תדעו שמן עתיקא קדישא הוא נוזל ונמשך אותו שינוי העליון, שיש בה מכל המקומות שבעולם. ובזה תדעו אם יש בה \u0003עץ,\u0004 שהוא ז״א, אם \u0003אין,\u0004 שהוא עתיקא קדישא, דהיינו א״א. וזה רציתם מתחילה לדעת, שכתוב, היש ה׳ בקרבנו, בקרבנו הוא בדיוק, ששאלו אם ז״א שוכן בקרבם, או \u0003אין,\u0004 שהוא א״א. וע״כ והתחזקתם ולקחתם מפרי הארץ. לדעת השינוי שבהם. כלומר לדעת אם יש שינוי בהם או לא."],[6,"והימים ימי בכורי ענבים:","שואל, \u0003והימים,\u0004 מה זה אומר, שהרי, ואז בכורי ענבים, היה די שיכתוב. ומשיב, אלא והימים, הם אלו שנודעו, דהיינו ששת הימים שהם חג״ת נה\"י דז\"א, כולם היו מתחברים בעת ההוא באילן שחטא בו אדם הראשון, שהוא מלכות, כמו שלמדנו ענבים היה. הרי שענבים הוא מלכות. וע״כ הימים האלו שנודעו, שהם ו״ק דז״א, ימי בכורי ענבים, בדיוק, שהיא מלכות. דהיינו שו״ק ח״א נתחברו אז במלכות."],[7,"ויעלו בנגב ויבא עד חברון:","שואל ויבאו היה צריך לומר. ומשיב, אלא אמר ר׳ יוסי, כלב היה, שבא להתפלל על קברי אבות בחברון. אמר כלב, יהושע, הרי ברכו משה בעזרה עליונה קדושה, ויכול להנצל מהם, ואני מה אעשה. לקח עצה, להתפלל תפלה על קברי האבות, כדי שינצל מעצה הרעה של שאר המרגלים."],[8,"רבי יצחק אמר וכו׳:","רי״א, ויבא, פירושו, מי שהוא חשוב יותר מכולם זה נכנס בתוכו, דהיינו השכינה נכנסה ונתלבשה בתוך כלב, שבו, בהשכינה, תלוי הכל. ובוא וראה, מי הוא בעל היתרון מהם, שיוכל לבא שמה לחברון, שהרי כתוב, ושם אחימן ששי ותלמי, ומפחדם, מי יוכל לבא ואפילו להסתתר במערה, אלא שהשכינה נתלבשה שם בכלב, לבשר אל האבות, שהגיע הזמן שיבואו בניהם לארץ אשר נשבע להם הקב״ה, וזה הוא ויבא עד חברון. שלא נאמר ויבואו, כי סובב על השכינה \u0003משאר\u0004 פירושו בעל יתרון, מלשון, ושארית גברא חייבא מן בעירא (קהלת רבה ג׳ י״ט)."]],[[0,"","אֵלֶּה שְׁמוֹת הָאֲנָשִׁים אֲשֶׁר שָׁלַח מֹשֶׁה וְגוֹ'. אָמַר רַבִּי יִצְחָק, מֹשֶׁה הִסְתַּכֵּל וְיָדַע שֶׁלֹּא יַצְלִיחוּ בְדַרְכֵיהֶם, וְאָז הִתְפַּלֵּל עַל יְהוֹשֻׁעַ. וְאָז כָּלֵב הָיָה בְדחַק, וְאָמַר מָה אֶעֱשֶׂה? הֲרֵי יְהוֹשֻׁעַ הוֹלֵךְ בְּסִיּוּעַ עֶלְיוֹן שֶׁל מֹשֶׁה, שֶׁשָּׁלַח בּוֹ אוֹר הַלְּבָנָה, וְהוּא הֵאִיר עָלָיו בִּתְפִלָּתוֹ מִשּׁוּם שֶׁהוּא שֶׁמֶשׁ. מֶה עָשָׂה כָּלֵב? נִשְׁמַט מֵהֶם וְהָלַךְ לְקִבְרֵי הָאָבוֹת, וְהִתְפַּלֵּל שָׁם תְּפִלָּתוֹ."],[1,"","אָמַר רַבִּי יְהוּדָה, דֶּרֶךְ אַחֵר לָקַח, וְעִקֵּם שְׁבִילִים, וְהִגִּיעַ עַל קִבְרֵי הָאָבוֹת וְהִסְתַּכֵּן בְּעַצְמוֹ, שֶׁהֲרֵי כָּתוּב וְשָׁם אֲחִימָן וְשֵׁשַׁי וְתַלְמַי יְלִידֵי הָעֲנָק. אֲבָל מִי שֶׁהוּא בְדחַק, לֹא מִסְתַּכֵּל עַל דָּבָר. כָּךְ כָּלֵב, מִשּׁוּם שֶׁהָיָה בְדחַק, לֹא הִסְתַּכֵּל עַל דָּבָר, וּבָא לְהִתְפַּלֵּל עַל קִבְרֵי הָאָבוֹת לְהִנָּצֵל מֵעֵצָה זוֹ."],[2,"","וַיִּקְרָא מֹשֶׁה לְהוֹשֵׁעַ בִּן נוּן יְהוֹשֻׁעַ. רַבִּי יִצְחָק אָמַר, וְכִי הוֹשֵׁעַ קְרָאוֹ הַפָּסוּק? וַהֲרֵי כָּתוּב (שמות יז) וַיֹּאמֶר מֹשֶׁה אֶל יְהוֹשֻׁעַ. (שם לג) יְהוֹשֻׁעַ בִּן נוּן נַעַר. (שם יז) וַיַּחֲלֹשׁ יְהוֹשֻׁעַ. אֶלָּא אָמַר לוֹ מֹשֶׁה, יָהּ יוֹשִׁיעֲךְ מֵהֶם."],[3,"","רַבִּי אַבָּא אָמַר, כֵּיוָן שֶׁשְּׁלָחוֹ לְהִכָּנֵס לְשָׁם, הִצְטָרֵךְ לִהְיוֹת שָׁלֵם, וּבַמֶּה? בַּשְּׁכִינָה. שֶׁעַד אוֹתָהּ שָׁעָה נִקְרָא נַעַר, כְּמוֹ שֶׁבֵּאַרְנוּ, וּבְאוֹתָהּ שָׁעָה קְשָׁרוֹ מֹשֶׁה אֵלֶיהָ. וְאַף עַל גַּב שֶׁמָּצָאנוּ יְהוֹשֻׁעַ בַּתְּחִלָּה, הַפָּסוּק קְרָאוֹ כָּךְ עַל שֶׁעָתִיד לְהִקָּרֵא כָּךְ. אָמַר מֹשֶׁה, וַדַּאי זֶה לֹא צָרִיךְ לְהִכָּנֵס לְשָׁם, אֶלָּא בַּשְּׁכִינָה, וְכָךְ רָאוּי."],[4,"","הֲיְשִׁ בָּהּ עֵץ אִם אַיִן וְגוֹ'. רַבִּי חִיָּיא אָמַר, וְכִי לֹא הָיָה יוֹדֵעַ מֹשֶׁה שֶׁיֵּשׁ בָּהּ כַּמָּה עֵצִים מְשֻׁנִּים זֶה מִזֶּה? וַהֲרֵי הוּא שִׁבַּח אוֹתָהּ לְיִשְׂרָאֵל כַּמָּה פְעָמִים, וְהוּא הִסְתַּפֵּק בָּזֶה?! וַהֲרֵי הַקָּדוֹשׁ בָּרוּךְ הוּא אָמַר לְמֹשֶׁה בַּתְּחִלָּה שֶׁהִיא אֶרֶץ זָבַת חָלָב וּדְבַשׁ. אָמַר רַבִּי יוֹסֵי, בָּזֶה הִתְעוֹרְרוּ הַחֲבֵרִים, שֶׁכָּתוּב (איוב א) אִישׁ הָיָה בְאֶרֶץ עוּץ אִיּוֹב שְׁמוֹ."],[5,"","אָמַר רַבִּי שִׁמְעוֹן, רָמַז לָהֶם רֶמֶז חָכְמָה עַל מַה שֶּׁשָּׁאֲלוּ בַתְּחִלָּה, שֶׁכָּתוּב (שמות יז) הֲיֵשׁ ה' בְּקִרְבֵּנוּ אִם אָיִן. אָמַר, שָׁם תִּרְאוּ אִם הִיא רְאוּיָה לָזֶה אוֹ לָזֶה. אָמַר לָהֶם, אִם תִּרְאוּ שֶׁפְּרִי הָאָרֶץ כִּשְׁאָר אַרְצוֹת הָעוֹלָם - יֵשׁ בָּהּ עֵץ הַחַיִּים, וְלֹא מִמָּקוֹם יוֹתֵר עֶלְיוֹן. וְאִם תִּרְאוּ שֶׁפְּרִי הָאָרֶץ יָתֵר וּמְשֻׁנֶּה מִכָּל מָקוֹם בָּעוֹלָם, תֵּדְעוּ שֶׁהֲרֵי מֵהָעַתִּיק הַקָּדוֹשׁ שׁוֹפֵעַ וְנִמְשָׁךְ אוֹתוֹ שִׁנּוּי עֶלְיוֹן מִכָּל מְקוֹמוֹת הָעוֹלָם. וּבָזֶה תֵּדְעוּ - הֲישׁ בָּהּ עֵ\"ץ אִם אַיִ\"ן, וְזֶה צְרִיכִים אַתֶּם בַּתְּחִלָּה (שבמעיכם רציתם) לָדַעַת זֶה, שֶׁכָּתוּב הֲיֵשׁ ה' בְּקִרְבֵּנוּ. בְּקִרְבֵּנוּ דַּוְקָא, אוֹ אִם אַיִן. וְעַל זֶה וְהִתְחַזַּקְתֶּם וּלְקַחְתֶּם מִפְּרִי הָאָרֶץ, לָדַעַת שִׁנּוּי שֶׁלּוֹ."],[6,"","וְהַיָּמִים יְמֵי בִּכּוּרֵי עֲנָבִים. וְהַיָּמִים, מַה בָּא לוֹמַר, שֶׁהֲרֵי וְאָז בִּכּוּרֵי עֲנָבִים מַסְפִּיק לוֹ? אֶלָּא וְהַיָּמִים - אוֹתָם הַנּוֹדָעִים, כֻּלָּם הָיוּ מְחֻבָּרִים בְּאוֹתוֹ זְמַן בְּאוֹתוֹ עֵץ שֶׁחָטָא בּוֹ אָדָם הָרִאשׁוֹן, כְּמוֹ שֶׁשָּׁנִינוּ עֲנָבִים הָיוּ, וְעַל זֶה וְהַיָּמִים - אוֹתָם הַיְדוּעִים - יְמֵי בִּכּוּרֵי עֲנָבִים דַּוְקָא."],[7,"","וַיַּעָלוּ בַנֶּגֶב וַיָּבא עַד חֶבְרוֹן. וַיָּבאוּ צָרִיךְ לִהְיוֹת! אֶלָּא אָמַר רַבִּי יוֹסֵי, כָּלֵב הוּא שֶׁבָּא לְהִתְפַּלֵּל עַל קִבְרֵי הָאָבוֹת. אָמַר כָּלֵב, יְהוֹשֻׁעַ הֲרֵי בֵּרְכוֹ מֹשֶׁה בְּסִיּוּעַ עֶלְיוֹן קָדוֹשׁ וְיָכוֹל לְהִנָּצֵל מֵהֶם, וַאֲנִי מָה אֶעֱשֶׂה? נִמְלַךְ לְבַקֵּשׁ בַּקָּשָׁה עַל קִבְרֵי הָאָבוֹת כְּדֵי שֶׁיִּנָּצֵל מִסּוֹדוֹתֵיהֶם (מעצה רעה) שֶׁל שְׁאָר מְרַגְּלִים."],[8,"","רַבִּי יִצְחָק אָמַר, מִי שֶׁהָיָה רָשׁוּם מִכֻּלָּם, זֶה נִכְנַס בּוֹ, שֶׁבּוֹ תָּלוּי הַכֹּל. וּבֹא וּרְאֵה, מִי הוּא מִשְּׁאָר אֲחֵרִים שֶׁיָּכוֹל לְהִכָּנֵס לְשָׁם? שֶׁהֲרֵי כָּתוּב וְשָׁם אֲחִימָן שֵׁשַׁי וְתַלְמַי, וּמִפַּחְדָּם מִי יָכוֹל לְהִכָּנֵס בַּמְּעָרָה? אֶלָּא הַשְּׁכִינָה נִכְנְסָה שָׁם עִם כָּלֵב, לְבַשֵּׂר לָאָבוֹת שֶׁהֲרֵי הִגִּיעַ זְמַן לְהַכְנִיס בְּנֵיהֶם לָאָרֶץ שֶׁנִּשְׁבַּע לָהֶם הַקָּדוֹשׁ בָּרוּךְ הוּא, וְזֶהוּ וַיָּבא עַד חֶבְרוֹן."]]],[["תָּאנָא, אֲחִימָן שֵׁשַׁי וְתַלְמַי, מִמַּאן נַפְקוּ. זַרְעָא הֲווֹ מֵאִינּוּן נְפִילִין, דְּאָפִּיל לוֹן קוּדְשָׁא בְּרִיךְ הוּא בְּאַרְעָא, וְאוֹלִידוּ מִבְּנַת אַרְעָא, וּמִנַּיְיהוּ נַפְקוּ גִּיבָּרֵי עָלְמָא, כְּמָה דִּכְתִּיב, (בראשית ו׳:ד׳) הֵמָּה הַגִּבּוֹרִים אֲשֶׁר מֵעוֹלָם אַנְשֵׁי הַשֵּׁם. אֲשֶׁר מֵעוֹלָם, שַׁמָּשֵׁי (נ\"א מדאתברי) עָלְמָא מִשְׁתַּכְּחֵי. אַנְשֵׁי הַשֵּׁם אֲחִימָן שֵׁשַׁי וְתַלְמַי.","(במדבר י״ג:כ״ג) וַיָבֹאוּ עַד נַחַל אֶשְׁכּוֹל וְגוֹ', רִבִּי יְהוּדָה פָּתַח, (ישעיהו מ״ב:ה׳) כֹּה אָמַר הָאֵל יְיָ בּוֹרֵא הַשָּׁמַיִם וְנוֹטֵיהֶם וְגוֹ'. כַּמָּה אִית לְהוּ לִבְנֵי נָשָׁא לְאִסְתַּכְּלָא בְּפוּלְחָנָא דְקוּדְשָׁא בְּרִיךְ הוּא, כַּמָּה אִית לְהוּ לְאִסְתַּכְּלָא בְּמִלֵּי דְּאוֹרַיְיתָא, דְּכָל מַאן דְּאִשְׁתְּדַּל בְּאוֹרַיְיתָא, כְּאִילּוּ מְקָרֵב כָּל קוֹרְבְּנִין דְּעָלְמָא לְקַמֵּי קוּדְשָׁא בְּרִיךְ הוּא. וְלָא עוֹד אֶלָּא דְקוּדְשָׁא בְּרִיךְ הוּא מְכַפֵּר לֵיהּ עַל כָּל חוֹבוֹי, וּמְתָּקְנִין לֵיהּ כַּמָה כּוּרְסְיָין לְעָלְמָא דְּאָתֵי, (חסר).","רִבִּי יְהוּדָה הֲוָה אָזִיל בְּאָרְחָא בַּהֲדֵי רִבִּי אַבָּא, שָׁאַל לֵיהּ, אָמַר מִלָּה חַד בָּעֵינָא לְשָׁאֲלָא, כֵּיוָן דְּיָדַע קוּדְשָׁא בְּרִיךְ הוּא דְּזַמִּין בַּר נָשׁ לְמֶחֱטֵי קַמֵּיהּ, וּלְמִגְזַר עָלֵיהּ מִיתָה, אֲמַאי בָּרָא לֵיהּ. דְּהָא אוֹרַיְיתָא הֲוָה תְּרֵי אַלְפִין שְׁנִין עַד לָא אִיבְרֵי עָלְמָא. וּכְתִיב בָּהּ בְּאוֹרַיְיתָא, (במדבר י״ט:י״ד) אָדָם כִּי יָמוּת בְּאֹהֶל. (במדבר כ״ז:ח׳) אִישׁ כִּי יָמוּת. וַיָּמָת. וַיְחִי פְּלוֹנִי וַיָּמָת. מַאי קָבָעֵי קוּדְשָׁא בְּרִיךְ הוּא לְבַּר נָשׁ בְּהַאי עָלְמָא, דְּאֲפִילּוּ אִי אִשְׁתָּדַּל בְּאוֹרַיְיתָא יְמָמָא וְלֵילְיָא יְמוּת, וְאִי לָא אִשְׁתָּדַּל בְּאוֹרַיְיתָא יְמוּת, כֹּלָּא בְּחַד אָרְחָא, בַּר פְּרִישׁוּתָא דְּהַהוּא עָלְמָא, כְּמָה דְאַתְּ אָמֵר (קהלת ט׳:ב׳) כַּטּוֹב כַּחוֹטֶא.","אָמַר לֵיהּ, אוֹרְחוֹי דְּמָארָךְ, וְגַזְרֵי דְּמָארָךְ, מַה לָךְ לְמִטְרַח בְּהוּ. מַה דְּאִית לָךְ רְשׁוּ לְמִנְדַּע וּלְאִסְתַּכְּלָא שָׁאִיל, וּדְלֵית לָךְ רְשׁוּ לְמִנְדַּע, כְּתִיב (קהלת ה׳:ה׳) אַל תִּתֵּן אֶת פִּיךָ לַחֲטִיא אֶת בְּשָׂרֶךָ, דְּאוֹרְחוֹי דְקוּדְשָׁא בְּרִיךְ הוּא וְסִתְרִין, גְּנִיזִין עִלָּאִין, דְּהוּא סָתִים וְגָנִיז לֵית לָן לְשָׁאֲלָא. אָמַר לֵיהּ, אִי הָכִי, הָא אוֹרַיְיתָא כֹּלָּא סָתִים וְגָנִיז, דְּהָא הִיא שְׁמָא קַדִּישָׁא עִלָּאָה הֲוִי, וּמַאן דְּמִתְעֲסָק בְּאוֹרַיְיתָא כְּאִלּוּ אִתְעֲסָק בִּשְׁמֵיהּ קַדִּישָׁא, וְאִי הָכִי, לֵית לָן לְשָׁאֲלָא וּלְאִסְתַּכְּלָא.","אָמַר לֵיהּ אוֹרַיְיתָא כֹּלָּא סָתִים וְגַלְיָיא, וּשְׁמֵיהּ קַדִּישָׁא סָתִים וְגַלְיָיא, וּכְתִיב (דברים כ״ט:כ״ח) הַנִּסְתָּרוֹת לַה' אֱלֹהֵינוּ וְהַנִּגְלוֹת לָנוּ וּלְבָנֵינוּ, הַנִּגְלוֹת לָנוּ, דְּאִית רְשׁוּ לְשָׁאֲלָא, וּלְעַיְּינָא וּלְאִסְתַּכְּלָא בְּהוּ וּלְמִנְדַּע בְּהוּ. אֲבָל הַנִּסְתָּרוֹת לַיְיָ אֱלֹהֵינוּ, דִּילֵיהּ אִינּוּן, וְלֵיהּ אִתְחַזְיָין, דְּמַאן יָכִיל לְמִנְדַּע וּלְאִתְדַּבְּקָא דַּעְתּוֹי סְתִימָא, וְכָּל שֶׁכֵּן לְמִשְׁאַל.","תָּא חֲזֵי, לֵית רְשׁוּ לִבְנֵי עָלְמָא לְמֵימַר מִלִּין סְתִימִין וּלְפָרְשָׁא לוֹן, בַּר בּוּצִינָא קַדִּישָׁא רַבִּי שִׁמְעוֹן, דְּהָא קוּדְשָׁא בְּרִיךְ הוּא אִסְתָּכַּם עַל יְדוֹי. וּבְגִין דְּדָרָא דִּילֵיהּ רְשִׁימָא הוּא לְעֵילָּא וְתַתָּא, וְעַל דָּא מִלִּין אִתְּמָרוּ בְּאִתְגַּלְיָיא עַל יְדוֹי, וְלָא יְהֵא דָּרָא כְּדָרָא דָּא דְּאִיהוּ שָׁארֵי בְּגַוִיהּ, עַד דְּיֵיתֵי מַלְכָּא מְשִׁיחָא.","אֲבָל תָּא חֲזֵי, כְּתִיב (בראשית א׳:כ״ז) וַיִּבְרָא אֱלֹהִים אֶת הָאָדָם בְּצַלְמוֹ בְּצֶלֶם אֱלֹהִים בָּרָא אוֹתוֹ (בכלא הוא כעין דוגמא דעילא תא חזי) רָזָא דְּמִלָּה, תְּלַת עָלְמִין אִית לֵיהּ לְּקוּדְשָׁא בְּרִיךְ הוּא, דְּאִיהוּ גָּנִיז בְּגַוָויְיהוּ. עָלְמָא קַדְמָאָה, הַהוּא עִלָּאָה טְמִירָא דְּכֹלָּא, דְּלָא אִסְתָּכַּל בֵּיהּ, וְלָא אִתְיְדַע בֵּיהּ, בַּר אִיהוּ, דְּאִיהוּ גָּנִיז בְּגַוִּויהּ.","עָלְמָא תִּנְיָינָא, דְּאִיהוּ קָשִׁיר בְּהַהוּא דִּלְעֵילָּא, וְדָא הוּא דְקוּדְשָׁא בְּרִיךְ הוּא אִשְׁתְּמוֹדַע מִנֵּיהּ, כְּמָה דִּכְתִּיב (תהילים קי״ח:י״ט) פִּתְחוּ לִי שַׁעֲרֵי צֶדֶק, זֶה הַשַּׁעַר לַיְיָ. וְדָא הוּא עָלְמָא תִּנְיָינָא.","עָלְמָא תְּלִיתָאָה, הַהוּא עָלְמָא תַּתָּאָה מִנַּיְיהוּ, דְּאִשְׁתְּכַח בֵּיהּ פִּרוּדָא, וְדָא הוּא עָלְמָא, דְּמַלְאֲכֵי עִלָּאֵי שַׁרְיָין בְּגַוִּויהּ, וְקוּדְשָׁא בְּרִיךְ הוּא אִשְׁתְּכַח בֵּיהּ, וְלָא אִשְׁתְּכַח. אִשְׁתְּכַח בֵּיהּ הַשְׁתָּא, כַּד בָּעָאן לְאִסְתַּכְּלָא וּלְמִנְדַּע לֵיהּ, אִסְתַּלָּק מִנַּיְיהוּ, וְלָא אִתְחֲזֵי, עַד דְּכֻלְּהוּ שָׁאֲלֵי אַיֵּה מְקוֹם כְּבוֹדוֹ. (יחזקאל ג׳:י״ב) בָּרוּךְ כְּבוֹד יְיָ מִמְּקוֹמוֹ. וְהַאי הוּא עָלְמָא דְּלָא אִשְׁתְּכַח בֵּיהּ תְּדִירָא."],[[0,"תאנא אחימן ששי וכו׳:","למדנו, אחימן ששי ותלמי ממי יצאו. הם היו זרעם של אלו הנפילים, שהפילם הקב״ה מן השמים לארץ, והולידו מבנות הארץ. ומהם יצאו גבורי העולם, כמ״ש, המה הגבורים אשר מעולם אנשי השם. \u0003אשר מעולם,\u0004 פירושו, שנמצאים מעת שנברא העולם. \u0003אנשי השם,\u0004 אחימן ששי ותלמי. כלומר ששמם נודע בעולם."],[1,"ויבואו עד נחל אשכול וגו׳:","ר׳ יהודה פתח, כה אמר האל ה׳ בורא השמים ונוטיהם וגו'. כמה יש להם לבני אדם להסתכל בעבודת הקב״ה, כמה יש להם להסתכל בדברי תורה, שכל מי שעוסק בתורה, כאלו מקריב כל הקרבנות שבעולם לפני הקב״ה. ולא עוד, אלא שהקב״ה מכפר לו על כל עונותיו, ומתקנים לו כמה כסאות לעולם הבא."],[2,"ר׳ יהודה הוה וכו׳:","ר׳ יהודה היה הולך בדרך עם ר׳ אבא. שאל אותו, אמר, דבר אחד אני רוצה לשאול, כיון שידע הקב״ה שאדם עתיד לחטוא לפניו ושיגזור עליו מיתה, למה בראו. והרי התורה היתה ב׳ אלפים שנה קודם שנברא העולם, דהיינו לפני חטאו של אדם הראשון, וכתוב בה בתורה, אדם כי ימות באהל. איש כי ימות. וימת. ויחי פלוני וימת. מה רצה הקב״ה מן האדם בעולם הזה, שאפילו אם עוסק בתורה יומם ולילה ימות, ואם אינו עוסק בתורה ימות, ודרך אחד לכולם, חוץ ממה שהחוטא נפרש מעולם ההוא. אבל בעולם הזה כולם שוים, כש״א כטוב כחוטא."],[3,"א״ל אורחוי דמארך וכו׳:","אמר לו, דרכיו של אדונך, וגזרות של אדונך, מה לך להתייגע בהם. מה שיש לך רשות לדעת ולהסתכל, שאל, ומה שאין לך רשות לדעת, כתוב, אל תתן את פיך לחטיא את בשרך. כי דרכיו של הקב״ה ונסתריו, סתרי עליונים, שהוא סתם וגנז, אין לנו לשאול. אמר לו, א״כ הרי התורה כולה סתומה וגנוזה, כי היא שם הקדוש העליון, ומי שעוסק בתורה כאלו עוסק בשמו הקדוש, וא״כ אין לנו לשאול ולהסתכל בתורה."],[4,"א״ל אורייתא כלא וכו׳:","אמר לו התורה כולה סתומה וגלויה, ושמו הקדוש סתום וגלוי, וכתוב, הנסתרות לה׳ אלקינו והנגלות לנו ולבנינו. \u0003הנגלות לנו,\u0004 היינו שיש רשות לשאול ולהתבונן ולהסתכל בהם ולדעת בהם. אבל \u0003הנסתרות לה׳ אלקינו,\u0004 שלו הם, ולו הם ראוים, כי מי יכול לדעת ולהשיג דעתו הסתום, וכל שכן לשאול."],[5,"ת״ח לית רשו וכו׳:","בוא וראה, אין רשות לבני העולם, לומר דברים סתומים ולפרשם. חוץ מן המאור הקדוש ר׳ שמעון, כי הקב״ה הסכים על ידו. ומשום שהדור שלו מצוין למעלה ולמטה, וע״כ נאמרים הדברים על ידו בגלוי, ולא יהיה דור כדור הזה שהוא שוכן בתוכו עד שיבא מלך המשיח."],[6,"אבל ת״ח כתיב וכו׳:","אבל בוא וראה כתוב, ויברא אלקים את האדם בצלמו בצלם אלקים ברא אותו. סוד הדבר הוא, שלשה עולמות יש לו להקב\"ה שהוא נסתר בתוכם. עולם הראשון, הוא עולם העליון הנסתר מכל, שלא נסתכל בו ולא נודע בו חוץ מאותו שהוא גנוז בתוכו. והוא עולם ז״א דאצילות."],[7,"עלמא תניינא דאיהו וכו׳:","עולם השני, הקשור באותו עולם שלמעלה, זה הוא שהקב״ה נודע ממנו. כמו שכתוב, פתחו לי שערי צדק, זה השער לה׳. והוא עולם המלכות דאצילות. שהיא שער לז״א. וזה הוא עולם השני."],[8,"עלמא תליתאה וכו׳:","עולם השלישי, הוא עולם התחתון מהם, שנמצא בו פירוד, דהיינו בי״ע, שעליהם נאמר ומשם יפרד וגו׳. וזה הוא עולם שמלאכים עליונים שורים בתוכו, והקב״ה נמצא בו ואינו נמצא בו, נמצא בו עתה, וכשרוצים להסתכל ולדעת אותו, מסתלק מהם ואינו נראה, עד שכולם שואלים איה מקום כבודו. ברוך כבוד ה׳ ממקומו. וזה הוא עולם שאינו נמצא שם תמיד."]],[[0,"","לָמַדְנוּ, אֲחִימָן שֵׁשַׁי וְתַלְמַי מִמִּי יָצְאוּ? זֶרַע הָיוּ מֵאוֹתָם נְפִילִים שֶׁהִפִּילָם הַקָּדוֹשׁ בָּרוּךְ הוּא בָּאָרֶץ וְהוֹלִידוּ מִבְּנוֹת הָאָרֶץ, וּמֵהֶם יָצְאוּ גִבּוֹרֵי עוֹלָם, כְּמוֹ שֶׁכָּתוּב (בראשית ו) הֵמָּה הַגִּבּרִים אֲשֶׁר מֵעוֹלָם אַנְשֵׁי הַשֵּׁם. אֲשֶׁר מֵעוֹלָם, שַׁמָּשֵׁי (משנברא) הָעוֹלָם נִמְצְאוּ. אַנְשֵׁי הַשֵּׁם, אֲחִימָן שֵׁשַׁי וְתַלְמַי."],[1,"","וַיָּבֹאוּ עַד נַחַל אֶשְׁכֹּל וְגוֹ'. רַבִּי יְהוּדָה פָּתַח, (ישעיה מב) כֹּה אָמַר הָאֵל ה' בּוֹרֵא הַשָּׁמַיִם וְנוֹטֵיהֶם וְגוֹ'. כַּמָּה יֵשׁ לָהֶם לִבְנֵי אָדָם לְהִסְתַּכֵּל בַּעֲבוֹדַת הַקָּדוֹשׁ בָּרוּךְ הוּא. כַּמָּה יֵשׁ לָהֶם לְהִסְתַּכֵּל בְּדִבְרֵי תוֹרָה. שֶׁכָּל מִי שֶׁמִּשְׁתַּדֵּל בַּתּוֹרָה, כְּאִלּוּ מַקְרִיב כָּל קָרְבְּנוֹת הָעוֹלָם לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא. וְלֹא עוֹד, אֶלָּא שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא מְכַפֵּר לוֹ עַל כָּל חֲטָאָיו, וּמְתַקְּנִים לוֹ כַּמָּה כִסְאוֹת לָעוֹלָם הַבָּא."],[2,"","רַבִּי יְהוּדָה הָיָה הוֹלֵךְ בַּדֶּרֶךְ יַחַד עִם רַבִּי אַבָּא. שָׁאַל אוֹתוֹ, אָמַר, דָּבָר אֶחָד אֲנִי רוֹצֶה לִשְׁאֹל; כֵּיוָן שֶׁיָּדַע הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁעָתִיד הָאָדָם לַחֲטֹא לְפָנָיו וְלִגְזֹר עָלָיו מִיתָה, מַדּוּעַ בְּרָאוֹ? שֶׁהֲרֵי הַתּוֹרָה הָיְתָה אַלְפַּיִם שָׁנִים עַד שֶׁלֹּא נִבְרָא הָעוֹלָם, וְכָתוּב בָּהּ בַּתּוֹרָה, (במדבר יט) אָדָם כִּי יָמוּת בְּאֹהֶל. (שם כז) אִישׁ כִּי יָמוּת. וַיָּמָת. וַיְחִי פְּלוֹנִי וַיָּמָת. מָה רָצָה הַקָּדוֹשׁ בָּרוּךְ הוּא לָאָדָם בָּעוֹלָם הַזֶּה, שֶׁאֲפִלּוּ אִם יִשְׁתַּדֵּל בַּתּוֹרָה יוֹמָם וָלַיְלָה יָמוּת, וְאִם לֹא יִשְׁתַּדֵּל בַּתּוֹרָה יָמוּת, הַכֹּל בְּדֶרֶךְ אֶחָד, פְּרָט לִפְרִישׁוּת אוֹתוֹ עוֹלָם, כְּמוֹ שֶׁנֶּאֱמַר (קהלת ט) כַּטּוֹב כַּחוֹטֶא."],[3,"","אָמַר לוֹ, דַּרְכֵי רִבּוֹנְךְ וּגְזֵרוֹת רִבּוֹנְךְ מַה לְּךְ לִטְרֹחַ בָּהֶם? מַה שֶּׁיֵּשׁ לְךְ רְשׁוּת לָדַעַת וּלְהִסְתַּכֵּל - שְׁאַל, וּמַה שֶּׁאֵין לְךְ רְשׁוּת לָדַעַת - כָּתוּב (שם ה) אַל תִּתֵּן אֶת פִּיךְ לַחֲטִיא אֶת בְּשָׂרֶךְ, שֶׁדַּרְכֵי הַקָּדוֹשׁ בָּרוּךְ הוּא וּסְתָרָיו גְּנוּזִים עֶלְיוֹנִים, שֶׁהוּא נִסְתָּר וְגָנוּז אֵין לָנוּ לִשְׁאֹל. אָמַר לוֹ, אִם כָּךְ, הֲרֵי הַתּוֹרָה כֻּלָּהּ נִסְתֶּרֶת וּגְנוּזָה, שֶׁהֲרֵי הִיא שֵׁם קָדוֹשׁ עֶלְיוֹן, וּמִי שֶׁמִּתְעַסֵּק בַּתּוֹרָה כְּאִלּוּ הִתְעַסֵּק בִּשְׁמוֹ הַקָּדוֹשׁ, וְאִם כָּךְ אֵין לָנוּ לִשְׁאֹל וּלְהִסְתַּכֵּל."],[4,"","אָמַר לוֹ, כָּל הַתּוֹרָה נִסְתֶּרֶת וּגְלוּיָה, וּשְׁמוֹ הַקָּדוֹשׁ נִסְתָּר וְגָלוּי, וְכָתוּב (דברים כט) הַנִּסְתָּרֹת לַה' אֱלֹהֵינוּ וְהַנִּגְלֹת לָנוּ וּלְבָנֵינוּ. הַנִּגְלֹת לָנוּ, שֶׁיֵּשׁ לָנוּ רְשׁוּת לִשְׁאֹל וּלְעַיֵּן וּלְהִסְתַּכֵּל בָּהֶם וְלָדַעַת בָּהֶם. אֲבָל הַנִּסְתָּרֹת לַה' אֱלֹהֵינוּ, שֶׁלּוֹ הֵם, וְלוֹ נִרְאִים, שֶׁמִּי יָכוֹל לָדַעַת וּלְהִתְדַּבֵּק בְּדַעְתּוֹ הַנִּסְתֶּרֶת, וְכָל שֶׁכֵּן לִשְׁאֹל?"],[5,"","בֹּא וּרְאֵה, אֵין רְשׁוּת לִבְנֵי הָעוֹלָם לוֹמַר דְּבָרִים נִסְתָּרִים וּלְפָרְשָׁם, פְּרָט לַמְּנוֹרָה הַקְּדוֹשָׁה רַבִּי שִׁמְעוֹן, שֶׁהֲרֵי הַקָּדוֹשׁ בָּרוּךְ הוּא הִסְכִּים עַל יָדוֹ. וּמִשּׁוּם שֶׁדּוֹרוֹ רָשׁוּם לְמַעְלָה וּלְמַטָּה, וְעַל זֶה דְּבָרִים נֶאֱמָרִים בְּגָלוּי עַל יָדוֹ, וְלֹא יִהְיֶה דוֹר כְּדוֹר שֶׁהוּא שָׁרוּי בְּתוֹכוֹ, עַד שֶׁיָּבא מֶלֶךְ הַמָּשִׁיחַ."],[6,"","אֲבָל בּא וּרְאֵה, כָּתוּב (בראשית א) וַיִּבְרָא אֱלֹהִים אֶת הָאָדָם בְּצַלְמוֹ בְּצֶלֶם אֱלֹהִים בָּרָא אֹתוֹ. (בכל הוא כעין דגמה שלמעלה. בא ראה) סוֹד הַדָּבָר - שְׁלֹשָׁה עוֹלָמוֹת יֵשׁ לַקָּדוֹשׁ-בָּרוּךְ-הוּא שֶׁהוּא נִסְתָּר בְּתוֹכָם. עוֹלָם רִאשׁוֹן, אוֹתוֹ עֶלְיוֹן נִסְתַּר הַכֹּל, שֶׁלֹּא מִסְתַּכֵּל בּוֹ וְלֹא נוֹדָע בּוֹ, פְּרָט לוֹ שֶׁהוּא גָנוּז בְּתוֹכוֹ."],[7,"","עוֹלָם שֵׁנִי, שֶׁהוּא קָשׁוּר בְּאוֹתוֹ שֶׁלְּמַעְלָה, וְזֶהוּ שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא נוֹדָע מִמֶּנּוּ, כְּמוֹ שֶׁכָּתוּב (תהלים קיח) פִּתְחוּ לִי שַׁעֲרֵי צֶדֶק, זֶה הַשַּׁעַר לַה'. וְזֶהוּ עוֹלָם שֵׁנִי."],[8,"","עוֹלָם שְׁלִישִׁי, אוֹתוֹ עוֹלָם תַּחְתּוֹן מֵהֶם שֶׁנִּמְצָא בּוֹ פֵּרוּד, וְזֶהוּ עוֹלָם שֶׁמַּלְאָכִים עֶלְיוֹנִים שׁוֹרִים בְּתוֹכוֹ, וְהַקָּדוֹשׁ בָּרוּךְ הוּא נִמְצָא בּוֹ וְלֹא נִמְצָא. נִמְצָא בּוֹ כָּעֵת. כְּשֶׁרוֹצִים לְהִסְתַּכֵּל וְלָדַעַת אוֹתוֹ, מִסְתַּלֵּק מֵהֶם, וְלֹא נִרְאֶה, עַד שֶׁכֻּלָּם שׁוֹאֲלִים אַיֵּה מְקוֹם כְּבוֹדוֹ. (יחזקאל ג) בָּרוּךְ כְּבוֹד ה' מִמְּקוֹמוֹ. וְזֶהוּ עוֹלָם שֶׁלֹּא נִמְצָא בוֹ תָּמִיד."]]],[["כְּגַוְונָא דָּא, (בראשית ט׳:ו׳) בְּצֶלֶם אֱלֹהִים עָשָׂה אֶת הָאָדָם. כְּדֵין אִית לֵיהּ תְּלַת עָלְמִין. עָלְמָא קַדְמָאָה: הַאי עָלְמָא דְּאִקְרֵי עָלְמָא דְּפִירוּדָא, וּבַּר נָשׁ אִשְׁתְּכַח בֵּיהּ וְלָא אִשְׁתְּכַח. כַּד בָּעָאן לְאִסְתַּכְּלָא בֵּיהּ, אִסְתַּלָּק מִנַּיְיהוּ וְלָא אִתְחֲזֵי.","עָלְמָא תִּנְיָינָא, עָלְמָא דְּאִיהוּ קָשִׁיר בְּהַהוּא עָלְמָא עִלָּאָה, וְדָא הוּא גַּן עֵדֶן דִּי בְּאַרְעָא, דְּדָא הוּא קָשִׁיר בְּעָלְמָא אַחֲרָא עִלָּאָה, וּמֵהַאי אִתְיְדַע וְאִשְׁתְּמוֹדַע עָלְמָא אַחֲרָא.","עָלְמָא תְּלִיתָאָה, עָלְמָא עִלָּאָה טְמִירָא, גָּנִיז וְסָתִים, דְּלֵית מַאן דְּיֵדַע לֵיהּ, כְּמָה דִּכְתִּיב, (ישעיהו ס״ד:ג׳) עַיִן לֹא רָאָתָה אֱלֹהִים זוּלָתְךָ יַעֲשֶׂה לִמְחַכֵּה לוֹ. וְכֹלָּא כְּגַוְונָא עִלָּאָה, (קדמאה דאמינא ובקשוט) דִּכְתִּיב, (בראשית ט׳:ו׳) בְּצֶלֶם אֱלֹהִים עָשָׂה אֶת הָאָדָם.","(תא חזי ודאי) עַל דָּא כְּתִיב, (דברים י״ד:א׳) בָּנִים אַתֶּם לַיְיָ אֱלֹהֵיכֶם וְגוֹ', כְּמָה דְּאוּקְמוּהָ. וְאִלֵּין אִינּוּן בְּצֶלֶם אֱלֹהִים, וְאִלֵּין יָרְתִין יְרוּתָא עִלָּאָה כְּגַוְונָא דִּילֵיהּ. וְעַל דָּא אַזְהַר בְּאוֹרַיְיתָא, (דברים י״ד:א׳) לֹא תִּתְגּוֹדְדוּ וְלֹא תָשִימוּ קָרְחָה. דְּהָא לָא אִתְאֲבִיד, וְהָא שְׁכִיחַ בְּעָלְמִין טָבִין עִלָּאִין וְיַקִּירִין, לֶהֱווֹן חַדָּן כַּד אִסְתָּלַק (צדיקא) מֵהַאי עָלְמָא.","וְתָּא חֲזֵי, אִלְמָלֵי לָא חָב אָדָם, לָא יִטְעַם טַעֲמָא דְּמוֹתָא בְּהַאי עָלְמָא, בְּזִמְנָא דְּעָיִיל לְעָלְמִין אַחֲרָנִין. אֲבָל בְּגִין דְּחָב, טַעַם טַעֲמָא דְּמוֹתָא, עַד לָא יֵיעוּל לְאִינּוּן עָלְמִין, וְאִתְפָּשַּׁט רוּחָא מֵהַאי גּוּפָא, וְאַשְׁאַר לֵיהּ בְּהַאי עָלְמָא, וְרוּחָא אִסְתַּחְיָא בִּנְהַר דִּינוּר לְקַבְּלָא עוֹנְשָׁא. וּלְבָתַר עַיְילָא לְגַּן עֵדֶן דִּבְאַרְעָא, וְאִזְדַּמְּנָא לֵיהּ מָאנָא אַחֲרָא דִּנְהוֹרָא, כְּהַאי פַּרְצוּפָא דְּגוּפָא דְּהַאי עָלְמָא מַמָּשׁ. וְאִתְלָבָּשׁ וְאִתְתָּקַּן בֵּיהּ. וְתַמָּן הוּא מָדוֹרָא דִּילֵיהּ תָּדִיר. וְאִתְקְשַׁר בְּרֵישׁ יַרְחֵי וְשַׁבַּתֵּי בְּנִשְׁמְתָא. וְסָלִיק וְאִתְעַטָּר לְעֵילָּא לְעֵילָּא, הֲדָא הוּא דִכְתִיב, (ישעיהו ס״ו:כ״ג) וְהָיָה מִדֵּי חֹדֶשׁ בְּחָדְשׁוֹ וְגוֹ'.","מִדֵּי חֹדֶשׁ בְּחָדְשׁוֹ אֲמַאי. אֶלָּא רָזָא דְּמִלָּה, בְּגִין חַדְתּוּתֵי דְּסִיהֲרָא, דְּאִתְעַטְּרָא (עטרוי) לְאַנְהָרָא מִן שִׁמְשָׁא בְּהַהוּא זִמְנָא. וְכֵן מִדֵּי שַׁבָּת בְּשַׁבַּתּוֹ, מִדֵּי שַׁבָּת דָּא סִיהֲרָא. בְּשַׁבַּתּוֹ דָּא שִׁמְשָׁא. דִּנְהוֹרָא אַתְיָא לָהּ מִן תַּמָּן. וְעַל דָּא כֹּלָּא חַד מִלָּה. וְדָא הוּא בְּרִירָא דְּמִלָּה, בַּר לְחַיָּיבַיָּא דִּכְתִּיב בְּהוּ מִיתָה לְכֻלְּהוּ עָלְמִין, כָּרֵת מִכֻּלְּהוּ עָלְמִין. וְאִשְׁתַּצְיָין מִכֹּלָּא, כַּד לָא עַיְילֵי בִּתְשׁוּבָה. אָמַר רִבִּי יְהוּדָה, בְּרִיךְ רַחֲמָנָא, דְּשָׁאִילְנָא וְרַוַוחְנָא מִלִּין אִלֵּין, וְקָאִימְנָא עָלַיְיהוּ.","אָמַר רִבִּי שִׁמְעוֹן, מִפַּרְשְׁתָּא דָּא אוֹלִיפְנָא רָזָא דְּחָכְמְתָא, וְאִשְׁתְּמָעוּ מִנָּהּ רָזִין עִלָּאִין וְיַקִּירִין. תָּא חֲזֵי, קוּדְשָׁא בְּרִיךְ הוּא מְשַׁבַּח בְּאוֹרַיְיתָא, וְאָמַר אַזִילוּ בְאוֹרְחַי, אִשְׁתַדְלוּ בְּפוּלְחַנַי, וְהָא אֲנָא מְעַיִיל לְכוֹן לְעָלְמִין טָבִין, לְעָלְמִין עִלָּאִין. בְּנֵי נָשָׁא דְּלָא יַדְעֵי, לָא מְהֵימְנֵי, וְלָא מִסְתַּכְּלֵי, קוּדְשָׁא בְּרִיךְ הוּא אָמַר, אֲזִילוּ אֲלִילוּ הַהוּא עָלְמָא טָבָא, הַהוּא עָלְמָא עִלָּאָה דְּכִסּוּפָא. אִינּוּן אַמְרֵי, אֵיךְ נֵיכוּל לְאַלְלָא לֵיהּ, וּלְמִנְדַּע כָּל הַאי.","מַה כְּתִיב. עֲלוּ זֶה בַנֶּגֶב, אִשְׁתְּדָּלוּ בְּאוֹרַיְיתָא, וְתֶחמוּן דְּהָא הִיא קַיְּימָא קַמַיְּיכוּ, וּמִנָהּ תִּנְדְּעוּן לֵיהּ. (במדבר י״ג:י״ח) וּרְאִיתֶם אֶת הָאָרֶץ מַה הִיא וְגוֹ'. תֶּחמוּן מִנָּהּ הַהוּא עָלְמָא, דְּהָא יְרוּתָא דְּאַחֲסָנָא, דַּאֲנָא עָיֵיל לְכוּ בָּה. וְאֶת הָעָם הַיּוֹשֵׁב עָלֶיהָ, אִינּוּן צַדִּיקַיָּיא דִּבְגִנְתָּא דְּעֵדֶן, דְּקַיְימָן שׁוּרִין שׁוּרִין בִּיקָרָא עִלָּאָה, בְּדַרְגִּין עִלָּאִין.","הֶחָזָק הוּא הֲרָפֶה, בָּהּ תֶּחמוּ אִי זָכוּ לְכָל הַאי כַּד אַתְּקָפוּ עַל יִצְרֵיהוֹן, וְתַבְרוּ לֵיהּ, אִי לָא. אוֹ כַּד אַתְּקָפוּ בְּאוֹרַיְיתָא, לְמִלְעֵי בָּהּ יְמָמָא וְלֵילְיָא. אוֹ אִי אַרְפּוּ יְדַיְיהוּ מִנָּהּ. וְזָכוּ לְכָל הַאי. הַמְעַט הוּא אִם רָב, אִי סַגִּיאִין אִינּוּן דְּאִשְׁתָּדָּלוּ בְּפוּלְחָנִי, וְאַתְּקִיפוּ בְּאוֹרַיְיתָא, בְּגִין דְּזָכוּ לְכָל הַאי אִי לָא.","(במדבר י״ג:כ׳) וּמָה הָאָרֶץ הַשְּׁמֵנָה הִיא אִם רָזָא. מִדְּאוֹרַיְיתָא תִּנְדְּעוּן מַה הָאָרֶץ. מַה הַהוּא עָלְמָא אִי אַסְגֵּי טִיבוּ עִלָּאָה לְיָתְבָהָא, אוֹ אִי אַזְעִיר מִנֵּהּ כְּלוּם. הֲיֵשׁ בָּהּ עֵץ אִם אַיִן, הֲאִית בָּהּ אִילָנָא דְּחַיֵּי, לְעָלַם וּלְעָלְמֵי עָלְמִין, אוֹ אִי צְרוֹרָא דְּחַיֵּי אִשְׁתְּכַח בְּגַוָּוהּ, אִם לָא."],[[0,"כגוונא דא בצלם:","כעין זה, בצלם אלקים עשה את האדם, ואז יש לו שלשה עולמות. עולם הראשון, הוא אותו עולם הנקרא עולם הפירוד, דהיינו עולם הזה. והאדם נמצא בו ואינו נמצא, כי כשרוצים להסתכל בו הוא מסתלק מהם, ואינו נראה. פירוש מטרם שחבריו מספיקים להסתכל בו הוא נפטר מן העולם ואינו. כמ״ש, התעיף עיניך בו ואיננו."],[1,"עלמא תניינא וכו׳:","עולם השני הוא עולם הקשור בעולם העליון. וזה הוא גן עדן הארץ, שזה הוא קשור בעולם אחר עליון, ומעולם זה נודע ומושג עולם אחר."],[2,"עלמא תליתאה וכו׳:","עולם השלישי הוא עולם עליון נסתר גנוז וסתום, שאין מי שיודע אותו, כמו שכתוב עין לא ראתה אלקים זולתך, יעשה למחכה לו. והכל כעין העליון. דהיינו כמו שיש ג׳ עולמות למעלה כנ״ל, שכתוב כי בצלם אלקים עשה את האדם."],[2,"","פירוש המאמר. ג׳ עולמות הם למעלה. א) הוא ז״א דאצילות שהוא בחינת ג״ר, דהיינו בסוד מחזה ולמעלה, והוא בחסדים מכוסים והחכמה אינה מגולה בו. וז״ש (באות מ״ו) \u0003עלמא קדמאה\u0004 וכו' \u0003דאיהו גניז בגויה.\u0004 דהיינו שאין בו השגה, משום שהחכמה נעלמת ומכוסה בו. ב) הוא המלכות דאצילות, שהארתה הוא בבחינת ו״ק, וע״כ החכמה מגולה בה, וז״ש \u0003עלמא תניינא\u0004 וכו׳ \u0003דקב״ה אשתמודע מניה\u0004 וכו'. וחוץ ממנה אין גילוי חכמה (כנ״ל ב״א דף רע״ו ד״ה ועוד כמה). ג) הוא למטה ממלכות שעליה נאמר ומשם יפרד, כי העולמות בי״ע שלמטה ממלכות הם דפרודא. ועד״ז נבחן ג״כ כלפי האדם ג׳ עולמות, שבהיותם בהם, הוא מקבל מג׳ העליונים, וחושב ממטה למעלה, שתחילה חושב עולם הזה, שהוא עולם דפרודא. שהוא בדומה לעולם ג׳ העליון. שהוא בי״ע. שבעוה״ז, הוא מקבל נר״ן מבי״ע דפרודא. וז״ש (באות מ״ט) \u0003עלמא קדמאה האי עלמא דאקדי עלמא דפרודא,\u0004 דהיינו בעולם הזה, שהוא כנגד בי״ע דפרודא. ועולם הב׳ הוא כנגד עולם הב׳ העליון שה״ס מלכות דאצילות שבה יש השגה, להיותה בחינת ו״ק. וז״ש (באות נ׳) \u0003עלמא תנינא\u0004 וכו' \u0003ומהאי אתיידע ואשתמודע עלמא אחרא.\u0004 דהיינו ג״ע הארץ, שמשם משיגים עולם הב׳ העליון שה״ס המלכות. ועולם הג׳ של האדם, ה״ס השגת הג״ר הנעלמים. הבא אחר גן העדן. וז״ש \u0003עלמא תליתאה\u0004 וכו׳ \u0003גניז וסתים דלית מאן דידע ליה\u0004 וכו'. והוא כנגד ז״א דאצילות, שה״ס ג״ר כנ״ל, שלעתיד לבא, יעלה ז״א לבחינת חכמה. ואז יהיה השגה בג״ר. וז״ש, יעשה למחכה לו. ונמצא אז שישיג את ז״א ונוקבא דאצילות, וע״ז כתוב \u0003בצלם אלקים עשה את האדם.\u0004 כי השגת ז״א מכונה צלם, והשגת המלכות מכונה דמות."],[3,"על דא כתיב וכו׳:","ע״ז משום שזוכים בג׳ עולמות, כתוב בנים אתם לה׳ אלקיכם, וגו׳ כמו שהעמידוהו. ואלו הם בצלם אלקים, ואלו יורשים ירושה עליונה כעין שלו, דהיינו ג׳ עולמות, וע״כ הזהיר בתורה, לא תתגודדו ולא תשימו קרחה למת, כי אינו נאבד לאחר מותו, והוא נמצא בעולמות טובים עליונים ויקרים, ויהיו בשמחה כשמסתלק צדיק מעולם הזה."],[4,"ות״ח אלמלי וכו׳:","ובוא וראה, אם לא היה חוטא אדם, לא היה טועם טעם המות בעולם הזה, בשעה שנכנס לעולמות האחרים. אבל משום שחטא, הוא טועם מעם המות מטרם שיכנס באלו העולמות, והרוח מתפשט מגוף הזה ומשאירו בעולם הזה, והרוח מתרחץ בנהר דינור לקבל עונשו, ואח״כ נכנס לגן עדן הארץ ומוכן לו כלי אחר של אור הדומה ממש לפרצוף הגוף שהיה לו בעולם הזה, והוא מתלבש ומתתקן בו, ושם, בג״ע, הוא מדורו תמיד. ובראשי חדשים ושבתות הרוח מתקשר בנשמה ועולה ומתעטר למעלה למעלה, בג״ע העליון, ז\"ש והיה מדי חדש בחדשו וגו׳."],[4,"","ומיושב בזה הקושיא שהקשה, על התורה שקדמה לחטא עצה״ד, וכתוב בה אדם כי ימות באהל. כי ההולך מעולם לעולם קוראים בו מיתה. אבל אם לא היה חטא בעצה״ד, לא היה לו גוף מזוהם, אלא שהיה לו גוף הראשון שבגן עדן, שהיה יכול ללכת עמו מעולם לעולם כמו עם הרוח של היום, וע״כ לא היה סובל צער מיתה ועונשים. ועתה שחטא, מחויב להשאיר גוף המזוהם בעוה״ז, והרוח מקבל עונש וטהרה בעולם ההוא, כנ״ל, שכ״ז בא מחמת חטא עצה\"ד."],[5,"מדי חדש בחדשו אמאי וכו׳:","שואל, למה דוקא בראש חדש. ומשיב, אלא סוד הדבר, משום שהתחדשות הלבנה שמתעטרת להאיר מן השמש היא בעת ההיא. כלומר שאז זווג העליון של ז״א ונוקבא המכונים שמש ולבנה. וכן מדי שבת בשבתו, \u0003מדי שבת\u0004 זו היא הלבנה, שהיא המלכות, \u0003בשבתו,\u0004 זה הוא השמש, שהוא ז״א. שהאור בא לה ממנו. וע״כ הכל דבר אחד הוא, שחדש ושבת דבר אחד, שאז זמן זווג ז״א ומלכות. אלא שיש חילוק בשיעור קומה, שבראש חדש הם בקומת ישסו״ת, ובשבת בקומת או״א. וזה הוא בירורו של הדבר. חוץ מן הרשעים שכתוב בהם מיתה לכל העולמות, שזהו כרת מכל העולמות, ונאבדים מכל, אם לא באו בתשובה. א״ר יהודה ברוך הרחמן ששאלתי והרוחתי דברים אלו, ועמדתי על טעמם."],[6,"אמר ר׳ שמעון וכו׳:","אר\"ש מפרשה זו למדתי סוד החכמה, ונשמע ממנה סודות עליונים ויקרים. בוא וראה, הקב״ה משבח בתורה ואמר, לכו בדרכי, ועסקו בעבודתי, ואני אביא אתכם לעולמות טובים לעולמות עליונים. אנשים שאינם יודעים, אינם מאמינים, ואינם מסתכלים, הקב״ה אומר להם, לכו ותרגלו עולם הטוב ההוא, עולם העליון הנחמד ההוא. הם עונים, איך נוכל לרגל אותו ולדעת כל זה."],[7,"מה כתיב, עלו וגו׳:","מה כתוב שהקב״ה אומר להם, \u0003עלו זה בנגב.\u0004 היינו השתדלו בתורה, ותראו שהיא עומדת לפניכם, וממנה תדעו אותו העולם. \u0003וראיתם את הארץ מה היא\u0004 וגו׳, היינו שתראו ממנה אותו העולם, שהוא ירושה ונחלה שאני מביאכם בו. \u0003ואת העם היושב עליה,\u0004 הם הצדיקים שבגן עדן, העומדים שורות שורות ביקר העליון במדרגות העליונות."],[8,"החזק הוא הרפה וכו׳:","היינו, בה תראו, אם זכו לכל זה משום שהתגברו על היצר שלהם בחזקה ושברו אותו, או ברפיון בלי יגיעה. או אם נתחזקו בתורה לעסוק בה יומם ולילה, או שהרפו ידיהם ממנה, ועכ״ז זכו לכל זה. \u0003המעט הוא אם רב,\u0004 אם רבים הם העוסקים בעבודתי ומתחזקים בתורה, וזכו לכל זה. או לא."],[9,"ומה הארץ השמנה הוא אם רזה:","בתורה תדעו, מה הארץ. היינו מה הוא עולם ההוא, אם מרובה בה טוב העליון ליושביה, או אם יחסר בה כלום. \u0003היש בה עץ אם אין,\u0004 היינו היש בה עץ החיים לעולם ולעולמי עולמים, שהוא ז״א, או אם נמצא בה צרור החיים, שהוא יסוד. אם לא."]],[[0,"","כְּמוֹ זֶה, (בראשית ט) בְּצֶלֶם אֱלֹהִים עָשָׂה אֶת הָאָדָם. אָז יֵשׁ לוֹ שְׁלֹשָׁה עוֹלָמוֹת. עוֹלָם רִאשׁוֹן - הָעוֹלָם הַזֶּה שֶׁנִּקְרָא עוֹלַם הַפֵּרוּד, וְהָאָדָם נִמְצָא בּוֹ וְלֹא נִמְצָא. כְּשֶׁרוֹצִים לְהִסְתַּכֵּל בּוֹ, מִסְתַּלֵּק מֵהֶם וְלֹא נִרְאֶה."],[1,"","עוֹלָם שֵׁנִי - עוֹלָם שֶׁהוּא קָשׁוּר בְּאוֹתוֹ עוֹלָם עֶלְיוֹן, וְזֶהוּ גַּן עֵדֶן שֶׁבָּאָרֶץ, שֶׁזֶּהוּ קָשׁוּר בְּעוֹלָם עֶלְיוֹן אַחֵר, וּמִזֶּה נוֹדָע וּמִתְיַדֵּעַ עוֹלָם אַחֵר."],[2,"","עוֹלָם שְׁלִישִׁי - עוֹלָם עֶלְיוֹן טָמִיר, גָּנוּז וְנִסְתָּר, שֶׁאֵין מִי שֶׁיֵּדַע אוֹתוֹ, כְּמוֹ שֶׁכָּתוּב (ישעיה סד) עַיִן לֹא רָאָתָה אֱלֹהִים זוּלָתְךְ יַעֲשֶׂה לִמְחַכֵּה לוֹ. וְהַכֹּל כְּדֻגְמָה עֶלְיוֹנָה, (ראשון שאמרתי ובאמת) שֶׁכָּתוּב (בראשית ט) בְּצֶלֶם אֱלֹהִים עָשָׂה אֶת הָאָדָם."],[3,"","(בא ראה, ודאי) עֵל זֶה כָּתוּב, (דברים יד) בָּנִים אַתֶּם לַה' אֱלֹהֵיכֶם וְגוֹ', כְּמוֹ שֶׁפֵּרְשׁוּהָ. וְאֵלּוּ הֵם בְּצֶלֶם אֱלֹהִים, וְאֵלּוּ יוֹרְשִׁים יְרֻשָּׁה עֶלְיוֹנָה כְּמוֹ שֶׁלּוֹ. וְעַל זֶה מֻזְהָרִים בַּתּוֹרָה (דברים יד) לֹא תִתְגֹּדְדוּ וְלֹא תָשִׂימוּ קָרְחָה. שֶׁהֲרֵי לֹא נֶאֱבָד, וַהֲרֵי מָצוּי בְּעוֹלָמוֹת טוֹבִים עֶלְיוֹנִים וּמְכֻבָּדִים, לִהְיוֹת שְׂמֵחִים כְּשֶׁמִּסְתַּלֵּק (צדיק) מֵהָעוֹלָם הַזֶּה."],[4,"","וּבֹא וּרְאֵה, אִלְמָלֵא לֹא חָטָא אָדָם, לֹא יִטְעַם טַעַם הַמָּוֶת בָּעוֹלָם הַזֶּה בִּזְמַן שֶׁיִּכָּנֵס לְעוֹלָמוֹת אֲחֵרִים. אֲבָל מִשּׁוּם שֶׁחָטָא, טוֹעֵם טַעַם הַמָּוֶת עַד שֶׁלֹּא יִכָּנֵס לְאוֹתָם עוֹלָמוֹת, וּמִתְפַּשֶּׁטֶת הָרוּחַ מִגּוּף זֶה, וּמַשְׁאִירוֹ בָּעוֹלָם הַזֶּה, וְהָרוּחַ מִתְרַחֶצֶת בִּנְהַר דִּינוּר לְקַבֵּל עָנְשָׁהּ. וְאַחַר כָּךְ נִכְנֶסֶת לְגַן עֵדֶן שֶׁבָּאָרֶץ, וּמִזְדַּמֵּן לָהּ כְּלִי אוֹר אַחֵר, כְּפַרְצוּף הַגּוּף שֶׁל הָעוֹלָם הַזֶּה מַמָּשׁ. וּמִתְלַבֶּשֶׁת וְנִתְקֶנֶת בּוֹ, וְשָׁם הוּא מְדוֹרָהּ תָּמִיד. וְנִקְשֶׁרֶת בְּרָאשֵׁי חֳדָשִׁים וְשַׁבָּתוֹת בַּנְּשָׁמָה, וְעוֹלָה וּמִתְעַטֶּרֶת לְמַעְלָה לְמַעְלָה. זֶהוּ שֶׁכָּתוּב (ישעיה סו) וְהָיָה מִדֵּי חֹדֶשׁ בְּחָדְשׁוֹ וְגוֹ'."],[5,"","לָמָּה מִדֵּי חֹדֶשׁ בְּחָדְשׁוֹ? אֶלָּא סוֹד הַדָּבָר, בִּגְלַל הִתְחַדְּשׁוּת הַלְּבָנָה שֶׁמִּתְעַטֶּרֶת (עטרות) לְהָאִיר מֵהַשֶּׁמֶשׁ בְּאוֹתוֹ זְמַן. וְכֵן מִדֵּי שַׁבָּת בְּשַׁבַּתּוֹ. מִדֵּי שַׁבָּת - זוֹ הַלְּבָנָה. בְּשַׁבַּתּוֹ - זֶה הַשֶּׁמֶשׁ. שֶׁהָאוֹר בָּא לָהּ מִשָּׁם. וְעַל זֶה הַכֹּל דָּבָר אֶחָד. וְזֶה בֵּרוּר הַדָּבָר, פְּרָט לָרְשָׁעִים שֶׁכָּתוּב בָּהֶם מִיתָה לְכָל הָעוֹלָמוֹת, כָּרֵת מִכָּל הָעוֹלָמוֹת, וּמֻשְׁמָדִים מֵהַכֹּל כְּשֶׁלֹּא נִכְנָסִים בִּתְשׁוּבָה. אָמַר רַבִּי יְהוּדָה, בָּרוּךְ הָרַחֲמָן שֶׁשָּׁאַלְתִּי וְהִרְוַחְתִּי דְבָרִים הַלָּלוּ וְעָמַדְתִּי עֲלֵיהֶם."],[6,"","אָמַר רַבִּי שִׁמְעוֹן, מִפָּרָשָׁה זוֹ לָמַדְנוּ סוֹד חָכְמָה, וְנִשְׁמָעִים מִמֶּנָּה סוֹדוֹת עֶלְיוֹנִים וְנִכְבָּדִים. בּא וּרְאֵה, הַקָּדוֹשׁ בָּרוּךְ הוּא מְשַׁבֵּחַ בַּתּוֹרָה וְאוֹמֵר: לְכוּ בִדְרָכַי, הִשְׁתַּדְּלוּ בַעֲבוֹדָתִי, וַהֲרֵינִי מַכְנִיסְכֶם לְעוֹלָמוֹת טוֹבִים, לְעוֹלָמוֹת עֶלְיוֹנִים. בְּנֵי אָדָם שֶׁלֹּא יוֹדְעִים, לֹא מַאֲמִינִים וְלֹא מִסְתַּכְּלִים, אוֹמֵר הַקָּדוֹשׁ בָּרוּךְ הוּא: לְכוּ תְּרַגְּלוּ אוֹתוֹ עוֹלָם טוֹב, אוֹתוֹ עוֹלָם עֶלְיוֹן שֶׁל כִּסּוּפִים. הֵם אוֹמְרִים: אֵיךְ נוּכַל לְרַגֵּל אוֹתוֹ וְלָדַעַת כָּל זֶה?"],[7,"","מַה כָּתוּב? עֲלוּ זֶה בַּנֶּגֶב. הִשְׁתַּדְּלוּ בַתּוֹרָה וְתִרְאוּ שֶׁהֲרֵי הִיא עוֹמֶדֶת לִפְנֵיכֶם, וּמִמֶּנָּה תֵדְעוּ אוֹתוֹ. וּרְאִיתֶם אֶת הָאָרֶץ מַה הִיא וְגוֹ'. תִּרְאוּ מִמֶּנָּה אוֹתוֹ עוֹלָם, שֶׁהֲרֵי יְרֻשָּׁה שֶׁל חֵלֶק שֶׁאֲנִי מַכְנִיסְכֶם בָּהּ. וְאֶת הָעָם הַיֹּשֵׁב עָלֶיהָ - אוֹתָם צַדִּיקִים שֶׁבְּגַן עֵדֶן, שֶׁעוֹמְדִים שׁוּרוֹת שׁוּרוֹת בְּכָבוֹד עֵלְיוֹן בִּדְרָגוֹת עֶלְיוֹנוֹת."],[8,"","הֶחָזָקֹ הוּא הֲרָפֶה. בָּהּ תִּרְאוּ אִם זָכוּ לְכָל זֶה כְּשֶׁהִתְגַּבְּרוּ עַל יִצְרָם וּשְׁבָרוּהוּ, אִם לֹא. אוֹ כְּשֶׁהִתְחַזְּקוּ בַתּוֹרָה לַעֲסֹק בָּהּ יוֹמָם וָלַיְלָה. אוֹ אִם הֲרָפוּ יְדֵיהֶם מִמֶּנָּה, וְזָכוּ לְכָל זֶה. הַמְעַט הוּא אִם רָב, אִם רַבִּים אֵלּוּ שֶׁהִשְׁתַּדְּלוּ בַעֲבוֹדָתִי וְהִתְחַזְּקוּ בַתּוֹרָה מִשּׁוּם שֶׁזָּכוּ לְכָל זֶה, אִם לֹא."],[9,"","וּמָה הָאָרֶץ הַשְּׁמֵנָה הִיא אִם רָזָה. מֵהַתּוֹרָה תֵּדְעוּ מָה הָאָרֶץ, מָה אוֹתוֹ עוֹלָם, אִם מַרְבֶּה טוֹבָה עֶלְיוֹנָה לְיוֹשְׁבֶיהָ, אוֹ אִם מַמְעִיט מִמֶּנּוּ כְּלוּם. הֲיֶשׁ בָּהּ עֵץ אִם אַיִן. הֲיֶשׁ בָּהּ עֵץ הַחַיִּים לְעוֹלָם וּלְעוֹלְמֵי עוֹלָמִים, אוֹ שֶׁצְּרוֹר הַחַיִּים נִמְצָא בְתוֹכָהּ, אִם לֹא."]]],[["(במדבר י״ג:כ״ב) וַיַּעֲלוּ בַנֶּגֶב וַיָּבֹא עַד חֶבְרוֹן. וַיַּעֲלוּ בַנֶּגֶב, בְּנֵי נָשָׁא סַלְּקִין בְּגַוָּוהּ בַנֶּגֶב, בְּלִבָּא עַצְלָא, כְּמַאן דְּאִשְׁתְּדַל בְּמַגָּנָא, בִּנְגִּיבוּ, דְּחָשִׁיב דְּלֵית בָּהּ אֲגָר, חָמֵי דְּהָא עוּתְרָא דְּהַאי עָלְמָא אָבִיד בְּגִינָהּ, חָשִׁיב דְּכֹלָּא הוּא. בַנֶּגֶב: כְּמָה דְאַתְּ אָמֵר (בראשית ח׳:י״ג) חָרְבוּ הַמַּיִם, וּמְתַּרְגְמִינָן נְגִיבוּ.","לְבָתַר וַיָּבֹא עַד חֶבְרוֹן, עַד דְּאָתֵי לְאִתְחַבְּרָא בָּהּ, קָארֵי וְשָׁאנֵי בָּה. (במדבר י״ג:כ״ב) וְשָׁם אֲחִימָן שֵׁשַׁי וְתַלְמַי, תַּמָּן חָמֵי פְּלִיגָּן סַגִּיאִין, טָמֵא וְטָהוֹר, אָסוּר וּמוּתָּר, (נ\"א כשר ופסול) עוֹנָשִׁין וְאַגָּרִין. אִלֵּין אִינּוּן אָרְחֵי דְּאוֹרַיְיתָא, דִּקְדוּקֵי אוֹרַיְיתָא. יְלִידֵי הָעֲנָק, דְּאִתְיְלִידוּ מִסִּטְרָא דִּגְבוּרָה.","וְחֶבְרוֹן שֶׁבַע שָׁנִים נִבְנְתָה, אִלֵּין אִינּוּן שִׁבְעִין אַנְפִּין דְּאוֹרַיְיתָא, שִׁבְעִין פָּנִים אִית לָהּ, לְכָל סִטְרָא עַשְׂרָה. וְחֶבְרוֹן, דָּא אוֹרַיְיתָא, מַאן דְּאִשְׁתְּדַל בָּהּ אִקְרֵי חָבֵר. לִפְנֵי צוֹעַן מִצְרָיִם, תָּנֵינָן אוֹרַיְיתָא אִית לָקֳבֵל אוֹרַיְיתָא. וְהַיְינוּ תּוֹרָה שֶׁבִּכְתָּב, וְתוֹרָה שֶׁבְּעַל פֶּה. וְהַאי (מלכות) חֶבְרוֹן. מִתּוֹרָה שֶׁבִּכְתָּב נַפְקַת. כְּמָה דְאַתְּ אָמֵר (משלי ז׳:ד׳) אֱמוֹר לַחָכְמָה אֲחוֹתִי אָתְּ. וְהַאי נִבְנְתָה שֶׁבַע שְׁנִין, דְבְּגִין כָּךְ אִקְרֵי בַּת שֶׁבַע. לִפְנֵי צֹעַן מִצְרָיִם, כְּמָה דְאַתְּ אָמֵר (מלכים א ה׳:י׳) וַתֵּרֶב חָכְמַת שְׁלֹמֹה מֵחָכְמַת כָּל בְּנֵי קֶדֶם וּמִכָּל חָכְמַת מִצְרָיִם.","(במדבר י״ג:כ״ג) וַיָבֹאוּ עַד נַחַל אֶשְׁכּוֹל, אִלֵּין אִינּוּן מִלֵּי אַגָּדָה, דְּרָשָׁה, דְּתַּלְיָין מִסִּטְרָא דִּמְהֵימְנוּתָא. וַיִכְרְתוּ מִשָּׁם זְמוֹרָה וְגוֹ', אוֹלְפִין מִתַּמָּן רָאשֵׁי פִּרְקִין, רָאשֵׁי מִלִּין, אִינּוּן דִּבְנֵי מְהֵימְנוּתָא, חַדָּאן בְּמִלִּין, וּמִתְבָּרְכָן מִלִּין בְּגַוַיְיהוּ, וּמִסְתַּכְּלָן שָׁרְשָׁא חַד וְעִקָרָא חַד, וְלָא אִשְׁתְּכַח בְּהוּ פִּרוּדָא. אִינּוּן דְּלָא מִשְׁתַּכְּחֵי בְּנֵי מְהֵימְנוּתָא, וְלָא אוֹלְפֵי אוֹרַיְיתָא לִשְׁמָהּ, שַׁוְיָן לֵיהּ לִמְהֵימְנוּתָא בְּפִרוּדָא, הֲדָא הוּא דִכְתִיב וַיִּשָּׂאוּהוּ בַמּוֹט בִּשְׁנָיִם, בְּפִרוּדָא. מַהוּ בַמּוֹט. כְּמָה דְאַתְּ אָמֵר (תהילים קכ״א:ג׳) אַל יִתֵּן לַמּוֹט רַגְלֶךָ. וּמִן הָרִמּוֹנִים וּמִן הַתְּאֵנִים, כֹּלָּא שָׁוִין לְהָנֵי מִילֵי לְסִטְרָא אַחֲרָא, לְסִטְרָא דְּמִינָאֵי, לְסִטְרָא דְּפִרוּדָא.","הֲדָא הוּא דִכְתִיב וַיָּשֻׁבוּ מִתּוּר הָאָרֶץ. וַיָּשֻׁבוּ, תַּיְיבִין לְסִטְרָא בִּישָׁא, וְתַיְיבִין מֵאָרְחָא דִּקְשׁוֹט. אַמְרֵי, מַאי אִכְפַּת לָן. עַד יוֹמָא לָא חֲמֵינָא טַב לְעָלְמָא, אַעְמַלְנָא בָּהּ, בֵּיתָא רֵיקָם. יָתִיבְנָא בִּקְלָנָא דְּעַמָּא, וּלְהַהוּא עָלְמָא מַאן יִזְכֵּי וּמַאן יֵיעוּל לְגַוִּויהּ, טַב לָן דְּלָא אַטְרַחְנָא כּוּלֵי הַאי. (במדבר י״ג:כ״ז) וַיְסַפְּרוּ לוֹ וַיֹּאמְרוּ וְגוֹ', הָא אַעְמַלְנָא וְלָאֵינָא, בְּגִין לְמִנְדַּע חוּלָקָא דְּהַהוּא עָלְמָא. וְגַם זָבַת חָלָב וּדְבַשׁ הִיא, טַב הוּא הַהוּא עָלְמָא עִלָּאָה, כְּמָה דְּיָדַעְנָא בְּאוֹרַיְיתָא, אֲבָל מַאן יְכִיל לְמִזְכֵּי בֵּיהּ.","(במדבר י״ג:כ״ח) אֶפֶס כִּי עַז הָעָם, תַּקִּיף הוּא, דְּלָא יַחֲשִׁיב כָּל עָלְמָא כְּלָל, בְּגִין דִּיְהֵא לֵיהּ עוּתְרָא סַגִיא לְאִשְׁתַּדְּלָא בֵּיהּ, מַאן הוּא דְּיִזְכֵּי בָּהּ. וַדַּאי אֶפֶס כִּי עַז הָעָם הַיּוֹשֵׁב בָּאָרֶץ, מַאן דְּבָעֵי לְמִזְכֵּי בָּהּ, בָּעֵי לְמֶהֱוִי תַּקִּיף בְּעוּתְרָא, כְּמָה דְאַתְּ אָמֵר (משלי י״ח:כ״ג) וְעָשִׁיר יַעֲנֶה עַזּוּת. וְהֶעָרִים גְּדוֹלוֹת בְּצוּרוֹת. בָּתִּין מַלְיָין כָּל טוּבָא, דְּלָא יַחְסְרוּן מִכֹּלָּא. וְעִם כָּל דָּא וְגַם יְלִידֵי הָעֲנָק רָאִינוּ שָׁם, בָּעֵי גּוּפָא תַּקִּיף, גִּיבֹּר כַּאֲרִי. (דאשתכח תמן תדירא) בְּגִין דְּהִיא מַתֶּשֶׁת חֵילֵיהּ דְּבַּר נָשׁ לְאִשְׁתַּדְּלָא בְּהַהוּא אִיסוּר וְהֵתֵּר, טָמֵא וְטָהוֹר, כָּשֵׁר וּפָסוּל. מַאן יֵיכוּל לְזַכָּאָה בָּהּ.","וְעוֹד, (במדבר י״ג:כ״ט) עֲמָלֵק יוֹשֵׁב בְּאֶרֶץ הַנֶּגֶב. אִי יֵימָּא בַּר נָשׁ, דְּאֲפִילּוּ בְּכָל דָּא יִזְכֵּי. עֲמָלֵק יוֹשֵׁב בְּאֶרֶץ הַנֶּגֶב, הָא יִצְרָא בִּישָׁא, קַטֵיגוֹרָא, מְקַטְרְגָא דְּבַר נָשׁ, דְּיִשְׁתְּכַח תָּדִיר בְּגוּפָא. וְהַחִתִּי וְהָאֱמוֹרִי וְגוֹ', כַּמָה מְקַטְרְגֵי מִשְׁתַּכְּחֵי תַּמָּן. דְּלָא יָכִיל בַּר נָשׁ לְמֵיעַל בְּהַהוּא עָלְמָא כְּלָל, מַאן יִזְכֵּי לֵיהּ, וּמַאן יֵיעוּל בְּגַוִיהּ, בְּמִלִּין אִלֵּין, (במדבר ל״ב:ט׳) וַיָּנִיאוּ אֶת לֵב בְּנֵי יִשְׂרָאֵל. בְּגִין דְּאַפִּיקוּ שׁוּם בִּישׁ עָלָהּ, כְּמָה דְאַתְּ אָמֵר וַיּוֹצִיאוּ אֶת דִּבַּת הָאָרֶץ.","אִינּוּן בְּנֵי מְהֵימְנוּתָא מַאי קָא אָמְרֵי, אִם חָפֵץ בָּנוּ יְיָ וּנְתָנָה לָנוּ. כֵּיוָן דְּיִשְׁתָּדַּל בַּר נָשׁ בִּרְעוּתָא דְּלִבָּא לְגַבֵּי קוּדְשָׁא בְּרִיךְ הוּא, לָא בָּעֵי מִנָן אֶלָּא לִבָּא, וְיִסְתַּמְרוּן הַהוּא רְשִׁימָא קַדִּישָׁא, דִּכְתִּיב, (ישעיהו ס׳:כ״א) וְעַמֵּךְ כֻּלָּם צַדִּיקִים לְעוֹלָם יִירְשׁוּ אָרֶץ."],[[0,"ויעלו בנגב ויבא עד חברון:","ויעלו בנגב, פירושו, שבני אדם \u0003עולים\u0004 בתוכה, בתורה, \u0003בנגב,\u0004 היינו בלב עצל, כמי שמשתדל בחנם ביבשות, שחושב שאין בה שכר. הוא רואה, שעושר עולם הזה אבד בשבילה, הוא חושב, שהכל הוא אבוד. \u0003בנגב,\u0004 היינו כש״א, חרבו המים, ומתרגמינן נגיבו."],[1,"לבתר ויבא עד וכו':","אח״כ, \u0003ויבא עד חברון.\u0004 היינו שבא להתחבר עם התורה, והוא קורא ושונה בה. \u0003ושם אחימן ששי ותלמי.\u0004 היינו, הוא רואה שם הרבה חילוקים, טמא וטהור, אסור ומותר, עונש ושכר, אלו הם דרכי התורה, דקדוקי התורה, \u0003ילידי הענק,\u0004 היינו שנולדו מצד הגבורה. פירוש, כי \u0003אחימן,\u0004 הוא אותיות אחי מן, \u0003אח\u0004 פירושו ראיה, \u0003מן\u0004 כמו מנין. שמדייק למצוא ראיה על כל דבר. וזהו דקדוקי אורייתא \u0003ששי\u0004 הוא לשון ששון, כמו שישו. והיינו שכר התורה. \u0003ותלמי,\u0004 הוא מלשון תלמי השדה, דהיינו חילוקי התורה, טמא טהור וכו'. כמו תלמים תלמים."],[2,"וחברון שבע שנים נבנתה:","אלו הם ע׳ פנים לתורה, שבעים פנים יש לה לתורה, שה״ס ז״א שיש לו ששה קצוות חג״ת נה״י, ומלכות, שהם ז״ס, ולכל צד עשרה היינו שכל אחת כלולה מע״ס, הם שבעים. וחברון, זו התורה, משום שמי שמשתדל בה נקרא חבר. \u0003לפני צוען מצרים,\u0004 למדנו יש תורה כנגד תורה, והיינו תורה שבכתב שהוא ז״א, ותורה שבעל פה שהיא מלכות. וחברון זו, שהוא תורה שבעל פה, דהיינו מלכות, יצאה מתורה שבכתב, מז״א. כש״א אמור לחכמה אחותי את. וזו נבנתה שבע שנים, דהיינו ז׳ ספירות חג״ת נהי״מ, שמשום זה נקרא בת שבע. \u0003לפני צוען מצרים,\u0004 כמש״א, ותרב חכמת שלמה, שהיא מלכות, מחכמת כל בני קדם ומכל חכמת מצרים."],[2,"","פירוש. שמביא ראיה שהמלכות יצאה מז״א מהכתוב אמור לחכמה אחותי את. כי חכמה זו, היא מלכות, שנקראת חכמה תתאה, ולפי שנשמות ישראל יצאו מז״א, וגם המלכות יצאה מז״א, ע״כ אוה״כ, שתאמר לחכמה שהיא אחותך. הרי שהמלכות יצאה מז״א. ומ״ש, וחברון שבע שנים נבנתה לפני צוען מצרים. הפירוש הוא, כי מצרים היא הלעומת של החכמה, שהיא חכמה דקליפות. ואוה״כ שחברון שהיא מלכות נבנתה בז״ס מז״א, כנגד הלעומת שלה, שהיא צוען מצרים שנתרוקנה, ואין לה בנין. כי כשקמה הקדושה נופלת הס״א."],[3,"ויבואו עד נחל אשכול:","אלו הם דברי אגדה ודרוש, התלוים מצד האמונה, שהיא המלכות, כי דרשות ואגדות תלוים בתורה ומסבבים אותה כמו ענבים באשכול. \u0003ויכרתו משם זמורה\u0004 וגו׳, למדו משם ראשי פרקים ראשי דברים. אלו שהם בני אמונה שמחים בדברים, והדברים מתברכים בתוכם, ומסתכלים שהם שורש אחד ועיקר אחד ולא נמצא בהם פירוד. אלו שאינם נמצאים בני אמונה, ואינם לומדים תורה לשמה, עושים האמונה שהיא המלכות בפירוד מז״א, כי פוגמים בזווג ז״א ומלכות, שהם תושב״כ ותושבע״פ. משום שאינם מאמינים שהם עיקר אחד ושורש אחד. ז״ש, \u0003וישאוהו במוט בשנים,\u0004 שעשו פירוד בין תושב״כ לתורה שבע״פ, וחושבים אותם ח\"ו לשנים. מהו \u0003במוט.\u0004 הוא כש״א אל יתן \u0003למוט\u0004 רגלך. \u0003ומן הרמונים ומן התאנים,\u0004 שמו אלו הדברים לגמרי לסטרא אחרא, לצד המינים ולצד הפירוד. כי \u0003רמונים,\u0004 הוא מלשון מינים, \u0003ותאנים\u0004 הוא מלשון וה' \u0003אינה\u0004 לידו, דהיינו מקרה, שאינם מאמינים בהשגחה, ואומרים על הכל מקרה הוא, ומפרידים השי״ת מן העולם."],[4,"הה״ד, וישובו מתור וכו׳:","ז״ש וישובו מתור הארץ. \u0003וישובו,\u0004 היינו שחזרו לצד הרע, וחזרו מדרך האמת, שאמרו, מה יצא לנו. עד היום לא ראינו טוב בעולם עמלנו בתורה, והבית ריקם. וישבנו בין הירודים שבעם. ולעולם ההוא, מי יזכה, ומי יבא לתוכו, מוטב לנו שלא היינו יגעים כל כך. \u0003ויספרו לו ויאמרו\u0004 וגו׳. הרי עמלנו ולמדנו כדי לדעת חלק עולם ההוא, כמו שיעצת לנו (לעיל אות נ״ו) וגם זבת חלב ודבש הוא, טוב הוא עולם העליון ההוא, כמו שידענו בתורה, אבל מי יכול לזכות בה."],[5,"אפס כי עז העם:","עז הוא העם שזכה לעולם ההוא, שלא החשיב כל העולם כלל, לעסוק בו, כדי שיהיה לו עשירות גדולה. מי הוא שיוכל לעשות כן שיזכה בה. ודאי, \u0003אפס כי עז העם היושב בארץ,\u0004 מי שרוצה לזכות בה צריך שיהיה עז בעשירות. כש״א, ועשיר יענה עזות. וצריך שיהיה לו, \u0003והערים גדולות בצורות,\u0004 דהיינו בתים מלאים כל טוב שלא יחסר בהם כלום. ועם כל זה, \u0003וגם ילידי הענק ראינו שם.\u0004 דהיינו שצריכים גוף חזק גבור כארי, משום שהתורה מתשת כחו של אדם, בעסקו באיסור והתר, טמא וטהור, כשר ופסול, ההוא. מי יוכל לזכות בה."],[6,"ועוד, עמלק יושב בארץ הנגב:","שאם יאמר האדם שאפילו בכל זה, יזכה להתגבר, \u0003עמלק יושב\u0004 בארץ הנגב, הרי יצר הרע הקטיגור, המקטרג על האדם, נמצא תמיד בגוף, \u0003והחתי והאמורי\u0004 וגו׳, כמה מקטרגים נמצאים שמה, שלא יוכל אדם להכנס לעולם ההוא כלל. מי יזכה לו, ומי יכנוס בתוכו. בדברים אלו, ויניאו את לב בני ישראל. משום שהוציאו שם רע עליה. כש״א, \u0003ויוציאו את דבת הארץ.\u0004"],[7,"אינון בני מהימנותא וכו׳:","אלו בני האמונה, מה אמרו. \u0003אם חפץ בנו ה׳ ונתנה לנו,\u0004 דהיינו כיון שאדם משתדל ברצון הלב להקב״ה, יזכה בה, כי אינו רוצה ממנו אלא הלב, וישמרו אותו רושם הקדוש. שהוא ברית הקדש, שכתוב, ועמך כלם צדיקים לעולם יירשו ארץ. דהיינו שומרים הברית הנקראים צדיקים."]],[[0,"","וַיַּעָלוּ בַנֶּגֶב וַיָּבֹא עַד חֶבְרוֹן. וַיַּעֲלוּ בַנֶּגֶב, בְּנֵי אָדָם נִכְנָסִים לְתוֹכָהּ בַּנֶּגֶב, בְּלֵב עָצֵל, כְּמִי שֶׁמִּשְׁתַּדֵּל בְּחִנָּם, בְּיֹבֶשׁ, שֶׁחוֹשֵׁב שֶׁאֵין בָּהּ שָׂכָר. רוֹאֶה שֶׁעֹשֶׁר הָעוֹלָם הַזֶּה אָבַד בִּגְלָלָהּ, חוֹשֵׁב שֶׁהוּא הַכֹּל. בַּנֶּגֶב, כְּמוֹ שֶׁנֶּאֱמַר (בראשית ח) חָרְבוּ הַמַּיִם, וּמְתַרְגְּמִים נְגִיבוּ."],[1,"","אַחַר כָּךְ - וַיָּבא עַד חֶבְרוֹן. עַד שֶׁבָּא לְהִתְחַבֵּר בָּהּ, קוֹרֵא וְשׁוֹנֶה בָּהּ. וְשָׁם אֲחִימָן שֵׁשַׁי וְתַלְמַי (במדבר י״ג:כ״ב), שָׁם רוֹאֶה פִלּוּגִים רַבִּים, טָמֵא וְטָהוֹר, אָסוּר וּמֻתָּר, (כשר ופסול) עֳנָשִׁים וּשְׂכָרִים. אֵלֶּה אוֹתָם דַּרְכֵי הַתּוֹרָה, דִּקְדּוּקֵי הַתּוֹרָה. יְלִידֵי הָעֲנָק, שֶׁנּוֹלְדוּ מִצַּד הַגְּבוּרָה."],[2,"","וְחֶבְרוֹן שֶׁבַע שָׁנִים נִבְנְתָה - אֵלֶּה אוֹתָם שִׁבְעִים פָּנִים שֶׁל הַתּוֹרָה. שִׁבְעִים פָּנִים יֵשׁ לָהּ, לְכָל צַד עֶשֶׂר. וְחֶבְרוֹן, זוֹ הַתּוֹרָה, מִי שֶׁמִּשְׁתַּדֵּל בָּהּ נִקְרָא חָבֵר. לִפְנֵי צֹעַן מִצְרָיִם. שָׁנִינוּ, יֵשׁ תּוֹרָה מוּל תּוֹרָה, וְהַיְנוּ תּוֹרָה שֶׁבִּכְתָב וְתוֹרָה שֶׁבְּעַל פֶּה. וְזֶה (מלכות) חֶבְרוֹן. מִתּוֹרָה שֶׁבִּכְתָב יוֹצֵאת, כְּמוֹ שֶׁנֶּאֱמַר (משלי ז) אֱמֹר לַחָכְמָה אֲחֹתִי אָתְּ. וְזוֹ נִבְנְתָה שֶׁבַע שָׁנִים, שֶׁבִּגְלַל זֶה נִקְרֵאת בַּת שֶׁבַע, לִפְנֵי צֹעַן מִצְרָיִם, כְּמוֹ שֶׁנֶּאֱמַר (מלכים א ה) וַתֵּרֶב חָכְמַת שְׁלֹמֹה מֵחָכְמַת כָּל בְּנֵי קֶדֶם וּמִכָּל חָכְמַת מִצְרָיִם."],[3,"","וַיָּבֹאוּ עַד נַחַל אֶשְׁכּוֹל - אֵלֶּה אוֹתָם דִּבְרֵי אַגָּדָה, דְּרָשָׁה, שֶׁתְּלוּיִים מִצַּד הָאֱמוּנָה. וַיִּכְרְתוּ מִשָּׁם זְמוֹרָה וְגוֹ', לוֹמְדִים מִשָּׁם רָאשֵׁי פְרָקִים, רָאשֵׁי דְבָרִים, אוֹתָם שֶׁבְּנֵי הָאֱמוּנָה שְׂמֵחִים בִּדְבָרִים, וּמִתְבָּרְכִים דְּבָרִים בְּתוֹכָם, וּמִסְתַּכְּלִים שֹׁרֶשׁ אֶחָד וְעִקָּר אֶחָד, וְלֹא נִמְצָא בָהֶם פֵּרוּד. אוֹתָם שֶׁלֹּא נִמְצָאִים בְּנֵי אֱמוּנָה וְלֹא לוֹמְדִים תּוֹרָה לִשְׁמָהּ, שָׂמִים אֶת הָאֱמוּנָה בְּפֵרוּד. זֶהוּ שֶׁכָּתוּב וַיִּשָּׂאֻהוּ בַמּוֹט בִּשְׁנָיִם, בְּפֵרוּד. מַהוּ בַמּוֹט? כְּמוֹ שֶׁנֶּאֱמַר (תהלים קכא) אַל יִתֵּן לַמּוֹט רַגְלֶךְ. וּמִן הָרִמֹּנִים וּמִן הַתְּאֵנִים, הַכֹּל שָׁוִים לִדְבָרִים אֵלֶּה לְצַד אַחֵר, לְצַד הַמִּינִים, לְצַד הַפֵּרוּד."],[4,"","זְהִוּ שֶׁכָּתוּב וַיָּשֻׁבוּ מִתּוּר הָאָרֶץ. וַיָּשֻׁבוּ, שָׁבִים לְצַד הָרָע וְשָׁבִים מִדֶּרֶךְ הָאֱמֶת. אוֹמְרִים, מָה אִכְפַּת לָנוּ? עַד הַיּוֹם לֹא רָאִינוּ טוֹב לָעוֹלָם. עָמַלְנוּ בָהּ, הַבַּיִת רֵיק, יָשַׁבְנוּ בְקָלוֹן בָּעָם, וּלְאוֹתוֹ עוֹלָם מִי יִזְכֶּה וּמִי יִכָּנֵס לְתוֹכוֹ? טוֹב לָנוּ שֶׁלֹּא טָרַחְנוּ כָּל זֶה. וַיְסַפְּרוּ לוֹ וַיֹּאמְרוּ וְגוֹ', הֲרֵי עָמַלְנוּ וְעָיַפְנוּ בִּשְׁבִיל לָדַעַת חֵלֶק אוֹתוֹ עוֹלָם. וְגַם זָבַת חָלָב וּדְבַשׁ הִיא, טוֹב הוּא אוֹתוֹ עוֹלָם עֶלְיוֹן, כְּמוֹ שֶׁיָּדַעְנוּ בַתּוֹרָה, אֲבָל מִי יָכוֹל לִזְכּוֹת בּוֹ?"],[5,"","אֶפֶס כִּי עַז הָעָם, תַּקִּיף הוּא, שֶׁלֹּא יַחֲשִׁיב כָּל הָעוֹלָם כְּלָל, מִשּׁוּם שֶׁיִּהְיֶה לוֹ עֹשֶׁר רַב לְהִשְׁתַּדֵּל בּוֹ, מִי הוּא שֶׁיִּזְכֶּה בָּהּ? וַדַּאי אֶפֶס כִּי עַז הָעָם הַיֹּשֵׁב בָּאָרֶץ. מִי שֶׁרוֹצֶה לִזְכּוֹת בָּהּ, צָרִיךְ לִהְיוֹת חָזָק בְּעֹשֶׁר, כְּמוֹ שֶׁנֶּאֱמַר (משלי יח) וְעָשִׁיר יַעֲנֶה עַזּוֹת. וְהֶעָרִים גְּדֹלֹת בְּצֻרוֹת, בָּתִּים מְלֵאִים כָּל טוֹב שֶׁלֹּא יֶחֶסְרוּ מֵהַכֹּל. וְעִם כָּל זֶה, וְגַם יְלִדֵי הָעֲנָק רָאִינוּ שָׁם, צָרִיךְ גּוּף חָזָק, גִּבּוֹר כַּאֲרִי. (שימצא שם תמיד) מִשּׁוּם שֶׁהִיא מַתֶּשֶׁת כֹּחוֹ שֶׁל אָדָם לְהִשְׁתַּדֵּל בְּאוֹתוֹ אִסּוּר וְהֶתֵּר, טָמֵא וְטָהוֹר, כָּשֵׁר וּפָסוּל. מִי יָכוֹל לִזְכּוֹת בָּהּ?"],[6,"","וְעוֹד, עֲמָלֵק יוֹשֵׁב בְּאֶרֶץ הַנֶּגֶב. אִם יֹאמַר אָדָם שֶׁאֲפִלּוּ שֶׁיִּזְכֶּה לְכָל זֶה, עֲמָלֵק יוֹשֵׁב בְּאֶרֶץ הַנֶּגֶב, הֲרֵי יֵצֶר הָרָע, הַקָּטֵגוֹר, מְקַטְרֵג עַל הָאָדָם, שֶׁנִּמְצָא תָמִיד בַּגּוּף. וְהַחִתִּי וְהָאֱמֹרִי וְגוֹ', כַּמָּה מְקַטְרְגִים נִמְצָאִים שָׁם, (כדי) שֶׁלֹּא יָכוֹל הָאָדָם לְהִכָּנֵס לְאוֹתוֹ עוֹלָם כְּלָל, מִי יִזְכֶּה בּוֹ וּמִי יִכָּנֵס לְתוֹכוֹ? בַּדְּבָרִים הַלָּלוּ (במדבר לב) וַיָּנִיאוּ אֶת לֵב בְּנֵי יִשְׂרָאֵל, מִשּׁוּם שֶׁהוֹצִיאוּ שֵׁם רַע עָלֶיהָ, כְּמוֹ שֶׁנֶּאֱמַר וַיֹּצִיאוּ דִּבַּת הָאָרֶץ."],[7,"","אוֹתָם בְּנֵי הָאֱמוּנָה מָה אוֹמְרִים? אִם חָפֵץ בָּנוּ ה' (וגו') וּנְתָנָהּ לָנוּ. כֵּיוָן שֶׁיִּשְׁתַּדֵּל אָדָם בִּרְצוֹן הַלֵּב לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, לֹא צָרִיךְ מִמֶּנּוּ אֶלָּא הַלֵּב, וְיִשְׁמְרוּ אוֹתוֹ רִשּׁוּם קָדוֹשׁ, שֶׁכָתוּב (ישעיה ס) וְעַמֵּךְ כֻּלָּם צַדִּיקִים לְעוֹלָם יִירְשׁוּ אָרֶץ."]]],[["אֲבָל, (במדבר י״ד:ט׳) אַךְ בַּיְיָ אַל תִּמְרוֹדוּ, בָּעֵי דְּלָא יִמְרְדוּן בְּאוֹרַיְיתָא, דְּאוֹרַיְיתָא לָא בָּעֵי עוּתְרָא, וְלָא מָאנֵי דְּכַסְפָּא וְדַהֲבָא. וְאַתֶּם אַל תִּירְאוּ אֶת עַם הָאָרֶץ, דְּהָא גּוּפָא תְּבִירָא, אִי יִשְׁתְּדַל בְּאוֹרַיְיתָא, יִשְׁכַּח אַסְוָותָא בְּכֹלָּא. הֲדָא הוּא דִכְתִיב, (משלי ג׳:ח׳) רִפְאוּת תְּהִי לְשָׁרֶךָ וְשִׁקּוּי לְעַצְמוֹתֶיךָ. וּכְתִיב (משלי ד׳:כ״ב-כ״ג) וּלְכָל בְּשָׂרוֹ מַרְפֵּא. וְכָל אִינּוּן מְקַטְרְגֵי, אִינּוּן מַכְרְזָאן וְאָמְרֵי, פַּנוּ אֲתָר לִפְלָנְיָּיא עַבְדָּא דְּמַלְכָּא.","בְּגִין כַּךְ אַל תִּירְאוּ, כִּי לַחְמֵנוּ הֵם, אִינּוּן בְּגַרְמַיְיהוּ מְזַמְּנָן מְזוֹנֵי בְּכָל יוֹמָא לְאִינּוּן דְּמִשְׁתַּדְּלֵי בְּאוֹרַיְיתָא. כְּמָה דְאַתְּ אָמֵר (מלכים א י״ז:ד׳) וְאֶת הָעוֹרְבִים צִוִּיתִי לְכַלְכֶּלְךָ. וּכְתִיב (מלכים א י״ז:ו׳) וְהָעוֹרְבִים מְבִיאִים לוֹ לֶחֶם וּבָשָׂר. סָר צִלָּם מֵעֲלֵיהֶם. מַאן צִלָּם. דָּא תּוּקְפָּא דְּדִינָא קַשְׁיָא. מַאי טַעֲמָא אַעְדֵּי. מִשּׁוּם דְּיְיָ אִתָּנוּ אַל תִּירָאוּם. כֹּלָּא אַעְדִּיאוּ בְּגִין אוֹרַיְיתָא. זַכָּאָה חוּלָקֵיהוֹן דְּאִינּוּן דְּמִשְׁתַּדְּלֵי בְּאוֹרַיְיתָא לִשְׁמָהּ, דְּהָא מִתְקַשְּׁרֵי בְּקוּדְשָׁא בְּרִיךְ הוּא מַמָּשׁ. וְאִקְרוּן אַחִים וְרֵעִים. הֲדָא הוּא דִכְתִיב, (תהילים קכ״ב:ח׳) לְמַעַן אַחַי וְרֵעָי אֲדַבְּרָה נָא שָׁלוֹם בָּךְ.","(במדבר י״ג:כ״ג) וַיָבֹאוּ עַד נַחַל אֶשְׁכּוֹל וְגוֹ'. רִבִּי אַבָּא אָמַר, כָּרְתוּ הַהוּא אֶשְׁכּוֹל, אָתוּ לְסַלְּקָא לֵיהּ לָא יָכִילוּ. אָתוּ לְנַטְלָא לֵיהּ, לָא יָכִילוּ. אָתוּ כָּלֵב וִיהוֹשֻׁעַ, נַטְלוּ לֵיהּ, וּסְלִיקוּ לֵיהּ, וְאִזְדְקַף עַל יְדַיְיהוּ. הֲדָא הוּא דִכְתִיב וַיִּשָּׂאוּהוּ בַמּוֹט בִּשְׁנָיִם. בִּשְׁנָיִם בְּאִינּוּן שְׁנַיִם יְחִידָן. זְמוֹרָה מַאי קָא בָּעָאן. אֶלָּא אֶשְׁכּוֹל הֲוָה תַּלְיָיא בֵּיהּ, וּבְעוֹד דְּהֲוָה מִתְחַבָּר בְּאַתְרֵיהּ, אִקְרֵי זְמוֹרָה. לְבָתַר קַרְיֵיה מוֹט, דִּכְתִּיב וַיִּשָּׂאוּהוּ בַמּוֹט. הַהוּא דְּאִשְׁתְּמוֹדַע. הַהוּא דְּכָרְתוּ.","מִכָּאן יָדְעוּ יְהוֹשֻׁעַ וְכָלֵב, דְּאִינּוּן אִתְחַזְיָין לְמֵיעַל לְאַרְעָא, וּלְמֶהֱוִי לוֹן בָּהּ חֻלָק וְאַחֲסָנָא. עַד דַּהֲווֹ אַתְיָין אַמְלְכוּ עָלַיְיהוּ כֻּלְּהוּ, קָאִים כָּלֵב בְּאִיבָּא, אָמַר אִיבָּא אִיבָּא, אִי בְּגִינָךְ אֲנָן מִתְקַטְלִין, מַה אֲנָן בְּחוּלָקָךְ. מִיַּד קָלִיל גַּרְמֵיהּ. וְיָהֲבוּ לוֹן.","רִבִּי אֶלְעָזָר אָמַר, לָא יָהֲבוּ לְאָחֳרִי, דְּהָא כְּתִיב וַיִּשָּׂאֻהוּ בַמּוֹט, וּכְתִיב בִּשְׁנָיִם, וּבְכֻלְּהוּ לָא הֲווֹ שְׁנַיִם כְּוָותַיְיהוּ. וּמִכָּאן אוֹלִיף יְהוֹשֻׁעַ לְבָתַר, דִּכְתִּיב, (יהושע ב׳:א׳) וַיִשְׁלַח יְהוֹשֻׁעַ בִּן נוּן מִן הַשִׁטִּים שְׁנַיִם אֲנָשִׁים מְרַגְּלִים. וְהָנֵי שְׁנַיִם הָא אוּקְמוּהָ קַדְמָאֵי. וְכַד מָטוּ לְגַבַּיְיהוּ דְּיִשְׂרָאֵל, יָהֲבוּ לוֹן, וְאִינּוּן אִשְׁתָּאֲרוּ, וְעַבְדּוּ גַּרְמַיְיהוּ שִׁירַיִים.","רִבִּי יִצְחָק אָמַר, כַּד הֲווֹ מָטָאן לְגַבַּיְיהוּ דְּאִינּוּן עֲנָקִים, הֲווֹ שַׁוְויָין הַהוּא חוּטְרָא דְּמֹשֶׁה קַמַּיְיהוּ, וְאִשְׁתְּזִיבוּ. וּמְנָלָן דְּהַהוּא חוּטְרָא יָהִיב לוֹן. הֲדָא הוּא דִכְתִיב, וַיֹּאמֶר אֲלֵיהֶם עַלוּ זֶה בַנֶּגֶב. כְּתִיב הָכָא עֲלוּ זֶה, וּכְתִיב הָתָם (שמות ד) וְאֶת הַמַּטֶּה הַזֶּה וְגוֹ', וּבְגִינֵיהּ אִשְׁתֵּזִיבוּ. דְּאִי תֵּימָא הָנֵי עֲנָקַיָּיא שַׁבְקֵי לוֹן. אֶלָּא אָתוּ לְנַסְבָּא לוֹן, וַהֲווּ שַׁוְויָין לְקָמַיְיהוּ הַהוּא חוּטְרָא, וּמִשְׁתֵּזְבֵי (ס\"א ומשתמטי) מִקַּמַּיְיהוּ. רִבִּי יְהוּדָה אָמַר, מָסוֹרֶת שְׁמָא קַדִּישָׁא מָסַר לוֹן מֹשֶׁה, וּבְגִינֵיהּ אִשְׁתֵּזִיבוּ מִנַּיְיהוּ.","רִבִּי חִיָּיא אָמַר, תְּלַת שְׁמָהָן אִקְרוּן, נְפִילִים. עֲנָקִים. רְפָאִים. וְכֻלְּהוּ אוֹרְכֵי יוֹמֵי. נְפִילִין אִקְרוּן בְּקַדְמִיתָא, לְבָתַר כַּד אִתְחַבְּרוּן בִּבְנַת בְּנֵי נָשָׁא, וְאוֹלִידוּ מִנַּיְיהוּ, אִקְרוּן עֲנָקִים. לְבָתַר דַּהֲווֹ אָזְלֵי וְשָׁטָאן בְּהַאי עָלְמָא, וּמִתְרַפְיָין מֵהַהוּא דִּלְעֵילָּא, אִקְרוּן רְפָאִים.","אָמַר רִבִּי יְהוּדָה, וְהָא כְּתִיב (איוב כ״ו:ה׳) הָרְפָאִים יְחוֹלָלוּ, (דברים ב׳:י״א) רְפָאִים יֵחָשְׁבוּ אַף הֵם כַּעֲנָקִים. אָמַר לֵיהּ, הָכִי הוּא, בְּגִין דַּעֲנָקִים אָתוּ מֵהַאי סִטְרָא וּמֵהַאי סִטְרָא, וְאִתְיָאֲשׁוּ יַתִּיר בְּאַרְעָא. כְּגַוְונָא דָּא רְפָאִים, וּמִנַּיְיהוּ נַפְקֵי, וַהֲווּ אוֹרְכֵי יוֹמֵי. וְכַד מִתְחַלְּשֵׁי אִתְחֲלָשׁ פַּלְגוּת גּוּפָא, וּפַלְגּוּת קָאִים. כֵּיוָון דְּפַלְגּוּת גּוּפָא הֲוָה מִית, הֲווֹ נַסְבֵּי עִשְׂבָּא מֵעִשְׂבֵּי בָּרָא וְשַׁדְיָין לְפוּמַיְיהוּ, וּמִיתוּ. וּבְגִין דְּאִינּוּן בָעָאן לְקָטְלָא גַּרְמַיְיהוּ, אִקְרוּן רְפָאִים. אָמַר רִבִּי יִצְחָק, שַׁדְיָין גַּרְמַיְיהוּ בְּיַמָּא רַבָּא, וְטַבְעָן וּמֵתִין. הֲדָא הוּא דִכְתִיב, (איוב כ״ו:ה׳) הָרְפָאִים יְחוֹלָלוּ מִתַּחַת מַיִם וְשׁוֹכְנֵיהֶם."],[[0,"אבל, אך בה׳ אל תמרודו:","אבל צריכים, שלא למרוד בתורה. כי התורה אינה צריכה עשירות, ולא כלי כסף וזהב. \u0003ואתם אל תיראו את עם הארץ,\u0004 כי גוף שבור אם יעסוק בתורה ימצא רפואה בכל. ז״ש, רפאות תהי לשרך ושקוי לעצמותיך. וכתוב, ולכל בשרו מרפא. וכל המקטרגים שיש על האדם, מתהפכים לו לעוזרים, והם מכריזים, פנו מקום לפלוני עבד המלך. דהיינו שמי שהוא לא יעכבו מלבא אל המלך לשמשו."],[1,"בגין כך אל וכו׳:","משום זה, \u0003אל תיראו כי לחמנו הם,\u0004 הם, המקטרגים בעצמם מזמינים מזון בכל יום לאלו שעוסקים בתורה. כש״א, ואת העורבים צויתי לכלכלך. וכתוב והעורבים מביאים לו לחם ובשר. ואע״פ שהעורבים הם עופות טמאים מסטרא אחרא היו מכלכלים אותו. \u0003סר צלם מעליהם,\u0004 מהו צלם. זהו תוקף דין הקשה שבהם, שסר ונתבטל. מהו הטעם שסר. משום שה׳ אתנו אל תיראום כל כחם נתבטל משום התורה. אשרי חלקם של אלו העוסקים בתורה לשמה, כי הם מתקשרים בהקב״ה ממש. ונקראים אחים ורעים. ז״ש למען אחי ורעי אדברה נא שלום בך."],[2,"ויבאו עד נחל אשכול וגו׳:","ר׳ אבא אמר, כרתו את האשכול, באו להעלות אותו עליהם ולא יכלו, באו להסיעו ממקומו ולא יכלו. באו יהושע וכלב, לקחו אותו והעלו אותו ונזדקף על ידיהם. ז״ש וישאוהו במוט בשנים. בשנים, פירושו בשני היחידים, שלא חטאו, שהם יהושע וכלב. שואל, זמורה, מה נצרך להם. ומשיב, אלא האשכול היה תלוי עליו, ובעוד שהיה מחובר במקומו, נקרא זמורה. אח״כ שכרתו אותו נקרא מוט. שכתוב, וישאוהו במוט, שפירושו אותו הנודע, דהיינו אותו שכרתו מן העץ."],[3,"מכאן ידעו יהושע וכו׳:","מכאן, שראו שהם יכלו לקחת האשכול והאחרים לא יכלו, ידעו יהושע וכלב, שהם ראוים להכנס לארץ, ושיהיה להם בה חלק ונחלה. בעוד שהיו הולכים המרגלים לקחו כולם עצה עליהם, על יהושע וכלב, שקנאו אותם על שיכלו לקחת האשכול. ולקחו עצה להרגם. קם כלב על הפרי, אמר פרי פרי, אם בשבילך אנו נהרגים, מה אנו בחלקך. מיד, האשכול הקל את עצמו, שיוכלו כולם לשאת אותו, ונתנו להם האשכול."],[4,"ר׳ אלעזר אמר וכו׳:","רא״א, לא נתנו האשכול לאחרים, שהרי כתוב, וישאוהו במוט, וכתוב, בשנים. שמשמע שנים המצוינים, ובכולם לא היו שנים כמוהם. ומכאן למד יהושע אחר כך לשלוח רק שנים מרגלים. שכתוב, וישלח יהושע בן נון מן השטים שנים אנשים מרגלים. ואלו שנים, כבר העמידו הראשונים (לעיל ספרא דצניעותא אות נ\"ד) וכשהגיעו יהושע וכלב אל ישראל נתנו את האשכול להם. והם נשארו, ולא אמרו בתחילה לישראל כלום, כי רק המרגלים אמרו, וזה פריה, כי עשו עצמם שירים."],[5,"ר׳ יצחק אמר וכו׳:","ר׳ יצחק אמר, כשהמרגלים הגיעו לאלו הענקים היו משימים מטה של משה לפניהם, ונצולו. ומאין לנו שנתן להם המטה. ז״ש, ויאמר אליהם עלו זה בנגב. כתוב כאן עלו \u0003זה\u0004 וכתוב שם ואת המטה ה \u0003זה\u0004 וגו׳ ולמדים גזירה שוה, זה זה. ובשביל המטה נצולו. כי אם תאמר שהענקים עזבו אותם, לא כן, אלא באו לתפוש אותם, והיו שמים לפניהם את המטה, ונצולו מהם. ר׳ יהודה אמר מסורת שם הקדוש מסר להם משה, ובשבילו נצולו מהם."],[6,"רבי חייא אמר וכו׳:","רח״א, ג׳ שמות נקראו, נפילים, ענקים, רפאים. וכולם האריכו ימים. \u0003נפילים\u0004 נקראו תחילה בעת שהפילו אותם משמים, ואחר שנתחברו בבנות האדם, והולידו מהם נקראו הבנים \u0003ענקים.\u0004 ואח״כ שהיו הולכים ומשוטטים בעולם הזה, \u0003והרפו\u0004 עצמם מן העולם שלמעלה, נקראו \u0003רפאים.\u0004"],[7,"אמר ר׳ יהודה וכו׳:","אר״י והרי כתוב הרפאים יחוללו. רפאים יחשבו אף הם כענקים. ואתה אומר שרפאים הוא לשון רפיון. אמר לו ר״ח, כך הוא. משום שענקים באו מצד זה ומצד זה, דהיינו מצד המלאכים ומצד בנות האדם. ונעשו מיואשים יותר להיות בארץ. כעין זה הרפאים שיצאו ונולדו מן הענקים, נתיאשו עוד יותר עד שהרפו את עצמם לגמרי מלמעלה. והיו מאריכים ימים. וכשנחלשו, נחלש ומת מחצית גופם, וחצי הגוף עמד חי, מחמת שהיו חצים ממלאכים שאינם מתים וחצים מבני אדם שמתים. כיון שחצי גופם היה מת, היו לוקחים עשבי מעשבי השדה, דהיינו סם המות, ושמו לפיהם, ומתו. ומשום שהם רוצים להרוג את עצמם, נקראים רפאים. על שם שמרפים את עצמם מן החיים. א״ר יצחק היו משליכים עצמם בים הגדול ונטבעו ומתו. ז״ש הרפאים יחוללו מתחת מים ושוכניהם."]],[[0,"","אֲבָל, אַךְ בַּה' אַל תִּמְרֹדוּ. צָרִיךְ שֶׁלֹּא תִמְרְדוּ בַתּוֹרָה, שֶׁהַתּוֹרָה לֹא צְרִיכָה עֹשֶׁר וְלֹא כְּלֵי כֶסֶף וְזָהָב. וְאַתֶּם אַל תִּירְאוּ אֶת עַם הָאָרֶץ, שֶׁהֲרֵי גּוּף שָׁבוּר, אִם יִשְׁתַּדֵּל בַּתּוֹרָה, יִמְצָא רְפוּאָה בַּכֹּל. זֶהוּ שֶׁכָּתוּב (משלי ג) רִפְאוּת תְּהִי לְשָׁרֶךְ וְשִׁקּוּי לְעַצְמוֹתֶיךְ. וְכָתוּב (שם ד) וּלְכָל בְּשָׂרוֹ מַרְפֵּא. וְכָל אוֹתָם מְקַטְרְגִים מַכְרִיזִים וְאוֹמְרִים: פַּנּוּ מָקוֹם לִפְלוֹנִי עֶבֶד הַמֶּלֶךְ!"],[1,"","בִּגְלַל זֶה אַל תִּירְאוּ, כִּי לַחְמֵנוּ הֵם. הֵם בְּעַצְמָם מְזַמְּנִים מְזוֹנוֹת בְּכָל יוֹם לְכָל אוֹתָם שֶׁמִּשְׁתַּדְּלִים בַּתּוֹרָה, כְּמוֹ שֶׁנֶּאֱמַר (מלכים א יז) וְאֶת הָעֹרְבִים צִוִּיתִי לְכַלְכֶּלְךְ, וְכָתוּב (שם) וְהָעוֹרְבִים מְבִיאִים לוֹ לֶחֶם וּבָשָׂר. סָר צִלָּם מֵעֲלֵיהֶם. מַהוּ צִלָּם? זֶה תֹקֶף הַדִּין הַקָּשֶׁה. מָה הַטַּעַם סָר? מִשּׁוּם שֶׁה' אִתָּנוּ אַל תִּירָאֻם. הַכֹּל זָז בִּגְלַל הַתּוֹרָה. אַשְׁרֵי חֵלֶק אוֹתָם שֶׁמִּשְׁתַּדְּלִים בַּתּוֹרָה לִשְׁמָהּ, שֶׁהֲרֵי מִתְקַשְּׁרִים בַּקָּדוֹשׁ-בָּרוּךְ-הוּא מַמָּשׁ, וְנִקְרָאִים אַחִים וְרֵעִים. זֶהוּ שֶׁכָּתוּב (תהלים קכב) לְמַעַן אַחַי וְרֵעָי אֲדַבְּרָה נָּא שָׁלוֹם בָּךְ."],[2,"","וַיָּבֹאוּ עַד נַחַל אֶשְׁכּוֹל וְגוֹ'. רַבִּי אַבָּא אָמַר, כָּרְתוּ אוֹתוֹ אֶשְׁכּוֹל, בָּאוּ לַהֲרִימוֹ, לֹא יָכְלוּ. בָּאוּ לְקַחְתּוֹ, לֹא יָכְלוּ. בָּאוּ כָלֵב וִיהוֹשֻׁעַ וּלְקָחוּהוּ וְהֶעֱלוּהוּ, וְעָלָה עַל יָדָם. זֶהוּ שֶׁכָּתוּב וַיִּשָּׂאֻהוּ בַמּוֹט בִּשְׁנָיִם. בִּשְׁנָיִם, בְּאוֹתָם שְׁנַיִם יְחִידִים. זְמוֹרָה מָה רָצוּ? אֶלָּא אֶשְׁכּוֹל הָיָה תָלוּי בָּהּ, וּבְעוֹד שֶׁהָיָה מְחֻבָּר בִּמְקוֹמוֹ, נִקְרָא זְמוֹרָה. אַחַר כָּךְ קְרָאוֹ מוֹט, שֶׁכָּתוּב וַיִּשָּׂאֻהוּ בַמּוֹט, אוֹתוֹ הַנּוֹדָע, אוֹתוֹ שֶׁכָּרְתוּ."],[3,"","מִכָּאן יָדְעוּ יְהוֹשֻׁעַ וְכָלֵב שֶׁהֵם רְאוּיִם לְהִכָּנֵס לָאָרֶץ וְלִהְיוֹת לָהֶם בָּהּ חֵלֶק וְנַחֲלָה. עַד שֶׁבָּאוּ, נִמְלְכוּ עֲלֵיהֶם כֻּלָּם. עָמַד כָּלֵב בִּפְרִי, אָמַר: פְּרִי פְּרִי, אִם בִּגְלָלְךְ אָנוּ נֶהֱרָגִים, מָה אָנוּ בְחֶלְקְךְ? מִיָּד עָשָׂה עַצְמוֹ קַל וְנִתַּן לָהֶם."],[4,"","רַבִּי אֶלְעָזָר אָמַר, לֹא נָתְנוּ לָאֲחֵרִים, שֶׁהֲרֵי כָּתוּב וַיִּשָּׂאֻהוּ בַמּוֹט, וְכָתוּב בִּשְׁנָיִם, וּבְכֻלָּם לֹא הָיוּ שְׁנַיִם כְּמוֹתָם. וּמִכָּאן לָמַד יְהוֹשֻׁעַ אַחַר כָּךְ, שֶׁכָּתוּב (יהושע ב) וַיִּשְׁלַח יְהוֹשֻׁעַ בִּן נוּן מִן הַשִּׁטִּים שְׁנַיִם אֲנָשִׁים מְרַגְּלִים. וּשְׁנַיִם אֵלֶּה הֲרֵי פֵּרְשׁוּהָ הַקַּדְמוֹנִים. וּכְשֶׁהִגִּיעוּ אֶל יִשְׂרָאֵל, נָתְנוּ לָהֶם, וְהֵם נִשְׁאֲרוּ וְעָשׂוּ עַצְמָם כְּשִׁירַיִם."],[5,"","רַבִּי יִצְחָק אָמַר, כְּשֶׁהָיוּ מַגִּיעִים לְאוֹתָם עֲנָקִים, הָיוּ שָׂמִים אוֹתוֹ מַטֶּה שֶׁל מֹשֶׁה לִפְנֵיהֶם, וְנִצְּלוּ. וּמִנַּיִן לָנוּ שֶׁאוֹתוֹ מַטֶּה נָתַן לָהֶם? זֶהוּ שֶׁכָּתוּב וַיֹּאמֶר אֲלֵהֶם עֲלוּ זֶה בַּנֶּגֶב. כָּתוּב כָּאן עֲלוּ זֶה, וְכָתוּב שָׁם (שמות ד) וְאֶת הַמַּטֶּה הַזֶּה וְגוֹ', וּבִגְלָלוֹ נִצְּלוּ. שֶׁאִם תֹּאמַר שֶׁהָעֲנָקִים הַלָּלוּ עָזְבוּ אוֹתָם? אֶלָּא בָּאוּ לְקַחְתָּם, וְהָיוּ שָׂמִים מוּלָם אוֹתוֹ מַטֶּה, וְנִצּוֹלִים (ובורחים) מִלִּפְנֵיהֶם. רַבִּי יְהוּדָה אָמַר, מָסֹרֶת שֵׁם הַקָּדוֹשׁ מָסַר לָהֶם מֹשֶׁה, וּבִגְלָלוֹ נִצְּלוּ מֵהֶם."],[6,"","רַבִּי חִיָּיא אָמַר, שְׁלֹשָׁה שֵׁמוֹת נִקְרְאוּ: נְפִילִים, עֲנָקִים, רְפָאִים. וְכֻלָּם הֶאֱרִיכוּ יָמִים. נְפִילִים נִקְרְאוּ בַתְּחִלָּה. אַחַר כָּךְ כְּשֶׁהִתְחַבְּרוּ בִּבְנוֹת בְּנֵי הָאָדָם וְהוֹלִידוּ מֵהֶם, נִקְרְאוּ עֲנָקִים. אַחַר כָּךְ שֶׁהָיוּ הוֹלְכִים וּמְשׁוֹטְטִים בָּעוֹלָם הַזֶּה וּמִתְרַפִּים מֵאוֹתוֹ שֶׁלְּמַעְלָה, נִקְרְאוּ רְפָאִים."],[7,"","אָמַר רַבִּי יְהוּדָה, וַהֲרֵי כָּתוּב (איוב כו) הָרְפָאִים יְחוֹלָלוּ, (דברים ב) רְפָאִים יֵחָשְׁבוּ אַף הֵם כַּעֲנָקִים. אָמַר לוֹ, כָּךְ הוּא, מִשּׁוּם שֶׁעֲנָקִים בָּאוּ מִצַּד זֶה וּמִצַּד זֶה וְהִתְחַזְּקוּ יוֹתֵר בָּאָרֶץ. כְּמוֹ זֶה רְפָאִים, וּמֵהֶם יָצְאוּ, וְהָיוּ מַאֲרִיכִים יָמִים. וּכְשֶׁנֶּחֱלָשִׁים, נֶחֱלָשׁ חֲצִי גוּף, וַחֲצִי עוֹמֵד. כֵּיוָן שֶׁחֲצִי הַגּוּף הָיָה מֵת, הָיוּ לוֹקְחִים עֵשֶׂב מֵעִשְׂבֵי הַשָּׂדֶה וְזוֹרְקִים לְפִיהֶם וּמֵתִים. וּמִשּׁוּם שֶׁהֵם רָצוּ לַהֲרֹג עַצְמָם, נִקְרְאוּ רְפָאִים. אָמַר רַבִּי יִצְחָק, זוֹרְקִים עַצְמָם לַיָּם הַגָּדוֹל, וְטוֹבְעִים וּמֵתִים. זֶהוּ שֶׁכָּתוּב הָרְפָאִים יְחוֹלָלוּ מִתַּחַת מַיִם וְשֹׁכְנֵיהֶם."]]],[["רִבִּי שִׁמְעוֹן אָמַר, אִלְמָלֵא הֲווֹ עַיְילִין יִשְׂרָאֵל לְאַרְעָא, בְּסִימָנָא (נ\"א באומנא) דְּלִישָׁנָא בִּישָׁא, לָא הֲוָה קָאִים עָלְמָא רִגְעָא חַד. מַאן אוּמָנָא דְּלִישָׁנָא בִּישָׁא, נָחָשׁ. וְרָזָא דְּמִלָּה, מִדְּאָתָא נָחָשׁ עַל חַוָּה אַטִּיל בָּהּ זוּהֲמָא. אָמַר רִבִּי שִׁמְעוֹן, וְעַל כֹּלָּא מָחַל קוּדְשָׁא בְּרִיךְ הוּא, בַּר מִן לִישָׁנָא בִּישָׁא. בְּגִין דִּכְתִּיב, (תהילים י״ב:ה׳) אֲשֶׁר אָמְרוּ לִלְשׁוֹנֵנוּ נַגְבִּיר שְׂפָתֵינוּ אִתָּנוּ מִי אָדוֹן לָנוּ.","תָּא חֲזֵי, כַּמָּה עָבֵד הַהוּא לִישָׁנָא בִּישָׁא, גָּזַר עַל אֲבְהֲתָנָא דְּלָא יֵיעוּל לְאַרְעָא וּמִיתוּ אִינּוּן דְּאָמְרוּ. וְאִתְגְּזַר בִּכְיָה לְדָרֵי דָּרִין. (כל שכן הכא דאפיקו לישנא בישא על כלא) כִּבְיָכוֹל כֵּיוָן דְּאַפִּיקוּ עַל אַרְעָא קַדִּישָׁא, כְּאִילּוּ אַפִּיקוּ עָלֵיהּ. בְּגִין כַּךְ קַנֵּי קוּדְשָׁא בְּרִיךְ הוּא עַל דָּא, (כלומר קני לשמיה) וְקָאִימוּ יִשְׂרָאֵל כֻּלְּהוּ לְאִשְׁתֵּצָאָה מֵעָלְמָא, אִלְמָלֵא בָּעוּתֵיהּ דְּמֹשֶׁה.","(במדבר י״ג:כ״ז) וַיְסַפְּרוּ לוֹ וַיֹּאמְרוּ וְגוֹ'. אָמַר רִבִּי חִיָּיא, מַאי שְׁנָא הָכָא וַיְסַפְּרוּ, וְלָא כְּתִיב וַיַּגִּידוּ, אוֹ וַיֹּאמְרוּ. אֶלָּא כָּל חַד אוֹלִיף מִלָּה בִּלְחוֹדוֹי. וַיַּגִּידוּ, בְּכָל אֲתָר רֶמֶז קָא רָמִיז בְּחָכְמְתָא, וְהָא אִתְּמַר. וַיֹּאמֶר, אֲמִירָה בְּעָלְמָא. וַיֹּאמְרוּ, הִרְהוּרָא דְּלִבָּא. וַיֹּאמְרוּ, תַּפְקִידְתָּא. וְהָא אוֹקִימְנָא בְּכַמָּה אֲתָר. וַיְסַפְּרוּ, פְּרִישׁוּתָא דְּמִלָּה בְּכָל אֲתָר.","בָּאנוּ אֶל הָאָרֶץ, הָלַכְנוּ מִבָּעֵי לֵיהּ. אֶלָּא בָּאנוּ, עָאלָנָא לְתַמָן לְהַהִיא אַרְעָא דַּהֲוִית מְשַׁבַּח בְּכָל יוֹמָא, וַהֲוִית אַמָרְתּ דְּלֵית דִּכְוָותָה. וְגַם זָבַת חָלָב וּדְבַשׁ הִיא. רִבִּי יִצְחָק אָמַר, מַאן דְּבָעֵי לְמֵימַר כְּדִיבָא, אָמַר מִלָּה דִּקְשׁוֹט בְּקַדְמִיתָא, בְּגִין דִּיְּהֶמְנוּ לֵיהּ כְּדִבוֹי.","רִבִּי חִיָּיא אָמַר, (אלא) הָכִי אָמְרוּ, עָאלָנָא לְהַהִיא אַרְעָא דַּהֲוִית מְשַׁבַּח לָהּ כָּל יוֹמָא וְאַמָרַת דְּלֵית דִּכְוָותָה, (וגם זבת חלב ודבש היא), וַאֲרִימַת שְׁבָחָא עַל כֹּלָּא. וְלָאו הָכִי, דְּהָא זֶה פִּרְיָה, אַתְכְּלָא חַד מֵאִינּוּן זְעִירִין קַטְפוּ. אָמְרוּ, אִי לְדָא אַחֲסִין קוּדְשָׁא בְּרִיךְ הוּא לְיִשְׂרָאֵל, וְסַבְלוּ כָּל אִינּוּן עַקְתִּין וְלֵיאוּתִין, הָא בְּאַרְעָא דְּמִצְרַיִם אִית אַתְכְּלִין וְאֵיבִין דְּאַרְעָא יַתִּיר, עַל חַד תְּרֵין.","(במדבר י״ג:כ״ח) אֶפֶס כִּי עַז הָעָם, אוֹרְחֵיהּ דְּעָלְמָא דְּאִינּוּן גִּבָּרִין מַגִּיחֵי קְרָבָא יַתְבִין לְבַר, לְאִסְתַּמְּרָא אָרְחִין. וְהָכָא אֲפִילוּ אִינּוּן בְּנֵי מָתָא, תַּקִּיפִן גִּבּוֹרִין. וְהֶעָרִים בְּצוּרוֹת, דְּאֲפִילּוּ כָּל מַלְכִין דְּעָלְמָא יִתְכָּנְּשׁוּ עָלַיְיהוּ. לָא יַעַבְדּוּן בְּהוּ פְּגִימוּתָא. אָמַר רִבִּי יוֹסֵי, כָּל מַה דְּאַמְרֵי, בְּלִישָׁנָא בִּישָׁא אָמְרוּ, וְקַשְׁיָא מְכֻּלְּהוּ, דִּכְתִּיב עֲמָלֵק יוֹשֵׁב בְּאֶרֶץ הַנֶּגֶב. לְבַר נָשׁ דִּנְשָׁכֵיהּ חִוְיָא, כַּד בָּעָאן לְאַגְזְמָא לֵיהּ, אַמְרֵי הָא חִוְיָא הָכָא.","רִבִּי אַבָּא אָמַר, ודַּאי דָּא קַשְׁיָא מִכָּל מַה דְּאָמְרֵי, כְּלוֹמַר, הַהוּא דְּאַגָּח קְרָבָא בְּכֹלָּא, הָא הָכָא זַמִּין. וּבְאָן אֲתָר. בְּאֶרֶץ הַנֶּגֶב, דְּהָא הוּא אֲתָר לְאַעְלָאָה בֵּיהּ. מִיַּד וַתִּשָּׂא כָּל הָעֵדָה וַיִּתְּנוּ אֶת קוֹלָם. קְבִיעוּ בִּכְיָה לַדּוֹרוֹת, לְעָלְמִין, בְּהַהוּא לֵילְיָא.","אָמַר רִבִּי יוֹסֵי, עֵיטָא נָסִיבוּ עַל כֹּלָּא, לְאַפָּקָא שׁוּם בִּישׁ. מַאי עַל כֹּלָּא. עַל אַרְעָא, וְעַל קוּדְשָׁא בְּרִיךְ הוּא. אָמַר רִבִּי יִצְחָק, עַל אַרְעָא תִּינַח. עַל קוּדְשָׁא בְּרִיךְ הוּא מִנַיִן. אָמַר לֵיהּ מַשְׁמַע דִּכְתִּיב, אֶפֶס כִּי עַז הָעָם. מַאן יָכִיל בְּהוּ. כִּי עַז הָעָם דַּיְיקָא. וּכְתִיב עֲמָלֵק יוֹשֵׁב בְּאֶרֶץ הַנֶּגֶב, כְּדֵין גָּרְמוּ כָּל הַאי, כְּמָה דְּאִתְּמַר. וּבָעָא קוּדְשָׁא בְּרִיךְ הוּא לְשֵׁיצָאָה לוֹן מִן עָלְמָא, הֲדָא הוּא דִכְתִיב, (תהילים ק״ו:כ״ג) וַיֹּאמֶר לְהַשְׁמִידָם לוּלֵי מֹשֶׁה בְחִירוֹ עָמַד בַּפֶּרֶץ לְפָנָיו וְגוֹ'.","(במדבר י״ד:י״ז) וְעַתָּה יִגְדַּל נָא כֹּחַ יְיָ. רִבִּי אֲחָא וְרִבִּי יוֹסֵי אַמְרֵי, זַכָּאי אִינּוּן יִשְׂרָאֵל מֵעַמִּין עוֹבְדֵי כּוֹכָבִים וּמַזָּלוֹת דְּעָלְמָא. דְקוּדְשָׁא בְּרִיךְ הוּא אִתְרְעֵי בְּהוּ, וְאִתְכְּנֵי בְּהוּ, וְאִתְפָּאַר בְּהוּ, דְּהָא עָלְמָא לָא אִבְרֵי אֶלָּא בְּגִינֵיהוֹן דְּיִשְׂרָאֵל, דְּיִשְׁתַּדְּלוּן בְּאוֹרַיְיתָא, בְּגִין דְּחַד בְּחַד אִתְקַשְׁרָן. וְיִשְׂרָאֵל לְתַתָּא בְּהַאי עָלְמָא, אִינּוּן קִיּוּמָא דִּילֵיהּ, וְקִיּוּמָא דְּכָל שְׁאַר עַמִּין, אֵימָתַי בִּזְמַן דְּעַבְדֵי רְעוּתָא דְּמָארֵיהוֹן.","תָּא חֲזֵי, כַּד בָּרָא קוּדְשָׁא בְּרִיךְ הוּא בַּר נָשׁ בְּעָלְמָא, אַתְקִין לֵיהּ כְּגַוְונָא עִלָּאָה (יקירא), וְיָהַב לֵיהּ חֵילֵיהּ וְתוּקְפֵּיהּ בְּאֶמְצָעִיתָא דְּגוּפָא, דְּתַמָּן שַׁרְיָא לִבָּא. דְּהוּא (מזונא) תּוּקְפָּא דְּכָל גּוּפָא, וּמִתַּמָּן אִתְּזָן כָּל גּוּפָא. (וכל אינון שייפי דגופא מתמן אתזנו) וְהָא לִבָּא אָחִיד וְאִתָּקַף בַּאֲתָר עִלָּאָה דִּלְעֵילָּא. דְּאִיהוּ מוֹחָא דְּרֵישָׁא, דְּשָׁארִי לְעֵילָּא (ואחיד ביה), וְדָא אִתְקְשַׁר בְּדָא."],[[0,"ר׳ שמעון אמר וכו׳:","רש\"א, אם היו ישראל נכנסים לארץ תחת סימן לשון הרע של המרגלים, לא היה עומד העולם אפילו רגע אחד. מי הוא האומן של לשון הרע, דהיינו השורש שלו, נחש. סוד הדבר הוא כשבא נחש על חוה, דהיינו החטא של עץ הדעת, הטיל בה זוהמא דהיינו הטומאה שלו, שכל החטאים של בני אדם באים מזוהמא הזו, אמר ר׳ שמעון, ועל כולם מחל הקב״ה, חוץ מלשון הרע. כי כתוב, אשר אמרו ללשוננו נגביר שפתינו אתנו מי אדון לנו."],[1,"ת״ח כמה עבד וכו׳:","בוא וראה, מה עשה לשון הרע ההוא של המרגלים, שגזר על אבותנו שלא יכנסו לארץ. ואלו שאמרו לשון הרע מתו. ונגזר בכיה לדורי דורות, שבאותו יום נחרבו ב׳ המקדשים. כביכול, כיון שהוציאו לשון הרע על ארץ הקדושה, הוא כאלו הוציאו עליו, משום זה קנא הקב״ה על זה, ועמדו ישראל להתכלות מן העולם, לולא תפלתו של משה."],[2,"ויספרו לו ויאמרו וגו׳:","א״ר חייא מה השינוי כאן, שכתוב, ויספרו, ולא כתוב, ויגידו או ויאמרו. ומשיב, אלא כל אחד פירש הדבר בפני עצמו. ויגידו. בכל מקום שכתוב ויגידו, רמז מרמז בחכמה. וכבר למדנו. ויאמר, היינו אמירה בלבד. ויאמרו, פירושו הרהור הלב. ע״ד שכתוב ויאמר המן בלבו. ויאמרו פירושו נתינת פקודה. וכבר העמדנו בכמה מקומות. ויספרו, פירושו בכל מקום, פרשת הדברים. שכל אחד ואחד פירש הדברים."],[3,"באנו אל הארץ:","שואל, הלכנו אל הארץ היה צריך לומר. ומשיב, אלא באנו, פירושו, נכנסנו שמה בארץ ההיא שהיית משבח בכל יום, והיית אומר שאין כמוה. \u0003וגם זבת חלב ודבש היא.\u0004 ר׳ יצחק אמר מי שרוצה לומר שקר, אומר בתחילה דבר אמת, כדי שיאמינו לו כזביו. וע״כ אמרו תחילה, וגם זבת חלב ודבש היא."],[4,"ר׳ חייא אמר וכו׳:","רח״א, כך אמרו, באנו אל הארץ שהיית משבחה בכל יום, ואמרת, שאין כמוה וגם זבת חלב ודבש היא, והרימות שבחה על כל הארצות. ואינו כן, כי \u0003זה פריה,\u0004 כי אשכול אחד מן הקטנים כרתו, והראו להם. אמרו, אם ארץ זו מנחיל הקב״ה לישראל, וסבלו עליה כל אלו הצרות והיגיעות, הרי בארץ מצרים יש אשכולות ופירות הארץ החשובים מהם פי שנים."],[5,"אפם כי עז העם:","אמרו, כי מדרך העולם הוא שהגבורים עורכי מלחמה יושבים מחוץ לערים, לשמור הדרכים. וכאן אפילו יושבי העיר הם חזקים, גבורים. \u0003והערים בצורות,\u0004 שאפילו כל מלכי העולם יתאספו עליהם, לא יוכלו לעשות בהם משהו קלקול. א״ר יוסי, כל מה שאמרו בלשון הרע אמרו, והקשה מכולם הוא שכתוב, עמלק יושב בארץ הנגב. בדומה לאדם שנשכו נחש, כשרוצים לאיים עליו, אומרים לו, הרי נחש כאן."],[6,"ר׳ אבא אמר וכו׳:","רא\"א, ודאי זה קשה מכל מה שאמרו. כלומר, שאמרו, אותו העורך מלחמה עם הכל, הנה נמצא כאן, ובאיזה מקום. בארץ הנגב, שהוא המקום, שדרך שם נכנסים לארץ. מיד, ותשא כל העדה ויתנו את קולם. שקבעו בכיה לדורות לעולם באותו לילה, שהיה ליל תשעה באב, שבו נחרבו ב׳ המקדשים."],[7,"א״ר יוסי עיטא וכו׳:","אר״י, עצה לקחו לעצמם, להוציא שם רע על הכל. מהו על הכל. היינו על הארץ ועל הקב״ה. א״ר יצחק, על הארץ, נכון הוא, על הקב״ה, מאין לנו. אמר לו, זה משמע משכתוב, אפס כי עז העם. שפירושו מי יכול להם. כי עז העם, הוא בדיוק, כלומר, שאפילו הקב״ה לא יוכל להם. והוציאו שם רע על הקב״ה. וכתוב עמלק יושב בארץ הנגב. אז גרמו כל זה כמו שלמדנו, ורצה הקב״ה לכלותם מן העולם. ז״ש, ויאמר להשמידם לולי משה בחירו עמד בפרץ לפניו וגו'."],[8,"ועתה יגדל נא כח ה׳:","ר׳ אחא ור' יוסי אומרים, אשרי הם ישראל מכל העמים שבעולם, שהקב״ה רצה בהם, וקרא שמו בהם, והתפאר בהם, כי העולם לא נברא אלא בשביל ישראל שיעסקו בתורה. משום שאחד באחד מתקשר, דהיינו ז״א ומלכות, וישראל למטה בעולם הזה הם הקיום שלו, שע״י מעשיהם הטובים מעלים מ״ן לזווגם. והם קיום כל שאר העמים. דהיינו שבשביל ישראל מתקיימים. מתי זה. היינו בזמן שעושים רצונו של אדונם."],[9,"ת״ח כד ברא וכו׳:","בוא וראה כשברא הקב״ה את האדם בעולם, תקן אותו כעין של מעלה, ונתן כחו ותוקפו באמצע גופו, ששם שורה הלב, שהוא תוקף כל הגוף, ומשם נזון כל הגוף. והלב מתאחז ומתחזק במקום עליון שלמעלה, שהוא במוח שבראש השורה למעלה, וזה נקשר בזה."]],[[0,"","רַבִּי שִׁמְעוֹן אָמַר, אִלְמָלֵא הָיוּ נִכְנָסִים יִשְׂרָאֵל לָאָרֶץ בְּסִימַן (באמנות) לָשׁוֹן הָרָע, לֹא הָיָה הָעוֹלָם עוֹמֵד אֲפִלּוּ רֶגַע אֶחָד. מִי אֻמָּן שֶׁל לָשׁוֹן הָרָע? הַנָּחָשׁ. וְסוֹד הַדָּבָר - מִשֶּׁבָּא הַנָּחָשׁ עַל חַוָּה הִטִּיל בָּהּ זֻהֲמָה. אָמַר רַבִּי שִׁמְעוֹן, וְעַל הַכֹּל מוֹחֵל הַקָּדוֹשׁ בָּרוּךְ הוּא, פְּרָט לְלָשׁוֹן הָרָע, מִשּׁוּם שֶׁכָּתוּב (תהלים יב) אֲשֶׁר אָמְרוּ לִלְשֹׁנֵנוּ נַגְבִּיר שְׂפָתֵינוּ אִתָּנוּ מִי אָדוֹן לָנוּ."],[1,"","בֹּא וּרְאֵה כַּמָּה עָשָׂה אוֹתוֹ לָשׁוֹן הָרָע; גָּזַר עַל אֲבוֹתֵינוּ שֶׁלֹּא יִכָּנְסוּ לָאָרֶץ, וּמֵתוּ אֵלֶּה שֶׁאָמְרוּ, וְנִגְזְרָה בְכִיָּה לְדוֹרֵי דוֹרוֹת. (כל שכן כאן שהוציא לשון הרע על הכל) כִּבְיָכוֹל כֵּיוָן שֶׁהוֹצִיאוּ עַל הָאָרֶץ הַקְּדוֹשָׁה, כְּאִלּוּ הוֹצִיאוּ עָלָיו. בִּגְלַל זֶה קִנֵּא הַקָּדוֹשׁ בָּרוּךְ הוּא עַל זֶה, (כלומר קנא לשמו) וְעָמְדוּ יִשְׂרָאֵל כֻּלָּם לְהִשָּׁמֵד מֵהָעוֹלָם אִלְמָלֵא תְפִלַּת מֹשֶׁה."],[2,"","וַיְסַפְּרוּ לוֹ וַיֹּאמְרוּ וְגוּ'. אָמַר רַבִּי חִיָּיא, מַה שּׁוֹנֶה כָּאן וַיְסַפְּרוּ, וְלֹא כָתוּב וַיַּגִּידוּ אוֹ וַיֹּאמְרוּ? אֶלָּא כָּל אֶחָד מְלַמֵּד דָּבָר לְבַדּוֹ. וַיַּגִּידוּ - בְּכָל מָקוֹם רֶמֶז הוּא רוֹמֵז בְּחָכְמָה, וַהֲרֵי נִתְבָּאֵר. וַיֹּאמֶר - אֲמִירָה בְּעָלְמָא. וַיֹּאמְרוּ - הִרְהוּר הַלֵּב. וַיֹּאמְרוּ - פְּקֻדָּה. וַהֲרֵי בֵּאַרְנוּ בְּכַמָּה מְקוֹמוֹת. וַיְסַפְּרוּ - פֵּרוּשׁ הַדָּבָר בְּכָל מָקוֹם."],[3,"","בָּאנוּ אֶל הָאָרֶץ. הָלַכְנוּ הָיָה צָרִיךְ לוֹ לִהְיוֹת! אֶלָּא בָּאנוּ, נִכְנַסְנוּ לְשָׁם לְאוֹתָהּ אֶרֶץ שֶׁהָיִיתָ מְשַׁבְּחָהּ בְּכָל יוֹם וְהָיִיתָ אוֹמֵר שֶׁאֵין כְּמוֹתָהּ, וְגַם זָבַת חָלָב וּדְבַשׁ הִיא. רַבִּי יִצְחָק אָמַר, מִי שֶׁרוֹצֶה לוֹמַר כָּזָב, אוֹמֵר דְּבַר אֱמֶת בַּהַתְחָלָה, כְּדֵי שֶׁיַּאֲמִינוּ לוֹ כְּזָבָיו."],[4,"","רַבִּי חִיָּיא אָמַר, (אלא) כָּךְ אָמְרוּ: נִכְנַסְנוּ לְאוֹתָהּ אֶרֶץ שֶׁהָיִיתָ מְשַׁבְּחָהּ כָּל יוֹם וְאָמַרְתָּ שֶׁאֵין כָּמוֹהָ, (וגם זבת חלב ודבש היא), וְהֵרַמְתָּ שִׁבְחָהּ עַל הַכֹּל - וְלֹא כָּךְ, שֶׁהֲרֵי זֶה פִּרְיָהּ, אֶשְׁכּוֹל אֶחָד מֵאוֹתָם קְטַנִּים קָטְפוּ. אָמְרוּ: אִם לָזֶה הוֹרִישׁ הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת יִשְׂרָאֵל וְסָבְלוּ כָּל אוֹתָן צָרוֹת וַעֲיֵפוּת, הֲרֵי בְּאֶרֶץ מִצְרַיִם יֵשׁ אֶשְׁכּוֹלוֹת וּפֵרוֹת הָאָרֶץ יוֹתֵר, עַל אֶחָד שְׁנַיִם."],[5,"","אֶפֶס כִּי עַז הָעָם. דֶּרֶךְ הָעוֹלָם שֶׁאוֹתָם גִּבּוֹרִים עוֹרְכֵי הַקְּרָב יוֹשְׁבִים בַּחוּץ לִשְׁמֹר הַדְּרָכִים, וְכָאן אֲפִלּוּ אוֹתָם בְּנֵי הָעִיר תַּקִּיפִים גִּבּוֹרִים. וְהֶעָרִים בְּצֻרוֹת, שֶׁאֲפִלּוּ כָּל מַלְכֵי הָעוֹלָם יִתְכַּנְּסוּ עֲלֵיהֶם, לֹא יַעֲשׂוּ בָהֶם פְּגָם. אָמַר רַבִּי יוֹסֵי, כָּל מַה שֶּׁאָמְרוּ, בְּלָשׁוֹן הָרָע אָמְרוּ, וְהַקָּשֶׁה מֵהַכֹּל - שֶׁכָּתוּב עֲמָלֵק יוֹשֵׁב בְּאֶרֶץ הַנֶּגֶב. לְבֶן אָדָם שֶׁנְּשָׁכוֹ נָחָשׁ, כְּשֶׁרוֹצִים לְהַפְחִיד אוֹתוֹ, אוֹמְרִים: הִנֵּה נָחָשׁ כָּאן."],[6,"","רַבִּי אַבָּא אָמַר, וַדַּאי זֶה קָשֶׁה מִכָּל מַה שֶּׁאָמְרוּ, כְּלוֹמַר, אוֹתוֹ שֶׁעוֹרֵךְ קְרָב בַּכֹּל הֲרֵי כָּאן זָמִין. וּבְאֵיזֶה מָקוֹם? בְּאֶרֶץ הַנֶּגֶב, שֶׁהֲרֵי הוּא הַמָּקוֹם לְהִכָּנֵס בּוֹ. מִיָּד - וַתִּשָּׂא כָּל הָעֵדָה וַיִּתְּנוּ אֶת קוֹלָם. קָבְעוּ בְכִיָּה לְדוֹרוֹת, לְעוֹלָמִים, בְּאוֹתוֹ לַיְלָה."],[7,"","אָמַר רַבִּי יוֹסֵי, עֵצָה לָקְחוּ עַל הַכֹּל לְהוֹצִיא שֵׁם רַע. מַה זֶּה עַל הַכֹּל? עַל הָאָרֶץ וְעַל הַקָּדוֹשׁ בָּרוּךְ הוּא. אָמַר רַבִּי יִצְחָק, עַל הָאָרֶץ בְּסֵדֶר, עַל הַקָּדוֹשׁ בָּרוּךְ הוּא מִנַּיִן? אָמַר לוֹ, מִמַּשְׁמָע שֶׁכָּתוּב אֶפֶס כִּי עַז הָעָם. מִי יָכוֹל לָהֶם? כִּי עַז הָעָם דַּוְקָא. וְכָתוּב עֲמָלֵק יוֹשֵׁב בְּאֶרֶץ הַנֶּגֶב, וְאָז גָּרְמוּ כָּל זֶה, כְּמוֹ שֶׁנִּתְבָּאֵר. וְרָצָה הַקָּדוֹשׁ בָּרוּךְ הוּא לְהַשְׁמִידָם מֵהָעוֹלָם. זֶהוּ שֶׁכָּתוּב (תהלים קו) וַיֹּאמֶר לְהַשְׁמִידָם לוּלֵי מֹשֶׁה בְחִירוֹ עָמַד בַּפֶּרֶץ לְפָנָיו וְגוֹ'."],[8,"","וְעַתָּה יִגְדַּל נָא כֹּחַ ה'. רַבִּי אָחָא וְרַבִּי יוֹסֵי אָמְרוּ, אַשְׁרֵיהֶם יִשְׂרָאֵל מֵעַמִּים עוֹבְדֵי כוֹכָבִים וּמַזָּלוֹת שֶׁל הָעוֹלָם, שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא רוֹצֶה בָהֶם וְהִתְכַּנָּה בָהֶם וְהִתְפָּאֵר בָּהֶם, שֶׁהֲרֵי הָעוֹלָם לֹא נִבְרָא אֶלָּא בִּשְׁבִיל יִשְׂרָאֵל שֶׁיִּשְׁתַּדְּלוּ בַתּוֹרָה, מִשּׁוּם שֶׁאֶחָד בְּאֶחָד הִתְקַשְּׁרוּ, וְיִשְׂרָאֵל לְמַטָּה בָּעוֹלָם הַזֶּה הֵם קִיּוּמוֹ, וְקִיּוּם שֶׁל כָּל שְׁאָר הָעַמִּים. אֵימָתַי? בִּזְמַן שֶׁעוֹשִׂים רְצוֹן רִבּוֹנָם."],[9,"","בֹּא וּרְאֵה, כְּשֶׁבָּרָא הַקָּדוֹשׁ בָּרוּךְ הוּא אָדָם בָּעוֹלָם, הִתְקִינוֹ כְּדֻגְמָה עֶלְיוֹנָה (מכבדת), וְנָתַן לוֹ כֹּחוֹ וְתָקְפּוֹ בְּאֶמְצַע הַגּוּף, שֶׁשָּׁם שׁוֹרֶה הַלֵּב, שֶׁהוּא חֹזֶק (ומזון) כָּל הַגּוּף וּמִשָּׁם נִזּוֹן כָּל הַגּוּף. (וכל אותם איברים שבגוף משם נזונו) וַהֲרֵי הַלֵּב אָחוּז וּמִתְחַזֵּק בְּמָקוֹם עֶלְיוֹן שֶׁלְּמַעְלָה (ואחוזבו), שֶׁהוּא מֹחַ הָרֹאשׁ שֶׁשּׁוֹרֶה לְמַעְלָה, וְזֶה נִקְשָׁר בָּזֶה."]]],[["וּבְגַוְונָא דְּדָא, אַתְקִין קוּדְשָׁא בְּרִיךְ הוּא עָלְמָא. וְעֲבַד (ליה) חַד גּוּפָא, וְאַתְקִין שַׁיְיפֵי דְּגוּפָא סַחֲרָנֵיהּ דְּלִבָּא, וְלִבָּא שָׁארֵי בְּאֶמְצָעִיתָא דְּכָל גּוּפָא. וְכָל אִינּוּן שַׁיְיפִין אִתְּזָנוּ מֵהַהוּא לִבָּא, דְּהוּא תּוּקְפָּא דְּכֹלָּא, וְכֹלָּא בֵּיהּ תַּלְיָין. וְהַהוּא לִבָּא, אִתְקְשַׁר וְאִתְאֲחָד בְּמוֹחָא עִלָּאָה דְּשַׁרְיָא לְעֵילָּא.","תָּא חֲזֵי, כַּד בָּרָא קוּדְשָׁא בְּרִיךְ הוּא עָלְמָא, אַשְׁרָא (ס\"א אסדר) לְיַמָּא דְּאוֹקְיָנוּס דְּאַסְחַר כָּל יִשּׁוּבָא דְּעָלְמָא. וְיִשּׁוּבָא דְּכָל שִׁבְעִין אוּמִין כֹּלָּא אַסְחַר לִיְרוּשָׁלַם. וִיְרוּשָׁלַם בְּאֶמְצָעִיתָא דְּכָל יִשּׁוּבָא שַׁרְיָא. וְהִיא אַסְחַרָא לְהַר הַבַּיִת. וְהַר הַבַּיִת אַסְחַר לַעֲזָרוֹת דְּיִשְׂרָאֵל. וְאִינּוּן עֲזָרוֹת סָחֲרָן לְלִשְׁכַּת הַגָּזִית, דְּתַמָּן סַנְהֶדְּרֵי גְּדוֹלָה יַתְבִין. וְתָנֵינָן, לֵית יְשִׁיבָה בַּעֲזָרָה, אֶלָּא לְמַלְכֵי בֵּית דָּוִד בִּלְחוֹדַיְיהוּ.","וְלִשְׁכַּת הַגָּזִית אַסְחַר לַמִּזְבֵּחַ. וְהַמִּזְבֵּחַ אַסְחַר לְבֵית הָאוּלָם. וְהָאוּלָם לָהֵיכָל. וְהֵיכָל לְבֵית קֹדֶשׁ הַקֳדָשִׁים, דְּתַמָּן שְׁכִינָה שַׁרְיָא, וְכַפֹּרֶת וּכְרוּבִים וְאָרוֹן. וְהָכָא הוּא לִבָּא, דְּכָל אַרְעָא וְעָלְמָא. וּמֵהָכָא אִתְּזָנוּ כָּל אִינּוּן אַתְרֵי דְּיִשּׁוּבָא, דְּאִינּוּן שַׁיְיפִי דְּגוּפָא. וְלִבָּא דָּא אִתְּזָן מִמּוֹחָא דְּרֵישָׁא, וְאִתְאֲחִיד דָּא בְּדָא, הֲדָא הוּא דִכְתִיב (שמות ט״ו:י״ז) מָכוֹן לְשִׁבְתְּךָ פָּעַלְתָּ יְיָ. כְּגַוְונָא דָּא לְעֵילָּא לְעֵילָּא, וְאִיהוּ בְּרָזָא דְּמַלְכָּא עִלָּאָה, בְּרָזָא יַקִּירָא סְתִימָאָה.","יַמָּא עִלָּאָה לָקֳבֵיל דָּא. דְּאִית יַמָּא לְעֵילָּא מִן יַמָּא, וְיַמָּא מִן יַמָּא. תָּא חֲזֵי, נְהַר דִּינוּר אַסְחַר לְכַמָּה מַשִׁרְיָין. מִקֳבְלֵיהּ שִׁבְעִין סִטְרִין, גְּלִיפִין מִשִּׁבְעָה דְּלִיקִין, וְאִינּוּן סָחֲרָן, לְאִינּוּן שַׁמָּשֵׁי דִּלְגוֹ מִנַּיְיהוּ. וְאִינּוּן סָחֲרִין לְאַרְבַּע רְתִיכִין. וְאִינּוּן סָחֲרָן לְהַהִיא קַרְתָּא דְּקַדִּישָׁא דִּרְבִיעָא עָלַיְיהוּ.","וְתָאנָא, תַּמָּן עֲזָרוֹת לְגוֹ מֵעֲזָרוֹת. וְלֵית יְשִׁיבָה בַּעֲזָרָה דְּתַמָּן, אֶלָּא לְמַלְכֵּיהוֹן דְּבֵית דָּוִד בִּלְחוֹדַיְיהוּ, וְתַמָּן מִשְׁתַּכְחֵי וְיַתְבֵי. וְסַהְנֶדְרֵי גְּדוֹלָה, מִשְׁתַּכְּחֵי תַּמָּן בְּלִשְׁכַּת הַגָּזִית. וְהַהוּא בֵּי דִּינָא עָלַיְיהוּ, דִּמְשַׁמֵּשׁ לַאֲתָר דִּמְשַׁמֵּשׁ. וְדִינָא אִתְיְהִיב מִתַּמָּן, לְקַדִּישִׁין עֶלְיוֹנִין, עַד דְּמָטָא לַאֲתָר דְּאִקְרֵי קֹדֶשׁ הַקֳדָשִׁים, דְּבֵיהּ כֹּלָּא, וְתַמָּן הוּא לִבָּא שַׁרְיָיא, וְדָא אִתְּזָן מִן מוֹחָא דִּלְעֵילָּא, וְאִתְאֲחִיד דָּא בְּדָא.","כְּגַוְונָא דָּא לְעֵילָּא לְעֵילָּא, וְאִיהוּ בְּרָזָא דְּמַלְכָּא עִלָּאָה, בְּרָזָא יַקִּירָא סְתִימָאָה. עַד דְּאִשְׁתְּכַח, דְּכֹלָּא אִתְּזָן מִמּוֹחָא עִלָּאָה, סְתִימָאָה דְּכֹלָּא. וְכַד יִסְתַּכְּלוּן מִלֵּי, כֹּלָּא אִתְקְשַׁר דָּא בְּדָא וְדָא בְּדָא.","תָּא חֲזֵי, כַּד אַנְהִיר עַתִּיקָא סְתִימָא בְּמוֹחָא, וּמוֹחָא אַנְהִיר לְלִבָּא, בְּדֶּרֶך נֹעַם יְיָ. וְהָא אוֹקִימְנָא, וְדָא הוּא כֹּחַ יְיָ. הַהוּא חֵילָא דְּאָתֵי מֵעַתִּיקָא קַדִּישָׁא. סְתִימָא דְּכָל סְתִימִין. יִגְדַּל נָא, דְּיִּתְרְבֵּי וְיִסְגֵּי לְעֵילָּא לְעֵילָּא. וְיִתְנְגִיד וְיִתְמְשַׁךְ לְתַתָּא. כַּאֲשֶׁר דִּבַּרְתָּ, כְּמָה דְּאוּקְמוּהָ. לֵאמֹר, לְמֵילַף מֵהָכָא כָּל דָּרִין בַּתְרָאִין, לְעָלַם וּלְעָלְמֵי עָלְמִין. לֵאמֹר, לְמֵימַר לְדָא בְּשַׁעֲתָא דְּעַקְתָּא. לְמֵימַר דָּא, בְּשַׁעֲתָא דִּרְוָוחָא. וּמַאי הוּא. יְיָ אֶרֶךְ אַפַּיִם וְגוֹ', וְהָא אוֹקִימְנָא מִלֵּי.","אָמַר רִבִּי יִצְחָק, אֱמֶת אֲמַאי סָלִיק מִכָּאן. אָמַר רִבִּי חִיָּיא, אִינּוּן גָּרְמוּ לֵיהּ דְּאִסְתָּלִיק מִכָּאן, דְּהָא בְּשִׁקְרוּ דִּבְּרוּ גַּרְמַיְיהוּ בְּהַהוּא מִדָּה דְּבַּר נָשׁ מוֹדֵד בָּהּ, מוֹדְדִין לֵיהּ. וְכֵן שְׁאַר אָחֳרֵי אִסְתְּלָקוּ, דְּלָא יָכִיל מֹשֶׁה לְמֵימְרִינְהוּ, בְּגִין דְּאִינּוּן גָּרְמוּ. סָלַחְתִּי כִּדְבָרֶיךָ, כִּדְבָרֶיךָ מַמָּשׁ, וְהָא אַתְּעֲרוּ חַבְרַיָּיא, וְהָא אִתְּמַר. (אמר המגיה כך מצאתי בהעתקות אשר לפני ומתוך הלשון נראה שחסר התחלת המאמר וגם במקומות אחרים ממנו חסר ועם כל זה לא רציתי להשמיטו מן הספר להגדיל תורה ולהאדיר)","דָּא עִם דָּא, מַה דְּלָא הֲווֹ יַכְלִין לְמַלְּלָא מִקַּדְמַת דְּנָא. נַפְקוּ מֵהַהִיא פִּתְחָא, וְיָתְבוּ בְּגִנְתָא תְּחוֹת אִילָנִין. אָמְרוּ דָּא לְדָא, כֵּיוָן דַּאֲנָן הָכָא, וְחָמֵינָן כָּל דָּא, אִי נֵמוּת הָכָא, וַדַּאי נֵיעוּל לְעָלְמָא דְּאָתֵי. יָתְבוּ. שֵׁינָתָא נַפְלַת עָלַיְיהוּ. וְדַמְכוּ. אַדְהָכִי, הָא הַהוּא מְמָנָא אָתָא, וְאַתְעַר לוֹן, אָמַר לוֹן, קוּמוּ פּוּקוּ לְגוֹ פַּרְדֵּס דְּאַבְרָא. נַפְקוּ, חָמוּ לְאִלֵּין מָארֵי מִקְרָא, דַּהֲווּ אַמְרֵי בְּהַהוּא קְרָא, (במדבר י״ד:ל״ה) בַּמִּדְבָּר הַזֶּה יִתַּמּוּ, הָא בַּאֲתָר אַחֲרָא לָא. וְשָׁם יָמוּתוּ, הָא בַּאֲתָר אַחֲרָא לָא, וְדָא בְּגוּפִין, אֲבָל בְּנִשְׁמָתִין לָא, כְּגַוְונָא דִּבְנֵי גִּנְתָא."],[[0,"וכגוונא דדא אתקין וכו׳:","ובאופן זה התקין הקב״ה את העולם. ועשהו גוף אחד, והתקין אברי הגוף מסביב הלב, והלב שורה באמצע כל הגוף, וכל האברים נזונים מלב ההוא, שהוא תוקפו של כולם, והכל תלוי בו, ולב ההוא מתקשר ומתאחד במוח עליון השורה למעלה. כמ\"ש לפנינו."],[1,"ת״ח כד ברא וכו׳:","בוא וראה, כשברא הקב״ה את העולם, השרה את ים אוקינוס המקיף כל ישוב העולם. והישוב של כל ע׳ אומות מקיפים את ירושלים. וירושלים שורה באמצע כל הישוב. והיא מקפת את הר הבית. והר הבית מקיף את עזרות ישראל. והעזרות מקיפות את לשכת הגזית. כלומר מבחינת החשיבות, ששם יושבים סנהדרי גדולה. ולמדנו, אין ישיבה בעזרה אלא למלכי בית דוד בלבד. ועכ״ז, הם מקיפים ללשכת הגזית ששם מושב הסנהדרין. וחושב כאן ז׳ בחינות זו חשובה מזו, כנגד ז׳ ספירות."],[2,"ולשכת הגזית אסחר וכו׳:","ולשכת הגזית מקיף את המזבח. והמזבח מקיף לבית האולם. והאולם את ההיכל, וההיכל לבית קדש הקדשים, ששם שורה השכינה והכפורת והכרובים והארון. וכאן הוא הלב של כל הארץ והעולם. ומכאן נזונים כל מקומות הישוב, שהם אברים של הגוף הזה, דהיינו של העולם, ולב הזה שהיא השכינה וכו'. נזון ממוח שבראש, שהוא מלכות דאצילות. ומתאחדים זה בזה. ז״ש, מכון לשבתך פעלת ה'. כעין זה הוא למעלה למעלה, בעולם האצילות והוא, הלב, הוא בסוד מלך העליון, שהוא ז״א. והמוח שלמעלה, הוא בסוד מוח היקר הסתום, דהיינו מוחא סתימאה דא״א, אשר ז״א, שה״ס הלב, מקבל ממנו, דרך או״א."],[3,"ימא עלאה לקביל וכו׳:","ים העליון, שהוא מלכות דאצילות, הוא כנגד זה, שיש לה ג״כ במרכבה שלה אותם ג׳ בחינות הנ״ל, שהם בחינת אברי הגוף, והלב שבאמצעם, שאברי הגוף מקבלים ממנו. ומוחא דרישא, שהלב מקבל ממנו. כי יש ים למעלה מן הים דעולם הזה, כלומר, כמו שיש בעוה״ז ים, כך יש למעלה באצילות ים, שהיא המלכות, וים מן ים, שעוד יש ים עליון למעלה מן הים העליון שהוא מלכות, כי גם הבינה נקראת ים. ועתה מפרש הזהר מרכבת המלכות בג׳ בחינות שלה, שבכל בחינה יש כמה בחינות, ואומר, בוא וראה, נהר דינור מקיף לכמה מחנות מלאכים, מכנגדו יוצאים ע׳ בחינות מלאכים חקוקות משבע משואות, שהם ז׳ ספירות חג״ת נהי״מ, של אש הגבורה, שכל אחת כלולה מעשר, שהם השומרים את השכינה. והם מקיפים לאלו המשמשים שלפנים מהם, והם מקיפים לארבע מרכבות, שה\"ס ד׳ מלאכים מיכאל גבריאל אוריאל רפאל, שכל אחד כלול מג׳, כנ״ל בהעלותך (אות קי״א) שהם נושאים את המלכות. ועד כאן היא בחינת גוף וחיצונית המלכות. והם מקיפין לאותה עיר הקדושה הרובצת עליהם, שהיא המלכות דאצילות. שה״ס הלב שבהם. אלא שגם היא מתחלקת לכמה בחינות, כמ״ש והולך."],[4,"ותאנא תמן עזרות וכו׳:","עתה מבאר, שהמלכות עצמה מתחלקת לכמה בחינות, ורק הפנימית שבה הוא הלב המקבל מן המוח שהוא ז״א. ואומר, למדנו, ששם, במלכות, יש עזרות לפנים מעזרות, שה\"ס ז״ס תחתונות במלכות, ואין ישיבה בעזרה אשר שם רק למלכי בית דוד בלבד, שנמצאים ויושבים שם. כלומר שמלכי בית דוד אחוזים שם. וסנהדרי גדולה נמצאים שם בלשכת הגזית, שה״ס ו״ק דג״ר דמלכות, ואותו הבית דין שעליהם, שה״ס ג\"ר דג״ר, המשמש למקום שמשמש, כלומר, שהם משמשים רק למלכות עצמה, ולא נמשך מהם לתחתונים, ודין נמשך משם לקדושים עליונים. כלומר, שהדינים שבהם הנתכים על ראש הרשעים, הם בלבדם מושגים לקדושים עליונים. בסו״ה ויצאו וראו בפגרי האנשים וגו'. עד שמגיע למקום הנקרא קדש הקדשים, שהוא פנימי פנימיות המלכות, דהיינו יסוד דגדלות שלה, שבו הכל, ושם הלב שורה, וזה הוא הנזון מן מוח העליון, שהוא ז״א, ומתאחדים זה בזה."],[5,"כגוונא דא לעילא וכו׳:","חוזר על הדברים הנ״ל (באות פ״ז) ומפרשם ביותר. כעין זה למעלה למעלה באצילות, והוא, הלב, הוא בסוד מלך העליון, שהוא ז״א, והמוח, בסוד המוח היקר הסתום דא״א, שז״א מקבל ממנו דרך או״א. עד שנמצא שהכל נזון ממוח העליון דא״א הסתום מכל. וכשמסתכלים בדברים רואים שהכל נקשר זה בזה וזה בזה. פירוש, כי הלב שבעולם הזה, שהוא קדש הקדשים מקבל ממלכות העליונה דאצילות (כנ״ל אות פ״ז) והמרכבה של מלכות דאצילות מקבלת מקדש הקדשים שבמלכות עצמה, וקדש הקדשים שבמלכות מקבלת מז\"א (כנ״ל אות פ״ט) וז״א מקבל דרך או״א ממוחא סתימאה דא\"א. הרי שהכל מקבלים ממוחא סתימאה דא״א. וכולם נקשרים זב״ז."],[6,"ת״ח כד אנהיר וכו׳:","בוא וראה, כשמאיר עתיקא הסתום שהוא מוחא סתימאה דא״א, במוח, שהוא אבא, והמוח מאיר ללב, שהוא ז״א, בדרך נעם ה', דהיינו דרך הבינה הנקראת נעם, והעמדנו, שזה הוא \u0003כח ה'.\u0004 דהיינו כח ההוא הבא מעתיקא קדישא הסתום מכל הסתומים. \u0003יגדל נא,\u0004 פירושו, שיתגדל ויתרבה למעלה למעלה ויזל, ויהי נמשך למטה. \u0003כאשר דברת,\u0004 הוא כמו שהעמידוהו. שהוא ארך אפים בין לצדיקים ובין לרשעים (עירובין כ״ב) \u0003לאמר,\u0004 היינו שילמדו מכאן כל דורות האחרונים לעולם ולעולמי עולמים \u0003לאמר,\u0004 היינו, לומר זה בעת צרה, ולומר זה בשעת הרוחה. ומה הוא. היינו ה׳ ארך אפים וגו׳. וכבר העמדנו הדברים."],[7,"אמר ר׳ יצחק וכו׳:","אר״י \u0003אמת\u0004 למה חסר מכאן, שאינו נאמר כאן ורב חסר \u0003ואמת\u0004 כמ״ש בי״ג מדות דפרשת כי תשא. אמר ר׳ חייא הם, המרגלים, גרמו לו שיסתלק מכאן, השם ואמת, משום שנהגו את עצמם בשקר, ובאותו מדה שאדם מודד מודדים לו מלמעלה וכן שאר המדות נסתלקו, שמשה לא יכול לאומרם, כי אין כאן אלא ט׳ מדות הרחמים ולא י״ג, משום שהם, המרגלים, גרמו. \u0003סלחתי כדבריך,\u0004 היינו כדבריך ממש (עי׳ ברכות ל״ב.). וכבר העירו החברים, ולמדנו."],[8,"דא עם דא וכו׳:","חסר כאן תחלת המאמר. והיו מדברים זה עם זה מה שלא יכלו לדבר מקודם לכן. יצאו מפתח ההוא, וישבו בגן תחת האילנות. אמרו זה לזה, כיון שאנו כאן, וראינו כל זה, אם נמות כאן, ודאי נבא לעולם הבא. ישבו. נפל עליהם שינה וישנו. בתוך כך בא ממונה ההוא והעירם. אמר להם, קומו צאו לתוך הפרדס שמבחוץ. דהיינו למדרגה חיצונית. יצאו. ראו אלו בעלי מקרא שהיו אומרים במקרא הזה. \u0003במדבר הזה יתמו,\u0004 אבל במקום אחר לא. דהיינו שיזכו לעולם הבא. ושם ימותו, אבל במקום אחר לא. דהיינו שיהיו להם חיי עולם הבא. וזה בגופין, שאפילו בעוה״ז ימותו רק מבחינת הגוף, אבל לא הנשמות. שיהיו כעין בני הגן. דהיינו שהנשמות יזכו לגן עדן."]],[[0,"","וּבְצוּרָה זוֹ הִתְקִין הַקָּדוֹשׁ בָּרוּךְ הוּא הָעוֹלָם וְעָשָׂה (אותו) גוּף אֶחָד, וְהִתְקִין אֵיבְרֵי הַגּוּף סְבִיב הַלֵּב, וְהַלֵּב שׁוֹרֶה בְּאֶמְצַע כָּל הַגּוּף. וְכָל אוֹתָם אֵיבָרִים נִזּוֹנִים מֵאוֹתוֹ לֵב, שֶׁהוּא חֹזֶק הַכֹּל, וְהַכֹּל בּוֹ תְּלוּיִים. וְאוֹתוֹ לֵב נִקְשָׁר וְנֶאֱחָז בַּמֹּחַ הָעֶלְיוֹן שֶׁשּׁוֹרֶה לְמַעְלָה."],[1,"","בֹּא וּרְאֵה, כְּשֶׁבָּרָא הַקָּדוֹשׁ בָּרוּךְ הוּא הָעוֹלָם, הִשְׁרָה (סדר) אֶת יָם הָאוֹקְיָנוֹס סְבִיב יִשּׁוּב כָּל הָעוֹלָם, וְיִשּׁוּב כָּל שִׁבְעִים הָאֻמּוֹת כֻּלָּם סְבִיב לִירוּשָׁלַיִם, וִירוּשָׁלַיִם שׁוֹרָה בְּאֶמְצַע כָּל הַיִּשּׁוּב, וְהִיא מְסוֹבֶבֶת לְהַר הַבַּיִת, וְהַר הַבַּיִת סְבִיב עֶזְרוֹת יִשְׂרָאֵל, וְאוֹתָן עֲזָרוֹת סוֹבְבוֹת לְלִשְׁכַּת הַגָּזִית, שֶׁשָּׁם יוֹשְׁבִים סַנְהֶדְרִין גְּדוֹלָה. וְשָׁנִינוּ שֶׁאֵין יְשִׁיבָה בָּעֲזָרָה, אֶלָּא לְמַלְכֵי בֵּית דָּוִד לְבַדָּם."],[2,"","וְלִשְׁכַּת הַגָּזִית סְבִיב הַמִּזְבֵּחַ, וְהַמִּזְבֵּחַ סְבִיב בֵּית הָאוּלָם, וְהָאוּלָם לַהֵיכָל, וְהַהֵיכָל לְבֵית קֹדֶשׁ הַקְּדָשִׁים, שֶׁשָּׁם שׁוֹרָה הַשְּׁכִינָה וְכַפֹּרֶת וּכְרוּבִים וְאָרוֹן. וְכָאן הוּא הַלֵּב שֶׁל כָּל הָאָרֶץ וְהָעוֹלָם, וּמִכָּאן נִזּוֹנוּ כָּל אוֹתָם מְקוֹמוֹת הַיִּשּׁוּב, שֶׁהֵם אֵיבְרֵי הַגּוּף. וְלֵב זֶה נִזּוֹן מִמֹּחַ הָרֹאשׁ וְנֶאֱחָז זֶה בָּזֶה. זֶהוּ שֶׁכָּתוּב (שמות טו) מָכוֹן לְשִׁבְתְּךְ פָּעַלְתָּ ה'. כְּמוֹ זֶה לְמַעְלָה לְמַעְלָה, וְהוּא בְסוֹד הַמֶּלֶךְ הָעֶלְיוֹן, בְּסוֹד נִכְבָּד נִסְתָּר."],[3,"","הַיָּם הָעֶלְיוֹן כְּנֶגֶד זֶה. שֶׁיֵּשׁ יָם לְמַעְלָה מִן הַיָּם, וְיָם מִן יָם. בֹּא וּרְאֵה, נְהַר דִּינוּר סוֹבֵב לְכַמָּה מֶרְכָּבוֹת. כְּנֶגְדּוֹ שִׁבְעִים צְדָדִים חֲקוּקִים מִשֶּׁבַע דְּלֵקוֹת, וְהֵם סוֹבְבִים לְאוֹתָם שַׁמָּשִׁים שֶׁלְּתוֹכָם. וְאֵלֶּה סוֹבְבִים לְאַרְבַּע מֶרְכָּבוֹת, וְאֵלּוּ סוֹבְבִים לְאוֹתָהּ עִיר קְדוֹשָׁה שֶׁרוֹבֶצֶת עֲלֵיהֶם."],[4,"","וְלָמַדְנוּ, שָׁם עֲזָרוֹת לִפְנִים מֵעֲזָרוֹת. וְאֵין יְשִׁיבָה בָּעֲזָרָה שֶׁל שָׁם, אֶלָּא לְמַלְכֵי בֵּית דָּוִד לְבַדָּם, וְשָׁם נִמְצָאִים וְיוֹשְׁבִים. וְסַנְהֶדְרִין גְּדוֹלָה נִמְצָאִים שָׁם בְּלִשְׁכַּת הַגָּזִית, וְאוֹתוֹ בֵּית דִּין עֲלֵיהֶם, שֶׁמְּשַׁמֵּשׁ לְמָקוֹם שֶׁמְּשַׁמֵּשׁ. וְהַדִּין נִתָּן מִשָּׁם לִקְדוֹשִׁים עֶלְיוֹנִים, עַד שֶׁמַּגִּיעַ לַמָּקוֹם שֶׁנִּקְרָא קֹדֶשׁ הַקְּדָשִׁים שֶׁבּוֹ הַכֹּל, וְשָׁם הַלֵּב שׁוֹרֶה, וְזֶה נִזּוֹן מִמֹּחַ הָעֶלְיוֹן, וְנֶאֱחָז זֶה בָּזֶה."],[5,"","כְּמוֹ זֶה לְמַעְלָה לְמַעְלָה, וְהוּא בְּסוֹד מֶלֶךְ הָעֶלְיוֹן, בְּסוֹד נִכְבָּד סָתוּם, עַד שֶׁנִּמְצָא, שֶׁהַכֹּל נִזּוֹן מִמֹּחַ עֶלְיוֹן סָתוּם שֶׁל הַכֹּל. וּכְשֶׁיִּסְתַּכְּלוּ עַל הַדְּבָרִים, הַכֹּל נִקְשָׁר זֶה בָּזֶה וְזֶה בָזֶה."],[6,"","בֹּא וּרְאֵה, כְּשֶׁמֵּאִיר הָעַתִּיק הַסָּתוּם בַּמֹּחַ, וְהַמֹּחַ מֵאִיר לַלֵּב, בְּדֶרֶךְ נֹעַם ה'. וַהֲרֵי בֵּאַרְנוּ, וְזֶהוּ כֹּחַ ה'. אוֹתוֹ כֹּחַ שֶׁבָּא מֵהָעַתִּיק הַקָּדוֹשׁ, סְתוּם כָּל הַסְּתוּמִים, יִגְדַּל נָא, שֶׁיִּתְרַבֶּה וְיִגְדַּל לְמַעְלָה לְמַעְלָה וְיֻשְׁפַּע וְיִמָּשֵׁךְ לְמַטָּה. כַּאֲשֶׁר דִּבַּרְתָּ, כְּמוֹ שֶׁפֵּרְשׁוּהָ. לֵאמֹר, לְלַמֵּד מִכָּאן לְכָל הַדּוֹרוֹת הָאַחֲרוֹנִים לְעוֹלָם וּלְעוֹלְמֵי עוֹלָמִים. לֵאמֹר, לוֹמַר לָזֶה בִּשְׁעַת צָרָה, לוֹמַר זֶה בִּשְׁעַת רְוָחָה. וּמַה הוּא? ה' אֶרֶךְ אַפַּיִם וְגוֹ', וַהֲרֵי בֵּאַרְנוּ הַדְּבָרִים."],[7,"","אָמַר רַבִּי יִצְחָק, אֱמֶת לָמָּה עוֹלֶה מִכָּאן? אָמַר רַבִּי חִיָּיא, הֵם גָּרְמוּ שֶׁעָלָה מִכָּאן, שֶׁהֲרֵי בְּשֶׁקֶר דִּבְּרוּ עַצְמָם. בְּאוֹתָהּ מִדָּה שֶׁאָדָם מוֹדֵד, בָּהּ מוֹדְדִים לוֹ. וְכֵן שְׁאָר הָאֲחֵרִים הִסְתַּלְּקוּ, שֶׁלֹּא יָכֹל מֹשֶׁה לְאָמְרָם, מִשּׁוּם שֶׁהֵם גָּרְמוּ. סָלַחְתִּי כִּדְבָרֶךְ, כִּדְבָרֶךְ מַמָּשׁ, וַהֲרֵי הִתְעוֹרְרוּ הַחֲבֵרִים, וַהֲרֵי נִתְבָּאֵר."],[8,"","זְהִ עִם זֶה, מַה שֶּׁלֹּא יָכְלוּ לְדַבֵּר מִקֹּדֶם זֶה. יָצְאוּ מֵאוֹתוֹ פֶּתַח, וְיָשְׁבוּ בְגִנָּה תַּחַת אִילָנוֹת. אָמְרוּ זֶה לָזֶה, כֵּיוָן שֶׁאָנוּ כָאן וְרָאִינוּ כָּל זֶה, אִם נָמוּת כָּאן, וַדַּאי נִכָּנֵס לָעוֹלָם הַבָּא. יָשְׁבוּ. שֵׁנָה נָפְלָה עֲלֵיהֶם וְנִרְדְּמוּ. בֵּין כָּךְ בָּא אוֹתוֹ מְמֻנֶּה וֶהֱעִירָם. אָמַר לָהֶם, קוּמוּ צְאוּ לְתוֹךְ פַּרְדֵּס שֶׁבַּחוּץ. יָצְאוּ. רָאוּ אוֹתָם בַּעֲלֵי מִקְרָא שֶׁהָיו אוֹמְרִים בְּאוֹתוֹ פָּסוּק, בַּמִּדְבָּר הַזֶּה יִתַּמּוּ - הֲרֵי בְּמָקוֹם אַחֵר לֹא. וְשָׁם יָמֻתוּ - הֲרֵי בְּמָקוֹם אַחֵר לֹא. וְזֶה בַגּוּפִים, אֲבָל בַּנְּשָׁמוֹת לֹא כְּמוֹ בְּנֵי הַגָּן."]]],[["אָמַר לוֹן הַהוּא מְמָנָא, פּוּקוּ. נַפְקוּ בַּהֲדֵיהּ, אָמַר לוֹן, שְׁמַעְתּוּן מִדִי לְגוֹ הַהוּא דַּרְגָּא. אָמְרוּ, שְׁמַעְנָא דְּהָא חַד קָלָא הֲוָה אָמַר, מַאן דְּפָסַק, יִתְפְּסַק. מַאן דְּקָצַר, יִתְקַצָר. מַאן דְּקָצַר, יִתְאֲרָךְ. אָמַר לוֹן, יְדַעְתּוּן מַאי הַאי. אָמְרוּ, לָא. אָמַר לוֹן, חֲמִיתּוּן הַהוּא נִשְׁרָא רַבְרְבָא, וְהַהוּא יְנוֹקָא דְּקָא מְלַקֵּט עֲשָׂבִין, רִבִּי אִילָאִי דִּנְצִיבִין הֲוָה. הוּא וּבְרֵיהּ, וּמָטָא הָכָא, וְחָמָא הוּא וִינוֹקָא בְּרֵיהּ מְעַרְתָּא דָּא, כֵּיוָן דְּעָאלוּ לְגוֹ חָשׁוּךְ, לָא יָכִילוּ לְמִסְבַּל, וּמִיתוּ.","וְהַהוּא יְנוֹקָא בְּרֵיהּ, קַיְּימָא בְּכָל יוֹמָא קָמֵּיהּ דִּבְצַלְאֵל, בְּשַׁעֲתָא דְּנָחִית מִמְּתִיבְתָא עִלָּאָה, וְאָמַר קָמֵּיהּ תְּלַת מִלִּין, עַד לָא יִפְתַּח בְּצַלְאֵל בְּרָזִין סְתִימִין דְּחָכְמְתָא, דְּכָל מִלּוֹי רָזִין סְתִימִין אִינּוּן, (ישעיהו ס״ד:ג׳) דְּעַיִן לֹא רָאָתָה אֱלֹהִים זוּלָתְךָ. הַאי (מאן) דְּאָמַר, מַאן דְּפָסַק יִתְפְּסַק. מַאן דְּפָסַק מִלִּין דְּאוֹרַיְיתָא, עַל מִלִּין בְּטֵלִין, יִתְפַּסְקוּן חָיּוֹהִי מֵהַאי עָלְמָא, וְדִינֵיה קַיְּימָא בְּהַהוּא עָלְמָא. מַאן דְּקָצַר יִתְקַצָר, מַאן דְּקָצַר אָמֵן, וְלָא מַאֲרִיךְ בֵּיהּ גּוֹ נַיְיחָא, יִתְקְצַר מֵחַיִּין דְּהַאי עָלְמָא. מַאן דְּקָצַר יִתְאֲרָךְ, מַאן דְּאָמַר אֶחָד, אִצְטְרִיךְ לְחַטְּפָא אָלֶף, וּלְקַצְּרָא קְרִיאָה דִּילֵהּ, וְלָא יְעַכֵּב בְּהַאי אָת כְּלָל. וּמַאן דְּעָבִיד דָּא, יִתְאָרְכוּן חַיָיו.","אָמְרוּ לֵיהּ, תּוּ אָמַר, תְּרֵין אִינּוּן, וַחֲדָא אִשְׁתְּתַּף בְּהוּ, וְאִינּוּן תְּלָתָא. וְכַד הֲווֹ תְּלָתָא, אִינּוּן חַד. אָמַר לוֹן, אִלֵּין תְּרֵין שְׁמָהָן דִּשְׁמַע יִשְׂרָאֵל, דְּאִינּוּן יְיָ יְיָ. אֱלֹהֵינוּ אִשְׁתְּתַּף בְּהוּ, וְאִיהוּ חוֹתָמָא דְּגוּשְׁפַּנְקָא, אֱמֶת. וְכַד מִתְחַבְּרָן כַּחֲדָא אִינּוּן חַד בְּיִחוּדָא חֲדָא.","תּוּ אָמַר, תְּרֵין אִינּוּן וְחַד אִתְהַדָר. כַּד שַׁלִּיט. טָאס עַל גַּדְפֵּי רוּחָא, וְשָׁאט בְּמָאתָן אֶלֶף, וְאִתְטָמַּר. אָמַר לוֹן, אִלֵּין תְּרֵין כְּרוּבִים, דְּהֲוָה רָכִיב בְּהוּ קוּדְשָׁא בְּרִיךְ הוּא. וּמִן יוֹמָא דְּאַגְנִיז יוֹסֵף מֵאֲחוּי, אַגְנִיז אִיהוּ (ס\"א חד), וְאִשְׁתְּאַר חַד לְגַבֵּי בִּנְיָמִין, הֲדָא הוּא דִכְתִיב, (תהילים י״ח:י״א) וַיִּרְכַב עַל כְּרוּב וַיָּעֹף וַיֵדֶא עַל כַּנְפֵי רוּחַ. וְאַגְנִיז בְּמָאתָן אֶלֶף עָלְמִין וְאִתְטָמַּר, הַהוּא דְּרָכִיב עָלֵיהּ, דְּאִינּוּן מָאתָן אֶלֶף גְּנִיזִין, אִינּוּן דִּילֵיהּ, בְּרִיךְ הוּא.","פּוּקוּ מֵהָכָא, זַכָּאִין אַתּוּן, נַפְקוּ, יָהַב לוֹן הַהוּא מְמָנָא וַורְדָא (אחרא) חֲדָא וְנַפְקוּ. כַּד נַפְקוּ אַסְתִּים פּוּם מְעַרְתָּא, וְלָא אִתְחֲזֵי כְּלָל. חָמוּ הַהוּא נִשְׁרָא, דְּהֲוָה נָחִית מֵהַהוּא אִילָנָא, וְעָאַל גּוֹ מְעַרְתָּא אַחֲרָא. אַרְחוּ אִינּוּן בְּהַהוּא וַּורְדָּא, וְעָאלוּ תַּמָּן, אַשְׁכָּחוּ הַהוּא נִשְׁרָא אַפּוּם מְעַרְתָּא, אָמַר לוֹן עוּלוּ זַכָּאֵי קְשׁוֹט חַבְרִין, דְּהָא לָא חֲמֵינָא חֶדְוָה דְּחַבְרוּתָא, מִן יוֹמָא דַּאֲנָא הָכָא, אֶלָּא בְּכוּ.","עָאלוּ מָאטוּ לַפַּרְדֵס אַחֲרָא, וְהַהוּא נִשְׁרָא בַּהֲדַיְיהוּ, כַּד מָטוּ לְגַבֵּי אִינּוּן מָארֵיהוֹן דְּמִשְׁנָה, אִתְהַדָּר הַהוּא נִשְׁרָא בְּדִיּוּקְנָא דְּאָדָם, בִּלְבוּשׁ יְקָר, מְנַהֲרָא כְּוָותַיְיהוּ, וְיָתִיב עִמְּהוֹן כַּחֲדָא, אָמַר לְאִינּוּן דְּיַתְבֵי, הָבוּ יְקָר לְמָארֵי מַתְנִיתָא דְּאָתוּ הָכָא, דְּהָא מָארֵיהוֹן אַחְמֵי לוֹן פְּלִיאָן רַבְרְבָן הָכָא. אָמַר חַד מִנַּיְיהוּ, אִית בְּכוּ סִימָנָא. אָמְרוּ הִין. אַפִּיקוּ תְּרֵין וְרָדִין, וְאַרְחוּ בְּהוּ. אָמְרוּ, תִּיבוּ מָארֵי מְתִיבְתָּא, תִּיבוּ זַכָּאֵי קְשׁוֹט, אֲחִידוּ בְּהוּ, וְיָתְבוּ. בְּהַהִיא שַׁעֲתָא, אוֹלְפוּ תַּמָּן תְּלָתִין הֲלָכוֹת, דְּלָא הֲווֹ יַדְעֵי מִקַּדְמַת דְּנָא, וְרָזִין אַחֲרָנִין דְּאוֹרַיְיתָא.","אָהַדְרוּ לְגַבֵּי אִינּוּן מָארֵי מִקְרָא, אַשְׁכָּחוּ דַּהֲווֹ אַמְרֵי, (תהילים פ״ב:ו׳) אֲנִי אָמַרְתִּי אֱלֹהִים אַתֶּם וּבְנֵי עֶלְיוֹן כֻּלְכֶם. אֲנִי אָמַרְתִּי, בְּשַׁעֲתָא דְּאַקְדִימְתּוּן עֲשִׂיָּה לַשְּׁמִיעָה. דְּהָא אֱלֹהִים אַתֶּם וְגוֹ'. כֵּיוָן דְּאַמְשִׁכְתּוּן בָּתַר יֵצֶר הֵרַע, אָכֵן כְּאָדָם תְּמוּתוּן וְגוֹ'. מַה מִיתָתוֹ שֶׁל אָדָם אָחִית לֵיהּ לְעַפְרָא, בְּגִין דְּיִתְמְחֵי הַהוּא יֵצֶר הָרָע דִּי בְּגַוִּיהּ, וְהַהוּא יֵצֶר הָרָע אִיהוּ דְּמִית, וְאִתְעַכָּל בְּגַוִּיהּ."],[[0,"אמר לון ההוא וכו׳:","אמר להם ממונה ההוא, צאו. יצאו עמו. אמר להם שמעתם משהו בתוך מדרגה ההיא. אמרו, שמענו, שקול אחד היה אומר, מי שפוסק יתפסק. מי שמקצר יתקצר. מי שמקצר יתארך. אמר להם הידעתם מה זה. אמרו לא. אמר להם ראיתם אותו נשר הגדול, ואותו הילד שמלקט עשבים. ר׳ אילאי מנציבין היה, הוא ובנו, והגיעו כאן וראו הוא ואותו הילד בנו את מערה ההיא. כיון שנכנסו לתוך החשך לא יכלו לסבול, ומתו."],[1,"וההוא ינוקא בריה וכו׳:","ואותו הילד בנו, עומד בכל יום לפני בצלאל בשעה שיורד מישיבה העליונה, ואמר לפניו שלשה דברים, מטרם שפותח בצלאל בסודות סתומים של החכמה, כי כל דבריו סודות סתומים הם דעין לא ראתה אלקים זולתך, וזהו שאמר, \u0003מי שפוסק יתפסק,\u0004 היינו, מי שפוסק דברי תורה בשביל לדבר דברים בטלים יהיו נפסקים חייו מעולם הזה, ודינו עומד לעולם ההוא. \u0003מאן דקצר יתקצר,\u0004 היינו מי שמקצר באמן, ואינו מאריך בו במנוחה, אלא שאומר אמן חטופה, יתקצר מחיים של עולם הזה. \u0003מאן דקצר יתארך,\u0004 היינו, מי שאמר אחד, צריך למהר באלף דאחד, ולקצר הקריאה שלה, ולא יתעכב באות הזו כלל. ומי שעושה כך, יתארכו חייו."],[2,"אמרו ליה וכו׳:","אמרו לו עוד אמר, שנים הם, ואחד נשתתף בהם, והם שלשה, וכשהם שלשה הם אחד. אמר להם, אלו הם שני שמות, \u0003הויה הויה,\u0004 שבשמע ישראל, אלקינו, נשתתף בהם, והוא חותם הטבעת, אמת. וכשמתחברים יחד, הם אחד ביחוד אחד."],[2,"","פירוש. ג׳ שמות שבשמע ישראל הם חב״ד, כמ״ש הזהר בכמה מקומות. הויה אלקינו הם חכמה ובינה. והויה שלאחריהם הוא דעת. ונודע שז״א שה״ס הדעת, מקבל חסדים מאבא, שהוא חכמה, כנ״ל (באות צא) וכל עוד שאמא שה״ס נעם ה', אינו משתתף עם אבא, יהיו החסדים שמקבל מאבא בבחינת ו״ק חסר ראש. אלא אם אמא משתתף עם אבא ומשפעת המוחין לז״א הם ג״ר. וז״ש \u0003אלין תרין שמהן דשמע ישראל דאינון הויה הויה,\u0004 שהם אבא שהוא חכמה, וז״א שה״ס הדעת. אשר ז״א מקבל אור החסדים מאבא. \u0003אלקינו אשתתף בהו,\u0004 אמא משתתף עם אבא ועם ז״א, אז נעשו החסדים בבחינת ג״ר, \u0003ואיהו חותמא דגושפנקא, אמת.\u0004 שז״א מקבל חתימת הטבעת מאמא, שה״ס אמת, דהיינו המוחין דג״ר מאמא, מכונים אמת, בסוד תתן אמת ליעקב. וה״ס חותם הטבעת מאמא. ולפני השתתפות אמא אין המוחין שלו נקראים אמת. ע״ד הנ״ל (באות צ״ב). וז״ש \u0003וכד מתחברן כחדא אינון חד ביחודא חדא.\u0004 כי הם מתחברין בסוד ג׳ קוין, שאבא ואמא הם ימין ושמאל, והדעת מכריע ביניהם, ואז הם אחד. כי הדעת מיחדם."],[3,"תו אמר תרין וכו׳:","עוד אמר, שנים הם, וחזר לאחד. כששולט הוא מעופף על כנפי דוח, ומשוטט במאתים אלף ומסתתר. אמר להם אלו ב׳ כרובים שהיה רוכב עליהם הקב״ה, ומיום שנגנז יוסף מאחיו נגנז אחד, ונשאר אחד אצל בנימין. ז״ש וירכב על כרוב ויעף וידא על כנפי רוח. ומה שאמר, ונגנז במאתן אלף ונסתתר, היינו מי שרוכב עליו, הוא נסתתר במאתים אלף, שאלו מאתים אלף גנוזים הם שלו, ברוך הוא."],[3,"","פירוש. ב׳ כרובים הם מטטרון וסנדלפון, שהם מרכבה לזווג זו\"ן דאצילות. ועל זה נאמר יושב הכרובים, שיורה שיש זווג זו״ן ואז ה״ס יושב הכרובים. אמנם אם אין זווג זו״ן, אינו רוכב על ב׳ הכרובים מטטרון וסנדלפון, שהם דכר ונוקבא, אלא על סנדלפון בלבד, ואז נאמר וירכב על כרוב. דהיינו רק על אחד. כמ״ש לעיל (תרומה אות תתקכ״ב ע״ש) וז״ש, \u0003אלין תרין כרובים דהוה רכיב בהו קב״ה\u0004 דהיינו בסוד יושב הכרובים, שהוא בזמן שז״א הוא בזווג עם המלכות. \u0003ומן יומא דאגניז יוסף מאחוי,\u0004 כלומר בשעה שאין זווג למעלה כי היסוד שנקרא יוסף נגנז מאחיו, ואינו משפיע אליהם. \u0003ואשתאר חד לגבי בנימין.\u0004 דהיינו סנדלפון. כי יוסף הוא בחינת יסוד דכורא, ובנימין הוא בחינת הנוקביות שביסוד. שמבחינת הכרובים הוא סנדלפון. ואז ז״א חסר ג\"ר. אבל בשעה שיש זווג בז״א ומלכות ומתלבש ויושב על ב׳ הכרובים, אז יש לו ג\"ר. וז״ש \u0003ואגניז במאתן אלף עלמין ואתטמר ההוא דרכיב עליה,\u0004 כי בעת שז״א רוכב על כרוב אחד הוא נגנז בחכמה ובינה, שה״ס מאתים אלף, כי מצד הבינה הם מאתים, ומצד החכמה הם אלף. וז״א גטז בהם, כלומר שהם נעלמים בו ואין לו ג\"ר. כי אין לו ג״ר אלא כשרוכב על שניהם. וז״ש, \u0003דאינון מאתן אלף גניזין אינון דיליה.\u0004 דהיינו־בזמן הזווג. וז״ש, \u0003ושאט במאתן אלף ואתטמר,\u0004 שבעת הזווג שאט במאתן אלף, דהיינו שיש לו ג״ר. וכשאין זווג, אז \u0003ואתטמר.\u0004 שהג״ר נעלמים."],[4,"פוקו מהכא זכאין וכו׳:","אמר להם הממונה, צאו מכאן, צדיקים אתם וראוים אתם למדרגה יותר גבוהה. יצאו. נתן להם אותו הממונה שושנה אחת, שה״ס המלכות בבחי׳ חכמה תתאה, ויצאו. כשיצאו נסתם פי המערה ולא היה נראה כלל. ראו אותו נשר, שה״ס פני נשר, שהיה יורד מאילן ונכנס תוך מערה אחרת, הם הריחו באותה שושנה. שהארת החכמה נקראת ריח. ונכנסו שם. מצאו את הנשר על פי המערה, אמר להם הכנסו חברים צדיקי אמת, כי עוד לא ראיתי שמחה של התחברות מיום שאני כאן, אלא בכם."],[5,"עאלו מאטו לפרדס וכו׳:","נכנסו לפרדס אחר, דהיינו למדרגה אחרת, ונשר ההוא עמהם, שה״ס פני נשר, כשהגיעו לאלו בעלי המשנה, חזר נשר ההוא לצורת אדם, דהיינו לסוד פני אדם, בלבוש יקר המאיר, כמוהם, וישב עמהם יחד. אמר לאלו בעלי המשנה היושבים, תנו כבוד לבעלי המשנה שבאו כאן, כי אדונם מראה להם כאן נפלאות גדולות. אמר להם אחד מהם, יש לכם סימן, שאתם ראוים לכאן, אמרו כן. הוציאו ב׳ שושנים והריחו. שרמזו בזה על מלכות ובינה הכלולות יחד, בסוד ב׳ שושנים. אמרו, שבו ראשי הישיבה, שבו צדיקי אמת. אחזו בהם וישבו. באותה שעה, למדו מהם שלשים הלכות, שלא ידעו מקודם לכן, וסודות אחרים בתורה."],[6,"אהדרו לגבי אינון וכו׳:","חזרו לאלו בעלי המקרא, מצאו אותם שהיו אומרים, אני אמרתי אלקים אתם ובני עליון כולכם. היינו \u0003אני אמרתי\u0004 בשעה שהקדמתם נעשה לנשמע, שאלקים אתם וגו׳, כיון שנמשכתם אחר יצר הרע, \u0003אכן כאדם תמותון\u0004 וגו'. מה מיתתו של אדם מורידו לעפר, כדי שימחה היצר הרע שבגוף, ואותו יצר הרע הוא שמת, ונרקב בתוכו."]],[[0,"","אָמַר לָהֶם אוֹתוֹ מְמֻנֶּה, צְאוּ. יָצְאוּ עִמּוֹ. אָמַר לָהֶם, שְׁמַעְתֶּם דָּבָר לְתוֹךְ אוֹתָהּ דַּרְגָּה? אָמְרוּ, שָׁמַעְנוּ, שֶׁהֲרֵי קוֹל אֶחָד הָיָה אוֹמֵר: מִי שֶׁפָּסַק - יִפָּסֵק, וּמִי שֶׁקִּצֵּר - יִתְקַצֵּר. מִי שֶׁקִּצֵּר - יִתְאָרֵךְ. אָמַר לָהֶם, יְדַעְתֶּם מַה זֶּה? אָמְרוּ, לֹא. אָמַר לָהֶם, רְאִיתֶם אוֹתוֹ נֶשֶׁר גָּדוֹל וְאוֹתוֹ תִּינוֹק שֶׁמְּלַקֵּט עֲשָׂבִים? זֶה הָיָה רַבִּי אִילָאִי מִנְּצִיבִין, הוּא וּבְנוֹ, וְהִגִּיעַ לְכָאן, וְרָאָה הוּא וּבְנוֹ הַתִּינוֹק מְעָרָה זוֹ. כֵּיוָן שֶׁנִּכְנְסוּ לְתוֹךְ הַחֹשֶׁךְ, לֹא יָכְלוּ לִסְבֹּל, וּמֵתוּ."],[1,"","וְאוֹתוֹ תִּינוֹק בְּנוֹ עוֹמֵד כָּל יוֹם לִפְנֵי בְצַלְאֵל בְּשָׁעָה שֶׁיּוֹרֵד מֵהַיְשִׁיבָה הָעֶלְיוֹנָה, וְאוֹמֵר לְפָנָיו שְׁלֹשָׁה דְבָרִים, עַד שֶׁלֹּא יִפְתַּח בְּצַלְאֵל בְּסוֹדוֹת סְתוּמִים שֶׁל הַחָכְמָה, שֶׁכָּל דְּבָרָיו סוֹדוֹת סְתוּמִים הֵם, (ישעיה סד) שֶׁעַיִן לֹא רָאָתָה אֱלֹהִים זוּלָתְךְ. (מי) זֶה שֶׁאָמַר מִי שֶׁפָּסַק יִפָּסֵק. מִי שֶׁפּוֹסֵק דִּבְרֵי תוֹרָה עַל דְּבָרִים בְּטֵלִים, יִפָּסְקוּ חַיָּיו מֵהָעוֹלָם הַזֶּה, וְדִינוֹ עוֹמֵד בְּאוֹתוֹ עוֹלָם. מִי שֶׁקִּצֵּר יִתְקַצֵּר - מִי שֶׁקִּצֵּר אָמֵן וְלֹא מַאֲרִיךְ בּוֹ תּוֹךְ מְנוּחָה, יִתְקַצֵּר מֵחַיֵּי הָעוֹלָם הַזֶּה. מִי שֶׁקִּצֵּר יִתְאָרֵךְ - מִי שֶׁאוֹמֵר אֶחָד, צָרִיךְ לַחְטֹף אָלֶ\"ף וּלְקַצֵּר קְרִיאָתָהּ, וְלֹא יְעַכֵּב בָּאוֹת הַזֹּאת כְּלָל. מִי שֶׁעָשָׂה כֵּן, יִתְאָרְכוּ חַיָּיו."],[2,"","אָמְרוּ לוֹ, עוֹד אָמַר, שְׁנַיִם הֵם, וְאֶחָד הִשְׁתַּתֵּף בָּהֶם, וְהֵם שְׁלֹשָׁה. וּכְשֶׁהָיוּ שְׁלֹשָׁה, הֵם אֶחָד. אָמַר לָהֶם, אֵלֶּה שְׁנֵי שֵׁמוֹת שֶׁל שְׁמַע יִשְׂרָאֵל, שֶׁהֵם ה' ה'. אֱלֹהֵינוּ הִשְׁתַּתֵּף בָּהֶם, וְהוּא חוֹתַם הַטַּבַּעַת, אֱמֶת. וּכְשֶׁמִּתְחַבְּרִים כְּאֶחָד, הֵם אֶחָד בְּיִחוּד אֶחָד."],[3,"","עוֹד אָמַר, שְׁנַיִם הֵם, וְאֶחָד חָזַר. כְּשֶׁשּׁוֹלֵט, טָס עַל כַּנְפֵי הָרוּחַ וְשָׁט בְּמָאתַיִם אֶלֶף, וְנִסְתָּר. אָמַר לָהֶם, אֵלּוּ שְׁנֵי כְרוּבִים שֶׁהָיָה רוֹכֵב בָּהֶם הַקָּדוֹשׁ בָּרוּךְ הוּא. וּמִיּוֹם שֶׁנִּגְנַז יוֹסֵף מֵאֶחָיו, נִגְנַז הוּא (אחד), וְנִשְׁאַר אֶחָד אֵצֶל בִּנְיָמִין. זֶהוּ שֶׁכָּתוּב (תהלים יח) וַיִּרְכַּב עַל כְּרוּב וַיָּעֹף וַיֵּדֶא עַל כַּנְפֵי רוּחַ. וְנִגְנַז בְּמָאתַיִם אֶלֶף עוֹלָמוֹת, וְנִסְתַּר אוֹתוֹ שֶׁרוֹכֵב עָלָיו, שֶׁהֵם מָאתַיִם אֶלֶף גְּנָזִים, הֵם שֶׁלּוֹ בָּרוּךְ הוּא."],[4,"","צְאוּ מִכָּאן, אַשְׁרֵיכֶם. יָצְאוּ. נָתַן לָהֶם אוֹתוֹ מְמֻנֶּה שׁוֹשַׁנָּה (אחרת) אַחַת וְיָצְאוּ. כְּשֶׁיָּצְאוּ, נִסְתַּם פִּי הַמְּעָרָה וְלֹא נִרְאָה כְּלָל. רָאוּ אוֹתוֹ נֶשֶׁר שֶׁהָיָה יוֹרֵד מֵאוֹתוֹ עֵץ וְנִכְנַס לִמְעָרָה אַחֶרֶת. הֵרִיחוּ הֵם בְּאוֹתָהּ שׁוֹשַׁנָּה וְנִכְנְסוּ לְשָׁם, מָצְאוּ אוֹתוֹ נֶשֶׁר עַל פִּי הַמְּעָרָה. אָמַר לָהֶם, הִכָּנְסוּ צַדִּיקֵי אֱמֶת חֲבֵרִים, שֶׁהֲרֵי לֹא רָאִיתִי שִׂמְחַת הַחַבְרוּתָא מִיּוֹם שֶׁאֲנִי כָּאן, אֶלָּא בָכֶם."],[5,"","נִכְנְסוּ, הִגִּיעוּ לְפַרְדֵּס אַחֵר, וְאוֹתוֹ נֶשֶׁר עִמָּהֶם. כְּשֶׁהִגִּיעוּ לְאוֹתָם בַּעֲלֵי מִשְׁנָה, חָזַר אוֹתוֹ נֶשֶׁר בִּדְמוּת אָדָם בִּלְבוּשׁ נִכְבָּד מֵאִיר כְּמוֹתָם, וְיָשַׁב אִתָּם כְּאֶחָד. אָמַר לְאוֹתָם שֶׁיּוֹשְׁבִים, תְּנוּ כָבוֹד לְבַעֲלֵי הַמִּשְׁנָה שֶׁבָּאוּ לְכָאן, שֶׁהֲרֵי רִבּוֹנָם הֶרְאָה לָהֶם נִפְלָאוֹת גְּדוֹלוֹת כָּאן. אָמַר אֶחָד מֵהֶם, יֵשׁ בָּכֶם סִימָן? אָמְרוּ, הֵן. הוֹצִיאוּ שְׁנֵי שׁוֹשַׁנִּים וְהֵרִיחוּ בָהֶם. אָמְרוּ, שְׁבוּ בַּעֲלֵי הַיְשִׁיבָה, שְׁבוּ צַדִּיקֵי אֱמֶת. אָחֲזוּ בָהֶם וְיָשְׁבוּ. בְּאוֹתָהּ שָׁעָה לָמְדוּ שָׁם שְׁלֹשִׁים הֲלָכוֹת שֶׁלֹּא יָדְעוּ מִקֹּדֶם, וְסוֹדוֹת תּוֹרָה אֲחֵרִים."],[6,"","חָזְרוּ לִפְנֵי אוֹתָם בַּעֲלֵי מִקְרָא, וּמָצְאוּ שֶׁהָיוּ אוֹמְרִים, (שם פב) אֲנִי אָמַרְתִּי אֱלֹהִים אַתֶּם וּבְנֵי עֶלְיוֹן כֻּלְּכֶם. אֲנִי אָמַרְתִּי, בְּשָׁעָה שֶׁהִקְדַּמְתֶּם עֲשִׂיָּה לַשְּׁמִיעָה, שֶׁהֲרֵי אֱלֹהִים אַתֶּם וְגוֹ'. כֵּיוָן שֶׁנִּמְשַׁכְתֶּם אַחַר יֵצֶר הָרָע - אָכֵן כְּאָדָם תְּמוּתוּן וְגוֹ'. מַה מִּיתָתוֹ שֶׁל אָדָם מוֹרִידָתוֹ לֶעָפָר כְּדֵי שֶׁיִּמָּחֶה אוֹתוֹ יֵצֶר הָרָע שֶׁבְּתוֹכוֹ, וְאוֹתוֹ יֵצֶר הָרָע הוּא שֶׁמֵּת וְנִתְעַכֵּל בְּתוֹכוֹ."]]],[["אָמַר הַהוּא סָבָא דְּעָלַיְיהוּ, אוּף הָכָא כְּתִיב, וּפִגְרֵיכֶם אַתֶּם יִפְּלוּ בַּמִּדְבָּר הַזֶּה. מַאי פִּגְרֵיכֶם. דָּא יֵצֶר הָרָע, כָּלִיל דְּכַר וְנוּקְבָּא. חֶסְרוֹנִין דְּאִית בְּכוּ, דְּיֵצֶר הָרָע נָחִית תָּדִיר לְחֶסְרוֹנָא, וְלָא סָלִיק. בַּקֹּדֶשׁ מַעֲלִין וְלָא מוֹרִידִין, בִּמְסָאֲבוּ מוֹרִידִין תָּדִיר, וְלָא מַעֲלִין. וְעַל דָּא אִקְרוּן פִּגְרֵיכֶם, חֶסְרוֹנִין דִּלְכוֹן. כְּמָה דְאַתְּ אָמֵר (שמואל א ל׳:י׳) אֲשֶׁר פִּגְּרוּ מֵעֲבוֹר אֶת הַנַּחַל וְגוֹ', סוֹפָא דִּקְרָא אוֹכַח, דִּכְתִּיב יִפְּלוּ, וְלָא תִּפְּלוּ. וְעַל דָּא, בַּמִּדְבָּר הַזֶּה יִתַּמּוּ אִינּוּן פְּגָרִים וְשָׁם יָמוּתוּ, בְּגִין דִּרְעוּתָא דְקוּדְשָׁא בְּרִיךְ הוּא לְשֵׁיצָאָה לְהָנֵי פְּגָרִים מֵעָלְמָא, לְעָלַם.","אָמַר לְהוּ רִבִּי אִילָאִי, זַכָּאֵי קְשׁוֹט, עוּלוּ וְתֶחֱמוּ, דְּהָא רְשׁוּ אִתְמְסַר לְכוּ, לְמֵיעָל עַד הַהוּא אֲתָר דְּפָרוֹכְתָּא פְּרִיסָא. זַכָּאָה חוּלָקֵכוֹן. קָמוּ וְעָאלוּ גּוֹ דּוּכְתָּא חֲדָא, וַהֲווּ תַּמָּן מָארֵיהוֹן דְּאַגָּדָה, וְאַנְפֵּיהוֹן מְנַהֲרָן כִּנְהִירוּ דְּשִׁמְשָׁא. אָמְרוּ מַאן אִלֵּין. אָמַר לְהוֹן, אִלֵּין מָארֵיהוֹן דְּאַגָּדָה. וְחָמָאן בְּכָל יוֹמָא נְהִירוּ דְּאוֹרַיְיתָא כַּדְּקָא יֵאוֹת. קַיְימוּ, וּשְׁמָעוּ כַּמָה מִלִּין חַדְתִּין בְּאוֹרַיְיתָא, וְלָא אִתְיְהִיב לוֹן רְשׁוּ לְמֵיעַל לְגַוַיְיהוּ.","אָמַר לֵיהּ רִבִּי אִילָאִי, עוּלוּ לְדוּכְתָּא אַחֲרָא וְתֶחמוּ. עָאלוּ לְגוֹ גִּנְתָּא אַחֲרָא, וְחָמוּ אוּף הָכִי כָּרָאן קִבְרִין, וּמִיַּד מֵתִין. וּמִתְהַדְּרִין חַיִּין בְּגוּפִין מְנַהֲרָן קַדִּישִׁין. אָמְרֵי לֵיהּ, מַאי הַאי. אָמַר לֵיהּ, דָּא עַבְדֵּי בְּכָל יוֹמָא, וּמִיַּד דְּשַׁכְבֵי מִתְעַכְּלָא הַהוּא זוּהֲמָא בִּישָׁא דְּקַבִּילוּ בְּקַדְמִיתָא, וְקַיְימִין מִיַּד בְּגוּפִין חַדְתִּין מְנַהֲרִין, בְּאִינּוּן גּוּפִין קַדִּישִׁין דְּקַיְימֵי עַל טוּרָא דְּסִינַי, כְּגַוְונָא דְּאַתּוּן חָמָאן, קַיְימוּ כֻּלְּהוּ עַל טוּרָא דְּסִינַי, בְּגוּפִין בְּלָא לִכְלוּכָא כְּלַל, כֵּיוָן דְּאַמְשִׁיכוּ עָלַיְיהוּ יֵצֶר הָרָע, אִתְהֲדָרוּ בְּגוּפִין אַחֲרָנִין, דְּגוּפִין קַדְמָאִין, גּוּפִין נוּכְרָאִין, הֲדָא הוּא דִכְתִיב, (שמות ל״ג:ו׳) וַיִּתְנַצְּלוּ בְּנֵי יִשְׂרָאֵל אֶת עֶדְיָם מֵהַר חוֹרֶב.","קָלָא אִתְּעַר, זִילוּ אִתְכְּנָשׁוּ, הָא אָהֳלִיאָב קָאִים עַל קִיּוּמֵיהּ, וְכָל אִינּוּן קַתֶּדְרָאִין קַמֵּיהּ. לְשַׁעֲתָא פָּרְחוּ כֻּלְּהוּ, וְלָא חָמוּ מִדִי, אִשְׁתָּאֲרוּ בִּלְחוֹדַיְיהוּ תְּחוֹת אִילָנִין דְּגִּנְתָּא. חָמוּ פִּתְחָא אַחֲרָא, עָאלוּ תַּמָּן, חָמוּ הֵיכְלָא חֲדָא, עָאלוּ וְיָתִיבוּ תַּמָּן. תְּרֵין עוּלֵימִין הֲווֹ תַּמָּן. זָקְפוּ עַיְינִין, וְחָמוּ חַד מַשְׁכְּנָא מְרֻקְּמָא בְּכָל זִינֵי צִיּוּרִין וּגְוָונִין דְּעָלְמָא, וְעָלֵיהּ פְּרֵיס פְּרִיסָא דִּנְהוֹרָא מְנַצְּצָא, דְּלָא יַכְלִין עַיְינִין לְאִסְתַּכְּלָא (וכפון תרין מלין חמו גו ההוא משכנא עד אתר פרוכתא פריסא דלא חמו), מִתַּמָּן וּלְהָלְאָה לָא חָמוּ כְּלוּם.","אַרְכִּינוּ אוּדְנִין, וּשְׁמָעוּ חַד קָלָא דְּהֲוָה אָמַר, בְּצַלְאֵל רְבִיעָאָה אִיהוּ לִנְהוֹרִין עִלָּאִין. יוֹסֵף רְבִיעָאָה אִיהוּ גּוֹ נְהוֹרִין דְּאָדָם קַדְמָאָה. סְלִיקוּ דִּלְעֵילָּא, חֲבִיבָא דְּכֹלָּא. עָלֵיהּ כְּתִיב, (במדבר כ״ח:ה׳) וְנִסְכּוֹ רְבִיעִית הַהִין בַּקֹּדֶשׁ וְגוֹ'. מַאן דְּיִסְתָּכַּל וְחָמֵי, יִסְמוּן עֵינֵיהּ. מַאן דְּלָא יִסְתָּכַּל, חָמֵי וְאִתְפְּתַח. אִילָנָא דְּתַמְנֵי סְרֵי, כַּד כָּפִיף, יִזְקוֹף וְיִתְקְיַּים. אִי לָא כָּפִיף, חִוְיָא בִּישָׁא אָכִיל לֵיהּ. מַאן דְּעָאל תְּרֵין כְּרוּבִין לְגוֹ, רְעוּתֵיהּ אִתְעָבִיד. מַאן דִּמְעַיֵין, רָחִיק מֵרְעוּתֵיהּ. קָרְבְּנָא דְּרַבְיָא, שְׁלִים לְאִתְקַבְּלָא. פָּסַק הַהוּא קָלָא.","אָמְרוּ אִינּוּן תְּרֵין עוּלֵימִין, סִימָנָא אִית בְּגַּוַיְיכוּ. אָמְרוּ הִין. אַפִּיקוּ אִינּוּן תְּרֵין וְרָדִין, אַרְחוּ בְּהוּ, אָמְרוּ תִּיבוּ, עַד דְּתִשְׁמְעוּן תְּרֵין מִלִּין, בְּרָזִין עַתִּיקִין, מִגּוֹ מָארֵי מְתִיבְתָּא, וִיהוֹן תָּדִיר בְּרָזָא בְּגַוַּיְיכוּ. אָמְרוּ הֵן.","אָמַר רִבִּי שִׁמְעוֹן, כָּל הָנֵי מִלִּין, וְכָל מַה דְּחָמוּ, כַּתְבוּ. וְכַד מָטוּ הָכָא, הֲוָה כְּתִיב (תהילים ל״ט:ב׳) אֶשְׁמְרָה דְּרָכַי מֵחֲטוֹא בִלְשׁוֹנִי. וַאֲנָא שָׁאִילְנָא לַאֲבִי אַבָּא, כַּמָה הֲווֹ אִינּוּן תְּרֵין מִלִּין, וְאָמַר לִי חַיֶּיךָ בְּרִי, אִינּוּן תְּרֵין מִלִּין, בָּאנוּ עָלְמִין, וְחָרִיבוּ עָלְמִין, מַאן דְּאִשְׁתַּמָּשׁ בְּהוּ.","כֵּיוָן דְּשַׁמְעוּ אִלֵּין תְּרֵין מִילִּין, אָמְרוּ אִינּוּן יְנוּקֵי, פּוּקוּ פּוּקוּ, לֵית לְכוּ רְשׁוּתָא יַתִּיר לְמִשְׁמַע. אַפִּיק חַד מִנַּיְיהוּ, תַּפּוּחַ אֶחָד, וְיָהַב לוֹן. וְאָמַר, אַרְחוּ בְּדָא, אַרְחוּ בֵּיהּ, וְנַפְקוּ, וּמִכָּל דְּחָמוּ לָא אַנְשׁוּ כְּלוּם. נַפְקוּ.","הָא מְמָנָא אַחֲרָא, אָתָא אָמַר לוֹן, חַבְרַיָּיא, רִבִּי אִילָאִי שָׁדַרְנִי לְכוּ, תּוֹרֵיכוּ לֵיהּ הָכָא אַפּוּם מְעַרְתָּא, וְהוּא יֵיתֵי וְיוֹדַע לְכוּ מִלִּין עִלָּאִין דְּלָא יְדַעְתּוּן. דְּאִיהוּ תָּבַע מִגּוֹ מְתִיבְתָּא, דִּיהֵא לֵיהּ רְשׁוּ לְגַלָּאָה לְכוּ מִלִּין. נַפְקוּ בַּהֲדֵיהּ וְאוֹרִיכוּ אַפּוּם מְעַרְתָּא, וַהֲווּ מְהַדְרִין מִלֵּי דָּא לְדָא, מִכָּל מַה דְּחָמוּ וְאוֹלִפוּ תַּמָּן."],[[0,"אמר ההוא סבא וכו׳:","אמר הזקן שעליהם, אף כאן כתוב, ופגריכם אתם יפלו במדבר הזה ואם רק היצה״ר מת, מהו פגריכם, לשון רבים. הלא יצר הרע אחד הוא לכולם. ומשיב. יצר הרע הזה כלול זכר ונקבה. ופגריכם, פירושו, החסרונים שיש בכם, כי היצר הרע נקרא חסרון, משום שיורד תמיד למקום החסרון שבאדם, ואינו עולה. בקדש מעלים ולא מורידים. בטומאה מורידים תמיד ולא מעלים. וע״כ נקרא יצה\"ר \u0003פגריכם,\u0004 דהיינו החסרונים שבכם. כש״א אשר \u0003פגרו\u0004 מעבור את הנחל וגו'. וסוף הפסוק מוכיח שסובב על יצה״ר, שכתוב יפלו, ולא כתוב תפלו. וע\"כ במדבר הזה יתמו אלו הפגרים, דהיינו יצה״ר, ושם ימותו, משום שרצון הקב״ה לכלות אלו הפגרים מן העולם, לתמיד."],[1,"אמר להו ר׳ אילאי וכו׳:","א\"ל ר׳ אילאי, צדיקי אמת הכנסו ותראו, כי רשות נמסר לכם ללכת עד מקום ההוא שהפרוכת פרושה. אשרי חלקכם. קמו ונכנסו במקום אחד, והיו שם בעלי אגדה, ופניהם מאירים כאור השמש. אמרו, מי הם. אמר להם, הם בעלי אגדה, ורואים בכל יום אור התורה כראוי. עמדו ושמעו כמה דברים חדשים בתורה, ולא ניתנה להם רשות לכנוס להם."],[2,"א״ל ר׳ אילאי וכו׳:","אמר להם ר״א, הכנסו למקום אחר ותראו. באו לתוך גן אחר, וראו גם כן דהיינו חוץ מדברים אחרים שראו, שחופרים קברים, ומיד מתים ואח״כ חוזרים חיים בגופים קדושים מאירים. שהם היו מתי מדבר (כמ״ש להלן אות קי״א). אמרו לו מה זה. א\"ל הם עושים זה בכל יום, וכשמתים מיד נרקב זוהמא הרעה שקבלו בתחילה ועומדים מיד בגופים חדשים מאירים. באלו גופים הקדושים, שהיה להם בעמדם על הר סיני, כמו שאתם רואים אותם. כי עמדו כולם על הר סיני בגופים בלי לכלוך כלל, כיון שהמשיכו עליהם היצר הרע, חזרו בגופים אחרים כגופים שהיו להם מקודם לכן, גופים זרים, דהיינו שחזר בהם זוהמת הנחש. ז״ש ויתנצלו בני ישראל את עדים מהר חורב. (ועי׳ להלן אות קכ״ז)."],[3,"קלא אתער זילו וכו׳:","קול התעורר ואמר, לכו התאספו, הנה אהליאב עומד על מעמדו, וכל אלו הכסאות לפניו. כרגע פרחו כולם ולא ראו כלום. נשארו לבדם תחת אילנות הגן. ראו פתח אחר. נכנסו שם. ראו היכל אחד. נכנסו וישבו שם. שני עלמים היו שמה. נשאו עיניהם וראו משכן אחד מרוקם בכל מיני ציורים וצבעים שבעולם, ועליו פרוש פרשת אור מנוצץ, שהעינים לא שלטו להסתכל. משם ולהלאה לא ראו כלום."],[4,"ארכינו אודנין ושמעו וכו׳:","הטו אזנים ושמעו קול אחד שהיה אומר, בצלאל הוא רביעי לאורות עליונים. יוסף רביעי הוא באורות של אדם הראשון. הוא עליה שלמעלה, החביב מכל. עליו כתוב, ונסכו רביעית ההין בקדש וגו'. מי שמסתכל ורואה יתעוורו עיניו. מי שאינו מסתכל, יהיה נפקח ויראה. אילן של שמונה עשר כשכופף עצמו יהיה זקוף ויתקיים. אם אינו כופף עצמו, נחש הרע יאכל אותו. מי שנכנס ב׳ כרובים לפנים, רצונו נעשה. מי שמעיין, הוא רחוק מרצונו. קרבנו של נער הוא שלם להתקבל. ונפסק אותו הקול. (כל דברים אלו מתבארים בזהר עצמו להלאה, (מאות קכ״ז עד אות רל״ב)."],[5,"אמרו אינון תרין וכו׳:","אמרו אלו שני עלמים, יש סימן בכם. אמרו כן. הוציאו אלו ב׳ שושנים והריחו בהם. אמרו שבו, עד שתשמעו שני דברים בסודות עתיקים, מראש הישיבה, ויהיו אצלכם בסוד תמיד. אמרו כן."],[6,"אמר ר׳ שמעון וכו׳:","אר״ש, כל אלו הדברים, וכל מה שראו כתבו, וכשהגיעו כאן, שאמרו להם שהדברים יהיו שמורים אצלם בסוד, היה כתוב, כלומר שכתבו עליהם, אשמרה דרכי מחטוא בלשוני. ואני שאלתי לאבי, אבי, במה היו אלו ב׳ דברים. ואמר לי, חייך בני, שאלו ב׳ דברים, בנו עולמות והחריבו עולמות, למי שהשתמש בהם."],[7,"כיון דשמעו אלין וכו׳:","כיון ששמעו אלו שני דברים, אמרו אלו העלמים, צאו צאו, אין לכם רשות לשמוע יותר. הוציא אחד מהם תפוח אחד, ונתן להם, ואמר הריחו בזה. הריחו בו, ויצאו. ומכל מה שראו לא שכחו כלום. יצאו."],[8,"הא ממנא אחרא וכו׳:","והנה בא ממונה אחר, אמר להם, חברים, ר׳ אילאי שלח אותי לכם, תמתינו לו כאן על פי המערה, והוא יבא ויודיע לכם דברים עליונים שלא ידעתם. שבקש מן הישיבה, שתהיה לו רשות לגלות לכם הדברים. יצאו עמו והמתינו על פי המערה והיו חוזרים על הדברים זה לזה, מכל מה שראו ולמדו שם."]],[[0,"","אָמַר אוֹתוֹ זָקֵן שֶׁעֲלֵיהֶם, גַּם כָּךְ כָּתוּב, וּפִגְרֵיכֶם אַתֶּם יִפְּלוּ בַּמִּדְבָּר הַזֶּה. מַה זֶּה פִּגְרֵיכֶם? זֶה יֵצֶר הָרָע, כּוֹלֵל זָכָר וּנְקֵבָה. חֶסְרוֹנוֹת שֶׁיֵּשׁ בָּכֶם, שֶׁיֵּצֶר הָרָע יוֹרֵד תָּמִיד לְחִסָּרוֹן, וְלֹא עוֹלֶה. בַּקֹּדֶשׁ מַעֲלִים וְלֹא מוֹרִידִים. בַּטֻּמְאָה מוֹרִידִים תָּמִיד וְלֹא מַעֲלִים. וְעַל זֶה נִקְרְאוּ פִגְרֵיכֶם, חֶסְרוֹנוֹתֵיכֶם, כְּמוֹ שֶׁנֶּאֱמַר (שמואל א ל) אֲשֶׁר פִּגְּרוּ מֵעֲבֹר אֶת (ה) נַּחַל וְגוֹ'. סוֹף הַפָּסוּק מוֹכִיחַ, שֶׁכָּתוּב יִפְּלוּ, וְלֹא תִפְּלוּ. וְעַל כָּךְ, בַּמִּדְבָּר הַזֶּה יִתַּמּוּ אוֹתָם פְּגָרִים וְשָׁם יָמוּתוּ, מִשּׁוּם שֶׁרְצוֹן הַקָּדוֹשׁ בָּרוּךְ הוּא לְהַשְׁמִיד אוֹתָם פְּגָרִים מֵהָעוֹלָם לְעוֹלָם."],[1,"","אָמַר לָהֶם רַבִּי אִילָאִי, צַדִּיקֵי אֱמֶת, הִכָּנְסוּ וּרְאוּ, שֶׁהֲרֵי רְשׁוּת נִמְסְרָה לָכֶם לְהִכָּנֵס עַד אוֹתוֹ מָקוֹם שֶׁפָּרֹכֶת פְּרוּסָה. אַשְׁרֵי חֶלְקְכֶם. קָמוּ וְנִכְנְסוּ לְתוֹךְ מָקוֹם אֶחָד, וְהָיוּ שָׁם בַּעֲלֵי אַגָּדָה, וּפְנֵיהֶם מְאִירִים כְּאוֹר הַשֶּׁמֶשׁ. אָמְרוּ, מִי אֵלֶּה? אָמַר לָהֶם, אֵלֶּה בַּעֲלֵי אַגָּדָה, וְרוֹאִים בְּכָל יוֹם אוֹר הַתּוֹרָה כָּרָאוּי. עָמְדוּ וְשָׁמְעוּ כַּמָּה דְבָרִים חֲדָשִׁים בַּתּוֹרָה, וְלֹא נִתְּנָה לָהֶם רְשׁוּת לְהִכָּנֵס לְתוֹכָם."],[2,"","אָמַר לָהֶם רַבִּי אִילָאִי, הִכָּנְסוּ לְמָקוֹם אַחֵר וְתִרְאוּ. נִכְנְסוּ לְתוֹךְ גִּנָּה אַחֶרֶת, וְרָאוּ גַם כָּךְ כּוֹרִים קְבָרִים, וּמִיָּד מֵתִים, וְחוֹזְרִים חַיִּים בְּגוּפוֹת מְאִירִים קְדוֹשִׁים. אָמְרוּ לוֹ, מַה זֶּה? אָמַר לָהֶם, זֶה עוֹשִׂים בְּכָל יוֹם, וּמִיָּד שֶׁשּׁוֹכְבִים, מִתְעַכֶּלֶת אוֹתָהּ זֻהֲמָה רָעָה שֶׁקִּבְּלוּ בַתְּחִלָּה, וְעוֹמְדִים מִיָּד בְּגוּפִים חֲדָשִׁים מְאִירִים, בְּאוֹתָם גּוּפִים קְדוֹשִׁים שֶׁעָמְדוּ עַל הַר סִינַי, כְּמוֹ שֶׁאַתֶּם רוֹאִים, עָמְדוּ כֻלָּם עַל הַר סִינַי בְּגוּפִים לְלֹא לִכְלוּךְ כְּלָל. כֵּיוָן שֶׁהִמְשִׁיכוּ עֲלֵיהֶם יֵצֶר הָרָע, חָזְרוּ בְגוּפִים אֲחֵרִים שֶׁל גּוּפִים רִאשׁוֹנִים, גּוּפִים נָכְרִיִּים, זֶהוּ שֶׁכָּתוּב (שמות לג) וַיִּתְנַצְּלוּ בְנֵי יִשְׂרָאֵל אֶת עֶדְיָם מֵהַר חוֹרֵב."],[3,"","קוֹל הִתְעוֹרֵר: לְכוּ הִתְכַּנְּסוּ, הֲרֵי אָהֳלִיאָב עוֹמֵד עַל עָמְדוֹ, וְכָל אוֹתָן קָתֶדְרָאוֹת עִמּוֹ. לְשָׁעָה פָּרְחוּ כֻלָּם וְלֹא רָאוּ דָבָר. נִשְׁאֲרוּ לְבַד תַּחַת אִילָנוֹת הַגִּנָּה. רָאוּ פֶּתַח אַחֵר, נִכְנְסוּ לְשָׁם, רָאוּ הֵיכָל אֶחָד, נִכְנְסוּ וְיָשְׁבוּ שָׁם. שְׁנֵי עֲלָמִים הָיוּ שָׁם. הֵרִימוּ עֵינַיִם, וְרָאוּ מִשְׁכָּן אֶחָד מְרֻקָּם בְּכָל מִינֵי צִיּוּרִים וּגְוָנִים שֶׁל הָעוֹלָם, וְעָלָיו פְּרוּסָה פְּרִיסַת אוֹר נוֹצֶצֶת שֶׁלֹּא יְכוֹלוֹת הָעֵינַיִם לְהִסְתַּכֵּל. (וכפי שני מילין ראו תוך אותו המשכן עד מקום פריסת הפרכת שלא ראו) מִשָּׁם וָהָלְאָה לֹא רָאוּ כְלוּם."],[4,"","הִרְכִּינוּ אָזְנַיִם, וְשָׁמְעוּ קוֹל אֶחָד שֶׁהָיָה אוֹמֵר: בְּצַלְאֵל רְבִיעִי הוּא לְאוֹרוֹת עֶלְיוֹנִים. יוֹסֵף רְבִיעִי הוּא תּוֹךְ אוֹרוֹת אָדָם הָרִאשׁוֹן. עֲלִיָּה שֶׁל מַעְלָה חֲבִיבַת הַכֹּל, עָלֶיהָ כָּתוּב (במדבר כח) וְנִסְכּוֹ רְבִיעִית הַהִין בַּקֹּדֶשׁ וְגוֹ'. מִי שֶׁיִּסְתַּכֵּל וְיִרְאֶה, יִסָּמְאוּ עֵינָיו. מִי שֶׁלֹּא יִסְתַּכֵּל, יִרְאֶה וְיִפָּתְחוּ עֵינָיו. עֵץ שֶׁל שְׁמֹנֶה עֶשְׂרֵה, כְּשֶׁמִּתְכּוֹפֵף, יִזְקֹף וְיַעֲמֹד. אִם לֹא מִתְכּוֹפֵף, נָחָשׁ רַע יֹאכַל אוֹתוֹ. מִי שֶׁמַּכְנִיס שְׁנֵי כְרוּבִים לִפְנִים, רְצוֹנוֹ יֵעָשֶׂה. מִי שֶׁמְּעַיֵּן רָחוֹק מֵרְצוֹנוֹ, קָרְבַּן הַתִּינוֹק שָׁלֵם לְהִתְקַבֵּל. פָּסַק אוֹתוֹ הַקּוֹל."],[5,"","אָמְרוּ אוֹתָם שְׁנֵי עֲלָמִים, סִימָן יֵשׁ בָּכֶם? אָמְרוּ, הֵן. הוֹצִיאוּ שְׁנֵי שׁוֹשַׁנִּים וְהֵרִיחוּ בָהֶם. אָמְרוּ, שְׁבוּ עַד שֶׁתִּשְׁמְעוּ שְׁנֵי דְבָרִים בְּסוֹדוֹת עַתִּיקִים מִתּוֹךְ רָאשֵׁי הַיְשִׁיבָה, וְיִהְיוּ תָמִיד בְּסוֹד בְּתוֹכֲכֶם. אָמְרוּ, הֵן."],[6,"","אָמַר רַבִּי שִׁמְעוֹן, כָּל הַדְּבָרִים הַלָּלוּ וְכָל מַה שֶּׁרָאוּ, כָּתְבוּ. וּכְשֶׁהִגִּיעוּ לְכָאן, הָיָה כָּתוּב (תהלים לט) אֶשְׁמְרָה דְרָכַי מֵחֲטוֹא בִלְשׁוֹנִי. וַאֲנִי שָׁאַלְתִּי לַאֲבִי אַבָּא, כַּמָּה הָיוּ אוֹתָם שְׁנֵי דְבָרִים? וְאָמַר לִי, חַיֶּיךְ בְּנִי, אוֹתָם שְׁנֵי דְבָרִים בָּנוּ עוֹלָמוֹת וְהֶחֱרִיבוּ עוֹלָמוֹת מִי שֶׁהִשְׁתַּמֵּשׁ בָּהֶם."],[7,"","כֵּיוָן שֶׁשָּׁמְעוּ שְׁנֵי דְבָרִים אֵלּוּ, אָמְרוּ אוֹתָם תִּינוֹקוֹת, צְאוּ צְאוּ! אֵין לָכֶם רְשׁוּת יוֹתֵר לִשְׁמֹעַ! הוֹצִיא אֶחָד מֵהֶם תַּפּוּחַ אֶחָד, וְנָתַן לָהֶם וְאָמַר, הָרִיחוּ בָזֶה, הָרִיחוּ בוֹ. וְיָצְאוּ, וּמִכָּל מַה שֶּׁרָאוּ לֹא שָׁכְחוּ כְלוּם. יָצְאוּ."],[8,"","הֲרֵי מְמֻנֶּה אַחֵר בָּא וְאָמַר לָהֶם, חֲבֵרִים, רַבִּי אִילָאִי שְׁלָחַנִי אֲלֵיכֶם, חַכּוּ לִי כָּאן עַל פִּי הַמְּעָרָה, וְהוּא יָבֹא וְיוֹדִיעַ לָכֶם דְּבָרִים עֶלְיוֹנִים שֶׁלֹּא יְדַעְתֶּם. שֶׁהוּא תָּבַע מִתּוֹךְ הַיְשִׁיבָה שֶׁיִּהְיֶה לוֹ רְשׁוּת לְגַלּוֹת לָכֶם דְּבָרִים. יָצְאוּ אִתּוֹ וְחִכּוּ עַל פִּי הַמְּעָרָה, וְהָיוּ מַחֲזִירִים דְּבָרִים זֶה לָזֶה מִכָּל מַה שֶּׁרָאוּ וְלָמְדוּ שָׁם."]]],[["אַדְּהָכִי, הָא רִבִּי אִילָאִי אָתָא, נָהִיר כְּשִׁמְשָׁא. אָמַר לֵיהּ אוֹרַיְיתָא חַדְתָּא שְׁמַעְתָּא. אָמַר לוֹן וַדַּאי, וּרְשׁוּ יָהֲבוּ לִי לְמֵימַר לְכוּ מִלֵּי. אִתְחַבְּרָא כַּחֲדָא אַפּוּם מְעַרְתָּא, וְיָתְבוּ. אָמַר לוֹן זַכָּאִין אַתּוּן, דְּאַחְמֵי לְכוֹן מָארֵיכוֹן כְּגַוְונָא דְּעָלְמָא דְּאָתֵי, וְהָא לֵית לְכוּ דְּחִילוּ וְאֶמְתָּנוּ, אָמְרוּ וַדַּאי הָא אִתְנְשֵׁי מִנָן אָרְחָא דִּבְנֵי נָשָׁא, וּתַוָּוהָא אִיהוּ עַל כָּל מַה דַּחֲמֵינָן בְּהַאי טוּרָא.","אָמַר לוֹן, חֲמִיתּוּן אִלֵּין טוּרַיָּא, כֻּלְּהוּ רָאשֵׁי מְתִיבְתֵּי לְעַמָּא דָּא דִּבְמַדְבְּרָא. וְזָכוּ הַשְׁתָּא, מַה דְּלָא זָכוּ כַּד הֲווֹ בַּחַיִּין. וְאִלֵּין רֵישֵּׁי מְתִיבְתֵּי, כֻּלְּהוּ בְּרֵישׁ יַרְחֵי וְשַׁבַּתֵּי וּמוֹעֲדַיָּיא, מִתְכַּנְּשֵׁי לְגַבֵּי טוּרָא דְּאַהֲרֹן כַּהֲנָא, וּמִתְעָרֵי לְגַבֵּיהּ, וְעָאלִין גּוֹ מְתִיבְתָּא דִּילֵיהּ, וּמִתְחַדְּשָׁן תַּמָּן, בְּדַכְיוּ דְּטַלָא קַדִּישָׁא דְּנָחִית עַל רֵישֵׁיהּ, וּמְשַׁח רְבוּ דְּנָגִיד עָלֵיהּ, וְעִמֵּיהּ מִתְחַדְּשָׁן כֻּלְּהוּ בְּחִדּוּשִׁין דִּרְחִימִין דְּמַלְכָּא קַדִּישָׁא, עַד דְּאִקְרֵי הָכָא מְתִיבְתָּא דִּרְחִימוּתָא.","וְאִיהוּ נָטִיל בְּכָל מְתִיבְתָּא, בִּטְמִירוּ דָּקִיק מִתְעָפְפָן כְּנִשְׁרִין גּוֹ מְתִיבְתָּא דִּנְהוֹרָא, וְאִיהִי מְתִיבְתָּא דְּמֹשֶׁה, וְכֻלְּהוּ קַיְימֵי לְבַר, וְלָא עָאלִין לְגוֹ, בַּר אַהֲרֹן בִּלְחוֹדוֹי וּכְפוּם שַׁעֲתָא אִקְרוּן בִּשְׁמָא.","וְלֵית מַאן דְּחָמֵי לֵיהּ לְמֹשֶׁה, דְּהָא הַהוּא מַסְוְה דְּאַנְפּוֹי, פְּרֵיס קָמֵיהּ. וּשְׁבַע עֲנָנֵי יְקָר סַחֲרָנֵיהּ. אַהֲרֹן קָאִים גּוֹ פַּרְגּוֹדָא דִּלְתַּתָּא מִן מֹשֶׁה. וּפַרְגּוֹדָא פָּסִיק, וְלָא פָּסִיק בְּגַּוַּיְיהוּ. וְכָל רֵישֵּׁי מְתִיבְתֵּי, לְבַר מִפָּרוֹכְתָּא דְּפַרְגּוֹדָא דָּא. וְכָל שְׁאָר, לְבַר מֵאִינּוּן עֲנָנִין. וּכְפוּם חִדּוּשֵׁי דִּנְהִירוּ דְּאוֹרַיְיתָא דְּאִתְנַהֲרָא, הָכִי מְנָהֲרָן אִינּוּן עֲנָנִין.","וְאִתְקְלִישׁוּ בִּדְקִיקוּ דִּנְהוֹרָא, עַד דְּאִתְחֲזֵי הַהוּא מַסְוְה, וּמִגּוֹ הַהוּא מַסְוְה, חָמָאן נְהוֹרָא דְּנָהִיר יַתִּיר מִכָּל נְהִירִין דְּעָלְמָא. וְאִינּוּן אַנְפֵּי מֹשֶׁה. אַנְפּוֹי לָא אִתְחָזוּן כְּלָל, וְלֵית מַאן דְּחָמֵי לוֹן, בַּר הַהוּא נְהִירוּ דְּנָפִיק מִגּוֹ הַהוּא מַסְוְה, בָּתַר כָּל אִינּוּן עֲנָנִין.","מֹשֶׁה אָמַר מִלָּה סְתָם לְאַהֲרֹן, וְאַהֲרֹן פָּרִישׁ לְרַבְרְבֵי מְתִיבְתֵּי. בְּמַה פָּרִישׁ. בְּכָל אִינּוּן מַבּוּעִין דְּאַסְתִּימוּ מִנֵּיהּ, כַּד מָטָא זִמְנֵיהּ דִּיהוֹשֻׁעַ. וְהַשְּׁתָּא אִיהוּ מְהָדָר לוֹן. בְּכַמָּה פְּלִיאָן, וּמְקוֹרִין וּמַבּוּעִין וּנְחָלִין דְּנַבְעִין מִכָּל מִלָּה וּמִלָּה.","כָּל נָשִׁין זַכְיָין דְּהַאי דָּרָא, אָתָאן לְמִרְיָם אוּף הָכָא בְּהָנֵי זִמְנִין. וּכְדֵין סַלְּקִין כֻּלְּהוּ, כְּתִמְרוֹת עָשָׁן גּוֹ מַדְבְּרָא דָּא. וְהַהוּא יוֹמָא, אִקְרֵי יוֹמָא דְּהִלּוּלָא. נָשִׁין בְּלֵילֵי שַׁבָּתוֹת וּבְלֵילֵי יוֹמִין טָבִין, כֻּלְּהוּ אָתָאן לְגַבֵּי מִרְיָם, וְיַדְעִין אִשְׁתַּדְּלוּתָא בִּידִיעָה דְּמָארֵי עָלְמָא. זַכָּאָה דָּרָא דָּא, מִכָּל דָּרִין דְּעָלְמָא. נַפְקֵי מִמְּתִיבְתָּא דְּמֹשֶׁה, וּפַרְחֵי לְגַבֵּי מְתִיבְתָּא דִּרְקִיעָא, וְאִינּוּן דְּאִתְחָזוּן פַּרְחֵי לְגַבֵּי מְתִיבְתָּא עִלָּאָה. עַל הַהוּא דָּרָא כְּתִיב, (תהילים קמ״ד:ט״ו) אַשְׁרֵי הָעָם שֶׁכָּכָה לוֹ אַשְׁרֵי הָעָם שֶׁיְיָ אֱלֹהָיו.","פָּתַח רִבִּי אִילָאִי וְאָמַר, (דברים י״ח:י״ג) תָּמִים תִּהְיֶה עִם יְיָ אֱלֹהֶיךָ. מַה בֵּין תָּם לְתָמִים. בְאַבְרָהָם כְּתִיב, (בראשית י״ז:א׳) הִתְהַלֵּךְ לְפָנַי וְהְיֵה תָמִים. יַעֲקֹב דְּאִשְׁתְּלִים יַתִּיר, כְּתִיב בֵּיהּ, (בראשית כ״ה:כ״ז) וְיַעֲקֹב אִישׁ תָּם. אֲמַאי אִקְרֵי אִישׁ תָּם. בְּגִין דְּלָא אִשְׁתְּאַר בֵּיהּ פְּסוֹלֶת כְּלַל, דְּהָא פְּרִיעָה הֲוָה בֵּיהּ.","בְּמָה אִתְפְּרַע, (ס\"א פריעה הוה ביה דאתפרע) וְאִתְדַכֵּי מֵהַהוּא פְּסוֹלֶת בְּגִין דְּהַהוּא אֲתָר דְּאַתְקִיף לִפְסוֹלֶת, דִּלְגוֹ אֲתָר דִּפְרִיעָה שָׁארֵי, אִיהוּ שׁוֹר, דִּיּוּקְנָא דִּשְׂמָאלָא דְּכֻרְסַיָא דִּילֵיהּ. וְהַהוּא שׁוֹר, אִקְרֵי שׁוֹר תָּם. דְּהָא רְתִיכָא דְּכֻרְסְיָא, רְשִׁימָא דִּבְרִית אִית בֵּיהּ. וְעַל דָּא, הַאי שׁוֹר אִקְרֵי תָּם. וְיַעֲקֹב אָחִיד בֵּיהּ בְּגַוִּויהּ, וּבְהַאי שׁוֹר עָבִיד פְּרִיעָה, וְאַעְבַּר זוּהֲמָא דִּפְסּוֹלֶת כֻּלָּא.","בְּמַתְנִיתָא דִּבְצַלְאֵל כְּתִיב, (בראשית ל׳:כ״ב) וַיִּזְכּוֹר אֱלֹהִים אֶת רָחֵל. בְּשָׂרָה כְּתִיב (בראשית כא) פְּקִידָה, וּבְרָחֵל כְּתִיב זְכִירָה, אֲמַאי. בְּגִין דְּזָכוֹר אִתְרְשִׁים בְּיַעֲקֹב, דְּאִיהוּ בְּרִית שְׁלִים, כַּד (אתעביד) אִתְיְילִיד יוֹסֵף. וּבְמָּה. כַּד נָטַל שׁוֹר בַּהֲדֵיהּ, דְּלָא יַתְקִיף לְסִטְרָא אַחֲרָא. וּבְגִין כָּךְ, אִתְקְרֵי יוֹסֵף (דברים ל״ג:י״ז) בְּכוֹר שׁוֹר, בְּכוֹר דְּהַהוּא שׁוֹר דְּנָטַל יַעֲקֹב בְּכוֹר שׁוֹרוֹ, (ודחי לההוא שור)."],[[0,"אדהכי הא ר׳ אילאי וכו׳:","בתוך כך בא ר׳ אילאי, והיה מאיר כשמש. אמרו לו תורה חדשה שמעת. אמר להם ודאי, ויש לי רשות לומר לכם הדברים. נתחברו יחד על פי המערה וישבו. אמר להם, אשרי לכם שהראה לכם אדוניכם, מעין עולם הבא, ואין עליכם פחד ואימה. אמרו לו, ודאי כבר נשכח ממנו דרך בני אדם, ופליאה היא על כל מה שראינו בהר הזה."],[1,"אמר לון המיתון וכו׳:","אמר להם, ראיתם אלו ההרים, כולם הם ראשי ישיבות לעם הזה של מתי מדבר, וזכו עתה, מה שלא זכו כשהיו בחיים, ואלו ראשי הישיבות מתאספים כולם, בר״ח ושבתות ומועדים, אל ההר של אהרן הכהן, ומתעוררים אליו, ונכנסים לישיבה שלו, והם מתחדשים שם בטהרת הטל הקדוש שיורד על ראשו של אהרן, ושמן המשחה היורד עליו, ועמו מתחדשים כולם בחדושים של אהבת המלך הקדוש, עד שנקרא כאן ישיבה של אהבה."],[2,"ואיהו נטיל בכל וכו׳:","והוא, אהרן, נוסע עם כל הישיבה, ובסתר ודקות מתעופפים כנשרים אל הישיבה של האור, והיא הישיבה של משה. כולם עומדים בחוץ ואינם נכנסים חוץ מאהרן בלבד, אלא שנקראים בשם כפי השעה, דהיינו בשבת וחדש."],[3,"ולית מאן דחמי וכו׳:","ואין מי¬ שיראה את משה, כי מסוה ההוא שעל פניו פרושה עליו, וז׳ ענני כבוד סביב לו. אהרן עומד תוך הפרגוד, שהיא מחיצה, שלמטה ממשה, והפרגוד פוסק ביניהם ואינו פוסק ביניהם. כלומר שאינו הפסק גמור. וכל ראשי הישיבות הם לחוץ מן הפרכת, שהוא הפרגוד הזה. כלומר שבעצם הוא מפסיק גמור. וכל שאר החכמים, הם לחוץ מאלו ז׳ עננים המקיפים עליו. וכפי חידושי הארות התורה שהאירה, כך מאירים אלו העננים."],[4,"ואתקלישו בדקיקו וכו׳:","ונזדככו בדקות האור, עד שנראה להם המסוה של משה, ומתוך מסוה ההוא היו רואים אור המאיר יותר מכל האורות שבעולם. והוא דהיינו המסוה, הוא הפנים של משה, כי פניו אינם נראים כלל, ואין מי שיראה אותם, חוץ מאותו האור היוצא מן המסוה, מאחורי כל אלו העננים."],[5,"משה אמר מלה וכו׳:","משה אמר הדבר אל אהרן בסתם, שלא פירשו, ואהרן פירשו לראשי הישיבות. במה פירש הדברים. היינו בכל אלו המבועים, דהיינו המדרגות, שנסתמו מיהושע וכל ישראל, כשהגיע זמנו של יהושע לנהוג הדור, דהיינו שנסתמו לו ג׳ מאות הלכות וז׳ מאות ספקות (תמורה טז.) ועתה, היה משה מחזיר אותם להם, בכמה פליאות ומקורות ומבועים ונחלים, הנובעים מכל דבר ודבר."],[6,"כל נשין זכיין וכו׳:","כל נשים הצדקניות של אותו הדור, דהיינו דור המדבר, באים גם כן למרים באלו הזמנים, ואז עולות כולן אליה כתמרות עשן מתוך המדבר הזה, ויום ההוא נקרא יום השמחה. בלילי שבתות וימים טובים באים הנשים כולן אל מרים, ועוסקות בהשתדלות בידיעת רבון העולם. אשרי דור הזה, דהיינו דור המדבר, מכל הדורות שבעולם. יוצאים מן הישיבה של משה ופורחים אל הישיבה של הרקיע, שהוא ישיבת מטטרון. ואלו הראוים, פורחים אל הישיבה העליונה, שהוא הישיבה של הקב״ה. על דור ההוא כתוב, אשרי העם שככה לו אשרי העם שה׳ אלקיו."],[7,"פתח ר׳ אילאי וכו׳:","פר״א, ואמר, תמים תהיה עם ה׳ אלקיך. שואל, מה בין תם לתמים. ומשיב, באברהם כתוב, התהלך לפני והיה \u0003תמים.\u0004 יעקב שנשלם יותר, כתוב בו ויעקב איש \u0003תם.\u0004 למה נקרא איש תם, משום שלא נשאר בו פסולת כלום, כי היה בו פריעה."],[8,"במה אתפרע ואתדכי וכו׳:","שואל, במה עשה פריעה, ונטהר מאותו פסולת. ומשיב, כי אותו מקום המתקיף את הפסולת שבפנים, הנמצאת במקום שהפריעה שורה, הוא שור, שהוא צורת השמאל של הכסא שלו, כי יש בהמרכבה של הכסא, פני אריה אל הימין ופני שור מהשמאל. ושור ההוא נקרא שור תם, כי המרכבה של הכסא, יש בה רושם הברית, ומשום זה נקרא שור הזה שור תם. ויעקב אחוז בו בתוכו, ובשור הזה עשה פריעה, והעביר הזוהמא של הפסולת לגמרי."],[8,"","פירוש בסיום פרצוף הקדושה, דהיינו ביסוד שהוא סיומא דגופא, דבוקים הקליפות. והם ד׳ קליפות, רוח סערה, וענן גדול, ואש מתלקחת, ונוגה. אשר ג׳ קליפות הראשונות הם טמאות לגמרי, והם נכללים בעור הא' הנקרא ערלה, הנחתך ונשלך לעפר. וקליפה הד' שהיא נגה, היא טמאה בעוד שג׳ הקליפות דבוקים בה, ואחר שמסירים ממנה ג׳ הקליפות היא חוזרת לקדושה. וה״ס עור הב' הנקרא עור הפריעה. שלאחר שחותכים ממנה הערלה, שה״ס ג׳ קליפות הטמאות היא חוזרת לקדושה, דהיינו גוף הפרצוף. אמנם נשאר בו זוהמא ופסולת מזמן שהערלה היתה דבוקה בה. וכדי להסיר ממנו הזוהמא והפסולת צריכים לקרוע העור ולהשימו לצדדין, שבקריעה ופריעה זו מתבטל ממנו כל הפסולת. ועתה, הוא שלם בקדושה. וע״כ צריכים \u0003למילה,\u0004 שה״ס הרחקת הס״א כולה. \u0003ולפריעה,\u0004 שה״ס נקוי הפסולת והזוהמא שנשארה בעור הפריעה. ואז מתגלים המוחין בשלמות. וז״ש, \u0003ויעקב איש תם, אמאי אקרי איש תם בגין דלא אשתאר ביה פסולת כלל, דהא פריעה הוה ביה,\u0004 כי הפריעה מנקה ומסיר \u0003הפסולת\u0004 הנשאר בעור הפריעה מזוהמת ג׳ קליפות הטמאות שנבלעה בה מטרם שחתכו אותן. ואז נקרא איש \u0003תם.\u0004"],[8,"","ויש להבין כי כאן אומר ששור תם ה״ס שור דמרכבה הקדושה, ושור המועד הוא הס״א המתחברת עם החמור, (כדלקמן אות ק״כ) ולהלאה (פרשת חוקת אות י״ט) אומר ששור תם הוא גבורה תתאה, שהיא מלכות. ושור המועד הוא גבורה עלאה, דהיינו גבורה דז״א. אמנם הכל הולך אל מקום אחד. והענין הוא, כי מחזה ולמעלה דז״א שה״ס ג״ר, אסור להמשיך חכמה משמאל שה״ס גבורה עלאה, מפני שכל הנמשך משם הוא אור זכר המאיר ממעלה למטה, שה״ס ג\"ר דחכמה שנגנזה. וכל הממשיך משם נופל ברשות הקליפות דהיינו לשור המועד, אבל הממשיך ממלכות, שה״ס אור נקבה, נמצא ממשיך רק ממטה למעלה שהוא ו\"ק דחכמה, וזה הוא חכמה דקדושה, וה״ס שור תם, וה״ס שור, של המרכבה המאיר ממטה למעלה, שהוא כמו הארת המלכות, דהיינו ו\"ק דחכמה. הרי, \u0003ששור המועד\u0004 ה״ס המשכת החכמה ממעלה למטה, בבחינת אור זכר, הנמשך מגבורה עלאה, שהוא מחזה ולמעלה דז״א, והוא כללות הס״א, שכל תאותה להמשיך הג״ר דחכמה מגבורה עלאה דז״א. \u0003ושור תם,\u0004 נמשך מגבורה תתאה, כלומר, המאיר בבחינת אור נקבה כמו המלכות שמחזה ולמטה דז״א, שהוא כללות המוחין דחכמה דשמאל דקדושה, הנקרא שור של המרכבה הקדושה."],[8,"","ודע שב׳ שורים אלו נוגחים זה את זה תמיד. כי הזוכה וממשיך החכמה מבחינת שור דקדושה, דהיינו ממלכות, כנ״ל, שה״ס שור תם. הנה נודע שאין החכמה נגלית אלא עם דינים, שהדינים אלו נופלים על ראש הרשעים הממשיכים החכמה ממעלה למטה בבחינת שור המועד (כנ״ל אד״ר אות רי״ט) הרי ששור תם נוגח עם הדינים שלו את שור המועד, וממיתו, דהיינו שור המועד שמצד שורשו של אותו האדם שהמשיך את השור תם. וכן אם אינו זוכה ורוצה להמשיך החכמה מגבורה עלאה, דהיינו ממעלה למטה, שהיא המשכת שור המועד, הנה אז לפתח חטאת רובץ, ומתגלה המנעולא, והמוחין דשור תם מסתלקים. וע״כ נבחן זה ששור המועד נגח והמית את שור התם. הרי איך שב׳ שורים אלו נוגחים וממיתים זה את זה."],[8,"","ובזה תבין פנימיות הכתובים. \u0003וכי יגוף שור איש את שור רעהו ומת.\u0004 שכאן מדבר הכתוב \u0003בשור תם,\u0004 נמצא ששור רעהו הוא שור המועד, שבעת ששור תם שהוא שור של המרכבה שולט, הרי הדינים שלו ממיתים את שור המועד. כנ״ל. ונודע שאפילו הממשיך מן המלכות שהוא ו\"ק דחכמה, אי אפשר שיתגלו הו\"ק בלי הג״ר, נמצא שגם בשור תם מתגלה בו הג״ר עם המשכתו, אלא כיון שנמשך מן המלכות, אז נוהג בו, \u0003ומכרו את השור החי,\u0004 דהיינו שממעטים אותו בכח המסך דחירק דקו האמצעי (כנ\"ל לך י״ג ד״ה ונתבאר) ואז עי״ז \u0003וחצו את כספו,\u0004 אשר מחציתו העליון, שה״ס ג\"ר דחכמה, נעלמים, ומחציתו התחתון, שה״ס ו״ק דחכמה, נשארים להממשיך אותו. (כנ״ל ב״א דף ס׳ ד\"ה מחלוקת) וז״ס \u0003וגם את המת יחצון,\u0004 כי אחר שנגלה תקון החלוקה ע״י קו האמצעי, נוהג זה גם בשור המועד המת, שגם ממנו לוקחים מחצית התחתון שלו וניתן להממשיך, שהוא טהור אבל \u0003בשור המועד,\u0004 אוה״כ, \u0003שלם ישלם שור תחת השור,\u0004 כי אותו הגורם ששור המועד יהרוג את שור התם, דהיינו משום שהמשיך החכמה מגבורה עלאה, כנ״ל, הוא מפסיד הכל, ואין לו תקנה אלא להשלים את שור התם, וז״ס, \u0003והמת יהיה לו.\u0004 דהיינו שור תם המת, יהיה לו, כדי שיתקן אותו."],[8,"","וז\"ש, \u0003במה אתפרע ואתדכי מההוא פסולת,\u0004 דהיינו ששואל, מי הוא המטהר והמנקה את עור הפריעה שה״ס נוגה, מאותו הפסולת שבלע מג' הקליפות הטמאות מטרם שחתכו את עור הערלה ממנו. כנ״ל בתחילת הביאור. ומשיב, \u0003בגין דההוא אתר דאתקיף לפסולת, דלגו אתר דפריעה שארי, איהו שור\u0004 וכו'. כי נתבאר שהשורים דקדושה ודקליפה מנגחים וממיתים זה את זה, ונמצא ששליטת שור תם שנוגח וממית את שור המועד, שהוא ג׳ הקליפות הטמאות, הוא ממית ג״כ אותה הפסולת הנבלע בעור הפריעה, ומגלה בה המוחין דו״ק דחכמה שלו. וז״ש, \u0003וההוא שור אקרי שור תם, דהא רתיכא דכרסיא רשימא דברית אית ביה,\u0004 כי בהכרח המרכבה דקדושה יש בו רושם הברית, דהיינו בחינת מילה ופריעה, מרחיק וממית ג׳ קליפות הטמאות שהם שור המועד. וע״כ הוא שור תם. \u0003ובהאי שור, עביד פריעה,\u0004 שהוא הממית אותו הפסולת שבעור הפריעה, וז״ש, \u0003ואעבר זוהמא דפסולת כלא.\u0004 כמבואר."],[9,"במתניתא דבצלאל כתיב וכו׳:","בברייתא של בצלאל כתוב, ויזכור אלקים את רחל. שואל, בשרה כתוב פקידה, וה׳ פקד את שרה, וברחל כתוב זכירה, למה. ומשיב, משום שזכור, שה״ס היסוד, נרשם ביעקב, שהוא, ברית שלם בשעה שנולד יוסף, ובמה נעשה ברית שלם. היינו כשלקח את השור עמו המתקיף לסטרא אחרא, שהוא מתקיף וממית הזוהמא דפסולת של שור המועד שבתוך עור הפריעה, כנ״ל בדבור הסמוך. ומשום זה נקרא יוסף בכור שור, דהיינו בכור של אותו שור שלקח יעקב בכור שורו, ודחה לשור ההוא דס״א, שהוא שור מועד."]],[[0,"","בֵּין כָּךְ הֲרֵי רַבִּי אִילָאִי בָּא מֵאִיר כַּשֶּׁמֶשׁ. אָמַר לוֹ, תּוֹרָה חֲדָשָׁה שָׁמַעְתָּ? אָמַר לָהֶם, בְּוַדַּאי! וְנָתְנוּ לִי רְשׁוּת לוֹמַר לָכֶם דְּבָרִים. הִתְחַבְּרוּ כְאֶחָד עַל פִּי הַמְּעָרָה וְיָשְׁבוּ. אָמַר לָהֶם, צַדִּיקִים אַתֶּם, שֶׁרִבּוֹנְכֶם הֶרְאָה לָכֶם כְּמוֹ הָעוֹלָם הַבָּא, וַהֲרֵי אֵין לָכֶם פַּחַד וְאֵימָה. אָמְרוּ, וַדַּאי הֲרֵי נִשְׁכַּח מֵאִתָּנוּ דֶּרֶךְ בְּנֵי אָדָם, וּתְמִיהָה הִיא עַל כָּל מַה שֶּׁרָאִינוּ בָהָר הַזֶּה."],[1,"","אָמַר לָהֶם, רְאִיתֶם הָרִים אֵלֶּה? כֻּלָּם רָאשֵׁי יְשִׁיבוֹת לָעָם הַזֶּה שֶׁבַּמִּדְבָּר. וְזָכוּ כָּעֵת מַה שֶּׁלֹּא זָכוּ כְּשֶׁהָיוּ בַחַיִּים. וְאֵלֶּה רָאשֵׁי יְשִׁיבוֹת, כֻּלָּם בְּרָאשֵׁי חֳדָשִׁים וְשַׁבָּתוֹת וּמוֹעֲדִים מִתְכַּנְּסִים לְהַר אַהֲרֹן הַכֹּהֵן וּמִתְעוֹרְרִים אֵלָיו, וְנִכְנָסִים לְתוֹךְ יְשִׁיבָתוֹ וּמִתְחַדְּשִׁים שָׁם בְּטֹהַר הַטַּל הַקָּדוֹשׁ שֶׁיּוֹרֵד עַל רֹאשׁוֹ, וְשֶׁמֶן מִשְׁחָה שֶׁשּׁוֹפֵעַ עָלָיו, וְעִמּוֹ מִתְחַדְּשִׁים כֻּלָּם בְּחִדּוּשִׁים אֲהוּבִים שֶׁל הַמֶּלֶךְ הַקָּדוֹשׁ, עַד שֶׁנִּקְרָא כָּאן יְשִׁיבַת הָאַהֲבָה."],[2,"","וְהוּא לוֹקֵחַ בְּכָל יְשִׁיבָה, בְּסֵתֶר דַּקִּיק מִתְעוֹפְפִים כַּנְּשָׁרִים לְתוֹךְ יְשִׁיבַת הָאוֹר, וְהִיא יְשִׁיבַת מֹשֶׁה, וְכֻלָּם עוֹמְדִים בַּחוּץ וְלֹא נִכְנָסִים פְּנִימָה, פְּרָט לְאַהֲרֹן לְבַדּוֹ, וּלְפִי שָׁעָה נִקְרָאִים בְּשֵׁם."],[3,"","וְאֵין מִי שֶׁיִּרְאֶה אֶת מֹשֶׁה, שֶׁהֲרֵי אוֹתוֹ מַסְוֶה שֶׁעַל פָּנָיו פָּרוּשׂ לְפָנָיו, וְשִׁבְעָה עַנְנֵי כָבוֹד סְבִיבוֹ. אַהֲרֹן עוֹמֵד תּוֹךְ הַפַּרְגּוֹד שֶׁלְּמַטָּה מִמֹּשֶׁה. וּפַרְגּוֹד פּוֹסֵק, וְלֹא פוֹסֵק בְּתוֹכָם. וְכָל רָאשֵׁי הַיְשִׁיבוֹת מִחוּץ לְפָרֹכֶת הַפַּרְגּוֹד הַזֶּה, וְכָל הַשְּׁאָר מִחוּץ לְאוֹתָם עֲנָנִים. וּכְפִי חִדּוּשֵׁי אוֹר הַתּוֹרָה שֶׁמְּאִירָה, כָּךְ מְאִירִים אוֹתָם עֲנָנִים."],[4,"","וְנִהְיִים קְלוּשִׁים בְּדַקִּיקוּת הָאוֹר, עַד שֶׁנִּרְאֶה אוֹתוֹ מַסְוֶה, וּמִתּוֹךְ אוֹתוֹ מַסְוֶה רוֹאִים אוֹר שֶׁמֵּאִיר יוֹתֵר מִכָּל אוֹרוֹת הָעוֹלָם, וְהֵם פְּנֵי מֹשֶׁה. פָּנָיו לֹא נִרְאִים כְּלָל, וְאֵין מִי שֶׁיִּרְאֶה אוֹתָם, פְּרָט לְאוֹתוֹ אוֹר שֶׁיּוֹצֵא מִתּוֹךְ אוֹתוֹ מַסְוֶה אַחַר כָּל אוֹתָם הָעֲנָנִים."],[5,"","מֹשֶׁה אָמַר דָּבָר סְתָם לְאַהֲרֹן, וְאַהֲרֹן מְפָרֵשׁ לִגְדוֹלֵי הַיְשִׁיבוֹת. בַּמֶּה מְפָרֵשׁ? בְּכָל אוֹתָם מַבּוּעִים שֶׁנִּסְתְּמוּ מִמֶּנּוּ כְּשֶׁהִגִּיעַ זְמַנּוֹ שֶׁל יְהוֹשֻׁעַ. וְכָעֵת הוּא מַחֲזִיר לָהֶם בְּכַמָּה פְלָאוֹת, וּמְקוֹרוֹת וּמַבּוּעִים וּנְחָלִים שֶׁנּוֹבְעִים מִכָּל דָּבָר וְדָבָר."],[6,"","כָּל נָשִׁים צִדְקָנִיּוֹת שֶׁל הַדּוֹר הַזֶּה בָּאוֹת לְמִרְיָם גַּם כָּאן בַּזְּמַנִּים הַלָּלוּ, וְאָז עוֹלוֹת כֻּלָּן כְּתִמְרוֹת עָשָׁן לְתוֹךְ הַמִּדְבָּר הַזֶּה, וְאוֹתוֹ יוֹם נִקְרָא יוֹם הַהִלּוּלָא. נָשִׁים בְּלֵילֵי שַׁבָּתוֹת וּבְלֵילֵי יָמִים טוֹבִים, כֻּלָּן בָּאוֹת לְמִרְיָם, וְיוֹדְעוֹת הִשְׁתַּדְּלוּת בַּיְדִיעָה שֶׁל רִבּוֹן הָעוֹלָם. אַשְׁרֵי דּוֹר זֶה מִכָּל דּוֹרוֹת הָעוֹלָם. יוֹצְאִים מִישִׁיבַת מֹשֶׁה, וּפוֹרְחִים לִישִׁיבַת הָרָקִיעַ, וְאֵלֶּה שֶׁנִּרְאִים פּוֹרְחִים לַיְשִׁיבָה הָעֶלְיוֹנָה. עַל אוֹתוֹ דּוֹר כָּתוּב, (תהלים קמד) אַשְׁרֵי הָעָם שֶׁכָּכָה לּוֹ אַשְׁרֵי הָעָם שֶׁה' אֱלֹהָיו."],[7,"","פָּתַח רַבִּי אִילָאִי וְאָמַר, (דברים יח) תָּמִים תִּהְיֶה עִם ה' אֱלֹהֶיךְ. מַה בֵּין תָּם לְתָמִים? בְּאַבְרָהָם כָּתוּב, (בראשית יז) הִתְהַלֵּךְ לְפָנַי וֶהְיֵה תָמִים. יַעֲקֹב שֶׁהִשְׁתַּלֵּם יוֹתֵר, כָּתוּב בּוֹ, (שם כה) וְיַעֲקֹב אִישׁ תָּם. לָמָּה נִקְרָא אִישׁ תָּם? מִשּׁוּם שֶׁלֹּא נִשְׁאַר בּוֹ פְּסֹלֶת כְּלָל, שֶׁהֲרֵי פְּרִיעָה הָיְתָה בּוֹ."],[8,"","בַּמֶּה נִפְרַע (פריעה היתה בו שנפרע) וְנִטְהַר מֵאוֹתָהּ פְּסֹלֶת? מִשּׁוּם שֶׁאוֹתוֹ מָקוֹם שֶׁמְּחַזֵּק פְּסֹלֶת, שֶׁלְּתוֹךְ מְקוֹם הַפְּרִיעָה שׁוֹרֶה, הוּא שׁוֹר, דְּמוּת הַשְּׂמֹאל שֶׁל כִּסֵּא שֶׁלּוֹ. וְאוֹתוֹ שׁוֹר נִקְרָא שׁוֹר תָּם, שֶׁהֲרֵי מֶרְכֶּבֶת הַכִּסֵּא, רֹשֶׁם שֶׁל בְּרִית יֵשׁ בּוֹ. וְעַל זֶה שׁוֹר זֶה נִקְרָא תָם, וְיַעֲקֹב אָחוּז בּוֹ בְּתוֹכוֹ, וּבְשׁוֹר זֶה עוֹשִׂים פְּרִיעָה, וּמַעֲבִירִים זֻהֲמַת הַפְּסֹלֶת כֻּלָּהּ."],[9,"","בְּמִשְׁנַת בְּצַלְאֵל כָּתוּב, (שם ל) וַיִּזְכֹּר אֱלֹהִים אֶת רָחֵל. בְּשָׂרָה כָּתוּב פְּקִידָה, וּבְרָחֵל כָּתוּב זְכִירָה. לָמָּה? מִשּׁוּם שֶׁזָּכוֹר נִרְשַׁם בְּיַעֲקֹב, שֶׁהוּא בְּרִית שָׁלֵם כְּשֶׁנַּעֲשָׂה (כשנולד) יוֹסֵף, וּבַמֶּה? כְּשֶׁנָּטַל שׁוֹר עִמּוֹ שֶׁלֹּא יִתְחַזֵּק לַצַּד הָאַחֵר, וּמִשּׁוּם זֶה נִקְרָא יוֹסֵף בְּכוֹר שׁוֹר, בְּכוֹר שֶׁל אוֹתוֹ שׁוֹר שֶׁלָּקַח יַעֲקֹב (דברים לג) בְּכוֹר שׁוֹרוֹ. וַדַּאי, וְאוֹתוֹ שׁוֹר שׁוֹר תָּם,"]]],[["ודַּאי, וְהַהוּא שׁוֹר שׁוֹר תָּם, וְיַעֲקֹב אִישׁ תָּם. רִבּוֹן וְשָׁלִיט, מָארֵיהּ דְּבֵיתָא, דְּהַהוּא שׁוֹר תָּם שָׁארֵי בְּגַוִּויהּ. בְּגִין דְּאִית שׁוֹר מוּעָד בִּסְטָר עָרְלָה פְּרִיעָה. וְכַמָּה גַּרְדִּינֵי נִימוּסִין נַפְקִין מִנֵּיהּ, עַד דַּרְגָּא בַּתְרַיְיתָא דְּאִקְרֵי שְׁאִיָ\"ה. הַהוּא דְּאָפִיל בֵּיתִין דְּעָלְמָא, דְּלָא דַּיְירִין בְּהוּ בְּנֵי נָשָׁא. וְכֻלְּהוּ נַפְקָא מֵהַהוּא שׁוֹר מוּעָד. וְדָא בְּחִבּוּרָא דַּחֲמוֹר בִּישָׁא. וּבְגִין כָּךְ (דברים כ״ב:י׳) לֹא תַחֲרוֹשׁ בְּשׁוֹר וּבַחֲמוֹר יַחְדָּיו. בְּגִין דְּלָא לְאַתְּעָרָא לְהוּ.","וּבְהַהוּא מְתִיבְתָּא דִּבְצַלְאֵל, וְכֵן בִּתְרֵין מְתִיבְתָּא, וְיַעֲקֹב אִישׁ תָּם, בַּעְלָהּ דְּהַהוּא תָּם. וּמַאן אִיהוּ א' רָזָא דְּוָ\"ו. וְכַד הֲווֹ כְּלַל דְּכַר וְנוּקְבָּא כַּחֲדָא, כְּדֵין נָטִיל כָּל אַתְוָון אִלֵּין את\"ם, וְאִיהוּ אֶמֶ\"ת. (מיכה ז׳:כ׳) תִּתֵּן אֱמֶת לְיַעֲקֹב, כְּלַל דְּכַר וְנוּקְבָּא כַּחֲדָא, שְׁלִימוּ דְּכֹלָּא.","אַבְרָהָם לָא אִתְפְּקַד עַל פְּרִיעָה, וְכַד עָאל, עָאל לְהַאי תָּם, וּלְגוֹ דַּרְגִּין דִּילֵיהּ, דְּאִקְרוּן כַּחֲדָא יָם. וְהַיְינוּ תָּמִים. לְבָתַר אִסְתָּלַּק אַבְרָהָם, וְעָאל לְגוֹ, וְאִתְקְשַׁר עִם יְמִינָא עִלָּאָה.","תָּמִים תִּהְיֶה עִם יְיָ אֱלֹהֶיךָ וַדַּאי, כְּמָה דְּאִיהוּ תָּמִים כְּלָלָא חֲדָא, אוּף אַנְתְּ תְּהֵא עִמֵּיהּ תָּמִים, עִמֵּיהּ וַדַּאי. בְּמָה אִתְעָבִיד בַּר נָשׁ תָּמִים, דִּיְהֵא תָּ\"ם יָם. תָּם כְּמָה דְּאִתְּמַר. יָ\"ם כָּל אִינּוּן דַּרְגִּין קַדִּישִׁין דִּילֵיהּ אִקְרוּן יָ\"ם, וְלָא אִתְפָּרְשָׁן מִנֵיהּ לְעָלְמִין. (תרי נוסחי) אוּף אַנְתְּ כְּגַוְונָא דָא, לְאַעֲדָאָה מִנָךְ דַּרְגִין נוּכְרָאִין, וּלְאִתְקְשְּׁרָא בְּתָמִים, לְמֶיהֱוִי בָּךְ דַּרְגִין קַדִּישִׁין, רָזָא דְּיָם, וְדַרְגָּא קַדִּישָׁא, תָּ\"ם. לְקַבְּלָא א' רָזָא דְּיַעֲקֹב. בַּר נָשׁ אִצְטְרִיךְ לְמֶהֱוִי בְּכָל יוֹמָא, תָּ\"ם יָ\"ם. כְּגַוְונָא דָּא מַמָּשׁ.","הַשְׁתָּא פָּרִישׁ מַאן דְּפָרִישׁ, בִּמְתִיבְתָּא, דְּסִיהֲרָא קַדִּישָׁא שַׁפִּירָא, אִיהוּ בְּחִוָּורוּ, וְכָל גַּוְונִין מְנַצְצָן בָּהּ וּמְרֻקָּמָן, וְאִיהוּ כְּהַהוּא שְׁפִּירוּ וְחִוָּורוּ דְּשִׁמְשָׁא מַמָּשׁ. וּבְהַהוּא יַמָּא דִּילָהּ, גּוֹ שִׁבְעִין שְׁנִין, נָפְקָא נוּנָא חֲדָא, וְאַפִּיק מִנֵּיהּ גּוָֹון תְּכֵלֶת, וְאִיהִי נַטְלָא גּוָֹון דָּא, וְתַקִּינַת לֵיהּ, וְאִתְחַפְּיָיא לְבַר בְּהַאי גּוָֹון. לָאו דְּהַאי גּוָֹון לְבוּשָׁא דִּילָהּ, דְּהָא (משלי ל״א:כ״ב) שֵׁשׁ וְאַרְגָּמָן לְבוּשָׁהּ. אֲבָל חוּפָּאָה דִּלְבַר הַאי גּוָֹון הוּא. כְּגַוְונָא דָּא הֲוָה מַשְׁכְּנָא, דְּכוּלֵיהּ בִּשְׁפִירוּ מְרֻקָּמָא לְגוֹ, וּלְבָתַר (במדבר ד׳:ו׳) וּפָרְשׂוּ בֶגֶד כְּלִיל תְּכֵלֶת. מַאי טַעְמָא. בְּגִין דִּתְחוֹת יָם דָּא, אִית מְצוּלוֹת יָ\"ם, כְּלַל דְּכַר וְנוּקְבָּא, וְאִית לוֹן עֵינָא בִּישָׁא לְאִסְתַּכְּלָא, וְכַד מִסְתַּכְּלִין, זַמִּין לְעֵינַיְיהוּ גּוָֹון תְּכֵלָא, וְלָא יַכְלָא עֵינַיְיהוּ לְשַׁלְּטָאָה, וְאִיהִי אִתְתְּקָנַת לְגוֹ, בְּכָל גְּוָונִין מְרֻקָּמָן כַּדְּקָא יָאוּת, מִתְתָּחְמָן לְד' סִטְרִין דְּעָלְמָא.","כְּגַוְונָא דָּא בַּר נָשׁ דְּלָבִישׁ צִיצִית, אִתְעָבִיד בְּכָל יוֹמָא תָּמִים. תָּ\"ם, בְּד' כְּנָפַיִם מְתֻקְּנָן כַּדְּקָא יָאוּת. יָ\"ם, בְּהַהוּא תְּכֵלֶת דְּנוּנָא, דְּשִׁבְעִין דַּרְגִּין דְּיַמָּא, סִטְרָא בִּישָׁא כַּד אִסְתָּכַּל בְּהַאי בַּר נָשׁ לָא יָכִיל לְאַבְאָשָׁא לֵיהּ בְּעֵינָא בִּישָׁא. וּכְדֵין אִיהוּ תָּם יָ\"ם, עִם יְיָ אֱלֹהָיו מַמָּשׁ, בְּתִקּוּנָא חֲדָא, אִיהִי לְעֵילָּא, וְאִיהוּ לְתַתָּא.","לְבָתַר אִסְתָּלָקַת אִיהִי גּוֹ דַּרְגִּין עִלָּאִין. אוּף הָכִי בַּר נָשׁ, אִסְתַּלָּק אִיהוּ לְבָתַר בִּתְפִלִין, גּוֹ דַּרְגִּין עִלָּאִין. וְעַל דָּא תָּמִים תִּהְיֶה עִם יְיָ אֱלֹהֶיךָ, עִמֵּיהּ ודַּאי. וַדַּאי בְּשַׁעֲתָא חֲדָא, בְּרִגְעָא חֲדָא, אִיהִי אִתָּקְנָת לְעֵילָּא, וּבַּר נָשׁ אִתָּקָן לְתַתָּא.","אָמַר רִבִּי אִילָאִי, כָּל אִלֵּין דְּהָכָא, כְּגַוְונָא דָּא מְתַקְּנָן, לְמֶהֱוִי כָּל חַד תָּמִים עִם יְיָ. וְעַל רָזָא דָּא, בַּמִּדְבָּר הַזֶּה יִתַּמּוּ. אִי תֵּימְרוּן דְּכַד אִתְּמַר לְבִישׁ אִתְּמַר, הָכִי הוּא וַדַּאי, דְּהֲוָה לוֹן לְמֶהֱוִי כָּל חַד תָּמִים עִם יְיָ בְּאַרְעָא קַדִּישָׁא, אֲתָר דַּיְיָ שָׁארֵי תַּמָּן, לְמֶהֱוִי אַפִּין בְּאַפִּין כַּחֲדָא עִמֵּיהּ, וְהַשְׁתָּא כָּל חַד הֲוִי תָּמִים בְּמַדְבְּרָא דָּא לְבַר, אֲתָר רָחִיק מִתַּמָּן, דְּלָא יִסְתָּכַּל אַנְפִּין בְּאַנְפִּין בַּהֲדֵּיהּ לְמֶהֱוִי עִם יְיָ כַּדְּקָא יָאוּת. וְשָׁם יָמוּתוּ, כְּמָה דַּחֲמִיתוּן דְּעַבְדִּין בְּכָל יוֹמָא.","זַכָּאָה חוּלָקְכוֹן חַבְרַיָּיא קַדִּישִׁין, דְּזָכִיתוּן לְכָל הַאי. הָנֵי תְּרֵי מְעַרְתֵי אַחֲרָנִין דִּילְכוּ, דְּלָא תִּשְׁכְּחוּ כָּל דָּא תַּמָּן, דְּאִינּוּן גּוֹ מְתִיבְתָּא דְּמֹשֶׁה, יַתְבֵי מֵרָחִיק. וְעַל דָּא כְּתִיב בְּמֹשֶׁה, (במדבר י״ב:ג׳) עָנָו מְאֹד מִכָּל הָאָדָם. וּנְבִיאָה עִלָּאָה, קַבִּיל לוֹן לִמְתִיבְתָּא דִּילֵיהּ, מִיּוֹמָא דְּשָׁארֵי לְמֵחֱמֵי כָּל דָּא, עַד הַהִיא שַׁעֲתָא שִׁבְעָה יוֹמִין. וְהָא לָא הֲווֹ מִסְתַּכְּלִין בְּהַאי עָלְמָא כְּלוּם."],[[0,"שור תם, ויעקב וכו׳:","שור תם, היינו, ויעקב איש תם. שפירושו רבון ושליט אדון הבית ששור תם שורה בתוכו, דהיינו המלכות שממנה נמשך שור תם, כנ״ל בסמוך, ולהלאה (חוקת אות י״ט) משום שיש שור מועד מצד ערלה ופריעה. דהיינו כל הערלה, וזוהמא דפסולת הנבלע בעור הפריעה, כנ״ל בסמוך. וכמה בעלי דין יוצאים ממנו עד מדרגה התחתונה הנקרא \u0003שאיה,\u0004 אותו המזיק המפיל בתי העולם הריקים מבני אדם. וכולם יוצאים מאותו שור המועד, והיינו בחבור חמור הרע, שה״ס דין הקשה דמנעולא, אשר המתחבר לשור המועד, נאמר עליו לפתח חטאת רובץ שמתגלה הדין של מנעולא שה״ס חמור. ונמצאים שור וחמור מתחברים להשמיד הכל (כנ״ל שמות דף כ״ה ד״ה פירוש). ומשום זה לא תחרוש בשור וחמור יחדיו, כדי שלא לעוררם."],[1,"ובההוא מתיבתא דבצלאל וכו׳:","ובאותה הישיבה של בצלאל וכן בב׳ הישיבות, דהיינו בישיבה של מטטרון ובישיבה של הקב״ה, אמרו, ויעקב איש תם, פירושו, בעלה של תם ההוא, שהוא המלכות (כנ\"ל באות קי״ח בהסולם). ומי הוא, בעלה דתם, הוא ה \u0003א',\u0004 שבסוד המילוי של ו \u0003א\u0004 ו, שיעקב ה״ס \u0003א׳\u0004 והמלכות ה״ס \u0003תם,\u0004 וכשהם כלל דכר ונוקבא כלולים יחדיו, אז לוקח יעקב כל אותיות אלו, א׳ ת״ם, שה״ס \u0003אתם,\u0004 והוא אותיות \u0003אמת,\u0004 וז״ש, תתן \u0003אמת\u0004 ליעקב, כי \u0003אמת\u0004 כולל דכר ונוקבא יחד שאז הם שלמות הכל."],[1,"","פירוש, יעקב ה״ס ז״א שכולו חסדים מכוסים, והמלכות ה״ס שור תם, דהיינו הארת החכמה שבקו שמאל. וכשז״א ומלכות נתכללו ומזדווגים יחד, וז״א הוא בעלה דההוא תם, נמצא ז״א כלול מחסרים וחכמה יחד. ואז יש לו משלו \u0003א׳\u0004 שה״ס חסדים, ומן המלכות יש לו \u0003תם,\u0004 שה\"ס הארת חכמה, שהם אותיות אמת. כי מוחין דג״ר נקראים אמת. וז\"ס תתן אמת ליעקב. וכל זה הוא משום שנתחבר במלכות, שה״ס שור תם. ונעשה בעלה דההוא תם. כי אז נכלל מחכמה וחסדים יחדיו. שזהו כל השלמות."],[2,"אברהם לא אתפקד וכו׳:","אברהם לא נצטוה על פריעה. וכאשר נכנס, דהיינו כשמל את עצמו, נכנס לאותו \u0003תם,\u0004 ולתוך המדרגות שלו שנקראים יחד \u0003ים,\u0004 והיינו \u0003תמים,\u0004 שהוא אותיות תם ים. אח״כ נתעלה אברהם ונכנס לפנימיות, ונקשר עם ימין העליון."],[2,"","פירוש. כבר ידעת, שג׳ קליפות הטמאות ה״ס עור הערלה, והם בחינות שור המועד. ונוגה, ה״ס עור הפריעה, שאחר שנפרדה ממנה הערלה, שה״ס הטומאה, נעשתה לבחי׳ שור תם. שע״י הפריעה ממשיכים שור התם ממלכות שיגח וימית הזוהמא והפסלות שבו, ואז נהפכה הנוגה, לבחינת שור תם ממש. וכולה קדושה. ואברהם לא נצטוה על הפריעה, אלא על המילה לבדה, ונמצא שע״י המילה, שהיא הסרת הערלה שהיא שור המועד, בא אברהם לבחינת שור תם, שה״ס עור הפריעה, וז״ש, \u0003אברהם לא אתפקד על פריעה, וכד עאל עאל להאי ת״ם ולגו דרגין דיליה. דאקרון כחדא י״ם,\u0004 כלומר שלא המשיך שור תם מן המלכות שיטהר עור הפריעה, שה״ס הנוגה ונתגלה החכמה, כמו יעקב, אלא שהמשיך מדרגות החסדים מן המלכות שנקראת שור תם, אשר חסדים אלו כלולים מ \u0003תם,\u0004 ואינם ממש שור \u0003תם,\u0004 שהוא בחינת שמאל, וז״ש, \u0003ולגו דרגין דיליה דאקרון כחדא ים,\u0004 דהיינו מדרגות החסדים הכלולים ויוצאים מתם, והם נקראים ים. \u0003והיינו תמים,\u0004 שפירושו, \u0003ים\u0004 הכלול מ \u0003תם,\u0004 ולא תם ממש. והוא מטעם שלא עשה פריעה. ועוד נשאר פסולת בעור הנגה. וז״ש \u0003לבתר אסתלק אברהם ועאל לגו,\u0004 דהיינו שעלה למעלה לז״א \u0003ואתקשר עם ימינא עילאה,\u0004 שהוא חסד דז״א. והשאיר תקון עור הפריעה ליעקב."],[3,"תמים תהיה עם וגו׳:","תמים תהיה עם ה׳ אלקיך ודאי. כמו שהוא תמים כלל אחד, שהים כלול מתם כנ״ל, אף אתה תהיה עמו תמים, עמו ודאי. כלומר עם ז״א שכולו חסדים מכוסים, והחכמה שבשמאל שה״ס תם אינו נגלה בו מטרם שנזדווג עם המלכות בסוד בעלה דתם, (כנ״ל באות קכ״א). במה נעשה האדם תמים. דהיינו שיהיה \u0003תם ים\u0004 בכלל אחד, \u0003תם,\u0004 כמו שאמרנו, אשר \u0003ים,\u0004 כל אלו מדרגות הקדושות של המלכות הנקראת תם, נקראות \u0003ים\u0004 ואינן מתפרשות ממנה לעולם, אף אתה כעין זה, תסיר ממך כל המדרגות הנכריות, שה״ס ג׳ קליפות הטמאות, ותתקשר בתמים, שתהיה בך מדרגות הקדושות שהן סוד \u0003ים,\u0004 ומדרגה הקדושה ת״ם, שתהיה ראויה לקבל אח״כ ה \u0003א׳,\u0004 שה״ס יעקב. ויעשה הצרוף \u0003אמת.\u0004 כנ״ל. האדם צריך להיות בכל יום \u0003תם ים,\u0004 כעין זה ממש."],[4,"","[א] \u0003השתא פריש מאן וכו':\u0004 עתה ביאר בהישיבה, מי שביאר, שהלבנה הקדושה שה\"ס מלכות, הוא בצבע לבן, שה״ס אור החסד, וכל הצבעים נוצצים בה ונרקמים, דהיינו גם אור החכמה, והוא כאותו היופי והלבן של השמש ממש. שה״ס ז״א. ובים ההוא של המלכות, בתוך שבעים שנה יוצא דג אחד, ומוציאה ממנו צבע תכלת, והיא לוקחת צבע הזה ומתקנת אותו ומתכסה מבחוץ בצבע ההוא."],[4,"","פירוש. המלכות מקבלת ג׳ קוין מן השמש שהוא ז״א, שהם ג׳ צבעים לבן אדום ירוק. ולפיכך יש בה י״ב בחינות, שהם חו\"ג תו״מ שבכל אחד ג׳ קוין, שהם ג׳ צבעים הנ״ל. אמנם צבע שלה עצמה שהוא אוכמא או תכלתא (כנ״ל ב״ב אות רנ״ט ע״ש) אין שם, להיות בה מבחינת מנעולא, בסוד האי שחור אדום הוא אלא שלקה (כנ״ל באד״ר אות רי״ב) וצבע זה נבחן לבחינת מלכות דמלכות שלה. וז״ש, \u0003ובההוא ימא דילה גו שבעין שנין,\u0004 שה״ס חג״ת נהי\"מ שכל אחת כלולה מעשר \u0003נפקא נונא חדא,\u0004 דהיינו, מלכות דמלכות. \u0003ואפיק מניה גוון תכלת,\u0004 שה״ס בחינת הדין הכלול ממנעולא (כמ״ש באדרא שם) \u0003ואתחפייא לבר בהאי גוון,\u0004 דהיינו רק מבחוץ שתהיה שמירה מפני החיצונים כמ״ש להלן, אבל מבפנים אין לה אלא ג׳ גוונים שהם לבן אדום ירוק כנ\"ל."],[4,"","[ב] \u0003לאו דהאי גוון וכו׳:\u0004 ולא משום שצבע תכלת הוא לבוש שלה, ע״כ היא מתכסה בו מבחוץ, שהרי כתוב שש וארגמן לבושה, אבל התכלת אינה ראויה ללבוש, אלא צבע זה הוא רק כיסוי מבחוץ על המלכות. כעין זה היה במשכן, שכולו ביופי ומעשה רוקם בפנים, ואח״כ, ופרשו בגד כליל תכלת, מבחוץ. מהו הטעם. הוא, משום שתחת ים הזה, שהוא המלכות, יש מצולות ים, שהם הקליפות הכלולים מדכר ונוקבא, ויש להם עין הרע להסתכל, וכשמסתכלים בהמלכות, דהיינו שרוצים להמשיך הארת חכמה ממנה ממעלה למטה כדרך הקליפות, אז מוכן לעיניהם צבע תכלת, שה״ס הדינין הכלולים ממנעולא, שעל ידו מסתלק אור החכמה, ואין עיניהם יכולות לשלוט בהמלכות. וזה רק מבחוץ, אבל הוא מתתקנת בפנים בכל הצבעים מרוקמים, שה״ס לבן אדום ירוק, כראוי להמשכת החכמה, והם מתפשטים לד׳ צדדי העולם. כלומר שאלו ג׳ צבעים שה״ס ג׳ קוין, הם נכללים בכל אחת מחו״ג תו״מ שבה, שהם ד׳ רוחות העולם, שהם י״ב בחינות, ומ״ש \u0003מתתחמן,\u0004 רומז על י״ב \u0003תחומין\u0004 המתפשטים בד׳ רוחות."],[5,"כגוונא דא ב״נ וכו׳:","כעין זה אדם הלובש ציצית, נעשה בכל יום תמים בחינת \u0003תם\u0004 של המלכות מקבל בד׳ כנפים של הבגד המתתקנים כראוי, בחינת \u0003ים\u0004 הוא מקבל מן המלכות, בתכלת ההוא של הציצית, שה״ס הדג של ע׳ מדרגות שבים, כנ״ל בסמוך, אשר צד הרע, כשמסתכל באדם הזה לא יוכל להזיק אותו בעין הרע, כלומר שלא יוכל להמשיכהו לרשות שור המועד כנ״ל, כי התכלת מעכב עליהם, כנ״ל בדבור הסמוך, ואז הוא \u0003תם ים\u0004 עם ה׳ אלקיו ממש בתקון אחד. כי גם המלכות מתתקנת ומתכסית בחוץ עם צבע התכלת כנ״ל. היא למעלה והוא למטה."],[6,"לבתר אסתלק איהי וכו':","אח״כ עולה המלכות למדרגות עליונות, דהיינו למדרגות דז״א, אף כך האדם, מתעלה אח״כ בתפלין אל מדרגות עליונות, דז״א. ועל זה נאמר, תמים תהיה עם ה׳ אלקיך, עמו ודאי. ודאי בשעה אחת וברגע אחת, המלכות מתתקנת למעלה, תחילה בתם ים, ואח״כ בזווג עם ז״א. כן האדם מתתקן למטה. תחילה מתתקן בציצית שהיא מדרגת תם ים, ואח״כ בתפלין, שהוא מדרגת ז״א."],[7,"א״ר אילאי כל וכו׳:","א״ר אילאי כל אלו שבכאן דהיינו דור המדבר, מהתקנים כעין זה להיות כל אחד \u0003תם ים\u0004 עם ה'. ועל סוד הזה נאמר, במדבר הזה \u0003יתמו,\u0004 דהיינו שיקבלו בחי׳ \u0003תם.\u0004 ואם תאמרו כשנאמר זה, נאמר לרע, ולא לשבחם. כך הוא ודאי, שאינו לשבחם, כי היה להם להיות כל אחד תמים עם ה׳ בארץ הקדושה, במקום שהקב״ה שורה שם פנים בפנים ביחד עם המלכות. ועתה הנה כל אחד תמים במדבר הזה בחוץ מקום רחוק משם, מארץ הקדושה, שאין המלכות מסתכלת פנים בפנים להיות עם ה׳ כראוי. \u0003ושם ימותו,\u0004 היינו כמו שראיתם אותם עושים בכל יום (כנ״ל באות ק״ג), שמתים וחוזרים לתחיה."],[8,"זכאה חולקכון חבריא וכו׳:","אשרי חלקכם, חברים הקדושים, שזכיתם לכל זה. אלו ב׳ מערות אחרות שלכם, שלא תמצאו מי שהוא שמה, הוא משום שהם בישיבה של משה. הם יושבים מרחוק, וע״כ כתוב במשה ענו מאד מכל האדם, כי נביא העליון קבל אותם לישיבה שלו. הנה מיום שאותם הצדיקים התחילו לראות כל זה, עד אותה שעה, כבר עבר שבעה ימים, ולא היו מסתכלים בעולם הזה כלום. כלומר שהיו מופשטים מכל גשמיות."]],[[0,"","(בראשית כה) וְיַעֲקֹב אִישׁ תָּם. רִבּוֹן וְשַׁלִּיט, בַּעַל הַבַּיִת, שֶׁאוֹתוֹ שׁוֹר תָּם שָׁרוּי בְּתוֹכוֹ. מִשּׁוּם שֶׁיֵּשׁ שׁוֹר מוּעָד בְּצַד עָרְלָה פְּרִיעָה. וְכַמָּה מְמֻנִּים עַל הַחֻקִּים יוֹצְאִים מִמֶּנּוּ עַד דַּרְגָּה אַחֲרוֹנָה שֶׁנִּקְרֵאת שְׁאִיָּ\"ה, אוֹתוֹ שֶׁמַּפִּיל בָּתֵּי הָעוֹלָם שֶׁלֹּא דָרִים בָּהֶם אֲנָשִׁים. וְכֻלָּם יוֹצְאִים מֵאוֹתוֹ שׁוֹר מוּעָד. וְזֶה בְּחִבּוּר עִם חֲמוֹר רַע. וּמִשּׁוּם זֶה (דברים כב) לֹא תַחֲרֹשׁ בְּשׁוֹר וּבַחֲמֹר יַחְדָּו, כְּדֵי לֹא לְעוֹרֵר אוֹתָם."],[1,"","וּבְאוֹתָהּ יְשִׁיבַת בְּצַלְאֵל, וְכֵן בִּשְׁתֵּי יְשִׁיבוֹת, וְיַעֲקֹב אִישׁ תָּם, בַּעְלָהּ שֶׁל אוֹתוֹ תָּם. וּמִיהוּ א'? סוֹד וָ\"ו. וּכְשֶׁהָיוּ כְּלַל זָכָר וּנְקֵבָה כְּאֶחָד, אָז נוֹטֵל כָּל אוֹתִיּוֹת אֵלֶּה את\"ם, וְהוּא אֱמֶ\"ת. (מיכה ז) תִּתֵּן אֱמֶת לְיַעֲקֹב. כְּלַל זָכָר וּנְקֵבָה כְּאֶחָד, שְׁלֵמוּת הַכֹּל."],[2,"","אַבְרָהָם לֹא הִצְטַוָּה עַל פְּרִיעָה, וּכְשֶׁנִּכְנַס, נִכְנַס לְתָם זֶה וּלְתוֹךְ דַּרְגוֹתָיו, שֶׁנִּקְרְאוּ כְאֶחָד יָם, וְהַיְנוּ תָּמִים. אַחַר כָּךְ הִתְעַלָּה אַבְרָהָם, וְנִכְנַס פְּנִימָה, וְנִקְשַׁר עִם יָמִין הָעֶלְיוֹן."],[3,"","תָּמִים תִּהְיֶה עִם ה' אֱלֹהֶיךְ וַדַּאי, כְּמוֹ שֶׁהוּא תָּמִים, כְּלָל אֶחָד, גַּם אַתָּה תִהְיֶה עִמּוֹ תָּמִים, עִמּוֹ וַדַּאי. בַּמֶּה נַעֲשֶׂה בֶּן אָדָם תָּמִים, שֶׁיִּהְיֶה תָ\"ם יָ\"ם? תָּ\"ם - כְּמוֹ שֶׁנִּתְבָּאֵר. יָ\"ם - כָּל אוֹתָן דְּרָגוֹת קְדוֹשׁוֹת שֶׁלּוֹ נִקְרָאִים יָ\"ם, וְלֹא נִפְרָדִים מִמֶּנּוּ לְעוֹלָמִים. (שתי נסחאות) גַּם אַתָּה כְּמוֹ זֶה, לְהַעֲבִיר מִמְּךְ דְּרָגוֹת נָכְרִיּוֹת, וּלְהִתְקַשֵּׁר בְּתָמִים, לִהְיוֹת בְּךְ דְּרָגוֹת קְדוֹשׁוֹת, סוֹד שֶׁל הַיָּ\"ם, וְדַרְגָּה קְדוֹשָׁה תָּ\"ם, כְּנֶגֶד א' סוֹד שֶׁל יַעֲקֹב. בֶּן אָדָם צָרִיךְ לִהְיוֹת בְּכָל יוֹם תָּ\"ם יָ\"ם כְּמוֹ זֶה מַמָּשׁ."],[4,"","כָּעֵת פֵּרַשׁ מַה שֶּׁפֵּרַשׁ בַּיְשִׁיבָה, שֶׁהַלְּבָנָה הַקְּדוֹשָׁה יָפָה הִיא בְּלֹבֶן, וְכָל הַגְּוָנִים נוֹצְצִים בָּהּ וּמְרֻקָּמִים, וְהִיא כְּאוֹתוֹ יֹפִי וְלֹבֶן הַשֶּׁמֶשׁ מַמָּשׁ. וּבְאוֹתוֹ הַיָּם שֶׁלָּהּ בְּתוֹךְ שִׁבְעִים שָׁנָה יוֹצֵא דָג אֶחָד, וּמוֹצִיא מִמֶּנָּה גָּוֶן תְּכֵלֶת, וְהִיא לוֹקַחַת גָּוֶן זֶה וּמַתְקִינָה אוֹתוֹ, וּמִתְחַפָּה בַחוּץ בַּגָּוֶן הַזֶּה. לֹא שֶׁגָּוֶן זֶה הוּא לְבוּשָׁהּ, שֶׁהֲרֵי (משלי לא) שֵׁשׁ וְאַרְגָּמָן לְבוּשָׁהּ. אֲבָל צִפּוּי חִיצוֹנִי הוּא הַגָּוֶן הַזֶּה. כְּמוֹ זֶה הָיָה הַמִּשְׁכָּן, שֶׁכֻּלּוֹ בְּיֹפִי מְרֻקָּם לִפְנִים, וְאַחַר כָּךְ - (במדבר ד) וּפָרְשׂוּ בֶגֶד כְּלִיל תְּכֵלֶת. מָה הַטַּעַם? מִשּׁוּם שֶׁתַּחַת יָם זֶה יֵשׁ מְצוּלוֹת יָ\"ם, כְּלָל שֶׁל זָכָר וּנְקֵבָה, וְיֵשׁ לָהֶם עַיִן הָרָע לְהִסְתַּכֵּל. וּכְשֶׁמִּסְתַּכְּלִים, מִזְדַּמֵּן לְעֵינֵיהֶם צֶבַע תְּכֵלֶת, וְלֹא יְכוֹלָה עֵינָם לִשְׁלֹט, וְהִיא מִתְתַּקֶּנֶת לִפְנִים בְּכָל גְּוָנִים מְרֻקָּמִים כָּרָאוּי, מִתְתַּחְמִים לְאַרְבַּעַת צִדְדֵי הָעוֹלָם."],[5,"","כְּמוֹ זֶה בֶּן אָדָם שֶׁלּוֹבֵשׁ צִיצִית, נַעֲשֶׂה בְּכָל יוֹם תָּמִים. תָּ\"ם, בְּאַרְבַּע כְּנָפַיִם מְתֻקָּנוֹת כָּרָאוּי. יָ\"ם, בְּאוֹתוֹ תְּכֵלֶת שֶׁל הַדָּג שֶׁל שִׁבְעִים דַּרְגוֹת הַיָּם, צַד הָרָע כְּשֶׁמִּסְתַּכֵּל בָּאָדָם זֶה לֹא יָכוֹל לְהַזִּיקוֹ בְּעַיִן הָרָע, וְאָז הוּא תָּם יָ\"ם עִם ה' אֱלֹהָיו מַמָּשׁ בְּתִקּוּן אֶחָד, הוּא לְמַעְלָה, וְהוּא לְמַטָּה."],[6,"","אַחַר כָּךְ מִסְתַּלֶּקֶת הִיא לְתוֹךְ דְּרָגוֹת עֶלְיוֹנוֹת. גַּם כָּךְ הַבֶּן אָדָם עוֹלֶה הוּא אַחַר כָּךְ בַּתְּפִלִּין לְתוֹךְ דְּרָגוֹת עֶלְיוֹנוֹת. וְעַל זֶה תָּמִים תִּהְיֶה עִם ה' אֱלֹהֶיךְ, עִמּוֹ וַדַּאי. וַדַּאי בְּשָׁעָה אַחַת, בְּרֶגַע אֶחָד, הִיא מְתֻקֶּנֶת לְמַעְלָה, וּבֶן אָדָם מְתֻקָּן לְמַטָּה."],[7,"","אָמַר רַבִּי אִילָאִי, כָּל אֵלּוּ שֶׁל כָּאן, כְּמוֹ זֶה מְתֻקָּנִים לִהְיוֹת כָּל אֶחָד תָּמִים עִם ה'. וְעַל סוֹד זֶה, בַּמִּדְבָּר הַזֶּה יִתַּמּוּ. אִם תֹּאמְרוּ שֶׁכְּשֶׁנֶּאֱמַר, לְרַע נֶאֱמַר - כָּךְ זֶה בְּוַדַּאי, שֶׁהָיָה לָהֶם לִהְיוֹת כָּל אֶחָד תָּמִים עִם ה' בָּאָרֶץ הַקְּדוֹשָׁה, מָקוֹם שֶׁה' שָׁרוּי שָׁם, לִהְיוֹת פָּנִים בְּפָנִים כְּאֶחָד עִמּוֹ, וְכָעֵת כָּל אֶחָד הָיָה תָמִים בְּמִדְבָּר זֶה לַחוּץ, מָקוֹם רָחוֹק מִשָּׁם, שֶׁלֹּא יִסְתַּכֵּל פָּנִים בְּפָנִים אִתּוֹ לִהְיוֹת עִם ה' כָּרָאוּי. וְשָׁם יָמוּתוֹ, כְּמוֹ שֶׁרְאִיתֶם שֶׁעוֹשִׂים בְּכָל יוֹם."],[8,"","אַשְׁרֵי חֶלְקְכֶם, חֲבֵרִים קְדוֹשִׁים, שֶׁזְּכִיתֶם לְכָל זֶה. שְׁתֵּי מְעָרוֹת אֵלֶּה אֲחֵרוֹת שֶׁלָּכֶם, שֶׁלֹּא תִמְצְאוּ כָּל זֶה שָׁם, שֶׁהֵם תּוֹךְ יְשִׁיבַת מֹשֶׁה יוֹשְׁבִים מֵרָחוֹק. וְעַל זֶה כָּתוּב בְּמֹשֶׁה, (במדבר יב) עָנָו מְאֹד מִכָּל הָאָדָם. וְנָבִיא עֶלְיוֹן קִבְּלָם לִישִׁיבָתוֹ מִיּוֹם שֶׁהֻתַּר לִרְאוֹת כָּל זֶה עַד אוֹתָהּ שָׁעָה שִׁבְעָה יָמִים. וַהֲרֵי לֹא הָיוּ מִסְתַּכְּלִים בָּעוֹלָם הַזֶּה כְּלוּם."]]],[["אָמַר לוֹן רִבִּי אִילָאִי, זַכָּאִין קַדִּישִׁין, אֵימָא לְכוּ מִלִּין דִּשְׁמַעְתּוּן. וּמִלָּה קַדְמָאָה כַּד תִּנְדְּעוּן מְדִידוּ דְּמִשְׁחָתָא, בִּשְׁמָא גְּלִיפָא מְפֹרָשׁ, תִּנְדְּעוּן (ואף על גב) דִּבְצַלְאֵל רְבִיעָאָה אִיהוּ, דִּנְהוֹרִין עִלָּאִין. דִּכְתִּיב, (שמות ל״א:ג׳) וָאֲמַלֵּא אוֹתוֹ רוּחַ אֱלֹהִים בְּחָכְמָה וּבִתְבוּנָה וּבְדַעַת. מַאן דְּלָא אִסְתָּכַּל חָמֵי וְאִתְפְּתַח.","מַאן דְּלָא אִסְתָּכַּל, בְּאִינּוּן תְּלַת מִלִּין טְמִירִין, מַה לְעֵילָּא, מַה לְתַתָּא וְכוּ'. זַמִּין אִיהוּ לְאִתְפַּתְּחָא בְּאוֹרַיְיתָא, וּלְפַקְחָא עַיְינִין בָּהּ. אִילָנָא דְּתַמְנֵי סְרֵי, שִׁדְרָתוֹ דְּבַּר נָשׁ, כַּד כָּפִיף קַמֵּי מָארֵיהּ, יִזְקוֹף וְיִתְקְיָּים לִתְחִיַּית מֵתַיָּיא. אִי לָא כָּפִיף בְּמוֹדִים, אִתְעָבִיד חִוְיָא, וְלֵית לֵיהּ תְּקוּמָה לְהַהוּא זִמְנָא. מַאן דְּעָאל בֵּין תְּרֵין כְּרוּבִים לְגוֹ.","מַאן דְּעָאל שִׁיעוּר תְּרֵין פִּתְחִין, לְגוֹ בֵּי כְּנִשְׁתָּא, אִתְדַּבָּק בְּמָארֵיהּ, וּרְעוּתֵיהּ אִתְעָבִיד. מַאן דִּמְעַיֵין בִּצְלוֹתֵיהּ, וְאִסְתָּכַּל בָּהּ, רָחִיק מֵרְעוּתֵיהּ דְּשָׁאִיל. קָרְבְּנָא דְּרַבְיָא, כַּד קָרֵב בַּר נָשׁ בְּרֵיהּ לְבֵי סַפְרָא, אוֹ לְמִילָה, דָּא קָרְבְּנָא שְׁלִים לְאִתְקַבְלָא. מִכָּאן וּלְהָלְאָה רְחִימִין, זִילוּ. (חסר)","אֶלְעָזָר בְּרִי, שַׁפִּיר קָאַמָרְת, כְּפוּם מַה דְּאוֹלִיפַת. אֲבָל חַס וְשָׁלוֹם, דְּאַף עַל גַּב דְּרָחֵל הֲוַת עֲקָּרָא בְּהַהוּא זִימְנָא, יַעֲקֹב חַכִּים הֲוָה. וְאִלְמָלֵא לָא יָדַע יַעֲקֹב, דְּלֵאָה אִנְתְּתֵיהּ, לָא קָבִיר לָהּ בִּמְעַרְתָּא, לְאִתְחַבְּרָא בַּהֲדֵּיהּ, בְּחִבּוּרָא חֲדָא, וִיהֵא קָבִיר לָהּ לְבַר מֵאַרְעָא. אֲבָל לְלֵאָה אָעִיל לָהּ גּוֹ אַרְעָא, וּלְרָחֵל שַׁוִּי לְבַר. מִית יַעֲקֹב, אִתְקְבַר בְּגַוָּוה, בְּחִבּוּרָא חֲדָא.","כְּמָה דְּעָבְדוּ כָּל שְׁאַר אֲבָהָן, אוּף הָכִי אָדָם. מֵתָה חַוָּה בְּקַדְמִיתָא, אִתְקַבְּרַת תַּמָּן. וְתַמָּן יָדַע אָדָם, דְּהַאי דּוּכְתָּא אִתְחֲזֵי לֵיהּ. מִית אָדָם, אִתְקְבַר בְּגַוָּוה בְּחִבּוּרָא חֲדָא. מֵתָה שָׂרָה אִתְקַבְּרַת תַּמָּן, וְחַוָּה חָמָאת, וְחַדָּאת לָקֳבְלָהּ, וְקָמַת וְקַבָּלָה לָהּ. שִׁיעוּרָא דְּחַוָּה לְגַבֵּי שָׂרָה, שִׁיעוּרָא דִּתְרֵין אַמִּין, וְלָא יַתִּיר. מֵת אַבְרָהָם, אִתְקְבַר לְגַבֵּי שָׂרָה, בְּחִבּוּרָא חֲדָא. מֵתָה רִבְקָה, אִתְקַבְּרַת תַּמָּן, וְשָׂרָה חָמָאת, וְקָמַת וְקִבְּלַת לָהּ. מֵת יִצְחָק, אִתְקְבַר בַּהֲדָהּ בְּחִבּוּרָא חֲדָא. מֵתָה לֵאָה, אִתְקַבְּרַת תַּמָּן, וְרִבְקָה חָמָאת, וְקָמַת, וְקַבָּלָה לָהּ. מֵת יַעֲקֹב, אִתְחֲבָּר בַּהֲדָהּ בְּחִבּוּרָא חֲדָא. וְכֻלְּהוּ דְּכַר וְנוּקְבָּא כַּחֲדָא, בְּחִבּוּרָא חֲדָא.","סִדּוּרָא דִּלְהוֹן הֵיךְ שָׁכְנֵי. נָשִׁין לְגַבֵּי נָשִׁין, וּדְכוּרִין לְגַבֵּי דְּכוּרִין. אָדָם בְּרֵישָׁא, חַוָּה סָמִיךְ לֵיהּ. שָׂרָה לְגַבֵּי חַוָּה. אַבְרָהָם סָמִיךְ לְשָׂרָה. יִצְחָק סָמִיךְ לְאַבְרָהָם. רִבְקָה סָמִיךְ לְיִצְחָק. לֵאָה סָמִיךְ לְרִבְקָה. יַעֲקֹב סָמִיךְ לְלֵאָה. אִשְׁתְּכַח אָדָם בְּסִטְרָא דָּא, יַעֲקֹב בְּסִטְרָא דָּא, דָּא רֵישָׁא, וְדָא סֵיפָא.","בְּסִפְרָא דִּשְׁלֹמֹה מַלְכָּא אִיהוּ כַּדְּקָא יָאוּת וְהָכִי הוּא, אָדָם וְחַוָּה בְּקַדְמִיתָא. וְשָׂרָה וְאַבְרָהָם סָמִיךְ לוֹן. יִצְחָק וְרִבְקָה לְזִוְיָא אַחֲרָא, בְּאֹרַח מֵישָׁר בְּשׁוּרָה חֲדָא. יַעֲקֹב וְלֵאָה בְּאֶמְצָעִיתָא. וְאִינּוּן נָשִׁין לְגַבֵּי נָשִׁין. וּדְכוּרִין לְגַבֵּי דְּכוּרִין. וְאָדָם וְחַוָּה, שָׂרָה וְאַבְרָהָם, יַעֲקֹב וְלֵאָה, רִבְקָה וְיִצְחָק. אָדָם בְּסִטְרָא דָּא, וְיִצְחָק בְּסִטְרָא דָּא, וְיַעֲקֹב בְּאֶמְצָעִיתָא. יִצְחָק לְגַבֵּי אֲבוּהָ לָאו אֹרַח עָלְמָא. וְעִם כָּל דָּא יַעֲקֹב אִצְטְרִיךְ בְּאֶמְצָעִיתָא.","וּבְכָל אִינּוּן זוּגִין, כְּמָה דְּאִתְקְבָרוּ, הָכִי יְקוּמוּן, וְהָכִי יִשְׁתַּכְּחוּן. לֵאָה תֶּחֱדֵי בַּהֲדֵי מָשִׁיחַ, בְּרֵיהּ דְּדָוִד, דְּנָפִיק מִנָּהּ לְגוֹ. רָחֵל תֶּחֱדֵי בַּהֲדֵי מָשִׁיחַ, בְּרֵיהּ דְּיוֹסֵף, דְּנָפִיק מִנָּהּ לְבַר מִיְרוּשָׁלַם. וְכֹלָּא לְדוּכְתַּיְיהוּ.","אִלֵּין הָכָא וְאִלֵּין הָכָא. דְּאִינּוּן (ס\"א מגדלין) מַרְגְּלָאן דְּאֶבֶן טָבָא כֻּלְּהוּ. בֵּין כֻּלְּהוּ מִגְדָּלִין אִית חַד מִגְדָּל דְּאֶבֶן טָבָא בְּאֶמְצָעִיתָא. וְדָא סָלִיק לְרוּם רְקִיעָא, וְלָא אִתְחֲזֵי הַשְׁתָּא, עַד הַהוּא זִמְנָא דְּיִתְגְּלֵי. רַב מְתִיבְתָּא חָמָא לֵיהּ, וַהֲוָה רָשִׁים בֵּיהּ לְעֵילָּא הַאי קְרָא, (משלי י״ח:י׳) מִגְדָּל עֹז שֵׁם יְיָ בּוֹ יָרוּץ צַדִּיק וְנִשְׂגָּב. וּפָרִישׂ רַב מְתִיבְתָא קְרָא דָּא, מִגְדָּל עֹז: דָּא כְּנֶסֶת יִשְׂרָאֵל. בּוֹ יָרוּץ צַדִּיק: בֵּיהּ רְעוּתֵיהּ דְּצַדִּיק תָּדִיר. וְעַל דָּא, וְנִשְׂגַּב הַהוּא מִגְדָּל, דְּלָא יִנְפּוֹל לְעָלְמִין, כְּמָה דְּהֲוָה."],[[0,"אמר לון ר׳ אילאי וכו׳:","א״ל ר״א, צדיקים קדושים, אומר לכם דברים ששמעתם אותם. דהיינו הדברים שלמעלה (באות ק״ה) ודבר ראשון מהדברים אשר שם. הוא, כשתדעו מדידה של המדה בשם החקוק המפורש, שהוא י״ה ו״ה, תדעו שבצלאל הוא רביעי לאורות העליונים, שכתוב, ואמלא אותו רוח אלקים בחכמה ובתבונה ובדעת."],[0,"","פירוש. כי ר׳ אילאי הולך כאן ומבאר כל המובא לעיל (באות ק״ה). נודע כי שיעורא דגופא הוא ד׳ בריתות, כמ״ש להלן (בלק אות שמ״ט) שהפירוש הוא כי כל מה שיש בגוף שה״ס ז״א כולל היסוד, וכיון שיש בגוף י״ב צירופי הויה, שה״ס חו\"ב תו״מ שבכל אחד ג׳ קוין, נמצא שהיסוד כולל אותם חו\"ב תו״מ דגוף, אשר ביסוד הם נקראים ד׳ בריתות, שכל ברית כולל ג׳ קוין, וז״ש ואמלא אותו \u0003רוח,\u0004 ה״ס ת\"ת, ו' דהויה, \u0003אלקים,\u0004 ה״ס מלכות ה׳ דהויה. \u0003בחכמה ובתבונה ובדעת,\u0004 היינו י״ה דהויה. וכל אלו כולל בצלאל, כי היסוד כולל כל מה שיש בגוף, וע״כ כתוב ואמלא אותו בי״ה ו״ה שה״ס רוח אלקים בחכמה ובתבונה ובדעת, שאצל בצלאל נקראים ד׳ בריתות. וה״ס \u0003רובע ישראל\u0004 (כמ״ש להלן בלק אות שמ״ט) כי הוא רובע הכולל ג׳ קוין והוא רביעי לג׳ קוין דחכמה ורביעי לג׳ קוין דבינה, ורביעי לג' קוין דת״ת ורביעי לג' קוין דמלכות. וע״כ נק' רובע ישראל, כי ישראל ה״ס ז״א שבו ד׳ אותיות הוי״ה, שבכל אות ג׳ קוין, והיסוד הוא רובע אליהם. שכוללם. וז״ש, \u0003כד תנדעון מדידו דמשחתא בשמא גליפא מפרש,\u0004 דהיינו המדידה די״ב גבולי אלכסון שה״ס י״ב צירופים שבשם המפורש י״ה ו״ה, אשר כל אות כלולה מג׳ קוין כנ״ל. \u0003תנדעון דבצלאל\u0004 שהוא יסוד, \u0003רביעאה איהו דנהורין עילאין\u0004 שבכל אות מד׳ אותיות הויה, הוא רביעי לג׳ קוין אשר שם, שהוא הכולל שלהם. ובזה מתבאר ג״כ מה שאומר לעיל (באות ק״ה) \u0003יוסף רביעאה איהו גו נהורין דאדם קדמאה,\u0004 כי אדם קדמאה, הוא ז״א, ויוסף הוא יסוד, שהוא אור רביעי לג' אורות הכלולים בכל אחד מחו״ב תו״מ שלו כנ״ל. ובהיותו כולל ד׳ בריתות אלו ע״כ היסוד עולה עד החב״ד, להיותו אור רביעי לחב״ד, וז״ש שם, \u0003סליקו דלעילא חביבא מכלא,\u0004 שה״ס העליה של היסוד למעלה למוחין, שעליה זו חביבה מכל, כי נוהגת בזמן הזווג."],[1,"מאן דלא אסתכל וכו׳:","עתה מבאר דבר הב׳ המובא לעיל (אות ק״ה) שאומר, מי שאינו מסתכל רואה ומתפקח, ע״ש. פירושו, מי שאינו מסתכל באלו ג׳ דברים נסתרים, מה למעלה מה למטה מה לפנים ומה לאחור. (נראה שמה לפנים ומה לאחור חושב לדבר אחד) עתיד הוא להתפתח בתורה, ולפקוח עיניו בה. דבר ג׳) אילן דתמני סרי \u0003כך כפיף יזקוף ויתקיים,\u0004 פירושו, השדרה של האדם, שיש בה י״ח חוליות, כשכופף אותה לפני אדונו, דהיינו כשכורע במודים, יזקוף ויתקיים לתחיית המתים. ואם אינו כופף במודים, נעשה נחש, ואין לו תקומה לעתיד לבא. וז״ש שם, \u0003ואי לא כפיף חויא כישא אכיל ליה.\u0004"],[2,"מאן דעאל בין וכו׳:","דבר ד) מי שנכנס בין ב׳ כרובים בפנים, פירושו, מי שנכנס שיעור שני פתחים בפנים בבית הכנסת (ברכות ח.) הוא מתדבק באדונו, ורצונו נעשה. דבר ה׳) \u0003מאן דמעיין רחיק מרעותיה,\u0004 פי׳ מי שמעיין בתפלה ומסתכל בה. כלומר, שאומר בלבו שתעשה בקשתו, לפי שמתפלל בכונה (רש״י ברכות נה.) הוא רחוק מקיום רצונו שבקש. דבר ו') \u0003קרבנא דרביא שלים לאתקבלא,\u0004 פירושו, כשאדם מקרב את בנו לבית הספר או למילה, זהו קרבן שלם להתקבל. מכאן ולהלאה אהובים, לכו."],[3,"אלעזר ברי שפיר וכו׳:","(חסר כאן תחילת הדברים) אלעזר בני, יפה אתה אומר כפי מה שלמדת, אבל ח״ו אע״ג דרחל היתה עקרה באותו הזמן, יעקב היה חכם, ואם לא היה יודע יעקב שלאה היא אשתו, לא היה קובר אותה במערת המכפלה, להתחבר עמו בחבור אחד, והיה קובר אותה מחוץ למערה. אבל את לאה הכניס לארץ, דהיינו למערת המכפלה, ואת רחל שם לחוץ ממערת המכפלה. מת יעקב נקבר בתוכה במערת המכפלה, בחבור אחד עם לאה."],[4,"כמה דעבדו כל וכו׳:","כמו שעשו כל שאר האבות כן עשה אדם הראשון, תחילה מתה חוה ונקברה שם במערת המכפלה, ושם ידע אדם שמקום ההוא ראוי לו. מת אדם נקבר בתוכה בחבור אחד עם חוה. מתה שרה נקברה שמה, וחוה ראתה ושמחה כנגדה, וקמה וקבלה אותה. שיעור המרחק של חוה משרה, הוא שיעור של ב׳ אמות, ולא יותר. מת אברהם נקבר אצל שרה בחבור אחד עמה. מתה רבקה נקברה שמה. ושרה ראתה וקמה וקבלה אותה. מת יצחק נקבר עמה בחבור אחד. מתה לאה נקברה שמה, ורבקה ראתה וקמה וקבלה אותה. מת יעקב נתחבר עמה בחבור אחד. וכולם היו דבר ונוקבא יחד בחיבור אחד."],[5,"סדורא דלהון היך וכו׳:","שואל, הסדר שלהם איך שוכנים. ומשיב, נשים אצל נשים ודכורין אצל דכורין. אדם בראש, חוה סמוכה לו. שרה אצל חוה, אברהם סמוך לשרה. יצחק סמוך לאברהם רבקה סמוכה ליצחק. לאה סמוכה לרבקה, יעקב סמוך ללאה. נמצא אדם בצד זה, יעקב בצד זה, זה בראש וזה בסוף."],[6,"בספרא דשלמה מלכא וכו׳:","בספרו של שלמה המלך, הוא ערוך כראוי. וכך הוא. אדם וחוה בתחילה, ושרה ואברהם סמוכים לו, יצחק ורבקה בזוית האחר כנגדם בדרך ישר בשורה אחת. יעקב ולאה באמצע. והם נשים אצל נשים, הזרים אצל זכרים, דהיינו אדם וחוה, שרה ואברהם יעקב ולאה, רבקה ויצחק. ונמצא אדם בצד זה, ויצחק בצד זה, ויעקב באמצע. יצחק אצל אביו אינו דרך העולם, וע״כ היה יעקב צריך להיות באמצע."],[7,"ובכל אינון זוגין וכו׳:","ובכל אלו הזוגות, כמו שנקברו כך יקומו לתחית המתים, וכך ימצאו. לאה תשמח עם משיח בן דוד שיצא ממנה, בפנים מערת המכפלה. רחל תשמח עם משיח בן יוסף שיצא ממנה, לחוץ מירושלים, דהיינו במקום שנקברה, בדרך אפרת. וכל אחד במקומו."],[8,"אלין הכא ואלין וכו׳:","(חסר תחילת המאמר) אלו כאן ואלו כאן. שהם כולם מגדלים של אבן טוב. בין כל המגדלים יש מגדל אחד של אבן טוב באמצע, וזה עולה לרום הרקיע, ואינו נראה עתה, עד לאותו הזמן שיתגלה. ראש הישיבה ראה אותו, והיה רושם עליו למעלה מקרא הזה, מגדל עז שם ה׳ בו ירוץ צדיק ונשגב. ומקרא הזה פירש ראש הישיבה כך, \u0003מגדל עז\u0004 זהו כנסת ישראל, דהיינו המלכות. \u0003בו ירוץ צדיק,\u0004 היינו כי רצון צדיק, שהוא יסוד, בו תמיד. כי ירוץ הוא לשון רצון. וע״כ \u0003ונשגב,\u0004 אותו מגדל עז, שלא יפול עוד לעולם כמו שהיה."]],[[0,"","אָמַר לוֹ רַבִּי אִילָאִי, צַדִּיקִים קְדוֹשִׁים, אֹמַר לָכֶם דְּבָרִים שֶׁשְּׁמַעְתֶּם. וְדָבָר רִאשׁוֹן כְּשֶׁתֵּדְעוּ מְדִידַת הַמִּשְׁחָה בְּשֵׁם חָקוּק מְפֹרָשׁ, תֵּדְעוּ (שאף על גב) שֶׁבְּצַלְאֵל הוּא רְבִיעִי שֶׁל אוֹרוֹת עֶלְיוֹנִים, שֶׁכָּתוּב (שמות לא) וָאֲמַלֵּא אֹתוֹ רוּחַ אֱלֹהִים בְּחָכְמָה וּבִתְבוּנָה וּבְדַעַת. מִי שֶׁלֹּא הִסְתַּכֵּל, רוֹאֶה וְנִפְקָח."],[1,"","מִי שֶׁלֹּא הִסְתַּכֵּל בְּאוֹתָם שְׁלֹשָׁה דְבָרִים טְמִירִים, מַה לְמַעְלָה מַה לְּמַטָּה וְכוּ', עָתִיד הוּא לְהִפָּקֵחַ בַּתּוֹרָה וְלִפְקֹחַ בָּהּ עֵינָיו. עֵץ שֶׁל שְׁמוֹנָה עָשָׂר, שִׁדְרַת הַבֶּן אָדָם, כְּשֶׁמִּתְכּוֹפֵף לִפְנֵי רִבּוֹנוֹ, יִזְקֹף וְיַעֲמֹד לִתְחִיַּת הַמֵּתִים. אִם לֹא כוֹפֵף בְּמוֹדִים, נַעֲשֶׂה נָחָשׁ, וְאֵין לוֹ תְקוּמָה לְאוֹתוֹ הַזְּמַן."],[2,"","מִי שֶׁנִּכְנָס לְבֵין שְׁנֵי כְרוּבִים פְּנִימָה, מִי שֶׁנִּכְנָס שִׁעוּר שְׁנֵי פְתָחִים לְתוֹךְ בֵּית הַכְּנֶסֶת, נִדְבָּק בְּרִבּוֹנוֹ, וּרְצוֹנוֹ נַעֲשֶׂה. מִי שֶׁמְּעַיֵּן בִּתְפִלָּתוֹ וּמִסְתַּכֵּל בָּהּ, רָחוֹק מֵרְצוֹנוֹ שֶׁשּׁוֹאֵל. קָרְבַּן הַתִּינוֹק כְּשֶׁמַּקְרִיב אָדָם בְּנוֹ לְבֵית סֵפֶר אוֹ לְמִילָה, זֶה קָרְבָּן שָׁלֵם לְהִתְקַבֵּל. מִכָּאן וּלְהָלְאָה, אֲהוּבִים, לְכוּ."],[3,"","אֶלְעָזָר בְּנִי, יָפֶה אָמַרְתָּ כְּפִי מַה שֶּׁלָּמַדְתָּ. אֲבָל חַס וְשָׁלוֹם, שֶׁאַף עַל גַּב שֶׁרָחֵל הָיְתָה עֲקָרָה בְּאוֹתוֹ זְמַן, יַעֲקֹב חָכָם הָיָה. וְאִלְמָלֵא לֹא יָדַע יַעֲקֹב שֶׁלֵּאָה אִשְׁתּוֹ, לֹא קָבַר אוֹתָהּ בַּמְּעָרָה לְהִתְחַבֵּר עִמּוֹ בְּחִבּוּר אֶחָד, וְיִקְבֹּר אוֹתָהּ מִחוּץ לָאָרֶץ. אֲבָל אֶת לֵאָה הִכְנִיס לְתוֹךְ הָאָרֶץ, וְרָחֵל שָׂם בַּחוּץ. מֵת יַעֲקֹב, נִקְבַּר בְּתוֹכָהּ בְּחִבּוּר אֶחָד."],[4,"","כְּמוֹ שֶׁעָשׂוּ כָּל שְׁאָר הָאָבוֹת, גַּם כֵּן אָדָם. מֵתָה חַוָּה בַּתְּחִלָּה, וּקְבָרָהּ שָׁם, וְשָׁם יָדַע אָדָם שֶׁזֶּה מָקוֹם רָאוּי לוֹ. מֵת אָדָם, נִקְבַּר בְּתוֹכָהּ בְּחִבּוּר אֶחָד. מֵתָה שָׂרָה, נִקְבְּרָה שָׁם, וְחַוָּה רָאֲתָה וְשָׂמְחָה לִקְרָאתָהּ וְקָמָה וְקִבַּלְתָּהּ. שִׁעוּר חַוָּה לְגַבֵי שָׂרָה, שִׁעוּר שֶׁל שְׁתֵּי אַמּוֹת וְלֹא יוֹתֵר. מֵת אַבְרָהָם, נִקְבַּר לְיַד שָׂרָה בְּחִבּוּר אֶחָד. מֵתָה רִבְקָה, נִקְבְּרָה שָׁם, וְשָׂרָה רָאֲתָה וְקָמָה וְקִבַּלְתָּהּ. מֵת יִצְחָק, נִקְבַּר אִתָּהּ בְּחִבּוּר אֶחָד. מֵתָה לֵאָה, נִקְבְּרָה שָׁם, וְרִבְקָה רָאֲתָה וְקָמָה וְקִבַּלְתָּהּ. מֵת יַעֲקֹב, הִתְחַבֵּר אִתָּהּ בְּחִבּוּר אֶחָד. וְכֻלָּם זָכָר וּנְקֵבָה כְּאֶחָד בְּחִבּוּר אֶחָד."],[5,"","סִדּוּרָם אֵיךְ שׁוֹכְנִים? נָשִׁים לְיַד נָשִׁים, וּזְכָרִים לְיַד זְכָרִים. אָדָם בָּרֹאשׁ, חַוָּה סְמוּכָה לוֹ. שָׁרָה לְיַד חַוָּה. אַבְרָהָם סָמוּךְ לְשָׂרָה. יִצְחָק סָמוּךְ לְאַבְרָהָם. רִבְקָה סְמוּכָה לְיִצְחָק. לֵאָה סְמוּכָה לְרִבְקָה. יַעֲקֹב סָמוּךְ לְלֵאָה. נִמְצָא אָדָם בְּצַד זֶה וְיַעֲקֹב בְּצַד זֶה, זֶה רֹאשׁ וְזֶה סוֹף."],[6,"","בְּסֵפֶר שְׁלֹמֹה הַמֶּלֶךְ הוּא כָּרָאוּי, וְכָךְ זֶה: אָדָם וְחַוָּה בַּתְּחִלָּה, וְשָׂרָה וְאַבְרָהָם סְמוּכִים לָהֶם. יִצְחָק וְרִבְקָה לְזָוִית אַחֶרֶת, בְּדֶרֶךְ יָשָׁר בְּשׁוּרָה אַחַת. יַעֲקֹב וְלֵאָה בָּאֶמְצַע. וְאוֹתָם נָשִׁים לְיַד נָשִׁים, וּזְכָרִם לְיַד זְכָרִים. וְאָדָם וְחַוָּה, שָׂרָה וְאַבְרָהָם, יַעֲקֹב וְלֵאָה, רִבְקָה וְיִצְחָק. אָדָם בְּצַד זֶה, וְיִצְחָק בְּצַד זֶה, וְיַעֲקֹב בָּאֶמְצַע. יִצְחָק לְיַד אָבִיו לֹא דֶרֶךְ הָעוֹלָם. וְעִם כָּל זֶה יַעֲקֹב צָרִיךְ בָּאֶמְצַע."],[7,"","וּבְכָל הַזּוּגוֹת הַלָּלוּ, כְּמוֹ שֶׁנִּקְבְּרוּ - כָּךְ יָקוּמוּ וְכָךְ יִמָּצְאוּ. לֵאָה תִּשְׂמַח עִם מָשִׁיחַ בֶּן דָּוִד שֶׁיֵּצֵא מִמֶּנָּה לִפְנִים. רָחֵל תִּשְׂמַח בְּמָשִׁיחַ בֶּן יוֹסֵף שֶׁיֵּצֵא מִמֶּנָּה מִחוּץ לִירוּשָׁלַיִם, וְהַכֹּל לִמְקוֹמוֹתֵיהֶ ם."],[8,"","אֵלֶּה כָּאן וְאֵלֶּה כָּאן. שֶׁהֵם (מגדלים) מַרְגָּלִיּוֹת שֶׁל אֶבֶן טוֹבָה כֻּלָּם. בֵּין כָּל הַמִּגְדָּלִים יֵשׁ מִגְדָּל אֶחָד שֶׁל אֶבֶן טוֹבָה בָּאֶמְצַע, וְזֶה עוֹלֶה לְרוּם הָרָקִיעַ, וְלֹא נִרְאֶה כָּעֵת, עַד אוֹתוֹ זְמַן שֶׁיִּתְגַּלֶּה. רֹאשׁ הַיְשִׁיבָה רָאָה אוֹתוֹ, וְהָיָה רָשׁוּם שָׁם פָּסוּק זֶה לְמַעְלָה, (משלי יח) מִגְדַּל עֹז שֵׁם ה' בּוֹ יָרוּץ צַדִּיק וְנִשְׂגָּב. וּפֵרַשׁ רֹאשׁ הַיְשִׁיבָה פָּסוּק זֶה, מִגְדַּל עֹז - זוֹ כְּנֶסֶת יִשְׂרָאֵל. בּוֹ יָרוּץ צַדִּיק - בּוֹ רְצוֹן הַצַּדִּיק תָּמִיד. וְעַל זֶה, וְנִשְׂגָּב אוֹתוֹ מִגְדָּל שֶׁלֹּא יִפֹּל לְעוֹלָמִים כְּמוֹ שֶׁהָיָה."]]],[["וְרִבִּי כְּרוּסְפְּדָאי חָמִיד לִבָּא, פָּרִישׁ הַאי קְרָא עַד לָא אִסְתַּלָּק, וּפָרִישׂ שַׁפִּיר. מִגְדָּל עֹז: דָּא תֵּיבָה, וְסֵפֶר תּוֹרָה דְּאִיהוּ עֹז, לְשַׁוָּאָה בֵּיהּ, וּלְאַפָּקָא לֵיהּ מִגּוֹ הֵיכָל, דִּיּוּקְנָא דְּהֵיכָל פְּנִימָאָה, דְּמִנֵּיהּ נָפְקָא תּוֹרָה, וְהַהוּא מִגְדָּל שֵׁם יְיָ אִיהוּ, וּדְיּוּקְנָא דִּילֵיהּ וְאִצְטְרִיךְ בְּשִׁית דַּרְגִּין.","בּוֹ יָרוּץ צַדִּיק, בְּמַאן. בְּמִגְדַּל, אוֹ בְּסֵפֶר תּוֹרָה. אֶלָּא קְרָא דָּרִישׁ בְּהַאי וּבְהַאי. כַּד דָּרַשׁ בְּמִגְדַּל, אִצְטְרִיךְ צַדִּיק דָּא דְּלִיהֱוִי חֲזַן הַכְּנֶסֶת, זַכָּאָה דִּקְשׁוֹט, וּדְיּוּקְנָא דְּצַדִּיק עִלָּאָה. כַּד דָּרִישׁ לְסֵפֶר תּוֹרָה, מַאן דְּסָלִיק לְסֵפֶר תּוֹרָה לְמִקְרֵי אוֹרַיְיתָא, אִצְטְרִיךְ צַדִּיק. וְצַדִּיק אִקְרֵי. מַאן אִקְרֵי צַדִּיק מְכֻּלְּהוּ. שְׁתִיתָאָה, דְּסָלִיק מֵאִינּוּן שִׁבְעָה. אָמַר רִבִּי שִׁמְעוֹן, וַדַּאי, דְּאִיהוּ לָא סָלִיק כָּל יוֹמוֹי, אֶלָּא שְׁתִיתָאָה לְאִינּוּן דְּסַלְּקִין. בּוֹ יָרוּץ צַדִּיק, בְּסֵפֶר תּוֹרָה יָרוּץ דִּבְרֵי צַדִּיק דָּא. וְנִשְׂגַּב מִמַּאן. מִדְּחִילוּ דְּמַלְאָךְ הַמָּוְת, דְּהָא אוֹרִיךְ יוֹמִין. וְנִשְׂגַּב דְּלָא יִתְנְזָק לְעָלְמִין.","בְּהַהוּא מִגְדָּל דְּסַלְּקָא בֵּין אִינּוּן מִגְדָּלִין, קַיְּימָא נְהִירוּ חַד, בְּדִיּוּקְנָא דְסֵפֶר תּוֹרָה, כַּד אָתֵי הַהוּא צִיפָּרָא, נַטְלָא הַהוּא מִגְדָּל מֵאַתְרֵיהּ, וְקָאִים גּוֹ אֶמְצָעִיתָא דַּעֲזָרָה, גּוֹ גַּדְפֵּי דִּכְרוּבִים הֲוָה. (ס\"א ומה דהוה). רוּמֵיהּ לְרוּם שְׁמַיָּא מָאִיךְ וְעָאל תְּחוֹת אִינּוּן כְּרוּבִים, וְשׁוּרוֹי בֵּין רֵישֵׁי כְּרוּבִים.","תְּלַת מֵאָה פִּתְחִין תַּמָּן, בְּפִתְחָא דְּאֶמְצָעִיתָא, קַיְּימָא נְהִירָא דָּא, דִּיּוּקְנָא דְסֵפֶר תּוֹרָה, בֵּיהּ זַמִּין מֶלֶךְ יִשְׂרָאֵל לְמִקְרֵי בְּפָרָשַׁת הַקְהֵל. וְדָא לִיהֱוִי מַלְכָּא מְשִׁיחָא, וְלָא אַחֲרָא.","וּבְהַהוּא סֵפֶר תּוֹרָה דְּהַהוּא נְהִירוּ, אִי חֲסִידָא קַדִּישָׁא, זַכָּאָה אִיהוּ דְּמִפּוּמֵיהּ יִשְׁמְעוּ, קָל נְעִימוּ דְּמִלוֹי מֵאִינּוּן מִלִּין סְתִימִין דְּפָרִישׁ בְּאוֹרַיְיתָא. בְּכָל רֵישׁ יַרְחֵי, וְשַׁבַּתֵּי וּמוֹעֲדַיָּיא וְזִמְנַיָּיא, כַּד בָּעָאן כָּל בְּנֵי מְתִיבְתֵּי לְסַלְּקָא לְעֵילָּא לְגוֹ מְתִיבְתָּא דִּרְקִיעָא, כֻּלְּהוּ מִתְכַּנְּפֵי לְגַבֵּי מַלְכָּא מְשִׁיחָא, וְאִיהוּ פָּרִישׁ מִלִּין, וּמִגּוֹ מְתִיקוּ דְּמִלוֹי בְּתִיאוּבְתָּא, סַלְּקִין. כֻּלְּהוּ עֶשֶׂר מִלִּין, גְּנִיזִין לָךְ מֵאִינּוּן מִלִּין דְּאִיהוּ פָּרִישׁ, לְיוֹמָא דִּשְׁאֶלְתִּין דִּילָךְ.","כַּד קַיְּימָא הַהוּא מִגְדָּל בְּאֶמְצָעוּ דַּעֲזָרָה, וּפִתְחָא דָּא פָּתַח, פָּתְחִין אִינּוּן כְּרוּבִין פּוּמַיְיהוּ, וּפַרְשֵׂי גַּדְפַּיְיהוּ, וְנָהִיר נְהִירוּ עִלָּאָה עַל הַהוּא פִּתְחָא. וְהַהוּא סֵפֶר תּוֹרָה פָּתִיחַ, וְאִינּוּן כְּרוּבִים פַּתְחֵי וְאַמְרֵי (תהילים ל״א:כ׳) מָה רַב טוּבְךָ אֲשֶׁר צָפַנְתָּ לִּירֵאֶיךָ וְגוֹ'. סָגִירוּ פִּתְחִין, וְסֵפֶר תּוֹרָה אִתְגְּלִיל.","מַאן חָמָא, נְהִירוּ דְּנַהֲרָא דְּהַהוּא סֵפֶר תּוֹרָה, כּוּלֵיהּ נְהוֹרָא דְּנָהִיר, אַתְוָון דִּילֵיהּ, שַׁלְהוֹבֵי דְּאֶשָּׁא מֵד' גַּוְונֵי, דְּאִינּוּן דְּעָלְמָא עִלָּאָה, כֻּלְּהוּ בַּלְטֵי וּמְנַצְצֵי, לֵית מַאן דְּיָכִיל לְמֵיקָם בְּהוּ, בַּר מָשִׁיחַ.","סָגִיר פִּתְחָא דָּא, כְּרוּבִים מִשְׁתַּכְכֵי. וְהַהוּא מִגְדָּל פָּרַח, וְקַיְּימָא בְּאַתְרֵיהּ בֵּין שְׁאַר מִגְדָּלִין.","בְּהַהוּא פִּתְחָא דְּאֶמְצָעִיתָא, אִית עֲטָרָה דְּפָז עִלָּאָה וְיַקִּירָא גְּנִיזָא, דְּלָא אִתְחֲזֵי הַשְׁתָּא, גְּלִיפָא וּמְחֻקָּקָא בְּכָל זִינֵי אַבְנֵי יְקָר, וּזְמִינָא לְמֶהֱוִי עַל רֵישָׁא דְּמַלְכָּא מְשִׁיחָא, כַּד סָלִיק בְּהַהוּא מִגְדָּל, וּתְרֵין נְשָׁרִין, דָּא מִסִּטְרָא דָּא, וְדָא מִסִּטְרָא דָּא, נַטְלֵי לֵיהּ בִּידַיְיהוּ.","כַּד סָלִיק מַלְכָּא מְשִׁיחָא, מִתְתָּקְנִין נְשָׁרִין, וְנַטְלֵי עֲטָרָא דָּא, בְּשַׁעֲתָא דְּיִשְׁרֵי לְמִקְרֵי, יִתְפְּתַח פִּתְחָא אַחֲרָא, וּמִתַּמָּן תִּפּוּק הַהִיא יוֹנָה, דְּשָׁדַר נֹחַ בִּימֵי טוֹפָנָא, דִּכְתִּיב, (בראשית ח׳:ח׳) וַיְשַׁלַּח אֶת הַיּוֹנָה, הַיּוֹנָה: הַהִיא דְּאִשְׁתְּמוֹדְעָא, וְלָא מַלִּילוּ בָּהּ קַדְמָאֵי, וְלָא יָדְעוּ מַה הִיא, אֶלָּא מֵהָכָא נַפְקַת, וְעַבְדַת שְׁלִיחוּתָא.","וּבְשַׁעֲתָא דִּכְתִּיב וְלָא יָסְפָה שׁוּב אֵלָיו עוֹד, לָא יָדַע בַּר נָשׁ לְאָן אַזְלַת, וְהִיא תָּבַת לְאַתְרָהּ, וְאִתְגְּנִיזַת בְּפִתְחָא דָּא וְאִיהִי תִּטּוֹל עֲטָרָה בְּפוּמָהָא, וּתְשָׁוִי עַל רֵישֵׁיהּ דְּמַלְכָּא מְשִׁיחָא, מָטֵי וְלָא מָטֵי, וּכְדֵין כְּתִיב, (תהילים כ״א:ד׳) תָּשִׁית לְרֹאשׁוֹ עֲטֶרֶת פָּז.","וְכֵיוָן דְּיִקְרֵי מַלְכָּא מְשִׁיחָא בְּסֵפֶר תּוֹרָה. יְקוּמוּן תְּרֵין נְשָׁרִין, דָּא מִכָּאן וְדָא מִכָּאן, וְיוֹנָה מָאִיךְ, וּמַלְכָּא מְשִׁיחָא נָחִית, וְעִטְרָה עַל רֵישֵׁיהּ, עַד דַּרְגָּא בַּתְרָאָה. וּתְרֵין נְשָׁרִין פַּרְחִין לְעֵילָּא עַל רֵישֵׁיהּ, וְיוֹנָה תָּבָאת וַעֲטָרָה בְּפוּמָהּ, וִיקַבְּלוּן לָהּ אִלֵּין תְּרֵין נְשָׁרִין."],[[0,"ורבי כרוספדאי וכו׳:","ור״כ חמוד הלב, פירש מקרא הזה מטרם שנסתלק, ופירש יפה. \u0003מגדל עז,\u0004 זהו התיבה, לשום בו הס״ת שהוא \u0003עז,\u0004 ולהוציאו מתוך ההיכל, שהוא צורת היכל הפנימי, שה״ס אמא, שממנו יוצאת התורה, שהוא ז״א. ומגדל ההוא שהוא התיבה הוא שם ה׳, וצורה שלו, דהיינו המלכות, והוא צריך להיות בשש מדרגות, כנגד חג״ת נה״י שבמלכות."],[1,"בו ירוץ צדיק:","שואל, במי ירוץ, אם במגדל או בספר תורה. ומשיב, אלא שדרש המקרא בזה ובזה, במגדל ובס״ת, כשדרש במגדל, צריך הצדיק להיות חזן הכנסת, ויהיה צדיק אמת וצורת צדיק העליון, שהוא יסוד. כשדרש בספר תורה, מי שעלה לס״ת לקרות בתורה צריך להיות צדיק. ונקרא צדיק, מי נקרא צדיק מכל ז׳ הקרואים לס״ת. היינו העולה לששי מאלו השבעה. כי פרשה הששית רומזת ליסוד הנקרא צדיק. א״ר שמעון ודאי הוא כן. כי הוא, ר׳ כרוספדאי, לא עלה כל ימיו אלא לעליה הששית מאלו העולים לתורה. הרומזת ליסוד צדיק. \u0003ובו ירוץ\u0004 צדיק, יהיה פירושו, בס״ת ירוץ דברי צדיק הזה. שואל \u0003ונשגב,\u0004 ממי. ומשיב מיראת מלאך המות, כי יאריך ימים. \u0003ונשגב,\u0004 היינו שלא ינזק לעולם."],[2,"בההוא מגדל דסלקא וכו׳:","באותו המגדל העולה בין המגדלים, עומד אור אחד בצורת ספר תורה. כשבא אותה הצפור היא לוקחת את המגדל ממקומו ומעמידה אותו באמצע העזרה, תוך כנפי הכרובים. ומה שהיה רומו לרום השמים נשפל ונכנס תחת הכרובים. וחומות המגדל בין ראשי הכרובים."],[2,"","ביאור המאמר. סוד קריאת התורה ה״ס גילוי הארת החכמה שבקו האמצעי הנקרא תורה. וע״כ יש כאן ג׳ בחינות. א׳ הוא ההיכל, דהיינו ארון הקודש שמשם מוציאים ספר התורה. ב׳ הוא הספר תורה שקוראים בה. ג׳ הוא המגדל, דהיינו הבימה שעליה מניחים ספר התורה. והנה ההיכל ה״ס בינה, שמשם נאצלת הספר התורה ומקבלת ממנה כל המוחין. וספר התורה, ה״ס ז״א, היוצא ונאצל מן הבינה. והמגדל ה״ס מלכות. ששם מקום הגילוי של קריאת התורה, שה״ס הארת החכמה. באופן שהתורה שה\"ס ז״א מקבלת הארת החכמה מן הבינה שה״ס ההיכל ומגלה אותה במגדל, שה״ס המלכות. ואין לדמות הארת חכמה זו להארת החכמה הנגלית בחצות לילה, כי שם נגלה הארת החכמה מבחינת השמאל, בסו\"ה שמאלו תחת לראשי. וע״כ אין שם אור היום. משא״כ כאן הארת החכמה נגלית מבחינת קו אמצעי ביחוד, הכולל חכמה וחסדים יחדיו. ומה גם שהכל נמצא תחת שליטת החסדים שהוא אור היום."],[2,"","וזה אמרו, \u0003בין כלהו מגדלין, אית חד מגדל דאבן מטא באמצעיתא,\u0004 המלכות בכללה נקראת מגדל ונקראת אבן טוב. וע״כ גם מדרגותיה בפרטיות נקראות מגדלים. ומדייק \u0003מגדל דאבן טבא באמצעיתא,\u0004 שה״ס קו האמצעי של המלכות, המקבלת מקו האמצעי דז״א. \u0003ודא סליק לרום רקיע,\u0004 דהיינו שמזדווגת עם ג״ר דז״א הנקרא רום רקיע. \u0003ולא אתחזי השתא,\u0004 כי בעת שהיא בזווג עם ג״ר דז״א, אין בה אלא חסדים דז״א, שהיא מדת ז״א, ומדתה עצמה שה״ס חכמה, אינה נראית בה אז. \u0003עד ההוא זמנא דיתגלי,\u0004 דהיינו בזמן קריאת התורה, שאז מתגלה בה הארת החכמה ע״י קריאת התורה כנ״ל. \u0003רב מתיבתא המא ליה, והוה רשים ביה לעילא\u0004 וכו'. דהיינו שרשם עליו שראיתו היה בסוד צדיק וכנסת ישראל המרומז בכתוב מגדל עוז וגו'."],[2,"","וז״ש \u0003מגדל עוז דא תיבה,\u0004 דהיינו המלכות, וספר התורה שהוא \u0003עז,\u0004 דהיינו הארת החכמה הנקראת עז, \u0003לשואה ביה,\u0004 לשום הארת החכמה במגדל שהיא מלכות. \u0003ולאפקא ליה מגו היכל וכו׳ דמניה תורה נפקא\u0004 שז״א הנקרא תורה יוצא ומקבל אורותיו מן ההיכל שהוא בינה. וז״ש, \u0003וההוא מגדל שם ה׳ איהו,\u0004 שהוא המלכות הנקראת שם ה׳. \u0003ואצטריך בשית דרגין,\u0004 דהיינו בו״ק של המלכות, כי אין החכמה נגלית בג״ר של המלכות אלא בו״ק שלה. \u0003בו ירוץ צדיק\u0004 וכו'. דהיינו שהשפעת הארת החכמה הוא ע״י היסוד דז״א. שיתכן ב \u0003ס״ת,\u0004 מבחינה ההשפעה, שהוא העולה לששי. ויתכן ב \u0003מגדל\u0004 מבחינת הקבלה, שמקבל מיסוד דז״א."],[2,"","ומפרש הדברים יותר בפרטות, ואומר, \u0003בההוא מגדל דסלקא בין אינון מגדלין,\u0004 דהיינו במגדל דאמצעיתא (כנ״ל אות ק״מ) \u0003קיימא נהירו חד בדיוקנא דספר התורה.\u0004 שה״ס הארת החכמה בצורת קו האמצעי, אמנם אינה נראית שם מחמת הארת הזווג דז״א כנ״ל. שאין שם מקום לגילוי הארת החכמה. ובחינת החכמה שבמלכות נקראת צפור. וז״ש, \u0003כד אתי ההוא ציפרא,\u0004 דהיינו שהגיע זמן הארת הצפור, שה״ס החכמה שבמלכות, \u0003נטלא ההוא מגדל מאתריה,\u0004 שלוקחת כללות המלכות הנקראת מגדל, ממקומו, דהיינו ממקום הזווג דג״ר דז״א, הנקרא רום רקיע, (כנ״ל באות קל״ז) \u0003וקאים גו אמצעיתא דעזרה,\u0004 שמעמידה את המגדל באמצע העזרה. כי הו״ק דמלכות מכונה עזרה, וההיכל הפנימי וקה״ק ה״ס ג\"ר דמלכות. ומשום שאין החכמה נגלית אלא במקום ו״ק ע״כ מכניסה המגדל בעזרה, שהוא מקום ו״ק. ובסוד קו אמצעי שבה. \u0003גו גדפי דכרובים,\u0004 הכרובים ה״ס אפי זוטרי, דהיינו זו״ן במוחין דאחורים (כנ״ל בהקדמת ספר הזהר דף ו׳ ד״ה ואלמלי) ויש להם כנפים לכסות הג״ר דחכמה, וע״כ מעמיד המגדל תחת הכנפים ההם, כדי שלא יתגלו ג״ר דחכמה."],[2,"","וזה נבחן לירידה כלפי המלכות, כי מקודם לכן היתה בזווג עם ג\"ר דז״א שה״ס רום רקיע, ועתה ירדה לבחינת עזרה, שהיא ו״ק כנ״ל, ולתחת כנפי אפי זוטרי, שהם הכרובים, שהם בחינת ג״ר דו״ק. וז״ש, \u0003ומה דהוה רומיה לרום שמיא,\u0004 דהיינו שהיתה בזווג עם ג״ר דז״א שנקרא שמים. \u0003מאיך ועאל תחות אינון כרובין,\u0004 דהיינו שירדה לתחת אפי זוטרי, הנחשבים לו״ק דמוחין, ולאחורים. כי אין החכמה מתגלה במלכות אלא בכלים דאחורים שלה, (כנ״ל בהקדמת ספר הזהר דף ז׳ ד\"ה בגין) \u0003ושורוי, בין רישי כרובים.\u0004 החומות, הם הדינים הנגלים עם החכמה השומרים שלא יקרבו החיצונים לג\"ר דחכמה (כנ״ל אד״ר נשא אות רי״ט) שנחשבים כחומות על המגדל השומרים מפני החיצונים. ודינים אלו נמצאים בראשי הכרובים, לדחות משם החצונים."],[3,"תלת מאה פתחין וכו׳:","שלש מאות פתחים שם, בהמגדל, בפתח שבאמצע עומד אור זה של צורת ספר התורה, שבו עתיד מלך ישראל לקרות בפרשת הקהל. וזה יהיה מלך המשיח, ולא אחר."],[3,"","פירוש. שלש מאות פתחים רומזים על ג\"ר, שכל אחת כוללת מאה. ופתח שבאמצע, רומז על קו האמצעי. וקריאת פרשת הקהל, ה״ס גילוי ג\"ר דחכמה, שלא תתגלה אלא בגמר התקון, ואז יקרא בו מלך המשיח. אבל לא לפני גמר התקון, וז״ש, \u0003ודא ליהוי מלכא משיחא, ולא אחרא.\u0004"],[4,"ובההוא ס״ת דההוא וכו׳:","ובאותו ספר תורה של אור הזה, כלומר בהארת ו״ק דחכמה שבאותו ספר תורה, בעל המאמר פונה אל השומע, ואמר אהה, חסיד קדוש, אשרי הוא מי שישמע מפיו של המשיח, קול נעימות דבריו מאלו דברים הסתומים שמפרש בתורה דהיינו באור של אותו ספר תורה הנ״ל, בכל ראשי חדשים ושבתות ומועדים וזמנים. וכשכל בני הישיבה רוצים לעלות למעלה לישיבה של הרקיע, שהוא ישיבה של מטטרון, כולם מתאספים אל מלך המשיח, והוא מפרש להם דברי תורה, ומתוך מתיקות דבריו והשתוקקות, עולים למתיבתא דרקיע. ובעל המאמר פונה שוב אל השומע, ואמר לו, כל עשרת הדברים מאלו הדברים שמלך המשיח פירש, גנוזים לך ליום של הבקשות שלך. כלומר, ליום שתתפלל על זה."],[5,"כד קיימא ההוא וכו׳:","כשמגדל ההוא עומד באמצע העזרה (כנ״ל אות ק״מ) ופתח זה פתוח, דהיינו הפתח שבקו האמצעי שבמגדל, אלו הכרובים פותחים פיהם, ופורשים כנפיהם, להסתיר הג״ר דחכמה כנ״ל, ומאירים באור העליון על אותו הפתח, וספר התורה ההוא פתוח, והכרובים פותחים ואומרים מה רב טובך אשר צפנת ליראיך וגו׳. אח״כ סוגרים הפתחים וספר התורה נגלל."],[6,"מאן חמא נהירו וכו׳:","מי ראה אור המאיר של ספר התורה ההוא, כולו הוא אור המאיר, האותיות עולו הן שלהביות אש מד׳ צבעים, שהן מעולם העליון, כולן בולטות ומנצצות. אין מי שיכול לעמוד בהם חוץ ממשיח."],[6,"","פירוש. הארת החכמה שבמלכות נמשכת בג׳ צבעים, לבן אדום ירוק, שה״ס ג׳ קוין, אבל הצבע שלה עצמה, שהוא שחור או תכלת, אין נראה בה, מטעם היותה נמתקת כולה בבינה, בסוד נקודת המפתחא, ונקודתה עצמה, שה״ס מנעולא גנוזה ואינה נראית. משא״כ בז״א בו משמשת ג״כ נקודה דמנעולא (כנ״ל ויקרא דף ל״ה ד״ה אמנם). ולפיכך אין מקום גילוי החכמה בז״א אלא במלכות. וז״ש, \u0003אתוון דיליה שלהובי דאשא מד׳ גווני,\u0004 דהיינו לבן אדום ירוק וגם שחור. ולפיכך, \u0003ליה מאן דיכיל למיקם בהו בר משיח.\u0004 משום שיש לו אור היחידה. אבל לאחר אינם מושגים, מפני גוון השחור."],[7,"סגיר פתחא דא וכו׳:","נסגר פתח הזה, שבמגדל, הכרובים משתככים, ומגדל ההוא פורח ועומד במקומו בין שאר מגדלים. כלומר, שחוזר לזווג הג״ר שלו עם ז״א. ומדתה של המלכות חוזרת ונעלמת, שנכללת בז\"א (כנ״ל אות ק״מ בהסולם)."],[8,"בההוא פתחא דאמצעיתא:","בפתח ההוא שבאמצע הפתחים של המגדל, כנ״ל, יש עטרת פז עליונה ויקרה, גנוזה, שאינה נראית עתה, מפותחת ונחקקת בכל מיני אבני יקר, ועתידה להיות על ראשו של מלך המשיח, בעת שיעלה במגדל ההוא, וב' נשרים, זה מצד זה וזה מצד זה לוקחים העטרה בידיהם."],[9,"כד סליק מלכא וכו׳:","כשעולה מלך המשיח, בהמגדל, מתתקנים הנשרים ולוקחים עטרה הזו. בשעה שיתחיל לקרות בתורה, פתח אחר יפתח, ומשם תצא יונה ההיא ששלח נח בימי המבול, שכתוב, וישלח את היונה. \u0003היונה,\u0004 עם \u0003ה׳\u0004 הידיעה, היינו יונה ההיא הנודעת, שלא דברו בה הראשונים, ולא ידעו מה היא. אלא מכאן יוצאת ועושה שליחות."],[10,"ובשעתא דכתיב, ולא וגו׳:","ובשעה שכתוב, ולא יספה שוב אליו עוד, לא ידע אדם לאן הלכה. והיא חזרה למקומה, ונגנזה בפתח הזה. והיא תקח העטרה בפיה, ותשום על ראשו של מלך המשיח, מטי ולא מטי. ואז כתוב, תשית לראשו עטרת פז."],[11,"וכיון דיקרי מלכא וכו׳:","וכיון שיקרא מלך המשיח בספר התורה. יקומו ב׳ נשרים זה מכאן וזה מכאן, והיונה משפלת עצמה לרדת, ומלך המשיח יורד והעטרה על ראשו, עד מדרגה האחרונה. ושני נשרים פורחים למעלה על ראשו. והיונה חוזרת ועטרה בפיה, ואלו ב׳ נשרים מקבלים אותה."]],[[0,"","וְרַבִּי כְּרוּסְפְּדַאי חֲמוּד הַלֵּב פֵּרַשׁ פָּסוּק זֶה עַד שֶׁלֹּא הִסְתַּלֵּק, וּפֵרַשׁ יָפֶה. מִגְדַּל עֹז - זוֹ תֵבָה. וְסֵפֶר תּוֹרָה שֶׁהוּא עֹז, לָשִׂים בּוֹ, וּלְהוֹצִיאוֹ מִתּוֹךְ הַהֵיכָל, דְּמוּת הֵיכָל הַפְּנִימִי, שֶׁמִּמֶּנּוּ יָצְאָה תוֹרָה, וְאוֹתוֹ מִגְדָּל שֵׁם ה' הוּא וּדְמוּתוֹ, וְצָרִיךְ בְּשֵׁשׁ דְּרָגוֹת."],[1,"","בּוֹ יָרוּץ צַדִּיק, בַּמֶּה? בְּמִגְדָּל אוֹ בְּסֵפֶר תּוֹרָה? אֶלָּא הַפָּסוּק נִדְרָשׁ בָּזֶה וּבָזֶה. כְּשֶׁדּוֹרְשִׁים בְּמִגְדָּל, צָרִיךְ צַדִּיק זֶה שֶׁיִּהְיֶה חַזַּן הַכְּנֶסֶת צַדִּיק אֱמֶת, וּדְמוּת שֶׁל צַדִּיק עֶלְיוֹן. כְּשֶׁדּוֹרְשִׁים בְּסֵפֶר תּוֹרָה, מִי שֶׁעוֹלֶה לַסֵּפֶר תּוֹרָה לִקְרֹא בַתּוֹרָה, צָרִיךְ צַדִּיק, וְצַדִּיק נִקְרָא. מִי נִקְרָא צַדִּיק מִכֻּלָּם? הַשִּׁשִּׁי שֶׁעוֹלֶה מֵאוֹתָם שִׁבְעָה. אָמַר רַבִּי שִׁמְעוֹן, וַדַּאי שֶׁהוּא לֹא עוֹלֶה כָּל יָמָיו, אֶלָּא שִׁשִּׁי לְאוֹתָם שֶׁעוֹלִים. בּוֹ יָרוּץ צַדִּיק, בְּסֵפֶר תּוֹרָה יָרוּץ דִּבְרֵי צַדִּיק זֶה. וְנִשְׂגָּב מִמָּה? מִפַּחַד מַלְאַךְ הַמָּוֶת, שֶׁהֲרֵי מַאֲרִיךְ יָמִים. וְנִשְׂגָּב שֶׁלֹּא יִנָּזֵק לְעוֹלָם."],[2,"","בְּאוֹתוֹ מִגְדָּל שֶׁעוֹלֶה בֵּין אוֹתָם מִגְדָּלִים קַיָּם אוֹר אֶחָד בִּדְמוּת סֵפֶר תּוֹרָה. כְּשֶׁבָּאָה אוֹתָהּ צִפּוֹר, לוֹקַחַת אוֹתוֹ מִגְדָּל מִמְּקוֹמוֹ, וְעוֹמֶדֶת תּוֹךְ אֶמְצַע הָעֲזָרָה תּוֹךְ כַּנְפֵי הַכְּרוּבִים הָיָה. (ומה שהיה), רוּמוֹ לְרוּם הַשָּׁמַיִם נִשְׁפָּל וְנִכְנָס תַּחַת אוֹתָם כְּרוּבִים, וְחוֹמוֹתָיו בֵּין רָאשֵׁי הַכְּרוּבִים."],[3,"","שְׁלֹש מֵאוֹת פְּתָחִים שָׁם, בַּפֶּתַח הָאֶמְצָעִי עוֹמֵד מָאוֹר זֶה, דְּמוּת סֵפֶר תּוֹרָה, בּוֹ עָתִיד מֶלֶךְ יִשְׂרָאֵל לִקְרֹא בְּפָרָשַׁת הַקְהֵל, וְזֶה יִהְיֶה מֶלֶךְ הַמָּשִׁיחַ, וְלֹא אַחֵר."],[4,"","וּבְאוֹתוֹ סֵפֶר תּוֹרָה שֶׁל אוֹתוֹ אוֹר, אִי חָסִיד קָדוֹשׁ, אַשְׁרֵי מִי שֶׁמִּפִּיו יִשְׁמְעוּ קוֹל נְעִימוּת שֶׁל דְּבָרָיו מֵאוֹתָם דְּבָרִים סְתוּמִים שֶׁפֵּרַשׁ בַּתּוֹרָה. בְּכָל רֹאשׁ חֹדֶשׁ וְשַׁבָּתוֹת וּמוֹעֲדִים וְחַגִּים, כְּשֶׁרוֹצִים כָּל בְּנֵי הַיְשִׁיבָה לַעֲלוֹת לְמַעְלָה לְתוֹךְ יְשִׁיבַת הָרָקִיעַ, כֻּלָּם מִתְכַּנְּסִים אֶל מֶלֶךְ הַמָּשִׁיחַ, וְהוּא מְפָרֵשׁ דְּבָרִים, וּמִתּוֹךְ מְתִיקוּת דְּבָרָיו בְּעֶרְגָּה עוֹלִים. כָּל עֲשֶׂרֶת הַדְּבָרִים גְּנוּזִים לְךְ מֵאוֹתָם דְּבָרִים שֶׁפֵּרַשׁ לַיּוֹם שֶׁל הַשְּׁאֵלוֹת שֶׁלְּךְ."],[5,"","כְּשֶׁעוֹמֵד אוֹתוֹ מִגְדָּל בְּאֶמְצַע הָעֲזָרָה וּפֶתַח זֶה פּוֹתֵחַ, פּוֹתְחִים אוֹתָם כְּרוּבִים פִּיהֶם, וּפוֹרְשִׂים כַּנְפֵיהֶם, וּמֵאִיר אוֹר עֶלְיוֹן עַל אוֹתוֹ פֶּתַח. וְאוֹתוֹ סֵפֶר תּוֹרָה נִפְתָּח, וְאוֹתָם כְּרוּבִים פּוֹתְחִים וְאוֹמְרִים: (תהלים לא) מָה רַב טוּבְךְ אֲשֶׁר צָפַנְתָּ לִּירֵאֶיךְ וְגוֹ'. נִסְגָּרִים הַפְּתָחִים, וְסֵפֶר הַתּוֹרָה נִגְלָל."],[6,"","מִי רָאָה אוֹר הַמֵּאִיר שֶׁל אוֹתוֹ סֵפֶר תּוֹרָה, כֻּלּוֹ אוֹר מֵאִיר, אוֹתִיּוֹת שֶׁלּוֹ, שַׁלְהֲבוֹת אֵשׁ מֵאַרְבָּעָה גְוָנִים שֶׁהֵם מֵעוֹלָם עֶלְיוֹן, כֻּלָּם בּוֹלְטִים וְנוֹצְצִים, אֵין מִי שֶׁיָּכוֹל לַעֲמֹד בָּהֶם פְּרָט לַמָּשִׁיחַ."],[7,"","נִסְגָּר פֶּתַח זֶה, וּכְרוּבִים שׁוֹכְכִים, וְאוֹתוֹ מִגְדָּל פּוֹרֵחַ וְעוֹמֵד בִּמְקוֹמוֹ בֵּין שְׁאָר הַמִּגְדָּלִים."],[8,"","בְּאוֹתוֹ פֶּתַח אֶמְצָעִי יֵשׁ עֲטֶרֶת פָּז עֶלְיוֹנָה וְנִכְבָּדָה גְּנוּזָה, שֶׁלֹּא נִרְאֵית כָּעֵת, גְּלוּפָה וַחֲקוּקָה בְּכָל מִינֵי אֲבָנִים יְקָרוֹת, וַעֲתִידָה לִהְיוֹת עַל רֹאשׁ מֶלֶךְ הַמָּשִׁיחַ כְּשֶׁעוֹלֶה בְּאוֹתוֹ מִגְדָּל, וּשְׁנֵי נְשָׁרִים, זֶה מִצַּד זֶה וְזֶה מִצַּד זֶה, לוֹקְחִים אוֹתוֹ בִּידֵיהֶם."],[9,"","כְּשֶׁעוֹלֶה מֶלֶךְ הַמָּשִׁיחַ, מִתְתַּקְּנִים הַנְּשָׁרִים, וְלוֹקְחִים עֲטָרָה זוֹ בְּשָׁעָה שֶׁיַּתְחִיל לִקְרֹא, יִפָּתַח פֶּתַח אַחֵר, וּמִשָּׁם תֵּצֵא אוֹתָהּ יוֹנָה שֶׁשָּׁלַח נֹחַ בִּימֵי הַמַּבּוּל, שֶׁכָּתוּב (בראשית ח) וַיְשַׁלַּח אֶת הַיּוֹנָה. הַיּוֹנָה, אוֹתָהּ הַנּוֹדַעַת, וְלֹא דִבְּרוּ בָהּ הַקַּדְמוֹנִים וְלֹא יָדְעוּ מַה הִיא, אֶלָּא מִכָּאן יָצְאָה וְעָשְׂתָה שְׁלִיחוּתָהּ."],[10,"","וּבְשָׁעָה שֶׁכָּתוּב וְלֹא יָסְפָה שׁוּב אֵלָיו עוֹד, לֹא יָדַע אָדָם לְאָן הָלְכָה, וְהִיא שָׁבָה לִמְקוֹמָהּ וְנִגְנְזָה בְּפֶתַח זֶה, וְהִיא תִּקַּח עֲטָרָה בְּפִיהָ וְתָשִׂים עַל רֹאשׁ מֶלֶךְ הַמָּשִׁיחַ, הִגִּיעַ וְלֹא הִגִּיעַ, וְאָז כָּתוּב, (תהלים כא) תָּשִׁית לְרֹאשׁוֹ עֲטֶרֶת פָּז."],[11,"","וְכֵיוָן שֶׁיִּקְרָא מֶלֶךְ הַמָּשִׁיחַ בְּסֵפֶר תּוֹרָה, יָקוּמוּ שְׁנֵי נְשָׁרִים, זֶה מִכָּאן וְזֶה מִכָּאן, וְיוֹנָה מִתְכּוֹפֶפֶת, וּמֶלֶךְ הַמָּשִׁיחַ יוֹרֵד, וַעֲטָרָה עַל רֹאשׁוֹ, עַד מַדְרֵגָה אַחֲרוֹנָה. וּשְׁנֵי נְשָׁרִים פּוֹרְחִים לְמַעְלָה עַל רֹאשׁוֹ, וְיוֹנָה שָׁבָה וַעֲטָרָה בְּפִיהָ, וִיקַבְּלוּ אוֹתָהּ שְׁנֵי נְשָׁרִים אֵלּוּ."]]],[["דָּוִד מַלְכָּא, זַיִת רַעֲנָן אִקְרֵי קַמֵּיהּ קוּדְשָׁא בְּרִיךְ הוּא, דִּכְתִּיב, (תהילים נ״ב:י׳) וַאֲנִי כְּזַיִת רַעֲנָן בְּבֵית וְגוֹ'. עֲלֵה זַיִת, דָּא מַלְכָּא מְשִׁיחָא בְּרֵיהּ דְּדָוִד. וְדָּא אִיהוּ דְּרָמִיז יוֹנָה דָּא בְּיוֹמוֹי דְּנֹחַ, דִּכְתִּיב, (בראשית ח׳:י״א) וְהִנֵּה עֲלֵה זַיִת טָרָף בְּפִיהָ. הַהוּא עֲלֵה זַיִת, טָרָף וְחָטַף לִיקָרָא דִּילֵיהּ. בְּמָה. בְּפִיהָ. דְּקַיְּימָא עַל רֵישֵׁיהּ, וּמְקַבְּלָא יְקָר מֵהַאי יוֹנָה וְהַאי דִּכְתִּיב טָרָף, וְלָא טָרְפָה, (אלא) כִּדְכוּרָא דָּא, דְּעֲבַיד חֵילָא וְנָצַח. בִּמְתִיבְתָּא דִּרְקִיעַ, יוֹנָה דְּכַר הוּא, מִגּוֹ דְּאִקְרֵי יוֹנָה, כְּתִיב כְּנוּקְבָּא, וּכְתִיב כִּדְכוּרָא, בְּזִמְנָא דִּמְקַבְּלָא יְקָר (חסר) דָּא.","מִגְדָּ\"ל דָּא כַּד תָּב לְאַתְרֵיהּ, נָהִיר כִּנְהִירוּ דְּעֵינָא דְּשִׁמְשָׁא, דִּכְתִּיב, (תהילים פ״ט:ל״ז) כִּסְאוֹ כַּשֶּׁמֶשׁ נֶגְדִּי. וְאַף דְּכֻרְסְיָיא אַחֲרָא לִיהֱוִי לֵיהּ בְּנִסִּין וְאָתִין רַבְרְבִין. בְּרֵישׁ מִגְדָּל דָּא, אִית עוֹפִין דְּנוּר (דרורא) דְּקָא מְצַפְצְפָאן, כַּד סָלִיק צַפְרָא, צִפְצוּפָא דִּנְעִימוּ, דְּלֵית נְעִימוּ וְנִגּוּנָא כְּהַהוּא נְעִימוּ.","לְעֵילָּא מְכֻּלְּהוּ, זִינִין אַחֲרָנִין, וְשַׁפְנִינִין אַחֲרָנִין, דְּקָא פַּרְחִין בַּאֲוִירָא, סַלְקֵי וְנַחְתֵּי, נַחְתֵּי וְסַלְקֵי, לָא מִשְׁתַּכְכִין לְעָלְמִין. אַתְוָון רַבְרְבָן, וְאַתְוָון זְעִירָן, פַּרְחִין בֵּינַיְיהוּ.","אִי חֲסִידָא קַדִּישָׁא, בְּשַׁעֲתָא דְּאַתְוָון פַּרְחִין, חָמֵי בַּר נָשׁ בְּאַתְוָון רַבְרְבָן. כְּתִיב בַּאֲוִירָא לְפוּם שַׁעֲתָא, (בראשית א׳:א׳-ב׳) בְּרֵאשִׁית בָּרָא אֱלֹהִים אֵת הַשָּׁמַיִם וְאֵת הָאָרֶץ (והארץ היתה תהו ובהו וגו', מהכא אהדרי אתוון רברבן כמלקדמין) בַּטְשֵׁי אַתְוָון זְעִירָן בְּהוּ, וּפַרְחִין, וְאִתְחַזֵּי מִנַּיְיהוּ כְּתִיב, וַיֹּאמֶר אֱלֹהִים יְהִי אוֹר וְגוֹ', וַיַּרְא אֱלֹהִים אֶת הָאוֹר וְגוֹ'. לְבָתַר מְהַדְּרֵי אַתְוָון זְעִירָן, וּבַטְשֵׁי בְּאַתְוָון רַבְרְבָן, וּמִתְחֲזֵי מִנַּיְיהוּ דִּכְתִּיב, וַיֹּאמֶר אֱלֹהִים יְהִי רָקִיעַ וְגוֹ'. וְכֵן כָּל עוֹבָדָא דִּבְרֵאשִׁית, פְּלִיאָן רַבְרְבָן, וְחֵדּוּ לְעַיְינִין עוֹבָדָאן דְּאַתְוָון אִלֵּין, זַכָּאָה עַמָּא דְּכָל דָּא מְחַכָּאן.","אִי חֲסִידָא קַדִּישָׁא, מַאן דְּנָטִיר בְּרִית, שַׁוִּי לֵיהּ אֲבַתְרוֹי, וְאִיהִי לְקָמָא. וְאִי תֵּימָא, מַאן נָטִיר לַאֲחוֹרָא. הָא נְטִירוּ רַב וְעִלָּאָה מִכֹּלָּא, דְּנָטִיר לֵיהּ. וּמַאן אִיהוּ. צַדִּיק עִלָּאָה בִּרְחִימוּ סַגִּי. עָאל בֵּין צַדִּיק וְצֶדֶק. וְאִשְׁתְּכַח נָטִיר מִכָּל סִטְרִין. זַכָּאָה מַאן דְּנָטִיר בְּרִית דָּא. וְעַל דָּא יִשְׂרָאֵל, אִתְחָזוּן כָּל דְּכוּרִין, דְּנַטְרִין אָת קַיָּימָא דָּא, קַמֵּי מַלְכָּא קַדִּישָׁא. מַאן אִיהוּ דְּיָכִיל לְנַזְקָא לִבְרָא, דְּאִיהוּ בְּאֶמְצָעוּ אֲבוּהָ מִכָּאן, וְאִמֵּיהּ מִכָּאן, וְאִיהוּ בֵּינַיְיהוּ. וְדָא כַּד אִיהוּ אַחֲרֵי יְיָ.","תָּא חֲזֵי הַהוּא רָקִיעַ כַּד סָחֲרָא בְּגִלְגּוּלָא מְנַגְּנָא בְּנִגּוּנָא, וּמִקַל נְהִימוּ דְּמַיִין דְּנַבְעִין, לָא יְדִיעַ הַהוּא נִגּוּנָא. כָּל אִינּוּן אַגָּנִין דִּי בְּאַרְבַּע סִטְרִין, מַלְיָין מִנְּבִיעוּ דְּמַיִין דְּנַבְעִין. מַאן דְּאִיהוּ לְגוֹ, בִּתְרֵין סִטְרִין קַיְּימָא תַּמָּן. חַד בְּחֶדְוָה, דְּלֵית חֶדְוָה כְּהַהִיא חֶדְוָה בְּעָלְמָא, לְקַיְּימָא (תהילים ק׳:ב׳) עִבְדוּ אֶת יְיָ בְּשִׂמְחָה. וְחַד בְּיִרְאָה, דְּלֵית דְּחִילוּ כְּהַהוּא דְּחִילוּ בְּעָלְמָא, לְקַיְּימָא (תהילים ב׳:י״א) עִבְדוּ אֶת יְיָ בְּיִרְאָה.","חַד מַעְיָינָא דְּמַיָּיא, דִּנְבִיעַ מִסְּטַר מִזְרָח, דָּא הוּא דְּאָמַר יְחֶזְקֵאל נְבִיאָה. מֵהַאי מַעְיָינָא, לָא יַכְלִין לְסַיְּימָא שְׁבָחָא כָּל בְּנֵי עָלְמָא. בַּאֲתַר דְּאִתְיְילִיד תַּמָּן לִסְטַר מִזְרָח, לֵית עוּמְקָא וְרוּמָא דִּילֵיהּ, אֶלָּא זְרָתָא וְלָא יַתִּיר.","כַּד נַבְעִין מַיָּא וְסַלְּקִין, סַלְּקִין כָּל זִינֵי מַרְגְּלָאן דְּעָלְמָא, וְלָא נַפְלִין לְבַר, הַשְׁתָּא אִתְחָזוּן בְּגָוְון חַד, לְפוּם שַׁעֲתָא נַפְלִין אִלֵּין, וְהָא סַלְּקִין, אָחֳרָנִין, כְּגָוַון אָחֳרָא, בְּכָל זִינֵי גַּוְונִין דְּעָלְמָא. נַפְלֵי אִינּוּן מַרְגְּלָאן, וְלָא נַפְלֵי לְבַר.","סַחֲרָנִין דְּהַהוּא נְבִיעוּ, חֵיזוּר וְשׁוּשָן סָחֲרִין. וְלָא יַכְלִין כָּל בְּנֵי עָלְמָא לְמֵיקָם עַל אִינּוּן גַּוְונִין, כֻּלְּהוּ שַׁלְהוֹבִין מְלָהֲטָאן, וְלָא יַכְלִין לְאִסְתַּכְּלָא בְּהוּ. לָא יְדִיעַ חֲשִׁיבוּ דְּעוֹבָדָא. טַרְפִּין דִּלְהוֹן מְנַצְצָן בְּכַמָּה גַּוְונִין.","עוֹבֵד צִיּוּר, אוּמָנוּ דְּמָארֵי עָלְמָא, חַפְיָין עַל תְּלַת מְאָה וְשִׁבְעִין וַחֲמִשָּׁה כְּרוּבִין דִּתְחוֹתַיְיהוּ, בָּתַר שְׂבָכִין אַחֲרָנִין לְגוֹ. וְאִינּוּן שְׂבָכִין סְחוֹר דַּעֲזָרָה לְגוֹ."],[[0,"דוד מלכא זית וכו׳:","דוד המלך נקרא \u0003זית רענן\u0004 לפני הקב\"ה, שכתוב, ואני כזית רענן בבית וגו'. \u0003עלה זית\u0004 זה מלך המשיח בנו של דוד. וזה הוא שרמזה יונה זו בימי נח, שכתוב, והנה עלה זית טרף בפיה. עלה זית ההוא, שהוא המשיח, טרף היונה וחטף את היקר שלו, דהיינו העטרה, במה. בפיה. שהעטרה עומדת על ראשו ומקבלת יקר מאותה היונה. וז״ש טרף, לשון זכר, ולא טרפה. שרומז, שהיא כזכר הזה שעושה חיל ומנצח. בישיבה של הרקיע, אמרו, יונה זו היא זכר, משום שהשם יונה שנקראת, כתוב פעם כנוקבא, דהיינו בלשון נקבה, ופעם כדוכרא, בלשון זכר. בזמן שמקבלת יקר זה. בלשון זכר נקראת (חסר כאן)."],[0,"","ביאור המאמר. נודע ששבירת הכלים בזמן הנקודים נשברו לש\"ך ניצוצים, כי ח׳ מלכים נשברו, והיה בכל מלך ד׳ בחינות חו\"ב תו״מ, שבכל אחת עשר ספירות, שהם מ׳ בחינות בכל מלך, ושמונה פעם מ', הם ש״כ בחינות. המכונים ש\"ך ניצוצין. והם נתקנו ע״י המאציל עצמו בעולם התקון, ואחר כך ע״י חטא של עצה״ד, חזרו ונפלו לקליפות. וכל מעשינו בשתא אלפי שני אינם רק לתקן ש״ך ניצוצים אלו, וכשיגמרו להתתקן, אז יהיה גמר התקון, ובלע המות לנצח."],[0,"","אמנם אין ביכלתינו לתקן כל ש\"ך ניצוצים אלו, כי בחינות המלכיות שבעשר ספירות שבכל בחינה, הם בחינת מנעולא שאינה מקבלת תקון, ואין בנו כח לתקן אלא ט׳ ספירות ראשונות, שבכל בחינה, ששם סוד מלכות דמפתחא המתוקנת בבינה, ונכללת ביסוד. אבל המלכיות עצמן, שהם מנעולא אין לנו כח לתקן. באופן שח' מלכים הם, שבכל אחד ד׳ בחינות, והם ל״ב בחינות, אשר ט\"ס ראשונות של כל בחינה אנו יכולים לתקן, והם ט׳ פעם ל״ב, שהם רפ״ח בחינות, ובחינה אחרונה שבע״ס, שהוא ל״ב האחרון, אין אנו יכולים לתקן. והאמת הוא, שאין אנו צריכים לתקן יותר מאלו רפ״ח בחינות, המתוקנות במלכות דמפתחא, המכונה נקודה אמצעית דישובא. ול״ב האחרון, שהם ל״ב מלכיות מבחינתה דמדת הדין הנקראות מנעולא, אינם צריכים תקון מצדינו כלל, אלא ע״י תקון כל רפ״ח בחינות בתכלית השלמות, אז מתקבצים כל האורות שיצאו מרפ״ח האלו, למקום אחד, ואז מתתקן ל״ב האחרון מאליו. ובסוד זה נאמר, והסירותי את ל״ב האבן מבשרכם. דהיינו לב האחרון שתקונו בא מקבוץ הרפ״ח."],[0,"","וכל התקון האמור מקבל מלך המשיח, וגואל את ישראל ומתקן את כל העולם עד למדרגה האחרונה. וע״כ נבחן גמר התקון להמלכות מלך המשיח ששמים עטרת פז על ראשו. ומשום שהתקון נחלק לשתי בחינות, לרפ״ח, שכל עבודתינו היא בהם. ולל\"ב האבן, ששם אין אנו צריכים לעבוד, וגם אסור העבודה בה, כי היא מתתקנת מאליה ע״י השלמת הרפ״ח כנ״ל. לפיכך מבחינים בעטרת המשיח ג״כ ב׳ בחינות אלו. א) היא עצם העטרה, שהיא בירורי רפ״ח, ההולכת ונעשית ע״י עבודתינו במשך שתא אלפי שני. ב) שימת העטרה על ראשו של המשיח. שהיא עצם גמר התקון, כלומר, קהילת כל האורות שיצאו מבירורי רפ״ח ניצוצין, אשר מקהילתם למקום אחד מתתקן ל״ב האבן, שהיא גמר התקון. ונבחן זה לשימת העטרה על ראשו של המשיח."],[0,"","וזה אמרו (באות קמ״ו) \u0003בההוא פתחא דאמצעיתא, אית עטרה דפז\u0004 וכו'. דהיינו בסוד נקודה האמצעית המקבלת מקו האמצעי, שה״ס מפתחא, שם נמצאת העטרה של משיח כלומר, ששם הולכת ונשלמת ע״י בירורי רפ״ח ניצוצין ע״י עבודתינו. כי הארות כל שתא אלפי שני אינן מקובלות רק במלכות דמפתחא שהיא יסוד דמלכות, ואינה מלכות ממש, (כנ״ל בהקדמת ספר הזהר דף מ״ה ד״ה ההיא) וע״כ נבחנת לקו האמצעי, כמו יסוד. \u0003דלא אתחזי השתא,\u0004 היינו מטרם שנגמרה כולה, אינה נראית כלל. אלא בגמר התקון. וז״ש, \u0003כד סליק בההוא מגדל,\u0004 דהיינו לעתיד לבא בגמר התקון כשמלך המשיח יעלה במגדל ההוא, לקריאת ס״ת בפרשת הקהל (כנ״ל באות קמ״א) שקריאת ס״ת ה״ס גילוי הארת החכמה. ופרשת הקהל רומזת לקהילת כל האורות שבס״ת למקום אחד שה״ס שימת העטרה על ראש המשיח, כנ״ל, אמנם יש בזה שתי בחי׳ א) עצם העטרה האורות של ספר התורה המתגלים בה במשך שתא אלפי שני, שזה בא רק מקו אמצעי כנ״ל, וזה נבחן לעלית מלך המשיח אל המגדל, שעוד לא קרא בפרשת הקהל. ועל זה אומר, \u0003ותרין נשרין,\u0004 פני נשר ה״ס קו האמצעי, שהוא כולל ב׳ הקוין ימין ושמאל שה״ס חסדים וחכמה, ולפיכך הם ב׳ נשרים, \u0003דא מסטרא דא,\u0004 היינו בימין שהוא חסדים, \u0003ודא מסטרא דא,\u0004 היינו בשמאל, שהוא חכמה. וז״ש \u0003מתתקנין נשרין ונטלי עטרא,\u0004 שעטרה זו מקובצת מתקון הנשרים שה״ס ב׳ הצדדים שבקו האמצעי והם הלוקחים את העטרה, כי הם מקבצים אותה בזה אחר זה ע״י בירורי רפ״ח ניצוצים כנ״ל. וזו היא בחינה ראשונה. ועתה מדבר מבחינה השניה, שהיא שימת העטרה על ראשו של משיח, ואומר, \u0003בשעתא דישרי למקרי,\u0004 שבשעה שמתחיל לקרות פרשת \u0003הקהל\u0004 (כנ״ל באות קמ״א) שה״ס קהילת כל האורות דרפ״ח ניצוצין למקום אחד המגלים תקון ל״ב האבן, שה״ס שימת העטרה על ראשו של המשיח. \u0003יתפתח פתחא אחרא,\u0004 דהיינו פתח שאינו מבחינת קו האמצעי, אלא היא פתח של בחינת המלכות דמנעולא שהיא מלכות דמדת הדין עצמה שהגיע תקונה ע״י קריאה של פרשת הקהל. \u0003ומתמן תפוק ההיא יונה דשדר נח בימי טופנא,\u0004 שה״ס מלכות דמנעולא, דכתיב, \u0003וישלח את היונה, היונה ההיא דאשתמודעא,\u0004 דהיינו המצוינת, שהיא המנעולא, \u0003ולא מלילו בה קדמאי ולא ידעו מה היא.\u0004 כי ה״ס, נתיב דלא ידעו עיט, שעיט זה משה, שלא ידעה, כמ״ש חז״ל. \u0003אלא מהכא נפקת,\u0004 שהיא יוצאת מפתח הצדדי הנ״ל, ועושית שליחות \u0003והיא תבת לאתרה ואתגניזת בפתחא דא,\u0004 כי נקודה דמפתחא שה״ס הפתח שבאמצע, היא השולטת בבירורי האורות, ונקודה דמנעולא נגנזת ואינה נראית. (כנ״ל בהקדמת ספר הזהר אות קכ״ג) \u0003ואיהי תטול עטרה בפומהא ותשוי על רישיה דמלכא משיחא,\u0004 היינו בעת קריאת פרשת הקהל, שאז מתקהלים כל האורות למקום אחד ול״ב האבן מתתקן, אז תשים העטרה על ראש המשיח, כנ״ל. \u0003מטי ולא מטי\u0004 שהעטרה אינה מתישבת תיכף על ראשו אלא תחילה במטי ולא מטי ואח״כ מתישבת כולה לנצחיות."],[0,"","וזה אמרו, \u0003וכיון דיקרי מלכא משיחא בספר תורה,\u0004 דהיינו בפרשת הקהל, \u0003יקומון תרין נשרין דא מכאן ודא מכאן,\u0004 שהם נושאים העטרה הבאה מקו האמצעי, כנ״ל. \u0003ויונה מאיך\u0004 והיונה, שה״ס מנעולא, נשפלת ויורדת למדרגתה, שהיא בחינה אחרונה של ש״ך הניצוצין, הנקראת ל״ב האבן כנ\"ל, שאין עוד מדרגה נמוכה ממנה, ומשימה משם העטרה על ראשו של המשיח, וע״כ \u0003ומלכא משיחא נחית ועטרה על רישיה, עד דרגא בתראה,\u0004 כי אחר שמדרגה האחרונה נתקנה יורד המשיח עם העטרה לשלוט עד סוף כל המדרגות. ונתבאר לעיל אשר בתחלה עוד העטרה אינה מתישבת על ראשו אלא שהיא בסוד \u0003מטי ולא מטי,\u0004 ולפיכך \u0003תרין נשרין פרחין לעילא על רישיה,\u0004 דהיינו אותם ב׳ הנשרים שלקחו העטרה ונתנו אותה אל היונה, \u0003ויונה תבאת ועטרה בפומה,\u0004 שהיא חוזרת ומקבלת העטרה של משיח, \u0003ויקבלון לה אלין תרין נשרין\u0004 ושני הנשרים מקבלים לה בחזרה, כי שלהם היא העטרה, כנ״ל. ואחר כך לאחר זמן תתישב העטרה על ראש המשיח לנצחיות, כ״ש במקום אחר."],[0,"","ומפרש יותר, ואומר, \u0003דוד מלכא זית רענן אקרי\u0004 וכו׳, שה״ס מלכות דמפתחא שהיא \u0003רענן\u0004 וכל האורות נמשכים על ידיה. \u0003עלה זית דא מלכא משיחא\u0004 וכו׳ שהיא מלכות דמנעולא, ולהיותה שורש למלכות דמפתחא ע״כ נקראת \u0003עלה\u0004 זית, שהיא מעלה את הזית רענן, שהיא מפתחא. \u0003ודא איהו דרמיז יונה\u0004 וכו׳ \u0003עלה זית טרף בפיה.\u0004 עלה זית, פירושו \u0003ההוא עלה זית,\u0004 שהוא משיח. \u0003וטרף,\u0004 היינו \u0003וחטף ליקרא דיליה,\u0004 שהיונה חטפה היקר שלו, דהיינו שחטפה העטרה מן הנשרים, \u0003במה. בפיה,\u0004 דהיינו בבחינת המנעולא שבפיה, \u0003דקיימא על רישיה\u0004 שהעטרה עומדת על ראשו, וכן \u0003ומקבלא יקר,\u0004 שהעטרה מקבלת יקר, הכל \u0003מהאי יונה.\u0004 וענין החטיפה שאומר, רומז שנראה כמו החוטף דבר שאינו שלו, כי כל העטרה יצאה מבחינת קו האמצעי וממלכות דמפתחא, שבה נעשה בירורי כל רפ״ח הניצוצין שמהם נעשתה העטרה. ולבסוף באה היונה שה״ס מלכות דמנעולא וחוטפת כל הכבוד הזה מרשות הנשרים ומלכות דמפתחא, ומשימה אותו על ראשו של משיח, הנמשך ממלכות שלה, שע״כ נקרא עלה זית כנ״ל. וע״כ נרמז בכתוב בלשון חטיפה. \u0003והאי דכתיב\u0004 וכוי, חסר סיום הענין."],[1,"מגדל דא כד וכו׳:","מגדל זה כשחוזר למקומו, דהיינו אחר קריאת התורה (כנ״ל אות ק״מ) שהמלכות חוזרת להתחבר עם ג\"ר דז״א, ע״ש, הוא מאיר כעין אור השמש, דהיינו כאור הז״א שנקרא שמש, שהוא חסדים מכוסים, שכתוב, כסאו כשמש נגדי, שהמלכות הנקרא כסא הוא כשמש, כז״א. והגם שיש לו כסא אחר, בנסים ואותות גדולים. כלומר הגם שמטרם חזרת המגדל לג\"ר דז״א, נקראת ג״כ כסא, והוא באותות גדולים דהיינו בחכמה, עכ״ז לא על זו נאמר כסאו כשמש, אלא אחר חזרתה לז״א נקראת כן. בראש מגדל זה, דהיינו בהיותו למטה מטרם שחזר לג\"ר דז״א, יש עופות של אש שמצפצפים, בעת שעולה הצפור, כלומר בעת שמתגלה החכמה דמלכות המכונה צפור. מתגלים עופות אש, דהיינו שיש בהם אש שהיא דינים להרחיק החצונים, ומצפצפים בצפצוף נעימות, שאין נעימות ונגון כנעימות ההיא."],[2,"לעילא מכלהו זינין וכו׳:","למעלה מכולם, דהיינו בבינה, יש מינים אחרים ותורים אחרים הפורחים באויר, בסוד עלית המלכות לבינה שה״ס ה \u0003י׳\u0004 הנכנסת לאור הבינה והאור נעשה לאויר. עולים ויורדים, יורדים ועולים, כשה \u0003י׳\u0004 נכנסת באויר הם יורדים, למדרגה תחתונה, וכשה \u0003י׳\u0004 יוצאת מאויר וחזר לאור, הם חוזרים ועולים (כנ״ל ב״א דף מ\"ד ד״ה בקע) ואינם נשקטים לעולם. ומפרש, למה הוא כך, הוא משום, אתוון רברבין שהן בינה, ואתוון זעירין שהן מלכות, פורחות ביניהם. שלפעמים עולות אתוון זעירין באתוון רברבין, דהיינו מלכות בבינה, ולפעמים האתוון זעירין חוזרות ויוצאות מאתוון רברבין, שהמלכות חוזרת ויוצאת מבינה, שה״ס \u0003י׳\u0004 הנכנסת באור ויוצאות מאור כנ״ל."],[3,"אי חסידא קדישא וכו׳:","אהה חסיד הקדוש. בשעה שהאותיות פורחות, רואה האדם כתוב מאותיות גדולות, שהם בינה, באויר, לפי שעה, בראשית ברא אלקים וגו', שמלות אלו הם מבינה, שה״ס אתוון רברבין. ואח״כ מכים אותיות הקטנות בהן, דהיינו המלכות עולה ומכה בבינה, כלומר שממעט אותה, בסוד ה \u0003י׳\u0004 שנכנסה לאור ונעשה אויר, ופורחות ונראה מהן כתוב, ויאמר אלקים יהי אור וגו׳. וירא אלקים את האור וגו׳. אח״כ חוזרות אותיות הקטנות ומכות באותיות גדולות, דהיינו ששוב עולה המלכות לבינה וממעט אותה, ונראה מהם שכתוב, ויאמר אלקים יהי רקיע וגו׳. וכן כל מעשה בראשית. מעשה אותיות האלו הן פליאות גדולות ושמחה לעינים. אשרי העם, שלכל זה הם מחכים."],[3,"","פירוש כל מעשה בראשית יצאו בסוד כניסת הי׳ באור הבינה ונעשתה לאויר, שאז יצא הקטנות, ואח״כ ביציאת ה \u0003י׳\u0004 מאויר יצא הגדלות (כנ״ל בראשית א׳ אות ל״א) שה״ס המלה \u0003יהי\u0004 הנאמר בכל מאמר ומאמר דמעשה בראשית. וז״ס שאומר שם \u0003יהי אור,\u0004 כל מה \u0003דנפק ברזא דא נפק,\u0004 ע״ש בהסולם. וז״ש כאן, \u0003חמי בר נש מאתוון רברבן\u0004 שהם בינה, \u0003כתיב באוירא לפום שעתא בראשית ברא אלקים.\u0004 וזה לפי שעה, אבל כשהגיע סוד המאמר יהי אור, \u0003בטשי אתוון זעירן בהו,\u0004 שהמלכות הכה בבינה, שז״ס המלה \u0003יהי,\u0004 וכן \u0003לבתר מהדרי אתוון זעירן ובטשי באתוון רברבן ומתחזי מנייהו דכתיב ויאמר אלקים יהי רקיע\u0004 וגו׳. שגם כאן במאמר הזה הקדים בטישת המלכות בבינה, בסוד המלה \u0003יהי. וכן כל עובדא דבראשית,\u0004 שכן היה בכל מאמר ומאמר (כמ״ש ב״א אות ל״א) \u0003כל מה דנפק ברזא דא נפק.\u0004 עש״ה. ואין להאריך."],[4,"אי חסידא קדישא וכו׳:","אהה חסיד קדוש, מי ששומר ברית משים עצמו אחרי השכינה, והשכינה לפניו. ואם תאמר. מי שומר אותו מאחוריו. ומשיב, הנה שמירה גדולה ועליונה מכל שומרת אותו. ומי היא. הוא צדיק עליון, דהיינו יסוד דז״א, ששומרו באהבה רבה. ונמצא נכנס בין צדיק שהוא יסוד, לבין צדק שהוא מלכות, ונמצא נשמר מכל הצדדים, היסוד מלאחריו, והמלכות מלפניו. אשרי מי ששומר ברית זה. וע״כ ישראל, יראו כל הזכרים, השומרים אות ברית זה, לפני הקב״ה. דהיינו כמ״ש שלוש פעמים בשנה יראה כל זכורך וגו׳. מי הוא שיכול להזיק לבן, שאביו מכאן ואמו מכאן, והוא באמצע ביניהם. וזהו, כשהוא אחרי ה'. דהיינו דוקא אחורי המלכות כנ״ל."],[4,"","פירוש. סוד הברית הוא מילה ופריעה, אשר ע\"י הפריעה מתגלה הארת החכמה, (כנ״ל אות קי״ח) וע״כ השומר בריתו זוכה לגילוי הארת החכמה, ונודע, שהארת החכמה באה מן המלכות, וע״י הפריעה היא מקובלת רק ממטה למעלה ולא ממעלה למטה, בסו״ה וחצו את כספו (כמ״ש שם). נמצא כששומר בריתו הוא משים את המלכות לפניו, כלומר שהארת החכמה מקובלת לו ממלכות ולמעלה, ואין החכמה מגעת אליו מן המלכות, כי אינה מושפעת ממלכות לאחוריה. וז״ש, \u0003מאן דנטיר ברית שוי ליה אבתרוי,\u0004 שמתוך ששומר ברית, דהיינו שלא להמשיך מן המלכות ממעלה למטה, נמצא שהוא אחורי המלכות, כלומר שאינו ממשיך פניה אליו, שפירושו, שאינו מקבל ממנה. וז״ש, \u0003ואי תימא מאן נטיר לאחורא,\u0004 כלומר, כיון שאין ממשיך החכמה אליו מן המלכות, א״כ מי שומר אותו, והלא אור החכמה שומר את האדם מכל המזיקים. וז״ש, \u0003הא נטירו רב\u0004 וכו', כי יסוד דז״א משפיע אליו חסדים מגולים, ונמצא פניו של היסוד דז״א אליו. באופן, שפני היסוד הוא אליו לאחוריו, ואחורי המלכות כלפי פניו, והוא ביניהם. וז״ש, \u0003עאל בין צדיק, וצדק,\u0004 דהיינו בין יסוד דז״א לבין מלכות. וז״ש, \u0003מאן איהו דיכיל לנזקא לברא דאיהו באמצעו, אבוה מכאן ואמיה מכאן.\u0004 כי יסוד דז״א הוא אביו, והמלכות היא אמו. כי נשמות ישראל נולדות מיסוד ומלכות."],[5,"ת״ח ההוא רקיע וכו׳:","בוא וראה, רקיע ההוא, שהוא ז״א, כשמסבב בגלגול, דהיינו כשמגלגל ג׳ קוין שלו בתלת דוכתי, שאז מתגלה החכמה (כנ״ל בשלח ל״ט ד״ה וג') הוא מנגן בנגון, שהחכמה מתגלית בסוד הניגון, ומקול נהימת המים, הנובעים, כלומר מריבוי שפע החסדים השולטים בז״א, לא ידוע ניגון הזה, כלומר, שאין התחתונים יכולים לקבל ממנו מטעם, שאין החכמה מתגלה במקום ז״א, אלא במקום המלכות, שה״ס חכמה תתאה (כנ״ל ב״א דף רע״ו ד״ה ועוד כמה) כל אלו אגנים שבארבעה צדדים דז״א, דהיינו ד׳ מלכיות שבד' צדדים חו״ג תו״מ דז״א, הנקראות אגנים, בסו״ה שררך \u0003אגן\u0004 הסהר. מלאים ממים הנובעים, דהיינו שמלאים מחסדים שמקבלים מד׳ מעיינות דז״א, והם מכוסים מחכמה, להיותם במקום ז״א. מי שהוא בפנים, דהיינו הזוכה לקבל ממנו. עומד שם בב' צדדים, אחד, \u0003בשמחה,\u0004 שאין עוד שמחה בעולם כאותה השמחה. לקיים עבדו את ה׳ בשמחה. ואחד, \u0003ביראה,\u0004 שאין עוד יראה בעולם כאותה היראה. לקיים עבדו את ה׳ ביראה."],[6,"חד מעיינא דמיא וכו׳:","מעיין מים אחד הנובע מצד מזרח, שהוא ת״ת, קו האמצעי דז״א, הכולל ימין ושמאל, זה הוא שהזכיר יחזקאל הנביא (יחזקאל מ״ז א׳) מעיין הזה, כל בני העולם אין גומרים עליו את השבח. להיותו מיחד ימין ושמאל, ופותח כל האורות שבבינה חסדים וחכמה יחדיו, וממשיכם לתחתונים. במקום שנולד שם, דהיינו לצד מזרח, אין מדת העומק והרום שלו, אלא זרת ולא יותר, כלומר שמקור קו האמצעי בתחילת לידתו, אינו אלא כח המסך דחירק שבו המכונה \u0003זרת.\u0004 (כנ״ל לך י״ג ד״ה ונתבאר) שעמו מכניע קו השמאל ומיחדו עם הימין, שכל המוחין יוצאים מיחוד הזה. כמ״ש שם."],[7,"כד נבעין מיא וכו׳:","כשהמים נובעים ועולים, עולים כל מיני מרגליות שבעולם. כלומר, כשהמים דמזרת, שהוא קו האמצעי דז\"א, משפיעים הארת החכמה אל המלכות, שהמדרגות שלה נקראים מרגליות, הן עולות למעלה, כי הארת החכמה שבהן מאירה רק ממטה למעלה. ואינן נופלות לחוץ, כלומר, שאינן מאירות ממעלה למטה, שאז היו נבחן שנפלו לחוץ לקליפות. והארת חכמה המקובלת בהן היא בג' קוין בזה אחר זה, שהם ג׳ גוונים, לבן אדום ירוק, וכל אחד מהן כלול משלשתם, עתה הן נראות בגוון אחד, ולפי שעה הן נופלות, דהיינו שגוון הזה נעבר מהם לפי שעה, ואז עולות מרגליות אחרות בגוון אחר, וכן בכל מיני גוונים שבעולם, דהיינו כל גווני המלכות הנקראת עולם, ששורשם לבן שחור ואדום, נופלות אלו המרגליות בזה אחר זה שאחד נשקע והשני עולה, ואינן נופלות לחוץ, שאינן משפיעות ממעלה למטה לחיצונים."],[8,"סחרנין דההוא נביעי וכו׳:","מסביב אותו המבוע, מסבבים כפתור ופרח, שה״ס הג״ר דחכמה, המקיפים בבחינת אור מקיף מסביב, ואינם מאירים בפנימיות המעיין. וכל בני העולם אינם יכולים לעמוד על אלו הגוונים שבהם, להיותם ג״ר, כי כולם הם להבות לוהטות ואינם יכולים להסתכל בהם. וע״כ לא ידוע חשיבות מעשיהם. העלים שבפרח, מנצצים בכמה צבעים."],[9,"עובד ציור אומנו וכו׳:","מעשה רוקם שהוא האומנות של רבון העולם, מכסים על שע״ה כרובים שמתחתיהם, אחר שבכות אחרות שבפנים. כי שבכות אלו הן מסביב העזרה מבפנים."],[9,"","פירוש. \u0003מעשה רוקם,\u0004 היא רקמת ג׳ מיני צבעים לבן אדום ירוק שה״ס ג׳ קוין, ותקונם בסוד ד׳ צורות, אריה שור נשר אדם. שע״י מעשה רוקם זה, מתתקנת הארת החכמה בחסדים, ומאירים שניהם בתכלית היופי והשלמות. \u0003כרובים,\u0004 ה״ס אפי זוטרי שהם מוחין דאחורים. והם בסוד \u0003לא שעה.\u0004 ע״ד שנאמר בקין, ואל קין ואל מנחתו \u0003לא שעה\u0004 וכו' \u0003ויפלו פניו\u0004 דהיינו שנפל לאחורים. אבל הארת הפנים ה״ס \u0003שעה.\u0004 וכדי להחזיר אל הכרובים הארת הפנים הם מוכרחים לקבל הכסוי של מעשה רוקם הנ״ל, המכסה על ג״ר שלהם שלא יאירו, ואז חוזרים לבחינת \u0003שע״ה\u0004 ולבחינת מוחין דפנים. וז״ש, \u0003עובד ציור\u0004 וכו' \u0003חפיין על שע״ה כרובין,\u0004 כלומר שמחמת כיסוי שלהם על הכרובים הם \u0003שע״ה\u0004 כרובים, שהיא בחינת פנים. \u0003דתחותייהו,\u0004 שהיו בבחינת תחת שה״ס אחורים. וע״י כיסוי דמעשה רוקם חזרו לפנים, דהיינו לסוד \u0003שע״ה.\u0004 והכרובים יונקים מקו שמאל דבינה, וז״ש, \u0003בתר שבכין אחרנין לגו.\u0004 שעומדים אחר השבכות, שה״ס בינה. כי שבכה נעשית מעירוב חוטים זה בזה, וכן הבינה, כדי שתוכל להשפיע לעולם, העלתה אליה המלכות ונתערבה עמה, כמו חוטי השבכה, לבלי הכר איזהי בינה ואיזהי מלכות. ובינה זו מלובשת בפנימיות העזרה, שה״ס המלכות. וז״ש, \u0003ואינון שבכין סחור דעזרה לגו.\u0004 שמקיפים העזרה בפנימיות העזרה. להיותן בינה, שהיא פנימיות המלכות."]],[[0,"","דָּוִד הַמֶּלֶךְ נִקְרָא זַיִת רַעֲנָן לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁכָּתוּב (תהלים נב) וַאֲנִי כְּזַיִת רַעֲנָן בְּבֵית וְגוֹ'. עֲלֵה זַיִת - זֶה מֶלֶךְ הַמָּשִׁיחַ בֶּן דָּוִד. וְזֶהוּ שֶׁרָמְזָה יוֹנָה זוֹ בִּימֵי נֹחַ, שֶׁכָּתוּב (בראשית ח) וְהִנֵּה עֲלֵה זַיִת טָרָף בְּפִיהָ. אוֹתוֹ עֲלֵה זַיִת טָרַף וְנֶחְטַף לִכְבוֹדוֹ, בַּמֶּה? בְּפִיהָ. שֶׁעוֹמֶדֶת עַל רֹאשׁוֹ, וּמְקַבֵּל כָּבוֹד מִיּוֹנָה זוֹ. וּמַה שֶּׁכָּתוּב טָרָף וְלֹא טָרְפָה, (אלא) כַּזָּכָר הַזֶּה שֶׁעוֹשֶׂה חַיִל וּמְנַצֵּחַ. בִּישִׁיבַת הָרָקִיעַ יוֹנָה זָכָר הוּא. מִתּוֹךְ שֶׁנִּקְרָא יוֹנָה כָּתוּב כִּנְקֵבָה, וְכָתוּב כְּזָכָר בִּזְמַן שֶׁמְּקַבֵּל כָּבוֹד זֶה."],[1,"","מִגְדָּל זֶה כְּשֶׁשָּׁב לִמְקוֹמוֹ, מֵאִיר כְּאוֹר עֵין הַשֶּׁמֶשׁ, שֶׁכָּתוּב (תהלים פט) כִּסְאוֹ כַּשֶּׁמֶשׁ נֶגְדִּי, וְאַף שֶׁכִּסֵּא אַחֵר יִהְיֶה לוֹ בְּנִסִּים וְאוֹתוֹת גְּדוֹלִים. בְּרֹאשׁ מִגְדָּל זֶה יֵשׁ עוֹפוֹת אֵשׁ (דרור) שֶׁמְּצַפְצְפִים, כְּשֶׁעוֹלֶה הַבּקֶר, צִפְצוּף שֶׁל נְעִימוּת, שֶׁאֵין נֹעַם וְנִגּוּן כְּאוֹתָהּ נְעִימוּת."],[2,"","לְמַעְלָה מִכֻּלָּם מִינִים אֲחֵרִים וְיוֹנִים אֲחֵרִים שֶׁפּוֹרְחִים בָּאֲוִיר, עוֹלִים וְיוֹרְדִים, יוֹרְדִים וְעוֹלִים, לֹא שׁוֹכְכִים לְעוֹלָמִים. אוֹתִיּוֹת גְּדוֹלוֹת וְאוֹתִיּוֹת קְטַנּוֹת פּוֹרְחוֹת בֵּינֵיהֶם."],[3,"","אִי חָסִיד קָדוֹשׁ, בְּשָׁעָה שֶׁהָאוֹתִיּוֹת פּוֹרְחוֹת, רוֹאֶה הָאָדָם בְּאוֹתִיּוֹת גְּדוֹלוֹת. כָּתוּב בָּאֲוִיר לְפִי שָׁעָה, בְּרֵאשִׁית בָּרָא אֱלֹהִים אֵת הַשָּׁמַיִם וְאֵת הָאָרֶץ. (והארץ היתה תהו ובהו וגו', מכאן חוזרות האותיות הגדולות כבתחלה) מַכּוֹת אוֹתִיּוֹת קְטַנּוֹת בָּהֶם וּפוֹרְחוֹת, וְנִרְאֶה מֵהֶן כָּתוּב, וַיֹּאמֶר אֱלֹהִים יְהִי אוֹר וְגוֹ', וַיַּרְא אֱלֹהִים אֶת הָאוֹר וְגוֹ'. אַחַר כָּךְ חוֹזְרוֹת אוֹתִיּוֹת קְטַנּוֹת וּמַכּוֹת בְּאוֹתִיּוֹת גְּדוֹלוֹת, וְנִרְאֶה מֵהֶן שֶׁכָּתוּב, וַיֹּאמֶר אֱלֹהִים יְהִי רָקִיעַ וְגוֹ'. וְכֵן כָּל מַעֲשֵׂה בְרֵאשִׁית, פְּלָאוֹת גְּדוֹלוֹת, וְשִׂמְחָה לָעֵינַיִם מַעֲשִׂים שֶׁל אוֹתִיּוֹת אֵלּוּ. אַשְׁרֵי הָעָם שֶׁלְּכָל זֶה מְצַפִּים."],[4,"","אִי חָסִיד קָדוֹשׁ, מִי שֶׁשּׁוֹמֵר בְּרִית, שָׂם אוֹתוֹ אַחֲרָיו, וְהוּא לַהַתְחָלָה. וְאִם תֹּאמַר, מִי שׁוֹמֵר לְאָחוֹר? הֲרֵי שְׁמִירָה גְדוֹלָה וְעֶלְיוֹנָה מֵהַכֹּל שֶׁשּׁוֹמְרוֹ. וּמִי הוּא? צַדִּיק עֶלְיוֹן בְּאַהֲבָה רַבָּה. נִכְנָס בֵּין צַדִּיק וְצֶדֶק, וְנִמְצָא שָׁמוּר מִכָּל הַצְּדָדִים. אַשְׁרֵי מִי שֶׁשּׁוֹמֵר בְּרִית זוֹ. וְעַל כֵּן יִשְׂרָאֵל נִרְאִים כָּל הַזְּכָרִים שֶׁשּׁוֹמְרִים אוֹת בְּרִית זוֹ לִפְנֵי הַמֶּלֶךְ הַקָּדוֹשׁ. מִיהוּ שֶׁיָּכוֹל לְהַזִּיק לְבֵן שֶׁהוּא בְּאֶמְצַע אָבִיו מִכָּאן, וְאִמּוֹ מִכָּאן, וְהוּא בֵּינֵיהֶם? וְזֶה כְּשֶׁהוּא אַחֲרֵי ה'."],[5,"","בֹּא וּרְאֵה, אוֹתוֹ רָקִיעַ כְּשֶׁסּוֹבֵב בְּגִלְגּוּל, מְנַגֵּן בְּנִגּוּן, וּמִקּוֹל נַהֲמַת הַמַּיִם הַנּוֹבְעִים לֹא יָדוּעַ אוֹתוֹ נִגּוּן. כָּל אוֹתָם הָאַגָּנִים שֶׁבְּאַרְבָּעָה צְדָדִים מִתְמַלְּאִים מִנְּבִיעַת הַמַּיִם שֶׁנּוֹבְעִים. מִי שֶּׁהוּא בִּפְנִים, בִּשְׁנֵי צְדָדִים עוֹמֵד שָׁם. אֶחָד בְּשִׂמְחָה, שֶׁאֵין שִׂמְחָה כְּאוֹתָהּ שִׂמְחָה בָּעוֹלָם, לְקַיֵּם (שם ק) עִבְדוּ אֶת ה' בְּשִׂמְחָה. וְאֶחָד בְּיִרְאָה, שֶׁאֵין יִרְאָה כְּאוֹתָהּ יִרְאָה בָּעוֹלָם, לְקַיֵּם (שם ב) עִבְדוּ אֶת ה' בְּיִרְאָה."],[6,"","מַעִִיַן מַיִם אֶחָד שֶׁנּוֹבֵעַ מִצַּד מִזְרָח, זֶהוּ שֶׁאָמַר יְחֶזְקֵאל הַנָּבִיא. מִמַּעְיָן זֶה לֹא יְכוֹלִים לְסַיֵּם שֶׁבַח כָּל בְּנֵי הָעוֹלָם. בְּמָקוֹם שֶׁנּוֹלַד שָׁם לְצַד מִזְרָח, אֵין עֹמֶק וְרוּם שֶׁלּוֹ אֶלָּא זֶרֶת, וְלֹא יוֹתֵר."],[7,"","כְּשֶׁנּוֹבְעִים הַמַּיִם וְעוֹלִים, עוֹלִים כָּל מִינֵי מַרְגָּלִיּוֹת שֶׁבָּעוֹלָם, וְלֹא נוֹפְלִים בַּחוּץ. כָּעֵת נִרְאִים בְּגָוֶן אֶחָד, לְפִי שָׁעָה נוֹפְלִים אֵלֶּה, וְהִנֵּה עוֹלִים אֲחֵרִים בְּגָוֶן אַחֵר בְּכָל מִינֵי גְוָנִים שֶׁבָּעוֹלָם. נוֹפְלוֹת אוֹתָן מַרְגָּלִיּוֹת, וְלֹא נוֹפְלוֹת בַּחוּץ."],[8,"","סְבִיב אוֹתָהּ נְבִיעָה סוֹבְבִים כַּפְתּוֹר וָפֶרַח, וְלֹא יְכוֹלִים כָּל בְּנֵי הָעוֹלָם לַעֲמֹד עַל אוֹתָם גְּוָנִים, כֻּלָּם שַׁלְהָבוֹת לוֹהֲטוֹת, וְלֹא יְכוֹלִים לְהִסְתַּכֵּל בָּהֶם. לֹא יָדוּעַ חֲשִׁיבוּת הַמַּעֲשֶׂה. הֶעָלִים שֶׁלָּהֶם נוֹצְצִים בְּכַמָּה גְוָנִים."],[9,"","מַעָשֵׂה צִיּוּר, אֻמָּנוּת רִבּוֹן הָעוֹלָם, מְכַסִּים עַל שְׁלֹשׁ מֵאוֹת וְשִׁבְעִים וַחֲמִשָּׁה כְּרוּבִים שֶׁתַּחְתֵּיהֶם, אַחַר שְׂבָכִים אֲחֵרִים לִפְנִים. וְאוֹתָם שְׂבָכִים סְבִיב הָעֲזָרָה לִפְנִים."]]],[["וּלְעֵילָּא מִנְּהוֹן, אִינּוּן גּוּפְנִין פְּרִישָׂאן, תְּחוֹת גּוּפְנִין אִינּוּן כְּרוּבִין, כֻּלְּהוּ גַּדְפִּין פְּרִישָׁן, מְשֻׁלָּבָן אִלֵּין בְּאִלֵּין. הָכָא אָמַר רַב מְתִיבְתָּא, דְּכָל מַאן דְּאִסְתַּכַּל בְּאִינּוּן גּוּפְנִין, מְנַהֲרִין אַנְפּוֹי כִּנְהִירוּ דְּשִׁמְשָׁא.","אִינּוּן שְׂבָכִין דְּאִתְּחָמָן סְחוֹר סְחוֹר דַּעֲזָרָה, כֻּלְּהוּ מְרֻקְּמָן, בְּחוּטִין דִּנְהִרִין בִּגְוָונִין סַגִּיאִין, מְלַהֲטָן בְּד' מִינֵי זְהוֹרִין דְּאֶשָּׁא. שַׁלְהוֹבִין סַלְּקִין, וּגְוָונִין מְנַצְּצָן, וּלְזִמְנִין שַׁלְהוֹבִין מִשְׁתַּכְכֵי, וּנְהוֹרִין וּגְוָונִין סַלְּקִין, וּבַטְשֵׁי אִלֵּין בְּאִלֵּין.","שִׁית אֶלֶף אַגָּנִין, לְגַבֵּי אִינּוּן שְׂבָכִין, ד' גַּוְונִין, לְד' סִטְרִין דַּעֲזָרָה, אִלֵּין אִינּוּן רַבְרְבִין, וּנְבִיעוּ דְּמַיִין חַיִּין בְּכָל סִטְרֵי. וְאִינּוּן נַפְלֵי בְּאִינּוּן אַגָּנִין, וּבַלְעֵי בְּאַתְרַיְיהוּ וְאִלֵּין מַיִין לָא יַדְעֵי לְאָן אַזְלִין.","בְּאֶמְצָעוּ דַּעֲזָרָה, יְקוּמוּן כֻּלְּהוּ יִשְׂרָאֵל, וְיִתְחֲזוּן קַמֵּי מַלְכָּא קַדִּישָׁא. בִּסְטָר דָּרוֹם בַּעֲזָרָה דָּא, אִתְיְילִיד חַד מַעְיָינָא דְּמַיָּא, וְאִתְרְמֵי (ס\"א ואתדמי) (ס\"א ואתרבי) דְּקָא יִשְׁטְפוּן מַיָּא כָּל עָלְמָא. מַאן דְּיֵיעוּל בְּהוּ, יְהוֹן עַד בִּרְכַּיִם, יֵיעוּל בְּהוּ גִּיבָּר רַב יֵיעוּל בְּהוּ עַד בִּרְכַּיִם, אִי תִּינוֹק בַּר יוֹמָא עַד בִּרְכַּיִם. מַאן דְּשָׁתֵי מִנַּיְיהוּ יִתְחַכָּם, וְיִתְפְּקַח בְּחָכְמְתָא.","מַעְיָינָא דָּא נָפִיק מִגּוֹ מַרְגְּלָא חֲדָא זְעֵירָא, בְּכוֹתָלָא דְּדָרוֹם. אִינּוּן מַיִין בַּלְעֵי גּוֹ אַתְרָא (ס\"א גו אתר דא), וּמִתַּמָּן יִפְּקוּן לְבַר מִמַּקְדְשָׁא, עַד דְּיַעֲלוּ לְנַחַל שִׁטִּים, יִשְׁטְפוּן הַהוּא זִמָה, דְּאוֹלְדִין מַיָּא דְּשִׁטִּים. וְעַל דָּא מַיִין אִלֵּין בַּעֲזָרָה, בְּגִין אִינּוּן דְּאִתְחָזוּן תַּמָּן דְּכוּרִין. הֲווֹ שָׁתָאן מִן מַיָּא, לָא חַיְישֵׁי בְּנוּקְבֵי, בְּמֵיתַיְהוֹן לְאִתְחֲזָאָה קַמֵּי מַלְכָּא קַדִּישָׁא. תּוּ, דְּהָא יִתְפַּקְחוּן לְמִנְדַּע מִלִּין סְתִימִין דְּמַלְכָּא עִלָּאָה, גּוֹ מַקְדְּשָׁא דָּא כָּל הִרְהוּרִין יִשְׁתַּכְּחוּן, בַּר הִרְהוּרָא דְּחֶדְוָה דְּמַלְכָּא קַדִּישָׁא.","עַנְפָּא חַד נָפִיק, גּוֹ אֶמְצָעוּ דְּהַהוּא מַעְיָינָא. אָמַר רַב מְתִיבְתָּא, כַּד קָרִיבְנָא לְהַהוּא עַנְפָּא גּוֹ מַעְיָינָא, אִסְתַּלָּק עַנְפָּא לְעֵילָּא לְעֵילָּא, כָּל מַה דְּקָרִיבְנָא, הָכִי אִסְתַּלָּק, יְסוֹדָא וְשָׁרְשָׁא דְּהַהוּא עַנְפָּא לָאו אִיהוּ אֶלָּא בְּמַיָּא. הַהוּא עַנְפָּא חָפֵי עָלְמִין. כָּל גַּוְונִין דְּעָלְמָא בְּאִינּוּן טַרְפִּין דִּילֵיהּ. אִיבָּא דִּילֵיהּ, לָא יְדִיעַ מַהוּ. וְלָא יַכְלִין לְמִנְדַּע. וְאָמַר, דְּקָא שָׁאִיל לְמָשִׁיחַ עַל הַהוּא אִיבָּא, וְאָמַר, אִיבָּא דָּא גָּנִיז, (זכריה ח׳:ד׳) לְאִישׁ מִשְׁעַנְתּוֹ בְּיָדוֹ מֵרוֹב יָמִים. מַאן דְּזָכֵי לְמִנְדַּע דָּא, לִינְדַע.","רָקִיעַ חַד אִית עַל הַהוּא עַנְפָּא, פָּרִישׂ לְעֵילָּא. מֵהַהוּא רְקִיעָ, אָזִיל טַלָּא עַל גַּבֵּי מַעְיָינָא דָּא, וְלָא יַתִּיר. כַּד אִסְתָּכַּל בַּר נָשׁ לְהַהוּא רָקִיעַ מֵרָחִיק, דָּמֵי תִּכְלָא. קָרִיב יַתִּיר, דָּמֵי סוּמָקָא. קָרִיב יַתִּיר, דָּמֵי יָרוֹק קָרוֹב יַתִּיר, דָּמֵי חִוָּור, דְּלֵית חִוָּור בְּעָלְמָא כְּגִינֵיהּ. טַלָּא דְּקָא אָזִיל מִנֵּיהּ, אִשְׁתְּאִיב בְּהַהוּא עַנְפָּא, וְעָבִיד אִיבָּא דָּא, וְאִתְרַבֵּי. הַהוּא רְקִיעָא, אִיהוּ אָזִיל בְּגִלְגּוּלָא יַתִּיר, מִמָּה דְּעַיְינִין יַכְלִין לְאִסְתַּכְּלָא.","כָּל אִינּוּן נְטוּרֵי קַיָּימָא קַדִּישָׁא, (ס\"א בעון) דְּבָּעוּן לְאִתְחֲזָאָה קַמֵּי מַלְכָּא, דְּהָא לָא אִתְחָזוּן, אֶלָּא בְּגִין לְאַחֲזָאָה דְּאִינּוּן בְּנֵי גְּזִירוּ קַדִּישָׁא. וְעַל דָּא, (שמות כ״ג:י״ז) יֵרָאֶה כָּל זְכוּרְךָ, אִינּוּן בְּנֵי קַיָּימָא קַדִּישָׁא. דָּיִיק רַב מְתִיבְתָּא, זְכוּרְךָ, וְלָא זְכָרְךָ. דְּהָא זָכָר כְּתִיב, וְלָא זָכוּר, מַאי זְכוּרְךָ. אֶלָּא כָּל אִינּוּן דְּנַטְרִין קַיָּימָא קַדִּישָׁא, וְלָא חָבָאן בֵּיהּ, אִינּוּן הֲווּ בְּנֵי מַלְכָּא, דִּבְכֹּל יוֹמָא מִשְׁתָּבַח בְּהוּ וְדָכִיר לוֹן תָּדִיר. וְעַל דָּא זְכוּרְךָ, הֲהוּא דְּאִית בֵּיהּ קַיָּימָא קַדִּישָׁא, דְּדָכִיר לוֹן מַלְכָּא בְּכָל יוֹמָא, דְּלֵית שְׁבָחָא קַמֵּי מַלְכָּא עִלָּאָה, (אלא) כְּמַאן דְּנָטִיר קַיְּימָא דָּא.","וְעַל דָּא בָּעֵי דְּיִתְחֲזוּן תְּלַת זִמְנִין בְּשַׁתָּא קַמֵּיהּ. תְּלַת זִמְנִין אֲמַאי. אֶלָּא בְּגִין אֲבָהָן קַדְמָאֵי, דְּקַבִּילוּ לְהַאי בְּרִית, קַדְמָאָה לְכָל פִּקוּדִין דְּאוֹרַיְיתָא, וּבְגִין כָּךְ תְּלַת זִמְנִין אִינּוּן בְּשַׁתָּא. אַבְרָהָם קַבִּיל בְּרִית. יִצְחָק קַבִּיל בְּרִית. יַעֲקֹב הֲוָה שְׁלִים מְכֻּלְּהוּ, וְעַל דָּא כְּתִיב בֵּיהּ, (בראשית כ״ה:כ״ז) וְיַעֲקֹב אִישׁ תָּם, שְׁלִים מִכֹּלָּא.","אַבְרָהָם תָּמִים אִקְרֵי, וְלָא הֲוָה כָּל כַּךְ שְׁלִים, אֲבָל תָּם: שְׁלִים מִכֹּלָּא. מַה כְּתִיב בְּנֹחַ, (בראשית ו׳:ט׳) אִישׁ צַדִּיק תָּמִים הָיָה בְּדוֹרוֹתָיו. הֲוָה רְשִׁים בִּרְשִׁימוּ קַדִּישָׁא בֵּינַיְיהוּ. וְאָמַר רַב מְתִיבְתָּא, בְּכָל אֲתָר דִּכְתִּיב תָּמִים, דְּרָשִׁים בִּרְשִׁימוּ קַדִּישָׁא, בְּאָת קַיָּימָא דִּבְרִית, וּבְגִין דְּנָטַר בְּרִית, אִקְרֵי תָּמִים בְּדוֹרוֹתָיו. מַה דְּלָא הֲווֹ כֻּלְּהוּ הָכִי, דְּאִינּוּן מְחַבְּלָן אָרְחַיְיהוּ."],[[0,"ולעילא מנהון וכו׳:","ולמעלה מן הכרובים, פרושים אלו הגפנים, שתחת הגפנים הם הכרובים, כולם פרושים כנפיהם. משולבות אלו באלו. כאן אמר רב מתיבתא, כל מי שמסתכל בגפנים אלו מאירים פניו כאור השמש."],[0,"","פירוש. הגפנים הם בחינת מוחין דפנים, שהאחורים שלהם נקראים כרובים. וז״ש, \u0003ולעילא מנהון איבון גופנין פרישאן,\u0004 שהם מוחין דפנים \u0003תחות גופנין אינון כרובין,\u0004 תחת, פירושו אחורים, ואומר שהאחורים של הגפנים, הם הכרובים. \u0003כלהו גדפין פרישן,\u0004 שכנפיהם מכסים הארת הג״ר, \u0003משלבן אלין באלין,\u0004 שהכרובים והגפנים משולבים זה בזה. וגם הכרובים חוזרים לבחינת פנים יחד בחבור עם הגפנים. \u0003דכל מאן דאסתכל באינון גופנין מנהרין אנפוי,\u0004 להיותם מוחין דפנים, \u0003כנהירו דשמשא,\u0004 כאור הז״א הנקרא שמש."],[1,"אינון שבכין דאתחמן וכו׳:","השבכות שהם אורות בינה המתלבשים במלכות המתפשטות סביב סביב העזרה מבפנים, כולם נרקמים בחוטים המאירים בגוונים רבים, שחוטי בינה וחוטי מלכות נרקמים ומסובכים זה בזה ומאירים יחד, וחוטים ה״ס הארות החסדים. והם לוהטים בד׳ מיני זוהר של אש. שה״ס ההארות דקו שמאל, שה״ס הארות החכמה, המאירות עם דינים הנקראים אש. הלהבות, שה״ס הארות החכמה, עולות שמאירים ממטה למעלה. וגוונים מתנוצצים. ולפעמים דהיינו בזמן הקטנות הלהבות משתככות, ואורות וגוונים עולים, דהיינו שמאירים רק ממטה למעלה. שבזמן הקטנות אינם מאירים אלא ממטה למעלה. ואז בוטשים אלו באלו, שהארות המלכות בוטשות בהארות הבינה וממעטות אותן."],[2,"שית אלף אגנין וכו׳:","ששה אלף אגנות יש אצל אלו שבכות, דהיינו מלכיות המקבלות ו״ק דחכמה מן השבכות, שהם ששה כנגד חג״ת נה״י, והם אלף ע״ש החכמה הנקראת אלף. ד׳ גוונים הם לד׳ צדדים של העזרה, דהיינו חו״ג תו\"מ, ואלו הם גדולות, דהיינו שהם בחינת ו״ק דגדלות, ומבוע של מים חיים בכל צד, דהיינו חסדים וחכמה יחד, מים, על שם החסדים. חיים, על שם החכמה. והם נופלים באלו האגנות ונבלעים במקומם, כלומר שאינם מושפעים ממעלה למטה, דהיינו לחוץ ממקומם. ומים אלו, אינם יודעים אנה הם הולכים. שלהיותם עם חכמה, שאינה מושפעת ממעלה למטה, אין בהם ידיעה איפה הם הולכים."],[3,"באמצעו דעזרה יקומון וכו׳:","באמצע העזרה, דהיינו בקו האמצעי של המלכות, יקומו כל ישראל ויראו לפני המלך הקדוש. שממנה מקבלים כל ישראל חכמה הנקראת ראיה. בצד דרום, של העזרה, שהוא קו ימין של המלכות, וחסד, נולד מעיין מים אחד, ונדמה שהמים ישטפו כל העולם. מי שיכנס בהם יכנס עד הברכים, יכנס בהם גבור גדול יכנס עד הברכים, ואם תנוק בן יומו יכנס בהם, יכנס בהם עד הברכים. מי ששותה מהם יחכם, ויתפקח בחכמה."],[3,"","נודע ששורש ג׳ קוין הם בסוד ג׳ נקודות חולם שורק חירק המבוארים לעיל (ב״א דף ט״ו ד\"ה ההיא) ומעיין מים ה״ס אור החסד שמקורם בקו ימין, שה\"ס דרום דעזרה, ולידתו של אור החסד הזה, הוא ע״י עלית המלכות לבינה, שנתמעטה מג״ר לו״ק, שה״ס נקודת החולם כמ״ש שם. וז״ש, \u0003בסטר דרום בעזרה דא,\u0004 דהיינו בקו ימין, שה״ס נקודת החולם, \u0003אתייליד חד מעיינא דמיא,\u0004 שע״י עלית המלכות לבינה נולד מעיין המים שהוא שורש החסד, ואז נדמה שהמלכות לא תצא עוד מן הבינה, והבינה לא תשוב לג״ר, כדי שלא יתבטלו החסדים, וז״ש \u0003ואתדמי דקא ישטפון מיא כל עלמא,\u0004 שנדמה אשר המים שה״ס החסדים שנולדו ע״י עלית המלכות, ישטפו כל העולם, כלומר שיחרבו העולם מבנין הג״ר, ולא יחזרו עוד הג\"ר אל העולם. שזה נבחן לחורבן העולם. אמנם לא היה כך אלא ע״י קו שמאל וקו האמצעי חזרו הג׳״ר לבינה כנודע. אמנם בשעתם ביציאת קו ימין, מי שנכנס בהם, אבד הג״ר שלו, וז״ש, \u0003מאן דייעול בהו יהון עד ברבים,\u0004 כלומר שהמים יעלימו את נה״י שלו, הנקראים ברכים, וכשנעלמו נה\"י דכלים נעלמים ג״ר דאורות. והעלמת ג״ר אלו נוהגת הן תיכף בעת לידת קו ימין ע״י עלית המלכות לבינה, שאז מכונה תינוק בן יומו. והן אפילו אח״כ כשיוצאת נקודת השורק, שאז יוצאת המלכות מן הבינה בסוד קו השמאל, והבינה חוזרת לג״ר, הנה גם אז אין המלכות יוצאת מבינה בקו הימין, וע״כ נעשה מחלוקת בין ימין לשמאל, (כנ״ל אד״ר נשא אות רי״ד בהסולם) והתגברות הימין על השמאל, נבחן, שקו השמאל, המכונה גבור וגדול, נכנס תוך המים שבימין, ואובד¬ נה״י דכלים שלו וג\"ר דאורות. וז״ש, \u0003ייעול בהו גיבר רב ייעול בהו עד ברכים,\u0004 דהיינו אם קו השמאל נכנס בו מתוך שהימין נתגבר עליו, יהיו נעלמים הברכים שלו, שהם נה״י. \u0003אי תינוק בר יומא, עד ברכים,\u0004 דהיינו תיכף בעת לידת קו הימין, כל מי שמקבלם יהיו נעלמים הברכים שלו, והג״ר. כנ״ל. ונודע שכל המוחין המתגלים לתחתונים הוא בסבת עלית המלכות לבינה (כנ\"ל ב״א דף ז׳ ד״ה וכבר) וז״ש, \u0003מאן דשתי מנייהו יתחכם ויתפקח, בחכמתא\u0004 כי נעשה מוכשר על ידיהם לקבל כל המוחין העליונים."],[4,"מעיינא דא נפיק וכו׳:","מעיין הזה יוצא מתוך מרגלית אחת קטנה בכותל דרום. מים אלו נבלעים במקומם, ומשם יצאו לחוץ מן המקדש עד שעולים לנחל שטים וישטפו זמה ההיא שהולידו המים דנחל שטים. וע״כ. מים אלו בעזרה, משום שאלו הזכרים הבאים להראות שם, כשהיו שותים מן המים, לא חששו בנקבות בבואם להראות לפני המלך הקדוש. ועוד, שעל ידי המים, יתפקחו לדעת דברים סתומים של המלך העליון. במקדש הזה כל ההרהורים יהיו נשכחים, חוץ מהרהור שמחת המלך הקדוש."],[4,"","פירוש. כי נתבאר בסמוך, שאע״פ שבקו שמאל יוצאת המלכות מבינה והבינה חזרה לאור הג״ר, שה״ס שה \u0003י׳\u0004 יוצאת מאויר הבינה, והבינה חזרה לאור. עכ״ז הקו ימין אינו מוציא ה \u0003י׳\u0004 מאויר שלו, כי חפץ חסד הוא, ולא באור החכמה. וז״ש, \u0003מעיינא דא נפיק מגו מרגלא חדא זעירא,\u0004 שהיא המלכות דמלכות, הנקראת מרגלא זעירא, שעלתה לבינה דמלכות לתקון קו ימין שלה, בסוד ה \u0003י׳\u0004 שנכנסה לאויר, כנ״ל. \u0003אינון מיין בלעי גו אתרא,\u0004 היינו בעת שהימין מתיחד עם השמאל והחסד נכלל בחכמה, והחסדים הנכללים מהכמה מושפעים למטה, הנה כח ה \u0003י'\u0004 שבאויר, שהוא גורם למניעת החכמה אינה נמשכת עם החסדים אלא \u0003בלעי גו אתרא,\u0004 והוא כדי שהחסדים יתכללו עם אור החכמה לתחתונים. אמנם אם ישראל חוטאים ומתדבקים בשמאל, כמו שהיה בנחל שטים, שהוא שמאל, שמשכו אותו בחטאם בבנות מואב, אז נתעורר כח ה \u0003י'\u0004 שבאויר הימין, המעורב במים שבדרום, ויוצא לחוץ ממקומו למעט השמאל, ולמחוק הזוהמא. וז״ש, \u0003ומתמן יפקון לבר ממקדשא,\u0004 דהיינו רק בשעת חטא, \u0003עד דיעלו לנחל שטים.\u0004 שהוא שליטת השמאל בלי ימין, שנתדבקו לבנות מואב ולבעל פעור, \u0003ישטפון ההוא זמה דאולדין מיא דשטים\u0004 דהיינו ע״י כח ה \u0003י׳\u0004 שבאויר שלהם הם ממעטים קו השמאל, ואז נמחק הזוהמא, כי נמחקים כל הנמשכים מצדו."],[4,"","ונצטוו ישראל שלש פעמים בשנה יראה כל זכורך וגו׳. דהיינו ע״י ג׳ קוין הנקרא שלש פעמים, ימשיכו החכמה הנקרא ראיה, בבח \u0003י׳\u0004 הזכרים, שהם חסדים, כלומר שהחכמה לא תהיה נמשכת מקו שמאל ששם סוד הנקבות, כי החכמה שבשמאל אסור למשוך ממעלה למטה, אלא החסדים, שה״ס הזכרים, מותר למשוך למטה אע״פ שהראיה שה״ס החכמה כלולה בהם. וז״ס, \u0003יראה כל זכורך,\u0004 שהראיה תהיה בזכרים. וכדי להיות בטוחים, שלא ימשיכו משהו מצד השמאל, שהם נקבות, היו שותים ממעיין הזה שבדרום, שבו ה \u0003י׳\u0004 נמצאת באויר, שכחה דוחה החכמה, כנ״ל. וז״ש, \u0003וע״ד מיין אלין בעזרה,\u0004 דהיינו עם ה \u0003י׳\u0004 הנמצא באויר שלהם, \u0003בגין אינון דאתחזון תמן דכורין,\u0004 דהיינו הזכרים שהם חסדים, \u0003הוו שתאן מן מיא,\u0004 שהיו שותים ומקבלים כח ה \u0003י׳\u0004 הנמצא באויר שלהם, ואז \u0003לא חיישי בנוקבי, במיתיהון לאתחזאה קמי מלכא קדישא,\u0004 דהיינו בבואם להראות, שפירושו להמשיך החסדים שבהם כלולה החכמה, לא יתעוררו בנקבות, דהיינו שלא יתעוררו להמשיך מן הצד שלהן שהוא קו שמאל. כי החכמה שבשמאל אסור להמשיך ממעלה למטה. \u0003תו, דהא יתפקחון למנדע מלין סתימין דמלכא עלאה,\u0004 כי מתקון הזה של ה \u0003י׳\u0004 שבאויר, נמשכים ויוצאים כל המוחין דז״א."],[5,"ענפא חד נפיק וכו׳:","ענף אחד יוצא באמצע אותו המעיין. אמר רב מתיבתא כשקרבתי לענף ההוא שבתוך המעיין, נסתלק הענף למעלה למעלה, כל מה שקרבתי כך נסתלק יותר. היסוד והשורש של ענף הזה, אינו אלא במים. ענף הזה מכסה עולמות. כל צבעים שבעולם נראים בעלים שלו. הפרי שלו אינו ידוע מה הוא, ואינם יכולים לדעת. ואמר רב מתיבתא, ששאל את המשיח על אותו הפרי, ואמר, פרי הזה גנוז, לאיש משענתו בידו מרוב ימים. מי שזכה לדעת את זה ידע."],[5,"","פירוש. אע״פ שאמרנו שמעיין הזה הוא קו ימין, עכ״ז הוא כולל ג׳ קוין, כי כל קו מג׳ קוין כלול משלשתם. ואין לשאול, א״כ, כל קו מג׳ הקוין, שוים זה לזה, שהרי בכולם יש ימין ושמאל, וקו האמצעי הכוללם יחד. וזה שמפרש כאן, שיש הפרש גדול בין קו האמצעי הכולל, ובין קו האמצעי הכלול בימין. וז״ש, \u0003ענפא חד נפיק גו אמצעו דההוא מעיינא,\u0004 דהיינו שהוא בחינת קו האמצעי, הכלול במעיין הזה שהוא ימין. \u0003אמר רב מתיבתא כד קריבנא\u0004 וכו׳ \u0003אסתלק ענפא לעילא לעילא, כל מה דקריבנא הכי אסתלק,\u0004 דהיינו שלא כדרך קו האמצעי הכולל, שמושגים בו הימין והשמאל, זה ממעלה למטה וזה ממטה למעלה (כנ״ל ב״א דף ס׳ ד״ה מחלוקת) אבל קו האמצעי הכלול בימין, כל מה שמתקרבים אליו כך הוא מסתלק למעלה. והוא ע״ד שנתבאר בדבור שלאחר זה אצל הרקיע שהוא הבחינה שכנגד ענף הזה. ע״ש. וכל זה הוא מטעם, כי \u0003יסודא ושרשא דההוא ענפא לאו איהו אלא במיא,\u0004 משום שבכל קו שולט היסוד שלו, אם היסוד והשורש הוא חסד, כל ג׳ הקוין הם בשליטת החסד, ואם היסוד והשורש הוא גבורה, כל ג׳ הקוין הם תחת שליטת הגבורה. וכיון שיסוד ושורש של ענף הזה הוא במים, שהוא חסד, ע״כ אפילו קו האמצעי בו הוא ג״כ כבחינת חסד, ואין בחינת השמאל ניכר בו. וז\"ש, \u0003ההוא ענפא חפי עלמין,\u0004 דהיינו שמכסה העולמות שלא יקבלו מהארת החכמה. ועם כל זה, \u0003כל גוונין דעלמא באינון טרפין דיליה,\u0004 שבבחינת העלים שלו, שאינם למאכל, רק הם משמשים לענף עצמו, יש שם כל ג׳ גוונים לבן אדום ירוק. דהיינו שלפי עצמו יש שם גם הארת חכמה. אבל, \u0003איבא דיליה,\u0004 דהיינו הפרי שהוא למאכל, דהיינו להמשיך ממנו למטה לתחתונים. \u0003לא ידיע מהו, ולא יכלין למנדע,\u0004 דהיינו שאין בו שום השגה, להיותו חסדים בלי חכמה כלל. וז״ש, \u0003ואמר דקא שאיל למשיח\u0004 וכו׳ \u0003ואמר איבא דא גניז לאיש משענתו בידו מרוב ימים.\u0004 דהיינו לעתיד לבא אחר שיזכו לכל המדרגות יקבלו בחינת חסדים מעתיקא קדישא שהם חשובים הרבה יותר מחכמה ויהיו נמשכים למטה לתחתונים. ואלו החסדים החשובים הם פרי של ענף הזה. כלומר, שעל ידו מתקבלים."],[6,"רקיע חד אית וכו׳:","רקיע אחד יש על אותו הענף האמצעי מבחינת הימין, הפרוש עליו מלמעלה. מרקיע ההוא הולך טל על מעיין הזה ולא יותר. כשאדם מסתכל לרקיע ההוא מרחוק, הוא דומה לתכלת. קרב יותר הוא דומה לאדום. קרב יותר הוא דומה לירוק. קרב יותר הוא דומה ללבן, שאין לבן כמוהו בעולם. הטל ההולך ממנו נשאב בענף ההוא, ועושה פרי הזו וגדל. רקיע ההוא הולך בגלגול יותר ממה שהעינים תוכלנה להסתכל בו."],[6,"","פירוש. ז״א נקרא רקיע, דהיינו שמים. והבחינה שכנגד הענף שבאמצע המים, אשר בז״א, הוא סוד, \u0003רקיע חד אית על ההוא ענפא פריש לעילא,\u0004 שגם הרקיע הוא בחי׳ קו האמצעי של צד ימין. וז״ש, \u0003מההוא רקיע אזיל טלא ע״ג מעיינא דא ולא יתיר,\u0004 להיותו הבחינה שכנגד הענף שבאמצע המעיין, ע״כ הוא משפיע רק לו לבדו ולא לאחר. והזוכה לקבל מרקיע הזה הוא מקבל והולך ממטה למעלה בד׳ מדרגות שלו. וז״ש, \u0003כד אסתכל בר נש לההוא רקיע מרחיק,\u0004 דהיינו בעת שהוא רחוק ורוצה לקבל מדרגה א׳, \u0003דמי תכלא,\u0004 שהוא צבע המלכות. \u0003קריב יתיר דמי סומקא,\u0004 הזוכה יותר רואה בו בחינת השמאל שהוא אדום. \u0003קריב יתיר דמי יריק,\u0004 הזוכה יותר רואה צבע ירוק, שה״ס קו האמצעי ת״ת. הכולל חסד וגבורה. \u0003קריב יתיר דמי חוור דלית חוור בעלמא כגיניה.\u0004 שה״ס חסד. וחסד הזה משפיע אל הענף ועושה פירות, וז״ש, \u0003טלא דקא אזיל מניה אשתאיב בההוא ענפא ועביד איבא דא ואתרבי,\u0004 שמן החסד הזה גדל פרי הנ״ל על הענף הזה שבאמצע המעיין. ואע״פ שיש ברקיע כל אלו ד׳ הצבעים הנ״ל, עכ״ז אין בחינתם נמשכת למטה כמו בקו האמצעי הכולל. על דרך שבארנו לעיל אצל הענף האמצעי שבמים, ע״ש. וז״ש, \u0003ההוא רקיעא איהו אזיל בגלגולא יתיר ממה דעיינין יכלין לאסתכלא.\u0004 כלומר שהצבעים מתגלגלים כל כך במהרה עד שהעינים אינן שולטות בהם. וכל ד׳ צבעים שאמרנו לעיל שהוא רואה, היינו בשליטת החסד ע״ד שבארנו בהענף."],[7,"כל אינון נטורי וכו׳:","כל אלו שומרי ברית קדש צריכים להראות לפני מלך הקדוש, כי לא נראים אלא להראות שהם בני ברית קדש, וע״כ יראה כל זכורך, שהם בני ברית קדש. ומדייק רב מתיבתא, זכורך ולא כתוב זכרך עם ז׳ חרוקה, כי זכר פירוש הכתוב דהיינו זכרים, ולא זכור, שאין הפירוש זכרון שלך. מהו זכורך, למה דוקא זכרים, אלא כל אלו השומרים ברית קדש ואינם חוטאים בו אלו הם בני המלך, שבכל יום משתבח בהם, וזוכר אותם תמיד. ועל כן אוה״כ. זכורך שפירושו, אותו שיש בו ברית קדש שזוכר אותם המלך בכל יום, שאין שבח לפני מלך העליון אלא כמי ששומר ברית הזה."],[8,"וע\"ד בעי דיתחזון וכו׳:","ועל כן צריכים שיראו לפניו ג׳ פעמים בשנה. ג׳ פעמים למה. אלא בשביל האבות הראשונים שקבלו ברית הזה, בראשונה לכל מצות התורה. ומשום זה הם ג׳ פעמים בשנה. אברהם קבל ברית. יצחק קבל ברית. יעקב היה שלם מכולם. כי אברהם ויצחק הם כנגד ימין ושמאל, ויעקב הוא כנגד קו האמצעי הכולל את שניהם. וע״כ כתוב בו, ויעקב איש תם, שפירושו שלם מכל."],[9,"אברהם תמים אקרי וכו׳:","אברהם נקרא \u0003תמים\u0004, ולא היה כל כך שלם, אבל \u0003תם,\u0004 שלם מכל (כנ״ל אות קי״ז) מה כתוב בנח, איש צדיק תמים היה בדורותיו, שהיה רשום ברושם קדוש ביניהם. ואמר רב מתיבתא בכל מקום שכתוב \u0003תמים,\u0004 פירושו, שרשום ברושם קדוש באות ברית מילה. ומשום ששמר ברית נקרא תמים בדורותיו, מה שכולם לא היו כך, שלא היו שומרים ברית, שהם היו משחיתים דרכם."]],[[0,"","וּלְמַעְלָה מֵהֶם אוֹתָן גְּפָנִים פְּרוּשׂוֹת, תַּחַת הַגְּפָנִים אוֹתָם כְּרוּבִים, כֻּלָּם בִּכְנָפַיִם פְּרוּשׂוֹת מְשֻׁלָּבוֹת אֵלּוּ בְאֵלּוּ. כָּאן אָמַר רֹאשׁ הַיְשִׁיבָה, שֶׁכָּל מִי שֶׁמִּשְׁתַּדֵּל בְּאוֹתָן גְּפָנִים, מְאִירִים פָּנָיו כְּאוֹר הַשֶּׁמֶשׁ."],[1,"","אוֹתָם שְׂבָכִים שֶׁתּוֹחֲמִים סָבִיב סָבִיב לָעֲזָרָה, כֻּלָּם מְרֻקָּמִים בְּחוּטִים שֶׁמְּאִירִים בִּגְוָנִים גְּדוֹלִים, לוֹהֲטִים בְּאַרְבָּעָה מִינֵי זֹּהַר שֶׁל אֵשׁ. שַׁלְהָבוֹת עוֹלוֹת, וּגְוָנִים נוֹצְצִים, וְלִפְעָמִים הַשַּׁלְהָבוֹת שׁוֹכְכוֹת, וְאוֹרוֹת וּגְוָנִים עוֹלִים וּמַכִּים אֵלֶּה בְאֵלֶּה."],[2,"","שֵׁשֶׁת אֲלָפִים אַגָּנִים לְגַבֵּי אוֹתָם שְׂבָכִים, אַרְבָּעָה גְוָנִים לְאַרְבָּעָה צְדָדִים שֶׁל הָעֲזָרָה. אֵלֶּה הֵם גְּדוֹלִים, וּנְבִיעַת הַמַּיִם הַחַיִּים בְּכָל הַצְּדָדִים. וְהֵם נוֹפְלִים בְּאוֹתָם אַגָּנִים, וְנִבְלָעִים בִּמְקוֹמָם, וּמַיִם אֵלֶּה לֹא יוֹדְעִים לְאָן הוֹלְכִים."],[3,"","בְּאֶמְצַע הָעֲזָרָה יָקוּמוּ כָּל יִשְׂרָאֵל וְיֵרָאוּ לִפְנֵי הַמֶּלֶךְ הַקָּדוֹשׁ. בְּצַד דָּרוֹם בַּעֲזָרָה זוֹ נוֹלַד מַעְיָן מַיִם אֶחָד, וְנִדְמָה (והתרבה) שֶׁיִּשְׁטְפוּ הַמַּיִם אֶת כָּל הָעוֹלָם. מִי שֶׁיִּכָּנֵס בָּהֶם, יִהְיוּ עַד הַבִּרְכַּיִם. יִכָּנֵס בָּהֶם גִּבּוֹר גָּדוֹל, יִכָּנֵס בָּהֶם עַד הַבִּרְכַּיִם. אִם תִּינוֹק בֶּן יוֹם, עַד הַבִּרְכַּיִם. מִי שֶׁשּׁוֹתֶה מֵהֶם יִתִחַכֵּם, וְיִתְפַּקַּח בְּחָכְמָה."],[4,"","מַעְיָן זֶה יוֹצֵא מִתּוֹךְ מַרְגָּלִית קְטַנָּה אַחַת בְּכֹתֶל דָּרוֹם. אוֹתָם הַמַּיִם נִבְלָעִים תּוֹךְ הַמָּקוֹם (תוך המקום הזה), וּמִשָּׁם יֵצְאוּ הַחוּצָה מֵהַמִּקְדָּשׁ, שֶׁעַד שֶׁיַּעֲלוּ לְנַחַל שִׁטִּים, יִשְׁטְפוּ אוֹתָהּ זִמָּה שֶׁיָּלְדוּ הַמַּיִם שֶׁבַּשִּׁטִּים. וְעַל כָּךְ מַיִם אֵלֶּה בָּעֲזָרָה, בִּגְלַל אֵלּוּ שֶׁנִּרְאוּ שָׁם זְכָרִים, הָיוּ שׁוֹתִים מֵהַמַּיִם, לֹא נִתְעוֹרְרוּ לַנְּקֵבוֹת בְּבוֹאָם לְהִתְרָאוֹת לִפְנֵי הַמֶּלֶךְ הַקָּדוֹשׁ. וְעוֹד, שֶׁהֲרֵי יִתְפַּקְּחוּ לָדַעַת דְּבָרִים סְתוּמִים שֶׁל הַמֶּלֶךְ הָעֶלְיוֹן, תּוֹךְ הַמִּקְדָּשׁ הַזֶּה כָּל הַהִרְהוּרִים נִשְׁכְּחוּ, פְּרָט לַהִרְהוּר שֶׁל חֶדְוַת הַמֶּלֶךְ הַקָּדוֹשׁ."],[5,"","עָנָף אֶחָד יוֹצֵא בְתוֹךְ אֶמְצַע אוֹתוֹ מַעְיָן. אָמַר רֹאשׁ הַיְשִׁיבָה, כְּשֶׁהִתְקָרַבְתִּי לְאוֹתוֹ עָנָף שֶׁבְּתוֹךְ הַמַּעְיָן, עָלָה עָנָף לְמַעְלָה לְמַעְלָה. כָּל מַה שֶּׁהִתְקָרַבְתִּי - כָּךְ עָלָה. יְסוֹד וְשֹׁרֶשׁ אוֹתוֹ עָנָף אֵינוֹ רַק בַּמַּיִם. אוֹתוֹ עָנָף מְכַסֶּה עוֹלָמוֹת. כָּל גּוֹנֵי הָעוֹלָם בְּאוֹתָם הָעֲנָפִים שֶׁלּוֹ. פִּרְיוֹ לֹא יָדוּעַ מַהוּ, וְלֹא יְכוֹלִים לָדַעַת. וְאָמַר שֶׁשָּׁאַל אֶת הַמָּשִׁיחַ עַל אוֹתוֹ פְּרִי, וְאָמַר, פְּרִי זֶה גָּנוּז (זכריה ח) לְאִישׁ מִשְׁעַנְתּוֹ בְּיָדוֹ מֵרֹב יָמִים. מִי שֶׁזּוֹכֶה לָדַעַת זֶה - שֶׁיֵּדַע."],[6,"","רָקִיעַ אֶחָד יֵשׁ עַל אוֹתוֹ עָנָף פָּרוּשׂ לְמַעְלָה. מֵאוֹתוֹ רָקִיעַ הוֹלֵךְ טַל עַל גַּבֵּי אוֹתוֹ מַעְיָן, וְלֹא יוֹתֵר. כְּשֶׁמִּסְתַּכֵּל אָדָם עַל אוֹתוֹ רָקִיעַ מֵרָחוֹק, דּוֹמֶה תְכֵלֶת יוֹתֵר קָרֵב, דּוֹמֶה אָדם. קָרֵב יוֹתֵר, דּוֹמֶה יָרֹק. קָרֵב יוֹתֵר, דּוֹמֶה לָבָן, שֶׁאֵין בָּעוֹלָם לָבָן כְּמוֹתוֹ. טַל שֶׁהוֹלֵךְ מִמֶּנּוּ נִשְׁאָב בְּאוֹתוֹ עָנָף, וְעוֹשֶׂה פְרִי זֶה וּמִתְגַּדֵּל. אוֹתוֹ רָקִיעַ הוּא הוּא הוֹלֵךְ בְּגִלְגּוּל יוֹתֵר מִמַּה שֶּׁעֵינַיִם יְכוֹלוֹת לְהִסְתַּכֵּל."],[7,"","כָּל אוֹתָם שׁוֹמְרֵי בְּרִית הַקֹּדֶשׁ (רוצים) שֶׁרוֹצִים לְהֵרָאוֹת לִפְנֵי הַמֶּלֶךְ, שֶׁהֲרֵי לֹא נִרְאוּ אֶלָּא בִּשְׁבִיל לְהַרְאוֹת שֶׁהֵם בְּנֵי מִילָה קְדוֹשָׁה. וְעַל זֶה, (שמות כג) יֵרָאֶה כָּל זְכוּרְךְ, אוֹתָם בְּנֵי בְּרִית קֹדֶשׁ. דִּיֵּק רֹאשׁ הַיְשִׁיבָה, זְכוּרְךְ וְלֹא זְכָרְךְ, שֶׁהֲרֵי זָכָר כָּתוּב, וְלֹא זָכוּר. מַה זֶּה זְכוּרְךְ? אֶלָּא כָּל אוֹתָם שֶׁשָּׁמְרוּ בְּרִית קֹדֶשׁ וְלֹא חָטְאוּ בוֹ, הֵם הָיוּ בְּנֵי הַמֶּלֶךְ שֶׁבְּכָל יוֹם מִשְׁתַּבֵּחַ בָּהֶם וְזוֹכֵר אוֹתָם תָּמִיד. וְעַל כֵּן זְכוּרְךְ, הַהוּא שֶׁיֵּשׁ בּוֹ בְּרִית קְדוֹשָׁה, שֶׁזּוֹכֵר אוֹתָם הַמֶּלֶךְ בְּכָל יוֹם, שֶׁאֵין שֶׁבַח לִפְנֵי הַמֶּלֶךְ הָעֶלְיוֹן (אלא) כְּמִי שֶׁשּׁוֹמֵר בְּרִית זוֹ."],[8,"","וְעַל כֵּן צָרִיךְ לְהֵרָאוֹת שָׁלֹשׁ פְּעָמִים בְּשָׁנָה לְפָנָיו. שָׁלֹשׁ פְּעָמִים לָמָּה? אֶלָּא בִּגְלַל אָבוֹת הָרִאשׁוֹנִים שֶׁקִּבְּלוּ בְרִית זוֹ רִאשׁוֹנָה לְכָל מִצְווֹת הַתּוֹרָה, וּמִשּׁוּם כָּךְ שָׁלֹשׁ פְּעָמִים הֵם בְּשָׁנָה. אַבְרָהָם קִבֵּל בְּרִית, יִצְחָק קִבֵּל בְּרִית, יַעֲקֹב הָיָה שָׁלֵם מִכֻּלָּם, וְעַל כֵּן כָּתוּב בּוֹ (בראשית כה) וְיַעֲקֹב אִישׁ תָּם, שָׁלֵם מֵהַכֹּל."],[9,"","אַבְרָהָם נִקְרָא תָמִים, וְלֹא הָיָה כָּל כָּךְ שָׁלֵם, אֲבָל תָּם - שָׁלֵם מֵהַכֹּל. מַה כָּתוּב בְּנֹחַ? (שם ו) אִישׁ צַדִּיק תָּמִים הָיָה בְּדרֹתָיו. הָיָה רָשׁוּם בְּרֹשֶׁם קָדוֹשׁ בֵּינֵיהֶם. וְאָמַר רֹאשׁ הַיְשִׁיבָה, בְּכָל מָקוֹם שֶׁכָּתוּב תָּמִים, שֶׁרָשׁוּם בְּרֹשֶׁם קָדוֹשׁ בְּאוֹת קִיּוּם הַבְּרִית, וּמִשּׁוּם שֶׁשָּׁמַר הַבְּרִית נִקְרָא תָמִים בְּדרֹתָיו, מַה שֶּׁלֹּא הָיוּ כֻלָּם כָּךְ, שֶׁהֵם מְחַבְּלִים דַּרְכֵיהֶם."]]],[["וְעַל דָּא כְּתִיב, אֶת הָאֱלֹהִים הִתְהַלֵּךְ נֹחַ. וְכִי מַאן יָכִיל לְמֵיהַךְ עִמֵּיהּ. אֶלָּא כָּל מַאן דְּנָטִיר בְּרִית קַדִּישָׁא, אִזְדַּוְּוגַת בֵּיהּ שְׁכִינְתָּא, וְשָׁרִיאַת עָלֵיהּ. וּבְגִין כָּךְ, (דברים י״ח:י״ג) תָּמִים תִּהְיֶה עִם יְיָ אֱלֹהֶיךָ. תָּמִים תִּהְיֶה, וּלְבָתַר עִם יְיָ אֱלֹהֶיךָ. בְּזִוּוּגָא חֲדָא. דְּכֵיוָן דְּנָטִיר בְּרִית דָּא, עִם יְיָ לִהֱוִי, וְלָא אִתְפְּרַשׁ מִנֵּיהּ.","בְּאַבְרָהָם כְּתִיב, (בראשית י״ז:א׳) הִתְהַלֵּךְ לְפָנַי וְהְיֵה תָמִים, גְּזִירוּ דְּאָת קַיָּימָא. הִתְהַלֵּךְ לְפָנַי, מֵהָכָא, דְּלָא יְהַךְ גָּבֶר בָּתַר אִתְּתָא, אֶלָּא קַמָהָא, אֹרַח כָּשֵׁר אִיהוּ. וְהָא כְּתִיב, (שמות כ״ג:כ׳) הִנֵּה אָנֹכִי שׁוֹלֵחַ מַלְאָךְ לְפָנֶיךָ. (שמות ל״ג:ב׳) וְשָׁלַחְתִּי לְפָנֶיךָ מַלְאָךְ. לְאַבְרָהָם דְּלָא הֲוָה גָּזִיר, דָּחָה לֵיהּ לְקַמָּהּ. וְעַל דָּא לָא כְּתִיב הֶיֵה תָּמִים, וְהִתְהַלֵּךְ לְפָנַי. אֶלָּא הִתְהַלֵּךְ לְפָנַי, דְּלָא יֵאוֹת אַנְתְּ, עַד שֶׁתְּהֵא תָּמִים. וְכֵן בְּכֻלְּהוּ, כֵּיוָן דְּבַּר נָשׁ תָּמִים, וְנָטִיר לֵיהּ, מִיַּד הִיא לְקָמֵיהּ, וְאִיהוּ אֲבַתְרָהּ, כָּשֵׁר אִיהוּ לְדָא. לְגִרְעוֹנָא מַה כְּתִיב, (שמואל א ט״ו:י״א) כִּי שָׁב מֵאַחֲרַי.","נֹחַ גָּזִיר הֲוָה, וְתָמִים, פְּרִיעָה לָא הֲוָה בֵּיהּ, וּבְגִין דְּלָא הֲוָה בֵּיהּ פְּרִיעָה מַה כְּתִיב, אֶת הָאֱלֹהִים, וְלָא אַחַר הָאֱלֹהִים, לְקַמָּא לָא הֲוָה, בְּגִין דְּהֲוָה גְּזִיר, לַאֲחוֹרָא לָא הֲוָה, בְּגִין דְּלָא אִתְפְּרַע. אֵיךְ הֲוָה. אֶת הָאֱלֹהִים, סָמִיךְ לֵיהּ, וְלָא יָכִיל לְאִסְתַּכְּלָא בֵּיהּ, דְּלָאו כָּשֵׁר כָּל כַּךְ.","בְּיִשְׂרָאֵל כְּתִיב, (שמות י״ג:כ״א) וַיְיָ הוֹלֵךְ לִפְנֵיהֶם יוֹמָם בְּעַמּוּד עָנָן וְלַיְלָה בְּעַמּוּד אֵשׁ וְגוֹ'. כֵּיוָן דְּאָמְרוּ יִשְׂרָאֵל, (שמות י״ד:י״א) הֲמִבְּלִי אֵין קְבָרִים בְּמִצְרַיִם וְגוֹ'. כִּי טוֹב לָנוּ עֲבוֹד אֶת מִצְרַיִם. כִּבְיָכוֹל, אִתְחֲלָשׁ דַּעְתָּא. כְּתִיב וַיִּסַּע מַלְאַךְ הָאֱלֹהִים הַהוֹלֵךְ לִפְנֵי מַחֲנֵה יִשְׂרָאֵל וַיֵּלֶךְ מֵאַחֲרֵיהֶם, וַיִּסַּע לְמֶעְבַּד בְּהוּ נוּקְמִין.","(חסר) וְעַל דָּא חַדֵּי מָשִׁיחַ, וְחַדֵּי רַב מְתִיבְתָּא, דְּקָא אִתְבָּשָּׂר בְּדָא. וְאָמַר רַב מְתִיבְתָּא, דְּהָא דָּיִיק לְמָשִׁיחַ וְאָמַר, מְנָא הֲוָה לְדָנִיאֵל דְּקָאָמַר, (דניאל ה׳:כ״ח) פְּרֵיס פְּרִיסַת מַלְכוּתָךְ וִיהִיבַת לְמָדַי וּפָרָס. מֵאִינּוּן אַתְוָון דְּוּפַרְסִין אִשְׁתְּמַע לֵיהּ. וְהָכָא מַאי הוּא. אָמַר לֵיהּ, הָכִי הוּא וַדַּאי, פְּרֵיס פְּרִיסַת מַלְכוּתָךְ חַיָּיבָא, עַל יְדֵי דְּמָשִׁיחַ אַחֲרָא, וּלְבָתַר יִשְׁלוֹט מֶלֶךְ פְּרָס, וְיִטּוֹל מַלְכְּוָון סַגִּיאִין, וְהוּא יִשְׁלֹט עַל אַרְעָא קַדִּישָׁא תְּרֵיסָר יַרְחֵי, וְהוּא יִשְׁלוֹט וְיִקְטוֹל סַגִּיאִין, וְהַהוּא מְשִׁיחָא, וּלְבָתַר יִפּוֹל, וִיקַבְּלוּן מַלְכוּתָא קַדִּישֵׁי עֶלְיוֹנִין. וְעַל דָּא, וּפַרְסִין, מַלְכָּא דְּפָרַס, אִשְׁתְּמַע הָכָא.","אִי חֲסִידָא קַדִּישָׁא, כַּמָּה חֶדְוָה עַל חֶדְוָה, בְּהַהוּא מַעְיָינָא. בְּהַהוּא מַעְיָינָא, מְגַדְּלָא כָּל זִינֵי אִילָנִין, דְּנָצִיב קוּדְשָׁא בְּרִיךְ הוּא בְּגַּן עֵדֶן, וְכֻלְּהוּ קַיְימֵי לְאַסְוָותָא, טַרְפִּין וְאֵיבִין וְעַנְפִין, וּלְחַדוּ לִבָּא תָּדִיר. וְלֵית בֵּינַיְיהוּ כַּפְנָא, וּדְאָגָה, וַאֲנָחָה, לְעָלְמִין. זַכָּאָה עַמָּא דְּכָל דָּא מְחַכָּאן, וְכָל דָּא גָּנִיז לוֹן.","אָמַר רַבִּי שִׁמְעוֹן, בְּקַרְקַע דְּהַאי מַקְדְּשָׁא, אִית מֵאִלֵּין ם פְּלִיאָן, אָמַר לֵיהּ, אִי רִבִּי, אִי רִבִּי, זַכָּאָה חוּלָקָךְ דְּכָל הַאי. בְּהַהוּא. עַל גַּבֵּי הַהוּא מַעְיָינָא רְקִימָא, אֲבָל לֵית מַאן דְּיָכִיל לְאִסְתַּכְּלָא בֵּיהּ, לְזִמְנִין נְהִירוּ דִּילֵיהּ נְהוֹרָא. לְזִמְנִין חֲשׁוֹכָא, לְזִמְנִין גּוָֹון אַרְגְּוָונָא. מְנַצְּצָן דְּלָא יַכְלִין עַיְינִין לְאִסְתַּכְּלָא לְעֵילָּא. (ס\"א ההיא) הִיא דְּשָׁאַלְת חֲסִידָא קַדִּישָׁא, מֵהַהוּא קַרְקַע דְּמַקְדְּשָׁא, רַב מְתִיבְתָּא לָא פָּרִישׁ מִנֵּיהּ, דְּהָא גָּנִיז אִיהוּ גּוֹ יַרְדְּנָא, וְהָא אֲמֵינָא לָךְ מַה דַּאֲמֵינָא, אֲבָל נִשְׁאַל מִלָּה דָּא, וְתִנְדַּע מַה דְּתִנְדַּע.","יַרְדֵּן דָּא, עָאל וְאִתְמְשַׁךְ זִמְנָא חֲדָא בְּשַׁתָּא, גּוֹ הַהוּא נָהָר דְּנָפִיק מֵעֵדֶן, לָאו מֵאִינּוּן אַרְבַּע נַהֲרִין דְּאִתְמַשְּׁכָן מִנֵּיהּ, אֶלָּא בֵּיהּ מַמָּשׁ. כֵּיוָן דְּמָטֵי לְגַבֵּיהּ, אִיהוּ אִתְמְשַׁךְ וְאִתְפָּשַּׁט וְעָאל גּוֹ יַרְדְּנָא. וְכֵיוָן דְּמָטֵי גּוֹ קַרְקַע דְּמַקְדְּשָׁא, אִשְׁתְּכַח תַּמָּן תְּלַת יוֹמִין, וְלָא אִתְפְּשָׁט וְלָא אִתְמְשַׁךְ לְאֲתָר אַחֲרָא. וְאָמַר רַב מְתִיבְתָּא, דְּכַד אַהְדָּר הַהוּא נָהָר לְאַתְרֵיהּ, שָׁבִיק תַּמָּן, כָּל זִינֵי צִיּוּרִין, דְּקָא עָבִיד קוּדְשָׁא בְּרִיךְ הוּא בְּגַּן עֵדֶן, דְּאִינּוּן צִיּוּרִין גְּנִיזִין, דִּתְחוֹת דּוּכְתַּיְיהוּ. (חסר)","אִלֵּין הָכָא וְאִלֵּין הָכָא, וְסַלְקֵי וְנַחְתֵּי כִּדְקַדְמֵיתָא. בְּהַהוּא סְטָר דָּרוֹם, אִית תְּלַת מְאָה וְחַמְשִׁין עַמּוּדִין, מִכָּל זִינֵי מַרְגְּלָאן. וְאִלֵּין אִינּוּן דִּנְהִרִין תָּדִיר, וְנַטְפִין בּוּסְמִין טְמִירִין, דְּלָא אִתְגַּלּוּ לְעָלְמִין. אַרְבַּע אַגָּנִין בְּכָל עַמּוּדָא וְעַמּוּדָא נְעִיצִין. וְכַד אִינּוּן בּוּסְמִין נַטְפִין, מֵאִינּוּן עַמּוּדִין, נַפְלֵי בְּהוּ, וְאִתְמַלְיָין כֻּלְּהוּ אֲגָנוֹת, וְלָא נָפְקִין בּוּסְמִין לְבַר."],[[0,"וע״ד כתיב את וגו׳:","וע״כ כתוב, את האלקים התהלך נח. שואל, וכי מי יכול ללכת עם האלקים. ומשיב, אבל כל מי ששומר ברית קדש, מתחברת בו השכינה ושורה עליו. ומשום זה כתוב, תמים תהיה עם ה׳ אלקיך. שפירושו, תמים תהיה, ואח״כ עם ה׳ אלקיך בחבור אחד. כיון ששומר ברית זה, יהיה עם ה', ולא יפרוש ממנו."],[1,"באברהם כתיב התהלך וגו׳:","באברהם כתוב, התהלך לפני והיה תמים. דהיינו מילת אות ברית שנקרא תמים. \u0003התהלך לפני,\u0004 מכאן שלא ילך גבר אחר אשה אלא לפניה, שהוא דרך הישר. שואל, והרי כתוב הנה אנכי שולח מלאך לפניך, שפירושו השכינה המכונה מלאך. וכן ושלחתי לפניך מלאך. הרי שהשכינה הלכה לפניהם והם לאחוריה. ומשיב, אברהם שלא היה נמול, דחתה אותו לפניה, ולא נתנה אותו ללכת לאחוריה, וע״כ לא כתוב, היה תמים והתהלך לפני, אלא התהלך לפני כל עוד שאינך נמול, כי אינך ראוי ללכת לאחורי עד שתהיה תמים, דהיינו עד שתמול וכן בכלם, שכן הוא בכל האנשים, כיון שאדם הוא תמים ושומר אותו, מיד השכינה לפניו והוא אחריה. כי כשר הוא לזה."],[1,"","פירוש. כי אין החכמה מקובלת מן המלכות אלא מכלים דאחורים שלה, (כנ״ל ויקהל אות נ״ג) ואם האדם אינו ראוי לזה, דהיינו שלא נמול, והוא עלול להמשיך החכמה ממעלה למטה, אז הוא אסור ללכת אחורי השכינה, שפירושו שלא ימשיך ממנה החכמה מאחורים שלה. וע״ז רמזו ז״ל, אסור לגבר ללכת אחרי אשה. משא״כ אחר שנמול והוא שומר ברית, דהיינו שכבר בטוח שלא ימשיך החכמה ממעלה למטה הוא ראוי ללכת אחר השכינה, דהיינו שראוי לקבל הארת החכמה מאחורים שלה. וז״ש, \u0003אלא התהלך לפני, דלא יאות אנת עד שתהא תמים,\u0004 שכל עוד שאינו נמול נאמר לו התהלך \u0003לפני,\u0004 ולא לאחרי, מטעם הנ\"ל. אבל \u0003כיון דב״נ תמים, ונטיר ליה,\u0004 דהיינו שנמול ושומר בריתו, \u0003מיד היא לקמיה ואיהו אבתרה,\u0004 דהיינו שמקבל מאחורי השכינה, כי \u0003פשר איהו לדא,\u0004 כי הוא כשר לקבל חכמה מאחורי השכינה. להיותו שומר הברית. כמבואר. לגנאי מה כתוב. כי שב מאחרי. דהיינו שאינו ראוי לינק מאחורי השכינה."],[2,"נח גזיר הוה וכו׳:","נח נמול היה ותמים, פריעה לא היתה בו.. ומשום שלא היתה בו פריעה מה כתוב, \u0003את האלקים\u0004 התהלך נח, ולא אחר האלקים. כי לפני השכינה לא היה משום שהיה נמול. לאחר השכינה לא היה, משום שלא עשה פריעה, אלא איך היה, \u0003את האלקים,\u0004 דהיינו סמוך לו, אבל אינו יכול להסתכל באחורים שלו, כי אינו כשר כל כך. משום שלא עשה פריעה."],[3,"בישראל כתיב וה' וגו׳:","בישראל כתוב, וה' הולך לפניהם יומם בעמוד ענן ולילה בעמוד אש וגו׳. היינו שהיו הולכים אחרי ה'. כיון שאמרו ישראל המבלי אין קברים במצרים וגו', כי טוב לנו עבוד את מצרים, כביכול, נחלש הדעת, ע״כ כתוב, ויסע מלאך האלקים ההולך לפני מחנה ישראל וילך מאחריהם, דהיינו שנדחו לפני ה'. \u0003ויסע,\u0004 היינו לעשות בהם נקמות. (חסר ההמשך)"],[4,"וע״ד חדי משיח וכו׳:","(חסר ההתחלה) ועל זה שמח המשיח, ושמח ראש הישיבה שנתבשר בזה. ואמר ראש הישיבה שהיה מדייק ושאל המשיח, ואמר, מאין ידע דניאל, שאמר פריס פריסת מלכותך ויהיבת למדי ופרס, הוא ידע זה מאותיות אלו \u0003ופרסין,\u0004 שהיה כתוב, וכאן מה הוא. כלומר, מה נשמע מזה לענין מלך המשיח. אמר לו כך הוא ודאי. שנרמז כאן ענין מלך המשיח, פריס פריסת מלכותך הרשעה על ידי משיח האחר, דהיינו משיח בן יוסף. ואח\"כ ישלוט מלך פרס ויכבוש הרבה מלוכות, והוא ישלוט על ארץ הקדושה י״ב חדש. והוא ישלוט ויהרוג רבים, ובתוכם משיח ההוא, משיח בן יוסף. ואח״כ יפול מלך פרס, וקדושים העליונים יקבלו המלכות. וע״כ גם כאן, המלה \u0003ופרסין\u0004 משמע \u0003שהוא מלך פרס.\u0004"],[5,"אי חסידא קדישא וכו׳:","אהה חסיד הקדוש, כמה שמחה על שמחה הוא במעיין ההוא, במעיין ההוא גדלים כל מיני אילנות שנטע הקב״ה בגן עדן, וכולם עומדים לרפואה, העלים והפירות והענפים, ולשמחת הלב תמיד. ואין ביניהם רעב ודאגה ואנחה לעולם. אשרי העם שמחכים להם כל זה. וכל זה גנוז להם."],[6,"אר״ש בקרקע דהאי וכו׳:","א\"ר שמעון בקרקע המקדש יש מאלו הפליאות. אמר לו אהה רבי, אהה רבי, אשרי חלקך שכל זה בההוא (חסר כאן) על אותו מעיין הוא נרקם, אבל אין מי שיכול להסתכל בו, לפעמים האור שלו הוא אור, ולפעמים הוא חשך, ולפעמים הוא בצבע ארגמן. ונוצצים עד שהעינים אינם יכולים להסתכל למעלה. וההוא ששאלת, חסיד קדוש, מאותו קרקע המקדש, רב מתיבתא לא ביאר ממנו, כי הוא גנוז תוך הירדן. והרי אמרתי לך מה שאמרתי, אבל נשאל דבר זה ותדע מה שתדע."],[7,"ירדן דא עאל וכו׳:","ירדן זה, שהוא יסוד המלכות, נכנם ונמשך פעם אחת בשנה, דהיינו פעם א׳ שה״ס קו אחד, משלש פעמים בשנה, שה״ס ג׳ קוין, והיינו בסוד קו שמאל, תוך אותו הנהר היוצא מעדן, שהוא יסוד דז״א, שתחילת הזווג היא בבחינת קו שמאל, ולא מאלו ד׳ נהרות המתפשטים ממנו, אלא בו ממש, בנהר היוצא מעדן עצמו, כיון שהוא מגיע אליו, הוא נמשך ומתפשט ונכנס תוך הירדן, מבחינת קו שמאל תחילה, בסוד פיוסא (כנ״ל ב\"ב דף קל״ו ד\"ה פנימית) וכיון שמגיע לקרקע המקדש, שה״ס המלכות דמלכות, נמצא שם ג׳ ימים, דהיינו בסוד ג׳ קוין, ואינו מתפשט ואינו נמשך למקום אחר. ואמר רב מתיבתא, כשחוזר אותו הנהר היוצא מעדן למקומו, עוזב שמה, בקרקע המשכן, כל מיני ציורין שעושה הקב\"ה בג״ע, שהם ציורים גנוזים תחת מקומם (חסר הסיום)."],[8,"אלין הכא ואלין הכא וכו׳:","(חסר ההתחלה) אלו כאן, ואלו כאן ועולים ויורדים כבתחילה. בצד דרום ההוא, שהוא קו ימין, שכולו חסד, יש ש״נ עמודים מכל מיני מרגליות. ואלו הם שמאירים תמיד, ונוטפים בשמים נסתרים שאינם נגלים לעולם. ארבעה אגנות תקועים בכל עמוד ועמוד. וכשהבשמים נוטפים מן העמודים נופלים באגנות וכל האגנות מתמלאים, ואין הבשמים יוצאים לחוץ."]],[[0,"","וְעַל זֶה כָּתוּב אֶת הָאֱלֹהִים הִתְהַלֶּךְ נֹחַ. וְכִי מִי יָכוֹל לָלֶכֶת עִמּוֹ? אֶלָּא כָּל מִי שֶׁשּׁוֹמֵר בְּרִית קֹדֶשׁ, מִזְדַּוֶּגֶת בּוֹ שְׁכִינָה וְשׁוֹרָה עָלָיו. וּמִשּׁוּם כָּךְ, (דברים יח) תָּמִים תִּהְיֶה עִם ה' אֱלֹהֶיךְ. תָּמִים תִּהְיֶה, וְאַחַר כָּךְ עִם ה' אֱלֹהֶיךְ. בְּזִוּוּג אֶחָד. שֶׁכֵּיוָן שֶׁשּׁוֹמֵר בְּרִית זוֹ, עִם ה' לִהְיוֹת, וְלֹא נִפְרָד מִמֶּנּוּ."],[1,"","בְּאַבְרָהָם כָּתוּב, (בראשית יז) הִתְהַלֵּךְ לְפָנַי וֶהְיֵה תָמִים, מִילַת אוֹתוֹ בְּרִית. הִתְהַלֵּךְ לְפָנַי - מִכָּאן שֶׁלֹּא יֵלֵךְ גֶּבֶר אַחַר אִשָּׁה, אֶלָּא לְפָנֶיהָ דֶּרֶךְ כָּשֵׁר הוּא. וַהֲרֵי כָּתוּב (שמות כג) הִנֵּה אָנֹכִי שּלֵחַ מַלְאָךְ לְפָנֶיךְ. (שם לג) וְשָׁלַחְתִּי לְפָנֶיךְ מַלְאָךְ. לְאַבְרָהָם שֶׁלֹּא הָיָה מָהוּל, דָּחָה אוֹתוֹ לְפָנֶיהָ. וְעַל כֵּן לֹא כָתוּב הֱיֵה תָמִים וְהִתְהַלֵּךְ לְפָנַי, אֶלָּא הִתְהַלֵּךְ לְפָנַי, שֶׁלֹּא רָאוּי אַתָּה עַד שֶׁתִּהְיֶה תָמִים. וְכֵן בְּכֻלָּם, כֵּיוָן שֶׁבֶּן אָדָם תָּמִים וְשׁוֹמֵר אוֹתוֹ, מִיָּד הִיא לְפָנָיו, וְהוּא אַחֲרֶיהָ, כָּשֵׁר הוּא לָזֶה. לְחִסָּרוֹן מַה כָּתוּב? (שמואל א טו) כִּי שָׁב מֵאַחֲרַי."],[2,"","נֹחַ מָהוּל הָיָה וְתָמִים, פְּרִיעָה לֹא הָיְתָה בּוֹ, וּמִשּׁוּם שֶׁלֹּא הָיְתָה בּוֹ פְּרִיעָה, מַה כָּתוּב? אֶת הָאֱלֹהִים, וְלֹא אַחַר הָאֱלֹהִים. לְפָנִים לֹא הָיָה, מִשּׁוּם שֶׁהָיָה מָהוּל. לְאָחוֹר לֹא הָיָה, מִשּׁוּם שֶׁלֹּא נִפְרַע. אָז אֵיךְ הָיָה? אֶת הָאֱלֹהִים, סָמוּךְ לוֹ, וְלֹא יָכוֹל לְהִסְתַּכֵּל בּוֹ, שֶׁלֹּא כָּל כָּךְ כָּשֵׁר."],[3,"","בְּיִשְׂרָאֵל כָּתוּב, (שמות יג) וַה' הֹלֵךְ לִפְנֵיהֶם יוֹמָם בְּעַמּוּד עָנָן (וגו') וְלַיְלָה בְּעַמּוּד אֵשׁ וְגוֹ'. כֵּיוָן שֶׁאָמְרוּ יִשְׂרָאֵל (שם יד) הֲמִבְּלִי אֵין קְבָרִים בְּמִצְרַיִם וְגוֹ', כִּי טוֹב לָנוּ עֲבֹד אֶת מִצְרַיִם - כִּבְיָכוֹל נֶחֱלַשׁ דַּעְתּוֹ. כָּתוּב וַיִּסַּע מַלְאַךְ הָאֱלֹהִים הַהֹלֵךְ לִפְנֵי מַחֲנֵה יִשְׂרָאֵל וַיֵּלֶךְ מֵאַחֲרֵיהֶם. וַיִּסַּע, לַעֲשׂוֹת בָּהֶם נְקָמוֹת."],[4,"","וְעַל זֶה שָׂמַח הַמָּשִׁיחַ וְשָׂמַח רֹאשׁ הַיְשִׁיבָה, שֶׁהִתְבַּשֵּׂר בָּזֶה. וְאָמַר רֹאשׁ הַיְשִׁיבָה, שֶׁהֲרֵי דִּיֵּק לַמָּשִׁיחַ וְאָמַר, מִנַּיִן הָיָה לְדָנִיֵּאל שֶׁאָמַר, (דניאל ה) שָׁבַר מַלְכוּתְךְ לִשְׁנַיִם וְנִתְּנָה לְמָדַי וּפָרַס? מֵאוֹתָן אוֹתִיּוֹת שֶׁל וּפַרְסִין נִשְׁמַע לוֹ. וְכָאן מַהוּ? אָמַר לוֹ, כָּךְ זֶה וַדַּאי, פְּרֵס פְּרִיסַת מַלְכוּתָךְ (שבר מלכותך) הָרְשָׁעָה עַל יְדֵי מָשִׁיחַ אַחֵר, וְאַחַר כָּךְ יִשְׁלֹט מֶלֶךְ פָּרַס וְיִטֹּל מַמְלָכוֹת רַבּוֹת, וְיִשְׁלֹט עַל אֶרֶץ הַקֹּדֶשׁ שְׁנֵים עָשָׂר חֳדָשִׁים, וְיִשְׁלֹט וְיַהֲרֹג רַבִּים וְאוֹתוֹ מָשִׁיחַ, וְאַחַר כָּךְ יִפֹּל, וִיקַבְּלוּ אֶת הַמַּלְכוּת קְדוֹשִׁים עֶלְיוֹנִים. וְעַל זֶה וּפַרְסִין, מֶלֶךְ פָּרַס נִשְׁמָע כָּאן."],[5,"","אִי חָסִיד קָדוֹשׁ, כַּמָּה חֶדְוָה עַל חֶדְוָה בְּאוֹתוֹ מַעְיָן. בְּאוֹתוֹ מַעְיָן מְגַדְּלִים כָּל מִינֵי אִילָנוֹת שֶׁהִצִּיב הַקָּדוֹשׁ בָּרוּךְ הוּא בְּגַן עֵדֶן, וְכֻלָּם קַיָּמִים לִרְפוּאָה, עָלִים וּפֵרוֹת וַעֲנָפִים, וּלְשִׂמְחַת הַלֵּב תָּמִיד. וְאֵין בֵּינֵיהֶם רָעָב וּדְאָגָה וַאֲנָחָה לְעוֹלָמִים. אַשְׁרֵי הָעָם שֶׁלְּכָל זֶה מְצַפִּים וְכָל זֶה גָּנוּז לָהֶם."],[6,"","אָמַר רַבִּי שִׁמְעוֹן, בְּקַרְקַע הַמִּקְדָּשׁ הַזֶּה יֵשׁ מֵאוֹתָן הַפְּלָאוֹת. אָמַר לוֹ, אִי רַבִּי, אִי רַבִּי, אַשְׁרֵי חֶלְקְךְ שֶׁכָּל זֶה בְּאוֹתוֹ עַל גַּבֵּי אוֹתוֹ מַעְיָן רָקוּם, אֲבָל אֵין מִי שֶׁיָּכוֹל לְהִסְתַּכֵּל בּוֹ. לִפְעָמִים אוֹרוֹ אוֹר, לִפְעָמִים חֹשֶׁךְ, לִפְעָמִים גּוֹן אַרְגָּמָן, נוֹצְצִים שֶׁהָעֵינַיִם לֹא יְכוֹלוֹת לְהִסְתַּכֵּל לְמַעְלָה. (ההיא) הִיא שֶּׁשָּׁאַלְתָּ, חָסִיד קָדוֹשׁ, מֵאוֹתוֹ קַרְקַע הַמִּקְדָּשׁ, רֹאשׁ הַיְשִׁיבָה לֹא נִפְרָד מִמֶּנּוּ, שֶׁהֲרֵי גָּנוּז הוּא בְּתוֹךְ הַיַּרְדֵּן, וַהֲרֵי אָמַרְתִּי לְךְ מַה שֶּׁאָמַרְתִּי, אֲבָל נִשְׁאַל דָּבָר זֶה, וְתֵדַע מַה שֶּׁתֵּדַע."],[7,"","יַרְדֵּן זֶה נִכְנָס וְנִמְשָׁךְ זְמַן אֶחָד בַּשָּׁנָה לְתוֹךְ אוֹתוֹ נָהָר שֶׁיּוֹצֵא מֵעֵדֶן, וְלֹא מֵאוֹתָם אַרְבָּעָה נְהָרוֹת שֶׁנִּמְשָׁכִים מִמֶּנּוּ, אֶלָּא בּוֹ מַמָּשׁ. כֵּיוָן שֶׁהִגִּיעַ אֵלָיו, הוּא נִמְשָׁךְ וּמִתְפַּשֵּׁט וְנִכְנָס לְתוֹךְ הַיַּרְדֵּן. וְכֵיוָן שֶׁמַּגִּיעַ לְתוֹךְ קַרְקַע הַמִּקְדָּשׁ, נִמְצָא שָׁם שְׁלֹשָׁה יָמִים, וְלֹא מִתְפַּשֵּׁט וְלֹא נִמְשָׁךְ לְמָקוֹם אַחֵר. וְאָמַר רֹאשׁ הַיְשִׁיבָה, שֶׁכְּשֶׁחוֹזֵר אוֹתוֹ נָהָר לִמְקוֹמוֹ, מַשְׁאִיר שָׁם כָּל מִינֵי צִיּוּרִים שֶׁעוֹשֶׂה הַקָּדוֹשׁ בָּרוּךְ הוּא בְּגַן עֵדֶן, שֶׁאוֹתָם צִיּוּרִים גְּנוּזִים תַּחַת מְקוֹמָם."],[8,"","אֵלֶּה כָּאן וְאֵלֶּה כָּאן, וְעוֹלִים וְיוֹרְדִים כְּמִקֹּדֶם. בְּאוֹתוֹ צַד דָּרוֹם יֵשׁ שְׁלֹשׁ מֵאוֹת וַחֲמִשִּׁים עַמּוּדִים מִכָּל מִינֵי מַרְגָּלִיּוֹת. וְאֵלֶּה אוֹתָם שֶׁמְּאִירִים תָּמִיד, וְנוֹטְפִים בְּשָׂמִים נִסְתָּרִים שֶׁלֹּא הִתְגַּלּוּ מֵעוֹלָם. אַרְבָּעָה אַגָּנִים בְּכָל עַמּוּד וְעַמּוּד נְעוּצִים. וּכְשֶׁאוֹתָם בְּשָׂמִים נוֹטְפִים מֵאוֹתָם עַמּוּדִים, נוֹפְלִים בָּהֶם, וּמִתְמַלְּאִים כָּל הָאַגָּנוֹת, וְלֹא יוֹצְאִים הַבְּשָׂמִים הַחוּצָה. מֵאוֹתָם בְּשָׂמִים עֲתִידִים לֶעָתִיד"]]],[["מֵאִינּוּן בּוּסְמִין, זְמִינִין לְזִמְנָא דְּאָתֵי, לְאַקְטְרָא בְּכָל יוֹמָא קְטוֹרְתָא, קַמֵּי מַלְכָּא קַדִּישָׁא. דְּלָא יֵהווּ מִכְּתִישׁוּ דִּבְנֵי נָשָׁא. אִינּוּן בּוּסְמִין לָא יְדִיעַ עִקָּרָא דִּלְהוֹן, וּמִמָּה הֲווֹ, אֶלָּא מֵאִינּוּן עַמּוּדִין נַפְלִין תַּמָּן.","תְּרֵין נְשָׁרִין בְּכָל עַמּוּדָא וְעַמּוּדָא, מִתְנַצְּצָן מִתְלַהֲטִין בְּכָל גַּוְונִין. שֶׁבַע מְאָה נְשָׁרִין. אִינּוּן, פַּרְחִין, אִלֵּין הָכָא וְאִלֵּין הָכָא, בְּגִלְגּוּלָא דְּעַמּוּדִין. כַּד אִסְתַּחֲרָן, לָא יַכְלִין עַיְינִין לְאִסְתַּכְּלָא, דּוּכְתָּא דִּבְהוּ.","תְּלַת אַתְוָון בַּלְטִין וּפַרְחִין, מִפּוּמָא דָּא לְפוּמָא דָּא. בְּגִלְגּוּלָא דְּעַמּוּדִין וּנְשָׁרִין. כָּל אִינּוּן אַתְוָון מְרֻקְּמָן בְּאֶשָּׁא חִוָּורָא, וְדַהֲבָא יְרוֹקָא. תְּרֵין אַלְפִין וּמְאָה מְנַרְתִּין, תַּלְיָין בֵּין אִינּוּן עַמּוּדִין. וּתְרֵין אַלְפִין וּמְאָה שְׁרָגִין, בְּכָל מְנַרְתָּא וּמְנַרְתָּא. דַּלְקִין בִּימָמָא, וּבְלֵילְיָא מִתְדַּעֲכֵי, עַל צַעֲרָא דְּיִשְׂרָאֵל. כַּד אָתֵי צַפְרָא, דַּלְקִין כֻּלְּהוּ מִגַּרְמַיְיהוּ.","אַדְהֲווֹ יַתְבֵי, אַמְרֵי הָא רָמַשׁ לֵילְיָא. אָמַר לֵיהּ לְרַבִּי שִׁמְעוֹן, אִי חֲסִידָא קַדִּישָׁא, נְהִירוּ דְּעָלְמָא, טוֹל פִּנְקֵסָא דְּאַחְמָתָא דָּא, וְטוֹל שְׁרַגָא, וּכְתוֹב מִלִּין אִלֵּין, דְּהָא מָטָא זִמְנָא דִּילָן, לְפַקְדָּא כָּל חַד וְחַד לְגוֹ קִבְרֵיהּ, עַד פָּלְגוּ לֵילְיָא, דְקוּדְשָׁא בְּרִיךְ הוּא עָאל גּוֹ גִּנְתָּא לְאִשְׁתַּעְשְׁעָא בַּהֲדֵי צַדִּיקַיָּיא וּכְדֵין כָּל חַד וְחַד פָּרַח לְתַמָן. וּלְמָחָר נֶהֱוִי גַּבָּךְ, הוֹאִיל וְיָהֲבוּ לָן רְשׁוּ, לְאַשְׁלְמָא דּוֹרוֹנָא דְּקָא מְשַׁדְרֵי לָךְ. פַּרְחֵי, בָּכָה רַבִּי שִׁמְעוֹן וְגָעָא.","פָּתַח וְאָמַר, (משלי ה׳:י״ט) אַיֶּלֶת אַהָבִים וְיַעֲלַת חֵן דַּדֶּיהָ יְרַוִּוךָ בְכָל עֵת בְּאַהֲבָתָהּ תִּשְׁגֶּה תָמִיד. אוֹרַיְיתָא אוֹרַיְיתָא, נְהִירוּ דְּכָל עָלְמִין, כַּמָה יָמִין, וּנְחָלִין, וּמְקוֹרִין, וּמַבּוּעִין, מִתְפַּשְּׁטֵי מִנָךְ לְכָל סִטְרִין. מִנָךְ כֹּלָּא, עֲלָךְ קַיְימֵי עִלָּאִין וְתַתָּאִין, נְהִירוּ עִלָּאָה (ודא) מִנָךְ נָפְקָא. אוֹרַיְיתָא אוֹרַיְיתָא, מַה אֵימָא לְגַבָּךְ, אַיֶּלֶת אַהָבִים אַנְתְּ, וְיַעֲלַת חֵן (גבי) עֵילָּא וְתַתָּא רְחִימִין דִּילָךְ. מַאן יִזְכֵּי לְיַנְקָא מִנָךְ כְּדְקָא יֵאוֹת. אוֹרַיְיתָא אוֹרַיְיתָא שַׁעֲשׁוּעִים דְּמָארָךְ, מַאן יָכִיל לְגַלָּאָה, וּלְמֵימָר סִתְרִין וּגְנִיזִין דִּילָךְ. בָּכָה, וְאָעִיל רֵישֵׁיהּ בֵּין בִּרְכּוֹי, וְנָשַׁק לְעַפְרָא.","אַדְּהָכִי חָמָא כְּמָה דִּיוּקְנִין דְּחַבְרַיָּיא סַחֲרָנֵיהּ. אָמַר לֵיהּ, לָא תִּדְּחַל בְּרֵיהּ דְּיוֹחָאי, לָא תִּדְּחַל בּוּצִינָא קַדִּישָׁא, כְּתוֹב וְחַדֵּי גּוֹ חֶדְוָה דְּמָארָךְ. כָּתַב כָּל אִינּוּן מִלִּין דְּשָׁמַע בְּהַהוּא לֵילְיָא, וְלָעָא לוֹן, וְלָהַג לוֹן, וְלָא אַנְשֵׁי מִלָּה. וְהַהוּא שְׁרָגָא נָהִיר קָמֵּיהּ כָּל הַהוּא לֵילְיָא, עַד דְּאָתָא צַפְרָא. כַּד אָתָא צַפְרָא, זָקַף עֵינוֹי, וְחָמָא חַד נְהִירוּ דְּהֲוָה נָהִיר בִּרְקִיעָא, מָאִיךְ עֵינוֹי לְתַתָּא. אַהְדָּר כְּמִלְקַדְּמִין, וְחָמָא נְהִירוּ בְּכָל רְקִיעָ, דְּנָהִיר וְסָלִיק בְּהַהוּא נְהִירוּ דִּיּוּקְנָא דְּבֵיתָא, בְּכַמָּה צִיּוּרִין. חֲדָא רַבִּי שִׁמְעוֹן, וּלְפוּם רִגְעָא, אַגְנִיז הַהוּא נְהוֹרָא.","אַדְּהָכִי, הָא אִינּוּן תְּרֵין שְׁלִיחָן אַתְיָין. אַשְׁכְּחוּהוּ רֵישֵׁיהּ בֵּין בִּרְכּוֹי. אָמְרוּ לֵיהּ שְׁלָמָא עָלֵיהּ דְּמֹר, שְׁלָמָא לְמַאן דְּעִלָּאִין וְתַתָּאִין בָּעָאן לְאַקְדְּמָא לֵיהּ שְׁלָם. קוּם. קָם רַבִּי שִׁמְעוֹן וַחֲדָא בְּהוּ. אָמְרוּ לֵיהּ, וְלָא חָמִית נַיְיחָא דְּרוּחָא דְּעָבַד לָךְ מָארָךְ, חָמִית נְהִירוּ דְּבֵיתָא בִּרְקִיעָא. אָמַר לוֹן חֲמֵינָא, אָמְרוּ לֵיהּ בֵּיהּ שַׁעֲתָא, אַפִּיק תְּהוֹמָא בֵּי מַקְדְּשָׁא, וְאַעְבְּרֵיהּ קוּדְשָׁא בְּרִיךְ הוּא בְּיַמָּא רַבָּא, וּמִנְהִירוּ דִּילֵיהּ, הֲוָה נָהִיר בִּרְקִיעָא.","אָמְרוּ לֵיהּ, רַב מְתִיבְתָּא בָּעָא בִּשְׁלָמָךְ, וְהָא יָדַע דַּאֲנָן שְׁלִיחָן לְגַבָּךְ. וְכַמָּה מִלִּין חַדְתִּין עַתִּיקִין, אִתְחַדָּשׁ בְּאוֹרַיְיתָא בְּהַאי לֵילְיָא. אָמַר לוֹן, בְּמָטוּ מִנַּיְיכוּ, אִמְרוּ חַד מִלָּה מִנַּיְיהוּ. אָמְרוּ, לָא אִתְיְיהִיב לָן רְשׁוּ לְמַאי דְּאָתֵינָן לְגַבָּךְ, אֲבָל מִלָּה חַדְתָּא הֲוָה לְגַבָּךְ הַשְׁתָּא.","פָּתַח רַב מְתִיבְתָּא וְאָמַר (בראשית י״ב:א׳) וַיֹּאמֶר יְיָ אֶל אַבְרָם לֶךְ לְךָ מֵאַרְצְךָ וְגוֹ', דָּא בְּגִין דְּאִתְנַהֲרָא בֵּיהּ נְהִירוּ כְּגַוְונָא דָּא. מַאן דְּלָא זָכֵי בַּאֲתָר דָּא, יְהַךְ וְיִנְטַל גַּרְמֵיהּ לַאֲתָר אַחֲרָא, וְיִזְכֶּי בֵּיהּ. אָעָא דְּדָלִיק, וּנְהוֹרָא לָא סָלִיק וְנָהִיר בֵּיהּ, יְנַעְנְעוּן לֵיהּ, וִיסַלֵק בֵּיהּ נְהוֹרָא, וְאַנְהִיר. וַהֲוִינָן זְמִינִין לְמִשְׁמַע, אֲבָל בְּגִין לְמֵיתֵי גַּבָּךְ, לָא בָּעֵינָן לְאִתְעַכְּבָא, חַדֵּי רִבִּי שִׁמְעוֹן."],[[0,"מאינון בוסמין זמינין וכו׳:","מאלו הבשמים, עתידים לעתיד לבא להקטיר קטורת בכל יום לפני המלך הקדוש. שלא יהיו מכתיתת בני אדם. בשמים אלו לא ידוע עיקר שלהם, וממה היו, אלא שנופלים שם מאלו העמודים."],[1,"תרין נשרין בכל וכו׳:","ב׳ נשרים בכל עמוד ועמוד מתנוצצים ומאירים בכל הצבעים. שבע מאות נשרים הם בכל ש״נ העמודים. הם פורחים אלו כאן ואלו כאן עם גלגול העמודים. כשמסתובבים, לא תוכלנה העינים להסתכל במקום שלהם."],[2,"תלת אתוון בלטין וכו׳:","ג׳ אותיות בולטות ופורחות מפיו של זה לפיו של זה, בגלגול העמודים והנשרים. כל אלו האותיות נרקמות באש לבנה וזהב ירוק. ב׳ אלפים ומאה מנורות תלויות בין עמודים האלו. וב׳ אלפים ומאה נרות בכל מנורה ומנורה. דולקים ביום, ונכבים בלילה בשביל צער ישראל. כשבא הבוקר, נדלקים כולם מאליהם."],[2,"","פירוש המאמר. מחזה ולמטה דז״א יש בו ד׳ ספירות, שהם תנה״י, וכל אחת מתנה״י כלולה מכולן, ויש בכל אחת מהן תנה״י. והם רק ג׳ ספירות וחצי, כי רק נה\"י הן שלמות, ומת״ת אין בהם רק חצי ספירה שמחזה ולמטה, והן בסוד מאות, ע״כ יש ג׳ מאות בחינות נגד נה״י. וחמשים בחינות נגד ת\"ת. ונמצא, שיש ג׳ מאות וחמשים בחינות ביסוד, וכן ג׳ מאות וחמשים בחינות בהוד, וכו'. כי כל אחת כלולה מכולם. וש״נ של היסוד נקראים ש״נ עמודים. וש״נ של נצח, והש״נ של הוד, נקראים ש״נ נשרים. ויש בהם בחינת מלכיות שבגופם דהיינו שכל אחת מתנה״י כלולה מע״ס, ויש מלכות אחת בכל בחינה מש״נ בחינות שבד׳ הספירות, והם נקראות \u0003אגנות,\u0004 ומלבד אלו, יש מלכות הכוללת, המקובלת מכל תנה״י דז״א, שה״ס המלכות המקבלת מג׳ קוין נה״י דז״א. והיא נקראת מנורה. ולהיותה מקבלת שפע של ג׳ אותיות, כמ״ש לפנינו, הפורחות מנשר לנשר, ע״כ יש בה אלפים ומאה בחינות, כי בב׳ נשרים ב״פ ש״נ שהם ז׳ מאה, ומכל בחינה שבז׳ מאה נמשכות ג׳ אותיות, הנה ג״פ ז׳ מאה, הם אלפים ומאה. ע״כ יש אלפים ומאה מנורות, והאורות שבהם נקראים נרות, ולהיותם כולם כלולים זה מזה, יש בכל אחת מב׳ אלפים ומאה מנורות, ב׳ אלפים ומאה נרות."],[2,"","וזה אמרו (באות קע״ח) \u0003בההוא סטר דרום,\u0004 דהיינו בצד ימין בחסד דז״א, \u0003אית תלת מאה וחמשין עמודין,\u0004 שהם ש״נ בחינות שביסוד דז\"א הנקראים עמודים כנ״ל. \u0003מכל זיני מרגלאן, ואלין אינון דנהרין תדיר,\u0004 שהם מאירים לכל בחינות המלכות הנקראות מרגליות, ולהארהם אין הפסק. \u0003ונטפין בוסמין טמירין,\u0004 הארות החכמה מכונים בשמים המעלים ריח ממטה למעלה. ואומר, שהבשמים נוטפים מהם להיותם כלולים מכל ג׳ קוין, אלא שהבשמים הם בסתר, ואינם נודעים, וז״ש, \u0003דלא אתגלו לעלמין.\u0004 והוא מטעם, כי כאן המדובר היא בצד דרום, שהוא שליטת החסד, וע״כ הארת החכמה שבקו שמאל, שה״ס צפון, אינה יכולה להתגלות בו."],[2,"","וזה אמרו, \u0003ארבע אגנין בכל עמודא ועמודא,\u0004 דהיינו המלכיות שבגופם של העמודים כנ״ל, והם ד׳ בכל עמוד כנגד תנה״י, \u0003וכד אינון בוסמין וכו׳ נפלי בהו,\u0004 כלומר שהבשמים, שהן הארות החכמה שאינן יכולות להתגלות כאן, נופלות באותם האגנות, \u0003ולא נפקין בוסמין לבר,\u0004 שאינם מושפעות לחוץ מהם, אלא נשארות באגנות. מטעם הנ״ל. וז״ש (באות קע״ט) \u0003זמינין לזמנא דאתי לאתקטרא\u0004 וכו', שלעתיד לבא יתגלו הארות החכמה שבהם, \u0003דלא יהוו מכתישו דבני נשא,\u0004 שלא יהיה בהם שום התעוררות מלמטה מבני אדם, אלא יהיה כולו אתערותא דלעילא בלי אתערותא דלתתא כלל. \u0003אינון בוסמין לא ידיע עקרא דלהון וממה הוו,\u0004 דהיינו שאין בהם שום השגה, מטעם היותם בשליטת הימין. \u0003אלא מאינון עמודין נפלין תמן,\u0004 ושום תחתון אינו מתערב בזה."],[2,"","וזה אמרו (באות ק״פ) \u0003תרין נשרין בכל עמודא ועמודא\u0004 וכו׳, כי העמודים הם בחינות היסוד, ונצח והוד הנקראים ב׳ נשרים עומדים עליו, שעל כל בחינה של יסוד, יש ב׳ בחינות של נצח, ושל הוד. \u0003שבע מאה נשרין אינון,\u0004 כי יש ש״נ בחינות בנשר של נצח וכן ש״נ בחינות בנשר של הוד. \u0003פרחין, אלין הכא ואלין הכא בגלגולא דעמודין,\u0004 פירוש, בשעת הארת ג׳ קוין שהם מתגלגלים על ג׳ דוכתי, (כנ״ל ויחי דף קנ״ט ד״ה קל) אז הנשרים פורחים מדוכתא לדוכתא, והעמודים מתגלגלים. \u0003כד אסתחרן לא יכלין עיינין לאסתכלא\u0004 וכו', כלומר, אע״פ שבכל מקום מתגלה החכמה שה״ס הסתכלות עינים ע״י גלגול הקוין, הנה כאן אינו כן, אלא שאין העינים יכולים להסתכל. מטעם שכאן הוא שליטת החסד."],[2,"","וז״ש (באות קפ\"א) \u0003תלת אתוון בלטין ופרחין מפומא דא לפומא דא\u0004 וכו', השפע היא כלול מג' קוין המכונים ג׳ אותיות, ואחר שהשפע מתוקן כולו בנצח והוד, שהם ב׳ הנשרים הוא בא ליסוד, וע״כ השפע שהוא ג׳ אתוון פורחות מנשר לנשר, מנצח להוד ומהוד לנצח, בעת הגלגול של העמודים והנשרים. \u0003כל אינון אתוון מרקמן באשא חוורא,\u0004 שהוא שמאל הנקרא אש, כלול בלבן שהוא חסד, \u0003ודהבא ירוקא,\u0004 שהשמאל שהוא זהב כלול בקו אמצעי, שהוא ירוק. וז״ש \u0003תרין אלפין ומאה מנרתין תליין בין אינון עמודין\u0004 כי המלכות המקבלת השפע נקראת מנורה. ולהיות השפע בא מכל נשר בג׳ אותיות, שכנגד כל אות יש מנורה אחת לקבל אותה, וע״כ הם ג׳ פעמים ז׳ מאות אתוון, שהם ב׳ אלפים ומאה אותיות, המקובלות בב' אלפים ומאה מנורות. והן תלויות בין עמודים כדי לקבל השפע. והאורות שבמנורות נקראים נרות, וז״ש, \u0003ותרין אלפין ומאה שרגין בכל מנרתא ומנרתא,\u0004 כי כל אחת מב' אלפים ומאה כלולה מכולם, וע״כ יש ב׳ אלפים ומאה בכל מנורה ומנורה. ולהיותם כולם תחת שליטת צד דרום שהוא חסד השולט ביום ולא בלילה, ע״כ, \u0003דלקין ביממא, ובלילה מתדעכי,\u0004 כי בלילה שולט הדין, והחושך, וז״ש, \u0003על צערא דישראל,\u0004 דהיינו מפני שליטת הדין והחשך, שממנו נמשך צער ישראל. \u0003כד אתי צפרא דלקין כלהו מגרמייהו,\u0004 כלומר, כשמגיע זמן שליטת החסד הם נדלקים מאליהם, ואין צריך להעלאת מ\"ן מתחתונים."],[3,"אדהוו יתבי אמרי וכו׳:","בעוד שהיו יושבים, אמרו, הנה נחשך הלילה. אמר לו לר' שמעון, אהה חסיד קדוש אור העולם, קח ספר מתיק הזה, שהוא כלי שמשימים בו כתבים, וקח נר, וכתוב דברים אלו. כי הגיע הזמן שלנו, שיפקוד כל אחד את קברו עד חצות לילה, ואז נכנס הקב\"ה לגן עדן להשתעשע עם הצדיקים, ואז כל אחד ואחד ממנו פורח שמה. ולמחר נהיה אצלך משום שניתנה לנו רשות, להשלים המתנה ששלחו לך. דהיינו להשלים גילוי הסודות. פרחו. בכה ר״ש וגעה."],[4,"פתח ואמר אילת וגו׳:","פתח ואמר, אילת אהבים ויעלת חן דדיה ירווך בכל עת באהבתה תשגה תמיד. תורה תורה, האור של כל העולמות, כמה ימים ונחלים ומקורות ומבועים מתפשטים ממך לכל הצדדים, ממך הכל, עליך עומדים העליונים והתחתונים, אור העליון ממך יוצא. תורה תורה, מה אומר לך, אילת אהבים אתה ויעלת חן, למעלה ולמטה הם האוהבים שלך, מי יזכה לינק ממך כראוי. תורה תורה, השעשועים של אדונך, מי יכול לגלות ולומר הנסתרות והגניזות שלך. בכה והכניס ראשו בין ברכיו, ונשק את העפר."],[5,"אדהכי חמא כמה וכו׳:","בתוך כך ראה ר׳ שמעון כמה צורות של החברים מסביב לו. אמרו לו, אל תירא בנו של יוחאי, אל תירא מאור הקדוש, כתוב ושמח בשמחת רבונך. כתב כל אלו הדברים ששמע באותו לילה, ושנה אותם והגה אותם ולא שכח דבר. ונר ההוא האיר לו כל אותו הלילה עד שבא הבוקר. כשבא הבוקר, נשא עיניו וראה אור אחד שהיה מאיר ברקיע, השפיל עיניו למטה. חזר כבתחילה וראה אור בכל הרקיע שהאיר, ועלה באותו האור צורת הבית דהיינו בית המקדש, כלומר שנעשה הזווג של מלכות בז״א, בכמה ציורים. שמח ר״ש. וכרגע נגנז אור ההוא."],[6,"אדהכי הא אינון וכו׳:","בתוך כך הנה באו ב׳ השליחים. מצאו אותו ראשו בין ברכיו. אמרו לו שלום עליך אדוני, שלום למי שעליונים ותחתונים רוצים להקדים לו שלום. קום. קם ר״ש ושמח בהם. אמרו לו, ולא ראית נחת הרוח שעשה לך אדונך, ראית אור בית המקדש ברקיע. דהיינו הארת הזווג של מלכות בז״א שנקרא רקיע. אמר להם, ראיתי. אמרו לו בו בשעה, הוציא הקב״ה התהום שהוא המסך, של בית המקדש, שהוא מלכות, והעבירו בים הגדול שהיא בינה, ומאור שלו, דהיינו מאור המיתוק של המסך שבמלכות, בבינה, היה מאיר ברקיע, צורת בית המקדש. שה״ס הזווג."],[7,"אמרו ליה רב. וכו׳:","א\"ל רב מתיבתא דורש שלומך, והרי ידע שאנו שליחים אליך. וכמה דברים חדשים מעתיק נתחדש בתורה בלילה הזה. אמר להם, בבקשה מכם, אמרו דבר אחד מהם. אמרו לו, לא ניתנה לנו רשות לגלותם לך בזה שבאנו אליך, אלא דבר חדש אחד יש לנו אליך עתה."],[8,"פתח רב מתיבתא וכו׳:","אמרו לו. פר״מ ואמר. ויאמר ה׳ אל אברם לך לך מארצך וגו'. זה הוא משום שהאיר בו האור באפן זה. כלומר, שע״כ אמר לו הקב״ה לך לך וגו' משום שהאור לא יכול להאיר בו באפן אחר, אלא באפן זה. כי מי שאינו זוכה במקום זה, ילך ויטול עצמו למקום אחר, ויזכה שם, עץ הדולק, והאור אינו עולה ומאיר בו, ינענעו אותו ויעלו בו האור, ויאיר. ואמרו השליחים, היינו מוכנים לשמוע המשך הדברים מרב מתיבתא, אבל משום שהיינו צריכים לבא אליך, לא רצינו להתעכב. שמח ר׳ שמעון."]],[[0,"","לָבא לְהַקְטִיר בְּכָל יוֹם קְטֹרֶת לִפְנֵי הַמֶּלֶךְ הַקָּדוֹשׁ, שֶׁלֹּא יִהְיוּ מִכְּתִישַׁת בְּנֵי הָאָדָם. אוֹתָם בְּשָׂמִים לֹא יָדוּעַ עִקָּרָם, וּמִמֶּה הָיוּ, אֶלָּא מֵאוֹתָם עַמּוּדִים שֶׁנּוֹפְלִים שָׁם."],[1,"","שְׁנֵי נְשָׁרִים בְּכָל עַמּוּד וְעַמּוּד נוֹצְצִים וְלוֹהֲטִים בְּכָל הַגְּוָנִים. שְׁבַע מֵאוֹת נְשָׁרִים הֵם, פּוֹרְחִים אֵלֶּה כָּאן וְאֵלֶּה כָּאן בְּגִלְגּוּל הָעַמּוּדִים. כְּשֶׁמִּסְתּוֹבְבִים, לֹא יְכוֹלוֹת הָעֵינַיִם לְהִסְתַּכֵּל הַמָּקוֹם שֶׁבָּהֶם."],[2,"","שָׁלֹש אוֹתִיּוֹת בּוֹלְטוֹת וּפוֹרְחוֹת מִפֶּה זֶה לְפֶה זֶה. בְּגִלְגּוּל הָעַמּוּדִים וּנְשָׁרִים. כָּל אוֹתָן אוֹתִיּוֹת מְרֻקָּמוֹת בְּאֵשׁ לְבָנָה וְזָהָב יָרֹק. אַלְפַּיִם וּמֵאָה מְנוֹרוֹת תְּלוּיוֹת בֵּין אוֹתָם עַמּוּדִים, וְאַלְפַּיִם וּמֵאָה נֵרוֹת בְּכָל מְנוֹרָה וּמְנוֹרָה. דּוֹלְקִים בַּיּוֹם, וּבַלַּיְלָה דּוֹעֲכִים עַל צַעַר יִשְׂרָאֵל. כְּשֶׁמַּגִּיעַ הַבֹּקֶר דּוֹלְקִים כֻּלָּם מֵעַצְמָם."],[3,"","עַד שֶׁהָיוּ יוֹשְׁבִים, אָמְרוּ, הֲרֵי יָרַד הַלַּיְלָה. אָמַר לוֹ לְרַבִּי שִׁמְעוֹן, אִי חָסִיד קָדוֹשׁ, אוֹר הָעוֹלָם, קַח פִּנְקָס שֶׁל תִּיק זֶה, וְקַח נֵר וּכְתֹב דְּבָרִים אֵלּוּ, שֶׁהֲרֵי הִגִּיעַ זְמַנֵּנוּ לִפְקֹד כָּל אֶחָד וְאֶחָד לְתוֹךְ קִבְרוֹ עַד חֲצוֹת הַלַּיְלָה, שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא נִכְנַס לְתוֹךְ הַגָּן לְהִשְׁתַּעֲשֵׁעַ יַחַד עִם הַצַּדִּיקִים, וְאָז כָּל אֶחָד וְאֶחָד פּוֹרֵחַ לְשָׁם. וּלְמָחָר נִהְיֶה אֶצְלְךְ, הוֹאִיל וְנָתְנוּ לָנוּ רְשׁוּת לְהַשְׁלִים דּוֹרוֹן שֶׁמְּשַׁלְּחִים לְךְ. פָּרְחוּ, וּבָכָה רַבִּי שִׁמְעוֹן וְגָעָה."],[4,"","פָּתַח וְאָמַר, (משלי ה) אַיֶּלֶת אֲהָבִים וְיַעֲלַת חֵן דַּדֶּיהָ יְרַוֻּךְ בְכָל עֵת בְּאַהֲבָתָהּ תִּשְׁגֶּה תָמִיד. תּוֹרָה תּוֹרָה, אוֹר כָּל הָעוֹלָמוֹת, כַּמָּה יַמִּים וּנְחָלִים וּמְקוֹרוֹת וּמַבּוּעִים מִתְפַּשְּׁטִים מִמֵּךְ לְכָל הַצְּדָדִים. מִמֵּךְ הַכֹּל, עָלַיִךְ עוֹמְדִים עֶלְיוֹנִים וְתַחְתּוֹנִים, אוֹר הָעֶלְיוֹן (בזה) מִמֵּךְ יוֹצֵא. תּוֹרָה תּוֹרָה, מָה אֹמַר לְפָנַיִךְ? אַיֶּלֶת אֲהָבִים אַתְּ, וְיַעֲלַת חֵן, (אצל) מַעְלָה וּמַטָּה אֲהוּבִים שֶׁלָּךְ. מִי יִזְכֶּה לִינֹק מִמֵּךְ כָּרָאוּי? תּוֹרָה תּוֹרָה, שַׁעֲשׁוּעִים שֶׁל רִבּוֹנֵךְ, מִי יָכוֹל לְגַלּוֹת וְלוֹמַר סְתָרִים וּגְנִיזוֹת שֶׁלָּךְ? בָּכָה, וְהִכְנִיס רֹאשׁוֹ בֵּין בִּרְכָּיו וְנָשַׁק אֶת הֶעָפָר."],[5,"","בֵּין כָּךְ רָאָה כַּמָּה דְמֻיּוֹת שֶׁל חֲבֵרִים סְבִיבוֹ. אָמַר לוֹ, אַל תִּירָא בַּר יוֹחַאי, אַל תִּפְחַד מְנוֹרָה קְדוֹשָׁה, כְּתֹב וּשְׂמַח תּוֹךְ שִׂמְחַת רִבּוֹנְךְ. כָּתַב כָּל הַדְּבָרִים הַלָּלוּ שֶׁשָּׁמַע בְּאוֹתוֹ לַיְלָה, וְלָמַד בָּהֶם וְעָסַק בָּהֶם, וְלֹא שָׁכַח דָּבָר. וְאוֹתוֹ נֵר הֵאִיר לְפָנָיו כָּל אוֹתוֹ הַלַּיְלָה עַד שֶׁהִגִּיעַ הַבֹּקֶר. כְּשֶׁהִגִּיעַ הַבֹּקֶר, הֵרִים עֵינָיו, וְרָאָה אוֹר אֶחָד שֶׁהָיָה מֵאִיר בָּרָקִיעַ. הוֹרִיד עֵינָיו לְמַטָּה. חָזַר כְּמִקֹּדֶם וְרָאָה אוֹר בְּכָל הָרָקִיעַ שֶׁמֵּאִיר וְעוֹלֶה בְּאוֹתוֹ אוֹר דְּמוּת הַבַּיִת בְּכַמָּה צִיּוּרִים. שָׂמַח רַבִּי שִׁמְעוֹן, וּלְפִי רֶגַע נִגְנַז כָּל אוֹתוֹ הָאוֹר."],[6,"","בֵּין כָּךְ הֲרֵי אוֹתָם שְׁנֵי שְׁלִיחִים בָּאִים. מְצָאוּהוּ רֹאשׁוֹ בֵּין בִּרְכָּיו. אָמְרוּ לוֹ, שָׁלוֹם עָלֶיךְ מֹר! שָׁלוֹם לְמִי שֶׁעֶלְיוֹנִים וְתַחְתּוֹנִים רוֹצִים לְהַקְדִּים לוֹ שָׁלוֹם. קוּם! קָם רַבִּי שִׁמְעוֹן וְשָׂמַח בָּהֶם. אָמְרוּ לוֹ, וְלֹא רָאִיתָ נַחַת רוּחַ שֶׁעָשָׂה לְךְ רִבּוֹנְךְ? רָאִיתָ אוֹר הַבַּיִת בָּרָקִיעַ? אָמַר לָהֶם, רָאִיתִי. אָמְרוּ לוֹ, בְּאוֹתָהּ שָׁעָה הוֹצִיא הַתְּהוֹם בֵּית הַמִּקְדָּשׁ, וְהֶעֱבִירוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא בַּיָּם הַגָּדוֹל, וּמֵאוֹרוֹ הָיָה מוּאָר בָּרָקִיעַ."],[7,"","אָמְרוּ לוֹ, רֹאשׁ הַיְשִׁיבָה דּוֹרֵשׁ בִּשְׁלוֹמְךְ, וַהֲרֵי יוֹדֵעַ שֶׁאָנוּ שְׁלִיחִים אֵלֶיךְ, וְכַמָּה דְבָרִים חֲדָשִׁים עַתִּיקִים הִתְחַדְּשׁוּ בַתּוֹרָה בַּלַּיְלָה הַזֶּה. אָמַר לָהֶם, בְּבַקָּשָׁה מִכֶּם, אִמְרוּ דָבָר אֶחָד מֵהֶם. אָמְרוּ, לֹא נִתְּנָה לָנוּ רְשׁוּת לְמַה שֶּׁבָּאנוּ אֵלֶיךְ, אֲבָל דָּבָר חָדָשׁ הָיָה אֵלֶיךְ כָּעֵת."],[8,"","פָּתַח רֹאשׁ הַיְשִׁיבָה וְאָמַר, (בראשית יב) וַיֹּאמֶר ה' אֶל אַבְרָם לֶךְ לְךְ מֵאַרְצְךְ וְגוֹ'. זֶה בִּשְׁבִיל שֶׁנִּרְאֶה בּוֹ אוֹר כְּמוֹ זֶה. מִי שֶׁלֹּא זוֹכֶה בְּמָקוֹם זֶה, יֵלֵךְ וְיִקַּח עַצְמוֹ לְמָקוֹם אַחֵר וְיִזְכֶּה בּוֹ. עֵץ שֶׁדּוֹלֵק, וְהָאוֹר לֹא עוֹלֶה וּמֵאִיר בּוֹ, יְנַעְנְעוּ אוֹתוֹ וְיַעֲלֶה בּוֹ הָאוֹר וְיָאִיר. וְהָיִינוּ עֲתִידִים לִשְׁמֹעַ, אֲבָל בִּשְׁבִיל לָבא אֵלֶיךְ לֹא רָצִינוּ לְהִתְעַכֵּב. שָׂמַח רַבִּי שִׁמְעוֹן."]]],[["אָמְרוּ לֵיהּ, אִי חֲסִידָא קַדִּישָׁא, כָּל מִלִּין דִּי בְּגַוָּון בְּאוֹרַיְיתָא, מִלִּין זְעִירִין אִינּוּן, בְּכָל מִלָּה וּמִלָּה. וְאִינּוּן מִלִּין זְעִירִין, כַּמָה אִינּוּן מִלִּין רַבְרְבִין וְעִלָּאִין, עַד דְּלֵית לוֹן שִׁיעוּרָא. דְּהָא לֵית בְּגַוָּון סְפֵקָא, אֶלָּא בְּרִירוּ דְּאוֹרַיְיתָא עַל בּוּרְיֵיהּ. וְהַשְׁתָּא רַב מְתִיבְתָּא פָּרִישׁ מִלִּין סְתִימִין עַל דָּא, בְּגִין דְּעִקָרָא דְּנִשְׁמְתָא, אֲמַאי לָא נָהִיר בַּאֲתָר דָּא, וְזָכֵי לְאִתְנַהֲרָא בַּאֲתָר אַחֲרָא. וְעַד כְּעַן לָא זָכֵינָן בְּהוּ, בְּגִין לְמֵיתֵי גַּבָּךְ.","וּמִלָּה אַחֲרָא זָכֵינָן לְמִשְׁמַע מִנֵּיהּ, רוּחָא דְּאַזְלָא בְּעִרְטוּרָא בְּהַהוּא עָלְמָא בְּלָא בְּנִין, אִנְתְּתֵיהּ יִתְעֲבִיד לֵיהּ מָאנָא לְאִתְבְּנָאָה אִיהוּ. מַאי טַעֲמָא. אִנְתְּתֵיהּ אִיהִי שְׁרָגָא, דְּאִתְדְּלִיקַת מִנֵּיהּ, וְתַרְוַויְיהוּ שְׁרָגָא חֲדָא הֲווֹ, נְהוֹרָא דָּא נָפַק מִנְּהוֹרָא דָּא, אִתְדָעַךְ דָּא, אִתְדְלִיק מִגּוֹ נְהוֹרֵיהּ מַמָּשׁ, בְּגִין דַּחֲדָא נְהוֹרָא הֲווֹ.","הַשְׁתָּא רִבִּי, נֶהְדַּר לְמִלִּין קַדְמָאִין, וְכַד נֶהְדַּר לְאַתְרִין, נִטוֹל רְשׁוּ מֵרַב מְתִיבְתָּא, בְּאִינּוּן מִלִּין דִּנְקַבֵּל מִנֵּיהּ, וְנֵימָא קַמָּךְ. זַכָּאָה חוּלָקָךְ, דְּאַתְּ זָכֵי לִנְהוֹרִין סְתִימִין, מִכָּל סִטְרִין, מֵעֵילָּא וּמִתַּתָּא, מֵהַאי עָלְמָא, וּמֵעָלְמָא אוֹחֲרָא. אָמַר רִבִּי שִׁמְעוֹן, מִלָּה חֲדָא בָּעֵינָא לְמִנְדַּע, אִי תֵּיכוּל לְאוֹדָעָא לִי. נָשִׁין בְּהַהוּא עָלְמָא, אִי זַכָּאִין לְסַלְּקָא לְעֵילָּא, אוֹ הֵיךְ אִינּוּן תַּמָּן. אָמַר לֵיהּ, אִי רִבִּי אִי רִבִּי, בְּדָא אִית לָן רָזָא יַתִּירָא (ס\"א יקירא). בְּגִין דְּלָא לְגַלָּאָה סִתְרִין דְּתַמָּן, אֲבָל דָּא יְהַךְ וְיִטּוֹל רְשׁוּ, וְנֵימָא לָךְ. אַדְּהָכִי פָּרַח חַד, וְאִתְכַּסֵּי מִנַּיְיהוּ, וְאָזַל לֵיהּ.","וּלְפוּם שַׁעֲתָא תָּב לְגַבַּיְיהוּ, אָמַר לוֹן, זְמִינָא הֲוִינָא לְמֵיעָאל, וַהֲווּ כֻּלְּהוּ בְּעִטּוּרָא חֲדָא, דְּדַיָּינֵי דִּינָא דְּחַד בַּר נָשׁ, דְּקָאִים עַל פִּתְחָא דְּגַן עֵדֶן, וְאִינּוּן כְּרוּבִין אֲחִידוּ בֵּיהּ, וְלָא שָׁבְקוּ לֵיהּ לְמֵיעָאל תַּמָּן, וַהֲוָה בְּצַעֲרָא בֵּינַיְיהוּ, וְצָוַוח צַוְוחִין עַל גַּבֵּי פִּתְחָא, וּשְׁמָעוּ כּוּלְהוּ צַדִּיקַיָּיא דְּתַמָּן, וְהַשְׁתָּא הֲווֹ מִתְכַּנְּפֵי כָּל בְּנֵי מְתִיבְתֵּי, לְמֵיעָאל לְגַבֵּי מַלְכָּא מְשִׁיחָא, לְעַיְּינָא בְּדִינֵיהּ. וַאֲתֵינָא לְאוֹדָעָא לְכוּ, וְדָא חַבְרָאי אִצְטְרִיךְ לְמֵהַךְ תַּמָּן, דְּכָרוֹזָא הֲוָה אַעְבָּר בְּכָל אִינּוּן בְּנֵי מְתִיבְתֵּי. דְּלִיהֱווֹן כְּנִישִׁין הַשְׁתָּא קַמֵּי מָשִׁיחַ. נָטַל פִּתְקָא חֲדָא, וְיָהַב לְרִבִּי שִׁמְעוֹן. אָמַר, טוֹל דָּא, וְעָיֵין בְּמָה דְּתַמָּן, עַד דְּנֵיתֵי גַּבָּךְ, פַּרְחוּ תַּרְוַויְיהוּ.","וְרִבִּי שִׁמְעוֹן נָטַל פִּתְקָא, וְחָמָא מַה דְּחָמָא, בְּרָזִין דְּתַמָּן, כָּל הַהוּא יוֹמָא. בְּלֵילְיָא חָמָא שְׁרָגָא, וְנָפִיל בֵּיהּ שֵׁינָתָא, וְדָמַךְ עַד צַפְרָא. כַּד נָהָר יְמָמָא, קָם וּפָרַח הַהוּא פִּתְקָא מִנֵּיהּ, וְהָא אִינּוּן תַּרְוַויְיהוּ אַתְיָין, אָמַר לֵיהּ, קוּם רִבִּי, זַכָּאָה חוּלָקָךְ, קוּם. בְּגִינָךְ חֲמֵינָן וְזָכֵינָן לְכַמָּה סִתְרִין עִלָּאִין, כַּמָה חֶדְוָה אַחְזִיוּ לָן, כַּד יָהֲבוּ רְשׁוּ לְגַלָּאָה לָךְ, כָּל מַה דְּאַתְּ בָּעֵי. רֵישׁ מְתִיבְתָּא עִלָּאָה נָפַק לְגַבָּן, וְאָמַר, שָׁאִילוּ בִּשְׁלָמֵיהּ דְּבַר יוֹחָאי, אַתְרֵיהּ דְּבַר יוֹחָאי, הָא פָּנוּ לֵיהּ מִכַּמָּה יוֹמִין. לֵית מַאן דְּיִקְרַב לְגַבֵּיהּ, זַכָּאָה אִיהוּ.","רִבִּי רִבִּי, כַּד פָּרַחְנָא (בגינך) מִגַּבָּךְ, עָאלָנָא וַחֲמֵינָא כָּל בְּנֵי מְתִיבְתֵּי, דְּהָא מִתְכַּנְּפֵי לְגוֹ הֵיכָלָא חֲדָא, דְּמָשִׁיחַ תַּמָּן, וְדַיְינוּ דִינָא דְּהַהוּא בַּר נָשׁ, דְּקָאִים עַל פִּתְחָא, שְׁמֵיהּ לֵית לָן רְשׁוּ לְגַלָּאָה. אִצְטָעַר רִבִּי שִׁמְעוֹן עַל דָּא, אָמַר לֵיהּ, לָא תִּצְטַעָר רִבִּי עַל דָּא, אַנְתְּ תֵּדַע בְּדָא לֵילְיָא בְּחֶלְמָךְ. אֲבָל דִּינָא דַּיְינוּ עָלֵיהּ, דְּגָזַר מָשִׁיחַ, דְּלִהֱוִי הַהוּא בַּר נָשׁ לְבַר בְּהַהוּא צַעֲרָא אַרְבְּעִין יוֹמִין. לְסוֹף אַרְבְּעִין יוֹמִין, יְצַעֲרוּן לֵיהּ בְּדִינָא, בְּצַעֲרָא דְּגֵיהִנָּם, שַׁעֲתָא וּפַלְגָּא.","וְכָל דָּא, בְּגִין דְּיוֹמָא חֲדָא, חַד מִן חַבְרַיָּיא הֲוָה פָּרִישׁ מִלִּין דְּאוֹרַיְיתָא, כַּד מָטָא לְחַד מִלָּה, יָדַע הַאי בַּר נָשׁ דְּיִתְכְּשַׁל בֵּיהּ, וְאָמַר לְחַבְרַיָּיא שְׁתּוֹקוּ, לָא תֵּימְרוּן מִדִי. וּבְגִין דִּשְׁתִּיקוּ חַבְרַיָּיא אִתְכְּשַׁל בְּהַהוּא מִלָּה, וְאִכְסִיף. וְהַהוּא כִּסּוּפָא. דְּגָרִים הַאי בַּר נָשׁ, דַּיְינִין לֵיהּ בְּהַאי דִּינָא קַשְׁיָא, בְּגִין דְּלָא בָּעֵי קוּדְשָׁא בְּרִיךְ הוּא לְשַׁבְקָא חוֹבָא דְּאוֹרַיְיתָא, אֲפִילּוּ כִּמְלֹא נִימָא."],[[0,"אמרו ליה אי וכו׳:","אמרו לו אהה חסיד קדוש, כל הדברים שלנו בתורה, דברים קצרים הם בכל דבר ודבר, דהיינו שנאמרו בקיצור נמרץ, ואלו דברים קצרים, כמה הם דברים גדולים ועליונים עד שאין להם שיעור. כי אין לנו ספקות, אלא בירורה של התורה על מכונה. ועתה ביאר רב מתיבתא דברים סתומים על זה, על עיקר הנשמה, למה אינה מאירה במקום זה וזוכה להאיר במקום אחר, ועד עתה לא זכינו בהם, שהיינו צריכים לבא אליך."],[1,"ומלה אחרא זכינן וכו׳:","ודבר אחר זכינו לשמוע ממנו. רוח ההולך ערום בעולם ההוא, בלא בנים, אשתו נעשית לו כלי שהוא יבנה, דהיינו ע״י יבום. מהו הטעם. היינו, כי אשתו היא נר הנדלק ממנו, ושניהם נר אחד היו, אור זה יצא מאור זה, נתכבה זה, דהיינו שמת בלא בנים, הוא נדלק מתוך אור אשתו ממש, משום שהיו אור אחד."],[2,"השתא רבי נהדר וכו׳:","עתה רבי נחזור לדברים הראשונים שלנו. וכשנחזור למקומנו, נקבל רשות מרב מתיבתא על אלו הדברים שנקבל ממנו, ונאמר לפניך. אשרי חלקך שזכית לאורות סתומים מכל הצדדים מלמעלה ומלמטה, מעולם הזה, ומעולם האחר. אמר ר׳ שמעון דבר אחד רציתי לדעת, אם תוכלו להודיע לי. נשים בעולם ההוא, אם זוכות לעלות למעלה, או איך הן שם. אמר לו. אהה רבי, אהה רבי, יש לנו בזה סוד יקר, רק אין לגלות הסתרים משם, אבל ילך זה ויטול רשות, ונאמר לך. בתוך כך, פרח אחד ונעלם מהם, והלך לו."],[3,"ולפום שעתא תב וכו׳:","וכרגע, חזר אליהם. אמר להם, מוכן הייתי להכנס והיו כולם בעגול אחד, דהיינו שהיו יושבים בעגול, שהיו דגים דין של אדם אחד שעמד על פתח גן עדן, והכרובים אחזו בו, ולא נתנו אותו להכנס שמה, והיה בצער ביניהם, וצעק צעקות בפתח, ושמעו כל הצדיקים אשר שם. ועתה נתאספו כל בני הישיבה להכנס למלך המשיח לעיין בדינו. ובאתי להודיע לכם. וחברי זה, צריך ללכת שמה, כי כרוז עבר בין כל בני הישיבה, שיהיו מתאספים לקראת המשיח. לקח כתב אחד ונתן לר׳ שמעון, אמר קח את זה, ועיין במה שכתוב שם, עד שנבא אליך. פרחו שניהם."],[4,"ור׳ שמעון נטל וכו׳:","ור״ש לקח הכתב, וראה מה שראה בהסודות אשר שם כל אותו היום. בלילה, ראה נר, ונפל עליו שינה, וישן עד הבקר. כשהאיר היום קם ופרח אותו הכתב ממנו. והנה אלו השנים באו. א״ל, קום רבי אשרי חלקך, קום. בשבילך ראינו וזכינו לכמה סתרים עליונים. כמה שמחה הראו לנו כשנתנו לנו רשות לגלות לך כל מה שאתה רוצה. ראש הישיבה העליונה, יצא אלינו, ואמר שאלו בשלום בן יוחאי, מקומו של בן יוחאי פנוי לו מכמה ימים, אין מי שיקרב לו, אשרי הוא."],[5,"רבי רבי כד וכו׳:","רבי רבי כשפרחנו ממך, נכנסנו וראינו כל בני הישיבה, שמתאספים להיכל אחד, ששם משיח, ודנו דין של אותו האדם שעמד על הפתח, אין לנו רשות לגלות שמו. נצטער על זה ר׳ שמעון, אמר לו אל תצטער, רבי, על זה, אתה תדע זה בלילה בחלומך, אבל דין דנו עליו, שגזר משיח, שיהיה אדם ההוא בחוץ בצער הזה ארבעים יום, לסוף מ׳ יום, יצערו ליה בדין צער הגיהנם, שעה ומחצה."],[6,"וכל דא בגין וכו׳:","וכל זה הוא, משום שיום אחד, היה אחד מן החברים מפרש דברי תורה, כשהגיע לדבר אחד ידע אותו האדם שיכשל בו, ואמר לחברים שתוקו, אל תאמרו כלום, ומשום ששתקו החברים, נכשל בדבר ההוא ונתבזה. ומשום בזיון ההוא, שגרם לו האדם, דנו אותו בדין קשה, משום שאין הקב״ה רוצה לעזוב עון של תורה אפילו כמלא שערה."]],[[0,"","אָמְרוּ לוֹ, אִי חָסִיד קָדוֹשׁ, כָּל הַדְּבָרִים שֶׁבְּתוֹכֵנוּ בַּתּוֹרָה, דְּבָרִים קְטַנִּים הֵם בְּכָל דָּבָר וְדָבָר. וְאוֹתָם דְּבָרִים קְטַנִּים, כַּמָּה הֵם דְּבָרִים גְּדוֹלִים וְעֶלְיוֹנִים עַד שֶׁאֵין לָהֶם שִׁעוּר? שֶׁהֲרֵי אֵין בָּנוּ סָפֵק, אֶלָּא בֵּרוּר הַתּוֹרָה עַל בֻּרְיָהּ. וְכָעֵת רֹאשׁ הַיְשִׁיבָה פֵּרַשׁ דְּבָרִים סְתוּמִים עַל זֶה בִּגְלַל מַה שֶּׁעִקַּר הַנְּשָׁמָה לָמָּה לֹא מֵאִיר בְּמָקוֹם זֶה וְזוֹכֶה לִהְיוֹת מוּאָר בְּמָקוֹם אַחֵר? וְעַד עַתָּה לֹא זָכִינוּ בָזֶה בִּשְׁבִיל לָבֹא אֵלֶיךְ."],[1,"","וְדָבָר אַחֵר זָכִינוּ לִשְׁמֹעַ מִמֶּנּוּ: רוּחַ שֶׁהוֹלֶכֶת עֲרֻמָּה בְּאוֹתוֹ עוֹלָם בְּלִי בָנִים, אִשְׁתּוֹ תֵּעָשֶׂה כְלִי לִבְנוֹתוֹ. מָה הַטַּעַם? אִשְׁתּוֹ הִיא נֵר שֶׁנִּדְלֶקֶת מִמֶּנּוּ, וּשְׁנֵיהֶם נֵר אֶחָד הָיוּ, אוֹר זֶה יוֹצֵא מֵאוֹר זֶה. דָּעַךְ זֶה, נִדְלָק מִתּוֹךְ אוֹרוֹ מַמָּשׁ, מִשּׁוּם שֶׁהָיוּ אוֹר אֶחָד."],[2,"","כָּעֵת, רַבִּי, נַחֲזֹּר לַדְּבָרִים הָרִאשׁוֹנִים, וּכְשֶׁנַּחֲזֹר לִמְקוֹמֵנוּ נִטֹּל רְשׁוּת מֵרֹאשׁ הַיְשִׁיבָה בְּאוֹתָם דְּבָרִים שֶׁנְּקַבֵּל מִמֶּנּוּ, וְנֹאמַר לְפָנֶיךְ. אַשְׁרֵי חֶלְקְךְ שֶׁאַתָּה זוֹכֶה לְאוֹרוֹת נִסְתָּרִים מִכָּל הַצְּדָדִים מִלְמַעְלָה וּמִלְּמַטָּה מֵהָעוֹלָם הַזֶּה וּמֵעוֹלָם אַחֵר. אָמַר רַבִּי שִׁמְעוֹן, דָּבָר אֶחָד רָצִיתִי לָדַעַת, אִם תּוּכַל לְהוֹדִיעַ לִי. נָשִׁים בְּאוֹתוֹ עוֹלָם אִם זַכָּאִיּוֹת לַעֲלוֹת לְמַעְלָה, אוֹ אֵיךְ הֵן שָׁם? אָמַר לוֹ, אִי רַבִּי אִי רַבִּי, בָּזֶה יֵשׁ לָנוּ סוֹד יָתֵר (נכבד) כְּדֵי לֹא לְגַלּוֹת סוֹדוֹת שֶׁל שָׁם, אֲבָל זֶה יֵלֵךְ וְיִטֹּל רְשׁוּת, וְנֹאמַר לְךְ. בֵּין כָּךְ פָּרַח אֶחָד וְהִתְכַּסָּה מֵהֶם וְהָלַךְ לוֹ."],[3,"","וּלְפִי שָׁעָה שָׁב אֲלֵיהֶם. אָמַר לָהֶם, עָתִיד הָיִיתִי לְהִכָּנֵס, וְהָיוּ כֻלָּם בְּעִטּוּר אֶחָד, שֶׁדָּנוּ דִין בֶּן אָדָם אֶחָד שֶׁעָמַד עַל פֶּתַח הַגַּן עֵדֶן, וְאוֹתָם כְּרוּבִים אָחֲזוּ בוֹ, וְלֹא נָתְנוּ אוֹתוֹ לְהִכָּנֵס שָׁם, וְהָיָה בְצַעַר בֵּינֵיהֶם, וְצָוַח צְוָחוֹת עַל גַּבֵּי הַפֶּתַח, וְשָׁמְעוּ כָּל הַצַּדִּיקִים שֶׁשָּׁם, וְכָעֵת הָיוּ מִתְכַּנְּסִים כָּל בְּנֵי הַיְשִׁיבָה לְהִכָּנֵס אֶל מֶלֶךְ הַמָּשִׁיחַ לְעַיֵּן בְּדִינוֹ. וּבָאתִי לְהוֹדִיעַ לָכֶם, וְזֶה חֲבֵרִי הִצְטָרֵךְ לָלֶכֶת לְשָׁם, שֶׁכָּרוֹז הָעֳבַר בְּכָל אוֹתָם בְּנֵי הַיְשִׁיבוֹת שֶׁיִּהְיוּ מִתְכַּנְּסִים כָּעֵת לִפְנֵי הַמָּשִׁיחַ. לָקַח פִּתְקָה אַחַת וְנָתַן לְרַבִּי שִׁמְעוֹן. אָמַר, קַח אֶת זֶה וְעַיֵּן בְּמַה שֶּׁשָּׁם עַד שֶׁנָּבֹא אֵלֶיךְ. וּפָרְחוּ שְׁנֵיהֶם."],[4,"","וְרַבִּי שִׁמְעוֹן לָקַח הַפִּתְקָה וְרָאָה מַה שֶּׁרָאָה בַּסּוֹדוֹת שֶׁשָּׁם כָּל אוֹתוֹ יוֹם. בַּלַּיְלָה רָאָה נֵר, וְנָפְלָה עָלָיו שֵׁנָה, וְנִרְדַּם עַד הַבֹּקֶר. כְּשֶׁהֵאִיר הַיּוֹם קָם, וּפָרְחָה אוֹתָהּ פִּתְקָה מִמֶּנּוּ, וְהִנֵּה שְׁנֵיהֶם בָּאִים. אָמַר לוֹ, עֲמֹד רַבִּי, אַשְׁרֵי חֶלְקְךְ. עֲמֹד. בִּגְלָלְךְ רָאִינוּ וְזָכִינוּ לְכַמָּה סְתָרִים עֶלְיוֹנִים, כַּמָּה חֶדְוָה הֶרְאוּ לָנוּ כְּשֶׁנָּתְנוּ רְשׁוּת לְגַלּוֹת לְךְ כָּל מַה שֶּׁאַתָּה רוֹצֶה. רֹאשׁ הַיְשִׁיבָה הָעֶלְיוֹנָה יָצָא אֵלֵינוּ וְאָמַר: שַׁאֲלוּ בִשְׁלוֹם בַּר יוֹחַאי, מְקוֹמוֹ שֶׁל בַּר יוֹחַאי הֲרֵי פָּנוּי לוֹ מִכַּמָּה יָמִים, אֵין מִי שֶׁיִּקְרַב אֵלָיו, אַשְׁרָיו!"],[5,"","רַבִּי רַבִּי, כְּשֶׁפָּרַחְנוּ מִמְּךְ (בשבילך), נִכְנַסְנוּ וְרָאִינוּ כָּל בְּנֵי הַיְשִׁיבוֹת שֶׁהֲרֵי מִתְכַּנְּסִים לְתוֹךְ הֵיכָל אֶחָד שֶׁשָּׁם הַמָּשִׁיחַ, וְדָנוּ דִין שֶׁל אוֹתוֹ אָדָם שֶׁעָמַד עַל הַפֶּתַח, שֶׁשְּׁמוֹ אֵין לָנוּ רְשׁוּת לְגַלּוֹת. הִצְטַעֵר רַבִּי שִׁמְעוֹן עַל זֶה. אָמַר לוֹ, אַל תִּצְטַעֵר רַבִּי עַל זֶה, אַתָּה תֵּדַע בַּלַּיְלָה הַזֶּה בַּחֲלוֹמְךְ. אֲבָל דִּין דָּנוּ עָלָיו, שֶׁגָּזַר מָשִׁיחַ שֶׁיִּהְיֶה אוֹתוֹ אָדָם בַּחוּץ בְּאוֹתוֹ צַעַר אַרְבָּעִים יוֹם, וּלְסוֹף אַרְבָּעִים יוֹם יְצַעֲרוּ אוֹתוֹ בְּדִין בְּצַעַר הַגֵּיהִנֹּם שָׁעָה וָחֵצִי."],[6,"","וְכָל זֶה מִשּׁוּם שֶׁיּוֹם אֶחָד אֶחָד מִן הַחֲבֵרִים הָיָה מְפָרֵשׁ דִּבְרֵי תוֹרָה, וּכְשֶׁהִגִּיעַ לְדָבָר אֶחָד, יָדַע הָאָדָם הַזֶּה שֶׁיִּכָּשֵׁל בּוֹ, וְאָמַר לַחֲבֵרִים: שִׁתְקוּ, אַל תֹּאמְרוּ דָבָר. וּמִשּׁוּם שֶׁשָּׁתְקוּ הַחֲבֵרִים, נִכְשַׁל בְּאוֹתוֹ דָּבָר וְהִתְבַּיֵּשׁ. וְעַל אוֹתָהּ בּוּשָׁה שֶׁגָּרַם אָדָם זֶה, דַּנוּ אוֹתוֹ בַּדִּין הַזֶּה הַקָּשֶׁה, מִשּׁוּם שֶׁלֹּא רוֹצֶה הַקָּדוֹשׁ בָּרוּךְ הוּא לְהַשְׁאִיר עֲווֹן הַתּוֹרָה אֲפִלּוּ כִּמְלֹא נִימָה."]]],[["דַּיְינוּ דִּינֵיהּ, וְנַפְקוּ כָּל בְּנֵי מְתִיבְתָּא. וַאֲנָא שָׁאִילְנָא רְשׁוּ, דְּהָא בְּרֵיהּ דְּיוֹחָאי, שָׁאִיל שְׁאֶלְתָּא דָּא. וְעַל דָּא אַחְזִיוּ לִי, מַה דְּלָא יְדַעְנָא מִקַּדְמַת דְּנָא. אִי רִבִּי, שִׁית הֵיכָלִין אַחְזִיוּ לִי, בְּכַמָּה עִנּוּגִין וְעִדּוּנִין, בַּאֲתָר דְּפָרוֹכְתָּא פְּרִישָׁא בְּגִנְתָּא. דְּהָא מֵהַהוּא פָּרוֹכְתָּא וּלְהָלְאָה, לָא עָאלִין דְּכוּרִין כְּלַל.","בְּהֵיכָלָא חֲדָא, אִית בַּתְיָה בַּת פַּרְעֹה, וְכַמָּה רִבּוֹא וְאַלְפֵי נָשִׁין, זַכְיָין בַּהֲדָהּ, וְכָל חֲדָא וַחֲדָא מִנַּיְיהוּ, דּוּכְתִּין דִּנְהוֹרִין וְעִדּוּנִין, בְּלָא דֹּחֲקָא כְּלָל אִית לָהּ. תְּלַת זִמְנִין בְּכָל יוֹמָא, כָּרוֹזֵי אַכְרִיזוּ, הָא דִּיּוּקְנָא דְּמֹשֶׁה נְבִיאָה מְהֵימָנָא אָתֵי, וּבַתְיָה נַפְקַת, לַאֲתָר דְּפַרְגּוֹדָא חֲדָא דְּאִית לָהּ, וְחָמָאת דִּיּוּקְנָא דְּמֹשֶׁה, וְסָגִידַת לְגַבֵּיהּ, וְאָמְרָה, זַכָּאָה חוּלָקִי דְּרָבִיתִי נְהִירוּ דָּא. וְדָא אִיהוּ עִנּוּגִין דִּילָהּ, יַתִּיר מְכֻּלְּהוּ.","אַהֲדְרַת לְגַבֵּי נָשִׁין, וְאִשְׁתַּדְּלָן בְּפִקּוּדֵי אוֹרַיְיתָא. כֻּלְּהוּ בְּאִינּוּן דִּיוּקְנִין דַּהֲווֹ בְּהַאי עָלְמָא, בִּלְבוּשָׁא דִּנְהוֹרָא, (ס\"א כלבושא) בִּלְבוּשָׁא דִּדְכוּרִין, בַּר דְּלָא נַהֲרֵי הָכִי, פִּקוּדִין דְּאוֹרַיְיתָא דְּלָא זָכוּ לְקַיְּימָא לוֹן בְּהַאי עָלְמָא, מִשְׁתַּדְּלֵי בְּהוּ, וּבְטַעְמַיְיהוּ, בְּהַהוּא עָלְמָא. וְכָל הָנֵי נָשִׁין, דְּיַתְבִין בַּהֲדֵי בַּתְיָה בַּת פַּרְעֹה, אִקְרוּן נָשִׁים שַׁאֲנַנּוֹת, דְּלָא אִצְטַעְרוּ בְּצַעֲרָא דְּגֵיהִנָּם כְּלַל.","בְּהֵיכָלָא אַחֲרָא, אִית סֶרַח בַּת אָשֵׁר, וְכַמָה נָשִׁין רִבּוֹא וְאַלְפִין בַּהֲדָהּ. תְּלַת זִמְנִין בְּיוֹמָא מַכְרִיזִין קַמֵּה, הָא דִּיּוּקְנָא דְּיוֹסֵף צַדִּיקָא אָתָא, וְאִיהִי חַדָּאת, וְנַפְקַת לְגַבֵּי פַּרְגּוֹדָא חֲדָא דְּאִית לָהּ, וְחָמָאת נְהִירוּ דְּדִיּוּקְנָא דְּיוֹסֵף, וְחַדָּאת, וְסָגִידַת לְגַבֵּיהּ, וְאָמָרְת, זַכָּאָה הַאי יוֹמָא, דְּאִתְּעָרִית בְּשׂוֹרָה דִּילָךְ לְגַבֵּי סָבָאי. לְבָתַר אַהֲדְרַת לְגַבֵּי שְׁאַר נָשִׁין, וּמִשְׁתַּדְּלִין בְּתוּשְׁבְּחָן דְּמָארֵי עָלְמָא, וּלְאוֹדָאָה שְׁמֵיהּ. וְכַמָּה דּוּכְתִּין וְחֵידוּ, אִית לְכָל חֲדָא וַחֲדָא. וּלְבָתַר אֲהְדְרָן לְאִשְׁתַּדְּלָא בְּפִקּוּדֵי אוֹרַיְיתָא, וּבְטַעְמַיְיהוּ.","בְּהֵיכָלָא אַחֲרָא, אִית יוֹכֶבֶד, אִמֵּיהּ דְּמֹשֶׁה נְבִיאָה מְהֵימָנָא, וְכַמָּה אַלְפִין וְרִבְּבָן בַּהֲדָהּ. בְּהֵיכָלָא דָּא, לָא מַכְרְזֵי כְּלַל, אֶלָּא ג' זִמְנִין בְּכָל יוֹמָא וְיוֹמָא, אוֹדֵת וּמְשַׁבָּחַת לְמָארֵי עָלְמָא, אִיהִי וְכָל אִינּוּן נָשִׁין דִּי בַּהֲדָהּ. וְשִׁירָתָא דְּיַמָּא מְזַמְּרִין בְּכָל יוֹמָא, וְאִיהִי בִּלְחוֹדָהָא אַמְרַת מֵהָכָא, (שמות ט״ו:כ׳) וַתִּקַּח מִרְיָם הַנְּבִיאָה וְגוֹ', אֶת הַתּוֹף בְּיָדָהּ וְגוֹ'. וְכָל אִינּוּן צַדִּיקַיָּיא דִּי בְגַן עֵדֶן, צַיְיתִין לַקָל נְעִימוּ דִּילָהּ. וְכַמָּה מַלְאֲכִין קַדִּישִׁין אוֹדָאן וּמְשַׁבְּחָן עִמָּהּ לִשְׁמָא קַדִּישָׁא.","בְּהֵיכָלָא אַחֲרָא, אִית דְּבוֹרָה, אוּף הָכִי וְכָל שְׁאַר נָשִׁין בַּהֲדָהּ, אוֹדָן וּמְזַמְּרָן בְּהַהִיא שִׁירָתָא דְּאִיהִי אַמְרַת בְּהַאי עָלְמָא. אִי רִבִּי, אִי רִבִּי, מַאן חָמֵי חֶדְוָה דְּצַדִּיקַיָּיא, וּדְנָשִׁין זַכְיָין דְּעַבְדִּין לְגַבֵּי קוּדְשָׁא בְּרִיךְ הוּא. לְגוֹ לְגוֹ דְּאִינּוּן הֵיכָלִין, אִית אַרְבַּע הֵיכָלִין טְמִירִין, דְּאִמָּהָן קַדִּישִׁין דְּלָא אִתְמַסְרָן לְאִתְגַּלָּאָה, וְלֵית מַאן דְּחָמֵי לוֹן. בְּכוּלֵיהּ יוֹמָא אִינּוּן בִּלְחוֹדֵיהוֹן, כְּמָה דַּאֲמֵינָא לְךָ, וְגוּבְרִין אוּף הָכִי.","וּבְכָל לֵילְיָא אִתְכְּלִילָן כֻּלְּהוּ כַּחֲדָא, בְּגִין דְּשַׁעְתָּא דְּזִוּוּגָא אִיהוּ בְּפַלְגוּת לֵילְיָא, בֵּין בְּהַאי עָלְמָא, בֵּין בְּהַהוּא עָלְמָא. זִוּוּגָא דְּהַהוּא עָלְמָא, אִתְדַּבְּקוּתָא דְּנִשְׁמְתָא בְּנִשְׁמְתָא נְהוֹרָא בִּנְהוֹרָא. זִוּוּגָא דְּהַאי עָלְמָא, גּוּפָא בְּגוּפָא. וְכֹלָּא כְּמָה דְּאִתְחֲזֵי, זִינָא בָּתַר זִינֵיהּ, זִוּוּגָא בָּתַר זִוּוּגָא, גּוּפָא בָּתַר גּוּפָא, זִוּוּגָא דְּהַהוּא עָלְמָא, נְהוֹרָא בָּתַר נְהוֹרָא. הֵיכָלִין דְּאַרְבַּע אִמָּהָן, אִקְרוּן הֵיכָלִין דְּבָנוֹת בּוֹטְחוֹת. וְלָא זָכֵינָא בְּהוּ לְמֵחמֵי. זַכָּאָה חוּלָקֵיהוֹן דְּצַדִּיקַיָּיא, גּוּבְרִין וְנוּקְבֵי דְּאַזְלֵי בְּאֹרַח מֵישָׁר בְּהַאי עָלְמָא, וְזַכָּאִין לְכֻלְּהוּ עִנּוּגִין דְּהַהוּא עָלְמָא."],[[0,"דיינו דיניה ונפקו וכו׳:","דנו דיניה ויצאו כל בני הישיבה. ואני שאלתי רשות כי בנו של יוחאי שאל שאלה זו. וע״כ הראו לי מה שלא ידעתי מקודם לכן. אהה רבי, ששה היכלות הראו לי, בכמה תענוגים ועדונים, במקום שהפרוכת פרושה בגן, כי מפרוכת ההיא ולהלאה, אין זכרים נכנסים כלל."],[1,"בהיכלא חדא איה וכו׳:","בהיכל אחד יש בתיה בת פרעה, וכמה רבבות ואלפים נשים צדקניות עמה, וכל אחת ואחת מהן יש לה מקומות אור ועדונים בלי דוחק כלל. ג' פעמים בכל יום כרוזים מכריזים הנה הצורה של משה הנביא הנאמן באה. ובתיה יוצאת למקום מחיצה אחת שיש לה, ורואית צורת משה, ומשתחוה לפניו, ואומרת אשרי חלקי, שגדלתי אור הזה. וזה הוא התענוג המיוחד שלה יותר מכולן."],[2,"אהדרת לגבי נשין וכו׳:","בתיה חוזרת אל הנשים, ועוסקות במצות התורה. כולן הן בצורות שהיו בעולם הזה בלבוש אור, כמו לבושי הזכרים, חוץ מה שאינם מאירים כל כך כלבושי הזכרים. מצות התורה שלא זכו לקיים אותן בעולם הזה, הן עוסקות בהן ובטעמיהן בעולם ההוא. וכל אלו הנשים היושבות עם בתיה בת פרעה בהיכל אחד, נקראות נשים שאננות. שלא נצטערו כלל בצער הגיהנם."],[3,"בהיכלא אחרא וכו׳:","בהיכל אחר יש סרח בת אשר, וכמה נשים רבבות ואלפים עמה. ג׳ פעמים ביום מכריזים לפניה, הנה צורת יוסף הצדיק באה. והיא שמחה ויוצאת למחיצה אחת שיש לה, ורואית אור צורת יוסף, ושמחה ומשתחוית אליו, ואומרת אשרי אותו יום שהערתי הבשורה שלך אל זקני. ואח״כ חוזרת אל שאר הנשים, ועוסקות בתשבחות לרבון העולם, ולהודות לשמו. וכמה מקומות ושמחה יש לכל אחת ואחת. ואח״כ חוזרות לעסוק במצות התורה ובטעמיהן."],[4,"בהיכלא אחרא אית וכו׳:","בהיכל אחר יש יוכבד אמו של משה הנביא הנאמן, וכמה אלפים ורבבות עמה. בהיכל זה אין מכריזים כלל, אלא ג׳ פעמים בכל יום ויום היא מודית ומשבחת לרבון העולם, היא וכל אלו הנשים שעמה. ומזמרות שירת הים בכל יום, והיא לבדה מתחלת מכאן, ותקח מרים הנביאה וגו׳ את התוף בידה וגו׳. וכל אלו הצדיקים שבגן העדן, מקשיבים לקול נעימות שלה. וכמה מלאכים קדושים מודים ומשבחים עמה לשם הקדוש."],[5,"בהיכלא אחרא וכו׳:","בהיכל אחר יש דבורה הנביאה, וגם כן, כל הנשים שעמה מודות ומזמרות בשירה ההיא שהיא אמרה בעולם הזה. אהה רבי, אהה רבי, מי ראה שמחת הצדיקים ונשים צדקניות העובדים להקב״ה. לפני ולפנים של אלו ההיכלות, יש ארבעה היכלות נסתרים של האמהות הקדושות, שלא נמסרו לגלות. ואין מי שראה אותן. בכל יום הן בלבדן כמו שאמרתי לך והגברים ג״כ לבדם."],[6,"ובכל ליליא אתכלילן וכו׳:","ובכל לילה מתכללים כולם יחד. משום ששעת הזווג הוא בחצות לילה, בין בעולם הזה ובין בעולם ההוא. הזווג של עולם ההוא, הוא התדבקות הנשמה בנשמה, אור באור. הזווג של עוה״ז, הוא גוף בגוף. והכל כמו שראוי, מין אחר מינו, זווג אחר זווג, גוף אחר גוף, הוא בעולם הזה, והזווג של עולם ההוא, הוא אור אחר אור. ההיכלות של ארבע אמהות נקראים היכלות של בנות בוטחות. ולא זכיתי לראות בהם. אשרי חלקם של צדיקים גברים ונקבות ההולכים בדרך הישר בעולם הזה, וזוכים לכל התענוגים שבעולם ההוא."]],[[0,"","דָּנוּ דִינוֹ, וְיָצְאוּ כָּל בְּנֵי הַיְשִׁיבָה, וַאֲנִי שָׁאַלְתִּי רְשׁוּת, שֶׁהֲרֵי בַּר יוֹחַאי שָׁאַל שְׁאֵלָה זוֹ. וְעַל זֶה הֶרְאוּ לִי מַה שֶּׁלֹּא יָדַעְתִּי מִלִּפְנֵי כֵן. אִי רַבִּי, שִׁשָּׁה הֵיכָלוֹת הֶרְאוּ לִי, בְּכַמָּה עִנּוּגִים וְעִדּוּנִים, בְּמָקוֹם שֶׁפָּרֹכֶת פְּרוּשָׂה בַּגִּנָּה. שֶׁהֲרֵי מֵאוֹתָהּ פָּרֹכֶת וּלְהָלְאָה לֹא נִכְנָסִים זְכָרִים כְּלָל."],[1,"","בְּהֵיכָל אֶחָד יֵשׁ בַּתְיָה בַּת פַּרְעֹה, וְכַמָּה רִבּוֹא וְאַלְפֵי נָשִׁים זוֹכוֹת אִתָּהּ, וּלְכָל אַחַת וְאַחַת מֵהֶן יֵשׁ מְקוֹמוֹת שֶׁל אוֹרוֹת וְעִדּוּנִים לְלֹא דחַק כְּלָל. שָׁלֹשׁ פְּעָמִים בְּכָל יוֹם הַכָּרוֹזוֹת מַכְרִיזִים: הֲרֵי דְּמוּת מֹשֶׁה נָבִיא הַנֶּאֱמָן בָּאָה! וּבַתְיָה יוֹצֵאת לִמְקוֹם פַּרְגּוֹד אֶחָד שֶׁיֵּשׁ לָהּ, וְרוֹאָה דְמוּת מֹשֶׁה וּמִשְׁתַּחֲוָה אֵלָיו, וְאוֹמֶרֶת: אַשְׁרֵי חֶלְקִי שֶׁגִּדַּלְתִּי אוֹר זֶה. וְזֶה עִנּוּגִים שֶׁלָּהּ יוֹתֵר מִכֻּלָּם."],[2,"","חוֹזֶרֶת לַנָּשִׁים וּמִשְׁתַּדֶּלֶת בְּמִצְווֹת הַתּוֹרָה. כֻּלָּן בְּאוֹתָן דְּמֻיּוֹת שֶׁהָיוּ בָּעוֹלָם הַזֶּה בִּלְבוּשׁ אוֹר, (כלבוש) בִּלְבוּשׁ הַזְּכָרִים, פְּרָט שֶׁלֹּא מְאִירִים כָּךְ, מִצְווֹת הַתּוֹרָה שֶׁלֹּא זָכוּ לְקַיְּמָן בָּעוֹלָם הַזֶּה, מִשְׁתַּדְּלוֹת בָּהֶן וּבְטַעֲמֵיהֶן בְּאוֹתוֹ עוֹלָם. וְכָל הַנָּשִׁים הַלָּלוּ שֶׁיּוֹשְׁבוֹת יַחַד עִם בַּת פַּרְעֹה נִקְרָאוֹת (ישעיה לב) נָשִׁים שַׁאֲנַנּוֹת, שֶׁלֹּא הִצְטַעֲרוּ כְלָל בְּצַעַר הַגֵּיהִנֹּם."],[3,"","בְּהֵיכָל אַחֵר יֵשׁ סֶרַח בַּת אָשֵׁר, וְכַמָּה נָשִׁים רִבּוֹא וַאֲלָפִים יַחַד אִתָּהּ. שָׁלֹשׁ פְּעָמִים בְּיוֹם מַכְרִיזִים לְפָנֶיהָ: הֲרֵי דְּמוּת יוֹסֵף הַצַּדִּיק בָּאָה! וְהִיא שְׂמֵחָה וְיוֹצֵאת לְגַבֵּי פַרְגּוֹד אֶחָד שֶׁיֵּשׁ לָהּ, וְרוֹאָה אוֹר דְּמוּת יוֹסֵף, וּשְׂמֵחָה, וּמִשְׁתַּחֲוָה אֵלָיו וְאוֹמֶרֶת: אַשְׁרֵי הַיּוֹם שֶׁעוֹרַרְתִּי בְשׂוֹרָתְךְ לְסָבִי. אַחַר כָּךְ חוֹזֶרֶת לִשְׁאָר הַנָּשִׁים, וּמִשְׁתַּדְּלוֹת בְּתִשְׁבְּחוֹת רִבּוֹן הָעוֹלָם וּלְהוֹדוֹת לִשְׁמוֹ. וְכַמָּה מְקוֹמוֹת וְשִׂמְחָה יֵשׁ לְכָל אַחַת וְאַחַת. אַחַר כָּךְ חוֹזְרוֹת לְהִשְׁתַּדֵּל בְּמִצְווֹת הַתּוֹרָה וּבְטַעֲמֵיהֶן."],[4,"","בְּהֵיכָל אַחֵר יֵשׁ יוֹכֶבֶד אֵם מֹשֶׁה נָבִיא הַנֶּאֱמָן, וְכַמָּה אֲלָפִים וּרְבָבוֹת עִמָּהּ. בְּהֵיכָל זֶה לֹא מַכְרִיזִים כְּלָל, אֶלָּא שָׁלֹשׁ פְּעָמִים בְּכָל יוֹם וָיוֹם מוֹדָה וּמְשַׁבַּחַת לְרִבּוֹן הָעוֹלָם הִיא וְכָל הַנָּשִׁים שֶׁאִתָּהּ. וְשִׁירַת הַיָּם מְזַמְּרוֹת בְּכָל יוֹם, וְהִיא לְבַדָּהּ אוֹמֶרֶת מִכָּאן, (שמות טו) וַתִּקַּח מִרְיָם הַנְּבִיאָה וְגוֹ', אֶת הַתֹּף בְּיָדָהּ וְגוֹ'. וְכָל אוֹתָם צַדִּיקֵי גַּן עֵדֶן מַקְשִׁיבִים לִנְעִימוּת קוֹלָהּ, וְכַמָּה מַלְאָכִים קְדוֹשִׁים מוֹדִים וּמְשַׁבְּחִים עִמָּהּ לַשֵּׁם הַקָּדוֹשׁ."],[5,"","בְּהֵיכָל אַחֵר יֵשׁ דְּבוֹרָה, גַּם כָּךְ וְכָל שְׁאָר הַנָּשִׁים אִתָּהּ מוֹדוֹת וּמְזַמְּרוֹת בְּאוֹתָהּ שִׁירָה שֶׁהִיא אָמְרָה בָּעוֹלָם הַזֶּה. אִי רַבִּי, אִי רַבִּי, מִי רָאָה חֶדְוַת הַצַּדִּיקִים וְשֶׁל נָשִׁים זַכָּאִיּוֹת שֶׁעוֹשׂוֹת לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא. לִפְנַי וְלִפְנִים שֶׁל אוֹתָם הֵיכָלוֹת יֵשׁ אַרְבָּעָה הֵיכָלוֹת טְמִירִים שֶׁל הָאִמָּהוֹת הַקְּדוֹשׁוֹת שֶׁלֹּא נִמְסָר לְהִגָּלוֹת, וְאֵין מִי שֶׁרוֹאֶה אוֹתָן. בְּכָל הַיּוֹם הֵן לְבַדָּן, כְּמוֹ שֶׁאָמַרְתִּי לְךְ, וְהַגְּבָרִים גַּם כֵּן."],[6,"","וּבְכָל לַיְלָה נִכְלָלִים כֻּלָּם כְּאֶחָד, מִשּׁוּם שֶׁשְּׁעַת הַזִּוּוּג הִיא בַּחֲצוֹת הַלַּיְלָה, בֵּין בָּעוֹלָם הַזֶּה וּבֵין בָּעוֹלָם הַבָּא. זִוּוּג אוֹתוֹ עוֹלָם - הִתְדַבְּקוּת נְשָׁמָה בִּנְשָׁמָה, אוֹר בְּאוֹר. זִוּוּג הָעוֹלָם הַזֶּה - גּוּף בְּגוּף. וְהַכֹּל כְּמוֹ שֶׁרָאוּי, מִין אַחַר מִינוֹ, זִוּוּג אַחַר זִוּוּג, גּוּף אַחַר גּוּף, זִוּוּג אוֹתוֹ עוֹלָם אוֹר אַחַר אוֹר. הֵיכְלֵי אַרְבַּע הָאִמָּהוֹת נִקְרָאִים הֵיכָלוֹת שֶׁל בָּנוֹת בּטְחוֹת (ישעיה לב), וְלֹא זָכִינוּ בָהֶם לִרְאוֹת. אַשְׁרֵי חֵלֶק הַצַּדִּיקִים, גְּבָרִים וּנְקֵבוֹת שֶׁהוֹלְכִים בְּדֶרֶךְ יָשָׁר בָּעוֹלָם הַזֶּה, וְזַכָּאִים לְכָל הָעִנּוּגִים שֶׁל אוֹתוֹ עוֹלָם."]]],[["אִי רִבִּי, אִי רִבִּי, אִלְמָלֵא בַּר יוֹחָאי אַנְתְּ, לָא אִתְמְסַר לְגַלָּאָה. זִוּוּגָא דְּהַהוּא עָלְמָא, אִתְעָבִיד אִיבָּא יַתִּיר, מֵאִיבָא דְּאִתְעָבִיד בְּהַאי עָלְמָא. בְּזִוּוּגָא דִּלְהוֹן, בְּזִוּוּגָא דְּהַהוּא עָלְמָא, בְּתִיאוּבְתָּא דִּלְהוֹן כַּחֲדָא, כַּד מִתְדַּבְּקָן נִשְׁמָתִין דָּא עִם דָּא, עַבְדֵי אֵיבִין, וְנַפְקֵי נְהוֹרִין מִנַּיְיהוּ, וְאִתְעַבְדֵי שְׁרָגִּין. וְאִינּוּן נִשְׁמָתִין, לַגִּיּוֹרִין דְּמִתְגַּיְירִין, וְכָל הָנֵי עַיְילִין לְהֵיכָלָא חֲדָא.","וְכַד מִתְגַּיְירָא גִּיּוֹרָא חֲדָא, פַּרְחָא מֵהַהוּא הֵיכָלָא נִשְׁמְתָא, וְעָאלַת תְּחוֹת גַּדְפָהָא דִּשְׁכִינְתָּא, וְנַשְׁקַת לָּהּ, בְּגִין דְּאִיהוּ אִיבָּא דְּצַדִּיקַיָּיא, וּמְשַׁדְרַת לָהּ לְגוֹ הַהוּא גִּיּוֹרָא, וְשָׁרַאת בֵּיהּ. וּמֵהַהוּא זִמְנָא, אִקְרֵי גֵּר צֶדֶק. וְהַיְינוּ רָזָא דִּכְתִּיב, (משלי י״א:ל׳) פְּרִי צַדִּיק עֵץ חַיִּים. מַה אִילָנָא דְּחַיֵּי אַפִּיק נִשְׁמָתִין, אוּף הָכִי צַדִּיק, אִיבָּא דִּילֵיהּ עָבִיד נִשְׁמָתִין.","רַב מְתִיבְתָּא אָמַר, כְּתִיב (בראשית י״א:ל׳) וַתְּהִי שָׂרַי עֲקָרָה אֵין לָהּ וָלָד. מִמַּאי דְּאָמַר וַתְּהִי שָׂרַי עֲקָרָה, לֵית אֲנָא יוֹדֵעַ דְּלֵית לָהּ וָלָד, מַאי אֵין לָהּ וָלָד. אֶלָּא הָכִי אָמַר רַב מְתִיבְתָּא, וָלָד לָא הֲוַת מוֹלִדָא, אֲבָל נִשְׁמָתִין הֲוַת מוֹלִדָא בְּאִתְדַּבְּקוּתָא דְּתִיאוּבְתָא, דְּאִינּוּן תְּרֵין זַכָּאִין הֲווֹ מוֹלִידֵי נִשְׁמָתִין לְגִיּוֹרֵי כָּל הַהוּא זִמְנָא דַּהֲווֹ בְחָרָן. כְּמָה דְּעַבְדִּין צַדִּיקַיָּיא בְּגַן עֵדֶן. כְּמָה דִּכְתִּיב, (בראשית י״ב:ה׳) וְאֶת הַנֶּפֶשׁ אֲשֶׁר עָשׂוּ בְחָרָן, נֶפֶשׁ עָשׂוּ וַדַּאי.","חַדֵּי רַבִּי שִׁמְעוֹן, אָמַר לֵיהּ הַהוּא גַּבְרָא, אִי רִבִּי, מָה אֵימָא לְךָ, בְּכָל רֵישׁ יַרְחֵי וְשַׁבַּתֵּי וּמוֹעֲדַיָּיא וּזְמָנַיָּיא, אִינּוּן דְּכוּרִין סַלְּקִין לְאִתְחֲזָאָה קַמֵּי מַלְכָּא קַדִּישָׁא, דְּכוּרִין וְלָא נוּקְבִין, כְּמָה דְאַתְּ אָמֵר (שמות כ״ג:י״ז) יֵרָאֶה כָּל זְכוּרְךָ. וְכַד אַהְדְּרָן מְהַדְרָן בְּכַמָּה מִלֵּי חַדְתִּין, וְאַהְדְּרָן מִלִּין קַמֵּי רַב מְתִיבְתָּא.","יוֹמָא דָּא אַהְדְּרָן מִלִּין חַדְתִּין קַמֵּי רַב מְתִיבְתָּא, עַל רָזִין עַתִּיקִין, צַדִּיק וְטוֹב לוֹ, צַדִּיק וָרָע לוֹ. דְּכֻלְּהוּ סַלְּקִין גּוֹ מַתְקְלָא דְּאִילָנָא, עַד לָא יֵיתוּן לְעָלְמָא, וּכְפוּם טַקְלָא דְּמַתְקְלָא, הָכִי אִית לוֹן בְּהַאי עָלְמָא. רַב מְתִיבְתָּא, נָחִית וְגַלֵּי מִמָּה דְּשָׁמַע לְעֵילָּא, מִלָּה חֲדָא גַּלֵּי וְלָא יַתִּיר. אָעָא דְּלָא סָלִיק נְהוֹרֵיהּ, יְבָטְשׁוּן בֵּיהּ וְאַנְהִיר. גּוּפָא דְּלָא סַלְּקָא בֵּיהּ נְהוֹרָא דְּנִשְׁמְתָא, יְבָטְשׁוּן בֵּיהּ, וִיסַלֵק נְהִירוּ דְּנִשְׁמְתָא, וְיִתְאַחֲדוּן דָּא בְּדָא לְאַנְהָרָא. (תרי נוסחי)","בְּגִין דְּאִית גּוּפָא דִּנְהִירוּ דְּנִשְׁמְתָא לָא נָהִיר בֵּיהּ, עַד דִּיבַטְּשׁוּן בֵּיהּ, כְּדֵין נָהִיר נְהִירוּ דְּנִשְׁמְתָא, וְאִתְאֲחָדָת בְּגוּפָא, וְגוּפָא אִתְאֲחָד בָּהּ. גּוּפָא כְּדֵין סָלִיק נְהִירוּ מִגּוֹ נִשְׁמְתָא, מְהַדַּר מְרוֹמַם וּמְשַׁבַּח, מְצַלֵּי צְלוֹתֵיהּ וּבָעוּתֵיהּ, מְבָרֵךְ לְמָארֵיהּ, הָא כְּדֵין כֹּלָּא נָהִיר. בְּגִין דְּאִית גּוּפָא, דְּלָא יָכִילַת נִשְׁמְתָא לְאַנְהָרָא בֵּיהּ, עַד דִּיבַטְּשׁוּן בֵּיהּ, וּכְדֵין נָהִיר וְאִתְאֲחָד דָּא בְּדָא. אִית אָעָא דְּלָא אִתְאֲחָד בִּנְהוֹרָא, וְלָא סָלִיק נְהוֹרָא בֵּיהּ, עַד דִּיבַטְּשׁוּן בֵּיהּ, וּכְדֵין נָהִיר.","סִטְרָא אַחֲרָא, בָּעֵי לְמֶעְבַּד הָכִי, וּבָטַשׁ בְּחַיָּיבַיָּא, וְכָל מַה דְּבָטַשׁ, כְּדֵין (משלי י״ג:ט׳) וְנֵר רְשָׁעִים יִדְעָךְ. מְחָרֵף וּמְגַדֵּף לְכָל סִטְרִין, וְלָא יָכִיל לְאַנְהֲרָא כְּלַל, וּכְדֵין כְּתִיב (קהלת ב׳:י״ב) כִּי מֶה הָאָדָם שֶׁיָּבֹא אַחֲרֵי הַמֶּלֶךְ. וּבָעֵי לְאִתְדָּמֵי לֵיהּ, וְלָא יָכִיל. וְעַל דָּא (תהילים י״א:ה׳) יְיָ צַדִּיק יִבְחָן, וּבָטַשׁ בֵּיהּ, וּכְדֵין נָהִיר וְאִתָּקַף בִּנְהִירוּ. יִבְחָן, כְּמָה דְאַתְּ אָמֵר (ישעיהו כ״ח:ט״ז) אֶבֶן בֹּחַן. גָּחִין רִבִּי שִׁמְעוֹן, וְנָשִׁיק לְעַפְרָא. אָמַר, מִלָּה מִלָּה אֲבַתְרָךְ רְדִיפְנָא, מִיּוֹמָא דַּהֲוִינָא, וְהַשְׁתָּא אִשְׁתְּמוֹדְעָא לִי מִלָּה, מִגּוֹ שָׁרְשָׁא וְעִקָּרָא דְּכֹלָּא.","אָמַר לֵיהּ, אִי רִבִּי, אִי רִבִּי, כַּד סַלְּקִין לְעֵילָּא, כָּל אִינּוּן רוּחִין דְּכוּרִין וְנוּקְבִין, בְּהַהוּא זִמְנָא, שַׁמְעִין (ס\"א כמה) מִלִּין חַדְתִּין וְעַתִּיקִין, נַחְתִּין וְעָאלִין לְגוֹ מְתִיבְתָּא, וְאַהְדְּרָן מִלֵּי קַמֵּי רַב מְתִיבְתָּא, וְאִיהוּ אוֹלִיף לוֹן מִלָּה עַל קִיּוּמֵיהּ. כַּד סַלְּקִין מִתְפַּשְּׁטִין מַלְבּוּשֵׁיהוֹן וְסַלְּקִין. כַּד נַחְתֵּי, מִתְלַבְּשִׁין בִּלְבוּשֵׁיהוֹן דְּהַהוּא גּוּפָא.","אִי רִבִּי, אִי רִבִּי, כַּמָה חַדְתִּין מִלִּין מִגּוֹ רַב מְתִיבְתָּא. זַכָּאָה אִיהוּ מַאן דְּאַזְעַר גַּרְמֵיהּ בְּהַאי עָלְמָא, כַּמָה אִיהוּ רַב וְעִלָּאָה בְּהַהוּא עָלְמָא. וְהָכִי פָּתַח רַב מְתִיבְתָּא, מַאן דְּאִיהוּ זְעֵיר, אִיהוּ רַב. וּמַאן דְּאִיהוּ רַב, אִיהוּ זְעֵיר. דִּכְתִּיב, (בראשית כ״ג:א׳) וַיִּהְיוּ חַיֵּי שָׂרָה מֵאָה שָׁנָה וְעֶשְׂרִים שָׁנָה וְשֶׁבַע שָׁנִים. מֵאָה דְּאִיהוּ חֶשְׁבּוֹן רַב, כְּתִיב בֵּיהּ שָׁנָה, זְעִירוּ דְּשָׁנִין, חַד אַזְעִיר לֵיהּ. שֶׁבַע, דְּאִיהוּ חֶשְׁבּוֹן זְעֵיר, אַסְגֵּי לֵיהּ, וְרַבֵּי לֵיהּ דִּכְתִּיב שֶׁבַע שָׁנִים. תָּא חֲזֵי, דְּלָא רַבֵּי קוּדְשָׁא בְּרִיךְ הוּא, אֶלָּא לִדְאַזְעִיר. לָא אַזְעִיר אֶלָּא לִדְרַבֵּי. זַכָּאָה אִיהוּ מַאן דְּאַזְעִיר גַּרְמֵיהּ בְּהַאי עָלְמָא, כַּמָּה אִיהוּ רַב בְּעִלּוּיָא בְּהַהוּא עָלְמָא."],[[0,"אי רבי אי וכו׳:","אהה רבי, אהה רבי. אם לא היית בן יוחאי, לא היה נמסר לגלות. הזווג שבעולם ההוא, עושה פירות יותר מבזווג שנעשה בעולם הזה. בהזווג שלהם, בזווג של עולם ההוא, בתשוקה שלהם כאחד, כשמתדבקות הנשמות זו עם זו, עושים פירות, ויוצאים מהם אורות, ונעשים נרות, והם הנשמות אל הגרים שמתגיירים. וכל אלו הנשמות שנולדות מאלו הזווגים, נכנסים להיכל אחד."],[1,"וכד מתגיירא גיורא וכו׳:","וכשמתגייר גר אחד, פורחת נשמה מהיכל ההוא, ונכנסת תחת כנפי השכינה, והשכינה נושקת אותה, משום שהיא תולדה של נשמות הצדיקים, ושולחת אותה לתוך אותו הגר, ושוכנת בו. ומזמן ההוא הוא נקרא גר צדק. והיינו הסוד שכתוב פרי צדיק עץ חיים, מה עץ החיים, שהוא ז״א, מוציא נשמות, אף הצדיק, כך הוא הפרי שלו, שעושה נשמות."],[2,"רב מתיבתא אמר וכו׳:","רב מתיבתא אמר, כתוב, ותהי שרה עקרה אין לה ולד. שואל, ממה שאמר ותהי שרה עקרה, אני יודע שאין לה ולד, למה כתוב, אין לה ולד. אלא כך אמר רב מתיבתא, בנים לא היתה מוליד, אבל היתה מוליד נשמות, בדבקות התשוקה של ב׳ צדיקים אלו, היו מולידים נשמות לגרים, בכל זמן ההוא שהיו בחרן, כמו שעושים צדיקים בגן עדן. כמו שכתוב, ואת הנפש אשר עשו בחרן. נפש, עשו ודאי."],[3,"חדי ר״ש א\"ל וכו׳:","שמח ר׳ שמעון, אמר לו איש ההוא, אהה רבי, מה אומר לך. בכל ראשי חדשים ושבתות ומועדים וזמנים, הזכרים עולים להראות לפני מלך הקדוש, זכרים ולא נקבות, כמו שאתה אומר, יראה כל זכורך. וכשחוזרים, חוזרים בכמה דברים חדשים, וחוזרים אותם הדברים לפני רב מתיבתא."],[4,"יומא דא אהדרן וכו׳:","ביום הזה חזרו דברים חדשים לפני ראש הישיבה, על סודות עתיקים, צדיק וטוב לו צדיק ורע לו. שכל הנשמות עולות תוך המאזנים של האילן, שהוא מלכות, מטרם שיבואו לעולם, וכפי המשקל שבמאזנים כך יש להם בעולם הזה. רב מתיבתא ירד וגילה ממה ששמע למעלה, דבר אחד גילה ולא יותר. העץ שאינו מעלה אורו כותשים אותו ומאיר. הגוף, שאור הנשמה אינה עולה בו מכים בו ויעלה אור הנשמה, ויתאחדו זה בזה, הגוף בנשמה, להאיר."],[5,"בגין דאית גופא וכו׳:","משום שיש גוף שאור הנשמה לא יאיר בו עד שמכים אותו, אז מאיר אור הנשמה ומתאחדת בגוף. והגוף מתאחד בה. ואז הגוף כשעולה אורו מתוך הנשמה, הוא מהדר ומרומם ומשבח ומתפלל תפלתו ובקשתו, ומברך לאדונו. הנה אז הכל מאיר. ולפיכך יש צדיק ורע לו."],[6,"סטרא אחרא בעי וכו׳:","סטרא אחרא רוצה לעשות כן, והיא מכה ברשעים, וכל מה שמכה, הוא, ונר רשעים ידעך, כי מחרף ומגדף לכל הצדדים, ואינו יכול להאיר כלל. ואז כתוב, כי מה האדם שיבא אחרי המלך. שרוצה להתדמות אליו ואינו יכול. וע״כ, ה׳ צדיק יבחן ומכה בו, ואז מאיר ומתחזק בהאור, \u0003יבחן,\u0004 כש״א, אבן בחן. כפף עצמו ר׳ שמעון ונשק העפר. אמר, מלה מלה, רדפתי אחריך מיום שהייתי לאיש, ועתה נודע לי הדבר, מתוך השורש ועיקר הכל."],[7,"א\"ל אי רבי וכו׳:","א״ל אהה רבי, אהה רבי. כשכל אלו הרוחות זכרים ונקבות עולים למעלה, בלילה בעת השינה, בזמן ההוא שומעים דברים חדשים וישנים, יורדים ונכנסים תוך הישיבה, וחוזרים הדברים לפני ראש הישיבה, והוא מלמד אותם דבר על מכונו. כשעולים מתפשטים מלבושיהם שבעולם הזה, ועולים. כשיורדים חוזרים ומתלבשים בלבושיהם של גוף ההוא."],[8,"אי רבי אי וכו׳:","אהה רבי אהה רבי. כמה חדשים הם הדברים מן ראש הישיבה. אשרי הוא מי שמשפיל את עצמו בעולם הזה, כמה הוא רב ועליון בעולם ההוא. וכך פתח ראש הישיבה. מי שהוא קטן הוא גדול. ומי שהוא גדול הוא קטן. שכתוב, ויהיו חיי שרה מאה שנה ועשרים שנה ושבע שנים. \u0003מאה\u0004 שהוא חשבון גדול כתוב בו \u0003שנה,\u0004 המיעוט ביותר של שנים, עד לאחת הקטין אותו. \u0003שבע,\u0004 שהוא חשבון קטן, הגדיל אותו והרבה אותו, שכתוב שבע \u0003שנים.\u0004 לשון רבים. בוא וראה שלא הגדיל הקב״ה אלא למשפיל עצמי. ולא השפיל הקב\"ה אלא למגדיל עצמו. אשרי הוא מי שמשפיל עצמו בעולם הזה, כמה הוא רב בהתעלות בעולם ההוא."]],[[0,"","אִי רַבִּי, אִי רַבִּי, אִלְמָלֵא בַּר יוֹחַאי י אַתָּה, לֹא נִמְסַר לְגַלּוֹת. זִוּוּג אוֹתוֹ עוֹלָם נַעֲשֶׂה פְרִי יוֹתֵר מִפְּרִי שֶׁנַּעֲשֶׂה בָּעוֹלָם הַזֶּה. בַּזִּוּוּג שֶׁלָּהֶם, בְּזִוּוּג אוֹתוֹ עוֹלָם, בָּעֶרְגָּה שֶׁלָּהֶם כְּאֶחָד, כְּשֶׁהַנְּשָׁמוֹת נִדְבָּקוֹת זוֹ בָּזוֹ, עוֹשׂוֹת פֵּרוֹת, וְיוֹצְאִים אוֹרוֹת מֵהֶם וְנַעֲשִׂים נֵרוֹת. וְהֵם הַנְּשָׁמוֹת לַגֵּרִים הַמִּתְגַּיְּרִים, וְכָל אֵלֶּה עוֹלִים לְהֵיכָל אֶחָד."],[1,"","וּכְשֶׁמִּתְגַּיֵּר גֵּר אֶחָד, פּוֹרַחַת מֵאוֹתוֹ הֵיכָל נְשָׁמָה, וְנִכְנֶסֶת תַּחַת כַּנְפֵי הַשְּׁכִינָה, וְנוֹשֶׁקֶת אוֹתָהּ, מִשּׁוּם שֶׁהִיא פְּרִי הַצַּדִּיקִים, וְשׁוֹלַחַת אוֹתָהּ לְתוֹךְ אוֹתוֹ גֵּר וְשׁוֹרָה בּוֹ, וּמֵאוֹתוֹ זְמַן נִקְרָא גֵר צֶדֶק. וְזֶהוּ סוֹד הַכָּתוּב, (משלי יא) פְּרִי צַדִּיק עֵץ חַיִּים. מָה עֵץ הַחַיִּים מוֹצִיא נְשָׁמוֹת, גַּם צַדִּיק פִּרְיוֹ עוֹשֶׂה נְשָׁמוֹת."],[2,"","רֹאשׁ הַיְשִׁיבָה אָמַר, כָּתוּב (בראשית יא) וַתְּהִי שָׂרַי עֲקָרָה אֵין לָהּ וָלָד. מִמַּה שֶּׁאָמַר וַתְּהִי שָׂרַי עֲקָרָה, אֵינִי יוֹדֵעַ שֶׁאֵין לָהּ וָלָד? מַה זֶּה אֵין לָהּ וָלָד? אֶלָּא כָּךְ אָמַר רֹאשׁ הַיְשִׁיבָה, וָלָד לֹא הָיְתָה מוֹלִידָה, אֲבָל נְשָׁמוֹת הָיְתָה מוֹלִידָה בְּהִתְדַּבְּקוּת עֶרְגָּה, שֶׁאוֹתָם שְׁנֵי צַדִּיקִים הָיוּ מוֹלִידִים נְשָׁמוֹת לַגֵּרִים כָּל אוֹתוֹ זְמַן שֶׁהָיוּ בְחָרָן כְּמוֹ שֶׁעָשׂוּ צַדִּיקִים בְּגַן עֵדֶן, כְּמוֹ שֶׁכָּתוּב (שם יב) וְאֶת הַנֶּפֶשׁ אֲשֶׁר עָשׂוּ בְחָרָן. נֶפֶשׁ עָשׂוּ בְּוַדַּאי."],[3,"","שָׂמַח רַבִּי שִׁמְעוֹן. אָמַר לוֹ אוֹתוֹ הָאִישׁ, אִי רַבִּי, מָה אֹמַר לְךְ, בְּכָל רֹאשׁ חֹדֶשׁ וְשַׁבָּתוֹת וּמוֹעֲדִים וּזְמַנִּים, אוֹתָם זְכָרִים עוֹלִים לְהֵרָאוֹת לִפְנֵי הַמֶּלֶךְ הַקָּדוֹשׁ, זְכָרִים וְלֹא נְקֵבוֹת, כְּמוֹ שֶׁנֶּאֱמַר (שמות כג) יֵרָאֶה כָּל זְכוּרְךְ. וּכְשֶׁחוֹזְרִים, חוֹזְרִים בְּכַמָּה דְבָרִים חֲדָשִׁים, וּמַחֲזִירִים דְּבָרִים לִפְנֵי רֹאשׁ הַיְשִׁיבָה."],[4,"","יוֹם זֶה הֶחֱזִירוּ דְבָרִים חֲדָשִׁים לִפְנֵי רֹאשׁ הַיְשִׁיבָה עַל סוֹדוֹת עַתִּיקִים - צַדִּיק וְטוֹב לוֹ, צַדִּיק וָרָע לוֹ. שֶׁכֻּלָּם עוֹלִים תּוֹךְ מִשְׁקַל הָאִילָן עַד שֶׁלֹּא יָבאוּ לָעוֹלָם, וּכְפִי מִשְׁקֹלֶת הַמִּשְׁקָל כָּךְ יֵשׁ לָהֶם בָּעוֹלָם הַזֶּה. רֹאשׁ הַיְשִׁיבָה יָרַד וְגִלָּה מִמַּה שֶּׁשָּׁמַע לְמַעְלָה, דָּבָר אֶחָד גִּלָּה וְלֹא יוֹתֵר. עֵץ שֶׁלֹּא עוֹלֶה אוֹרוֹ, יַכּוּ בוֹ וְיָאִיר. גּוּף שֶׁלֹּא עוֹלֶה בּוֹ אוֹר הַנְּשָׁמָה, יַכּוּ בוֹ וְיַעֲלֶה אוֹר הַנְּשָׁמָה, וְיֹאחֲזוּ זֶה בָזֶה לְהָאִיר. (שתי נסחאות)"],[5,"","מִשּׁוּם שֶׁיֵּשׁ גּוּף שֶׁאוֹר הַנְּשָׁמָה לֹא מֵאִיר בּוֹ עַד שֶׁיַּכּוּ בוֹ, אָז מֵאִיר אוֹר הַנְּשָׁמָה וְנֶאֱחָז בַּגּוּף, וְהַגּוּף נֶאֱחָז בּוֹ. הַגּוּף אָז עוֹלֶה אוֹר מִתּוֹךְ הַנְּשָׁמָה, מְהַדֵּר מְרוֹמֵם וּמְשַׁבֵּחַ, מִתְפַּלֵּל תְּפִלָּתוֹ וּבַקָּשָׁתוֹ, מְבָרֵךְ לְרִבּוֹנוֹ. הֲרֵי אָז הַכֹּל מֵאִיר, מִשּׁוּם שֶׁיֵּשׁ גּוּף שֶׁאֵין הַנְּשָׁמָה יְכוֹלָה לְהָאִיר בּוֹ עַד שֶׁיַּכּוּ בוֹ, וְאָז מֵאִיר וְנֶאֱחָז זֶה בָזֶה. יֵשׁ עֵץ שֶׁלֹּא נֶאֱחָז בָּאוֹר, וְלֹא עוֹלֶה בּוֹ אוֹר עַד שֶׁיַּכּוּ בוֹ, וְאָז מֵאִיר."],[6,"","צַד הָאַחֵר רוֹצֶה לַעֲשׂוֹת כָּךְ, וּמַכֶּה בָרְשָׁעִים, וְכָל מַה שֶּׁמַּכֶּה, אָז (משלי יג) וְנֵר רְשָׁעִים יִדְעָךְ. מְחָרֵף וּמְגַדֵּף לְכָל הַצְּדָדִים וְלֹא יָכוֹל לְהָאִיר כְּלָל, וְאָז כָּתוּב (קהלת ב) כִּי מֶה הָאָדָם שֶׁיָּבוֹא אַחֲרֵי הַמֶּלֶךְ. וְרוֹצֶה לְהִדָּמוֹת לוֹ וְלֹא יָכוֹל. וְעַל זֶה (תהלים יא) ה' צַדִּיק יִבְחָן, וּמַכֶּה בּוֹ, וְאָז מֵאִיר וּמִתְחַזֵּק בָּאוֹר. יִבְחָן, כְּמוֹ שֶׁנֶּאֱמַר (ישעיה כח) אֶבֶן בּחַן. גָּחַן רַבִּי שִׁמְעוֹן וְנָשַׁק לֶעָפָר. אָמַר, דָּבָר דָּבָר אַחֲרֶיךְ רָדַפְתִּי מִיּוֹם שֶׁהָיִיתִי, וְכָעֵת נוֹדַע לִי הַדָּבָר מִתּוֹךְ שֹׁרֶשׁ וְעִקַּר הַכֹּל."],[7,"","אָמַר לוֹ, אִי רַבִּי, אִי רַבִּי, כְּשֶׁעוֹלִים לְמַעְלָה, כָּל אוֹתָם רוּחוֹת זְכָרִים וּנְקֵבוֹת בְּאוֹתוֹ זְמַן שׁוֹמְעִים (כמה) דְּבָרִים חֲדָשִׁים וְעַתִּיקִים, יוֹרְדִים וְנִכְנָסִים לְתוֹךְ הַיְשִׁיבָה, וּמַחֲזִירִים דְּבָרִים לִפְנֵי רֹאשׁ הַיְשִׁיבָה, וְהוּא מְלַמְּדָם דָּבָר עַל קִיּוּמוֹ. כְּשֶׁעוֹלִים, מִתְפַּשְּׁטִים מִלְּבוּשֵׁיהֶם וְעוֹלִים. כְּשֶׁיּוֹרְדִים, מִתְלַבְּשִׁים בִּלְבוּשֵׁיהֶם שֶׁל אוֹתוֹ גּוּף."],[8,"","אִי רַבִּי, אִי רַבִּי, כַּמָּה דְבָרִים חֲדָשִׁים מִתּוֹךְ רֹאשׁ הַיְשִׁיבָה. אַשְׁרָיו מִי שֶׁמַּקְטִין עַצְמוֹ בָּעוֹלָם הַזֶּה, כַּמָּה הוּא גָּדוֹל וְעֶלְיוֹן בָּעוֹלָם הַהוּא. וְכָךְ פָּתַח רֹאשׁ הַיְשִׁיבָה: מִי שֶׁהוּא קָטָן - הוּא גָּדוֹל, וּמִי שֶׁהוּא גָּדוֹל - הוּא קָטָן, שֶׁכָּתוּב (בראשית כג) וַיִּהְיוּ חַיֵּי שָׂרָה מֵאָה שָׁנָה וְעֶשְׂרִים שָׁנָה וְשֶׁבַע שָׁנִים. מֵאָה, שֶׁהוּא חֶשְׁבּוֹן גָּדוֹל, כָּתוּב בּוֹ שָׁנָה, קְטַן הַשָּׁנִים, לְאֶחָד הִקְטִינוֹ. שֶׁבַע, שֶׁהוּא חֶשְׁבּוֹן קָטָן, הִגְדִּילוֹ וְרִבָּה אוֹתוֹ, שֶׁכָּתוּב שֶׁבַע שָׁנִים. בֹּא וּרְאֵה שֶׁלֹּא הִגְדִּיל הַקָּדוֹשׁ בָּרוּךְ הוּא אֶלָּא לַמַּקְטִין. לֹא הִקְטִין אֶלָּא לְמִי שֶׁהִתְגַּדֵּל. אַשְׁרֵי מִי שֶׁמַּקְטִין עַצְמוֹ בָּעוֹלָם הַזֶּה, כַּמָּה הוּא גָּדוֹל בְּעִלּוּי בְּאוֹתוֹ הָעוֹלָם."]]],[["אַדְּהָכִי שַׁמְעוּ שִׁירָתָא דְּיַמָּא, בְּקָל נְעִימוּ דְּלָא שָׁמְעוּ מִיּוֹמָא דְּאִתְבְּרִיאוּ, קָל נְעִימוּ דְּשִׁירָתָא, כְּהַהוּא נְעִימוּ דַּהֲווֹ אַמְרֵי. וְכַד סִיְּימוּ (שמות ט״ו:י״ח) יְיָ יִמְלוֹךְ לְעוֹלָם וָעֶד. חָמוּ ד' דִּיוּקְנִין בִּרְקִיעַ. וְחַד מִנַּיְיהוּ רַב וְעִלָּאָה מְכֻּלְּהוּ. וְהַהוּא רַב וְעִלָּאָה מִנַּיְיהוּ, אִתְּעַר קָלָא וְאָמַר, (ירמיהו ב׳:ב׳) כֹּה אָמַר יְיָ זָכַרְתִּי לָךְ חֶסֶד נְעוּרַיִךְ אַהֲבַת כְּלוּלוֹתָיִךְ וְגוֹ'. שָׁאט בִּרְקִיעָא וְאַגְנִיז, קָם אַחֲרָא אֲבַתְרֵיהּ וְאָמַר, (ישעיהו מ״ב:ט״ז) וְהוֹלַכְתִּי עִוְרִים בְּדֶּרֶךְ לֹא יָדָעוּ בִּנְתִיבוֹת לֹא יָדְעוּ וְגוֹ'. סִיֵּים וְשָׁאט בִּרְקִיעָא וְאַגְנִיז.","פָּתַח אִידָךְ וְאָמַר, (ישעיהו ל״ה:א׳) יְשׂוּשׂוּם מִדְבָּר וְצִיָּה וְתָגֵל עֲרָבָה וְתִפְרַח כַּחֲבַצָּלֶת. וְשָׁאט בִּרְקִיעָא, וְאַגְנִיז. פָּתַח אִידָךְ וְאָמַר, (ישעיהו מ״ג:א׳) כֹּה אָמַר יְיָ בּוֹרַאֲךָ יַעֲקֹב וְגוֹ', (ישעיהו מ״ג:ט״ז) כֹּה אָמַר יְיָ הַנּוֹתֵן בַּיָּם דָּרֶךְ וּבְמַיִם עַזִּים נְתִיבָה וְגוֹ'. תְּכַבְּדֵנִי חַיַּת הַשָּׂדֶה תַּנִּים וּבְנוֹת יַעֲנָה וְגוֹ'. סִיֵּים וְשָׁאט בִּרְקִיעָא, וְאַגְנִיז. כְּדֵין דְּחִילוּ סַגִּיא וְאֶמְתָּנִי נָפַל עָלַיְיהוּ.","כַּד הֲוָה נָהִיר יְמָמָא, קָלָא אִתְּעַר כְּמִלְּקַדְּמִין, וְאָמַר, עַמָּא תַּקִּיפָא כְּאַרְיֵה, גִּבָּרִין כִּנְמָרִין, הָבוּ יְקָר לְמָארֵיכוֹן. דִּכְתִּיב, (ישעיהו כ״ה:ג׳) עַל כֵּן יְכַבְּדוּךָ עַם עָז וְגוֹ'. שָׁמְעוּ קָל. חֵילִין וּמַשִׁרְיָין דַּהֲווֹ אַמְרֵי, (דברי הימים א כ״ט:י״א) לְךָ יְיָ הַגְּדוּלָה וְהַגְּבוּרָה וְהַתִּפְאֶרֶת וְהַנֵּצַח וְהַהוֹד וְגוֹ', עַד וּמְרוֹמַם עַל כָּל בְּרָכָה וּתְהִלָּה. תַּוְוהוּ וְאַזְלוּ. אַדְּהָכִי נָהַר יְמָמָא, אַהְדְּרוּ רֵישָׁא, וְחָמוּ כָּל מַדְבְּרָא חָפֵּי בַּעֲנָנֵי יְקָר, מְנַהֲרָן, מְנַצְּצָן, בִּגְוָונִין סַגִּיאִין.","אָמְרוּ דָּא לְדָא, וַדַּאי קוּדְשָׁא בְּרִיךְ הוּא בָּעֵי לְאִשְׁתַּבְּחָא בְּתוּשְׁבַּחְתָּא דְּדָרָא דְּמַדְבְּרָא, דְּלָא הֲוָה בְּעָלְמָא, דָּרָא עִלָּאָה, כְּדָרָא דָּא. וְלָא יְהֵא עַד דְּיֵיתֵי מַלְכָּא מְשִׁיחָא וַדַּאי כָּל מַה דְּאַחְמֵי לָן קוּדְשָׁא בְּרִיךְ הוּא, לָא הֲוָה, אֶלָּא בְּגִין לְאוֹדָעָא לָן חֲבִיבוּ דְּמָארֵיהוֹן עָלַיְיהוּ. לְאוֹדָעָא דְּאִית לוֹן חוּלָקָא טָבָא, וְאִינּוּן בָּנֵי עָלְמָא דְּאָתֵי. וּלְזִמְנָא דְּאָתֵי כַּד יוֹקִים קוּדְשָׁא בְּרִיךְ הוּא מֵתַיָּיא, זְמִינִין אִלֵּין לְאַחֲיָיא בְּקַדְמִיתָא. כְּמָה דְאַתְּ אָמֵר (ישעיהו כ״ו:י״ט) יִחְיוּ מֵתֶיךָ, וְאִלֵּין אִינּוּן דָּרָא דְּמַדְבְּרָא.","אָמַר לֵיהּ, אִי מִלָּה חַדְתָּא יַדְעַת, דַּאֲנָא עַרְטִירָא בָּהּ. אָמַר לֵיהּ אֵימָא. אָמַר קָלָא דְּהַדְרָא בָּעֵינָא לְמִנְדַּע. בַּר נָשׁ יָהִיב קָלָא בְּחַקְלָא, אוֹ בַּאֲתָר אַחֲרָא, וְהַדְרָא קָלָא אַחֲרָא, וְלָא יְדִיעַ. אָמַר לֵיהּ, אִי חֲסִידָא קַדִּישָׁא, עַל מִלָּה דָּא, כַּמָה קָלִין אִתְּעֲרוּ, וְכַמָּה דִּקְדוּקִין הֲווֹ קָמֵי רַב מְתִיבְתָּא, וְכַד נָחִת רַב מְתִיבְתָּא, אָמַר, הָכִי אוּקְמוּהָ מִלָּה בִּמְתִיבְתָּא דִּרְקִיעָא, וְרָזָא יַקִּירָא אִיהִי.","תָּא חֲזֵי, תְּלַת קָלִין אִינּוּן, דְּלָא אִתְאֲבִידוּ לְעָלְמִין, בַּר קָלִין דְּאוֹרַיְיתָא וּצְלוֹתָא, דְּאִלֵּין סַלְּקִין לְעֵילָּא, וּבָקְעִין רְקִיעִין. אֲבָל קָלִין אַחֲרָנִין אִינּוּן דְּלָא סַלְּקִין, וְלָא אִתְאֲבִידוּ.","וְאִינּוּן תְּלַת: קוֹל חַיָּה בְּשַׁעֲתָא דְּאִיהִי עַל קַלְבִּיטָא, הַהוּא קָלָא מְשַׁטְּטָא וְאָזְלָא בַּאֲוִירָא, מִסַּיְיפֵי עָלְמָא עַד סַיְיפֵי עָלְמָא. קוֹל דְּבַר נָשׁ, בְּשַׁעֲתָא, דְּנָפִיק נִשְׁמָתֵיהּ מִגוּפֵיהּ, הַהוּא קָלָא מְשַׁטְּטָא וְאָזְלָא בַּאֲוִירָא, מִסַּיְיפֵי עָלְמָא עַד סַיְיפֵי עָלְמָא. קוֹל נַחַשׁ, בְּשַׁעֲתָא דְּפָשִׁיט מַשְׁכֵּיהּ, הַהוּא קָלָא מְשַׁטְּטָא בַּאֲוִירָא, וְאָזְלָא מִסַּיְיפֵי עָלְמָא עַד סַיְיפֵי עָלְמָא.","אִי חֲסִידָא קַדִּישָׁא, כַּמָה מִלָּה דָּא רַבָּא וְיַקִּירָא. אִלֵּין קָלִין, מַה אִתְעָבִיד מִינַיְיהוּ, וּלְאָן אֲתָר עָאלִין וְשָׁרָאן. אִלֵּין קָלִין דְּצַעֲרָא אִינּוּן, וְאָזְלִין וְּמְשַׁטְטֵי בַּאֲוִירָא, וְאָזְלֵי מִסַּיְיפֵי עָלְמָא, עַד סַיְיפֵי דְּעָלְמָא, וְעָאלִין גּוֹ נְקִיקִין וּמְחִילִין דְּעַפְרָא, וְאִתְטַמְּרָן תַּמָּן. וְכַד יָהִיב בַּר נָשׁ קָלָא, אִינּוּן מִתְעָרִין לְגַבֵּי הַהוּא קָלָא. קָלָא דְּנָחָשׁ, לָא אִתְּעַר לְגַבֵּי קָלָא דְּבַּר נָשׁ. הֵיאַךְ יִתְּעַר. בְּמָחָאָה. כַּד מָחֵי בַּר נָשׁ מָחָאָה אִתְּעַר קָלָא דְּנָחָשׁ, דְּאִתְטַמַּר לְגַבֵּיהּ הַהוּא קָלָא, וְלָאו קָלָא אַחֲרָא. קָלָא אִתְּעַר בָּתַר קָלָא, זִינָא בָּתַר זִינֵיהּ."],[[0,"אדהכי שמעו שירתא וכו׳:","בתוך כך שמעו שירת הים בקול נעימות, שלא שמעו מיום שנבראו קול נעימת שירה, כאותה הנעימות שהיו אומרים. וכשגמרו, ה׳ ימלוך לעולם ועד, ראו ד׳ צורות אנשים ברקיע, ואחד מהם גדול ועליון מכולם. ואותו גדול ועליון מכולם עורר קול ואמר, כה אמר ה׳ זכרתי לך חסד נעוריך אהבת כלולותיך וגו'. עף ברקיע ונגנז. קם אחר אחריו, ואמר והולכתי עורים בדרך לא ידעו בנתיבות לא ידעו וגו'. גמר ועף ברקיע ונגנז."],[1,"פתח אידך ואמר וכו׳:","פתח אחר ואמר. ישושום מדבר וציה ותגל ערבה ותפרח כחבצלת. ועף ברקיע ונגנז. פתח אחר ואמר, כה אמר ה׳ בוראך יעקב וגו'. כה אמר ה׳ הנותן בים דרך ובמים עזים נתיבה וגו', תכבדני חית השדה תנים ובנות יענה וגו'. גמר ועף ברקיע ונגנז. אז פחד גדול ואימה נפל עליהם."],[2,"כד הוה נהיר וכו׳:","כשהאיר היום, נתעורר קול כבתחילה ואמר, עם החזק כאריה, גבורים כנמרים, תנו כבוד לאדונכם. שכתוב, על כן יכבדוך עם עז וגו׳. שמעו קול צבאות ומחנות שהיו אומרים, לך ה׳ הגדולה והגבורה והתפארת והנצח וההוד וגו׳ עד, ומרומם על כל ברכה ותהלה. תמהו והלכו. בתוך כך האיר היום. החזירו ראשם, וראו כל המדבר מכוסה בענני יקר, המאירים ומנצצים בצבעים רבים."],[3,"אמרו דא לדא וכו׳:","אמרו זה לזה, ודאי, הקב״ה רוצה להשתבח בתשבחות דור המדבר. שלא היה בעולם דור עליון כדור הזה, ולא יהיה עד שיבא מלך המשיח. ודאי, כל מה שהראה אותנו הקב״ה, לא היה אלא כדי להודיענו אהבת רבונם עליהם, להודיענו שיש להם חלק טוב, והם בני עולם הבא. ולעתיד לבא, כשיקים הקב״ה את המתים לתחיה, עתידים אלו דור המדבר, לקום לתהיה תחילה. כש״א יחיו מתיך. שאלו הם דור המדבר."],[4,"א״ל אי מלה וכו׳:","א״ל, אם אתה יודע דבר חדש שאני עירום ממנו. א״ל אמור. אמר לו, קול החוזר אני רוצה לדעת. אדם הנותן קול בשדה או במקום אחר, וחוזר קול אחר אחריו, ולא ידוע מאין הוא בא. אמר לו, אהה חסיד קדוש, על דבר זה כמה קולות נתעוררו, וכמה דקדוקים היו לפני ראש הישיבה. וכשירד ראש הישיבה, אמר, כך העמידו הדבר במתיבתא דרקיע, והוא סוד יקר."],[5,"תא חזי תלת וכו׳:","בוא וראה שלשה קולות הם שאינם נאבדים לעולם. לבד מקולות תורה ותפלה שהם עולים למעלה ובוקעים רקיעים (כנ״ל ויקהל אות ק\"ל) אבל קולות אחרים יש שאינם עולים ואינם נאבדים."],[6,"ואינון תלת קול וכו׳:","והם שלשה קולות. א) קול חיה, בשעה שהיא על האבנים, קול ההוא הולך ומשוטט באויר מסוף העולם עד סוף העולם. ב) קול האדם בשעה שהנשמה יוצאת מגופו, קול ההוא משוטט והולך באויר, מסוף העולם עד סוף העולם. ג) קול הנחש, בשעה שפושט עורו (כנ\"ל פקודי אות תתע״ט) קול ההוא משוטט באויר והולך מסוף העולם עד סוף העולם."],[7,"אי חסידא קדישא וכו׳:","אהה חסיד קדוש, כמה דבר זה גדול ויקר. אלו הקולות מה נעשה מהם ולאיזה מקום נכנסים ושורים. אלו הקולות, של צער הם. והולכים ומשוטטים באויר, והולכים מסוף העולם עד סוף העולם, ונכנסים תוך בקעים ומחילות עפר, ומסתתרים שם. וכשאדם נותן קול הם מתעוררים כלפי קול ההוא. רק קול של הנחש אינו מתעורר כלפי קולו של אדם, ואיך הוא מתעורר. היינו בהכאה. כשאדם נותן הכאה באיזה דבר, נתעורר כלפי קול ההכאה ההוא, קולו של נחש שנסתתר שם, במקום הריק או בשדה, ולא לקול אחר של אדם. קול מתעורר אחר קול אבל מין הולך אחר מינו. שב' קולות הראשונים שהם של אדם מתעוררים אחר קול אדם, וקול הג׳, שהוא של הנחש מתעורר אחר קול הכאה."]],[[0,"","בֵּין כָּךְ שָׁמְעוּ שִׁירַת הַיָּם בְּקוֹל נָעִים שֶׁלֹּא שָׁמְעוּ מִיּוֹם שֶׁנִּבְרְאוּ, קוֹל נָעִים שֶׁל שִׁירָה כְּאוֹתָהּ נְעִימָה שֶׁהָיוּ אוֹמְרִים. וּכְשֶׁסִּיְּמוּ (שמות טו) ה' יִמְלֹךְ לְעֹלָם וָעֶד, רָאוּ אַרְבַּע דְמֻיּוֹת בָּרָקִיעַ, וְאֶחָד מֵהֶם גָּדוֹל וְעֶלְיוֹן מִכֻּלָּם. וְאוֹתוֹ גָּדוֹל וְעֶלְיוֹן מֵהֶם עוֹרֵר קוֹל וְאָמַר, (ירמיהב) כֹּה אָמַר ה' זָכַרְתִּי לָךְ חֶסֶד נְעוּרַיִךְ אַהֲבַת כְּלוּלֹתָיִךְ וְגוֹ'. שָׁט בָּרָקִיעַ וְנִגְנַז, עָמַד אַחֵר אַחֲרָיו וְאָמַר, (ישעיה מב) וְהוֹלַכְתִּי עִוְרִים בְּדֶרֶךְ לֹא יָדָעוּ בִּנְתִיבוֹת לֹא יָדְעוּ וְגוֹ'. סִיֵּם וְשָׁט בָּרָקִיעַ וְנִגְנַז."],[1,"","פָּתַח הָאַחֵר וְאָמַר, (שם לה) יְשֻׂשׂוּם מִדְבָּר וְצִיָּה וְתָגֵל עֲרָבָה וְתִפְרַח כַּחֲבַצָּלֶת. וְשָׁט בָּרָקִיעַ וְנִגְנַז. פָּתַח הָאַחֵר וְאָמַר, (שם מג) כֹּה אָמַר ה' בֹּרַאֲךְ יַעֲקֹב וְגוֹ'. (שם) כֹּה אָמַר ה' הַנּוֹתֵן בַּיָּם דָּרֶךְ וּבְמַיִם עַזִּים נְתִיבָה וְגוֹ', תְּכַבְּדֵנִי חַיַּת הַשָּׂדֶה תַּנִּים וּבְנוֹת יַעֲנָה וְגוֹ'. סִיֵּם וְשָׁט בָּרָקִיעַ וְנִגְנַז. אָז פַּחַד גָּדוֹל וְאֵימָה נָפַל עֲלֵיהֶם."],[2,"","כְּשֶׁהֵאִיר הַיּוֹם, קוֹל הִתְעוֹרֵר כְּמִקֹּדֶם וְאָמַר: עַם תַּקִּיף כְּאַרְיֵה, גִּבּוֹרִים כַּנְּמֵרִים, תְּנוּ כָבוֹד לְרִבּוֹנְכֶם, שֶׁכָּתוּב (שם כה) עַל כֵּן יְכַבְּדוּךְ עַם עָז וְגוֹ'. שָׁמְעוּ קוֹל, חֲיָלוֹת וּמֶרְכָּבוֹת שֶׁהָיוּ אוֹמְרִים, (דברי הימים א כט) לְךְ ה' הַגְּדֻלָּה וְהַגְּבוּרָה וְהַתִּפְאֶרֶת וְהַנֵּצַח וְהַהוֹד וְגוֹ', עַד (נחמיה ט) וּמְרוֹמַם עַל כָּל בְּרָכָה וּתְהִלָּה. תָּמְהוּ וְהָלְכוּ. בֵּין כָּךְ הֵאִיר הַיּוֹם, הֶחֱזִירוּ רֹאשׁ, וְרָאוּ כָּל הַמִּדְבָּר מְכֻסֶּה בְּעַנְנֵי כָבוֹד מְאִירִים, נוֹצְצִים בִּגְוָנִים רַבִּים."],[3,"","אָמְרוּ זֶה לָזֶה, וַדַּאי הַקָּדוֹשׁ בָּרוּךְ הוּא רוֹצֶה לְהִשְׁתַּבֵּחַ בַּתִּשְׁבַּחַת שֶׁל דּוֹר הַמִּדְבָּר, שֶׁלֹּא הָיָה בָּעוֹלָם דּוֹר עֶלְיוֹן כְּדוֹר זֶה, וְלֹא יִהְיֶה עַד שֶׁיָּבֹא מֶלֶךְ הַמָּשִׁיחַ. וַדַּאי כָּל מַה שֶּׁהֶרְאָה לָנוּ הַקָּדוֹשׁ בָּרוּךְ הוּא, לֹא הָיָה אֶלָּא בִּשְׁבִיל לְהוֹדִיעֵנוּ חֲבִיבוּת רִבּוֹנָם עֲלֵיהֶם, לְהוֹדִיעַ שֶׁיֵּשׁ לָהֶם חֵלֶק טוֹב, וְהֵם בְּנֵי עוֹלָם הַבָּא. וְלֶעָתִיד לָבֹא כְּשֶׁיָּקִים הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת הַמֵּתִים, עֲתִידִים אֵלּוּ לַעֲמֹד לִתְחִיָּה בָּרִאשׁוֹנָה, כְּמוֹ שֶׁנֶּאֱמַר (ישעיהכו) יִחְיוּ מֵתֶיךְ, וְאֵלֶּה הֵם דּוֹר הַמִּדְבָּר."],[4,"","אָמַר לוֹ, הַאִם דָּבָר חָדָשׁ יָדַעְתָּ שֶׁאֲנִי מְעֻרְטָל מִמֶּנּוּ? אָמַר לוֹ, אֱמֹר. אָמַר, קוֹל הַחוֹזֵר רָצִיתִי לָדַעַת. בֶּן אָדָם נוֹתֵן קוֹל בַּשָּׂדֶה אוֹ בְמָקוֹם אַחֵר, וְחוֹזֵר קוֹל אַחֵר וְלֹא יָדוּעַ. אָמַר לוֹ, אִי חָסִיד קָדוֹשׁ, עַל דָּבָר זֶה כַּמָּה קוֹלוֹת הִתְעוֹרְרוּ, וְכַמָּה דִקְדּוּקִים הָיו לִפְנֵי רֹאשׁ הַיְשִׁיבָה. וּכְשֶׁיָּרַד רֹאשׁ הַיְשִׁיבָה, אָמַר, כָּךְ פֵּרְשׁוּהָ דָּבָר בִּישִׁיבַת הָרָקִיעַ, וְסוֹד נִכְבָּד הוּא."],[5,"","בֹּא וּרְאֵה, שְׁלֹשָׁה קוֹלוֹת הֵם שֶׁלֹּא נֶאֱבָדִים לְעוֹלָמִים, פְּרָט לְקוֹל הַתּוֹרָה וְהַתְּפִלָּה, שֶׁאֵלֶּה עוֹלִים לְמַעְלָה וּבוֹקְעִים רְקִיעִים. אֲבָל קוֹלוֹת אֲחֵרִים הֵם שֶׁלֹּא עוֹלִים וְלֹא אוֹבְדִים."],[6,"","וְהֵם הַשְּׁלֹשָׁה: קוֹל הַחַיָּה בְּשָׁעָה שֶׁהִיא עַל הַמַּשְׁבֵּר, אוֹתוֹ קוֹל מְשׁוֹטֵט וְהוֹלֵךְ בָּאֲוִיר מִסּוֹף הָעוֹלָם וְעַד סוֹף הָעוֹלָם. קוֹל הַבֶּן אָדָם בְּשָׁעָה שֶׁיּוֹצֵאת נִשְׁמָתוֹ מִגּוּפוֹ, אוֹתוֹ קוֹל מְשׁוֹטֵט וְהוֹלֵךְ בָּאֲוִיר מִסּוֹף הָעוֹלָם וְעַד סוֹף הָעוֹלָם. קוֹל הַנָּחָשׁ בְּשָׁעָה שֶׁפּוֹשֵׁט עוֹרוֹ, אוֹתוֹ קוֹל מְשׁוֹטֵט בָּאֲוִיר וְהוֹלֵךְ מִסּוֹף הָעוֹלָם וְעַד סוֹף הָעוֹלָם."],[7,"","אִי חָסִיד קָדוֹשׁ, כַּמָּה דָבָר זֶה גָּדוֹל וְנִכְבָּד. אֵלֶּה הַקּוֹלוֹת מַה נַּעֲשֶׂה מֵהֶם, וּלְאֵיזֶה מָקוֹם נִכְנָסִים וְשׁוֹרִים? אֵלֶּה הֵם קוֹלוֹת צַעַר, וְהוֹלְכִים וּמְשׁוֹטְטִים בָּעוֹלָם בָּאֲוִיר, וְהוֹלְכִים מִסּוֹף הָעוֹלָם וְעַד סוֹף הָעוֹלָם, וְנִכְנָסִים לְתוֹךְ נְקִיקִים וּמְחִלּוֹת עָפָר וְנִסְתָּרִים שָׁם. וּכְשֶׁנּוֹתֵן אָדָם קוֹל, הֵם מִתְעוֹרְרִים לְאוֹתוֹ קוֹל. קוֹל נָחָשׁ לֹא מִתְעוֹרֵר לְקוֹל אָדָם. אֵיךְ יִתְעוֹרֵר? בְּמַכָּה. כְּשֶׁמַּכֶּה אָדָם מַכָּה, מִתְעוֹרֵר קוֹל הַנָּחָשׁ שֶׁנִּסְתָּר אֵלָיו אוֹתוֹ קוֹל, וְלֹא קוֹל אַחֵר. קוֹל מִתְעוֹרֵר אַחַר קוֹל, מִין אַחַר מִינוֹ."]]],[["וְעַל דָּא בְּיוֹמָא דְרֹאשׁ הַשָּׁנָה, קוֹל שׁוֹפָר, אִתְּעַר קוֹל שׁוֹפָר אַחֲרָא, זִינָא בָּתַר זִינֵיהּ אָזְלָא. אָרְחֵיהּ דְּנָחָשׁ לְבִישׁ אִיהוּ, לְקָטְלָא וּלְמָחָאָה, בְּהַהוּא קָלָא מַמָּשׁ, לָא אִתְּעַר קָלָא דְּהַאי נָחָשׁ, אֶלָּא בָּתַר זִינֵיהּ. וְדָא אִיהוּ, כַּד בַּר נָשׁ מָחֵי בְּחוּטְרָא בְּאַרְעָא, וְקָרֵי לֵיהּ לְזִינֵיהּ, כְּדֵין אִתְּעַר הַהוּא קָלָא דְּנָחָשׁ, לְאָתָבָא לְזִינֵיהּ. וְרָזָא דָּא אִיהוּ טְמִירוּ.","אָמַר רַבִּי שִׁמְעוֹן, וַדַּאי מִלָּה דָּא מִלָּה סְתִימָא הִיא. וְתַוַּוהְנָא אֵיךְ שְׁלֹמֹה מַלְכָּא לָא יָדַע מִלָּה דָּא. אָמַר לֵיהּ, שְׁלֹמֹה מַלְכָּא מִנְדַּע יָדַע, וְלָא כָּל כַּךְ. אֲבָל מַה דְּלָא יָדַע, הַהוּא קָלָא מַה תּוֹעַלְתָּא אִית בָּהּ, וְהֵיךְ יָתְבָא.","וְרַב מְתִיבְתָּא הָכִי אָמַר, דִּקְדוּקָא דָּא לָא יָדַע שְׁלֹמֹה מַלְכָּא, דְּהָא הַהוּא קָלָא, אִיהִי כְּלִילָא רוּחָא וְנַפְשָׁא, וְהַבַל גַּרְמֵי מֵעִצְּבוֹנָא דְּבִשְׂרָא, וּמְשַׁטְּטָא בַּאֲוִירָא, וְכָל חַד מִתְפְּרַשׁ דָּא מִן דָּא. וְכַד מָטָא לְהַהוּא אֲתָר דְּעָאל בֵּיהּ, יָתְבָא כְּמֵיתָא. וְכָל אִינּוּן חַרְשִׁין וְקוֹסְמִין יַדְעִין אַתְרִין אִלֵּין בְּחַרְשַׁיְיהוּ, וְגַחְנִין לְאַרְעָא, וְשַׁמְעִין קָלָא דָּא, דְּמִתְחַבְּרוּן אִינּוּן רוּחָא וְנַפְשָׁא, וְהַבַל דְּגַרְמֵי, וְאוֹדְעִין מִלָּה. וְדָא אִיהוּ (ישעיה כט) אוֹב מֵאֶרֶץ. וְעַל דָּא רָדִיף שְׁלֹמֹה, לְמִנְדַּע מַה דְּאִתְעָבִיד מֵהַהוּא קָלָא, וְלָא יָדַע. זַכָּאָה חוּלָקָךְ רִבִּי, דְּאִתְבְּרִיר לָךְ מִלָּה דִּקְשׁוֹט.","כַּד בַּר נָשׁ אִתְּעַר קָלָא, מִיַּד (מתחברן) אִתְּעַר הַהוּא קָלָא, וְלֵית לֵיהּ רְשׁוּ לְאַרְכָּא יַתִּיר. אֶלָּא כְּעֵין הַהוּא קָלָא, דְּאִתְּעַר בַּר נָשׁ, וְלָא יַתִּיר. וְאִי אָרִיךְ בַּר נָשׁ קָּלֵיה, אִיהוּ לֹא אֲרִיךְ כָּל כַּךְ בָּהֲדֵיה, אֶלָא לְסוֹפָא דְקָלָא, בְּגִין דְּלָא יָכִיל לְאֲרְכָּא. מַאי טַעֲמָא, בְּגִין דְּכַד נָפְקָא בְּקַדְמִיתָא, אִתְאֲרִיךְ מִסַּיְיפֵי עָלְמָא עַד סַיְיפֵי עָלְמָא, וְהַשְׁתָּא דְּעָאל תַּמָּן, לָא יָכִיל לְאַרְכָּא קָלָא, דְּהָא לֵית לֵיהּ אֲתָר לְאִתְפַּשְׁטָא תַּמָּן כִּדְבְּקַדְמֵיתָא.","חַדֵּי רַבִּי שִׁמְעוֹן וְאָמַר, אִלְמָלֵי לָא זָכֵינָא לְמִשְׁמַע, אֶלָּא מִלָּה דָּא, דַּי לִי, לְמֶהֱוִי חַדֵּי, דְּזָכֵינָא לְמִשְׁמַע מִלִּין דִּקְשׁוֹט, דְּהַהוּא עָלְמָא. אָמַר לֵיהּ, אִי חֲסִידָא קַדִּישָׁא. אִלְמָלֵי יַדְעַת חֶדְוָה דְּמִלִּין בְּהַהוּא עָלְמָא קַמֵּי רַב מְתִיבְתָּא, תְּהֵא חַדֵּי יַתִּיר.","אָמַר לֵיהּ, מַאי חִדּוּשָׁא הֲוָה הַשְׁתָּא, כַּד אָתִית לְגַבָּי. אָמַר, רַב מְתִיבְתָּא פָּתַח וְאָמַר, (בראשית מ״ו:ד׳) וְיוֹסֵף יָשִׁית יָדוֹ עַל עֵינֶיךָ. חֶדְוָה הוּא. אֲמַאי סְתִימוּ דְּעַיְינִין לְמִיתָא. בְּגִין דְּעַיְינִין, גַּוְונִין דְּהַאי עָלְמָא אִינּוּן, וְחֵיזוּ וּדְיּוּקְנָא דְּהַאי עָלְמָא בְּהוּ, אִיהוּ אַסְתִּים מִנֵּיהּ הַאי עָלְמָא, חֵיזוּ דְּהַאי עָלְמָא. אַסְתִּימוּ עֵינוֹי, כָּל חֵיזוּ דְּהַאי עָלְמָא, הָא אִתְחֲשָׁךְ מִנֵּיהּ. וְחֶשְׁכִין מִנֵּיהּ חֵיזוּ דְּעֵינוֹי, לֵית לֵיהּ חֵיזוּ בְּהַאי עָלְמָא, מִתַּמָּן וּלְהָלְאָה. אָמַר רַבִּי שִׁמְעוֹן, יָאוּת תִּקּוּנָא דְּקַדְמָאֵי, וְחָכְמְתָא דִּלְהוֹן יַתִּיר מִמַּלְאָכִין קַדִּישִׁין.","אָמַר לֵיהּ, יוֹסֵף אֲמַאי יָשִׁית יָדוֹ מִכָּל בְּנוֹי. וְאִי תֵּימָא עַל בְּשׂוֹרָה דִּילֵיהּ, מִבָּעֵי לֵיהּ וְיוֹסֵף חַי תִּרְאֶה. אָמַר לֵיהּ יָשִׁית יָדוֹ בְּגִין דִּרְחִימוּ דִּילֵיהּ הֲוָה, וּבְגִין כָּךְ דָּא אַסְתִּים מִינֵּיהּ נְהִירוּ דְּהַאי עָלְמָא, וְדָא נָטִיל לֵיהּ. מַאן דְּאַסְתִּים עֵינוֹי, רְחִימָא דִּילֵיהּ אַחְזֵי הָכִי: חֵיזוּ דִּילָךְ דְּהַאי עָלְמָא אִתְאֲבִיד, הָא אֲנָא חֵיזוּ דִּילָךְ בְּאַתְרָךְ. מִכָּאן וּלְהָלְאָה יִתַּתְקְנוּן לָךְ חֵיזוּ אַחֲרָא, דְּהַהוּא עָלְמָא.","אָמַר רַבִּי שִׁמְעוֹן, מַה אִתְהֲנֵי הַאי לְמִּיתָא, וּמַה תּוֹעַלְתָּא אִית לֵיהּ בְּהַאי. מַאן דְּיִבְעֵי לְמִשְׁאַל יוֹמָא מַה דְּאִצְטְרִךְ לְאַפְקְחָא עֵינוֹי, בְּגִין לְאַחֲזָאָה דְּעֲדַיִין אִזְדְּמַן אִיהוּ, לְאָתָבָא לְחֵיזוּ דְּהַאי עָלְמָא כִּדְבְּקַדְּמִין.","אָמַר לֵיהּ אִי חֲסִידָא קַדִּישָׁא, וַדַּאי אִי לָא אַסְתִּים מִנֵּיהּ כָּל חֵיזוּ דְּהַאי עָלְמָא, וְלָא אִתְאֲבִיד כֹּלָּא מִנֵּיהּ, לָא לֶהֱוִי לֵיהּ חֵיזוּ וְחוּלָקָא דְּהַהוּא עָלְמָא. עָלְמָא דָּא, בְּהִפּוּכָא אִיהוּ מֵהַהוּא עָלְמָא דַּאֲנָן בֵּיהּ, דִּבְזִמְנָא דִּתְחִיַית מֵתַיָּיא, אֲפִילוּ כְּחוּטָא דְּשַׂעֲרָא לָא הֲוָה מֵעוֹבָדָא דְּהַאי עָלְמָא, דְּכֹלָּא אִתְאֲבִיד בְּקַדְמִיתָא, (טלא יבטיל ליה, וישוי ליה) בְּהַהוּא טַלָּא (בקדמיתא) וְיִתְעֲבָר מִנֵּיהּ כָּל זוּהֲמָא, וּלְבָתַר יִתְעֲבִיד כַּחֲמִירָא דָּא, וּמִנֵּיהּ יִתְעֲבִיד גּוּפָא בִּרְיָה חַדְתָּא, כַּךְ הָכָא."],[[0,"וע״ד ביומא דר״ה וכו׳:","וע״כ ביום ראש השנה, קול שופר מעורר קול שופר אחר, שה״ס קול הבינה (כנ״ל ויקרא ק׳ ד״ה פירוש) מין הולך אחד מינו. דרך הנחש הוא לרע, להרוג ולהכות, וע״כ בקולו של אדם ממש אין מתעורר קול הנחש, אלא אחר מינו, וזה הוא כשאדם מכה במקל בארץ, שקול הזה קורא את מינו, אז נתעורר קול ההוא של הנחש לענות אל מינו. וסוד זה הוא נסתר."],[1,"אר״ש ודאי מלה וכו׳:","א\"ר שמעון, ודאי דבר זה היא דבר סתום. ותמה אני איך שלמה המלך לא ידע דבר זה, שאמר שלשה אלה וגו׳ דרך נחש עלי צור. אמר לו, שלמה המלך ידע, ולא כל כך. אבל מה שלא ידע, הוא שלא ידע קול ההוא איזה תועלת יש בו ואיך הוא מתיישב."],[2,"ורב מתיבתא הכי וכו׳:","ורב מתיבתא אמר כך. דקדוק זה לא ידע שלמה המלך, אשר קול ההוא הוא כלול מן רוח, נפש, והבל העצמות מעצבון של הבשר. והקול משוטט באויר, וכל אחד מאלו הג', נפרדו זה מזה. וכשהקול מגיע למקום ההוא שנכנס בו, הוא יושב כמת. וכל אלו המכשפים והקוסמים יודעים מקומות אלו בכשפיהם, וכופפים עצמם לארץ ושומעים קול זה, שרוח נפש והבל העצמות מתחברים בו. והם מודיעים הדבר ששאלו. וזה הוא אוב מארץ. וע״כ רדף שלמה לדעת מה שנעשה מקול הזה, ולא ידע. אשרי חלקך רבי, שנתברר לך דבר אמת. \u0003מעצבונא דבשרא,\u0004 פירושו, שההבל, הוא עיצוב של הגוף, מלשון ידיך עצבוני ויעשוני (איוב י׳ ח׳) שהוא אינו מסתלק מן הגוף כמו הנפש."],[3,"כד ב״נ אתער וכו׳:","כשאדם מעורר קול, מיד מתעורר קול ההוא, של החיה או של יציאת נשמה, ואין לו רשות להאריך יותר, אלא בשוה כעין אותו הקול שעורר האדם, ולא יותר. ואם האדם מאריך קולו, הוא אינו מאריך כל כך עמו, אלא נתעורר לסוף הקול של האדם, משום שאינו יכול להאריך. מהו הטעם. הוא, כי כשיצא מתחילה נתארך מסוף העולם עד סוף העולם, ועתה שנכנס שם, אינו יכול להאריך הקול, כי אין לו מקום להתפשט שם כבתחילה."],[4,"חדי ר״ש ואמר וכו׳:","שמח ר\"ש ואמר, אם לא זכיתי לשמוע רק דבר זה היה די לי להיות שמח, שזכיתי לשמוע דברי אמת של עולם ההוא. אייל, אהה חסיד קדוש, אם היית יודע שמחת הדברים בעולם ההוא לפני ראש הישיבה, היית שמח יותר."],[4,"","ביאור המאמר. ג׳ מיגי אורות יש שמאירים ואח״כ מתבטלים. ויש להבין אותם, אם דרכם להתבטל, למה האירו בכלל. ועליהם סובב כל המאמר הזה, לבאר שאינם נאבדים, אע״פ שמתבטלים. ואלו ג׳ אורות ה״ס ג׳ קולות ההולכים מסוף העולם עד סוף העולם, כלומר שמדרגתם שלמה לגמרי, ע״ד שאמרו רואה מסוף העולם עד סופו. וכאן אינו אומר רואה, משום שהם אורות דשמאל בלי ימין, שהם אינם מאירים אלא בבחינת ג״ר דו\"ק. שה״ס נפש רוח, ונקרא ג״כ קול. אלא מפני שהם שלמים בג״ר דחכמה דשמאל, ע״כ אומר עליהם, מסוף העולם עד סוף העולם."],[4,"","וז״ש (באות רט״ז) \u0003ת״ח ג׳ קלין אינון דלא אתאבידו לעלמין\u0004 וכו׳ \u0003דלא סלקין ולא אתאבידו,\u0004 כי להיותם הארת שמאל בלי ימין, אינם יכולים לעלות למעלה מפני הדין שבהם. ואע״פ שאח״כ מתמעטים, מ״מ אינם נאבדים, כמ״ש לפנינו. וז״ש (באות רי״ז) \u0003קול חיה בשעתא דאיהי על קלביטא,\u0004 דהיינו שצועקת ע׳ קולות על האבנים, והיא רומזת על חיה העליונה, שהיא המלכות, בעת הולדת נשמות, שאז רחמה צר ואינה יכולה ללדת, שהוא מטעם שאז מגולה בה הארת החכמה שבשמאל בלי ימין (כמ״ש באורך לעיל משפטים דף ק׳ ד״ה פנימיות ע״ש) וז״ש, \u0003ההוא קלא משטטא ואזלא באוירא מסייפי עלמא עד סייפי עלמא,\u0004 דהיינו שיש בקול הזה הארת הג״ר דחכמה, שה״ס מסוף העולם עד סופו. כי העולם ה״ס מלכות, וכשהחכמה מקובלת מקו אמצעי, שהשמאל והימין כלולים זב״ז, אין החכמה ממלאה אותה כולה, מסוף עד סוף, אלא רק הו״ק שלה בלבד, כנודע. אבל כשמאיר השמאל בלי ימין החכמה ממלאה אותה כולה. אפילו הג״ר שלה. וז״ס מסוף העולם עד סופו."],[4,"","קול הב׳ הוא, \u0003קול דבר נש בשעתא דנפיק נשמתיה מגופיה,\u0004 כי אז מתגלה בו ג״כ הארת השמאל בלי ימין, בבחינת הג״ר דחכמה, וע״כ נקרא אז יום הדין הגדול, כי גדול, יורה ג״ר, וז״ס שלא נפטר אדם מן העולם עד שרואה את השכינה (כמ״ש לעיל וירא אות ל׳ ע״ש) וז״ש, \u0003ההוא קלא\u0004 וכו׳ \u0003מסייפי עלמא עד סייפי עלמא,\u0004 דהיינו שהוא הארת ג״ר כנ״ל."],[4,"","קול הג' הוא. \u0003קול נחש בשעתא דפשיט משכיה,\u0004 כי בעת שפושט עורו, שהוא ממלכות, תחילה היא עולה ונאחז בשמאל דבינה, בלי ימין, ואח״כ מעלים המלכות לבינה, והוא חוזר ומתמעט בסוד המוקש שמשימים לנחש (כמ״ש באורך לעיל וארא אות ק״ט בהסולם ע״ש) ונמצא בעת שנאחז בשמאל בלי ימין דבינה, \u0003ההוא קלא\u0004 וכו׳ \u0003מסייפי עלמא עד סייפי עלמא.\u0004 להיותו ג״ר דחכמה הממלא את כל העולם כנ״ל."],[4,"","אמנם כל אלו ג׳ הארות השמאל אינם אלא לשעתם, כי אח״כ חוזרים ומתמעטים. כי החיה על האבנים, הרי אינה יכולה ללדת מחמת הארת השמאל, וע״כ בא נחש ונשיך בערייתא, והארת השמאל מסתלקת (כמ״ש במשפטים דף ק׳ ד״ה פנימיות). וכן קול אדם בשעת יציאת נשמה, הנה בביאת מלאך המות מסתלקת ממנו הארת השמאל והוא מת. וכן קול נחש, הנה תיכף מעלים המלכות לבינה, והארת השמאל מסתלקת. (כמ״ש לעיל וארא אות ק״ט בהסולם ע״ש) הרי שכל אלו ג׳ קולות שהיו תחילה מסוף העולם עד סוף העולם, חוזרים ומסתלקים."],[4,"","וזה אמרו (באות רי״ח) \u0003אלין קלין מה אתעביד מנייהו ולאן אתר עאלין ושארן,\u0004 כיון שנעלמים תיכף, למה יצאו מתחילה, ובהכרח שנעשה מהם דבר מה, ושואל, מה נעשה מהם. וז״ש \u0003אלין קלין\u0004 וכו׳ \u0003ועאלין גו נקיקין ומחילין דעפרא,\u0004 דהיינו אחר שנסתלק מהם הארת השמאל באים בנקיקי הסלעים ובמחילות עפר, ששם כמו מקום קבורתם, דהיינו שנתמעטו עד לאפס. \u0003ואתטמרן תמן,\u0004 שהם שם בהסתר במיעוט."],[4,"","והאדם הנותן קולו רומז לאדם העליון ז״א שבסוד הקול שלו הוא מיחד הימין והשמאל זה בזה, ואז יש תקון גם לג' קולות הנ״ל, עם שליטת קו האמצעי. אבל לא לגמרי כמו שהיו מתחילה. כמ״ש לפנינו. וז״ש, \u0003וכד יהיב ב״נ קלא אינון מתערין לגבי ההוא קלא,\u0004 שמתעוררים להדבק בקולו של אדם שעי״ז הם מקבלים תקון ממנו כנ״ל. ויש בזה ב׳ בחינות. א׳, קולו של אדם, שהוא מרמז על ז״א, שאע״פ שמיחד שניהם מ״מ רק הימין שולט בו ולא השמאל. ב׳, קול הכאת מקל על הארץ, שהארץ שה״ס מלכות, משמעת קול. ומתיחדים בה ע״י קולה זה הימין והשמאל. וכיון שרומז על המלכות, נמצא שיש בה גילוי לשמאל, כי המלכות נבנית משמאל. ולפיכך קול אדם מספיק לתיקון ב׳ קולות הראשונים, קול חיה, וקול אדם לפני יציאת נשמתו, אבל לא לתקון קול נחש, להיותו כולו רק שמאל. ולתקון קולו של נחש, שהוא שמאל צריכים לקול הנשמע מארץ, שה״ס מלכות, שבנינה משמאל. וז\"ש (באות רי״ח) \u0003קלא דנחש לא אתער לגבי קלא דב״נ.\u0004 כי אינו מינו, כי האדם רומז לז״א שכולו ימין וחסד, והנחש כולו שמאל. וז״ש, \u0003כד מחי ב״נ מחאה\u0004 וכו׳ \u0003ודא איהו כד בר נש מחי בחוטרא בארעא\u0004 וכו׳ \u0003כדין אתער ההוא קלא דנחש לאתבא לזיניה\u0004 (באות רי״ט) שכיון שקול הנשמע מארץ הוא מינו של הנחש הוא מקבל תקון מקול הזה."],[4,"","וז״ש (באות ר״כ) \u0003ותווהנא איך שלמה מלכא לא ידע מלה דא,\u0004 שאמר שלשה אלה נפלאו ממני וגו׳ דרך נחש עלי צור, שפירושו, קולו של נחש, הנסתר בנקיקי הסלע. ולמה נפלא ממנו. ומשיב. \u0003אבל מה דלא ידע ההוא קלא, מה תועלתא אית בה, ואיך יתבא.\u0004 שלא ידע איזה תקון הוא מקבל, ואיך הוא שם בנקיקי הסלע. כי אם מקבל תקון, למה אינו יוצא משם. ואם אינו יכול לצאת משם הרי שאינו מקבל תקון, וחזר הקושיא למקומה, \u0003מה אתעביד מנייהו\u0004 (כבאות רי״ח)"],[4,"","וז״ש (באות רכ״א) \u0003ההוא קלא איהי כלילא רוחא ונפשא והכל גרמי,\u0004 דהיינו מטרם שנתמעט, היה בו ג׳ מדרגות אלו קשורות זו בזו, כי שיעור קומתו היה עד ג״ר דרוח כנ״ל. \u0003וכל חד מתפרש דא מן דא,\u0004 דהיינו אחר שנתמעט, נסתלקו ממנו האורות דנפש רוח, ונשאר בהבל דגרמי. ונמצאו נפרדות זו מזו, וז\"ש \u0003יתבא כמיתא,\u0004 שהבל דגרמי הנשאר הוא כמו מת, כי גם במת נשאר הבל דגרמי, שאינו מסתלק מקברו. ולפיכך בעת שנתעורר ומקבל תקון מקול ההכאה, חוזרות ג׳ מדרגות אלו ומתחברות, אבל לא בג״ר דרוח, כמקודם לכן, אלא בו״ק דרוח. כמ״ש לפנינו. וז\"ש, \u0003וכל אינון חרשין\u0004 וכו׳ \u0003ושמעין קלא דא דמתחברן אינון רוחא ונפשא והבל דגרמי,\u0004 דהיינו מחמת שקבלו תקון מקול ההכאה בארץ, כנ״ל. ואז הנחש מודיע להם צרכי הכשפים שלהם, וז״ש \u0003ואודעין מלה.\u0004 וז״ש, \u0003ועל דא רדיף שלמה למנדע, מה דאתעביד מההוא קלא, ולא ידע.\u0004 שלא ידע תקון זה שנעשה מסוד הכאה בארץ מהו."],[4,"","וז״ש (באות רכ״ב) \u0003ולית ליה רשו לארכא יתיר\u0004 וכו'. כיון שג׳ קולות הנ״ל מקבלים תקונם מן קולו של אדם ומקול הכאת אדם בארץ כנ״ל, אין בהם יותר אריכות, דהיינו הארת חכמה הנק׳ ארוך, מקול אדם. כלומר, כיון שקול אדם אינו מתקן עם יחוד ימין ושמאל, אלא ו״ק דחכמה דשמאל, ע״כ גם ג׳ קולות הנ״ל אינם מקבלים תקונם בשלמות כמו שהיו תחילה, מסוף העולם עד סוף העולם, אלא רק ו״ק, כקולו של אדם. \u0003ואי אריך בר נש קליה,\u0004 דהיינו בעת שהוא ממשיך מצד ימין, הוא מאריך וממשיכו ממעלה למטה, \u0003איהו לא אריך כל כך בהדיה אלא לסופא דקלא,\u0004 כי להיותם משמאל לבד, ואין להם חלק בימין, ע״כ אינם יכולים להאריך שפירושו להמשיך חכמה ממעלה למטה. כי גם בקולו של אדם לא נמצא זה. ו\"ש, \u0003בגין דכד נפקא בקדמיתא אתאריך מסייפי עלמא עד סייפי עלמא,\u0004 דהיינו שהיה נמשכות הג״ר דשמאל, הממלא כל העולם, כנ״ל, \u0003והשתא דעאל תמן,\u0004 דהיינו שנתמעטו ובאו במחילות עפר, \u0003לית ליה אתר לאתפשטא תמן,\u0004 כי המיעוט דמחילות עפר רובץ עליהם, כי קולו של אדם אינו מתקן את מיעוט הזה. וע״כ אינם חוזרים לבחינת מסוף העולם עד סופו, ונשארים במחילות עפר, ואינם יכולים להתפשט."],[5,"א״ל מאי חדושא וכו׳:","אמר לו, איזה חדוש היה עתה כשבאת אלי. אמר, רב מתיבתא פתח ואמר, ויוסף ישית ידו על עיניך. הוא בשורה של שמחה. שואל, למה צריכים סתימת עינים למת. ומשיב, משום שהעינים, הם הגוונים של עולם הזה, והמראה והצורה של עולם הזה נמצא בהם, וע״כ בסתימת עינים הוא סותם ממנו עולם הזה, והמראה של עולם הזה. כי כשנסתמו עיניו כל מראה של עולם הזה נחשך לו, ואם מחשיכים לו מראה עיניו, אין לו עוד מראה בעולם הזה משם והלאה. א״ר שמעון, יפה הם התקונים של הראשונים, וחכמתם היא יתרה ממלאכים הקדושים."],[6,"א״ל יוסף אמאי וכו׳:","אמר לו. יוסף, למה ישית ידו, מכל בניו. ואם תאמר שאמר לו כן משום הבשורה שלו, שיוסף עודנו חי. א״כ היה צריך לומר ויוסף חי תראה, ולמה אמר ויוסף ישית ידו על עיניך. אמר לו, \u0003ישית ידו,\u0004 הוא משום שהיה אוהבו, ומשום זה הסתים ממנו האור של עולם הזה, והוא לקח אותו, מי שסותם עיניו של אוהבו, מראה כך: המראה שלך מעולם הזה, נאבד, ואני לוקח המראה שלך במקומך, מכאן ולהלאה, יתקנו לך מראה אחרת של עולם ההוא. וע״כ ניתן הדבר ליוסף, משום שהיה אהובו של יעקב יותר מכל בניו."],[7,"אר״ש מה אתהני וכו׳:","א״ר שמעון, מה יועיל זה אל המת. ואיזה תועלת יש בו בזה. מי שירצה לשאול, צריכים לומר לו, שצריכים לפקוח את עיני המת, כדי להראות שעוד הוא מוכן לחזור אל המראה של עולם הזה כבתחילה, דהיינו שיקום בתחית המתים."],[8,"א״ל אי חסידא וכו׳:","אמר לו אהה חסיד קדוש, ודאי, אם לא נסתם ממנו כל מראה של עולם הזה, ולא נאבד ממנו הכל, לא יהיה לו מראה וחלק בעולם ההוא, כי עולם הזה הוא הפוך מעולם ההוא שאנו בו, ובזמן תחיית המתים אפילו כחוט השערה לא יהיה ממעשה עולם הזה, כי הכל יאבד תחילה באותו הטל, דהיינו בטל התחיה. ויעביר ממנו כל הזוהמא, ואח״כ הוא נעשה כעיסה זו, וממנו יעשה הגוף כבריה חדשה. כך כאן. בעולם העליון גם מטרם התחיה."]],[[0,"","וְעַל כָּךְ בְּיוֹם רֹאשׁ הַשָּׁנָה קוֹל שׁוֹפָר מְעוֹרֵר קוֹל שׁוֹפָר אַחֵר, מִין אַחַר מִינוֹ הוֹלֵךְ. דֶּרֶךְ הַנָּחָשׁ הוּא לְרַע, לַהֲרֹג וּלְהַכּוֹת. בְּאוֹתוֹ קוֹל מַמָּשׁ לֹא מִתְעוֹרֵר קוֹל נָחָשׁ זֶה אֶלָּא אַחַר מִינוֹ. וְזֶהוּ כְּשֶׁאָדָם מַכֶּה בְּמַקֵּל בָּאָרֶץ וְקוֹרֵא לוֹ לְמִינוֹ, אָז מִתְעוֹרֵר אוֹתוֹ קוֹל הַנָּחָשׁ לְהָשִׁיב לְמִינוֹ. וְסוֹד זֶה הוּא נִסְתָּר."],[1,"","אָמַר רַבִּי שִׁמְעוֹן, וַדַּאי דָּבָר זֶה הוּא דָּבָר נִסְתָּר, וְתָמַהְנוּ אֵיךְ שְׁלֹמֹה הַמֶּלֶךְ לֹא יָדַע דָּבָר זֶה. אָמַר לוֹ, שְׁלֹמֹה הַמֶּלֶךְ יָדוֹעַ יָדַע, וְלֹא כָּל כָּךְ. אֲבָל מַה שֶּׁלֹּא יָדַע, אוֹתוֹ קוֹל מַה תּוֹעֶלֶת יֵשׁ בּוֹ, וְאֵיךְ יוֹשֵׁב?"],[2,"","וְרֹאשׁ הַיְשִׁיבָה כָּךְ אָמַר, דִּקְדּוּק זֶה לֹא יָדַע שְׁלֹמֹה הַמֶּלֶךְ, שֶׁהֲרֵי אוֹתוֹ קוֹל כָּלוּל רוּחַ וְנֶפֶשׁ, וְהֶבֶל עֲצָמוֹת מֵעִצְּבוֹן בָּשָׂר, וּמְשׁוֹטֵט בָּאֲוִיר, וְכָל אֶחָד נִפְרָד זֶה מִזֶּה. וּכְשֶׁמַּגִּיעַ לְאוֹתוֹ מָקוֹם שֶׁנִּכְנַס בּוֹ, יוֹשֵׁב כְּמֵת. וְכָל אוֹתָם מְכַשְּׁפִים וְקוֹסְמִים יוֹדְעִים מְקוֹמוֹת אֵלּוּ בְּכִשְׁפֵיהֶם, וְגוֹחֲנִים לָאָרֶץ, וְשׁוֹמְעִים קוֹל זֶה שֶׁמִּתְחַבְּרִים אוֹתָם רוּחַ וְנֶפֶשׁ וְהֶבֶל עֲצָמוֹת, וּמוֹדִיעִים דָּבָר, וְזֶהוּ (ישעיהכט) אוֹב מֵאֶרֶץ. וְעַל זֶה רָדַף שְׁלֹמֹה לָדַעַת מַה נַּעֲשָׂה מֵאוֹתוֹ קוֹל, וְלֹא יָדַע. אַשְׁרֵי חֶלְקְךְ, רַבִּי, שֶׁהֻבְרַר לְךְ דְּבַר אֱמֶת."],[3,"","כְּשֶׁבֶּן אָדָם מְעוֹרֵר קוֹל, מִיָּד (מתחברים) מִתְעוֹרֵר אוֹתוֹ קוֹל, וְאֵין לוֹ רְשׁוּת לְהַאֲרִיךְ יוֹתֵר, אֶלָּא כְּעֵין אוֹתוֹ קוֹל שֶׁעוֹרֵר הָאָדָם, וְלֹא יוֹתֵר. וְאִם הֶאֱרִיךְ הָאִישׁ קוֹלוֹ, הוּא לֹא מַאֲרִיךְ כָּל כָּךְ אִתּוֹ, אֶלָּא לְסוֹף הַקּוֹל, מִשּׁוּם שֶׁלֹּא יָכוֹל לְהַאֲרִיךְ. מָה הַטַּעַם? מִשּׁוּם שֶׁכְּשֶׁיּוֹצֵא בַּהַתְחָלָה, מִתְאָרֵךְ מִסּוֹף הָעוֹלָם וְעַד סוֹף הָעוֹלָם. וְכָעֵת שֶׁנִּכְנָס לְשָׁם, לֹא יָכוֹל לְהַאֲרִיךְ קוֹל, שֶׁהֲרֵי אֵין לוֹ מָקוֹם לְהִתְפַּשֵּׁט שָׁם כְּבַתְּחִלָּה."],[4,"","שָׂמַח רַבִּי שִׁמְעוֹן וְאָמַר, אִלְמָלֵא לֹא זָכִיתִי לִשְׁמֹעַ אֶלָּא דָּבָר זֶה - דַּי לִי לִהְיוֹת שָׂמֵחַ שֶׁזָּכִיתִי לִשְׁמֹעַ דְּבַר אֱמֶת שֶׁל אוֹתוֹ עוֹלָם. אָמַר לוֹ, אִי חָסִיד קָדוֹשׁ, אִלְמָלֵא יָדַעְתָּ חֶדְוַת דִּבְרֵי אוֹתוֹ עוֹלָם לִפְנֵי רֹאשׁ הַיְשִׁיבָה, תִּשְׂמַח יוֹתֵר."],[5,"","אָמַר לוֹ, מַה חִדּוּשׁ הָיָה כָעֵת כְּשֶׁבָּאתָ אֵלַי? אָמַר, רֹאשׁ הַיְשִׁיבָה פָּתַח וְאָמַר, (בראשית מו) וְיוֹסֵף יָשִׁית יָדוֹ עַל עֵינֶיךְ. חֶדְוָה הִיא. מַדּוּעַ סְתִימַת הָעֵינַיִם לְמֵת? מִשּׁוּם שֶׁהָעֵינַיִם הֵן גְּוָנִים שֶׁל הָעוֹלָם הַזֶּה, וּמַרְאֵה וּדְמוּת הָעוֹלָם בָּהֶן. הוּא נִסְתָּם מִמֶּנּוּ עוֹלָם הַזֶּה וּמַרְאֵה הָעוֹלָם הַזֶּה, נִסְתְּמוּ עֵינָיו. כָּל מַרְאֵה הָעוֹלָם הַזֶּה נֶחְשָׁךְ מִמֶּנּוּ, וְנֶחְשְׁכוּ מִמֶּנּוּ מַרְאֵה עֵינָיו, אֵין לוֹ מַרְאֶה בָּעוֹלָם הַזֶּה מִשָּׁם וָהָלְאָה. אָמַר רַבִּי שִׁמְעוֹן, נָאֶה תִקּוּן הַקַּדְמוֹנִים, וְחָכְמָתָם יְתֵרָה מִמַּלְאָכִים קְדוֹשִׁים."],[6,"","אָמַר לוֹ, לָמָּה יוֹסֵף יָשִׁית יָדוֹ מִכָּל בָּנָיו? וְאִם תֹּאמַר עַל בְּשׂוֹרָה שֶׁלּוֹ, צָרִיךְ לוֹמַר וְיוֹסֵף חַי תִּרְאֶה. אָמַר לוֹ יָשִׁית יָדוֹ, מִשּׁוּם שֶׁאַהֲבָתוֹ הָיָה, וּמִשּׁוּם כָּךְ זֶה נִסְתָּם מִמֶּנּוּ אוֹר הָעוֹלָם הַזֶּה, וְזֶה לָקַח אוֹתוֹ. מִי שֶׁסּוֹתֵם עֵינָיו, אֲהוּבוֹ מַרְאֶה כָּךְ: מַרְאֶה שֶׁלְּךְ שֶׁל הָעוֹלָם הַזֶּה אָבַד, הֲרֵינִי מַרְאֶה שֶׁלְּךְ בִּמְקוֹמְךְ. מִכָּאן וָהָלְאָה יְתַקְּנוּ לְךְ מַרְאֶה אַחֵר שֶׁל אוֹתוֹ עוֹלָם."],[7,"","אָמַר רַבִּי שִׁמְעוֹן, מַה הֲנָאָה זוֹ לַמֵּת, וּמַה תּוֹעֶלֶת יֵשׁ לוֹ בָּזֶה? מִי שֶׁיִּרְצֶה לִשְׁאֹל יוֹם מַה שֶּׁהִצְטָרֵךְ לִפְקֹחַ עֵינָיו, בִּשְׁבִיל לְהַרְאוֹת שֶׁעֲדַיִן הוּא מִזְדַּמֵּן לְהָשִׁיב לְמַרְאֵה הָעוֹלָם הַזֶּה כְּמִקֹּדֶם."],[8,"","אָמַר לוֹ, אִי חָסִיד קָדוֹשׁ, וַדַּאי אִם לֹא נִסְתָּם מִמֶּנּוּ כָּל מַרְאֵה הָעוֹלָם הַזֶּה וְלֹא נֶאֱבָד מִמֶּנּוּ הַכֹּל, לֹא יִהְיֶה לוֹ מַרְאֶה וְחֵלֶק שֶׁל הָעוֹלָם הַהוּא. עוֹלָם זֶה הוּא בְּהִפּוּךְ מֵאוֹתוֹ עוֹלָם שֶׁאָנוּ בוֹ, שֶׁבִּזְמַן תְּחִיַּת הַמֵּתִים אֲפִלּוּ כְּחוּט הַשַּׂעֲרָה לֹא יִהְיֶה מִמַּעֲשֵׂה הָעוֹלָם הַזֶּה, שֶׁהַכֹּל נֶאֱבָד בַּהַתְחָלָה (הטל יבטל אותו וישים אותו) בְּאוֹתוֹ הַטַּל (בהתחלה), וְיָעֳבַר מִמֶּנּוּ כָּל זֻהֲמָה, וְאַחַר כָּךְ יַעֲשֶׂה כְּחֹמֶץ זֶה, וּמִמֶּנּוּ יֵעָשֶׂה הַגּוּף בְּרִיָּה חֲדָשָׁה, כָּךְ כָּאן."]]],[["אָמַר לֵיהּ רִבִּי שִׁמְעוֹן, ודַּאי יְדַעְנָא דְּאַתּוּן מְלוּבָּשִׁין תַּמָּן, בִּלְבוּשׁ יְקָר, דְּגוּפָא דַּכְיָא קַדִּישָׁא. אִי הֲוָה בְּגַוְונָא דָּא בְּהַאי עָלְמָא, בַּר נָשׁ דְּאִתְחֲזֵי בְּהַהוּא גּוּפָא, כְּגַוְונָא דְּאַתּוּן קַיְימִין בְּהַהוּא עָלְמָא.","אָמַר לֵיהּ, מִלָּה דָּא שָׁאִילוּ קַמֵּי רַב מְתִיבְתָּא, תְּרֵין עוּלְימִין דְּאִתְלְבָּשׁוּ בֵּינָנָא, בָּתַר דְּסַבְלוּ צַעֲרָא עַל חוֹבָא, דְּלָא אִתְחֲזֵי לְגַלָּאָה, וְשָׁאִילּוּ דָּא קַמֵּי רַב מְתִיבְתָּא. וְאִיהוּ אָמַר, דְּהָא הֲוָה בְּהַאי עָלְמָא הָכִי. מְנָלָן. דִּכְתִּיב, (אסתר ה׳:א׳) וַיְהִי בַּיּוֹם הַשְּׁלִישִׁי וַתִּלְבַּשׁ אֶסְתֵּר מַלְכוּת, אִתְלַבְּשַׁת בְּהַהוּא דִּיּוּקְנָא דְּהַהוּא עָלְמָא. מַלְכוּת: דָּא רוּחָא דְּקוּדְשָׁא, דְּהָא מַלְכוּת שְׁמַיָא, נָשִׁיב רוּחָא, מֵהַהוּא רוּחָא דַּאֲוִירָא דְּהַהוּא עָלְמָא, וְאִתְלַבְּשָׁא בֵּיהּ אֶסְתֵּר.","וְכַד עָאלַת קַמֵּי מַלְכָּא אֲחַשְׁוִרוֹשׁ, וְחָמָא הַהוּא לְבוּשָׁא דִּנְהוֹרָא, דִּיוּקְנָאָה אִדְמִי לְמַלְאַךְ אֱלֹהִים. פַּרְחָה מִנֵּיהּ נִשְׁמְתָא לְפוּם שַׁעֲתָא. מָרְדְּכַי אוּף הָכִי, דִּכְתִּיב (אסתר ח׳:ט״ו) וּמָרְדְּכַי יָצָא מִלִּפְנֵי הַמֶּלֶךְ בִּלְבוּשׁ מַלְכוּת. לְבוּשׁ מַלְכוּת, ודַּאי, דִּיּוּקְנָא דְּהַהוּא עָלְמָא. וְעַל דָּא כְּתִיב, (אסתר ט׳:ג׳) כִּי נָפַל פַּחַד מָרְדְּכַי עֲלֵיהֶם. פַּחַד מָרְדְּכַי, וְלָא פַּחַד אֲחַשְׁוִרוֹשׁ. אָמַר רִבִּי שִׁמְעוֹן, כַּמָה מְתִיקִין אִינּוּן מִלִּין, זַכָּאָה חוּלָקִי, וְהָא יְדַעְנָא דְּצַדִּיקַיָּיא (ס\"א בהאי) בְּהַהוּא עָלְמָא, מִתְלַבְּשָׁן בִּלְבוּשָׁא דְּאִקְרֵי לְבוּשׁ מַלְכוּת, וְהָכִי הוּא וַדַּאי.","אָמַר לֵיהּ, אֲוִירָא דְּגַּן עֵדֶן, נְשִׁיבוּ דְּרוּחַ קוּדְשָׁא אִינּוּן, וּמִתְלַבְּשָׁן בֵּיהּ צַדִּיקַיָּיא, כְּגַוְונָא דַּהֲווֹ בְּהַאי עָלְמָא. וּלְבָתַר, רוּחַ קוּדְשָׁא שָׁרָאת, עַל רֵישָׁא דְּכָל חַד וְחַד. וְאִתְעַטָּר וְאִתְעָבֵידַא לֵיהּ עָטָרָא. וְכַךְ הֲוָה לְמָרְדְּכַי, דִּכְתִּיב בִּלְבוּשׁ מַלְכוּת, דִּיּוּקְנָא דְּהַהוּא עָלְמָא. וּלְבָתַר וַעֲטֶרֶת זָהָב גְּדוֹלָה, דָּא עֲטֶרֶת, דִּשְׁרִיאַת עַל רֵישֵׁיהוֹן דְּצַדִּיקַיָּיא בְּהַהוּא עָלְמָא. כַּד קַבִּילוּ יִשְׂרָאֵל אוֹרַיְיתָא, כְּגַוְונָא דָּא הֲוָה לְהוֹן. עַד דְּחָבוּ, דִּכְתִּיב בְּהוּ, (שמות ל״ג:ו׳) וַיִּתְנַצְּלוּ בְנֵי יִשְׂרָאֵל אֶת עֶדְיָם מֵהַר חוֹרֶב. אִתְפְּשָׁטוּ מֵהַהוּא לְבוּשָׁא.","וְכֵן כְּתִיב בִּיהוֹשֻׁעַ כַּהֲנָא רַבָּא, (זכריה ג׳:ד׳) הָסִירוּ הַבְּגָדִים הַצּוֹאִים מֵעָלָיו. וּכְתִיב וַיַלְבִּישׁוּהוּ בְּגָדִים, אִלֵּין לְבוּשִׁין דְּהַהוּא עָלְמָא. מֵהָכָא מִלִּין קַדְמָאִין. וּמֵהָכָא, דְּכָל זִמְנָא דְּגוּפָא דְּהַאי עָלְמָא קַיְּימָא בְּקִבְרָא בְּקִיּוּמָא, לָא אִתְלְבַּשׁ רוּחָא בִּלְבוּשָׁא דְּהַהוּא עָלְמָא. דִּכְתִּיב וַיָּסִירוּ הַבְּגָדִים הַצּוֹאִים מֵעָלָיו בְּקַדְמִיתָא. וּלְבָתַר וַיַלְבִּישׁוּהוּ בְּגָדִים. וּמַלְאַךְ יְיָ עוֹמֵד, מַהוּ עוֹמֵד. אֶלָּא דָּא הִיא עָטָרָא, דְּאִקְרֵי מַלְאַךְ יְיָ, דְּקַיְּימָא עַל רֵישֵׁיהוֹן דְּצַדִּיקַיָּיא וְדָא אִיהוּ עוֹמֵד. עוֹמֵד עַל רֵישָׁא לְעֵילָּא. לְבָתַר דְּאִתְלַבְּשָׁן בְּהַאי לְבוּשָׁא דִּיקָר.","תְּרֵין גּוּפִין כַּחֲדָא, לָא יַכְלִין לְמֵיקָם, כָּל זִמְנָא דְּהַאי קַיָּים, רוּחָא לָא מְקַבְּלָא אַחֲרָא. אִתְעֲבָר דָּא, הָא אַחֲרָא זְמִינָא מִיַּד, ודַּאי, דָּא נָפִיק, וְדָא עָאל. כְּגַוְונָא דְּיֵצֶר טוֹב וְיֵצֶר רָע. בְּהַאי עָלְמָא. לָא בָּעֵי קוּדְשָׁא בְּרִיךְ הוּא דְּתַרְוַויְיהוּ יְקוּמוּן כַּחֲדָא.","אָמַר לֵיהּ, תַּוַּוהְנָא עַל מַה דִּכְתִּיב, (זכריה ג׳:א׳) וְהַשָּׂטָן עוֹמֵד עַל יְמִינוֹ לְשִׂטְנוֹ. וְכִי יְהוֹשֻׁעַ בֶּן יְהוֹצָדָק כַּךְ, שְׁאַר בְּנֵי עָלְמָא עַל אַחַת כַּמָה וְכַמָּה. אָמַר לֵיהּ, חֲסִידָא קַדִּישָׁא, כַּמָה טְמִירִין סְתִימִין מִלִין אִלֵּין, (אמר ליה) אַף עַל גַּב דְּחַבְרַיָּיא יַדְעִין בְּמִלִּין דְּהַהוּא עָלְמָא, לָא יַכְלִין לְמִנְדַּע בְּרָזִין אִלֵּין.","אָמַר לֵיהּ, כֵּיוָן דְּבַר נָשׁ בְּהַהוּא עָלְמָא, מַה תּוֹעַלְתָּא אִית לְהַהוּא שָׂטָן לְאַסְטָאָה לֵיהּ, וְלָא דַּי לֵיהּ דְּאַפִּיק נִשְׁמָתֵיהּ מִנֵּיהּ, וְקָטִיל לֵיהּ. אָמַר לֵיהּ אִי חֲסִידָא קַדִּישָׁא, זַכָּאָה חוּלָקָךְ. תָּא חֲזֵי תִּיאוּבְתָּא דְּשָׂטָן לָא הֲוָה, אֶלָּא בְּגִין דְּלָא יִתְלַבָּשׁ הַהוּא זַכָּאָה בִּלְבוּשָׁא דַּכְיָא קַדִּישָׁא, דְּכֵיוָן דְּחָזֵי הַהוּא שָׂטָן, דִּלְבוּשָׁא דִּילֵיהּ אִתְדַּחְיָא, וְלָא אִתְחֲשִׁיב, עַל דָּא אַסְטֵי לֵיהּ. מַאי טַעֲמָא. בְּגִין דְּאִי אִתְלְבַּשׁ בְּהַהוּא לְבוּשׁ יְקָר, מִיַּד לְבוּשָׁא דְּזוּהֲמָא, וְעַבִידְתָּא דְּהַהוּא שָׂטָן, יִתְבָּטַל וְיַּעֲבֹר מֵעָלְמָא, וְלָא נִיחָא לֵיהּ לְשָׂטָן.","וְתוּ, דִּבְכָל זִמְנָא דְּלָא אִתְלְבַּשׁ, פַּקְדָא רוּחָא לְהַהוּא גּוּפָא דְּזוּהֲמָא דִּילֵיהּ, וְנִיחָא לֵיהּ לְשָׂטָן. וְכֵיוָן דְּאִתְלָבַּשׁ בְּהַהוּא לְבוּשׁ יְקָר, הָא אִתְבְּטִל גְּוָונֵי דְּיִצְרָא בִּישָׁא, וְגוּפָא דִּילֵיהּ, וְלֵית לֵיהּ דּוּכְרָנָא בַּהֲדֵיהּ לְעָלְמִין."],[[0,"א״ל רבי שמעון וכו':","א״ל ר״ש, ודאי ידעתי שאתם מלובשים שם בלבוש יקר, של גוף טהור וקדוש. ושואל, אם יש כעין זה בעולם הזה, אם יש אדם הנראה כאן באותו הגוף, כעין שאתם עומדים בעולם ההוא."],[1,"א״ל מלה דא וכו׳:","א״ל, דבר זה שאלו ב׳ עלמים, דהיינו נערים, לפני רב מתיבתא, שנתלבשו ביננו אחר שסבלו צער על חטא שאינו ראוי לגלותו, ושאלו זה לפני רב מתיבתא. והוא אמר, שהיה בעולם הזה כך. מאין לנו. כי כתוב, ויהי ביום השלישי ותלבש אסתר \u0003מלכות,\u0004 שפירושו, שנתלבשת באותה הצורה של עולם ההוא. \u0003מלכות,\u0004 פירושו רוח הקדש, כי מלכות שמים, דהיינו מלכות דז״א הנקרא שמים, נושבת רוח, מרוח ההוא של אויר עולם ההוא, ונתלבשה בו אסתר."],[2,"וכד עאלת קמי וכו׳:","וכשנכנסה לפני מלך אחשורוש. וראה לבוש ההוא של אור, צורתה נדמה לו למלאך אלקים. ופרחה נשמתו ממנו לרגע. מרדכי, גם כן, לבש לבוש של עולם ההוא, שכתוב, ומרדכי יצא מלפני המלך בלבוש \u0003מלכות.\u0004 לבוש מלכות ודאי, דהיינו צורה של עולם ההוא. וע״כ כתוב, כי נפל פחד מרדכי עליהם. פחד מרדכי, ולא פחד אחשורוש. כלומר, לא מטעם שגדלו אחשורוש, אלא מפני הלבוש שלו שמעולם ההוא. אר״ש, כמה מתוקים הם אלו הדברים, אשרי חלקי. והריני יודע, שצדיקים בעולם הזה מתלבשים בלבוש, שנקרא לבוש מלכות. וכך הוא ודאי."],[3,"א״ל אוירא דגן עדן וכו׳:","אמר לו, האויר של גן עדן, הוא נשיבת רוח הקדש, ומתלבשים בו הצדיקים, כעין שהיו בעולם הזה. ואח״כ, רוח הקודש שורה על ראש כל אחד ואחד, ונתעטר בו, ונעשה לו עטרה. וכך היה למרדכי, שכ׳ \u0003בלבוש מלכות,\u0004 שפירושו בצורה של עולם ההוא, ואח״כ, \u0003ועטרת זהב גדולה,\u0004 זו היא העטרה השורה על ראש הצדיקים בעולם ההוא. כשקבלו ישראל את התורה, היה להם ג״כ כעין זה. דהיינו לבוש של עולם ההוא, עד שחטאו, שכתוב בהם, ויתנצלו בני ישראל את עדים מהר חורב. דהיינו שנתפשטו מלבוש ההוא."],[4,"וכן כתיב ביהושע וכו׳:","וכן כתוב ביהושע כהן גדול, הסירו בגדים הצואים מעליו. וכתוב, וילבישוהו בגדים. אלו הם הלבושים של עולם ההוא. מכאן, משמע דברינו הראשונים, שצריכים מקודם לסתום העינים מכל מראה עולם הזה, שהם נחשבים כבגדים צואים, ואח״כ יוכל לזכות למראה של עולם ההוא, שהם הבגדים החדשים, שהלבישו את יהושע. ומכאן משמע, שכל זמן שהגוף של עולם הזה שנקרא בגדים הצואים נמצא בקבר בקיומו, אין הרוח מתלבש בלבוש של עולם ההוא. שכתוב, ויסירו הבגדים הצואים מעליו, בתחילה, ואחר כך, וילבישוהו בגדים. וכתוב, ומלאך ה׳ עומד. שואל, מהו עומד. ומשיב, אלא זה הוא העטרה, שנקראת מלאך ה', העומדת על ראש הצדיקים, כנ״ל, וזהו שכתוב, עומד, דהיינו שעומד על הראש מלמעלה, אחר שנתלבשו בלבוש יקר הזה."],[5,"תרין גופין כחדא וכו׳:","ב׳ גופים יחד אינם יכולים להמצא, כל זמן שזה, של עוה\"ז, נמצא אין הרוח מקבל לבוש אחר של עולם ההוא. נעבר זה, של עולם הזה, הרי מוכן האחר מיד. ודאי, זה יוצא וזה נכנס. והוא כעין יצר הטוב ויצר הרע בעולם הזה, שהקב״ה אינו רוצה ששניהם יקומו בגוף אחד. אלא שאם היצר הרע שולט בורח יצר הטוב, ואם יצר הטוב שולט בורח יצר הרע."],[6,"אמר ליה תווהנא וכו׳:","אמר לו תמה אני על מה שכתוב, והשטן עומד על ימינו לשטנו. ואם יהושע בן יהוצדק כך, שאר בני העולם על אחת כמה וכמה. אמר לו, חסיד קדוש, כמה נסתרים וסתומים דברים אלו. אע״פ שהחברים יודעים בדברים של עולם ההוא, אינם יכולים לדעת בסודות האלו."],[7,"א״ל כיון דב״נ וכו׳:","אמר לו כיון שהאדם בעולם ההוא, איזה תועלת יש לשטן להסטין עליו. ולא די לו שהוציא נשמתו והרגו. אמר לו, אהה חסיד קדוש, אשרי חלקך. בוא וראה תשוקתו של השטן לא היה, אלא כדי שלא יתלבש, צדיק הזה, יהושע בן יהוצדק, בלבוש טהור וקדוש, כיון שראה השטן, שלבוש שלו נדחה ולא נחשב, דהיינו בגדים הצואים, על זה השטין עליו. מהו הטעם. הוא משום שאם יתלבש בלבוש יקר ההוא, מיד הלבוש דזוהמא, ופעולת השטן יתבטל ויעבור מן העולם. וע״כ, לא רצה בזה השטן."],[8,"ותו דבכל זמנא וכו׳:","ועוד, כי בכל זמן שלא נתלבש בלבוש של עולם ההוא, פוקד הרוח לגוף המזוהם שלו, ורצוי זה לשטן. וכיון שנתלבש באותו לבוש יקר של עולם ההוא, הרי נתבטל כל גווני היצר הרע, והגוף שלו, ואין לו זכרון עמו לעולם."]],[[0,"","אָמַר לוֹ רַבִּי שִׁמְעוֹן, וַדַּאי יָדַעְתִּי שֶׁאַתֶּם מְלֻבָּשִׁים שָׁם בִּלְבוּשׁ נִכְבָּד שֶׁל גּוּף זַךְ קָדוֹשׁ. הַאִם הָיָה כְּמוֹ זֶה בָּעוֹלָם הַזֶּה, אָדָם שֶׁנִּרְאֶה בְּאוֹתוֹ גּוּף כְּמוֹ שֶׁאַתֶּם עוֹמְדִים בְּאוֹתוֹ עוֹלָם?"],[1,"","אָמַר לוֹ, דָּבָר זֶה שָׁאֲלוּ לִפְנֵי רֹאשׁ הַיְשִׁיבָה, שְׁנֵי עֲלָמִים שֶׁהִתְלַבְּשׁוּ בֵינֵינוּ אַחַר שֶׁסָּבְלוּ צַעַר עַל חֵטְא שֶׁלֹּא נִתָּן לְגַלּוֹת, וְשָׁאֲלוּ זֶה לִפְנֵי רֹאשׁ הַיְשִׁיבָה, וְהוּא אָמַר שֶׁזֶּה הָיָה כָּךְ בָּעוֹלָם הַזֶּה. מִנַּיִן לָנוּ? שֶׁכָּתוּב (אסתר ה) וַיְהִי בַּיּוֹם הַשְּׁלִישִׁי וַתִּלְבַּשׁ אֶסְתֵּר מַלְכוּת, הִתְלַבְּשָׁה בְאוֹתָהּ דְּמוּת שֶׁל הָעוֹלָם הַהוּא. מַלְכוּת - זוֹ רוּחַ הַקֹּדֶשׁ, שֶׁהֲרֵי מַלְכוּת הַשָּׁמַיִם נוֹשֶׁבֶת רוּחַ מֵאוֹתָהּ רוּחַ הָאֲוִיר שֶׁל אוֹתוֹ עוֹלָם, וּבָהּ הִתְלַבְּשָׁה אֶסְתֵּר."],[2,"","וּכְשֶׁנִּכְנְסָה לִפְנֵי הַמֶּלֶךְ אֲחַשְׁוֵרוֹשׁ וְרָאָה אוֹתוֹ לְבוּשׁ שֶׁל אוֹר, דְּמוּתָהּ נִדְמְתָה לְמַלְאַךְ אֱלֹהִים, וּפָרְחָה מִמֶּנּוּ נִשְׁמָתוֹ לְפִי שָׁעָה. מָרְדְּכַי גַּם כָּךְ, שֶׁכָּתוּב (שם ה) וּמָרְדֳּכַי יָצָא מִלִּפְנֵי הַמֶּלֶךְ בִּלְבוּשׁ מַלְכוּת. לְבוּשׁ מַלְכוּת וַדַּאי, דְּמוּת שֶׁל אוֹתוֹ עוֹלָם. וְעַל זֶה כָּתוּב (שם ט) כִּי נָפַל פַּחַד מָרְדֳּכַי עֲלֵיהֶם. פַּחַד מָרְדֳּכַי, וְלֹא פַּחַד אֲחַשְׁוֵרוֹשׁ. אָמַר רַבִּי שִׁמְעוֹן, כַּמָּה מְתוּקִים דְּבָרִים אֵלּוּ. אַשְׁרֵי חֶלְקִי. וַהֲרֵי יָדַעְתִּי שֶׁצַּדִּיקִים (בזה) בְּאוֹתוֹ עוֹלָם מִתְלַבְּשִׁים בִּלְבוּשׁ שֶׁנִּקְרָא לְבוּשׁ מַלְכוּת, וְכָךְ הוּא וַדַּאי."],[3,"","אָמַר לוֹ, אֲוִיר גַּן עֵדֶן, נְשִׁיבַת רוּחַ הַקֹּדֶשׁ הֵם, וּבוֹ מִתְלַבְּשִׁים הַצַּדִּיקִים כְּמוֹ שֶׁהָיוּ בָּעוֹלָם הַזֶּה. וְאַחַר כָּךְ רוּחַ הַקֹּדֶשׁ שׁוֹרָה עַל רֹאשׁ כָּל אֶחָד וְאֶחָד, וּמִתְעַטֵּר וְנַעֲשֵׂית לוֹ עֲטָרָה. וְכָךְ הָיָה לְמָרְדְּכַי, שֶׁכָּתוּב (שם ח) בִּלְבוּשׁ מַלְכוּת, דְּמוּת אוֹתוֹ הָעוֹלָם. אַחַר כָּךְ וַעֲטֶרֶת זָהָב גְּדוֹלָה - זוֹ עֲטֶרֶת שֶׁשּׁוֹרָה עַל רָאשֵׁי הַצַּדִּיקִים בְּאוֹתוֹ עוֹלָם. כְּשֶׁקִּבְּלוּ יִשְׂרָאֵל תּוֹרָה, כְּמוֹ זֶה הָיָה לָהֶם עַד שֶׁחָטְאוּ, שֶׁכָּתוּב בָּהֶם (שמות לג) וַיִּתְנַצְּלוּ בְנֵי יִשְׂרָאֵל אֶת עֶדְיָם מֵהַר חוֹרֵב. הִתְפַּשְּׁטוּ מֵאוֹתוֹ לְבוּשׁ."],[4,"","וְכֵן כָּתוּב בִּיהוֹשֻׁעַ כֹּהֵן גָּדוֹל, (זכריה ג) הָסִירוּ הַבְּגָדִים הַצֹּאִים מֵעָלָיו. וְכָתוּב וַיַּלְבִּישֻׁהוּ בְּגָדִים, אֵלּוּ לְבוּשֵׁי הָעוֹלָם הַהוּא. מִכָּאן דְּבָרִים רִאשׁוֹנִים. וּמִכָּאן, שֶׁכָּל זְמַן שֶׁגּוּף הָעוֹלָם הַזֶּה קַיָּם בַּקֶּבֶר בְּקִיּוּמוֹ, לֹא מִתְלַבֵּשׁ רוּחַ בִּלְבוּשׁ אוֹתוֹ עוֹלָם, שֶׁכָּתוּב וַיָּסִירוּ הַבְּגָדִים הַצּאִים מֵעָלָיו - בַּהַתְחָלָה, וְאַחַר כָּךְ - וַיַּלְבִּישֻׁהוּ בְּגָדִים. וּמַלְאַךְ ה' עֹמֵד. מַה זֶּה עֹמֵד? אֶלָּא זוֹהִי עֲטָרָה שֶׁנִּקְרֵאת מַלְאַךְ ה', שֶׁעוֹמֶדֶת עַל רָאשֵׁי הַצַּדִּיקִים. וְזֶהוּ עֹמֵד, עוֹמֵד עַל הָרֹאשׁ לְמַעְלָה לְאַחַר שֶׁמִּתְלַבְּשִׁים בִּלְבוּשׁ כָּבוֹד זֶה."],[5,"","שְׁנֵי גוּפִים כְּאֶחָד לֹא יְכוֹלִים לַעֲמֹד. כָּל זְמַן שֶׁזֶּה קַיָּם, הָרוּחַ לֹא מְקַבֶּלֶת אַחֵר. הָעֳבַר זֶה, הֲרֵי אַחֵר מְזֻמָּן מִיָּד וַדַּאי. זֶה יוֹצֵא וְזֶה נִכְנָס. כְּמוֹ שֶׁיֵּצֶר טוֹב וְיֵצֶר בָּעוֹלָם הַזֶּה לֹא רוֹצֶה הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁשְּׁנֵיהֶם יַעַמְדוּ כְאֶחָד."],[6,"","אָמַר לוֹ, תָּהִינוּ עַל מַה שֶּׁכָּתוּב, וְהַשָּׂטָן עֹמֵד עַל יְמִינוֹ לְשִׂטְנוֹ. וְכִי יְהוֹשֻׁעַ בֶּן יְהוֹצָדָק כָּךְ, שְׁאָר בְּנֵי הָעוֹלָם עַל אַחַת כַּמָּה וְכַמָּה. אָמַר לוֹ, חָסִיד קָדוֹשׁ, כַּמָּה טְמִירִים נִסְתָּרִים הַדְּבָרִים הַלָּלוּ. (אמר לו,) אַף עַל גַּב שֶׁהַחֲבֵרִים יוֹדְעִים בְּדִבְרֵי אוֹתוֹ עוֹלָם, לֹא יְכוֹלִים לָדַעַת בַּסּוֹדוֹת הַלָּלוּ."],[7,"","אָמַר לוֹ, כֵּיוָן שֶׁבֶּן אָדָם בְּאוֹתוֹ עוֹלָם, מַה תּוֹעֶלֶת יֵשׁ לְאוֹתוֹ שָׂטָן לְהַשְׂטִינוֹ? וְלֹא דַי לוֹ שֶׁהוֹצִיא נִשְׁמָתוֹ מִמֶּנּוּ וְהָרַג אוֹתוֹ?! אָמַר לוֹ, אִי חָסִיד קָדוֹשׁ, אַשְׁרֵי חֶלְקְךְ. בּא וּרְאֵה, תַּאֲוַת הַשָּׂטָן לֹא הָיְתָה, אֶלָּא כְּדֵי שֶׁלֹּא יִתְלַבֵּשׁ אוֹתוֹ צַדִּיק בִּלְבוּשׁ זַךְ קָדוֹשׁ, שֶׁכֵּיוָן שֶׁרוֹאֶה אוֹתוֹ שָׂטָן שֶׁלְּבוּשׁוֹ נִדְחֶה וְלֹא נֶחְשָׁב, עַל כָּךְ מַסְטֶה אוֹתוֹ. מָה הַטַּעַם? מִשּׁוּם שֶׁאִם יִתְלַבֵּשׁ בְּאוֹתוֹ לְבוּשׁ נִכְבָּד, מִיָּד לְבוּשׁ הַזֻּהֲמָה וּמַעֲשֵׂה אוֹתוֹ שָׂטָן יִתְבַּטֵּל וְיַעֲבֹר מֵהָעוֹלָם, וְלֹא נוֹחַ לוֹ לַשָּׂטָן."],[8,"","וְעוֹד, שֶׁבְּכָל זְמַן שֶׁלֹּא הִתְלַבֵּשׁ, פּוֹקֶדֶת הָרוּחַ לְאוֹתוֹ הַגּוּף שֶׁהַזֻּהֲמָה שֶׁלּוֹ, וְנוֹחַ לוֹ לַשָּׂטָן. וְכֵיוָן שֶׁהִתְלַבֵּשׁ בְּאוֹתוֹ לְבוּשׁ נִכְבָּד, הֲרֵי הִתְבַּטְּלוּ גּוֹנֵי יֵצֶר הָרָע וְהַגּוּף שֶׁלּוֹ, וְאֵין לוֹ זִכָּרוֹן עִמּוֹ לְעוֹלָמִים."]]],[["וְאִי תֵּימָא, דַּאֲנָן פַּקְדִין לְבֵי קִבְרֵי בְּרֵישׁ כָּל לֵילְיָא, לָאו עַל גּוּפָא אֶלָּא עַל נַפְשָׁא. (דאזלא ערטיראה) דְּהָא כָּל זִמְנָא דְּבִשְׂרָא קַיְּימָא, רוּחָא פַּקְדָא עָלָה דְּנַפְשָׁא, וְנַפְשָׁא פַּקְדָא לְגוּפָא. אֲבָל הַשְׁתָּא, פִּקְדוֹנָא דִּילָן אִיהוּ לְנַפְשָׁא, דְּאִיהִי מִשְׁתַּכְּכָא. וְאִשְׁתְּאָרַת בְּשִׁכוּכֵי גּוֹ גַּרְמֵי. וּבְגִין כָּךְ, בְּרֵישׁ כָּל לֵילְיָא, פִּקְדוֹנָא דְּרוּחָא לְנַפְשָׁא, וְלָא עַל בִּשְׂרָא.","אִי חֲסִידָא קַדִּישָׁא, תָּא וְאַגָלֵּי לָךְ מִלָּה סְתִימָא. בִּנְיָינָא דְּגוּפָא דְּבַר נָשׁ הָכִי הוּא, רוּחָא מֵעִם רוּחָא דְּקוּדְשָׁא. (יתרו ע\"ג, צ\"ט ע\"ב, רל\"ו ע\"ב) נִשְׁמְתָא מִגּוֹ אִילָנָא דְּחַיֵּי. כֵּיוָן דְּרוּחָא קַדִּישָׁא, יָהַב חֵילָא, מִיַּד רְתִיכִין דִּילֵיהּ. יָהֲבִין חֵילַיְיהוּ. חֵילָא דִּלְהוֹן, גַּרְמֵי וְשַׁיְיפִין. כֻּלְּהוּ מִסִּטְרָא דִּלְהוֹן, וְתִקּוּנַיְיהוּ דָּא עַל דָּא. סִטְרָא אַחֲרָא יָהָבַת בִּשְׂרָא, וּמִסִּטְרָא דִּילָהּ, אַתְיָא בִּשְׂרָא, וְלָא מִלָּה אַחֲרָא. רְתִיכִין דִּילָהּ, יָהֲבִין כָּל אִינּוּן גִּידִין וְעַרְקִין, לְאַמְשָׁכָא דָּמָא לְבִשְּׂרָא. בָּתַר דְּאִלֵּין יָהֲבֵי חֵילַיְיהוּ, שְׁמַיָא יַהֲבֵי חֵילַיְיהוּ, וּמַאן אִינּוּן. עוֹר דְּאִתְמְשָׁךְ עַל כֹּלָּא. כְּגַוְונָא דִּלְהוֹן.","לְבָתַר מִתְחַבְּרָן שְׁמַיָא וְאַרְעָא כַּחֲדָא, וְיָהֲבֵי ד' יְסוֹדֵי אִלֵּין: אֶשָּׁא, וּמַיָא וַאֲוִירָא, וְעַפְרָא. לְאַגָּנָא עַל אִלֵּין, וּלְחַפְיָא עַל כֹּלָּא. לְבָתַר, כָּל חַד נָטִיל חוּלָקֵיהּ דְּיָהַב, וְאִתְבָּטֵּל. רוּחָא דְּקוּדְשָׁא, וּרְתִיכִין דִּילֵיהּ, חוּלָקַיְיהוּ קַיְּימָא. רוּחָא דְּקוּדְשָׁא, רוּחָא דִּילֵיהּ קַיְּימָא וְנִשְׁמְתָא סַלְּקָא. רְתִיכִין דְּרוּחָא דְּקוּדְשָׁא, גַּרְמִין דִּלְהוֹן קַיְימִין. וְעַל דָּא חָשִׁיבוּ דְּגוּפָא, גַּרְמִין הֲווֹ. וּבְגִין כָּךְ כְּתִיב, (ישעיהו נ״ח:י״א) וְעַצְמוֹתֶיךָ יַחֲלִיץ. וּבִשְׂרָא לָא כְּתִיב בֵּיהּ הָכִי.","וְכָל זִמְנָא דְּבִשְׂרָא דְּסִטְרָא אַחֲרָא קַיְּימָא בְּקִיּוּמָא, הַהוּא שָׂטָן קַיְּימָא לְאַסְטָנָא. אִתְאֲבִיד בִּשְׂרָא, לֵית לֵיהּ רְשׁוּ לְאַסְטָנָא, דְּהָא לֵית לֵיהּ עַל מַה דְּיִסְתְּמִיךְ. וְעַל דָּא כְּתִיב, (איוב ל״ג:כ״א) יִכֶל בְּשָׂרוֹ מֵרוֹאִי וְשֻׁפּוּ עַצְמוֹתָיו לֹא רֻאוּ. מֵהַהוּא חֵיזוּ דְּשָׂטָן דְּקַיְּימָא לְאַסְטָנָא, דְּלָא יָכִיל, כֵּיוָן דְּיִכֶל בְּשָׂרוֹ. וְשֻׁפּוּ עַצְמוֹתָיו לֹא רֻאוּ, לָא אִתְחָזוּן לְקָרְבָא לְגַבֵּיהּ, דְּלֵית לֵיהּ בְּהוֹן חוּלָקָא, כֵּיוָן דְּשָׁף כָּל חַד וְחַד מִדּוּכְתֵּיהּ, לָא תָּבַע עָלַיְיהוּ, וְלָא קָאִים לְאַסְטָנָא בְּגִינַיְיהוּ. לְבָתַר דְּבִשְׂרָא מִתְעֲכְּלָא, הָא לָא יִתְבַּע דִּינָא, וְלָא קָאִים לְאַסְטָנָא, דְּהָא לֵית לֵיהּ עַל מַה דְּיִסְתְּמִיךְ, וְלָא אִדְכַּר לְבַּר נָשׁ בְּשׁוּם מִלָּה דְּעָלְמָא. אָמַר רִבִּי שִׁמְעוֹן, הַשְׁתָּא יְדַעְנָא מִלִּין עַל תִּקּוּנַיְיהוּ, וַדַּאי יָאוּת הוּא לֵיהּ לְאַסְטָנָא.","אָמַר לֵיהּ רִבִּי (שמעון), חֲגוֹר זֵינָךְ, וְתָקִין גַּרְמָךְ, אִי תִּבְעֵי לְמִנְדַּע מִלִּין דְּשָׁארִית. אוֹ אִי תִּשְׁאַל בְּהָנֵי מִלִּין, אֵימָא לִי. אָמַר לֵיהּ ודַּאי, הָא יְדַעְנָא דְּבֵיתָאי שְׁכִיבַת, דְּלָא יְדַעְנָא מִנָּהּ כְּלוּם. וְחַבְרַיָּיא יַדְעִין. נָשִׁין מַאי טַעְמָא דַּעְתַּיְיהוּ קַלָּה.","אָמַר לֵיהּ דַּעְתָּא אַתְיָא בְּשִׁית דַּרְגִּין, וְכָל חַד נָטִיל חוּלָקֵיהּ, מַה דְּאִשְׁתְּאַר, קַל אִיהוּ. אֲבָל יַקִּירָא דָּא, אִי לָאו דְּאֵשֶׁת כְּסִילוּת אִשְׁתְּתַּף בָּה. בְּמִלָּה דָּא לָא תִּשְׁאַל, דְּהָא יְדַעְנָא דְּלָאו עַל דְּבִיתָךְ שָׁאַלְתָּ, אֶלָּא עַל מַה דִּכְתִּיב, (ישעיהו י״ט:א׳) הִנֵּה יְיָ רוֹכֵב עַל עָב קַל. וְהַהוּא עָב קַל אִקְרֵי דַּעַת, מֵהַהִיא כַּלָּה יִרְאַת יְיָ, וְאִיהִי קַיְּימָא בְּאֶמְצָעִיתָא כְּגַוְונָא דְּדַעַת עִלָּאָה, אֲבָל (ועל דא) אִקְרֵי קַל. וְהָא יְדַעְנָא שְׁאֶלְתָּא דִּילָךְ מַאי הִיא.","אֲבָל שָׁארֵי וַחֲגוֹר זֵינָךְ, וְקָטִיר קִטְרָךְ, דְּהָא עִידָנָא הוּא לְגַלָּאָה, כְּמָה דְּשָׁארִית עוֹבָדָא. דְּעַל אַנְפֵּי רוֹחַב בֵּיתָא, אוּלָם דַּעֲזָרָה לְגוֹ. בְּהַאי עֲזָרָה, אִית תְּרֵיסָר פִּתְחִין, לְפוּם חוּשְׁבָּן שִׁבְטַיָּא דְּיִשְׂרָאֵל. בְּפִתְחָא חֲדָא, כְּתִיב רְאוּבֵן. וּבְפִתְחָא אַחֲרָא, כְּתִיב שִׁמְעוֹן. וְכֵן כָּל שִׁבְטַיָּא דְּיִשְׂרָאֵל, רְשִׁימִין עַל אִינּוּן פִּתְחִין. בְּזִמְנָא דִּיסַלְקוּן לְאִתְחֲזָאָה קַמֵּי מָארֵיהּ דְּעָלְמָא. מַאן דְּעָיִיל בְּפִתְחָא דְּרָשִׁים בֵּיהּ רְאוּבֵן, אִי מִשִּׁבְטָא דִּרְאוּבֵן אִיהוּ, מְקַבְּלִין לֵיהּ פִּתְחִין, וְאִי לָא פַּלְטִין לֵיהּ לְבַר. וְכֵן בְּכֻלְּהוּ, דְּלָא יְקַבְּלוּן פִּתְחִין, אֶלָּא לְמַאן דְּאִיהוּ מֵהַהוּא שִׁבְטָא דְּרָשִׁים בְּהוֹן. וּבְדָא יִתְחַקְּקוּן וְיִשְׁתְּמּוֹדְעֻן כָּל חַד וְחַד."],[[0,"ואי תימא דאנן וכו׳:","ואם תאמר הרי אנו, הרוחות, פוקדים בית הקברות בתחילת כל לילה. ואם הגוף נעבר מן העולם, יש לשאול למה אנו פוקדים הקבר. ומשיב, זה אינו על הגוף, כי אם על הנפש. כי כל זמן שבשר הגוף נמצא, הרוח פוקד את הנפש, והנפש פוקדת את הגוף. אבל עתה, שבשר הגוף נעבר מן העולם, הפקידה שלנו היא אל הנפש, שהיא נשתככה ונשארת בהשקט בתוך עצמות הגוף, שעצם אחד נשאר ממנו תמיד בקבר, שממנו נבנה לתחיית המתים. ומשום זה בתחילת כל לילה הפקדון של הרוח, הוא לנפש, ולא על בשר."],[1,"אי חסידא קדישא וכו׳:","אהה חסיד קדוש, קום ואגלה לך דבר סתום. הבנין של רוח האדם כך הוא. הרוח שלו נמשך מרוח הקודש, שהוא מלכות. הנשמה שלו נמשכת מעץ החיים. וכיון שרוח הקודש, שהוא המלכות, נותן כחו, מיד המרכבות שלו נותנים כחם, והכח שלהם הוא, העצמות והאברים כולם הם מן הצד של מרכבות המלכות, ותקוניהם הוא זה על זה, דהיינו עצם על עצם אבר על אבר. הסטרא אחרא, נותנת בשר, ומן הצד שלו בא רק בשר ולא דבר אחר. המרכבות שלו, של הס״א, נותנות כל אלו גידים ועורקים להמשיך דם אל הבשר. ואחר שאלו נותנים כחם, השמים שהם ז״א נותנים כחם, ומה הוא. הוא העור הנמשך על הכל, כמו שהם. דהיינו כמו השמים שהם מקיפים על הכל."],[2,"לבתר מתחברן שמיא וכו׳:","אחר כך מתחברים שמים וארץ, שהם ז״א ומלכות, ונותנים, ד׳ יסודות אלו, אש, מים, אויר ועפר להגן אל אלו ולכסות על הכל. ואח\"כ, כשמת, כל אחד לוקח חלקו שנתן אל הגוף, והוא מתבטל. רוח הקדש והמרכבות שלו, חלקם שנתנו אל האדם, מתקיים. רוח הקדש, הנה הרוח שלו קיים, והנשמה, עולים למעלה. המרכבות של רוח הקודש, הנה העצמות שלהם מתקיימים. וע״כ חשיבות הגוף הוא העצמות. ומשום זה כתוב, ועצמותיך יחליץ ובבשר לא כתוב כך."],[3,"וכל זמנא דבשרא וכו׳:","וכל זמן שהבשר מסטרא אחרא קיימת בקיומו, שטן ההוא עומד להסטין, נאבד הבשר אין לו רשות להשטין, כי אין לו על מה שיסמוך, שכבר אין לו חלק בו, וע״כ כתוב, יכל בשר מרואי ושפו עצמותיו לא ראו. \u0003מרואי,\u0004 פירושו מראיה ההוא של השטן העומד להשטין, שאינו יכול, משום דיכל בשרו. \u0003ושפו עצמותיו לא ראו,\u0004 היינו, לא נראו לשטן שיקרב אליו, כי אין לו חלק בו, כיון שניתק כל אחד ואחד, דהיינו כל עצם ועצם ממקומו, אינו תובע עליהם ואינו עומד להשטין בשבילם. כי אחר שהבשר נעכל לא יתבע עוד דין, ואינו עומד להשטין, כי אין לו על מה שיסמוך, ואינו מזכיר את האדם בשום דבר שבעולם. א״ר שמעון, עתה אני יודע הדברים על תקונם. דהיינו מ״ש, והשטן עומד על ימינו לשטנו. ודאי יפה הוא לו להשמין, כל עוד שלא הסיר בגדים הצואים."],[4,"א״ל רבי, חגור וכו׳:","אמר לו, רבי, חגור נשקך, ותקן את עצמך, אם אתה רוצה לדעת הדברים שהתחלת בהם, או אם תשאל באלו הדברים, אמור לי. אמר לו ודאי הרי אני יודע, שאשתי מתה, כי איני יודע ממנה כלום. והחברים יודעים ממנה. נשים מהו הטעם שדעתם קלה."],[4,"","פירוש, ששאל לו על האשה העליונה שהיא המלכות. ורמז לו, על עצם המלכות דמדת הדין שנקראת מנעולא, שנגנזה ואין בה זווג כל שתא אלפי שני, והיא כמו מתה. וזה שרמז לו \u0003דביתאי שכיבת,\u0004 שהיא מתה, \u0003דלא ידענא מנה כלום,\u0004 שאין לי בה שום השגה. \u0003וחברייא ידעין,\u0004 שהם חושבים על מלכות דמפתחא שהיא עצם המלכות, ויש להם בה השגה. \u0003נשים מ״ט דעתייהו קלה.\u0004 כי בדעת של הנוקבא, אין מציאות הארת המנעולא כלל. כמו בדעת דז״א. אלא ממלכות דמפתחא בלבדה. כי ע״כ שערות ז״א שחורות, ושערות הנוקבא אדומות (כנ״ל אד״ר נשא אות קמ״א) ונמצא שדינין דנוקבא הם יותר קלים מדינין דדוכרא. ושואל, למה זה."],[4,"","[1]"],[5,"א״ל דעתא אתיא וכו׳:","אמר לו הדעת דז״א בא בששה מדרגות, וכל אחד לוקח חלקו, מה שנשאר הוא קל. אבל יקרה הזו, שהיא המלכות. דמנעולא, אם לא אשת כסילות שהשתתפה בה. בדבר זה לא תשאל. כי כאן אסור השאלה. כי ידעתי דמה שאמרת שאשתך מתה, ואינך יודע ממנה כלום, לא על אשתך שאלת. אלא על מלכות דמנעולא כנ״ל. אלא, מותר לשאול, על מה שכתוב, הנה ה׳ רוכב על עב קל. ואותו \u0003עב קל\u0004 נקרא דעת של כלה ההיא יראת ה׳, שהיא המלכות, והיא עומדת באמצע, כמו דעת העליון, אבל נקראת קל. והנה ידעתי השאלה שלך מה היא."],[5,"","פירוש. הדעת בא בששה מדרגות, דהיינו שממשיך רק ו״ק דחכמה בהכרעתו בין ימין לשמאל. וז״ש, הטעם מה שנשים דעתן קלה, שאין בהם אלא דין קל של המפתחא, שהוא משום כי, \u0003דעתא אתיא בשית דרגין,\u0004 דהיינו שבכח הדינים שבו, ממנעולא וממפתחא (כנ״ל לך י״ג ד\"ה ונתבאר) אינו ממשיך רק ששה קצוות דחכמה, ולא הג\"ר. \u0003וכל חד נטיל חולקיה,\u0004 וכל אחד מן הקוין לוקח חלקו, כי המנעולא מאירה בקו ימין והדינין דדכורא בקו שמאל. \u0003מה דאשתאר קל איהו,\u0004 מה שנשאר מן הדינים שלא נמתקו ע״י דעת דז״א הוא נקרא \u0003קל.\u0004 כי היא בחינת מפתחא שדיניה קלים וראויה לקבלת החכמה בהקסה״ז דף מ״ה ד״ה ההיא). וז״ש, \u0003וההוא עב קל אקרי דעת מההיא כלה יראת ה׳, ואיהי קיימא באמצעיתא\u0004 דהיינו שהוא משמש לקו אמצעי שלה כמו הדעת דז״א."],[6,"אבל שארי וחגור וכו׳:","אבל התחל וחגור נשקך וקשור קשרך, כי עת הוא לגלות כמו שהתחלת הדבר. כי על פני רוחב הבית, יש אולם העזרה בפנים, בעזרה ההיא יש י״ב פתחים לפי חשבון שבטי ישראל. בפתח אחד כתוב ראובן. בפתח שני כתוב שמעון. וכן כל שאר שבטי ישראל רשומים על אלו הפתחים, בעת שעולים להראות לפני אדון העולם, מי שנכנס בפתח שרשום בו ראובן, אם משבט ראובן הוא מקבלים אותו הפתחים, ואם לא הפתחים פולטים אותו לחוץ. וכן בכולם, שהפתחים אינם מקבלים אלא מי שהוא מאותו השבט שרשום בהם. ובזה יהיו נחקרים ונודעים כל אחד ואחד."]],[[0,"","וְאִם תֹּאמַר שֶׁאָנוּ פּוֹקְדִים בָּתֵּי הַקְּבָרוֹת בְּרֹאשׁ כָּל לַיְלָה - לֹא עַל הַגּוּף, אֶלָּא עַל הַנֶּפֶשׁ (שהולכת מערטלת). שֶׁהֲרֵי כָּל זְמַן שֶׁהַבָּשָׂר קַיָּם, הָרוּחַ פּוֹקֶדֶת עַל הַנֶּפֶשׁ, וְהַנֶּפֶשׁ פּוֹקֶדֶת עַל הַגּוּף. אֲבָל עַכְשָׁו פִּקְדוֹנֵנוּ הוּא לַנֶּפֶשׁ, שֶׁהִיא שׁוֹכֶכֶת, וְנִשְׁאֶרֶת שׁוֹכֶכֶת תּוֹךְ הָעֲצָמוֹת. וּמִשּׁוּם זֶה בְּרֹאשׁ כָּל לַיְלָה פִּקְדוֹן הָרוּחַ לַנֶּפֶשׁ, וְלֹא עַל הַבָּשָׂר."],[1,"","אִי חָסִיד קָדוֹשׁ, בֹּא אֲגַלֶּה לְךְ דָּבָר נִסְתָּר. בִּנְיַן גּוּף הָאָדָם כָּךְ הוּא: הָרוּחַ מֵעִם רוּחַ הַקֹּדֶשׁ, הַנְּשָׁמָה מִתּוֹךְ עֵץ הַחַיִּים. כֵּיוָן שֶׁרוּחַ הַקֹּדֶשׁ נָתְנָה כֹּחַ, מִיָּד מַרְכְּבוֹתָיו נוֹתְנִים כֹּחָם. כֹּחָם הוּא עֲצָמוֹת וְאֵיבָרִים. כֻּלָּם מִצִּדָּם, וְתִקּוּנָם זֶה עַל זֶה. הַסִּטְרָא אַחֲרָא נוֹתֶנֶת בָּשָׂר, וּמִצִּדָּהּ בָּא הַבָּשָׂר, וְלֹא דָבָר אַחֵר. מַרְכְּבוֹתֶיהָ נוֹתְנִים כָּל אוֹתָם גִּידִים וְעוֹרְקִים לְהַמְשִׁיךְ דָּם לַבָּשָׂר. אַחֲרֵי שֶׁאֵלֶּה נוֹתְנִים חֵילָם, הַשָּׁמַיִם נוֹתְנִים חֵילָם, וּמִי הֵם? עוֹר שֶׁנִּמְשָׁךְ עַל הַכֹּל כְּמוֹהֶם."],[2,"","אַחַר כָּךְ מִתְחַבְּרִים שָׁמַיִם וָאָרֶץ כְּאֶחָד, וְנוֹתְנִים אַרְבָּעָה יְסוֹדוֹת אֵלּוּ: אֵשׁ וּמַיִם וַאֲוִיר וְעָפָר, לְהָגֵן עַל אֵלֶּה וּלְכַסּוֹת עַל הַכֹּל. אַחַר כָּךְ כָּל אֶחָד נוֹטֵל חֶלְקוֹ שֶׁנָּתַן, וְהִתְבַּטֵּל. רוּחַ הַקֹּדֶשׁ וּמַרְכְּבוֹתֶיהָ, חֶלְקָם קַיָּם. רוּחַ הַקֹּדֶשׁ, רוּחוֹ קַיָּם וְהַנְּשָׁמָה עוֹלָה. מַרְכְּבוֹת רוּחַ הַקֹּדֶשׁ עַצְמוֹתֵיהֶם קַיָּמִים, וְעַל זֶה חֲשִׁיבוּת הַגּוּף אֵלּוּ הָעֲצָמוֹת, וּמִשּׁוּם זֶה כָּתוּב (ישעיה נח) וְעַצְמֹתֶיךְ יַחֲלִיץ, וּבָשָׂר לֹא כָתוּב בּוֹ כָּךְ."],[3,"","וְכָל זְמַן שֶׁהַבָּשָׂר שֶׁל צַד הָאַחֵר עוֹמֵד בְּקִיּוּמוֹ, אוֹתוֹ שָׂטָן עוֹמֵד לְהַשְׂטִין. אָבַד הַבָּשָׂר, אֵין לוֹ רְשׁוּת לְהַשְׂטִין, שֶׁהֲרֵי אֵין לוֹ עַל מַה שֶּׁיִּסְמֹךְ. וְעַל זֶה כָּתוּב, (איוב לג) יִכֶל בְּשָׂרוֹ מֵרוֹאִי וְשֻׁפּוּ עַצְמֹתָיו לֹא רֻאוּ. מֵאוֹתוֹ מַרְאֵה שָׂטָן שֶׁעוֹמֵד לְהַשְׂטִין שֶׁלֹּא יָכוֹל, כֵּיוָן שֶׁיִּכֶל בְּשָׂרוֹ. וְשֻׁפּוּ עַצְמֹתָיו לֹא רֻאוּ, לֹא רְאוּיִים לִקְרַב אֵלָיו, שֶׁאֵין לוֹ חֵלֶק בָּהֶם, כֵּיוָן שֶׁזָּז כָּל אֶחָד וְאֶחָד מִמְּקוֹמוֹ, לֹא תוֹבֵעַ עֲלֵיהֶם וְלֹא עוֹמֵד לְהַשְׂטִין בִּגְלָלוֹ. לְאַחַר שֶׁמִּתְעַכֵּל הַבָּשָׂר הֲרֵי לֹא יִתְבַּע דִּין וְלֹא עוֹמֵד לְהַשְׂטִין, שֶׁהֲרֵי אֵין לוֹ עַל מַה שֶּׁיִּסְמֹךְ, וְלֹא מַזְכִּיר לָאָדָם בְּשׁוּם דָּבָר שֶׁל הָעוֹלָם. אָמַר רַבִּי שִׁמְעוֹן, כָּעֵת יָדַעְתִּי דְבָרִים עַל תִּקּוּנָם, וַדַּאי נָאֶה הוּא לוֹ לְקַטְרֵג."],[4,"","אָמַר לוֹ רַבִּי (שמעון), חֲגֹר כְּלֵי זֵינְךְ וְהַתְקֵן עַצְמְךְ. אִם תִּרְצֶה לָדַעַת דְּבָרִים שֶׁהִתְחַלְתָּ, אוֹ אִם תִּשְׁאַל בַּדְּבָרִים הָאֵלֶּה, אֱמֹר לִי. אָמַר לוֹ, וַדַּאי, הֲרֵי יָדַעְתִּי שֶׁאִשְׁתִּי מֵתָה, שֶׁלֹּא יָדַעְתִּי מִמֶּנָּה כְלוּם. וְהַחֲבֵרִים יוֹדְעִים. נָשִׁים מָה הַטַּעַם דַּעְתָּן קַלָּה?"],[5,"","אָמַר לוֹ, הַדַּעַת בָּאָה בְּשֵׁשׁ דְּרָגוֹת, וְכָל אַחַת לוֹקַחַת חֶלְקָהּ, מַה שֶּׁנִּשְׁאָר, הוּא קַל. אֲבָל נִכְבָּדָה זוֹ, אִם לֹא שֶׁאֵשֶׁת כְּסִילוּת מִשְׁתַּתֶּפֶת בָּהּ, בְּדָבָר זֶה אַל תִּשְׁאַל, שֶׁהֲרֵי יָדַעְתִּי שֶׁלֹּא עַל אִשְׁתְּךְ שָׁאַלְתָּ, אֶלָּא עַל מַה שֶּׁכָּתוּב, (ישעיה יט) הִנֵּה ה' רֹכֵב עַל עָב קַל. וְאוֹתוֹ עָב קַל נִקְרָא דַּעַת, מֵאוֹתָהּ כַּלָּה יִרְאַת ה', וְהִיא עוֹמֶדֶת בָּאֶמְצַע כְּמוֹ שֶׁדַּעַת עֶלְיוֹנָה, אֲבָל (ועל זה) נִקְרֵאת קַל. וַהֲרֵי יָדַעְתִּי שְׁאֵלָתְךְ מַהִי."],[6,"","אֲבָל הַתֵּר וַחֲגֹר כְּלֵי זֵינְךְ וּקְשֹׁר קִשְׁרְךְ, שֶׁהֲרֵי זְמַן הוּא לְגַלּוֹת כְּמוֹ שֶׁהִתְחַלְתָּ אֶת הַמַּעֲשֶׂה. שֶׁעַל פְּנֵי רֹחַב הַבַּיִת אוּלַם הָעֲזָרָה לִפְנִים. בַּעֲזָרָה זוֹ יֵשׁ שְׁנֵים עָשָׂר פְּתָחִים לְפִי חֶשְׁבּוֹן שִׁבְטֵי יִשְׂרָאֵל. בְּפֶתַח אֶחָד כָּתוּב רְאוּבֵן, בְּפֶתַח אַחֵר כָּתוּב שִׁמְעוֹן, וְכֵן כָּל שִׁבְטֵי יִשְׂרָאֵל רְשׁוּמִים עַל אוֹתָם פְּתָחִים בִּזְמַן שֶׁיַּעֲלוּ לְהֵרָאוֹת לִפְנֵי רִבּוֹן הָעוֹלָם. מִי שֶׁיִּכָּנֵס בַּפֶּתַח שֶׁרָשׁוּם בּוֹ רְאוּבֵן - אִם מִשֵּׁבֶט רְאוּבֵן הוּא, הַפְּתָחִים מְקַבְּלִים אוֹתוֹ. וְאִם לֹא, פּוֹלְטִים אוֹתוֹ הַחוּצָה. וְכֵן בְּכֻלָּם, שֶׁלֹּא יְקַבְּלוּ הַפְּתָחִים אֶלָּא לְמִי שֶׁהוּא מֵאוֹתוֹ שֵׁבֶט שֶׁרָשׁוּם בָּהֶם, וּבָזֶה יִתְחַקְּקוּ וְיִוָּדְעוּ כָּל אֶחָד וְאֶחָד."]]],[["תְּלַת מְאָה וְשִׁתִּין וְחָמֵשׁ עַמּוּדִין דִּנְהוֹרָא מְלָהֲטָא, אִית בְּכָל סִטְרָא, מֵאִינּוּן אַרְבַּע סִטְרִין. כָּל אִלֵּין עַמּוּדִין, אִקְרוּן עַמּוּדִים חַיִּים. בְּגִין דְּלָא קַיְּימָא נְהוֹרָא דִּלְהוֹן שָׁכִיךְ בְּאֲתָר חַד. וְכֻלְּהוּ, אִלֵּין סַלְּקִין, וְאִלֵּין נַחְתִּין. יַהֲבֵי דּוּכְתָּא דָּא לְדָא. אִלֵּין דְּסַלְּקִין בַּטְשִׁין דָּא בְּדָא, וּמְנַגְּנֵי נִגּוּנָא. וְאִלֵּין דְּנַחְתֵּי אוּף הָכִי. אִלֵּין דְּסַלְקֵי דְּנַגְּנֵי נִגּוּנָא, מַאי נִגּוּנָא מְנַגְּנֵי. שִׁיר יַתְמָא. (תהילים צ״ח:א׳) מִזְמוֹר שִׁירוּ לַיְיָ שִׁיר חָדָשׁ כִּי נִפְלָאוֹת עָשָׂה וְגוֹ'. שִׁיר חָדָשׁ, וְכִי אִית שִׁיר עַתִּיק. אֶלָּא שִׁיר, דְּעַד כְּעַן מַלְאֲכִין קַדִּישִׁין לָא שַׁבָּחוּ לֵיהּ, בְּגִין דְּאִיהוּ חָדָשׁ. מַאי טַעֲמָא אִיהוּ חָדָשׁ. בְּגִין דְּהַהוּא דִּמְחַדֵּשׁ עוּלֵימוֹי, מְשַׁבַּח לֵיהּ, וְאָמַר לֵיהּ. וְהָכִי אָמַר רַב מְתִיבְתָּא, דָּא אִקְרֵי חָדָשׁ וְאִיהוּ חָדָשׁ. בְּגִין דְּדָבִיק בְּשִׁמְשָׁא, וְלָא אִתְפְּרַשׁ מִנֵּיהּ. לְאַפָּקָא סִטְרָא אַחֲרָא, דְּלֵית בֵּיהּ חִדּוּשָׁא, דִּכְתִּיב בֵּיהּ (קהלת א) וְאֵין כָּל חָדָשׁ. זָקֵן הוּא וְאִתְבְּלֵי, וְלָא אִתְחֲדָּשׁ. (ס\"א ולא עביד תולדין דאלמלא עביד תולדין הוה מטשטש כולי עלמא)","תּוּ פָּתַח רַב מְתִיבְתָּא. שָׂרָה אִתְחֲדָּשָׁת בְּעִדּוּנָא, דַּרְגָּא דִּילָהּ גָּרִים, דִּכְתִּיב, (בראשית י״ח:י״ב) אַחֲרֵי בְלוֹתִי הָיְתָה לִּי עֶדְנָה. מַאי עֶדְנָה, מְשִׁיכוּ דְּעֵדֶן עִלָּאָה. וּבְגִין דְּאִתְמְשָׁךְ עָלָה מִסְּטַר דְּנוּקְבָּא, כְּתִיב עֶדְנָה בְּהֵ\"א וּבְגִין כָּךְ כְּתִיב הָיְתָה, וְלֹא הָיָה.","וַאדֹנִי זָקֵן. וְכִי אַף עַל גַּב דְּאִיהוּ זָקֵן, לָא אִתְחֲזֵי לְאוֹלָדָא. אֶלָּא לָאו מִלְּתָא זְעֵירְתָּא אָמְרָה לְגַבֵּיהּ, (דאברהם אלא) דִּבְגִין (לאזער גרמה דאתדבקת) הַהוּא (מלך) זָקֵן, (ד\"א דאתדבקא) (וכסיל) לָא אִתְחֲדָּשׁ וְלָא עָבִיד תּוֹלָדִין, דְּאִלְמָלֵא הֲוָה עָבִיד תּוֹלָדִין הֲוָה מְטַשְׁטְשָׁא עָלְמָא. (אלא אמרה לגבי דאברהם, בגין דהוא זקן לא יתחדש ולא עביד תולדין) וְעַל דָּא אַהְדָּר מִלִּין קוּדְשָׁא בְּרִיךְ הוּא, לָמָּה זֶה צָחֲקָה שָׂרָה וְגוֹ'. וְאִי תֵּימָא וְהָא כְּתִיב (בראשית כ״ד:א׳) וְאַבְרָהָם זָקֵן בָּא בַּיָּמִים. אֶלָּא בָּא בַּיָּמִים, בְּאִינּוּן יוֹמִין עִלָּאִין, דִּמְחַדְּשֵׁי עוּלְמִין כְּנִשְׁרָא. וְעַל דָּא נִגּוּנָא דָּא נִגּוּנָא דְּהַהוּא חָדָשׁ אִיהוּ. הוֹשִׁיעָה לּוֹ, לְמַאן. לְהַהוּא חָדָשׁ, הוֹשִׁיעָה יְמִינָא דְּמַלְכָּא עִלָּאָה, וּדְרוֹעָא דִּילֵיהּ.","אִינּוּן דְּנַחְתֵּי, אוּף הָכִי מְנַגְּנֵי, וְאָמְרֵי שִׁירָה אַחֲרָא יַתְמָא. וּמַאן אִיהוּ. (תהילים ק׳:א׳) מִזְמוֹר לְתוֹדָה, דְּאִיהוּ יַתְמָא, אוּף הָכִי.","נְהוֹרָא דִּלְהוֹן חַד אִתְחֲזֵי. וְכַד מִתְגַּלְגְּלֵי, אִתְחֲזָן חָמֵשׁ גַּוְונִין דִּנְהוֹרִין. בְּכָל עַמּוּדָא וְעַמּוּדָא. עַמּוּדִין אִלֵּין כֻּלְּהוּ חֲלֻלִין מִלְּגָאו. וְכַד סַלְקֵי וְנַחְתֵּי, נַפְקֵי מִנַּיְיהוּ שַׁלְהוֹבִין דְּנוּרָא, כְּגְוָונֵי חֵיזוּר וְשׁוּשָן. לְעֵילָּא מִכָּל עַמּוּדָא וְעַמּוּדָא, אִית תְּלַת תַּפּוּחִין, דְּבַטְשֵׁי בְּהוּ תְּלַת גַּוְונִין, סוּמָק יָרוֹק וְחִוָּור. בְּכָל גּוָֹון וּגְוָון מְלַהֲטָן אַתְוָון בַּלְטֵי, מִשַּׁלְהוֹבָא יְרוֹקָא דְּאֶשָּׁא, וְלָא מִשְׁתַּכְכֵי לְעָלְמִין. וְלֵית מַאן דִּיְקוּם עָלַיְיהוּ.","אַרְבַּע גַּלְגַּלִּין מְתַחֲמָן עוֹבָד צִיּוּר, בְּכָל עַמּוּדָא וְעַמּוּדָא. בְּאִינּוּן גַּלְגַּלִּין, אִית פְּלִיאָן רַבְרְבָן. כַּד מִסְתַּחֲרָן מַפְּקִין מִנַּיְיהוּ זַגִּין דְּדַהֲבָא וְאַבְנֵי יְקָר. וּמִיַּד מִתְכַּנְּשֵׁי בְגַוַויְיהוּ, וְלָא נַפְלֵי לְאַרְעָא. כַּד נָפְקִין אִינּוּן זַגִּין דְּדַהֲבָא, וְאִינּוּן אַבְנֵי יְקָר גּוֹ אִסְתַחֲרוּתָא דְּגַלְגַּלִין, אִשְׁתְּמַע קָלָא דְּאָמְרֵי, (ישעיהו נ״ד:י״ז) זֹאת נַחֲלַת עַבְדֵי יְיָ וְצִדְקָתָם מֵאִתִּי נְאֻם יְיָ.","תְּרֵין אַרְיָין בְּכָל גַּלְגַּלָּא וְגַלְגַּלָּא, אַרְיָא חֲדָא מִסִּטְרָא חֲדָא, וְאַרְיָא חֲדָא מִסִּטְרָא חֲדָא, וְכֻלְּהוּ מֵאֶשָּׁא יְרוֹקָא, וּבְגִלְגּוּלָא דְּקָא מִסְתַּחֲרָן גַּלְגַּלִּין, מִתְחַבְּקָן אִלֵּין בְּאִלֵּין. וְאָזְלֵי כֻּלְּהוּ, בְּגִלְגּוּלָא מִתְדַּבְּקָן דָּא בְּדָא. כַּד סַלְּקִין עַמּוּדִין, מְנָהֲמָן אַרְיָין אִלֵּין בְּאִלֵּין, וְתַפּוּחִין פַּרְחִין בַּאֲוִירָא, וְסַלְּקִין לְעֵילָּא, וּבַטְשֵׁי אִלֵּין בְּאִלֵּין בַּאֲוִירָא. וְתָבוּ לְאַתְרַיְיהוּ, וּמִתַּמָּן נָפְלֵי. וְאַרְיָין פַּשְׁטֵי יְדַיְיהוּ לְנַטְלָא לוֹן, וְסַלְּקִין אִלֵּין מִגַּרְמַיְיהוּ. אִי חֲסִידָא קַדִּישָׁא, מַאן חָמָא חָכְמְתָא דְּאוּמָנוּ, דְּצִיֵּיר קוּדְשָׁא בְּרִיךְ הוּא בְּעַמוּדִין אִלֵּין.","בְּפַלְגּוּ יוֹמָא נָפְקֵי תְּרֵין נִשְׁרִין בְּכָל גַּלְגַּלָּא וְגַלְגַּלָּא, וְלָא יְדִיעַ אֲתָר דְּנַפְקֵי מִתַּמָּן, וְשַׁרְיָין עַל רֵישֵׁיהוֹן דְּאִלֵּין אַרְיָין. וּכְדֵין מִשְׁתַּכְכֵי עַמּוּדִין וְגַלְגְּלִין, וְקַיְימֵי בְּקִיּוּמַיְיהוּ. וְתַפּוּחִין נָפְלֵי עַל פּוּמַיְיהוּ דְּנִשְׁרֵי, וּמְקַבְּלֵי לוֹן. וּמִיַּד פַּרְחִין מִפּוּמָא לְפוּמָא, וְאָזְלִין וּמְשַׁטְטֵי בֵּינַיְיהוּ, וְתָבוּ לְאַתְרַיְיהוּ, וְלָא יְדִיעַ מַאן הִיא. לְבָתַר שַׁעֲתָא וּפַלְגָּא, נִשְׁרִין אֲרִימִין קָלָא, וּמְנַגְּנִין נִגּוּנָא תָּאִיבָא, וְאִתְטַמְּרָן, וְלָא יְדִיעַ בְּהֵי אֲתָר.","סַחֲרָנַיְיהוּ דְּאִינּוּן עַמּוּדִין, אִית שְׂבָכִין עוֹבָד צִיּוּר. אֶשָּׁא סוּמָקָא, וּנְהוֹרָא חִוָּורָא, וְחוּטִין דְּדַהֲבָא, סְחוֹר סְחוֹר, סָחֲרִין לְכָל סְטָר. וּמַעְיָינָא דְּמַיָּא כְּמָה דְאַתְּ אָמֵר וְהָיָה בַּיוֹם הַהוּא יֵצְאוּ מַיִם חַיִּים מִיְרוּשָלַיִם חֶצְיָם אֶל הַיָּם הַקַּדְמוֹנִי וְחֶצְיָם אֶל הַיָּם הָאַחֲרוֹן."],[[0,"","[א] \u0003תלת מאה ושתין וכו׳:\u0004 ג׳ מאות וששים וחמשה עמודי אור לוהט, יש בכל צד מאלו ד׳ צדדים שבעזרה, כל אלו עמודים נקראים עמודים חיים, משום שהאור שלהם אינו עומד שקט במקום אחד, שכל העמודים, אלו עולים ואלו יורדים, נותנים מקום זה לזה, אלו שעולים, מכים זה בזה, ומנגנים נגון. וגם כן אלו שיורדים מנגנים."],[0,"","[ב] \u0003אלין דסלקי דנגני וכו׳:\u0004 אלו העמודים העולים שמנגנים נגון, איזה נגון הם מנגנים. הוא שיר יתום, שלא נזכר שם אמרו. מזמור שירו לה׳ שיר חדש כי נפלאות עשה וגו׳. שואל, שיר חדש, וכי יש שיר ישן. אלא הוא שיר, שעד עתה עוד המלאכים לא שבחו אותו, משום שהוא חדש. מה הטעם הוא חדש. הוא משום שאותו שמחדש נעוריו, דהיינו נער מטטרון, משבח אותו ואמרו, וכך אמר רב מתיבתא. מטטרו״ן זה נקרא חדש, והוא חדש, משום שמחדש נעוריו תמיד, והוא משום שדבוק בשמש, שהוא ז״א, ואינו נפרש ממנו. להוציא את סטרא אחרא שאין בו חידוש, שכתוב בו, ואין כל חדש. כי זקן הוא, ונבלה ואינו מתחדש."],[1,"תו פתח רב וכו׳:","עוד פתח רב מתיבתא, שרה נתחדשה בעדון, כי המדרגה שלה שהיא נקבה גרמה, שכתוב אחרי בלותי היתה לי עדנה. מהו עדנה. היא המשכה של עדן העליון, שהוא חכמה. ומשום שנמשך עליה מבחינת נקבה, כתוב \u0003עדנה\u0004 עם \u0003ה׳,\u0004 וע״כ כתוב היתה ולא היה. (וע' להלן חקת אות נ״ט)."],[2,"ואדני זקן:","שואל וכי משום שהוא זקן אינו ראוי להוליד. הרי גם זקנים מולידים. ומשיב, אלא, לא אמרה עליו דבר קטן, שאמרה, משום אותו זקן, שהוא הס״א, כנ״ל, שאין בו חידוש ותולדות כנ״ל, אין אברהם מתחדש ואינו עושה תולדות, כי אם היה הס״א מעמיד תולדות היה מטשטש העולם. ועל זה השיב הקב״ה למה זה צחקה שרה וגו׳. לומר, שזקן דס״א שולט באברהם. שואל. וא״ת והרי כתוב ואברהם זקן בא בימים. הרי שגם הכתוב, קורא לאברהם זקן. ומשיב, אלא הכתוב אומר \u0003בא בימים,\u0004 שהפירוש הוא, שבא באלו ימים העליונים דז״א, שמחדשים נעוריהם כנשר. וע״כ, על שם ימים העליונים אלו, נגון זה דמזמור לה׳ שיר חדש, הוא ניגון של חדש ההוא, שהוא מטטרון הדבוק בימים העליונים דז״א. \u0003הושיעה לו.\u0004 למי. היינו הושיעה לאותו חדש, שהוא כולל הימין של מלך העליון, שהוא ז״א, והזרוע שלו, דהיינו גם השמאל. וע״כ כתוב, ימינו וזרוע קדשו."],[3,"אינון דנחתי אוף וכו׳:","עד כאן פירש השירה של העמודים העולים למעלה. ועתה מפרש, אלו העמודים היורדים ממעלה למטה, מנגנים גם כן ואומרים שירה אחרת, יתומה, דהיינו שלא נזכר שם אומרה, ומה היא. היא מזמור לתודה, שהיא יתומה גם כן."],[4,"נהורא דלהון חד וכו׳:","האור של העמודים, נראה אור אחד, וכשמתגלגלים נראים בכל עמוד ועמוד חמשה אפנים של אור. עמודים אלו חלולים המה כולם מבפנים, וכשעולים ויורדים, יוצאות מהם להבות אש כעין כפתור ופרח. למעלה מכל עמוד ועמוד יש שלשה תפוחים, שמזדווגים בהם ג׳ צבעים, אדום ירוק לבן, ובכל צבע וצבע לוהטות אותיות בולטות, מלהבות אש ירוקות, ואינם שקטים לעולם. ואין מי שיעמוד עליהם וישיג אותם."],[4,"","ביאור המאמר. כבר ידעת שסוד השלמות באה בי״ב בחינות, שה״ס חו״ג תו״מ שבכל אחד ג׳ קוין. וה \u0003עזרה,\u0004 ה״ס מלכות, המקבלת אלו י״ב בחינות מתנה״י דז״א, ונקראים אצלה י״ב שבטים. ועד״ז הכלל ישראל, מחולק לי״ב שבטים, שכל שבט מקבל מבחינה שכנגדו בי״ב הבחינות שבעזרה, שהיא המלכות. וסוד ה \u0003פתחים\u0004 כבר נתבאר לעיל, (פרשת ויקהל אות קל״א בהסולם) ותראה שם שהמסך החוצה בין כו״ח של המדרגה ובין בינה ותו\"מ שלה, שהמסך הזה מוריד בינה ותו״מ של המדרגה למדרגה תחתונה בעת קטנות. ומחזיר ומעלה את הבינה ותו״מ של המדרגה, ביחד עם המדרגה התחתונה המחוברת בבינה ותו״מ אלו, בעת גדלות, הנה המסך הזה נבחן לפתח בשביל התחתונה, כי לולא המסך הזה לא היה שום מציאות שיוכל התחתון להכנס לעליון ולקבל ממנה אורותיו. כמ״ש שם, עש\"ה. והנה נשמות ישראל הן מעולם הבריאה, שהן מדרגה תחתונה של המלכות. ונמצא שהמסך שמתחת כתר וחכמה שבי״ב בחינות דעזרה, שהיא המלכות, מוריד הבינה ותו״מ די״ב בחינות שבמלכות, לי״ב השבטים של ישראל, בעת קטנות, ואותו המסך חוזר ומעלה את הבינה ותו״מ עם י״ב שבטי ישראל אל מדרגת העזרה שהיא המלכות, בעת גדלות. ונמצא שהמסך שמתחת חו״ב שבכל בחינה שבעזרה, הוא הפתח להעלות את אותו השבט שבישראל, שבינה ותו״מ דאותה הבחינה היו מלובשים בו בעת קטנות. וז״ש (באות רמ״ג) \u0003בהאי עזרה אית י״ב פתחין לפום חושבן שבטיא דישראל.\u0004 דהיינו י״ב המסכים שמתחת כו״ח די״ב בחינות שבמלכות הנקראת עזרה, אשר הבינה ותו״מ דכל בחינה ובחינה מלובשת בהבחינה שכנגדה בנשמות די״ב שבטי ישראל. וז\"ש, \u0003בפתחא חדא כתיב ראובן ובפתחא\u0004 וכו׳ \u0003וכן כל שבטיא דישראל.\u0004 כי במסך דכל בחינה, נבחן הבחינה שכנגדה בי״ב שבטי ישראל. \u0003מאן דעייל בפתחא דרשים ביה ראובן, אי משבטא דראובן איהו.\u0004 דהיינו שבינה ותו״מ דאותו בחינה מלובשים בו בקטנות, \u0003מקבלין ליה פתחין,\u0004 כלומר, שבעת גדלות, בזמן הראיה, שהמסך מעלה את הבינה ותו״מ שלו, נמצא מעלה גם אותו השבט המחוברים מעת קטנות בבינה ותו״מ אלו. \u0003ואי לא, פלטין ליה לבר,\u0004 שאם אינו מחובר בבינה ותו״מ של אותו בחינה, לא יוכלו להעלותו, כי אין לו שום מגע עמו. \u0003וכן בכלהו. ובדא יתחקקון, וישתמודען כל חד וחד,\u0004 יתחקקון, פירושו קטנות, כי כל אחד ואחד נמצא נחקק בעת קטנות, מבינה ותו״מ שבבחינה שכנגדו בהפתח דעזרה, שהוא המסך, כי המסך מוריד, בינה ותו״מ של בחינתו שבמלכות, אליו בעת קטנות. ועל דרך זה, \u0003וישתמודען,\u0004 שפירושו גדלות, שאז המסך מעלה אותו, מחמת שבינה ותו״מ דבחינתו נמצאים בו."],[4,"","ונודע שד׳ ספירות תנה״י דז״א, דהיינו מחזה ולמטה מלובשים במלכות (כנ\"ל ויקהל אות ש״י ד״ה וצריך) דהיינו בעזרה. והם כלולים זה מזה, באפן, שכל אחת ואחת מתנה״י כלולה מכל ד׳ ספירות תנה״י, כי היסוד כלול מתנה״י וכן ההוד כלול מתנה״י וכו'. ובהיות בהם המוחין מבינה, נחשבת כל ספירה למאה ספירות כמו הספירות דבינה (כנ\"ל ב״א דף קס\"ז ד״ה ומכאן) ונמצאות ג׳ ספירות נה״י, שהם שלש מאות. וספירת הת״ת, שאינה בשלמותה אלא מחזה שלה ולמטה, לפעמים נחשבת לחצי ספירה דהיינו לחמשים. ומבחינה זו נמצאות ד׳ ספירות תנה״י, שהם ג׳ מאות וחמישים (כנ״ל אות קע״א) ולפעמים אנו מחשבים את הת״ת לג׳ שלישים, ששליש עליון נמשך עד החזה, ומחזה ולמטה נמצאים ב׳ שלישי הת״ת. וכשאלו המאה מתחלקת בהם, נמצאות ל״ה מהם בשליש העליון דת״ת עד החזה, וס״ה בב׳ השלישים דת״ת שמחזה ולמטה, ומבחינה זו נמצאות מספר ד׳ ספירות תנה״י, שהם שלש מאות וששים וחמשה, שלש מאות מנה״י, וס״ה מב׳ שלישי ת״ת. והטעם ששליש עליון יש לו חלק אחד וב״ש יותר מן חלק התחתון שבת״ת, הוא משום שכתר דב״ש ת״ת התחתון, שה״ס חזה, נחשב לרגלים דשליש עליון."],[4,"","וז״ש (באות רמ״ד/א) \u0003תלת מאה ושתין וחמש עמודין דנהורא מלהטא,\u0004 כי היסוד דז״א נקרא \u0003עמוד,\u0004 ובהיותו כלול מתנה״י יש בו שס״ה בחינות כנ״ל וע״כ יש שס״ה עמודים. בכל סטרא מאינון ארבע סטרין, ד׳ רוחות דעזרה היינו חו״ג תו״מ שבמלכות, וכל אחת מהם כלולה משס״ה עמודים, שהם בחינות היסוד דז״א. והיסוד דז״א נקרא \u0003חי.\u0004 וז״ש, \u0003כל אלין אקרון עמודיו חיים,\u0004 שה״ס שס״ה עמודים חיים, \u0003בגין דלא קיימא נהורא דלהון, שכיך באתר חד, וכלהו אלין סלקין ואלין נחתין.\u0004 פירוש, שהם תמיד בבחינת הזווג עם המלכות, אלא פעם עולים ופעם יורדים. כי אין זווג אלא מסוד הדעת, וע״כ לפני כל זווג עולה היסוד עד הדעת. ופירוש הדבר. כי כל המוחין דז״א באים מסוד הכרעתו בין ב׳ קוין דבינה, שאז כיון \u0003דתלת מחד נפקי,\u0004 כיון שחב״ד דבינה יוצאים ע״י ז״א שנעשה לקו אמצעי, שה״ס דעת, ליחד חו״ב דבינה, \u0003חד בתלת קיימא,\u0004 גם הז״א זוכה באלו המוחין חב״ד שגרם בבינה (כנ״ל ב״א דף רפ״ז ד״ה תלת) ועיקר כח הכרעה שבז״א ליחד ב׳ קוין דבינה, הוא מכח היסוד שלו, שה״ס המסך דחירק שבו (כנ״ל לך י״ג ד״ה ונתבאר) והדינים שבצד שמאל דדעת דז״א, יש בהם בחי׳ השפעה ובחינת קבלה, ובחינת ההשפעה שבהם נקראת \u0003יסוד,\u0004 ובחינת הקבלה שבהם נקראת \u0003מלכות.\u0004 ונמצא שהיסוד גרם למוחין דחב״ד דז״א, וכל השעור של אור שהתחתון גרם לעליון זוכה בו גם התחתון. ולפיכך, אחר שז״א קבל חב״ד מבינה, נבחן, כיון שכח ההכרעה שבדעת דז״א הוא יסוד נמצא שיסוד הוא הגורם שיצאו חב״ד בז״א ע״כ זכה בהם גם היסוד. כי כל מה שהתחתון גורם לעליון זכה בו גם התחתון, וכן קו האמצעי שבחג״ת דז״א, שכח ההכרעה שבו הוא היסוד, ע״כ זכה בהם גם היסוד. ומכ״ש במקומו עצמו שהוא תנה״י דז״א, ומטעם זה נכלל היסוד דז״א משפע המוחין דחב״ד דז״א, ומשפע המוחין דחג״ת דז״א. ומנו\"ה דז״א, וממשיכים למקומו לבחינת יסוד דז״א, ומשם משפיע אותם אל המלכות."],[4,"","ולפני כל השפעה והשפעה שהיסוד משפיע למלכות, הוא צריך \u0003להתחדשות,\u0004 כלומר שצריך \u0003לעלות\u0004 מחדש אל הדעת דז״א, ולהכריע בין חו״ב דז״א, ולקבל משפע הג״ר, ואח״כ \u0003יורד\u0004 לחג״ת ואח״כ למקומו לנה״י, ואח״כ משפיע אל המלכות. וז״ש, \u0003וכלהו, אלין סלקין, ואלין נחתין,\u0004 דהיינו ש \u0003עולים\u0004 עד הדעת לקבל שפע הג״ר, ואח״כ \u0003יורדים\u0004 ונותנים ההשפעה אל המלכות. ואע״פ שיש שינוי בין עליה לירידה, כי העולים הם עולים בכח שליטת הימין, כי רוצים למעט השמאל ולכללו בימין. והיורדים להשפיע למלכות הם משפיעים מבחינת השמאל בעיקר, כי המלכות צריכה לשפע החכמה שבשמאל, עכ״ז אינם מעכבים זה לזה, וכל אחד עושה כפי שצריך. וז״ש, \u0003יחבי דוכתא דא לדא,\u0004 שאינם מעכבים משהו זה לזה."],[4,"","וגילוי אורות העליונים, נמשכים בסוד הגגון. וז״ש (באות רמד/א) \u0003אלין דסלקין בטשין דא בדא,\u0004 שהעולים מיחדים בין ב׳ הקוין חו״ב, ובטישא פירושו יחוד וזווג הבא ע״י כח מלמטה, דהיינו היסוד, ומנגני נגונא, דהיינו שמתגלה השפע דג׳ קוין חב״ד. \u0003ואלין דנחתי אוף הכי\u0004, כמ״ש לפנינו. וז״ש (באות רמ״ד/ב) \u0003מאי נגונא מנגני, שיר יתמא, מזמור שירו לה׳ שיר חדש וגו'. שיר חדש וכו׳ דעד כען מלאכין קדישין לא שבחו ליה בגין דאיהו חדש\u0004. כלומר, שגילוי האורות הנמשכים ע״י עלית היסוד מחדש אל הדעת, היא \u0003גילוי חדש\u0004, שהמלאכים עוד לא ידעו ממנו לשבח אותו. כי בכל עליה ועליה נמשכת השפעה חדשה שלא היתה עוד בעולמות. וז״ש \u0003מאי טעמא איהו חדש, בגין דההוא דמחדש עולימוי משבח ליה, ואמר ליה\u0004, שהוא מטטרון, שהוא מרכבה אל זווג יסוד דז״א ומלכות, והוא הראשון המקבל הארה החדשה הזו שהמשיך היסוד מלמעלה. וממנו מקבלים כל המלאכים. וז״ש \u0003דא אקרי חדש ואיהו חדש בגין דדביק בשמשא ולא אתפרש מניה\u0004, שהוא דבוק בז״א שנקרא שמש, ואינו נפרד ממנו, וע״כ הוא הראשון, המקבל שפע החדש מיסוד דז״א. \u0003לאפקא סטרא אחרא דלית ביה חדושא\u0004, כי הסטרא אחרא אין להם מוח הדעת, ששם עולה היסוד ומחדש זווגם בכל פעם, ובאים ע״י זווג זה תמיד אורות חדשים ותולדות חדשות, אלא שיש להם רק ב׳ מוחין חכמה ובינה בלבד, וכיון שהם מחוסרי דעת, לא יצא מחכמה ובינה שלהם שום דבר חדש, אלא אותה מדת ההארה הנקלטת בחכמה ובינה שלהם בתחילת הויתן, הולכות ונשנות ומוחזרות בכל פעם כמו שהיו בתחילה, בלי הוספה כל שהוא, עד שנבחנים שנשחקת ונבלה מרוב שמוש בה, וז״ש, \u0003זקן הוא ואתבלי ולא אתחדש\u0004, דהיינו שהולך ובלה כמו זקן, שכחותיו הולכים ועוזבים אותו לאט לאט עד שנתבלה והולך לו. וז״ש (באות רמ״ו), \u0003וע״ד נגונא דא\u0004 שהעמודים מנגנים בשעת עלייתם לחב״ד, \u0003נגונא דההוא חדש איהו\u0004, שהוא מטטרון כנ״ל, וגם העמודים מנגנים אותו משום שהם מתחדשים בשפע חדש בעת עלייתם לחב״ד כנ״ל. וזה שממשיך הכתוב, \u0003הושיעה לו, למאן. לההוא חדש הושיעה ימינא דמלכא עלאה, ודרועא דיליה\u0004. כלומר שהוא טעם ב׳ למה, שהעמודים שהם יסוד דז״א, מנגנים שיר הזה בעת עליה, כי הכתוב מדבר בהכרעת קו האמצעי, ש \u0003חדש\u0004 ההוא, שהוא יסוד, מייחד \u0003ימינא דמלכא עלאה\u0004 וזרוע קדשו, שהוא השמאל בעת עליתו זו כנ״ל. וז״ש (באות רמ״ז) \u0003אינון דנחתי אוף הכי מנגני\u0004 וכו׳ \u0003מזמור לתודה.\u0004 והוא מטעם שכתוב בו, הריעו לה׳ כל \u0003הארץ,\u0004 שהיא המלכות הנקראת ארץ, וכיון שהעמודים יורדים להשפיע למלכות, ע״כ אומרים זה."],[4,"","וז״ש (באות רמ\"ח) \u0003נהורא דלהון חד אתחזי,\u0004 שהאור של כל שס״ה העמודים הם אור אחד, כי כולם בחינת יסוד הם. \u0003וכד מתגלגלי,\u0004 דהיינו כשמאירים בהארת הקוין הנקרא גלגול (כנ\"ל ויחי דף קנ״ט ד״ה קל גלגלא) אז נכלל היסוד מכל ה׳ בחינות כח״ב תו״מ, אשר מבחינת החסדים, נקראים חג״ת נ״ה (כנ״ל בהקדמת ספר הזהר דף י״א במראות הסולם ד״ה ומה) וז״ש \u0003אתחזן חמש גוונין דנהורין בכל עמודא ועמודא,\u0004 כי כל אחד משס״ה העמודים כולל אז חג״ת נ״ה. אמנם היסוד עצמו אינה בחינה ששית, כי אין יותר מה׳ בחינות שמבחינת החכמה נקראות כח״ב תו״מ ומבחינת החסדים נקראות חג״ת נ״ה. אבל היסוד אינו בחינה נוספת עליהן, אלא שהוא רק בחינת כולל, שכולל את ה׳ בחינות אלו, וז״ש, \u0003עמודין אלין כלהו חללין מלגאו,\u0004 כלומר, שאין בהם בחינת תוך ותוכן, משום שזולת ה׳ בחינות אין עוד שום בחינה של אור וע״כ אין בהם שום תוכן. ונבחן שהם חללים בלי תוכן של צורת אור. אלא שיש בהם ב׳ בחינות דינים, דינים דימין, ודינים של שמאל, שהיסוד נושא אותם כי ע״כ נבחן לשמאל של הדעת כנ״ל בדבור הסמוך. כי המכריע כולל ימין ושמאל וכמו שהימין דדעת כולל ב׳ האורות דימין ושמאל כן השמאל דדעת כולל ב׳ הדינים דימין ושמאל. והם נקראים כפתור ופרח. כי דינים דימין, שה״ס ה \u0003י׳\u0004 שנכנסה באויר, שה״ס נקודת החולם, נקראים \u0003כפתור,\u0004 והוא אותיות כפת אור, כי האור נקשר בימין בכח דינים הללו. ודינים דשמאל, שהאור דחסדים \u0003פורח\u0004 מהם ונשארים בחכמה בלי חסדים, שאינה יכולה להאיר, היא נקרא משום זה \u0003פרח,\u0004 מלשון פריחה, שהאורות פורחים משם, כי אפילו החכמה אינה מאירה. ועוד טעם, משום שכל כח השמאל בא ע״י יציאת ה \u0003י׳\u0004 מאויר שחוזר לאור שה״ס נקודת השורק וע״כ נבחן, שה \u0003י׳ פורחת\u0004 באויר, ויוצאת משם. וז״ש, \u0003וכד סלקי ונחתי, נפקי מנייהו שלהובין דנורא,\u0004 דהיינו ב׳ בחינות דינים הנ״ל, \u0003כגווני חיזור ושושן,\u0004 שדינים דימין ה״ס חיזור, דהיינו \u0003כפתור,\u0004 ודינים דשמאל ה״ס שושן, דהיינו \u0003פרח.\u0004"],[4,"","והנה אחר שביאר היטב סוד העמודים שבעזרה, שה״ס יסוד דז״א, מבאר עתה, צורת השפע הקבועה במדת היסוד, להשפיע למלכות, כי אע״פ שאין בחינת השפעה אחת דומה לחברתה, וכל השפעה והשפעה היא צורה חדשה שהיסוד משפיע למלכות כנ״ל. עכ״ז יש צורה אחת קבועה וכוללת לכל ההשפעות שבעולם המחויבת בכולן, שה״ס צורה השלמה של י״ב בחינות, שתוכנם הוא ד׳ ספירות חו״ב תו״מ או חו״ג תו״מ, שבכל אחת ג׳ קוין, וג״פ ד׳ הם י״ב. וז״ש, \u0003לעילא מכל עמודא ועמודא,\u0004 דהיינו למעלה מיסוד, \u0003אית תלת תפוחין,\u0004 שה״ס ג׳ קוין, \u0003דבטשי בהו תלת גוונין סומק ירוק וחוור,\u0004 שהם חסד גבורה ת״ת, הבוטשים ומזדווגים עם ג׳ תפוחין אלו, \u0003בכל גוון וגוון מלהטן אתוון בלטי,\u0004 שה״ס \u0003המלכות\u0004 הנקראת אותיות, המתחברת עם ג׳ הגוונים שהם \u0003חג״ת,\u0004 וגוון של האותיות הוא. \u0003משלהובא ירוקא דאשא,\u0004 דהיינו מת״ת, שהוא גוון ירוק, כי המלכות היא דבוקה תמיד בת״ת. \u0003ולא משתככי לעלמין ולית מאן דיקום עלייהו.\u0004 כי מלכות זו היא נחשבת מבחינת היסוד, ואין הארת החכמה מתגלה שם, אלא במלכות הנפרדת, שה״ס הגלגלים, וע״כ אין מי שיוכל לעמוד עליהם, שאי אפשר להשיגם שם. ונמצא שיש כאן ג׳ תפוחים שהם ג׳ קוין ובכל תפוח, דהיינו בכל קו, יש ג׳ גוונים לבן אדום ירוק שהם \u0003חג״ת,\u0004 ואותיות ירוקות שהם \u0003מלכות,\u0004 וג״פ ד׳ הם י״ב בחינות, שזולתם אין השפע שלם. והנה נתבאר בחינות העמודים שהם יסוד דז״א, והשפע הכולל שעל היסוד, שהוא צורת ג׳ תפוחים, שבכל תפוח חוג תו״מ. ועתה יבאר לפנינו צורת המלכות הנפרדת, שה״ס הגלגלים שמתחת העמודים, וצורת השפע הכוללת שבהם לתחתונים, וסוד ב׳ הזווגים, זווג דבוקר וזווג דחצות. וכו'."],[5,"ארבע גלגלין מתחמן וכו׳:","ארבעה גלגלים מעשה רוקם, מתפשטים ומסבבים בכל עמוד ועמוד, משס״ה עמודים הנ\"ל, שבכל צד של העזרה. באלו הגלגלים יש נפלאות גדולות. כשמסתובבים מוציאים מהם זגי זהב ואבני יקר, ומיד נאספים בתוכם, ואינם נופלים לארץ. בעת שיוצאים אלו זגי זהב ואלו אבני יקר, נשמע קול מתוך הסתובבות הגלגלים, שאומרים, זאת נחלת עבדי ה׳ וצדקתם מאתי נאום ה'."],[6,"תרין אריין וכו׳:","ב׳ אריות הם בכל גלגל וגלגל, אריה אחד מצד אחד ואריה אחד מצד אחד. וכולם מאש ירוקה. ובגלגולא שהגלגלים מסתובבים מתחבקים האריות אלו באלו, והולכים כולם, בגלגול מתדבקים זה בזה. כשהעמודים עולים, נוהמים האריות אלו באלו, ותפוחים פורחים באויר ועולים למעלה. והתפוחים בוטשים אלו באלו באויר. ואח״כ, חוזרים למקומם, ומשם נופלים. והאריות פושטים ידיהם לקבל אותם, והתפוחים עולים מעצמם. אהה חסיד קדוש, מי ראה החכמה של האומנות, שצייר הקב״ה בעמודים האלו."],[7,"בפלגו יומא נפקי וכו׳:","בחצות היום, יוצאים שני נשרים בכל גלגל וגלגל. (ל״ג ולא ידיע אתר דנפקי מתמן), והם שורים על ראשיהם של האריות האלו. ואז משתככים העמודים והגלגלים, ועומדים בקיומם. ותפוחים נופלים על פיהם של הנשרים, והם מקבלים אותם. ומיד פורחים התפוחים מפה לפה, (ל״ג ואזלין ומשטטי בינייהו ותבו לאתרייהו ולא ידיע מאן היא). לאחר שעה ומחצה הנשרים מרימים קולם ומנגנים נגדן נחמד, ומסתתרים, (ל״ג ולא ידיע בהי אתר)."],[7,"","ביאור המשך המאמר. אחר שכבר ביאר כל הבחינות שביסוד והשפע שעליו, ממשיך לבאר את המלכות המקבלת ממנו שספירותיה נקראים \u0003גלגלים,\u0004 וסוד הזווג של יסוד ומלכות. וז״ש, (באות רמ״ט) \u0003ארבע גלגלין מתהמן עובד ציור בכל עמודא ועמודא,\u0004 כי השפע היוצא מכל עמוד כלול מחו\"ג תו״מ, וצריך לארבע מלכיות דחו״ג תו״מ שיקבלו, וע״כ יש כנגד כל עמוד ד׳ גלגלים. ומפרש סוד השפע המקובל במלכות בשביל התחתונים. ואומר, \u0003כד מסתחרן,\u0004 כי אין השפע מתגלה אלא בדרך גלגול, כנ״ל, \u0003מפקין מנייהו זגי דדהבא ואבני יקר,\u0004 זגי דדהבא, פירושו הארות החכמה מקו שמאל. ואבני יקר, ה״ס הארות החסדים. \u0003כד נפקין אינון\u0004 וכו' \u0003אשתמע קלא דאמרי זאת נחלת עבדי ה׳\u0004 וגו'. דהיינו שמכריז שזה השפע מוכן להתקבל לעבדי ה', והוא נחלתם."],[7,"","עתה מבאר סדר זווג הבוקר. שאז שולט החסד. ואומר (באות ר״נ) \u0003ב׳ אריין בכל גלגלא וגלגלא,\u0004 שבכל גלגל, שהוא מלכות, יש ב׳ אריות המקבלים השפע, \u0003אריה חדא מסטרא חדא ואריה חדא מסטרא חדא,\u0004 דהיינו אחד מבחינת ימין המלכות ואחד מבחינת שמאל המלכות. ואפילו אותו שבשמאל נקרא ג״כ אריה, שהוא שם החסד, להורות שבבוקר שליטת הימין הוא, וגם השמאל הוא בצורה של ימין, שהוא אריה. אבל, \u0003וכלהו מאשא ירוקא,\u0004 שהוא הגוון הנקרא ת״ת, מפני שהמלכות בכללה היא נמצאת באמצע בין ימין לשמאל, שנבחן לת״ת, וגוון ירוק. \u0003ובגלגולא דקא מסתחרן,\u0004 דהיינו בעת גילוי השפע, שאינה באה אלא ע״י גלגול, כנ\"ל, \u0003מתחבקן אלין באלין,\u0004 שהימין והשמאל מתחבקים להיות אחד, \u0003ואזלי כלהו בגלגולא, מתדבקן\u0004 וכו', דהיינו כלולים זה בזה. \u0003כד סלקין עמודין,\u0004 דהיינו כשהיסוד עולה לחב״ד לקבל שפע ולהתחדש כנ״ל, (באות רמ\"ח) \u0003מנהמן אריין אלין באלין,\u0004 דהיינו אותם שבימין באותם שבשמאל, כי מטרם הגלגול אינם עוד בחינה אחת, \u0003ותפוחין,\u0004 שהם השפע שעל היסוד, כנ״ל, \u0003פרחין באוירא וסלקין לעילא,\u0004 דהיינו שהם עולים יחד עם העמודים שהם היסוד, כדי לפרוח באויר, דהיינו לקבל שפע מג״ר שהם בסוד כניסה ויציאה מאויר, \u0003ובטשי אלין באלין באוירא,\u0004 שהם נכללים אלו באלו שם, \u0003ותבו לאתרייהו,\u0004 דהיינו שיורדים יחד עם העמודים, למקומם, שה״ס המלכות שנקראת מקום, \u0003ומתמן נפלי,\u0004 דהיינו מכח חבורם עם המלכות נופלים התפוחים מן היסוד אל המלכות, \u0003ואריין,\u0004 שהם מקבלי השפע שבמלכות, \u0003פשטי ידייהו לנטלא לון,\u0004 דהיינו לקבל התפוחים, \u0003וסלקין אלין מגרמייהו,\u0004 כלומר שהארתם עולה ממטה למעלה מעצמם, והאריות מקבלים אותם, ואינם נמשכים ונופלים למטה ממלכות. והיינו מפני שפע החכמה הכלולה שם, שאינה מאירה אלא ממטה למעלה. והנה נתבאר זווג הבוקר שהוא בשליטת הימין. שהוא חסד."],[7,"","ועתה מבאר זווג דחצות היום. וז״ש (באות רנ״א) \u0003בפלגו יומא נפקי תרין נשרין בכל גלגלא וגלגלא,\u0004 כי חצי יום הראשון הוא חסד דהיינו ימין, וחצי יום השני הוא דין, דהיינו שמאל, ובאמצע שהוא חצות היום, כלול משניהם מחסד ודין, שהוא צורת פני נשר הכלול מאריה ושור שהם ימין ושמאל, וע״כ יוצאים אז בחינת המקבלים שבמלכות שבימינה ושבשמאלה, בצורת ב׳ נשרים בכל גלגל, אחד לימין ואחד לשמאל, כנ״ל אצל ב׳ אריות. \u0003ושריין על רישיהון דאלין אריין,\u0004 דהיינו שהם שולטים בעת ההוא על האריות. ואז זמן הזווג של העמודים והגלגלים שהם יסוד ומלכות, וז״ש, \u0003וכדין משתככי עמודין וגלגלין\u0004 דהיינו שמשתככים מגלגולם, \u0003וקיימי בקיומייהו,\u0004 דהיינו שמזדווגים אלו עם אלו. ואז \u0003ותפוחין נפלי,\u0004 שהשפע נופל מן העמודים, שהם יסוד, \u0003על פומייהו דנשרי,\u0004 שהם מקבלי השפע שבמלכות, \u0003ומקבלי לון,\u0004 והם מקבלים התפוחין מן העמודים, \u0003ומיד פרחין מפומא לפומא,\u0004 שהשפע פורח מפיהם של נשרים שבימין לפיהם של הנשרים שבשמאל וכן להיפך, כדי להכלל מימין ומשמאל. ועם כל זה גם הזווג הזה שבחצות, נוטה אל הימין, וע״כ אינו נמשך אלא שעה וחצי, שה״ס קו וחצי קו דימין שבעת ההוא, כי ג׳ קוין מכונים ג׳ שעות. וכשנגמר זה ומתחיל להאיר קו וחצי קו משמאל, אז נפסק זווג הזה. וז״ש, \u0003לבתר שעתא ופלגא,\u0004 דהיינו אחר שנגמר להאיר קו וחצי קו של צד הימין, שהם חכמה, וחצי הימני של הדעת, ומתחיל להאיר קו וחצי קו דשמאל, שהם בינה וחצי השמאלי של הדעת, אז \u0003נשרין ארימין קלא, ומנגנין נגונא תאיבא,\u0004 דהיינו שמתחילים לקבל מן השמאל, ששפעו בא בהרמת קול ובניגון נחמד, אבל \u0003ואתטמרן,\u0004 שהם מסתתרים תיכף, וההארה נפסקת. כי מחמת שה״ס פני נשר הכלולים מימין ומשמאל הם יכולים לקבל תחילת הארת השמאל, אבל מפני שהימין מתחיל להתמעט אז בזמן שליטת קו וחצי דשמאל, ע״כ הם מסתתרים ונעלמים."],[8,"סחרנייהו דאינון עמודין וכו׳:","מסביב אלו העמודים, יש שבכות מעשה רוקם, שה״ס הארת הבינה המלובשת שם, המעורבת ומסובכת ונקלעת יחד עם המלכות, וע״כ נקראת, שבכה מעשה רוקם. והיא מקולעת מאש אדום, שהיא הארת השמאל, ומאש לבן, שהוא הארת הימין, וחוטי זהב, שהוא הארת השמאל שבבינה הנקרא זהב. סביב סביב מקיפים אותו מכל צד. ויש שם מעין של מים. כש״א, והיה ביום ההוא יצאו מים חיים מירושלים חצים אל הים הקדמוני וחצים אל הים האחרון."]],[[0,"","שְׁלֹש מֵאוֹת וְשִׁשִּׁים וַחֲמִשָּׁה עַמּוּדֵי אוֹר לוֹהֵט יֵשׁ בְּכָל צַד מֵאוֹתָם אַרְבָּעָה צְדָדִים. כָּל הָעַמּוּדִים הַלָּלוּ נִקְרָאִים עַמּוּדִים חַיִּים, מִשּׁוּם שֶׁלֹּא עוֹמֵד אוֹרָם שׁוֹכֵךְ בְּמָקוֹם אֶחָד. וְכֻלָּם, אֵלּוּ עוֹלִים וְאֵלּוּ יוֹרְדִים, נוֹתְנִים מָקוֹם זֶה לָזֶה. אֵלּוּ שֶׁעוֹלִים מַכִּים זֶה בָּזֶה וּמְנַגְּנִים נִגּוּן, וְאֵלֶּה שֶׁיּוֹרְדִים גַּם כָּךְ. אֵלֶּה שֶׁעוֹלִים שֶׁמְּנַגְּנִים נִגּוּן, אֵיזֶה נִגּוּן מְנַגְּנִים? שִׁיר יָתוֹם. (תהלים צח) מִזְמוֹר שִׁירוּ לַה' שִׁיר חָדָשׁ כִּי נִפְלָאוֹת עָשָׂה וְגוֹ'. שִׁיר חָדָשׁ, וְכִי יֵשׁ שִׁיר עַתִּיק? אֶלָּא שִׁיר, שֶׁעַד כָּעֵת מַלְאָכִים קְדוֹשִׁים לֹא שִׁבְּחוּ לוֹ, מִשּׁוּם שֶׁהוּא חָדָשׁ. מָה הַטַּעַם הוּא חָדָשׁ? בִּגְלַל אוֹתוֹ אֶחָד שֶׁמְּחַדֵּשׁ עֲלוּמָיו, מְשַׁבְּחוֹ וְאוֹמֵר לוֹ. וְכָךְ אָמַר רֹאשׁ הַיְשִׁיבָה, זֶה נִקְרָא חָדָשׁ וְהוּא חָדָשׁ, מִשּׁוּם שֶׁדָּבֵק בַּשֶּׁמֶשׁ וְלֹא נִפְרָד מִמֶּנּוּ. לְהוֹצִיא סִטְרָא אַחֲרָא שֶׁאֵין בָּהּ חִדּוּשׁ, שֶׁכָּתוּב בָּהּ (קהלת א) וְאֵין כָּל חָדָשׁ. זָקֵן הוּא וּבָלֶה, וְלֹא הִתְחַדֵּשׁ. (ולא עושה תולדות. ואלמלא עשה תולדות, היה מטשטש העולם)."],[1,"","עוֹד פָּתַח רֹאשׁ הַיְשִׁיבָה. שָׂרָה הִתְחַדְּשָׁה בְעִדּוּן, דַּרְגָּתָהּ גָּרְמָה, שֶׁכָּתוּב (בראשית יח) אַחֲרֵי בְלֹתִי הָיְתָה לִּי עֶדְנָה. מַה זֶּה עֶדְנָה? מְשִׁיכַת עֵדֶן הָעֶלְיוֹן. וּמִשּׁוּם שֶׁנִּמְשַׁךְ עָלֶיהָ מִצַּד נְקֵבָה, כָּתוּב עֶדְנָה בְּהֵ\"א, וּמִשּׁוּם זֶה כָּתוּב הָיְתָה, וְלֹא הָיָה."],[2,"","וַאדֹנִי זָקֵן. וְכִי אַף עַל גַּב שֶׁהוּא זָקֵן לֹא רָאוּי לְהוֹלִיד? אֶלָּא לֹא דָבָר קָטָן אָמְרָה עָלָיו, (שאברהם אלא) שֶׁבִּגְלַל (להקטין עצמה שנדבקה) אוֹתוֹ (מלך) זָקֵן (שנדבקה) (וכסיל), לֹא מִתְחַדֵּשׁ וְלֹא עוֹשֶׂה תוֹלָדוֹת, שֶׁאִלְמָלֵא הָיָה עוֹשֶׂה תוֹלָדוֹת, הָיָה מְטַשְׁטֵשׁ אֶת הָעוֹלָם. (אלא אמרה על אברהם, בגלל שהוא זקן לא יתחדש ולא יעשה תולדות) וְעַל זֶה הַקָּדוֹשׁ בָּרוּךְ הוּא הֶחֱזִיר דְּבָרִים, לָמָּה זֶּה צָחֲקָה שָׂרָה וְגוֹ'. וְאִם תֹּאמַר, וַהֲרֵי כָּתוּב (שם כד) וְאַבְרָהָם זָקֵן בָּא בַּיָּמִים? אֶלָּא בָּא בַּיָּמִים, בְּאוֹתָם יָמִים עֶלְיוֹנִים שֶׁמְּחַדְּשִׁים עֲלוּמִים כַּנֶּשֶׁר. וְעַל זֶה נִגּוּן זֶה נִגּוּן שֶׁל אוֹתוֹ חָדָשׁ הוּא. הוֹשִׁיעָה לּוֹ, לְמִי? לְאוֹתוֹ חָדָשׁ, הוֹשִׁיעָה יְמִין הַמֶּלֶךְ הָעֶלְיוֹן וּזְרוֹעוֹ."],[3,"","אוֹתָם שֶׁיּוֹרְדִים גַּם כֵּן מְנַגְּנִים, וְאוֹמְרִים שִׁירָה יְתוֹמָה אַחֶרֶת. וּמַהִי? (תהלים ק) מִזְמוֹר לְתוֹדָה, שֶׁהוּא יָתוֹם, גַּם כָּךְ."],[4,"","אוֹרָם אֶחָד נִרְאֶה. וּכְשֶׁמִּתְגַּלְגֵּל, נִרְאִים חֲמִשָּׁה גְוָנִים שֶׁל אוֹרוֹת בְּכָל עַמּוּד וְעַמּוּד. הָעַמּוּדִים הַלָּלוּ כֻּלָּם חֲלוּלִים מִבִּפְנִים, וּכְשֶׁעוֹלִים וְיוֹרְדִים, יוֹצְאִים מֵהֶם שַׁלְהֲבוֹת אֵשׁ, כְּצוּרוֹת כַּפְתּוֹר וָפֶרַח. מֵעַל כָּל עַמּוּד וְעַמּוּד יֵשׁ שְׁלֹשָׁה תַפּוּחִים שֶׁמַּכִּים בָּהֶם שְׁלֹשָׁה גְוָנִים, אָדם יָרֹק וְלָבָן. בְּכָל גָּוֶן וְגָוֶן לוֹהֲטוֹת אוֹתִיּוֹת בּוֹלְטוֹת מִשַּׁלְהֶבֶת יְרֻקָּה שֶׁל אֵשׁ, וְלֹא שׁוֹכְכִים לְעוֹלָמִים, וְאֵין מִי שֶׁיָּקוּם עֲלֵיהֶם."],[5,"","אַרְבָּעָה גַלְגַּלִּים תּוֹחֲמִים מַעֲשֵׂה צִיּוּר בְּכָל עַמּוּד וְעַמּוּד. בְּאוֹתָם גַּלְגַּלִּים יֵשׁ פְּלִיאוֹת גְּדוֹלוֹת. כְּשֶׁמִּסְתּוֹבְבִים, מוֹצִיאִים מֵהֶם זַגִּים שֶׁל זָהָב וַאֲבָנִים יְקָרוֹת. וּמִיָּד מִתְכַּנְּסִים בְּתוֹכָם וְלֹא נוֹפְלִים לָאָרֶץ. כְּשֶׁיּוֹצְאִים אוֹתָם זַגֵּי זָהָב וְאוֹתָם אֲבָנִים יְקָרוֹת תּוֹךְ סִבּוּב הַגַּלְגַּלִּים, נִשְׁמָע קוֹל שֶׁאוֹמְרִים: (ישעיה נד) זֹּאת נַחֲלַת עַבְדֵי ה' וְצִדְקָתָם מֵאִתִּי נְאֻם ה'."],[6,"","שְׁנֵי אֲרָיוֹת בְּכָל גַּלְגַּל וְגַלְגַּל, אַרְיֵה אֶחָד מִצַּד אֶחָד, וְאַרְיֵה אֶחָד מִצַּד אֶחָד, וְכֻלָּם מֵאֵשׁ יְרֻקָּה, וּבַגִּלְגּוּל שֶׁמִּסְתּוֹבְבִים הַגַּלְגַּלִּים מִתְחַבְּקִים אֵלֶּה בְאֵלֶּה, וְהוֹלְכִים כֻּלָּם בְּגִלְגּוּל, מִתְדַּבְּקִים זֶה בָּזֶה. כְּשֶׁעוֹלִים הָעַמּוּדִים, נוֹהֲמִים הָאֲרָיוֹת אֵלֶּה בְאֵלֶּה, וְהַתַּפּוּחִים פּוֹרְחִים בָּאֲוִיר וְעוֹלִים לְמַעְלָה וּמַכִּים אֵלֶּה בְאֵלֶּה בָּאֲוִיר. וְשָׁבִים לִמְקוֹמוֹתֵיהֶם, וּמִשָּׁם נוֹפְלִים. וְהָאֲרָיוֹת פּוֹשְׁטִים יְדֵיהֶם לְקַבְּלָם, וְעוֹלִים אֵלֶּה מֵעַצְמָם. אִי חָסִיד קָדוֹשׁ, מִי רָאָה חָכְמַת הָאָמָּנוּת שֶׁצִּיֵּר הַקָּדוֹשׁ בָּרוּךְ הוּא בָּעַמּוּדִים הַלָּלוּ?"],[7,"","בַּחֲצוֹת הַיּוֹם יוֹצְאִים שְׁנֵי נְשָׁרִים בְּכָל גַּלְגַּל וְגַלְגַּל, וְלֹא יָדוּעַ מָקוֹם שֶׁמִּשָּׁם יוֹצְאִים, וְשׁוֹרִים עַל רֹאשׁ הָאֲרָיוֹת הַלָּלוּ, וְאָז שׁוֹכְכִים הָעַמּוּדִים וְהַגַּלְגַּלִּים, וְעוֹמְדִים בְּקִיּוּמָם. וְהַתַּפּוּחִים נוֹפְלִים עַל פִּיהֶם שֶׁל הַנְּשָׁרִים, וּמְקַבֶּלֶת אוֹתָם. וּמִיָּד פּוֹרְחִים מִפֶּה לְפֶה, וְהוֹלְכִים וּמְשׁוֹטְטִים בֵּינֵיהֶם, וְשָׁבִים לִמְקוֹמוֹתֵיהֶם, וְלֹא יָדוּעַ מִי הִיא. לְאַחַר שָׁעָה וָחֵצִי מְרִימִים הַנְּשָׁרִים קוֹל, וּמְנַגְּנִים נִגּוּן מָתוֹק, וְנִסְתָּרִים, וְלֹא יָדוּעַ בְּאֵיזֶה מָקוֹם."],[8,"","סְבִיב אוֹתָם הָעַמּוּדִים יֵשׁ שְׂבָכִים מַעֲשֵׂה צִיּוּר. אֵשׁ אֲדֻמָּה וְאוֹר לָבָן וְחוּטֵי זָהָב סָבִיב סָבִיב סוֹבְבִים לְכָל צַד, וּמַעְיַן מַיִם, כְּמוֹ שֶׁנֶּאֱמַר (זכריה יד) וְהָיָה בַּיּוֹם הַהוּא יֵצְאוּ מַיִם חַיִּים מִירוּשָׁלם חֶצְיָם אֶל הַיָּם הַקַּדְמוֹנִי וְחֶצְיָם אֶל הַיָּם הָאַחֲרוֹן."]]],[["הָכָא פָּרִישׁ רַב מְתִיבְתָּא קְרָא דָּא לְגוֹ, וְקַלֵיהּ אִשְׁתְּמַע לְבַר. מִדַּהֲוָה פָּרִישׁ קְרָא דָּא. (אי קדישא אי קדישא) קַל יְנוֹקָא אִתְּעַר מִלְּבַר, הַהוּא יְנוֹקָא דְּהֲוָה פָּרִישׁ תַּלְמוּדֵיהּ, וְגָמִיר קַמֵּי חַד עַמּוּדָא דְּעָלְמָא, בְּרֵיהּ דְּרִבִּי יְהוּדָה, דְּרָבִית אַנְתְּ. וַהֲווּ אַחְדֵּי בֵּיהּ לְדִינָא, וְקַלֵיהּ אִתְּעַר מִלְּבַר, בְּהַאי קְרָא, וְאָמַר, מַיָּא דְּאִינּוּן מִלְּרַע הֵיךְ סַלְּקִין לְעֵילָּא מִנֵּיהּ, לַאֲתָר עִלָּאָה יַתִּיר מִנֵּיהּ, בְּכַמָּה דַּרְגִּין, וּמַה אִצְטְרִךְ לוֹן לְאִינּוּן מַיִין לְעֵילָּא. וּמָה אֲתָר דְּכָל (תפוחי) מַבּוּעִין וּנְחָלִין נָפְקִין מִנֵּיהּ, וְלֵית פְּסִיקוּ לְמַבּוּעֵי וְנַחֲלֵי, אִתְשַׁקְיָא מֵאֲתָר נָגִיב, מַאן חָמָא חֲפִירָא דְּבֵירָא, יָהִיב מַיִין לְמַבּוּעָא דִּנְבִיעַ. וְכִי יְרוּשָׁלַ ם, יָהִיב מַיִין אֶל הַיָּם הַקַּדְמוֹנִי, אֲתָר דְּכָל מֵימִין דְּעָלְמָא נָפְקֵי מִתַּמָּן, וְנַבְעִין מִנֵּיהּ. אִי חֲסִידָא קַדִּישָׁא, לְקָלָא דָּא אִשְׁתְּכָכוּ, וְצָיְיתוּ כָּל קָלִין דִּבְנֵי מְתִיבְתֵּי דְּתַמָּן, וּבְגִין כָּךְ לָא יָכִילוּ מָארֵי דְּדִינָא לְמִקְרַב גַּבֵּיהּ.","בָּכָה רִבִּי שִׁמְעוֹן, אָמַר לֵיהּ לָא תִּבְכֵּי בּוּצִינָא קַדִּישָׁא, זַכָּאָה חוּלָקָךְ, דְּאֲפִילּוּ יְנּוּקֵי, מִנָּךְ אַמְרֵי רָזִין סְתִימִין דְּאוֹרַיְיתָא. תָּא, וְאֵימָא לְךָ, מַה דְּעָבְדוּ בְּנֵי מְתִיבְתֵּי עַל קַלֵיהּ דְּהַהוּא יְנוֹקָא, כַּד עָאל קַלֵיהּ דְּהַהוּא יְנוֹקָא, כְּגִירָא לְגוֹ, וְכֻלְּהוּ צַיְיתֵי לֵיהּ. בְּהַהִיא שַׁעֲתָא אִזְדַּעְזָע רַב מְתִיבְתָּא, וְכָל אִינּוּן דַּהֲווֹ קַמֵּיהּ, וְאָמַר, מַאן אִינּוּן דְּלָא שַׁבְקִין לְהַהוּא בְּרָא דֶּאֱלָהָא חַיָיא, לְמֵיעַל. קָמוּ וְאָחִידוּ בֵּיהּ תְּלַת עַמּוּדִין דְּקַיְימֵי קַמֵּי רַב מְתִיבְתָּא, וְעָאל. וְכָל בְּנֵי מְתִיבְתֵּי אִתְכְּנָשׁוּ לְגַבֵּיהּ, אָמַר רַב מְתִיבְתָּא, אֵימָּא קְרָאִיךְ בְּרָא קַדִּישָׁא.","אָמַר, עַד כְּעַן דָּחִילְנָא, דְּהָא אֲנָא מִמְּתִיבְתָּא אַחֲרִינָא הֲוִינָא, וְהָכִי אָמְרוּ לִי, כַּד מָארֵי דְּדִינָא הֲווֹ אֲחַדִין בֵּיה. אָמַר לֵיהּ, לָא תִּדְחַל בְּרָא קַדִּישָׁא, הָכָא תְּהֵא בֵּינָנָא שִׁבְעָה יוֹמִין, וְתִתְסְחֵי בְּכָל יוֹמָא מִטַּלָּא קַדִּישָׁא. וּלְבָתַר יְסַלְּקוּן לָךְ. לְגוֹ הַהוּא מְתִיבְתָּא בִּשְׁאַר יַנּוּקָא דְּהָכָא.","פָּתַח הַהוּא יְנּוּקָא וְאָמַר, וְהָיָה בַּיוֹם הַהוּא. הַהוּא, לָא יְדִיעַ מַאן הוּא. אֶלָּא בְּכָל אֲתָר בַּיוֹם הַהוּא, יוֹמָא בַּתְרָאָה הוּא, אֲמַאי אִקְרֵי יוֹם הַהוּא. אֶלָּא דָּא הוּא יוֹמָא דְּאָחִיד סוֹפָא בְּשֵׁירוּתָא. שֵׁירוּתָא אִקְרֵי הוּא, כְּמָה דְאַתְּ אָמֵר (במדבר י״ח:כ״ג) וְעָבַד הַלֵּוִי הוּא פּוּלְחָנָא דְּלֵוִי, לְדַרְגָּא דְּאִקְרֵי הוּא, טָמִיר וְגָנִיז. וְאִקְרֵי הַהוּא (ה' הוא), לְאַחֲזָאָה סוֹפָא דְּכָל דַּרְגִּין, דְּאִיהוּ שֵׁירוּתָא, וְכֹלָּא חַד. וּבְגִין דְּאִיהוּ סוֹפָא, אִתּוֹסַף בֵּיהּ ה'. (ס\"א ועבד הלוי הוא טמיר וגניז. ואקרי יום ההוא, לאחזאה סופא דכל דרגין, דאחיד שירותא וכלא חד)","זְמִינָא יְרוּשָׁלַ ם לְאַפָּקָא מַיִין, וּלְנַבְעָא נְבִיעוּ, הָכָא אִית לוֹמַר, סוֹפָא דְּכָל דַּרְגִּין, לָאו אִיהוּ יְרוּשָׁלַם, אֶלָּא וַדַּאי יְרוּשָׁלַ ם וְיוֹמָא הַהוּא כֹּלָּא חַד. מַה בֵּין הַאי לְהַאי. אֶלָּא יְרוּשָׁלַם, כָּל דַּרְגִּין קַדִּישִׁין דִּילָהּ, כַּד אִסְתַּחֲרָן, אִקְרוּן יְרוּשָׁלַ ם. וְהָכִי אִתְּחֲמָאן. וְאִית דַּרְגִּין דְּסַחֲרָן, וְאִקְרוּן עֲזָרוֹת, אִלֵּין פְּנִימָאִין, וְאִלֵּין לְבַר. וְאִית דַּרְגִּין דְּאִקְרוּן כַּד אִסְתַּחֲרָן, לְשָׁכוֹת. (ס\"א כד אסתחרן אלין פנימאין, ואלין לבר. אקרון ירושלם. ואית דרגין דסחרן, ואקרון עזרות, ואית דרגין דאקרון לשכות) וְאִית דַּרְגִּין דְּאִקְרוּן כַּד אִסְתַּחֲרָן. הֵיכָל וּדְבִיר. לְגוֹ מִכָּל אִינּוּן דַּרְגִּין, אִית חַד נְקוּדָה, (תהילים מ״ה:י״ד) כְּבוּדָּה בַת מֶלֶךְ פְּנִימָה. נְקוּדָה דָּא, אִקְרֵי יוֹם הַהוּא, וְסִימָנִיךְ (דברים ג׳:י״ג) הַהוּא יִקָּרֵא אֶרֶץ.","וְכַד יְקוּם יוֹמָא דָּא, מִגּוֹ שְׂבָכִין דַּעֲזָרָה יְקוּם נְבִיעוּ דְּמַיָּא, וְהַהוּא נְבִיעוּ מִן הַיָּם הַקַּדְמוֹנִי לֶהֱוִי. כְּגַוְונָא דְּאִמָּא, דִּבְרָהּ בֵּין דְּרוֹעָהָא, וּמִסְּגִיאוּ חֲלָבָא דְּיָנִיק, אִתְמְלֵי פּוּמֵיהּ, וְאִתְרַבֵּי בֵּיהּ, אָרִיק חֲלָבָא לְפוּמָא דְּאִמֵּיהּ. כַּךְ חֶצְיָם אֶל הַיָּם הַקַּדְמוֹנִי.","נַטְלֵיהּ רַב מְתִיבְתָּא, וּנְשָׁקֵיהּ. אָמַר חַיֶּיךָ (ס\"א חיין דעלמא דמלה דא הכי), אוּקְמוּהָ בִּמְתִיבְתָּא דִּרְקִיעָא, וְהָכִי הוּא וַדַּאי. יָם הָאַחֲרוֹן: דַּרְגִּין בַּתְרָאִין דִּילָהּ. אִי חֲסִידָא קַדִּישָׁא, כַּמָה חֶדְוָה עַל חֶדְוָה, אִתּוֹסַף בְּהַהוּא יַנּוּקָא, גּוֹ בְּנֵי מְתִיבְתֵּי. כ\"ז טַעֲמֵי דְּאוֹרַיְיתָא, אָמַר הַהוּא יַנּוּקָא. וְשִׁבְעִין כִּתְרִין אַעְטְּרוּהָ לַאֲבוּהָ בְּהַהוּא יוֹמָא. זַכָּאָה חוּלָקֵיהּ, מַאן דְּזָכֵי לְמֵילַף לִבְרֵיהּ. אָמַר רִבִּי שִׁמְעוֹן, לָא זָכָה אֲבוּהָ לְמֵילַף לֵיהּ. אָמַר, אֲבוּהָ שָׁבַק."],[[0,"הכא פריש רב וכו׳:","כאן פירש רב מתיבתא כתוב הזה בפנים, וקולו נשמע לחוץ. ומשפירש כתוב הזה נתעורר קול ילד מבחוץ, שהיה אותו ילד, שפירש תלמודו ולמד לפני עמוד העולם אחד בנו של ר׳ יהודה, מן רבית אנת, שהוא שם מקום. והיו מלאכים בעלי דין אוחזים בו לדון אותו, וקולו נתעורר מבחוץ כששמע פסוק הזה מפי רב מתיבתא, ואמר, מים שהם מלמטה בירושלים, איך יעלו למעלה ממנו למקום עליון ממנו בכמה מדרגות, דהיינו אל ים הקדמוני שהוא בינה. ועוד, מה הצורך בהם, במים האלו, למעלה, בבינה. ועוד, איך מקום, שכל המבועים והנחלים יוצאים ממנו, ואין הפסק למבועים ונחלים אלו היוצאים ממנו, שהוא הים הקדמוני שהוא בינה, יהיה נשקה ממקום יבש, שהוא ירושלים. מי ראה, בור חפור שיתן מים למבוע הנובע. וכי ירושלים יתן מים אל הים הקדמוני, שהוא מקום שכל מימי העולם יוצאים משם ונובעים משם. אהה חסיד קדוש, אמר לר״ש, לקול זה נשתככו והקשיבו כל קולות בני הישיבה שהיו שם, ומשום זה לא יכלו בעלי הדין לקרב אליו לדון אותו."],[1,"בכה ר׳ שמעון וכו׳:","בכה ר״ש. אמר לו אל תבכה מאור הקדוש, אשרי חלקך, שאפילו ילדים אומרים ממך, דהיינו בזכותך, סודות סתומים שבתורה, בוא ואומר לך, מה שעשו בני הישיבה בשביל הקול של אותו ילד. כשהקול של אותו הילד נכנם כחץ לפנים, וכולם הקשיבו לו, באותה שעה נזדעזע ראש הישיבה, וכל אלו שהיו לפניו, ואמר, מי המה שאינם עוזבים אותו בן אלקים חיים, להכנס. קמו ואחזו בו ג׳ עמודים, שה״ס הארת ג׳ קוין, שהיו עומדים לפני רב מתיבתא, ונכנס. וכל בני הישיבה נתאספו אליו. אמר רב מתיבתא, אמור המקרא שלך. בן קדוש."],[2,"אמר עד כען וכו׳:","אמר, אותו הילד, עד עתה יראתי, כי אני הייתי מישיבה אחרת. וכך אמרו לי, כשבעלי הדין היו אוחזים אותי, א״ל, אל תירא בן קדוש, כאן תהיה בינינו שבעה ימים, ותתרחץ בכל יום מטל הקדוש, ואח״כ יעלו אותך לתוך ישיבה ההוא של שאר הילדים שבכאן."],[3,"פתח ההוא ינוקא וכו׳:","פתח ילד ההוא ואמר, \u0003והיה ביום ההוא,\u0004 שואל, \u0003ההוא,\u0004 לא ידוע מי הוא. ומשיב, אלא בכל מקום, \u0003ביום ההוא,\u0004 הוא יום האחרון. למה נקרא יום ההוא. אלא משום שזה הוא יום שהסוף אחוז בראשיתו, ראשיתו שהיא בינה, נקראת \u0003הוא\u0004 כש״א, ועבד הלוי \u0003הוא,\u0004 כי עבודת הלוי, היא למדרגה הנקראת \u0003הוא,\u0004 הנסתרת וגנוזה. שמשום שהיא נסתרת, ע״כ נקראת \u0003הוא,\u0004 כי \u0003הוא,\u0004 הוא לשון נסתר. וכשנקראת \u0003ההוא\u0004 עם ה׳ הידיעה, שהיא מלכות, הוא בא להראות שהסוף של כל המדרגות, שהוא מלכות, היא ראשית המדרגות, שהיא בינה, שהכל אחד, ומשום שהמלה \u0003ההוא,\u0004 הוא סוף דהיינו מלכות, ע״כ נתוספה בה \u0003ה׳,\u0004 דהיינו שנתוספה \u0003ה׳\u0004 שהיא מלכות על המלה \u0003הוא,\u0004 שהוא בינה המלובשת תוך המלכות, ונמצא, שהמלה \u0003ההוא\u0004 היא מלכות, אלא בעת שהבינה מלובשת בה."],[4,"זמינא ירושלם לאפקא וכו׳:","עתידה ירושלים להוציא מים, ולהיות למעיין נובע. וכאן יש לומר, שהסוף של כל המדרגות, הנקרא ההוא, אין זה ירושלים, אלא ודאי שירושלים ויום ההוא הכל אחד. ששניהם הם מלכות. ומה ההפרש בין זל״ז. אלא ההפרש הוא, כי ירושלים, היינו, כשמקיפים אותה כל המדרגות הקדושות שלה היא נקראת ירושלים. וכך הן נראות. ויש מדרגות המקיפים שנקראות עזרות, אלו הם פנימיים ויש מקיפים עליה מבחוץ, ויש מדרגות יותר פנימיות, הנקראות, כשהן מקיפות, לשכות. ויש מדרגות הנקראות כשהן מקיפות, היכל ודביר. לפנים מכל אלו המדרגות, יש נקודה אחת, כבודה בת מלך פנימה, שה״ס נקודת המנעולא הנסתרת וגנוזה במלכות לפני ולפנים (כנ״ל בהקסה״ז דף מ״ז ד״ה גו) נקודה זו נקראת \u0003יום ההוא,\u0004 והסימן שלך, \u0003ההוא\u0004 יקרא ארץ, דהיינו המלכות הנקראת ארץ, אבל רק נקודה הגנוזה שלה."],[5,"וכד יקום יומא וכו׳:","ובשיקום יום הזה, שהוא נקודת המנעולא הגנוזה, דהיינו בגמר התקון, מתוך שבכין דעזרה שה״ס הארת הבינה המתלבשת במלכות, (כנ״ל אות רנ״ב עש\"ה) יקום מבוע מים, ומבוע ההוא יהיה מן ים הקדמוני, דהיינו מבינה, שממנה היא נמשך אל המלכות, וזה דומה כמו אם שבנה בין זרועותיה, ומרוב החלב שהוא יונק, מתמלא פיו, ומתרבה בו, עד שמחזיר החלב לפיה של אמו. כך חצים אל הים הקדמוני. פירוש על כן כתוב, והיה ביום ההוא יצאו מים חיים מירושלים \u0003חצים אל הים הקדמוני.\u0004 דהיינו מרוב השפע שנקודה זו לוקחת אז מים הקדמוני, השפע עובר על גדותיו ומוחזר חציו לים הקדמוני, כלומר, שהבינה תקבל גדלות גדולה מן המלכות, \u0003וחצים אל הים האחרון,\u0004 דהיינו לנקודה דמנעולא עצמה. שתקבל אז כל תקוניה, משפע ים הקדמוני."],[6,"נטליה רב מתיבתא וכו׳:","לקחו רב מתיבתא ונשקו. אמר לו, חייך, שכך העמידו בישיבה של הרקיע, וכך הוא ודאי. \u0003ים האחרון,\u0004 פירושו, מדרגות אחרונות שלה, דהיינו נקודה דמנעולא. אהה חסיד קדוש, אמרה הנשמה לר׳ שמעון, כמה שמחה על שמחה נתוסף בילד ההוא בין בני הישיבה, וכ״ז טעמים בתורה אמר אותו הילד. ושבעים כתרים העטירו לאביו באותו יום. אשרי חלקו מי שזכה ללמד לבנו. א\"ר שמעון וכי לא זכה אביו ללמוד אותו. אמר לו אביו מת."]],[[0,"","כָּאן פֵּרַשׁ רֹאשׁ הַיְשִׁיבָה פָּסוּק זֶה לְפָנִים, וְקוֹלוֹ נִשְׁמַע הַחוּצָה. מִשֶּׁהָיָה מְפָרֵשׁ פָּסוּק זֶה, (אי קדוש, אי קדוש) קוֹל תִּינוֹק הִתְעוֹרֵר מִבַּחוּץ, אוֹתוֹ תִּינוֹק שֶׁהָיָה מְפָרֵשׁ תַּלְמוּדוֹ, וְלָמַד לִפְנֵי עַמּוּד אֶחָד שֶׁל הָעוֹלָם, בְּנוֹ שֶׁל רַבִּי יְהוּדָה שֶׁגִּדַּלְתָּ. וְאָחֲזוּ בוֹ לְדִין, וְקוֹלוֹ הִתְעוֹרֵר מִבַּחוּץ בְּפָסוק זֶה, וְאָמַר, מַיִם שֶׁהֵם מִלְּמַטָּה, אֵיךְ יַעֲלוּ לְמַעְלָה מִמֶּנּוּ, לְמָקוֹם עֶלְיוֹן יוֹתֵר מִמֶּנּוּ בְּכַמָּה מַעֲלוֹת? וּמַה צָּרִיךְ לְאוֹתָם מַיִם לְמַעְלָה? וּמַה מָּקוֹם שֶׁכָּל (תפוחי) הַמַּבּוּעִים וְהַנְּחָלִים יוֹצְאִים מִמֶּנּוּ, וְאֵין הֶפְסֵק לַמַּבּוּעִים וְהַנְּחָלִים, הֻשְׁקָה מִמָּקוֹם יָבֵשׁ? מִי רָאָה חֲפִירַת הַבְּאֵר נוֹתֵן מַיִם לַמַּבּוּעַ שֶׁנּוֹבֵעַ? וְכִי יְרוּשָׁלַיִם תִּתֵּן מַיִם אֶל הַיָּם הַקַּדְמוֹנִי, מָקוֹם שֶׁכָּל מֵימֵי הָעוֹלָם יוֹצְאִים מִשָּׁם וְנוֹבְעִים מִשָּׁם? אִי חָסִיד קָדוֹשׁ, לְקוֹל זֶה שָׁכְכוּ וְשָׁמְעוּ כָּל קוֹלוֹת בְּנֵי הַיְשִׁיבָה שֶׁל שָׁם, וּמִשּׁוּם זֶה לֹא יָכְלוּ בַּעֲלֵי הַדִּין לִקְרַב אֵלָיו."],[1,"","בָּכָה רַבִּי שִׁמְעוֹן, אָמַר לוֹ, אַל תִּבְכֶּה מְנוֹרָה הַקְּדוֹשָׁה, אַשְׁרֵי חֶלְקְךְ שֶׁאֲפִלּוּ תִינוֹקוֹת מִמְּךְ אוֹמְרִים סוֹדוֹת נִסְתָּרִים שֶׁל הַתּוֹרָה. בֹּא וְאֹמַר לְךְ מַה שֶּׁעָשׂוּ בְּנֵי הַיְשִׁיבָה עַל קוֹל אוֹתוֹ תִּינוֹק. כְּשֶׁנִּכְנַס קוֹל אוֹתוֹ תִּינוֹק כְּחֵץ פְּנִימָה וְכֻלָּם הִקְשִׁיבוּ לוֹ, בְּאוֹתָהּ שָׁעָה הִזְדַּעֲזַע רֹאשׁ הַיְשִׁיבָה וְכָל אֵלּוּ שֶׁהָיוּ לְפָנָיו, וְאָמַר, מִי אֵלּוּ שֶׁלֹּא הִשְׁאִירוּ אֶת אוֹתוֹ בֶּן אֱלֹהִים חַיִּים לְהִכָּנֵס? קָמוּ וְאָחֲזוּ בוֹ שְׁלֹשָׁה עַמּוּדִים שֶׁעוֹמְדִים לִפְנֵי רֹאשׁ הַיְשִׁיבָה, וְנִכְנַס, וְכָל בְּנֵי הַיְשִׁיבָה נִכְנְסוּ אֵלָיו. אָמַר רֹאשׁ הַיְשִׁיבָה, פְּסֹק פְּסוּקְךְ בֵּן קָדוֹשׁ!"],[2,"","אָמַר, עַד כָּעֵת פָּחַדְתִּי, שֶׁהֲרֵינִי מִישִׁיבָה אַחֶרֶת, וְכָךְ אָמְרוּ לִי כְּשֶׁבַּעֲלֵי הַדִּין אָחֲזוּ בוֹ. אָמַר לוֹ, אַל תִּפְחַד בֵּן קָדוֹשׁ, כָּאן תִּהְיֶה בֵּינֵינוּ שִׁבְעָה יָמִים, וְתִתְרַחֵץ בְּכָל יוֹם מִטַּל הַקָּדוֹשׁ, וְאַחַר כָּךְ יַעֲלוּ אוֹתְךְ לְתוֹךְ אוֹתָהּ יְשִׁיבָה כִּשְׁאָר הַתִּינוֹקוֹת מִכָּאן."],[3,"","פָּתַח אוֹתוֹ תִּינוֹק וְאָמַר, וְהָיָה בַּיּוֹם הַהוּא, הַהוּא - לֹא יָדוּעַ מִיהוּ. אֶלָּא בְּכָל מָקוֹם בַּיּוֹם הַהוּא, יוֹם אַחֲרוֹן הוּא. לָמָּה נִקְרָא יוֹם הַהוּא? אֶלָּא זֶהוּ יוֹם שֶׁאוֹחֵז סוֹף בָּרֹאשׁ. רֵאשִׁית נִקְרָא הוּא, כְּמוֹ שֶׁנֶּאֱמַר (במדבר יח) וְעָבַד הַלֵּוִי הוּא. עֲבוֹדַת הַלֵּוִי לְדַרְגָּה שֶׁנִּקְרֵאת הוּא, טָמִיר וְגָנוּז. וְנִקְרָא הַהוּא (ה' הוא), לְהַרְאוֹת סוֹף כָּל הַמַּעֲלוֹת, שֶׁהִיא רֵאשִׁית, וְהַכֹּל אֶחָד. וּמִשּׁוּם שֶׁהוּא סוֹף, הִתּוֹסֵף בּוֹ ה'. (הלוי הוא טמיר וגנוז. ונקרא יום ההוא, להראות סוף של כל הדרגות, שאחוז תחלה, והכל אחד)."],[4,"","עָתִידָה יְרוּשָׁלַיִם לְהוֹצִיא מַיִם וְלִנְבֹּעַ מַבּוּעַ. כָּאן יֵשׁ לוֹמַר, סוֹף לְכָל הַדְּרָגוֹת אֵינָהּ יְרוּשָׁלַיִם, אֶלָּא וַדַּאי יְרוּשָׁלַיִם וְיוֹם הַהוּא, הַכֹּל אֶחָד. מַה בֵּין זֶה לָזֶה? אֶלָּא יְרוּשָׁלַיִם, כָּל הַדְּרָגוֹת הַקְּדוֹשׁוֹת שֶׁלָּהּ, כְּשֶׁסּוֹבְבִים נִקְרָאִים יְרוּשָׁלַיִם, וְכָךְ נִרְאִים. וְיֵשׁ דְּרָגוֹת שֶׁסּוֹבְבוֹת, וְנִקְרָאוֹת עֲזָרוֹת. אֵלֶּה פְּנִימִיּוֹת וְאֵלֶּה בַּחוּץ. וְיֵשׁ דְּרָגוֹת שֶׁנִּקְרָאוֹת כְּשֶׁסּוֹבְבוֹת לְשָׁכוֹת. (כשמסתובבות אלו הפנימיות ואלו לבחוץ, נקראו ירושלים. ויש דרגות שסובבות, ונקראות עזרות. ויש דרגות שנקראות לשכות) וְיֵשׁ דְּרָגוֹת שֶׁנִּקְרָאוֹת כְּשֶׁסּוֹבְבוֹת הֵיכָל וּדְבִיר. לִפְנִים מִכָּל אֵלּוּ הַדְּרָגוֹת יֵשׁ נְקֻדָּה אַחַת, (תהלים מה) כְּבוּדָּה בַת מֶלֶךְ פְּנִימָה. נְקֻדָּה זוֹ נִקְרֵאת יוֹם הַהוּא, וְסִימָנְךְ - (דברים ג) הַהוּא יִקָּרֵא אֶרֶץ."],[5,"","וּכְשֶׁיַּעָמֹד יוֹם זֶה מִתּוֹךְ שִׂבְכֵי הָעֲזָרָה, תָּקוּם נְבִיעַת מַיִם, וְאוֹתָהּ נְבִיעָה תִּהְיֶה מֵהַיָּם הַקַּדְמוֹנִי, כְּמוֹ אִמָּא שֶׁבְּנָהּ בֵּין זְרוֹעוֹתֶיהָ, וּמֵרֹב חָלָב שֶׁיּוֹנֵק, מִתְמַלֵּא פִיו וְנִתְגַּדֵּל בּוֹ, מֵרִיק חָלָב לְפִי אִמּוֹ. כָּךְ חֶצְיָם אֶל הַיָּם הַקַּדְמוֹנִי."],[6,"","לְקָחוֹ רֹאשׁ הַיְשִׁיבָה וּנְשָׁקוֹ. אָמַר, חַיֶּיךְ (חיי עולם שדבר זה כך), כָּךְ פֵּרְשׁוּהוּ בִּישִׁיבַת הָרָקִיעַ, וְכָךְ זֶה וַדַּאי. יָם הָאַחֲרוֹן - מַעֲלוֹת אַחֲרוֹנוֹת שֶׁלָּהּ. אִי חָסִיד קָדוֹשׁ, כַּמָּה חֶדְוָה עַל חֶדְוָה נִתּוֹסְפָה בְּאוֹתוֹ תִּינוֹק תּוֹךְ בְּנֵי הַיְשִׁיבָה. עֶשְׂרִים וְשֶׁבַע טַעֲמֵי הַתּוֹרָה, אָמַר אוֹתוֹ תִּינוֹק. וְשִׁבְעִים כְּתָרִים עִטְּרוּ לְאָבִיו בְּאוֹתוֹ יוֹם. אַשְׁרֵי חֶלְקוֹ מִי שֶׁזּוֹכֶה לְלַמֵּד אֶת בְּנוֹ. אָמַר רַבִּי שִׁמְעוֹן, לֹא זָכָה אָבִיו לְלַמֵּד. אָמַר, אָבִיו הִשְׁאִיר."]]],[["וְרָזָא סְתִימָא הֲוָה בְּהַאי יַנּוּקָא, עַל מַה דְּאִסְתַּלָּק מֵעָלְמָא, וְעַל דְּבָעוּ לְמֵידָן דִּינֵיהּ, (ס\"א באתגלייא) וְאִשְׁתְּזִיב מִנֵּיהּ, דָּא הֲוָה בְּאִתְגַּלְיָיא, דְּהֲוָה מַכְסִיף לְרַבֵּיהּ קַמֵּי כֹּלָּא, בִּשְׁאֶלְתִּין וְקוּשְׁיָין דִּילֵיהּ, וְלָא חָיִישׁ לְמֵהַךְ לְאַחֲרָא, לְאַתְקְנָא תַּלְמוּדוֹי, וְחָלִישׁ דַּעְתָּא דְּרַבֵּיהּ. וְעַל דָּא בָּעוּ לְמֵידָן לֵיהּ בְּדִינָא תַּקִּיפָא. וּבְגִין כָּךְ, אַף עַל גַּב דְּאִשְׁתְּזִיב מִמָארֵיהוֹן דְּדִינָא, לָא אִשְׁתְּזִיב הָכָא. שִׁבְעָה יוֹמִין הֲוִי דְּלָא אִשְׁתְּלִים דְּיוּקְנֵיה. (ס\"א דיניה) וְכַּד הֲוָה אֶסְתַּחִי, בִּכְּאֶבָא יַתִּירָא קָמֵי כֹּלָא כָּל אִינוּן שִׁבְעָה יוֹמִין עַד דְּאִשְׁתְּלִים דִּיּוּקְנֵיהּ. וְעַל דְּאִסְתַּלָּק מֵעָלְמָא לָא תִּבְעֵי לְמִנְדַּע. אִי רִבִּי, אִי רִבִּי, זַכָּאָה חוּלָקָךְ.","תָּא חֲזֵי, תְּחוֹת עִגּוּלָא דְּאִינּוּן שְׂבָכִין, דְּתַמָּן בְּאִינּוּן מַיִין דְּהַהוּא נְבִיעוּ דְּמַעְיָינָא, אִתְרְשִׁים נְבִיעוּ חַד, וְאִתְפָּשַּׁט וְנָפִיק לְבַר, וְעָאל גּוֹ יַמָּא רַבָּא. (דתמן) וְרָשִׁים בֵּיהּ אָרְחָא בְּלִבָּא דְּיַמָּא, וּמִינֵּיהּ שָׁתֵי לִוְיָתָן, וְרַוִּי, וְחַדֵּי, וְאִתְרַבֵּי בְּרִבּוּיָיא. וְכַד נָפִיק נְבִיעוּ אַחֲרָא, הַהוּא נְבִיעוּ אִתְפְּשָׁט וְאָזִיל בִּטְמִירוּ, תְּחוֹת תְּהוֹמָא, לְגוֹ יַמָּא בַּתְרָאָה. וְכֹל אִינּוּן מַיִם זֵדוֹנִים, וּמַיִין תַּקִּיפִין, מָאִיךְ לוֹן, וְכָפִיף לוֹן, דְּלָא יִפְּקוּן לְחַבְּלָא בְּנֵי עָלְמָא. וְסִימָן (ישעיהו מ״ג:ט״ז) הַנּוֹתֵן בַּיָּם דָּרֶךְ וּבְמַּיִם עַזִּים נְתִיבָה.","וּבְאֶמְצָעִיתָא דְּהַהִיא עֲזָרָה, אִית תְּרֵין כְּרוּבִים, עוֹבָדָא דְּאוּמָנָא דְּמַלְכָּא קַדִּישָׁא. וְלָא יַכְלִין לְקַיְּימָא בְּהוּ, עִלָּאִין וְתַתָּאִין. וּתְחוֹתַיְיהוּ זְמִנִין כָּל יִשְׂרָאֵל לְקַיְּימָא, דְּלָא יִפְּקוּן מִתְּחוֹת גַּדְפַּיְיהוּ לְבַר, זַכָּאִין לִיהֱוָון, כָּל דְּעָאלִין תְּחוֹת גַּדְפַּיְיהוּ. תְּלֵיסַר אַלְפֵי מִגְדָּלִין דְּשִׁמְשָׁא, דְּנָהִיר מִנִיצוֹצָא דְּמַרְגְּלָא בְּצִעְצוּעָא (ס\"א בניצוצא), כְּדְקָא יָאוּת. רַב מְתִיבְתָּא בְּגִין כָּךְ זָכָה לְהַהוּא יְקָר.","מַאן יָכִיל לְמֵימַר, מֵאִינּוּן מִלִּין דְּקָא מִתְחַדְּשָׁן בְּכָל יוֹמָא, מִקַּמֵּי רַב מְתִיבְתָּא, אִי רִבִּי, בְּכָל זִמְנָא דְּרוּחִין דְּכוּרִין סַלְּקִין לְעֵילָּא. נָשִׁין בְּהַהוּא זִמְנָא נָפְקֵי כֻּלְּהוּ, וּמִתְכַּנְּשֵׁי לְגוֹ הֵיכָלָא דְּבַתְיָה תַּמָּן, וְחַדָּאִין תַּמָּן, בְּכַמָּה מִלִּין עַתִּיקִין. וּמִתַּמָּן נָפְקִין, וְעָאלִין כֻּלְּהוּ. וְהִיא עִמְּהוֹן, לְגוֹ הֵיכָלָא דְּסֶרַח. וְחַדָּאן בְּכַמָּה מִלִּין חַדְתִּין וְעַתִּיקִין, וּמִתַּמָּן נָפְקִין וְהִיא עִמְּהוֹן, וְעָאלִין לְגוֹ הֵיכָלָא דְּיוֹכֶבֶד. וְכֵן בְּכָל אִינּוּן הֵיכָלִין.","הַשְׁתָּא רִבִּי אֵימָא לָךְ רָזָא חֲדָא. תָּא חֲזֵי, בְּכָל שְׁמִטָּה וּשְׁמִטָּה, כָּרוֹזָא נָפִיק, אִתְכְּנִישׁוּ גּוּבְרִין וְנָשִׁין, וְכָל אִינּוּן בְּנֵי מְהֵימְנוּתָא, וּסְלִיקוּ. כְּדֵין כֻּלְּהוּ מִתְפַּשְּׁטִין דְּכוּרִין וְנָשִׁין, וְסַלְּקִין. וְכֹל אִינּוּן יַנּוּקֵי מֵחָלָב, עָאלִין לְגוֹ מְתִיבְתָּא (ס\"א אתכנישו בני מהימנותא גוברין ונשין וכל אינון ינוקי מחלב וסליקו. כדין כלהו מתפשטין דכורין ונשין, וסלקין. וכלהו עאלין לגו מתיבתא) דִּרְקִיעָא, וְחַדָּאן חֶדְוָה, וְעִלּוּיָא דִּלְהוֹן, וְתַמָּן חֵדוּ עַל חֵדוּ. וְהַהוּא נַעַר דְּמַפְתְּחָן דְּמָארֵיהּ בִּידֵיהּ, קָם וְאָמַר לוֹן כַּמָה מִלִּין חַדְתִּין וְעַתִּיקִין, וְכֻלְּהוּ חָמָאן חֶדְוָה, דְּלֵית חֶדְוָה כְּהַהִיא חֶדְוָה.","לְבָתַר עָאלִין כֻּלְּהוּ לְגּוֹ כַּמָה פְּרוֹכְתִּין, וְכַמָּה הֵיכָלִין גְּנִיזִין תַּמָּן. דְּאִינּוּן נַהֲרִין בְּנֹעַם יְיָ, בְּגוֹ הֵיכָלָא דְּאַהֲבָה דְקוּדְשָׁא בְּרִיךְ הוּא. וְדָא הוּא דִּכְתִּיב, (תהילים כ״ז:ד׳) לַחֲזוֹת בְּנוֹעַם ה' וּלְבַקֵּר בְּהֵיכָלוֹ. (קכ\"ז ע\"ב, שמות קי\"ג ע\"ב) לְבָתַר פַּרְחִין יַנּוּקִין לְעֵילָּא, וְאִינּוּן פַּרְחִין לְתַתָּא, וּמְהַדְּרִין לְדוּכְתַּיְיהוּ, וּמִתְלַבְּשָׁן כִּדְבְּקַדְמֵיתָא. זַכָּאָה עַמָּא דְּכָל טוּבָא דְּהַהוּא עָלְמָא מְחַכָּאן.","אָמַר רַבִּי שִׁמְעוֹן, כַּמָה מְתִיקִין מִלִּין דְּשָׁמַעְנָא. זַכָּאָה חוּלָקָא דִּידִי, דְּזָכֵינָא לְכָל הַאי לְמִשְׁמַע, זַכָּאָה יוֹמָא דְּנָפִיקְנָא הָכָא. אַמְרֵי לֵיהּ רִבִּי, תְּלַת יוֹמִין אִית לָן רְשׁוּ לְמֵיתֵי גַּבָּךְ, וּלְבָתַר יוֹמָא חַד (ס\"א ניזיל ולא אית לן רשו למיתי, בההוא יומא אתוסף) ם חֶדְוָה דִּילָךְ. ם","אִיהוּ מָשִׁיךְ מְשִׁיכוּ מִסִּטְרָא דִּילֵיהּ, וְאִתְטָמַּר וְאִתְחָפָּא תְּחוֹת אֲתָר דְּאִקְרֵי (מלכים א י״ד:כ״ח) תָּא הָרָצִים, עַד פַּלְגּוּ לֵילְיָא. מִבָּתַר פַּלְגּוּ לֵילְיָא, שַׁלְהוֹבָא דְּעַמּוּדָא דְּיִצְחָק נָפִיק, וּבָטַשׁ בְּהַאי תַּרְנְגוֹלָא דְּאִקְרֵי גָּבֶר, כְּגַוְונָא דְּגֶבֶר אַחֲרָא עִלָּאָה עָלֵיהּ. כֵּיוָן דְּבָטַשׁ בֵּיהּ הַאי גָּבַר, קָרֵי וְיָהִיב שִׁית קָלִין, וְכֻלְּהוּ בְּסָכְלְתָנוּ.","בְּשַׁעֲתָא דְּאִיהוּ קָרֵי, כָּל תַּרְנְגוֹלִין דְּהַאי עָלְמָא קָרָאן, וְנָפִיק מִנֵּיהּ שַׁלְהוֹבָא אַחֲרָא, וּמָטֵי לוֹן תְּחוֹת גַּדְפַיְיהוּ, וְקָרָאן. אִיהוּ מַה קָרֵי. בְּשַׁעֲתָא קַדְמָאָה קָרֵי וְאָמַר, (תהילים כ״ט:ד׳) קוֹל יְיָ בַּכֹּחַ קוֹל יְיָ בֶּהָדָר. וּבְשַׁעֲתָא תִּנְיָינָא קָרֵי וְאָמַר, (מיכה ו׳:ט׳) קוֹל יְיָ לָעִיר יִקְרָא (תהילים כ״ט:ד׳) קוֹל יְיָ שׁוֹבֵר אֲרָזִים. בְּשַׁעֲתָא תְּלִיתָאָה קָרֵי וְאָמַר, קוֹל יְיָ חוֹצֵב לַהֲבוֹת אֵשׁ. בְּשַׁעֲתָא רְבִיעָאָה קָרֵי וְאָמַר, (תהילים כ״ט:ח׳) קוֹל יְיָ יָחִיל מִדְבָּר וְגוֹ'. בְּשַׁעֲתָא חֲמִישָּׁאָה קָרֵי וְאָמַר, קוֹל יְיָ עַל הַמָּיִם וְגוֹ'. בְּשַׁעֲתָא שְׁתִיתָאָה קָרֵי וְאָמַר, קוֹל יְיָ יְחוֹלֵל אַיָּלוֹת וְגוֹ'. לְבָתַר קָרֵי וְאָמַר, (ישעיהו מ׳:ו׳) קוֹל אוֹמֵר קְרָא וְאָמַר מָה אֶקְרָא וְגו'. וְדָא אִיהוּ תַּרְנְגוֹלָא דְּקָרֵי, וְלָא שָׁכִיךְ וּלְבָתַר קָרֵי כְּמִלְּקַדְּמִין."],[[0,"ורזא סתימא הוה וכו׳:","וסוד סתום היה בילד ההוא, על מה שנסתלק מן העולם, ועל שרצו לדון דינו, וניצול ממנו. זה היה משום שבגלוי היה מבייש את רבו לפני כל בשאלות וקושיות שלו, שלא היה יכול לתרץ לו. ולא חשש ללכת לרב אחר לתקן תלמידו, והחליש דעתו של רבו. וע״כ רצו לדון אותו בדין קשה. ומשום זה אע״פ שניצול מבעלי הדין, לא ניצל כאן, ז׳ ימים היו שלא נשלמה צורתו, וכשהיה רוחץ בכאב גדול לפני הכל כל אלו ז׳ ימים, עד שנשלמה צורתו. ועל מה שנסתלק מן העולם, אל תבקש לדעת. אהה רבי, אהה רבי, אשרי חלקך."],[1,"ת\"ח תחות עגולא וכו׳:","חוזר לפרש הכתוב חצים אל הים הקדמוני וגו', בדרך אחר, ובמלים אחרות, בוא וראה, תחת העגול של שבכות האלו (כנ״ל אות רנ״ב) אשר שם, בעזרה, שה״ס הארת הבינה שבמלכות המקולעת עמה, כנ״ל, באלו המים של מעיין הנובע אשר שם, נרשם נביע אחד שמתפשט ויוצא לחוץ, ונכנס לים הגדול, שה״ס מלכות מבחינת החכמה, ורושם בו דרך אל לב הים, ששם שליטת המלכות הממותקת בבינה, שה״ס נקודת המפתחא, וממנו שותה הלויתן, שפירושו תמצא לעיל (בא דף י״א ד״ה פנימיות) ורוה ושמח ומתרבה וגדל ברבוי. שז״ס חצים אל הים הקדמוני, דהיינו לב הים. וכשיוצא נביע אחר, אותו הנביע הולך ומתפשט בסתר תחת התהום, דהיינו תחת מלכות דמפתחא שנקרא תהום, לתוך ים האחרון, שהוא מלכות דמנעולא הגנוזה. וכל אלו מים הזדונים ומים קשים הוא משפיל אותם וכופף אותם, שלא יצאו לחבל בני העולם. והסימן הוא, \u0003הנותן בים דרך,\u0004 שפירושו בלב הים. \u0003ובמים עזים נתיבה,\u0004 שפירושו בים האחרון."],[2,"ובאמצעיתא דההיא עזרה וכו':","ובאמצע העזרה, יש ב׳ כרובים מעשה אומן של מלך הקדוש, שה\"ס אפי זוטרי (כנ״ל אות ק״מ) ועליונים ותחתונים אינם יכולים לעמוד עליהם, כי הג״ר שלהם מכוסים בכנפים, ותחתיהם, דהיינו בבחינת ו״ק דג״ר שבהם, עתידים לעמוד כל ישראל, דהיינו לקבל הארתם, ובלבד שלא יצאו מתחת כנפיהם לחוץ, דהיינו שלא יציצו, בג״ר המכוסים בכנפים. מאושרים יהיו, כל אלו הנכנסים תחת כנפיהם של הכרובים. כי י״ג אלף מגדלים של השמש, שה״ס ז״א, דהיינו י\"ב צירופי הויה, והכולל אותם. שה״ס חו״ב תו״מ שבכל אחד ג׳ קוין, מאירים בצעצועים כראוי, דהיינו בהכרובים, כי צעצועים פירושו אנפי זוטרי, כמ״ש \u0003מעשה צעצועים\u0004 (ד״ה ב׳ ג׳ י׳) רב מתיבתא זכה משום זה, שנכנס תחת כנפי הכרובים, לכל יקר ההוא."],[3,"מאן יכיל למימר וכו׳:","מי יכול לומר מאלו הדברים המתחדשים בכל יום לפני ראש הישיבה. אהה רבי, בכל זמן שרוחות זכרים עולים למעלה, בזמן ההוא יוצאות כל הנשים ומתאספות שם אל היכל בתיה, בת פרעה (כנ״ל אות קצ״ו) ושמחים שם בכמה דברים עתיקין. ומשם יוצאות כולן ונכנסות, ובתיה עמהן, אל היכל של סרח בת אשר (כנ״ל אות קצ\"ח) ושמחות בכמה דברים חדשים וישנים. ומשם יוצאות וסרח עמהן, ונכנסות אל היכלה של יוכבד (כנ״ל אות קצ״ט). וכן בכל אלו היכלות."],[4,"השתא רבי אימא וכו׳:","עתה רבי, אומר לך סוד אחד. בוא וראה, בכל שמטה ושמטה יוצא כרוז בגן עדן, התאספו גברים ונשים, וכל אלו בני האמונה, ועלו. אז כולם מתפשטים, זכרים ונשים, ועולים, וכל אלו גמולי מחלב עולים, אל הישיבה של הרקיע שהוא הישיבה של מטטרון, ושמחים בשמחה על התעלות שלהם, ושם שמחה על שמחה. ואותו הנער, שמפתחות אדוניו בידו, דהיינו מטטרון, קם ואמר להם כמה דברים חדשים וישנים. וכולם רואים שמחה, שאין שמחה כאותה השמחה."],[5,"לבתר עאלין כלהו וכו׳:","לאח״כ עולים כולם לפנים. כמה פרוכיות וכמה היכלות גנוזים שמה, שהם מאירים בנעם ה׳, בתוך היכל האהבה של הקב\"ה. וז״ש, לחזות בנועם ה׳ ולבקר בהיכלו. לאח״כ פורחים הילדים גמולי מחלב למעלה, דהיינו למתיבתא עלאה, והם, הגברים והנשים, פורחים למטה ששם מקומם (כמו שכ' להלן בלק אות רל״ג) וחוזרים למקומם, בגן עדן התחתון. ומתלבשים שם בלבושם כבתחילה. אשרי העם, שכל טוב של עולם ההוא, מחכה להם."],[6,"אר״ש כמה מתיקין וכו׳:","א״ר שמעון, כמה מתוקים אלו הדברים ששמעתי. אשרי חלקי שזכיתי לשמוע כל זה. אשרי היום שיצאתי לכאן. אמרו לו, רבי ג׳ ימים יש לנו רשות לבא אליך. ולאחר יום אחד. השמחה שלך (חסר ההמשך)."],[7,"אייהן משיך משיכו וכו׳:","(חסר ההתחלה) הוא משך המשכה מן הצד שלו ונסתתר ומתכסה תחת מקום שנקרא תא הרצים, עד חצות לילה. מאחר חצות לילה יוצא שלהבת מן העמוד של יצחק, שהוא קו השמאל, ומכה בתרנגול הזה שנקרא גבר שהוא גבריאל, כעין גבר אחר עליון שעליו, שהוא גבורה דז״א, עמודא דיצחק, כיון שהשלהבת דקו שמאל מכה בגבר ההוא, שהוא גבריאל, קורא ונותן ששה קולות, וכלהו בתבונה. (וביאורו, לעיל ויקהל דף ח׳ ד״ה פירוש)."],[8,"בשעתא דאיהו קרי וכו׳:","בשעה שהוא קורא, דהיינו גבריאל, קוראים כל התרנגולים של עולם הזה. ויוצא ממנו, מן גבריאל, שלהבת אחרת ומגיע אליהם תחת כנפיהם, והם קוראים. הוא, גבריאל, מה קורא. היינו. בשעה ראשונה, קורא ואומר, קול ה׳ בכח קול ה׳ בהדר, ובשעה שניה קורא ואומר קול ה׳ שובר ארזים. בשעה שלישית קורא ואומר, קול ה׳ חוצב להבות אש. בשעה רביעית קורא ואומר, קול ה׳ יחיל מדבר וגו'. בשעה חמישית קורא ואומר, קול ה׳ על המים. בשעה ששית קורא ואומר, קול ה׳ יחולל אילות וגו'. אח״כ קורא ואומר, קול אומר קרא ואמר מה אקרא וגו'. וזהו, גבריאל, הוא תרנגול הקורא ואינו נשתק, ולאח״כ חוזר וקורא כבתחילה."]],[[0,"","וְסוֹד נִסְתָּר הָיָה בְּתִינוֹק זֶה עַל מַה שֶּׁהִסְתַּלֵּק מֵהָעוֹלָם וְעַל שֶׁרָצוּ לָדוּן דִּינוֹ (בגלוי) וְנִצַּל מִמֶּנּוּ. זֶה הָיָה בְגִלּוּי, שֶׁהָיָה מְבַיֵּשׁ לְרַבּוֹ לִפְנֵי הַכֹּל בִּשְׁאֵלוֹת וְקֻשְׁיוֹת שֶׁלּוֹ, וְלֹא חָשַׁשׁ לָלֶכֶת לְאַחֵר לְהַתְקִין תַּלְמוּדוֹ, וְהֶחֱלִישׁ דַּעַת רַבּוֹ, וְלָכֵן רָצוּ לָדוּן אוֹתוֹ בְּדִין קָשֶׁה. וּמִשּׁוּם כָּךְ, אַף עַל גַּב שֶׁנִּצַּל מִבַּעֲלֵי הַדִּין, לֹא נִצַּל כָּאן. שִׁבְעָה יָמִים הָיוּ שֶׁלֹּא הִשְׁתַּלֵּם דְּיוֹקְנוֹ (דינו). וּכְשֶׁהָיָה מִתְרַחֵץ, בִּכְאֵב יָתֵר לִפְנֵי הַכֹּל כָּל אוֹתָם שִׁבְעָה יָמִים עַד שֶׁהִשְׁתַּלֵּם דְּיוֹקְנוֹ. וְעַל שֶׁהִסְתַּלֵּק מֵהָעוֹלָם לֹא תִרְצֶה לָדַעַת. אִי רַבִּי, אִי רַבִּי, אַשְׁרֵי חֶלְקְךְ!"],[1,"","בֹּא וּרְאֵה, תַּחַת הָעִגּוּל שֶׁל אוֹתָם שְׂבָכִים שֶׁשָּׁם, בְּאוֹתָם מַיִם שֶׁל אוֹתוֹ מַבּוּעַ הַמַּעְיָן, נִרְשָׁם מַבּוּעַ אֶחָד, וּמִתְפַּשֵּׁט וְיוֹצֵא הַחוּצָה, וְנִכְנָס לְתוֹךְ הַיָּם הַגָּדוֹל, (ששם) וְרוֹשֵׁם בּוֹ דֶּרֶךְ בְּלֵב הַיָּם, וּמִמֶּנּוּ שׁוֹתֶה לִוְיָתָן וְרָוֶה וְשָׂמֵחַ, וּמִתְרַבֶּה בְרִבּוּי. וּכְשֶׁיּוֹצֵא מַבּוּעַ אַחֵר, אוֹתוֹ מַבּוּעַ מִתְפַּשֵּׁט וְהוֹלֵךְ בַּסֵּתֶר תַּחַת הַתְּהוֹם לְתוֹךְ הַיָּם הָאַחֲרוֹן. וְכָל אוֹתָם מַיִם זֵידוֹנִים וּמַיִם תַּקִּיפִים מַנְמִיךְ אוֹתָם וּמְכוֹפֵף אוֹתָם שֶׁלֹּא יֵצְאוּ לְחַבֵּל בִּבְנֵי הָעוֹלָם. וְסִימָן - (ישעיה מג) הַנּוֹתֵן בַּיָּם דָּרֶךְ וּבְמַיִם עַזִּים נְתִיבָה."],[2,"","וּבְאֶמְצַע אוֹתָהּ עֲזָרָה יֵשׁ שְׁנֵי כְרוּבִים, מַעֲשֵׂה אָמָּנוּת שֶׁל הַמֶּלֶךְ הַקָּדוֹשׁ, וְלֹא יְכוֹלִים לַעֲמֹד בָּהֶם עֶלְיוֹנִים וְתַחְתּוֹנִים. וְתַחְתֵּיהֶם עֲתִידִים כָּל יִשְׂרָאֵל לַעֲמֹד, שֶׁלֹּא יֵצְאוּ מִתַּחַת כַּנְפֵיהֶם הַחוּצָה, זַכָּאִים יִהְיוּ כָּל הַנִּכְנָס תַּחַת כַּנְפֵיהֶם. שְׁלֹשָׁה עָשָׂר אֶלֶף מִגְדָּלִים שֶׁל שֶׁמֶשׁ שֶׁמֵּאִיר מִנִּיצוֹץ שֶׁל מַרְגָּלִית בְּצַעֲצוּעַ (בניצוץ) כָּרָאוּי. רֹאשׁ הַיְשִׁיבָה בִּגְלַל זֶה זָכָה לְאוֹתוֹ כָּבוֹד."],[3,"","מִי יָכוֹל לוֹמַר מֵאוֹתָם דְּבָרִים שֶׁמִּתְחַדְּשִׁים בְּכָל יוֹם מִלִּפְנֵי רֹאשׁ הַיְשִׁיבָה. אִי רַבִּי, בְּכָל זְמַן שֶׁרוּחוֹת זְכָרִים עוֹלוֹת לְמַעְלָה, נָשִׁים בְּאוֹתוֹ זְמַן יוֹצְאוֹת כֻּלָּן, וּמִתְכַּנְּסוֹת לְתוֹךְ הַהֵיכָל שֶׁשָּׁם בַּתְיָה, וּשְׂמֵחוֹת שָׁם בְּכַמָּה דְבָרִים עַתִּיקִים. וּמִשָּׁם יוֹצְאוֹת, וְנִכְנָסוֹת כֻּלָּן, וְהִיא עִמָּהֶן, לְתוֹךְ הֵיכַל סֶרַח, וּשְׂמֵחוֹת בְּכַמָּה דְבָרִים חֲדָשִׁים וְעַתִּיקִים, וּמִשָּׁם יוֹצְאוֹת וְהִיא עִמָּהֶן, וְנִכְנָסוֹת לְתוֹךְ הֵיכַל יוֹכֵבֶד. וְכֵן בְּכָל אוֹתָם הֵיכָלוֹת."],[4,"","כָּעֵֹת, רַבִּי, אֹמַר לְךְ סוֹד אֶחָד. בֹּא וּרְאֵה, בְּכָל שְׁמִטָּה וּשְׁמִטָּה הַכָּרוֹז יוֹצֵא: הִתְכַּנְּסוּ גְבָרִים וְנָשִׁים וְכָל אוֹתָם בְּנֵי הָאֱמוּנָה וַעֲלוּ. אָז כֻּלָּם מִתְפַּשְּׁטִים, זְכָרִים וְנָשִׁים, וְעוֹלִים. וְכָל אוֹתָם תִּינוֹקוֹת מֵחָלָב נִכְנָסִים לְתוֹךְ יְשִׁיבַת (התכנסו בני האמונה גברים ונשים, וכל אותם יונקי חלב, ועלו. אז כלם מתפשטים, גברים ונשים, ועולים. וכלם נכנסים לתוך ישיבת) הָרָקִיעַ, וּשְׂמֵחִים בְּחֶדְוָה וְעִלּוּי שֶׁלָּהֶם, וְשָׁם שִׂמְחָה עַל שִׂמְחָה. וְאוֹתוֹ נַעַר שֶׁמַּפְתְּחוֹת רִבּוֹנוֹ בְיָדוֹ עוֹמֵד, וְאוֹמֵר לָהֶם כַּמָּה דְבָרִים חֲדָשִׁים וְעַתִּיקִים, וְכֻלָּם רוֹאִים שִׂמְחָה שֶׁאֵין שִׂמְחָה כְּאוֹתָהּ שִׂמְחָה."],[5,"","אַחַר כָּךְ נִכְנָסִים כֻּלָּם לְתוֹךְ כַּמָּה פָרוֹכוֹת, וְכַמָּה הֵיכָלוֹת גְּנוּזִים שָׁם, שֶׁהֵם מְאִירִים בְּנֹעַם ה' בְּתוֹךְ הֵיכַל אַהֲבַת הַקָּדוֹשׁ בָּרוּךְ הוּא, וְזֶהוּ שֶׁכָּתוּב (תהלים כז) לַחֲזוֹת בְּנֹעַם ה' וּלְבַקֵּר בְּהֵיכָלוֹ. אַחַר כָּךְ פּוֹרְחִים הַתִּינוֹקוֹת לְמַעְלָה, וְהֵם פּוֹרְחִים לְמַטָּה, וְחוֹזְרִים לִמְקוֹמוֹתֵיהֶם וּמִתְלַבְּשִׁים כְּבַתְּחִלָּה. אַשְׁרֵי הָעָם שֶׁלְּכָל טוּב אוֹתוֹ עוֹלָם מְצַפִּים."],[6,"","אָמַר רַבִּי שִׁמְעוֹן, כַּמָּה מְתוּקִים הַדְּבָרִים שֶׁשָּׁמַעְנוּ. אַשְׁרֵי חֶלְקִי שֶׁזָּכִיתִי לְכָל לִשְׁמֹעַ אֶת כָּל זֶה. אַשְׁרֵי הַיּוֹם שֶׁיָּצָאתִי לְכָאן. אָמְרוּ לוֹ, רַבִּי, שְׁלֹשָׁה יָמִים יֵשׁ לָנוּ רְשׁוּת לָבא אֵלֶיךְ, וְאַחַר כָּךְ יוֹם אֶחָד (נלך, ואין לנו רשות לבא. באותו יום נוספת) שִׂמְחָה שֶׁלְּךְ."],[7,"","הוּא מוֹשֵׁךְ מְשִׁיכוּת מִצִּדּוֹ, וְנִסְתָּר וּמִתְכַּסֶּה תַחַת מָקוֹם שֶׁנִּקְרָא תָּא הָרָצִים עַד חֲצוֹת הַלַּיְלָה. מֵאַחַר חֲצוֹת הַלַּיְלָה יוֹצֵאת שַׁלְהֶבֶת עַמּוּד יִצְחָק, וּמַכָּה בַּתַּרְנְגוֹל הַזֶּה שֶׁנִּקְרָא גֶבֶר, כְּמוֹ גֶבֶר אַחֵר עֶלְיוֹן מִמֶּנּוּ. כֵּיוָן שֶׁמַּכֶּה בּוֹ גֶּבֶר זֶה, קוֹרֵא וְנוֹתֵן שִׁשָּׁה קוֹלוֹת, וְכֻלָּם בְּהַשְׂכֵּל."],[8,"","בְּשָׁעָה שֶׁהוּא קוֹרֵא, כָּל תַּרְנְגוֹלֵי הָעוֹלָם הַזֶּה קוֹרְאִים, וְיוֹצֵאת מִמֶּנּוּ שַׁלְהֶבֶת אַחֶרֶת וּמַגִּיעָה תַחַת כַּנְפֵיהֶם, וְקוֹרְאִים. מַה הוּא קוֹרֵא? בְּשָׁעָה רִאשׁוֹנָה קוֹרֵא וְאוֹמֵר: (תהלים כט) קוֹל ה' בַּכֹּחַ קוֹל ה' בֶּהָדָר. וּבְשָׁעָה שְׁנִיָּה קוֹרֵא וְאוֹמֵר: (מיכהו) קוֹל ה' לָעִיר יִקְרָא, (תהלים כט) קוֹל ה' שֹׁבֵר אֲרָזִים. בְּשָׁעָה שְׁלִישִׁית קוֹרֵא וְאוֹמֵר: קוֹל ה' חֹצֵב לַהֲבוֹת אֵשׁ. בְּשָׁעָה רְבִיעִית קוֹרֵא וְאוֹמֵר: קוֹל ה' יָחִיל מִדְבָּר וְגוֹ'. בְּשָׁעָה חֲמִישִׁית קוֹרֵא וְאוֹמֵר: קוֹל ה' עַל הַמָּיִם וְגוֹ'. בְּשָׁעָה שִׁשִּׁית קוֹרֵא וְאוֹמֵר: קוֹל ה' יְחוֹלֵל אַיָּלוֹת וְגוֹ'. וְאַחַר כָּךְ קוֹרֵא וְאוֹמֵר: (ישעיה מ) קוֹל אֹמֵר קְרָא וְאָמַר מָה אֶקְרָא וְגוֹ'. וְזֶהוּ הַתַּרְנְגוֹל שֶׁקּוֹרֵא וְלֹא שׁוֹכֵךְ, וְאַחַר כָּךְ קוֹרֵא כְּמוֹ מִקֹּדֶם."]]],[["וּמַאי קָרֵי. כָּל עוֹבָדִין דִּבְנֵי עָלְמָא, בְּגִין דְּאִיהוּ מָארֵיהּ דְּאַחְמְתָא (ס\"א דחכמתא) וְקֶסֶת הַסּוֹפֵר בְּחַרְצוֹי. וְכָל עוֹבָדִין דִּבְנֵי עָלְמָא כַּתִיב בְּכָל יוֹמָא. וּבְלֵילְיָא, בָּתַר דְּקָרֵי כָּל קְרִיאָן אִלֵּין, קָרֵי כָּל מַה דְּכָתַב בְּיוֹמָא.","וְאִלְמָלֵא רַגְלוֹי אֶצְבְּעָאן דִּילֵיהּ, דְּאִינּוּן תְּרֵין דַּרְגִּין, חַד הַהוּא דְּקַיְּימָא בְּאֶמְצָעִיתָא. דְּאִיהוּ רַב. וְהַהוּא דְּקַיְּימָא מֵאֲחוֹרָא, דְּאִיהוּ זְעֵיר, דְּקָא מְעַכְּבִין לֵיהּ, יְהֵא מוֹקִיד עָלְמָא בְּשַׁלְהוֹבוֹי. וּמָה עַבְדֵּי. כֵּיוָן דְּסָלִיק צַפְרָא, וְחוּטָא דִּנְהִירוּ נָפִיק מִסְטַר דָּרוֹם, כְּדֵין מִתְחַבְּרִין כֻּלְּהוּ, וְאִתְעָבְדִין תְּרֵין רַגְלִין תְּרֵין טְלָפַיִן כְּעֶגְלָא, לְקַיְּימָא דִּכְתִּיב (יחזקאל א׳:ז׳) וְכַף רַגְלֵיהֶם כְּכַף רֶגֶל עֵגֶל, וְהָא יַדְעַת רָזָא דָּא. שְׁאֵלָת עַנְפָּא דְּגוֹרֶן. לְגוֹ בַּעֲזָרָה דָּא, אִית תְּלַת מְאָה וְשִׁתִּין וַחֲמִשָּׁה הֵיכָלִין, כְּחוּשְׁבָן יוֹמֵי שַׁתָּא. וּבְכָל פִּתְחָא וּפִתְחָא כְּתִיב, (תהילים קכ״ב:ז׳) יְהִי שָׁלוֹם בְּחֵילֵךְ שַׁלְוָה בְּאַרְמְנוֹתָיִךְ. לָא יְדִיעַ מַאי הוּא בְּהָנֵי הֵיכָלִין, אֶלָּא כֻּלְּהוּ, אִתְּחֲמָן עוֹבָד צִיּוּר. שֶׁבַע סִדְרִין דְּמַרְגְּלָאן אִתְּחֲמָן אִלֵּין בְּאִלֵּין, בְּכָל חַד וְחַד.","אִי חֲסִידָא קַדִּישָׁא, כַּמָה מְשַׁבַּח רַב מְתִיבְתָּא הֵיכָלָא חֲדָא, דְּאִיהוּ בְּרֵישׁ סְטָר מִזְרָח דַּעֲזָרָה דָּא, בְּגִין דְּאַרְבַּע אִינּוּן בְּד' סִטְרִין דְּעָלְמָא, אֲבָל הֵיכָלָא דִּסְטָר מִזְרָח, אַסְגֵּי נְהוֹרִין דִּילֵיהּ יַתִּיר מְכֻּלְּהוּ.","יוֹמָא חַד, בְּיַמָּא רַבָּא, לִוְיָתָן נָפִיק, וְכָל יַמָּא אִזְדַּעְזָע, וְכָל נוּנֵי אָזְלִין לְכָאן וּלְכָאן, כַּד מָטֵי לִוְיָתָן בְּפִתְחָא דְּפִתְחָא דִּתְהוֹמָא, שָׁארֵי לְמֶחְדֵּי, וְאִשְׁתְּכַךְ תַּמָּן ם תְּהוֹמֵי ם, אֶלָּא הַהוּא ם כְּחֵיזוּ דְּמַעְיָין, וְאִתְחַפְּיָין נְהוֹרִין, וְלָא אִתְחָזוּן כָּל אִינּוּן נְהוֹרִין, בַּר נְהוֹרָא דְּהֵיכָלָא דְּבִסְטַר מִזְרָח דָּא.","הַהוּא מַרְגְּלָא דְּקָא אַפִּיק לִוְיָתָן, מִגּוֹ הַהוּא תְּהוֹמָא דְּאִקְרֵי סַגְדוֹ\"ן, מִמָּה אִתְעָבִיד. אֶלָּא יוֹמָא דָּא דְּקָא אַפִּיק לִוְיָתָן, דְּאִזְדַּעְזָע יַמָּא, יוֹמָא דְּאִתְחָרַב בֵּי מַקְדְּשָׁא, ט' בְּאָב אִיהוּ. וְהַהוּא מַרְגְּלָא, דְּכַד דָּכִיר קוּדְשָׁא בְּרִיךְ הוּא לִבְנוֹי, וְאוֹשִׁיד (שמות ט' ע\"א) תְּרֵין דִּמְעִין לְגוֹ יַמָּא רַבָּא, חַד נָפִיל לְגוֹ תְּהוֹמָא דָּא דְּאִקְרֵי סַגְדּוֹ\"ן, וְחַד נָפִיל לְגוֹ תְּהוֹמָא אַחֲרָא דְּאִקְרֵי גִּילְבָ\"א.","בְּגִין דְּחָמֵשׁ תְּהוֹמֵי אַחֲרָנִין אִינּוּן בְּיַמָּא רַבָּא. אֲבָל לָא חֲשִׁיבִין כְּהָנֵי אַחֲרָנִין, וְכֵיוָן דְּנַפְלֵי אִינּוּן דִּמְעִין, קָפָאָן גּוֹ תְּהוֹמֵי חַד. וְחַד אַטְבַּע גּוֹ תְּהוֹמָא, דְּאִקְרֵי גִּילְבָ\"א. ם","דְּתַתָּא גּוֹ שְׁמָרִים דְּחַמְרָא, דּוּרְדְיָין בִּישִׁין, נָפִיק חַד עִרְעוּרָא מְקַטְרְגָא, מַזִיקָא קַדְמָאָה, וְאִיהוּ בְּרוּחָא דִּיּוּקְנָא דְּאָדָם, ם כַּד קָרִיב לְגוֹ קוּדְשָׁא. כֵּיוָן דְּמִתְעֲבֵר מִתַּמָּן, וּבָעֵי לְנַחְתָּא לְתַתָּא, לְאִתְלַבְּשָׁא בִּלְבוּשָׁא לְנַזְקָא עָלְמָא, נָחִית הוּא וּרְתִיכוֹי. וּלְבוּשָׁא קַדְמָאָה דְּקָא נָקִיט תַּבְנִית שׁוֹר, דִּיּוּקְנָא דְּשׁוֹר. וְקַדְמָאָה לַנְּזִיקִין מֵאִינּוּן אַרְבַּע, שׁוֹר אִיהוּ. וְאִינּוּן אַרְבַּע אָבוֹת לְנַזְקָא עָלְמָא. וְכֻלְּהוּ תְּלָתָא אָבוֹת נְזִיקִין, בַּר שׁוֹר, כֻּלְּהוּ דִּילֵיהּ.","וְעַל דָּא כְּתִיב, (תהילים ק״ו:כ׳) וַיָּמִירוּ אֶת כְּבוֹדָם בְּתַבְנִית שׁוֹר אוֹכֵל עֵשֶׂב. מַהוּ אוֹכֵל עֵשֶׂב, הָא דַּרְשִׁינָן בֵּיהּ. אֲבָל עִקָּרָא דְּמִלָּה, מִתַּמְצִית הַלֶּחֶם, וְלָא שִׁבְעַת זִינֵי דָּגָן, לֵית לֵיהּ בְּהוּ חוּלָקָא, וְלָא יָאוּת לֵיהּ לְמֶהֱוִי תַּמָּן.","מִדּוּכְתַּיְיהוּ, וְאִלֵּין יַתְבִין בְּדוּכְתַּיְיהוּ, עַד לָא נָפְקֵי אִלֵּין, זְמִינִין אִלֵּין, נְהִירוּ וּנְצִיצוּ דִּלְהוֹן, לָא יַכְלִין עַיְינִין לְמִסְבַּל. אַזְלִין בְּסָחֲרָנִין, לֵית לְהוֹן שְׁכִיכוּ לְעָלְמִין.","כַּד אֶסְתָּכַּל בַּר נָשׁ בְּהַאי הֵיכָלָא, מִיַּד בְּאִסְתַּכְּלוּתָא קַדְמָאָה, אִתְחֲזֵי זְעֵיר וְלָא זְעֵיר, אֶסְתָּכַּל יַתִּיר, אִתְחֲזֵי רַב. תּוּ אֶסְתָּכַּל, אִתְחֲזֵי יַתִּיר רַב, כָּל מַה דְּאִסְתָּכַּל, הָכִי אִתְחֲזֵי בְּאִתְפָּשְׁטוּתָא רַב וְעִלָּאָה, עַד דְּדָמֵי בְּאִסְתַּכְּלוּתָא כִּמְלֹא נִימָא, דְּלֵית לֵיהּ שִׁיעוּרָא."],[[0,"ומאי קרי, כל וכו׳:","שואל, מה הוא קורא. גבריאל, לאח״כ. ומשיב, הוא קורא כל המעשים של בני העולם. משום שהוא בעל התיק, דהיינו שברשותו הוא הכלי שבו נמצא כל הכתבים ופסקי הדינים והגזירות, וקסת הסופר במתניו, וכותב כל מעשי בני העולם בכל יום. ובלילה אחר שקרא כל הקריאות הנ״ל, הוא קורא כל מה שכתב ביום."],[1,"","[א] \u0003ואלמלא רגלוי אצבעאן וכו':\u0004 ולולא אצבעות רגלים שלו, שיש בהם ב׳ מדרגות, א׳ הוא האצבע העומד באמצע, שהוא גדול. וא׳ הוא האצבע העומד מאחור, שהוא קטן. ולולא ב׳ אצבעות אלו המעכבים עליו, היה שורף אה העולם בשלהביותיו. ומה עושים, כיון שהאיר הבוקר, וחוט של חסד יוצא מצד דרום, אז כולם מתחברים, דהיינו אצבע האמצעית עם אצבע האחורית, ונעשו ב׳ טלפים בכל אחד מב' רגלים, כמו עגל. לקיים מה שכתוב וכף רגליהם ככף רגל עגל. וכבר ידעת סוד הזה. שאלת ענף הגורן (חסר ההמשך)."],[1,"","פירוש. האצבעות ה״ס הארת החכמה, כמ״ש לעיל (ב״א אות ק״ל ע״ש) וכיון שבחצות לילה מתייחד קו האמצעי עם המלכות (כנ״ל ויקהל אות ט״ו ע״ש), יוצא בקו שמאל שבמלכות ב׳ בחינות, א) הארת החכמה שבשמאל המחובר עם קו האמצעי, וכל תקוניו, דהיינו בעיקר, שלא תאיר החכמה ממעלה למטה אלא ממטה למעלה כדרך קו האמצעי (כנ״ל ב״א דף ס׳ ד״ה מחלוקת) והארתו על כן היא הארה גדולה. ב) בחינת קו שמאל שלה מקודם חצות, דהיינו מטרם שקבלה קו האמצעי, והוא מלא דינים ואינו מאיר, ונבחן לבחינת אחורים, וקטנות."],[1,"","והנה גבריאל, הוא מקו שמאל של המלכות, וע״כ יוצא בו ב׳ מדרגות האלו של המלכות, הנזכרות, ונבחנות בו בסוד ב׳ אצבעות רגליו, אותה האצבע שהוא מקו האמצעי הוא אצבע גדול שאורו רב, להיותו מתוקן מקו אמצעי שלא יאיר אלא ממטה למעלה. ואותה האצבע שהיא מבחינת האחור והקטנות דקו שמאל שבמלכות, נקרא אצבע האחור, והוא קטן."],[1,"","וז״ש \u0003ואלמלא רגלוי אצבעאן דיליה,\u0004 שהם הכלים של החכמה, \u0003דאינון תרין דרגין,\u0004 הנמשכות מב' מדרגות שבשמאלה של המלכות \u0003חד, ההוא דקיימא באמצעיתא\u0004 דהיינו האצבע המיוחדת בקו האמצעי, \u0003דאיהו רב,\u0004 שהוא מאיר בבחינת גדלות. \u0003וההוא דקיימא מאחורא,\u0004 דהיינו האצבע המקבל מאחורים דשמאל שבמלכות שאינה מיוחדת עם קו האמצעי וע״כ נבחנת האצבע הזה, \u0003דקיימא מאחורא,\u0004 שהוא אחורים, \u0003דאיהו זעיר,\u0004 שהוא קטן שאינו יכול להאיר. ואלו ב׳ מדרגות האמורות, שגבריאל מקבל מקו שמאל שבמלכות, מעכבים אותו שלא יוכל להמשיך החכמה ממעלה למטה, שהיה שורף בזה את העולם. וז״ש, \u0003ואלמלא רגלוי אצבען דיליה דאינון ב׳ דרגין\u0004 וכו׳ \u0003דקא מעכבין ליה,\u0004 שמעכבים אותו שלא יוכל להמשיך החכמה ממעלה למטה, \u0003יהא מוקיד עלמא בשלהובוי\u0004 שהיה ממשיך החכמה ממעלה למטה, והיה שורף את העולם."],[1,"","ובבוקר כשמתחיל שליטת החסד, אז יוצא חוט של חסד לגבריאל, והוא מקבל בזה גם מדרגת הימין של ז״א, ואז מתחברים ב׳ מדרגות שבשמאל שלו, דהיינו מדרגת \u0003האמצעי\u0004 ומדרגת \u0003האחור,\u0004 ונעשו אחד והחסד שקבל נעשה בו מדרגה שניה לימין, ואז נעשים ב׳ אצבעותיו לבחינת ב׳ טלפים \u0003לימין ושמאל,\u0004 שה״ס חסדים מימין וחכמה משמאל. וז״ש, \u0003כיון דסליק צפרא וחוטא דנהירו נפיק\u0004 וכו׳ \u0003ואתעבדין תרין רגלין תרין טלפין.\u0004 דהיינו אחת לימין ואחת לשמאל, שהם רומזים לחסד וחכמה, וז״ש, \u0003כדין מתחברין כלהו.\u0004 שהחוט של חסד, עם האצבע דאמצע, ואצבע דאחור, כולם מתחברים \u0003ואעבדין בתרין רגלין ב׳ טלפין,\u0004 שאלו הג׳ נעשו שנים, שהם ימין ושמאל, ואחור אין בהם."],[1,"","[ב] \u0003לגו בעזרה דא וכו':\u0004 לפנים העזרה הזו, שה״ס המלכות, יש שס״ה היכלות כחשבון ימי השנה ובכל פתח ופתח שבכל היכל, כתוב, יהי שלום בחילך שלוה בארמנותיך. לא ידוע מה הוא באלו היכלות אלא כולם מסובבים זה בזה, מעשה רוקם. שבע סדרים של מרגליות מסובבים אלו בתוך אלו בכל אחד ואחד, דהיינו בכל היכל והיכל."],[2,"אי חסידא קדישא וכו׳:","אהה חסיד קדוש. כמה משבח רב מתיבתא היכל אחד העומד בראש צד מזרח של עזרה הזו, משום שארבע בחינות הם בעזרה, לד׳ רוחות העולם, שהם, חו״ג, בימין ושמאל, שהם דרום וצפון, ותו״מ במזרח ומערב. אבל ההיכל שבצד מזרח מגדיל האורות שלו יותר מכולם."],[3,"יומא חד בימא וכו׳:","יום אחד, יוצא לויתן בים הגדול, וכל הים מזדעזע, וכל הדגים הולכים לכאן ולכאן. כשמגיע הלויתן אל הפתח של פתח התהום הוא מתחיל לשמוח, והתהומות בשקטים שם (חסר ההמשך) אלא ההוא, הוא כעין מעיין והאורות מתכסים. ואינם נראים כל אלו האורות, חוץ האור שבהיכל הזה שמצד מזרח הזה."],[4,"ההוא מרגלא דקא וכו׳:","שואל, מרגלית ההוא שהלויתן מוציא מתוך התהום ההוא הנקרא \u0003סגדו״ן,\u0004 ממה היא נעשה. ומשיב, אלא יום הזה, שהלויתן הוציא המרגלית, שהים נזדעזע, יום שנחרב בו בית המקדש היה, שהוא יום ט׳ באב. ואותה המרגלית, הנה כשהקב״ה זוכר את בניו ושופך ב׳ דמעות לים הגדול, דמעה אחת נופלת לתהום הזה, שנקרא \u0003סגדו״ן,\u0004 ודמעה אחת נופלת לתוך תהום אחר, שנקרא \u0003גילב״א.\u0004"],[5,"בגין דחמש תהומי וכו׳:","משום שה׳ תהומות אחרות הם בים הגדול, אבל אינן חשובות כאלו אחרות שהם סגדו״ן וגילב״א. וכיון שאלו הדמעות הן נופלות הן נקפאות תוך תהום אחת, ודמעה אחת נטבעת תוך התהום שנקרא \u0003גילב״א.\u0004"],[5,"","ביאור המאמר. העזרה ה״ס ו״ק דמלכות, ובפנימיות העזרה מלובשים ההיכלות שה״ס ע״ס שלמות. ולפיכך הם שס״ה היכלות, כי ג׳ מאות ה״ס ג\"ר שכל אחת כוללת מאה, להיותם מבינה שספירותיה הן בסוד מאות ששים ה״ס ו״ק, שכל אחת כוללת עשרה, להיותם מבחינת ז״א שספירותיו הן בסוד עשרות. והמלכות, ספירותיה בסוד יחידות, והיו צריכות להיות עשרה, אלא מפני שהמלכות חסרה חצי פרצוף שמבחינת עצמותה (כנ״ל ב״ב דף קנ״ח ד\"ה בארבעין), ע״כ נחשבת רק לחמשה. והם שס״ה. וז״ש, (באות ר״ע/ב) \u0003לגו בעזרה דא,\u0004 בפנימיות העזרה הזו, אית שס״ה היכלין, דהיינו ע״ס שלמות כנ״ל, וכדי שלא נטעה לומר שהם בחשבון של מחזה ולמטה כנ״ל אצל שס״ה עמודים (באות רמד/א) על כן אומר \u0003כחושבן יומי שתא,\u0004 שימי השנה ה״ס ע״ס של פרצוף המלכות. \u0003ובכל פתחא ופתחא כתיב יהי שלום\u0004 וגו׳ שזה מראה על שליטת קו האמצעי העושה שלום בין ימין לשמאל של כל הספירות. \u0003לא ידיע מאי הוא בהני היכלין,\u0004 משום שהם ג״ר, ומה שמושג מהם, הוא \u0003שבע סדרין דמרגלאן אתחמן אלין באלין בכל חד וחד,\u0004 נקראים מרגליות, משום שהם בחינות מחזה ולמטה, ששם בחינת רגלין, ומרגלית הוא מלשון מרגלין, והם ז׳ סדרים, משום שיש בהם ז׳ ספירות חג״ת נהי\"מ, כלומר, בחי׳ מחזה ולמטה של כל אחת מז\"ס חג״ת נהי\"מ הם ז׳ סדרים של מרגליות, והם בכל היכל והיכל, ובהם יש השגה. וההיכלות מחולקים לד׳ רוחות, דרום צפון מזרח ומערב, שבעזרה, שה״ס חג״ת ומלכות, וצד המזרח הוא ת״ת שהוא קו האמצעי, וז״ש (באות רע\"א) \u0003היכלא דסטר מזרח אסגי נהורין דיליה יתיר מכלהו,\u0004 להיותו בחינת קו האמצעי הכולל דרום צפון, שהם חו״ג, והוא המשפיע אותם למערב, שהוא מלכות."],[5,"","ונודע שבעת שליטת קו השמאל בים הגדול, נעשה שם מחלוקת בין ימין לשמאל, בסו״ה יעלו שמים ירדו תהומות (כנ״ל באדרא רבא אות רי״ד בהסלם ע״ש) וכן המלכות, הנקראת בית המקדש, נפרדת מז״א, ונחרבת. וזה נמשך עד שקו האמצעי שה״ס לויתן ממעט קו השמאל ומיחד אותו עם הימין, ואז נשקט הים. וחוזר השמחה בעולמות. וז״ש, (באות רע״ב) \u0003יומא חד בימא רבא,\u0004 דהיינו היום שנחרב בו המלכות שה״ס בית המקדש, מחמת התגברות השמאל, \u0003לויתן נפיק,\u0004 יוצא קו האמצעי שנקרא לויתן, והוא משום, \u0003וכל ימא אזדעזע וכל נוני אזלין לכאן ולכאן,\u0004 דהיינו מחמת המחלוקת דימין ושמאל, \u0003כד מטי לויתן בפתחא דפתחא דתהומא,\u0004 דהיינו שהגיע לעשות שלום בין ימין ושמאל, שבזה נעשה פתח בתהום הגדול שנפתחו האורות, \u0003שארי למחדי,\u0004 הוא מתחיל לשמוח \u0003ואשתכך תמן תהומי,\u0004 שהתהומות נשתככו, מהרגז והכעס שבמחלוקת, מפני שהלויתן עשה שלום ביניהם."],[5,"","והנה שלום זה שהלויתן עושה בין שמאל וימין שבים ומיחדם זה בזה, נמצא מגלה בזה הארת החכמה שבשמאל, כי אחר שהשמאל מתיחד עם הימין, החכמה שבשמאל מתלבשת בחסדים שבימין, ואז יכולה החכמה להתגלות. משא״כ מטרם שעשה שלום, היתה החכמה בלי חסדים והיתה מלאה דינים ולא יכלה להאיר. וגילוי חכמה זו ע\"י הלויתן נקרא \u0003מרגלא,\u0004 על שם שאינה נגלית אלא מבחינת מחזה ולמטה בלבד, שנקראת רגלין, ומרגלאן הוא כמו מרגלין. וזה ששואל, (באות רע\"ג) \u0003ההוא מרגלא, דקא אפיק לויתן מגו ההוא תהומא דאקרי סגדו״ן ממה אתעביד.\u0004 שואל, איך נעשה הוצאת המרגלא מן התהום ע״י הלויתן. ומשיב, \u0003אלא יומא דא דקא אפיק לויתן,\u0004 יום הזה שהלויתן בא להוציא המרגלא, \u0003דאזדעזע ימא,\u0004 שאז נזדעזע הים מחמת המחלוקת של ימין ושמאל כנ\"ל, \u0003יומא דאתחרב בי מקדשא,\u0004 הוא היום שבית המקדש שה״ס מלכות נחרבה, מטעם שנפרדה מז״א, \u0003ט׳ באב איהו,\u0004 והוא מכונה ט׳ באב, שהוא יום חורבן בהמ״ק שלמטה. \u0003וההוא מרגלא,\u0004 ומרגלא ההוא שהוציא הלויתן אז, הוא כך, \u0003דכד דכיר קב״ה לבנוי,\u0004 כשהקב״ה זוכר את בניו לגאלם, דהיינו להחזיר אליו המלכות שה״ס בנין בית המקדש, וגאולת ישראל. \u0003ואושיד תרי דמעין לגו ימא רבא,\u0004 שה״ס ב׳ מלכיות אחת \u0003סומקא\u0004 מחמת שמיוחדת עם הבינה, ואחת \u0003אוכמא,\u0004 שה״ס מלכות דמדת הדין (כנ״ל באדרא רבא אות רי״ד) והנה דינים דימין שיש בתהומות נקראים \u0003גילב״א,\u0004 שמשם אין ה \u0003י׳\u0004 יוצאת מאויר, ודינים דשמאל שיש בתהומות נקראים \u0003סגדו״ן,\u0004 שמשם יוצא ה \u0003י'\u0004 מאויר, והשמאל שולט, ועי״ז המים נקפאים (כנ״ל ב״א דף רמ״ז ד״ה ימא דקאפו). וז\"ש, \u0003חד, נפיל לגו תהומא דא דאקרי סגדו\"ן,\u0004 והיינו הדמעה שהיא סומקא הממותקת ומיוחדת היטב בבינה, \u0003וחד, נפיל לגו תהומא אחרא דאקרי גילב״א,\u0004 היינו הדמעה שהיא אוכמא, שיש בה ממלכות דמדת הדין שאינה נמתקת בבינה, היא נופלת לתהום שנקרא \u0003גילבא,\u0004 שהיא הדינים דימין, שמשם אין ה \u0003י׳\u0004 יוצא מאויר. וע״כ הדמעה האוכמא נכללת בדינים ההם וזהו כל תקונה, לא יותר."],[5,"","ויש שם בים ז׳ תהומות, כנגד ז׳ ספירות. כי יש בכל אחת ע״ס, והמסך שבין כו״ח דכל אחת לבין בינה ותו״מ דכל אחת הוא נקרא תהום, וע״כ יש ז׳ תהומות, תהום אחד בכל ספירה. ואלו ב׳ תהומות \u0003גילבא וסגדון,\u0004 הם בחסד וגבורה של ז״ס. וז״ש, \u0003בגין דחמש תהומי אחרנין אינון בימא רבא,\u0004 שהם התהומות שבה׳ ספירות תנהי״מ, \u0003אבל לא חשיבין כהני אחרנין,\u0004 שאינם חשובים כמו \u0003גילבא וסגדון,\u0004 משום שהם בב׳ ספירות העליונות חסד וגבורה. \u0003וכיון דנפלי אינון דמעין קפאן גו תהומי חד,\u0004 דהיינו \u0003בסגדו\"ן,\u0004 ששם יוצא ה \u0003י׳\u0004 מאויר, והשמאל שולט שמחמת זה המים נקפאים, כנ״ל, \u0003וחד אטבע גו תהומא דאקרא גילב\"א,\u0004 ודמעה האוכמא, שמגולה בה עצם המלכות דמדת הדין לא תוכל לקבל תקונה בתהום שנקרא סגדון, אלא שיוצאת משם ונטבע \u0003בגילב״א\u0004 שהם דינין דימין, מסוד נקודת החולם. וזהו כל תקונה. כי מתערבת שם עם הדינין דימין, שהם מבינה. ואח״כ כשהלויתן עושה שלום בין ימין ושמאל והים נפתח, והארת חכמה שבשמאל מקבלת תקונה ומאירה שהיא נקראת \u0003מרגלא,\u0004 כנ״ל הוא מוציא אותה מאותה דמעה סומקא שנפלה לסגדון ונקפאה. שהלויתן, ע״י שמיחד השמאל עם הימין, הוא פותח את \u0003סגדו״ן\u0004 מקפאונו, והדמעה מקבלת הארת החכמה. ונתבאר איך הלויתן מוציא המרגלא מן התהום. ומרגלא זו כוללת ז׳ ספירות וה״ס \u0003ז׳ סדרין דמרגלאן\u0004 שאומר (באות ר״ע). הדינים דימין נקראים \u0003גילב״א,\u0004 שהם אותיות \u0003גיל בא,\u0004 כי ה״ס נקודת החולם הממשיכים חסדים אל הימין, וע״כ \u0003בא\u0004 עמהם \u0003גיל.\u0004 והדינין דשמאל נקראים \u0003סגדו״ן,\u0004 שפירושו משתחוה, כי אין תקונו אלא ע״י הרכנת הראש, שפירושו מיעוט הג״ר דג״ר, כי אז הוא מתיחד עם הימין. ולא זולת."],[6,"דתתא, גו שמרים וכו׳:","למטה, בתוך שמרי היין, שמרים הרעים, יוצא מערער ומקטרג אחד, מזיק הראשון בעולם, והוא בסוד צורת אדם כשקרב אל הקודש. כיון שבעבר מן הקודש ורוצה לרדת למטה, להתלבש בלבוש להזיק העולם, יורד הוא ומרכבותיו. ולבוש הראשון שלוקח הוא תבנית שור, דהיינו צורת שור. והראשון לנזיקין מאלו ארבעה אבות נזיקין, הוא שור. כמ״ש בתחילת בבא קמא, השור והבור המבעה וההבער. והם ארבעה אבות להזיק העולם, וכל שאר ג׳ אבות נזיקין חוץ משור, כולם של השור הוא."],[6,"","פירוש. המוחין דשמאל של המלכות הבאים עם הארת חכמה מלובשת בחסדים נקראים יין. ומחמת הדינים הנמצאים בקו שמאל, יש בסופם, דהיינו בסוף המלכות, פסולת הנקראת שמרי היין. ומפסולת הזאת, יצא מזיק הראשון של הקליפות בעולם. וז״ש, \u0003דתתא גו שמרים דחמרא\u0004 וכו׳ \u0003מזיקא קדמאה.\u0004 ובעוד שהמזיק נכלל בשמרי היין, שבמקום המלכות, יש לו צורת אדם, כמו המלכות, וז״ש, \u0003ואיהו ברזא דיוקנא דאדם כד קריב לגו קודשא,\u0004 דהיינו בעוד שהוא נכלל בשמרי היין, שהם במלכות שה״ס פני אדם. \u0003כיון דמתעבר מתמן\u0004 וכו׳ \u0003נקיט תבנית שור\u0004 וכו', כי הוא מתדבק בקו שמאל בלבדו, שנקרא פני שור. והוא שורש כל המזיקים. וז״ש, \u0003וקדמאה לנזיקין\u0004 וכו׳."],[7,"וע״ד כתיב וימירו","וגו': וע״כ כתוב, וימירו את כבודם בתבנית שור אוכל עשב. שואל, מהו אוכל עשב. ומשיב, כבר דרשנו בו, אבל עיקר הדבר הוא, כי מתמצית הלחם, וכן לא משבעת מיני דגן, שהם מן המלכות, אין לו בהם חלק, ולא ראוי לו להיות שם. כלומר, שאין ראוי לינק ממאכל אדם, שהוא מלכות, וע״כ אומר אוכל עשב."],[8,"מדוכתייהו ואלין יתבין וכו׳:","(חסר תחילת הענין) ממקומם. ואלו יושבים במקומם, עוד מטרם שיצאו אלו מוכנים אלו. באור והתנוצצות שלהם לא יוכלו העינים לשלוט. הולכים מסביב ומקיפים, ואין להם שקט לעולם."],[9,"כד אסתכל בר וכו׳:","כאשר אדם מסתכל בהיכל הזה, מיד בהסתכלות ראשון, נראה לו שהוא קטן ולא קטן. הסתכל יותר נראה שהוא גדול. הסתכל עוד, נראה גדול יותר, כל מה שמסתכל בו, כך הוא נראה בהתפשטות גדול ועליון, יותר. עד שלבסוף בהסתכלותו, כמלא השערה בהיכל ההוא נדמה לו שהוא גדול כל כך עד שאין לו שיעור."]],[[0,"","וּמַה קּוֹרֵא? כָּל מַעֲשֵׂי בְּנֵי הָעוֹלָם, מִשּׁוּם שֶׁהוּא בַּעַל הַתִּיק (שלהחכמה) וְקֶסֶת הַסּוֹפֵר בְּמָתְנָיו, וְכָל מַעֲשֵׂי בְּנֵי הָעוֹלָם כּוֹתֵב בְּכָל יוֹם. וּבַלַּיְלָה לְאַחַר שֶׁקּוֹרֵא כָּל הַקְּרִיאוֹת הַלָּלוּ, קוֹרֵא כָּל מַה שֶּׁכָּתַב בַּיּוֹם."],[1,"","וְאִלְמָלֵא רַגְלָיו אֶצְבָּעוֹת שֶׁלּוֹ, שֶׁהֵם שְׁתֵּי דְרָגוֹת - אֶחָד אוֹתוֹ שֶׁעוֹמֵד בָּאֶמְצַע שֶׁהוּא גָּדוֹל, וְאוֹתוֹ שֶׁעוֹמֵד מֵאָחוֹר שֶׁהוּא קָטָן, שֶׁמְּעַכְּבִים אוֹתוֹ - יִשְׂרֹף הָעוֹלָם בְּשַׁלְהֲבוֹתָיו. וּמָה עוֹשִׂים? כֵּיוָן שֶׁעוֹלֶה הַבֹּקֶר וְחוּט אוֹר יוֹצֵא מִצַּד דָּרוֹם, אָז מִתְחַבְּרִים כֻּלָּם וְנַעֲשִׂים שְׁתֵּי רַגְלַיִם שְׁנֵי טַלְפֵי עֵגֶל, לְקַיֵּם הַכָּתוּב (יחזקאל א) וְכַף רַגְלֵיהֶם כְּכַף רֶגֶל עֵגֶל. וַהֲרֵי יָדַעְתָּ סוֹד זֶה. שְׁאֵלַת עֲנַף הַגֹּרֶן. לְתוֹךָ עֲזָרָה זוֹ יֵשׁ שְׁלֹשׁ מֵאוֹת וְשִׁשִּׁים וַחֲמִשָּׁה הֵיכָלוֹת, כְּחֶשְׁבּוֹן יְמוֹת הַשָּׁנָה. וּבְכָל פֶּתַח וּפֶתַח כָּתוּב: יְהִי שָׁלוֹם בְּחֵילֵךְ שַׁלְוָה בְּאַרְמְנוֹתָיִךְ (תהלים קכב). לֹא יָדוּעַ מַהוּ בַּהֵיכָלוֹת הָאֵלֶּה, אֶלָּא כֻּלָּם נִרְאִים מַעֲשֵׂה צִיּוּר. שִׁבְעָה סִדְרֵי מַרְגָּלִיּוֹת נִרְאִים אֵלּוּ בְאֵלּוּ בְּכָל אֶחָד וְאֶחָד."],[2,"","אִי חָסִיד קָדוֹשׁ, כַּמָּה מְשַׁבֵּחַ רֹאשׁ הַיְשִׁיבָה הֵיכָל אֶחָד שֶׁהוּא בְּרֹאשׁ צַד מִזְרַח הָעֲזָרָה הַזּוֹ, מִשּׁוּם שֶׁאַרְבָּעָה הֵם בְּאַרְבַּעַת צִדְדֵי הָעוֹלָם. אֲבָל הֵיכָל שֶׁל צַד מִזְרָח מַרְבֶּה אוֹרוֹתָיו יוֹתֵר מִכֻּלָּם."],[3,"","יוֹם אֶחָד בַּיָּם הַגָּדוֹל יָצָא לִוְיָתָן, וְכָל הַיָּם הִזְדַּעֲזַע, וְכָל הַדָּגִים הָלְכוּ לְכָאן וּלְכָאן. כְּשֶׁהִגִּיעַ הַלִּוְיָתָן לְפֶתַח פֶּתַח הַתְּהוֹם, מַתְחִיל לִשְׂמֹחַ, וְשָׁכַךְ שָׁם הַתְּהוֹם, אֶלָּא אוֹתוֹ כְּמַרְאֵה הַמַּעְיָן, וּמִתְכַּסִּים הָאוֹרוֹת, וְלֹא נִרְאוּ כָּל אוֹתָם אוֹרוֹת, פְּרָט לְאוֹר הַהֵיכָל שֶׁבְּצַד הַמִּזְרָח הַזֶּה."],[4,"","אוֹתָהּ מַרְגָּלִית שֶׁמּוֹצִיא הַלִּוְיָתָן מִתּוֹךְ אוֹתוֹ תְהוֹם שֶׁנִּקְרָא סַגְדּוֹ\"ן, מִמַּה נֶּעֶשְׂתָה? אֶלָּא יוֹם זֶה שֶׁמּוֹצִיא הַלִּוְיָתָן שֶׁהִזְדַּעֲזַע הַיָּם, יוֹם שֶׁנֶּחֱרַב בֵּית הַמִּקְדָּשׁ, הוּא ט' בְּאָב. וְאוֹתָהּ מַרְגָּלִית, שֶׁכְּשֶׁזּוֹכֵר הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת בָּנָיו וְזוֹרֵק שְׁתֵּי דְמָעוֹת לְתוֹךְ הַיָּם הַגָּדוֹל, אַחַת נוֹפֶלֶת לְתוֹךְ תְּהוֹם זֶה שֶׁנִּקְרָא סַגְדּוֹ\"ן, וְאַחַת נוֹפֶלֶת לְתוֹךְ תְּהוֹם אַחֵר שֶׁנִּקְרָא גִּילְבָ\"א."],[5,"","מִשּׁוּם שֶׁחֲמִשָּׁה תְהוֹמוֹת אֲחֵרִים הֵם בַּיָּם הַגָּדוֹל, אֲבָל לֹא חֲשׁוּבִים כְּאֵלּוּ הָאֲחֵרִים. וְכֵיוָן שֶׁנּוֹפְלוֹת אֵלּוּ הַדְּמָעוֹת, צָפוֹת תּוֹךְ תְּהוֹם אֶחָד. וְאֶחָד נִטְבָּע תּוֹךְ תְּהוֹם שֶׁנִּקְרָא גִּילְבָ\"א."],[6,"","שֶׁלְּמַטָה תּוֹךְ שִׁמְרֵי הַיַּיִן, שְׁמָרִים רָעִים, יוֹצֵא עִרְעוּר אֶחָד מְקַטְרֵג, מַזִּיק קַדְמוֹן, וְהוּא בְּרוּחַ דְּמוּת אָדָם כְּשֶׁמִּתְקָרֵב לַקֹּדֶשׁ. כֵּיוָן שֶׁנֶּעֱבָר מִשָּׁם וְרוֹצֶה לָרֶדֶת לְמַטָּה לְהִתְלַבֵּשׁ בִּלְבוּשׁ לְהַזִּיק אֶת הָעוֹלָם, יוֹרֵד הוּא וּמַרְכְּבוֹתָיו, וּלְבוּשׁ קַדְמוֹן שֶׁלּוֹבֵשׁ תַּבְנִית שׁוֹר, דְּמוּת שׁוֹר. וְרִאשׁוֹן לַנְּזִיקִין מֵאוֹתָם אַרְבָּעָה הוּא שׁוֹר, וְאוֹתָם אַרְבָּעָה אָבוֹת לְהַזִּיק הָעוֹלָם. וְכֻלָּם שְׁלֹשָׁה אֲבוֹת נְזִיקִין פְּרָט לַשּׁוֹר כֻּלָּם שֶׁלּוֹ."],[7,"","וְעַל זֶה כָּתוּב, (תהלים קו) וַיָּמִירוּ אֶת כְּבוֹדָם בְּתַבְנִית שׁוֹר אֹכֵל עֵשֶׂב. מַהוּ אֹכֵל עֵשֶׂב? הֲרֵי דָּרַשְׁנוּ בוֹ, אֲבָל עִקַּר הַדָּבָר מִתַּמְצִית הַלֶּחֶם, וְלֹא מִשִּׁבְעַת מִינֵי דָגָן, אֵין לוֹ בָּהֶם חֵלֶק, וְלֹא רָאוּי לוֹ לִהְיוֹת שָׁם."],[8,"","מִמְּקוֹמוֹתֵיהֶם, וְאֵלֶּה יוֹשְׁבִים בִּמְקוֹמוֹתֵיהֶם. עַד שֶׁלֹּא יוֹצְאִים אֵלּוּ, מְזֻמָּנִים אֵלּוּ. אוֹר וְהִתְנוֹצְצוּת שֶׁלָּהֶם אֵין הָעֵינַיִם יְכוֹלוֹת לִסְבֹּל. הוֹלְכִים מִסָּבִיב, אֵין הֵם שׁוֹכְכִים לְעוֹלָמִים."],[9,"","כְּשֶׁמִּסְתַּכֵּל בֶּן אָדָם בְּהֵיכָל זֶה, מִיָּד בְּהִסְתַּכְּלוּת רִאשׁוֹנָה נִרְאֶה קָטָן וְלֹא קָטָן, מִסְתַּכֵּל יוֹתֵר - נִרְאֶה גָדוֹל. עוֹד מִסְתַּכֵּל - נִרְאֶה יוֹתֵר גָּדוֹל. כָּל מַה שֶּׁמִּסְתַּכֵּל, כָּךְ נִרְאֶה בְּהִתְפַּשְּׁטוּת גָּדוֹל וְעֶלְיוֹן, עַד שֶׁנִּדְמֶה בַהִסְתַּכְּלוּת כִּמְלֹא נִימָה שֶׁאֵין לָהּ שִׁעוּר."]]],[["עוֹבָדִין סַגִּיאִין לְגוֹ, דְּלָא יְדִיעַ אוּמָנוּ דִּלְהוֹן, מִנֵּיהּ נַהֲרָא עֶזְרָה, וְכָל מַה דְּאִית בָּהּ, בַּר כְּרוּבִים דִּנְהוֹרָא דִּלְהוֹן סַלְּקָא עַד רוּם רְקִיעָא, בִּגְוָונִין סַגִּיאִין, וּנְהוֹרִין מְנַצְצָן. אֶלֶף וַחֲמֵשׁ מְאָה וַחֲמִשָּׁה וְשִׁבְעִין גּוּפְנִין, עַבְדִּין אֵיבִין בַּעֲזָרָה דָּא. ם","יַתִּיר (קהלת ד׳:ה׳) חוֹבֵק אֶת יָדָיו, בִּמְרִירוּ וַאֲנִינוּ דִּילֵיהּ, וּלְבָתַר אוֹכֵל אֶת בְּשָׂרוֹ בְּעַל כָּרְחֵיהּ, דְּלֵית לֵיהּ רְשׁוּ לְשַׁלְּטָאָה עַל מִלָּה אַחֲרָא. מָה אִתְהֲנֵי לֵיהּ בְּכָל מַה דְּאַסְטֵי וְעָבִיד וְעָמֵל, דִּלְבָתַר לֵית לֵיהּ רְשׁוּ, אֶלָּא עַל דִּילֵיהּ לְבָתַר מַרְקִיד וְחַדֵּי, כַּכְּסִיל בְּלָא דַּעְתָּא כְּלָל, וְאָזִיל בְּלָא תּוֹעַלְתָּא, וְאָכִיל לְבִשְׂרָא. וּבַשְּׁאָר לֵית לֵיהּ רְשׁוּ. מְרִירוּ דְּעֵילָּא וְתַתָּא, כַּד יִשְׂרָאֵל בְּעָאקוּ, וְאָכְלֵי לוֹן שַׂנְאֵיהוֹן וְלָא יַהֲבֵי חֵילָא בְּעוֹבָדִין טָבִין דִּלְהוֹן, לְאַפָּקָא מִנֵּיהּ.","וַאֲפִילּוּ מִבִּשְׂרֵיהּ דְּאִיהוּ מֵהַאי סְטָר, אַבְאִישׁ קַמֵּי מַלְכָּא קַדִּישָׁא, דְּאִיהוּ רַחוּם וְחַנּוּן. אֲבָל עַל דִּילֵיהּ, רוּחָא קַדִּישָׁא וְנִשְׁמְתָא קַדִּישָׁא, לֵית עִלָּאִין וְתַתָּאִין יַכְלִין לְשַׁלְטָא עֲלוֹי כְּלָל. וְעַל דָּא כָּל תַּסְקוּפִין, וְכָל מַה דְּאַסְטֵי הַהוּא רָע, דְּחָשִׁיב לְמִשְׁלַט עַל רוּחָא קַדִּישָׁא, וּלְבָתַר לָא יָכִיל, וְיָשׁוּב וְאוֹכֵל אֶת בְּשָׂרוֹ. מַה תּוֹעַלְתָּא הֲוָה לֵיהּ. וְעוֹד דְּאִינּוּן חָפָּאן כֻּלְּהוּ כְּעַרְטִירָאָה תַּקִּיף, וְלֵית שְׁכִיכוּ לְעִלָּאִין וְתַתָּאִין.","תָּא וְאֵימָא לְךָ מִלָּה. אִי תֵּימָא, דְּחֵדוּ הוּא לְמַלְאָךְ הַמָּוְת, כַּד קָטִיל בְּנֵי נָשָׁא. לָאו. אֶלָּא בְּגִין דְּחָמֵי דִּרְעוּתָא דְּמָארֵיהּ בְּכַךְ, אַחְזֵי גַּרְמֵיהּ בְּחֵדוּ, לְמֶעְבַּד רְעוּתֵיהּ דְקוּדְשָׁא בְּרִיךְ הוּא, דִּכְתִּיב, (תהילים קמ״ח:ח׳) רוּחַ סְעָרָה עוֹשָׂה דְבָרוֹ. אָמַר לֵיהּ רַבִּי שִׁמְעוֹן, וְהָא אִיהוּ אָזִיל וּמְרַקֵּד בְּחֶדְוָה קַמֵּי נָשִׁין. אָמַר לֵיהּ אִי חֲסִידָא קַדִּישָׁא, וַדַּאי הָכִי הוּא, לְאַחֲזָאָה קַמֵּי מַלְכָּא דְּנִיחָא לֵיהּ בִּרְעוּתֵיהּ דְּמַלְכָּא. אֲבָל נַיְיחָא דִּילֵיהּ בְּהֶסְפֵּדָא דְּנָשִׁין, אִיהוּ רָקִיד וְאוּדְנֵיהּ לְהֶסְפֵּדָא.","אָמַר לֵיהּ אִי הָכִי, אֲמַאי אָזִיל וְאַסְטֵי עַל בַּר נָשׁ לְעֵילָּא, וְאַדְכַּר לְחוֹבוֹי. אָמַר לֵיהּ, בְּגִין דְּאִיהוּ זָקֵן וּכְסִיל, וְחָשִׁיב לְמִשְׁלַט עַל רוּחָא, וְכָל תִּאוּבְתֵּיהּ בְּגִינֵי כַּךְ אִיהוּ, לְסוֹף לָא שַׁלִּיט אֶלָּא עַל דִּילֵיהּ. בִּשְׂרָא דִּילֵיהּ. וְעַל דָּא כְּתִיב, (תהילים ז׳:י״ז) יָשׁוּב עֲמָלוֹ בְרֹאשׁוֹ.","אָזִיל וּבָעֵי לְאַרְגְּשָׁא עָלְמָא, וּמַיָא סְלִיקִין מִגּוֹ שְׁאַר תְּהוֹמִין, וּבָעָאן לְחַפְּיָא עָלְמָא, אִינּוּן דִּמְעִין רְתִיחִין יַתִּיר מִכָּל אֶשָּׁא דְּעָלְמָא. וּמִגּוֹ תּוֹקֶף דִּרְתִּיחוּ דִּלְהוֹן, אַקְפוּ מַיָּא, גּוֹ יַמָּא דְּנִקְפֵּא. וְאִלְמָלֵא דְּרָמַז קוּדְשָׁא בְּרִיךְ הוּא חַד נְשִׁיבוּ מִסִּטְרָא דְּאַבְרָהָם, מֵעַמוּדָא דִּילֵיהּ, וְאַחְזֵי עַל עָלְמָא, לָא יָכִיל לְמֵיקָם אֲפִילּוּ רִגְעָא חֲדָא.","אִינּוּן דִּמְעִין כַּד נַפְלִין גּוֹ יַמָּא, אִשְׁתְּמַע קָלָא בֵּין יַמָּא, עַד מְעַרְתָּא דְּכַפֶּלְתָּא. מִקַל נְהִימוּ דִּלְהוֹן דְּקָא אִשְׁתְּמַע תַּמָּן, כַּד עָאלִין גּוֹ יַמָּא, מִתְעֲרָן אֲבָהָן קַדְמָאֵי, וְקָמוּ, וְחָשְׁבוּ דְקוּדְשָׁא בְּרִיךְ הוּא בָּעֵי לְאָהַפְּכָא עָלְמָא, עַד דְּקָלָא נָפִיק וְאָמַר לוֹן, לָא תִּדְחָלוּ רְחִימִין קַדִּישִׁין, בְּגִינֵכוֹן דָּכִיר קוּדְשָׁא בְּרִיךְ הוּא לִבְנֵיכוֹן, וְאִיהוּ בָּעֵי דְּמִפְרַק לוֹן, וְאַתּוּן תֶּחמוּן.","אַלְפָא בֵּיתִין כֻּלְּהוּ, מְשֻׁלָּבָן וּמִתְצָרְפָאן אִלֵּין בְּאִלֵּין, וְאִתְחַבְּרָן בְּצֵרוּפָא דִּשְׁמָא קַדִּישָׁא. כֵּיוָן דְּאִתְחָזוּן אַתְוָון בְּצֵרוּפָא דָּא, אִלֵּין גְּנִיזִין, וְנָפְקִין אַחֲרָנִין, וְכֵן כֻּלְּהוּ. אִלֵּין גְּנִיזִין, וְאִלֵּין נָפְקִין, כֻּלְּהוּ לְגוֹ בְּחָלוּלָא דְּאִינּוּן כַּפְתּוֹרִים.","תּוּ פַּרְחֵי תְּלַת זִמְנִין בְּיוֹמָא בַּאֲוִירָא וְנָפְקָא לְבַר, וְקַיְּימָא שְׁמָא בְּאַרְבַּע אַתְוָון, תַּלְיָין בַּאֲוִירָא שַׁעֲתָא וּפַלְגָּא, לְבָתַר גָּנִיז דָּא, מִיַּד נָפִיק מִגּוֹ אֲוִירָא מֵחָלוּלָא דִּילֵיהּ, שְׁמָא דִּתְרֵיסָר אַתְוָון, פָּרַח וְתַלְיָא בַּאֲוִירָא, שַׁעֲתָא חֲדָא, וְלָא יַתִּיר. לְבָתַר גָּנִיז דָּא, וְנָפְקָא מִיַּד צֵרוּפָא דְּאַתְוָון אַחֲרָנִין, שְׁמָא דכ' (דכ\"ב) אַתְוָון, וְתַלְיָין בַּאֲוִירָא שַׁעֲתָא אַחֲרָא, וְאַגְנִיז. וּמִיַּד נָפְקֵי אַתְוָון מֵחָלוּלָא אַחֲרָא, שְׁמָא דִּתְמָנְיָא וְעֶשְׂרִין אַתְוָון, מִתְעַטְּרִין כֻּלְּהוּ בְּכִתְרַיְיהוּ, וְקַיְימֵי שַׁעֲתָא וּפַלְגָּא, וְאַגְנִיז דָּא. וּמִיַּד נָפְקֵי תַּלְיָא בַּאֲוִירָא, שְׁמָא דְּעֶשְׂרִין וַחֲמֵשׁ אַתְוָון בְּצִרוּפַיְּיהוּ, וְקַיְּימָא שַׁעֲתָא וּתְלַת רִגְעֵי, נַפְקֵי אַתְוָון דְּאַרְבְּעִין וּתְרֵין אַתְוָון. לְעָלְמָא קַיְּימָא."],[[0,"עובדין סגיאין לגו וכו׳:","מלאכות רבות הפנים שאומנותם אינה ידועה, ממנו מאירה העזרה וכל מה שיש בה. חוץ מהכרובים שהאור שלהם עולה עד רום הרקיע בגוונים רבים ואורות נוצצים. אלף וחמש מאה וחמשה ושבעים גפנים עושים פירות בעזרה זו. (מפני שחסר ההתחלה והסוף של הענין איני יכול לפרשו)."],[1,"יתיר. חובק את וגו׳:","(חמר תחילת הענין) יותר. הכסיל, שהוא הס״א \u0003חובק את ידיו,\u0004 במרירות ואנינות שלו, ואח\"כ \u0003אוכל את בשרו\u0004 בהכרח, כי אין לו רשות לסטרא אחרא, לשלוט על דבר אחר, חוץ מבשר. מה הוא נהנה בכל מה שהשטין ועשה ועמל עד שהמיתו, שלאחר כך אין לו רשות להנות ממנו אלא על מה שהוא שלו, שהוא הבשר, כי הס״א נותנת לאדם את הבשר (כנ״ל אות רל״ח ע״ש) ואח״כ הוא רוקד ושמח ככסיל בלא דעת כלל, והולך בלא תועלת, ואוכל את הבשר, ובשאר אין לו רשות. והוא מרירות שלמעלה ושלמטה, כשישראל בצרה ושונאיהם אוכלים אותם, ואינם נותנים כח במעשים טובים שלהם להוציאם ממנו. מן הס״א."],[2,"ואפילו מבשריה דאיהו וכו':","ואפילו מבשר שהוא של צד ההוא, רע לפני מלך הקדוש לתת אותו לס״א, כי הוא רחום וחנון. אבל על שלו, של הקדוש ברוך הוא, שהוא רוח הקדוש ונשמה הקדושה, אין העליונים והתחתונים יכולים לשלוט עליו כלל. וע״כ כל העלילות וכל מה שהסטין אותו הרע, הס״א, שחשב לשלוט על הרוח הקדוש, ולבסוף אינו יכול, וישוב \u0003ואוכל את בשרו.\u0004 ואיזה תועלת היה לו. מן הקטרוגים שלו. (חסר כאן איזה מלות) ועוד שהם מכסים כולם כערפל חזק. ואין מנוחה לעליונים ותחתונים."],[2,"תסקופין","פירושו, עלילות. כי על עלילות דברים מתרגם תסקופי מלין (דברים כ״ב י״ד) \u0003ערטיראה\u0004 הוא ערפל, לפי הענין."],[3,"תא ואימא לך וכו׳:","בוא ואומר לך דבר. אם תאמר שהיא שמחה למלאך המות כשהורג בני אדם. לא. אלא משום שרואה שרצונו של אדונו הוא בזה, מראה את עצמו בשמחה לעשות רצונו של הקב״ה. שכתוב, רוח סערה עושה דברו. א״ל ר״ש והרי הוא הולך ורוקד בשמחה לפני הנשים. א״ל אהה חסיד קדוש. ודאי כך הוא, כדי להראות לפני המלך, שיש לו נחת מרצון המלך. אבל הנחת שלו בהספד הנשים, הוא, שהוא רוקד ואזנו אל ההספד."],[4,"א\"ל אי הכי וכו׳:","אמרו לו א״כ, למה הולך ומסטין על האדם למעלה, ומזכיר את עונותיו. כיון שאין לו שמחה מהריגת האדם. אמר לו, משום שהוא זקן וכסיל, וחושב לשלוט על הרוח, וכל תאותו הוא בשביל זה. אבל לסוף אינו שולט אל על מה שהוא שלו. הבשר הוא שלו (כנ״ל באות רל״ח ע״ש) וע״כ כתוב, ישוב עמלו בראשו. דהיינו שאינו נהנה מן העמל שלו, שהסית למטה והסטין למעלה."],[5,"אזיל ובעי לארגשא וכו׳:","(חסר ההתחלה) הולך ורוצה להרעיש העולם. והמים עולים מתוך שאר התהומות, ורוצים לכסות העולם. אלו הדמעות, דהיינו ב׳ דמעות שמוריד הקב״ה לים הגדול (כנ\"ל אות רע״ג) הם רותחים יותר מכל אש שבעולם, ומתוך תוקף רתיחתם הם מקפיאים המים בתוך ים הקפוי. כי הדמעה האדומה הנופלת לתהום הנקרא סגדו״ן, מקפאת המים (כנ״ל אות רע\"ד) כי הם מעוררים שליטת השמאל, ושליטת השמאל בלי ימין מקפיא הים (כנ״ל ב״א דף רמ״ז ד\"ה ימא דקאפו) ואם לא היה רומז הקב״ה שהוא קו האמצעי, ע״י מסך דחירק (כנ״ל לך דף י״ג ד״ה ונתבאר) שבזה רומז לנשיבת רוח אחד מצד אברהם, שהוא חסדים, מן העמוד שלו, דהיינו קו הימין, שיתיחד עם השמאל, ומראה הארתו על העולם, לא היה העולם יכול לעמוד אפילו רגע אחד."],[6,"אינון דמעין כד וכו׳:","אלו הדמעות, כשהן נופלות תוך הים, נשמע הקול בין גלי הים עד מערת המכפלה. מקוד נהימתם הנשמע שם כשנכנסים תוך הים, מתעוררים אבות הראשונים, וקמים, וחושבים, שהקב״ה רוצה להפוך את העולם, עד שהקול יוצא ואומר להם, אל תראו אהובים הקדושים, בשבילכם זוכר הקב״ה את בניכם, והוא רוצה לגאול אותם, ואתם תראו."],[6,"","פירוש. כשהדמעות נופלות תוך הים נופלים תחילה לתהום הנקרא סגדון, ואז יוצא הי׳ מן האויר (כנ״ל אות רע״ד) והקו שמאל מתחיל לשלוט, ואז נעשה מחלוקת בין ימין ושמאל, בסוד יעלו שמים ירדו תהומות (כנ״ל באדרא רבא אות רי״ד בהסולם) וז״ש, \u0003אינון דמעין כד נפלין גו ימא אשתמע קלא,\u0004 דהיינו קול גלי הים העולות שמים מתוך הארת השמאל, ונופלים ויורדים בחזרה תהומות, מתוך הארת הימין (כמ״ש שם) וז״ש \u0003מקל נהימו דלהון\u0004 וכו' \u0003מתערן אבהן קדמאי,\u0004 שהם אברהם ויצחק. להיותם מרכבה לב' הקוין ימין ושמאל. \u0003וקמו וחשבו דקב״ה בעי לאהפכא עלמא,\u0004 מכח המחלוקת דימין ושמאל, \u0003עד דקלא נפיק,\u0004 שהוא קו האמצעי הנקרא קול, והוא יעקב, \u0003ואמר לון לא תדחלון,\u0004 כי הקול, עושה שלום ביניהם ומקיים הארת שניהם וז״ש, \u0003בגינכון דכיר קב״ה לבניכון\u0004 וכו', כי אחר שמקיים הארת שניהם, הרי כל המוחין וכל הגאולות נמשכים לישראל מהארתם של ב׳ הקוין ימין ושמאל."],[7,"אלפא ביתין כלהו וכו׳:","(חסר תחילת הענין) כל האלפא ביתות משתלבים ומצטרפים אלו באלו, ומתחברים בצירוף השם הקדוש. אחר שנראו האותיות בצירוף זה, אותיות אלו נגנזות, ואחרות יוצאות ומצטרפות לצירוף אחר. וכן כולם, אלו נגנזות ואלו יוצאות, וכולם בפנים בתוך החלל של אלו הכפתורים."],[8,"תו פרחי תלת וכו':","עוד פורחות האותיות ג׳ פעמים ביום באויר, ויוצאות לחוץ, והשם עומד בארבע אותיות תלויות באויר, שעה ומחצה. לאחר כך נגנז שם הזה, ומיד יוצא מתוך האויר, מן החלל שלו, השם של י״ב אותיות. הוא פורח ותלוי באויר, שעה אחת ולא יותר. ולאחר כך נגנז שם הזה, ויוצא מיד צירוף אותיות אחרות, השם של כ״ב אותיות. ותלויות באויר שעה אחרת, ונגנז. ומיד יוצאות אותיות מחלל אחר, השם של כ״ח אותיות, מתעטרות כולן בכתריהן, ועומדות שעה ומחצה, ונגנז השם הזה. ומיד יוצא תלוי באויר השם של כ״ה אותיות בצירופיהם. ועומד שעה וג׳ רגעים (יש כאן חסר) יוצאות אותיות במ״ב אותיות. (יש כאן חסר) עומד לעולם. (חסר ההמשך)."]],[[0,"","מַעָשִׂים גְּדוֹלִים לִפְנִים שֶׁלֹּא יְדוּעָה אֻמָּנוּתָם, מִשָּׁם מְאִירָה עֲזָרָה וְכָל מַה שֶּׁיֵּשׁ בָּהּ, פְּרָט לַכְּרוּבִים שֶׁאוֹרָם עוֹלֶה עַד רוּם הָרָקִיעַ בִּגְוָנִים רַבִּים, וְאוֹרוֹת נוֹצְצִים. אֶלֶף וַחֲמֵשׁ מֵאוֹת וַחֲמִשָּׁה וְשִׁבְעִים גְּפָנִים עוֹשִׂים פֵּרוֹת בַּעֲזָרָה זוֹ."],[1,"","יוֹתֵר - (קהלת ד) חֹבֵק אֶת יָדָיו, בִּמְרִירוּת וַאֲנִינוּת שֶׁלּוֹ, וְאַחַר כָּךְ - אֹכֵל אֶת בְּשָׂרוֹ, בְּעַל כָּרְחוֹ, שֶׁאֵין לוֹ רְשׁוּת לִשְׁלֹט עַל דָּבָר אַחֵר. מָה עוֹזֵר לוֹ בְּכָל מַה שֶּׁמַּסְטֶה וְעוֹשֶׂה וְעָמֵל שֶׁלְּאַחַר כָּךְ אֵין לוֹ רְשׁוּת אֶלָּא עַל שֶׁלּוֹ, אַחַר כָּךְ מַרְקִיד וְשָׂמֵחַ כִּכְסִיל בְּלִי דַעַת כְּלָל, וְהוֹלֵךְ לְלֹא תוֹעֶלֶת וְאוֹכֵל הַבָּשָׂר. וּבַשְּׁאָר אֵין לוֹ רְשׁוּת. מְרִירוּת שֶׁלְּמַעְלָה וְשֶׁלְּמַטָּה, כְּשֶׁיִּשְׂרָאֵל בְּצָרָה וְאוֹכְלִים אוֹתָם שׂוֹנְאֵיהֶם, וְלֹא נוֹתְנִים כֹּחַ בְּמַעֲשֵׂיהֶם הַטּוֹבִים לְהוֹצִיא מִמֶּנּוּ."],[2,"","וַאֲפִלּוּ מִבְּשָׂרוֹ שֶׁהוּא מִצַּד זֶה, מֵרֵעַ לִפְנֵי הַמֶּלֶךְ הַקָּדוֹשׁ, שֶׁהוּא רַחוּם וְחַנּוּן. אֲבָל עַל שֶׁלּוֹ, רוּחַ הַקֹּדֶשׁ וּנְשָׁמָה קְדוֹשָׁה, אֵין עֶלְיוֹנִים וְתַחְתּוֹנִים יְכוֹלִים לִשְׁלֹט עָלָיו כְּלָל. וְעַל כָּךְ כָּל הָעֲלִילוֹת וְכָל מַה שֶּׁמַּסְטֶה אוֹתוֹ רָע, שֶׁחוֹשֵׁב לִשְׁלֹט עַל רוּחַ הַקֹּדֶשׁ וְאַחַר כָּךְ לֹא יָכוֹל, וְיָשׁוּב וְאוֹכֵל אֶת בְּשָׂרוֹ, מַה תּוֹעֶלֶת הָיָה לוֹ? וְעוֹד, שֶׁהֵם מְכַסִּים כֻּלָּם כְּמוֹ מְעֻרְפָּל חָזָק, וְאֵין שׁוֹכְכִים עֶלְיוֹנִים וְתַחְתּוֹנִים."],[3,"","בֹּא וְאֹמַר לְךְ דָּבָר. אִם תֹּאמַר שֶׁשִּׂמְחָה הִיא לְמַלְאַךְ הַמָּוֶת כְּשֶׁהוֹרֵג בְּנֵי אָדָם - לֹא. אֲבָל מִשּׁוּם שֶׁרוֹאֶה שֶׁרְצוֹן רִבּוֹנוֹ בְּכָךְ, מַרְאֶה עַצְמוֹ בְשִׂמְחָה לַעֲשׂוֹת רְצוֹן הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁכָּתוּב (תהלים קמח) רוּחַ סְעָרָה עֹשָׂה דְבָרוֹ. אָמַר לוֹ רַבִּי שִׁמְעוֹן, וַהֲרֵי הוּא מְרַקֵּד וְהוֹלֵךְ בְּחֶדְוָה לִפְנֵי נָשִׁים. אָמַר לוֹ, אִי חָסִיד קָדוֹשׁ, וַדַּאי כָּךְ זֶה, לְהֵרָאוֹת לִפְנֵי הַמֶּלֶךְ שֶׁנּוֹחַ לוֹ בִּרְצוֹן הַמֶּלֶךְ. אֲבָל הַנַּחַת שֶׁלּוֹ בְּהֶסְפֵּד הַנָּשִׁים. הוּא רוֹקֵד, וְאָזְנָיו לַהֶסְפֵּד."],[4,"","אָמַר לוֹ, אִם כָּךְ, מַדּוּעַ הוֹלֵךְ וּמַסְטֶה עַל הָאָדָם לְמַעְלָה וּמַזְכִּיר חֲטָאָיו? אָמַר לוֹ, מִשּׁוּם שֶׁהוּא (קהלת ד) זָקֵן וּכְסִיל, וְחוֹשֵׁב לִשְׁלֹט עַל הָרוּחַ, וְכָל תַּאֲוָתוֹ הִיא בִּגְלַל זֶה. בַּסּוֹף לֹא שׁוֹלֵט אֶלָּא עַל שֶׁלּוֹ, בְּשָׂרוֹ, וְעַל זֶה כָּתוּב (תהלים ז) יָשׁוּב עֲמָלוֹ בְרֹאשׁוֹ."],[5,"","הוֹלֵךָ וְרוֹצֶה לְרַגֵּשׁ אֶת הָעוֹלָם, וּמַיִם עוֹלִים מִתּוֹךְ שְׁאָר תְּהוֹמוֹת וְרוֹצִים לְכַסּוֹת הָעוֹלָם. אוֹתָן דְּמָעוֹת רוֹתְחוֹת יוֹתֵר מִכָּל אֵשׁ שֶׁבָּעוֹלָם. וּמִתּוֹךְ תֹּקֶף הָרְתִיחָה שֶׁלָּהֶן, קוֹפְאִים הַמַּיִם תּוֹךְ הַיָּם הַקָּפוּא, וְאִלְמָלֵא שֶׁרָמַז הַקָּדוֹשׁ בָּרוּךְ הוּא נְשִׁיבָה אַחַת מִצַּד אַבְרָהָם מֵעַמּוּד שֶׁלּוֹ וְנִרְאֶה כָּל הָעוֹלָם, לֹא יָכוֹל לַעֲמֹד אֲפִלּוּ רֶגַע אֶחָד."],[6,"","אוֹתָן דְּמָעוֹת כְּשֶׁנּוֹפְלוֹת לְתוֹךְ הַיָּם, נִשְׁמָע קוֹל בֵּין הַיָּם עַד מְעָרַת הַמַּכְפֵּלָה. מִקּוֹל נַהֲמָתָם שֶׁנִּשְׁמָע שָׁם כְּשֶׁנִּכְנָסִים לְתוֹךְ הַיָּם, מִתְעוֹרְרִים אָבוֹת הָרִאשׁוֹנִים, וְקָמוּ, וְחָשְׁבוּ שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא רוֹצֶה לַהֲפֹךְ אֶת הָעוֹלָם, עַד שֶׁקּוֹל יוֹצֵא וְאוֹמֵר לָהֶם: אַל תְּפַחֲדוּ אֲהוּבִים קְדוֹשִׁים, בִּגְלַלְכֶם זוֹכֵר הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת בְּנֵיכֶם, וְהוּא רוֹצֶה לִגְאֹל אוֹתָם, וְאַתֶּם תִּרְאוּ."],[7,"","כָּל הָאַלְפָא בֵּיתוֹת מְשֻׁלָּבוֹת וּמִצְטָרְפוֹת אֵלֶּה בְאֵלֶּה, וּמִתְחַבְּרוֹת בְּצֵרוּף הַשֵּׁם הַקָּדוֹשׁ. כֵּיוָן שֶׁנִּרְאוּ הָאוֹתִיּוֹת בְּצֵרוּף זֶה, אֵלֶּה נִגְנָזִים, וְיוֹצְאִים אֲחֵרִים, וְכֵן כֻּלָּם. אֵלֶּה נִגְנָזִים, וְאֵלֶּה יוֹצְאִים, כֻּלָּם לִפְנִים בַּחֲלַל אוֹתָם כַּפְתּוֹרִים."],[8,"","שׁוּב פּוֹרְחִים שָׁלֹשׁ פְּעָמִים בַּיּוֹם בָּאֲוִיר וְיוֹצְאִים הַחוּצָה, וְעוֹמֵד הַשֵּׁם בְּאַרְבַּע אוֹתִיּוֹת, תְּלוּיִים בָּאֲוִיר שָׁעָה וָחֵצִי. לְאַחַר שֶׁנִּגְנַז זֶה מִיָּד יוֹצֵא מִתּוֹךְ חֲלַל הָאֲוִיר שֵׁם שֶׁל שְׁתֵּים עֶשְׂרֵה אוֹתִיּוֹת, פּוֹרֵחַ וְתָלוּי בָּאֲוִיר שָׁעָה אַחַת, וְלֹא יוֹתֵר. אַחַר כָּךְ זֶה נִגְנָז, וְיוֹצֵא מִיָּד צֵרוּף אוֹתִיּוֹת אֲחֵרוֹת, שֵׁם שֶׁל כ' (של כ\"ב) אותיות, ותלוי באויר שעה אחרת ונגנז. ומיד יוצאות אותיות מחלל אחר, שם של עשרים ושמונה אותיות, מתעטרים כלם בכתריהם, ועומדים שעה וחצי, ונגנז זה. ומיד יוצאים תלויים באויר שם של עשרים וחמש אותיות בצרופיהן, ועומד שעה ושלשה רגעים. יוצאות אותיות של ארבעים ושתים אותיות, ועומדות לעולם."]]],[["שְׁמָהָן. אֶלָּא אַתְוָון כּוּלְּהוּ, לָא מִשְׁתַּכְכֵי לְעָלְמִין, בַּלְטֵי וּמְנַצְצֵי לְבַר, וְסַלְקֵי וְנַחְתֵּי, לֵית מַאן דְּיָכִיל לְקַיְּימָא בְּהוּ, בַּר מָשִׁיחַ בְּטוֹרַח סַגִּי. דָּא גָּנִיז, לְבָתַר דְּקַיְּימָא תְּרֵין שַׁעְתִּין וְעֶשְׂרִין וּתְרֵין רְגָעִין, וְהַאי שְׁמָא גְּלִיפָא דְּע\"ב אַתְוָון קָא נָפִיק. וְקַיְּימָא וְתַלְיָא בַּאֲוִירָא, שַׁעֲתָא וּפַלְגָּא. כָּל הָנֵי שְׁמָהָן לָא נָפְקֵי, וְלָא אִתְחָזוּן, אֶלָּא זִמְנָא חֲדָא בְּיוֹמָא, אֲבָל אִינּוּן אַלְפָא בֵּיתִין, אִתְחָזוּן פַּרְחִין בַּאֲוִירָא, וּמְצָרְפִין אִלֵּין בְּאִלֵּין, תְּלַת זִמְנִין בְּיוֹמָא.","כַּד פַּרְחָן אַתְוָון דְּאַלְפָא בֵּיתִין, אִלֵּין פַּרְחִין מִכָּאן, וְאִלֵּין מִכָּאן, וּמִתְצָרְפָן כֻּלְּהוּ. כַּד נָחִית תַּמָּן רַב מְתִיבְתָּא, שָׁארֵי, מָשִׁיחַ חָמָא בְּצֵרוּפָא דְּאַלְפָא בֵּיתָא, אַתְוָון כְּמָה דְּחָמָא דָּנִיאֵל, דְּאִינּוּן ממתוס ננקפי אאלרן.","כָּל מַעֲלֵי שַׁבְּתָא, כַּד מְקַדְּשִׁין יִשְׂרָאֵל יוֹמָא לְתַתָּא, כָּרוֹזָא כָּרִיז לְאַרְבַּע סִטְרֵי עָלְמָא, אִתְכְּנָשׁוּ מַשִׁרְיָין קַדִּישִׁין, אַתְּקָנוּ כֻּרְסְיָין (קדישין). מַאן חָמֵי חֶדְוָה, בִּתְלַת מְאָה וְתִשְׁעִין רְקִיעִין, כַּמָּה מְמָנָן, כַּמָּה שִׁלְטוֹנִין, מִתְכַּנְּשִׁין לְאַתְרַיְיהוּ. כֵּיוָן דְּיִשְׂרָאֵל לְתַתָּא מְקַדְּשִׁין (לקודשא בריך הוא), כְּדֵין אִתְּעַר אִילָנָא דְּחַיֵּיא, וְאָקִישׁ בְּאִינּוּן טַרְפִּין דִּילֵיהּ, רוּחַ נְשִׁיבוּ חַד מִגּוֹ עָלְמָא דְּאָתֵי, וְאִינוּן עֲנָפִין דְּאִילָנָא מִתְנַעְנְעָן, וְסַלְּקִין רֵיחִין דְּעָלְמָא דְּאָתֵי.","הַהוּא אִילָנָא דְּחַיֵּי אִתְּעַר, וְאַפִּיק נִשְׁמָתִין קַדִּישִׁין, וּפָרִישׂ עַל עָלְמָא. וְעִם כָּל דָּא, נִשְׁמָתִין נָפְקִין, וְנִשְׁמָתִין עָאלִין, אִלֵּין מִתְעָרֵי אִלֵּין, אִלֵּין נָפְקִין וְאִלֵּין עָאלִין, וְאִילָנָא דְּחַיֵּי בְּחֶדְוָה.","וּכְדֵין, יִשְׂרָאֵל כֻּלְּהוּ מִתְעַטְּרִין בְּעִטְרִין דְּאִינּוּן נִשְׁמָתִין קַדִּישִׁין, כֻּלְּהוּ בְּחֶדְוָה בְּנַיְיחָא. וְכָל הַשַּׁבָּת, אִית לוֹן הַהוּא חֶדְוָה, וְהַהוּא נַיְיחָא, וְכָל צַדִּיקַיָּיא דִּי בְּגִנְתָּא, כֻּלְּהוּ סַלְּקִין וּמִתְעַנְּגִין בְּעִנּוּגָא עִלָּאָה, דְּעָלְמָא דְּאָתֵי. כֵּיוָן דְּנָפִיק שַׁבָּתָא, כֻּלְּהוּ נִשְׁמָתִין פַּרְחִין וְסַלְּקִין.","תָּא חֲזֵי, כַּד עָיֵיל שַׁבְּתָא נִשְׁמָתִין נַחְתִּין לְשַׁרְיָיא עַל עַמָּא קַדִּישָׁא. וְנִשְׁמָתִין דְּצַדִּיקַיָּיא סַלְּקִין לְעֵילָּא. כַּד נָפִיק שַׁבְּתָא, נִשְׁמָתִין סַלְּקִין, אִינּוּן דְּשָׁארוּ עָלַיְיהוּ דְּיִשְׂרָאֵל. וְנִשְׁמָתִין נַחְתִּין, אִינּוּן נִשְׁמָתִין דְּצַדִּיקַיָּיא.","כֵּיוָן דְּסַלְּקִין כֻּלְּהוּ נִשְׁמָתִין דְּשָׁארוּ עָלַיְיהוּ דְּיִשְׂרָאֵל. סַלְקֵי וְקַיְימִין בְּדִיּוּקְנָא קַמֵּי מַלְכָּא קַדִּישָׁא, וְקוּדְשָׁא בְּרִיךְ הוּא שָׁאִיל לְכֻלְּהוּ, מַאי חִדּוּשָׁא הֲוָה לְכוּ בְּהַהוּא עָלְמָא בְּאוֹרַיְיתָא. זַכָּאָה אִיהוּ מַאן דְּחִדוּשָׁא דְּאוֹרַיְיתָא אַמְרַת קַמֵּיהּ. כַּמָּה חֶדְוָה עָבִיד קוּדְשָׁא בְּרִיךְ הוּא, כָּנִישׁ לְפָמַלְיָא דִּילֵיהּ, וְאָמַר, שִׁמְעוּ חִדּוּשָׁא דְּאוֹרַיְיתָא, דְּאַמְרַת נִשְׁמְתָא דָּא דִּפְלוֹנִי, וְכֻלְּהוּ מוּקְמֵי הַהִיא מִלָּה בִּתְרֵי מְתִיבְתֵּי. אִינּוּן לְתַתָּא, וְקוּדְשָׁא בְּרִיךְ הוּא לְעֵילָּא, חָתִים לְהַהִיא מִלָּה.","תָּא חֲזֵי, כַּד מִלָּה אִתְחֲדָּשׁ בְּאוֹרַיְיתָא, וְנִשְׁמְתָא דְּנַחְתָּא בְּשַׁבְּתָא אִתְעַסְּקַת בְּאִינּוּן מִלִּין חַדְתִּין, וְסַלְקֵי לְעֵילָּא. כָּל פָּמַלְיָא דִּלְעֵילָּא, צַיְיתִין לְהַהוּא מִלָּה, וְחַיּוֹת הַקֹּדֶשׁ מִתְרָבִין בְּגַדְפִּין, וּמִתְלַבְּשָׁן בְּגַדְפִּין. וְכַד שָׁאִיל לוֹן קוּדְשָׁא בְּרִיךְ הוּא, וְלָא תָּבִין וְשַׁתְקִין, כְּדֵין חַיוֹת הַקֹּדֶשׁ מַה כְּתִיב, (יחזקאל א׳:כ״ד) בְּעָמְדָם תְּרַפֶּינָה כַנְפֵיהֶן, כְּמָה דְּאַתְּ אָמֵר (איוב ל״ב:ט״ז) כִּי עָמְדוּ לֹא עָנוּ עוֹד. (נחמיה ח׳:ה׳) וּכְפִתְחוֹ עָמְדוּ כָּל הָעָם.","וְאִי תֵּימָא, שְׁתִיקָה אֲמַאי קָרוּ לֵיהּ עֲמִידָה. אֶלָּא, בְּדִבּוּרָא אִית ז' שַׁיְיפִין דְּמִתְנַעֲנְעָן בַּהֲדֵיהּ, לִבָּא. רֵיאָה. קָנֵה. לָשׁוֹן. שִׁנַּיִים. שִׂפְוָון. בָּשָׂר. וּבִשְׁתִּיקָה קַיְימוּ בְּקִיּוּמַיְיהוּ, בְּלָא נִעְנוּעָא. וְעַל דָּא קָרֵי לַשְׁתִּיקָה עֲמִידָה.","דְּהָא רַב הַמְנוּנָא סָבָא אָמַר, (נ\"א רב מתיבתא) (תהילים כ׳:ג׳) יִשְׁלַח עֶזְרְךָ מִקֹדֶשׁ וְגוֹ'. מִקֹדֶשׁ, דָּא קִדּוּשׁ יָדַיִם. וּמִצִיּוֹן יִסְעָדֶךָ, דָּא הַמּוֹצִיא, דְּאִיהוּ סָעִיד לִבָּא דְּבַר נָשׁ. יִזְכּוֹר כָּל מִנְחוֹתֶיךָ, כָּל לְאַסְגָּאָה מִלָּה אַחֲרָא, דָּא נְטִּילַת יָדַיִם בַּתְרַיְיתָא. וְעוֹלָתְךָ יְדַשְּׁנֶה סֶּלָה, דָּא בִּרְכַּת הַמָּזוֹן בְּזִמּוּן. וְאִי אַתְּ עָבִיד כֵּן, יִתֶּן לְךָ כִלְבָבֶךָ וְכָל עֲצָתְךָ יְמַלֵּא. וּבְשַׁבָּת מְקַדֵּשׁ, דָּא קְדוּשָּׁא רַבָּא. וְעַל מִלָּה דָּא, אִתְעַטָּרוּ צַדִּיקַיָּיא בְּגַן עֵדֶן, מִשַּׁבָּת לְשַׁבָּת אַחֲרָא."],[[0,"שמהן. אלא אתוון וכו׳:","(חסר תחלת הדברים) השמות. אלא אותיות כולן אינן שקטות לעולם, בולטות ונוצצות לחוץ, ועולות ויורדות. אין מי שיכול לעמוד עליהם, חוץ ממשיח ביגיעה רבה. השם הזה נגנז אחר שעומד ב׳ שעות וכ״ב רגעים. ושם הזה החקוק בע״ב אותיות, יוצא. ועומד ותלוי באויר שעה ומחצה. כל אלו השמות אינם יוצאים ואינם נראים אלא פעם אחת ביום, אבל האלפא ביתות נראות פורחות באויר, ומצטרפות אותיות עם אותיות, ג׳ פעמים ביום."],[1,"כד פרחן אתוון וכו׳:","כשפורחות האותיות של אלפא ביתא, אלו פורחות מכאן ואלו פורחות מכאן וכולן מצטרפות. כשירד שם רב מתיבתא, התחיל, משיח ראה בצירופי אלפא ביתא אותיות כמו שראה דניאל, שהוא ראה האותיות \u0003ממתוס ננקפי אאלרן,\u0004 אשר ידע לצרף מהם, \u0003מנא מנא תקל ופר סין,\u0004 כי ג׳ אותיות ראשונות של ג׳ צירופים אלו הם \u0003מנא\u0004 וג' אותיות שניות שבהם מצטרפים ג״כ, \u0003מנא\u0004 וג׳ אותיות שלישיות מצטרפות, \u0003תקל,\u0004 וג׳ אותיות רביעיות מצטרפות \u0003ופר,\u0004 וג׳ אותיות חמישיות מצטרפות, \u0003סין.\u0004 (שפירושם בסנהדרין כב.) איני יכול לפרש, מאמר החשוב הזה, מפני רוב החסרים שבו."],[2,"כל מעלי שבתא וכו׳:","בכל ליל שבת, כשישראל מקדשים היום למטה הכרוז יוצא לד׳ רוחות העולם, התאספו מחנות הקדושים, התקינו כסאות. מי ראה השמחה, כאשר בש״צ רקיעים כמה ממונים כמה שליטים מתאספים למקומותיהם. כיון שישראל למטה מקדשים היום, אז נתעורר עץ החיים שהוא ז״א, ורוח אחד נושב מן עולם הבא שהוא בינה, מכה בעלים שלו. ואלו הענפים שבאילן מתנענעים, ומעלים ריחות של עולם הבא. \u0003אילן\u0004 הוא ז״א, \u0003ענפיו,\u0004 הם הספירות שלו, \u0003עלים\u0004 הם הנשימות שמוליד. \u0003ש״צ\u0004 רקיעים, ה״ס חו״ב תו״מ שכל אחד כלול מאה. רק המלכות חסרה העשר האחרונות שלהיותן ממלכות דמלכות שהן ממדת הדין, הן נגנזות. וע״כ הן ד׳ מאות חסר עשר."],[3,"ההוא אילנא דחיי וכו׳:","עץ החיים ההוא התעורר ומוציא נשמות קדושות, ופורש אותן על העולם. ועם כל זה, נשמות יוצאות ונשמות נכנסות, כלומר, שנשמות יוצאות להתלבש בישראל בעולם הזה, ונשמות הצדיקים עולים מגן עדן התחתון ונכנסות למעלה לגן עדן העליון. ואלו היוצאות מעוררות לאלו שיכנסו, וע״כ אלו יוצאות ואלו עולות, ועץ החיים שהוא ז״א, הוא בשמחה."],[4,"וכדין ישראל כלהו וכו׳:","ואז כל ישראל מתעטרים בעטרות של אלו הנשמות הקדושות שה״ס נשמות יתרות, וכולם בשמחה ובנחת. וכל השבת יש להם שמחה ההיא ונחת ההיא, וכל הצדיקים שהם בגן כולם עולים ומתענגים בעונג העליון של עולם הבא, בגן עדן העליון. כיון שיוצא השבת כל הנשמות פורחות מישראל, ועולות למעלה."],[5,"ת״ח כד עייל וכו׳:","בוא וראה כשנכנס השבת, יורדות הנשמות, דהיינו נשמות יתרות, לשרות על עם הקדוש, ונשמות הצדיקים מג״ע התחתון עולות למעלה, לג״ע העליון (כנ״ל תרומה אות קע\"ו) וכשיוצא השבת, עולות אלו הנשמות ששרו על ישראל, דהיינו נשמות היתרות, ויורדות אלו הנשמות של הצדיקים שעלו לג״ע העליון. שחוזרות לג״ע התחתון."],[6,"כיון דסלקין כלהו וכו׳:","כיון שעלו כל הנשמות ששרו על ישראל, עולות ועומדות בצורה לפני המלך הקדוש, והקב״ה שואל את כולן, איזה חידוש היה לכן, בעולם ההוא, בתורה. אשרי היא, מי שאומרת לפניו חידושי תורה, כמה שמחה עושה הקב״ה, מקבץ הפמליא שלו, דהיינו הנשמות העליונות, והמלאכים, ואומר, שמעו חידושי תורה שאומרת נשמה הזו של פלוני. וכולם מעמידים דבר ההוא בב' הישיבות. דהיינו במתיבתא דקב״ה ובמתיבתא דמטטרו״ן. הם למטה, והקב״ה למעלה חותם על דבר ההוא."],[7,"ת״ח כד מלה וכו׳:","בוא וראה, בשנתחדש דבר בתורה, והנשמה היתירה שירדה בשבת נתעסקה באלו חידושי דברי תורה, ועולה למעלה, אחר השבת, כל פמליא של מעלה מקשיבים לדבר ההוא, וחיות הקודש מתגדלות בכנפיהן, ומתלבשות בכנפיהן. וכששואל אותן, דהיינו את הנשמות, על חידושי תורה, ואינן משיבות, ושותקות, אז חיות הקדש, מה כתוב בהן, בעמדם תרפינה כנפיהם. בעמדם פירושו בשתיקתם, כש״א, כי \u0003עמדו\u0004 ולא ענו עוד. וכן, וכפתחו \u0003עמדו\u0004 כל העם. שפירושו שתקו."],[8,"ואי תימא שתיקה וכו׳:","ואם תאמר, שתיקה למה קורא עמידה. ומשיב, אלא בדבור יש ז׳ אברים המתגעגעים עמו, בשעת הדיבור, שהם, לב, ריאה, קנה, לשון, שנים, שפתים, בשר. ובשתיקה הם עומדים במעמדם בלי נענוע, וע״כ קורא לשתיקה עמידה."],[9,"דהא רב המנונא וכו׳:","(חסר ההתחלה) כי רב המנונא הזקן אמר, ישלח עזרך מקדש וגו', \u0003מקדש\u0004 זהו קדוש ידים, דהיינו מים ראשונים לפני הסעודה. \u0003ומציון יסעדך,\u0004 זהו, המוציא, שהוא סועד לבו של אדם. \u0003יזכור כל מנחותיך,\u0004 הנה \u0003כל\u0004 בא לרבות דבר אחר, שזהו נטילת ידים האחרונה. דהיינו מים אחרונים. \u0003ועולתך ידשנה סלה,\u0004 זהו ברכת המזון בזמון. ואם אתה עושה כן, \u0003יתן לך כלבבך וכל עצתך ימלא.\u0004 ובשבת המלה \u0003מקדש\u0004 רומזת על קדוש הגדול בבוקר, ועל דבר זה נתעטרו הצדיקים בגן עדן משבת לשבת אחר. (חסר הסיום)."]],[[0,"","הַשֵּׁמוֹת, אֶלָּא כֻּלָּם אוֹתִיּוֹת, לֹא שׁוֹכְכִים לְעוֹלָמִים, בּוֹלְטִים וְנוֹצְצִים הַחוּצָה, וְעוֹלִים וְיוֹרְדִים. אֵין מִי שֶׁיָּכוֹל לַעֲמֹד בָּהֶם, פְּרָט לַמָּשִׁיחַ בְּטֹרַח גָּדוֹל. זֶה גָנוּז, לְאַחַר שֶׁעוֹמֵד שְׁעָתַיִם וְעֶשְׂרִים וּשְׁנַיִם רְגָעִים, וְהַשֵּׁם הֶחָקוּק שֶׁל ע\"ב אוֹתִיּוֹת יוֹצֵא וְעוֹמֵד וְתָלוּי בָּאֲוִיר שָׁעָה וָחֵצִי. כָּל הַשֵּׁמוֹת הָאֵלֶּה לֹא יוֹצְאִים וְלֹא נִרְאִים, אֶלָּא פַּעַם אַחַת בַּיּוֹם, אֲבָל אוֹתָן א\"ב נִרְאוֹת פּוֹרְחוֹת בָּאֲוִיר, וּמְצָרְפוֹת אֵלֶּה בְאֵלֶּה שָׁלֹשׁ פְּעָמִים בְּיוֹם."],[1,"","כְּשֶׁפּוֹרְחוֹת אוֹתִיּוֹת הָאָלֶף בֵּית, אֵלֶּה פּוֹרְחוֹת מִכָּאן וְאֵלֶּה מִכָּאן, וּמִצְטָרְפוֹת כֻּלָּן. כְּשֶׁיּוֹרֵד שָׁם רֹאשׁ הַיְשִׁיבָה, מַתְחִיל, מָשִׁיחַ רוֹאֶה בְצֵרוּף א\"ב אוֹתִיּוֹת כְּמוֹ שֶׁרָאָה דָנִיֵּאל, שֶׁהֵם: ממתוס ננקפי אאלרן (מנא מנא תקל ופרסין (דניאל ה, כה))."],[2,"","כָּל עֶרֶב שַׁבָּת, כְּשֶׁמְּקַדְּשִׁים יִשְׂרָאֵל אֶת הַיּוֹם לְמַטָּה, כָּרוֹז מַכְרִיז לְאַרְבָּעָה צִדְדֵי הָעוֹלָם: הִתְכַּנְּסוּ מֶרְכָּבוֹת קְדוֹשׁוֹת! הַתְקִינוּ כִסְאוֹת (קדושים) מִי רָאָה חֶדְוָה בִּשְׁלֹשׁ מֵאוֹת וְתִשְׁעִים רְקִיעִים? כַּמָּה מְמֻנִּים, כַּמָּה שַׁלִּיטִים מִתְכַּנְּסִים לִמְקוֹמוֹתֵיהֶם. כֵּיוָן שֶׁיִּשְׂרָאֵל לְמַטָּה מְקַדְּשִׁים (להקדוש ברוך הוא), אָז מִתְעוֹרֵר עֵץ הַחַיִּים, וּמַקִּישׁ בְּאוֹתָם הֶעָלִים שֶׁלּוֹ רוּחַ נְשִׁיבוּת אַחַת מִתּוֹךְ עוֹלָם הַבָּא, וְאוֹתָם עַנְפֵי הָאִילָן מִתְנַעְנְעִים, וְעוֹלִים רֵיחוֹת שֶׁל הָעוֹלָם הַבָּא."],[3,"","אוֹתוֹ עֵץ הַחַיִּים מִתְעוֹרֵר, וּמוֹצִיא נְשָׁמוֹת קְדוֹשׁוֹת, וּפוֹרֵשׂ עַל הָעוֹלָם. וְעִם כָּל זֶה נְשָׁמוֹת יוֹצְאוֹת וּנְשָׁמוֹת נִכְנָסוֹת. אֵלֶּה מְעוֹרְרִים אֵלֶּה, אֵלֶּה יוֹצְאִים וְאֵלֶּה נִכְנָסִים, וְעֵץ הַחַיִּים בְּחֶדְוָה."],[4,"","וְאָז יִשְׂרָאֵל כֻּלָּם מִתְעַטְּרִים בָּעֲטָרוֹת שֶׁל אוֹתָן נְשָׁמוֹת קְדוֹשׁוֹת, כֻּלָּם בְּחֶדְוָה בִּמְנוּחָה. וְכָל הַשַּׁבָּת יֵשׁ לָהֶם אוֹתָהּ חֶדְוָה וְאוֹתָהּ מְנוּחָה, וְכָל הַצַּדִּיקִים שֶׁבַּגָּן, כֻּלָּם עוֹלִים וּמִתְעַנְּגִים בְּעֹנֶג עֶלְיוֹן שֶׁל הָעוֹלָם הַבָּא. כֵּיוָן שֶׁיּוֹצֵאת הַשַּׁבָּת, כָּל הַנְּשָׁמוֹת פּוֹרְחוֹת וְעוֹלוֹת."],[5,"","בֹּא וּרְאֵה, כְּשֶׁנִּכְנֶסֶת שַׁבָּת, נְשָׁמוֹת יוֹרְדוֹת לִשְׁרוֹת עַל הָעָם הַקָּדוֹשׁ, וְנִשְׁמוֹת הַצַּדִּיקִים עוֹלוֹת לְמַעְלָה. כְּשֶׁיּוֹצֵאת הַשַּׁבָּת, הַנְּשָׁמוֹת עוֹלוֹת, אוֹתָן שֶׁשָּׁרוּ עַל יִשְׂרָאֵל. וּנְשָׁמוֹת יוֹרְדוֹת, אוֹתָן נִשְׁמוֹת הַצַּדִּיקִים."],[6,"","כֵּיוָן שֶׁעוֹלוֹת כָּל הַנְּשָׁמוֹת שֶׁשָּׁרוּ עַל יִשְׂרָאֵל, עוֹלוֹת וְעוֹמְדוֹת בִּדְמוּת לִפְנֵי הַמֶּלֶךְ הַקָּדוֹשׁ, וְהַקָּדוֹשׁ בָּרוּךְ הוּא שׁוֹאֵל אֶת כֻּלָּם: אֵיזֶה חִדּוּשׁ הָיָה לָכֶם בְּאוֹתוֹ עוֹלָם בַּתּוֹרָה? אַשְׁרֵי מִי שֶׁאוֹמֵר לְפָנָיו חִדּוּשׁ עַל הַתּוֹרָה. כַּמָּה חֶדְוָה עוֹשֶׂה הַקָּדוֹשׁ בָּרוּךְ הוּא. מְכַנֵּס פָּמַלְיָה שֶׁלּוֹ וְאוֹמֵר: שִׁמְעוּ חִדּוּשׁ תּוֹרָה שֶׁאוֹמֶרֶת נִשְׁמַת פְּלוֹנִי זֶה. וְכֻלָּם מַעֲמִידִים אוֹתוֹ דָבָר בִּשְׁתֵּי יְשִׁיבוֹת. הֵם לְמַטָּה, וְהַקָּדוֹשׁ בָּרוּךְ הוּא לְמַעְלָה חוֹתֵם לְאוֹתוֹ דָבָר."],[7,"","בֹּא וּרְאֵה, כְּשֶׁדָּבָר מִתְחַדֵּשׁ בַּתּוֹרָה וּנְשָׁמָה שֶׁיּוֹרֶדֶת בְּשַׁבָּת הִתְעַסְּקָה בְּאוֹתָם דְּבָרִים חֲדָשִׁים וְעוֹלָה לְמַעְלָה, כָּל הַפָּמַלְיָה שֶׁל מַעְלָה מַקְשִׁיבָה לְאוֹתוֹ דָבָר, וְחַיּוֹת הַקֹּדֶשׁ מִתְרַבִּים בִּכְנָפַיִם וּמִתְלַבְּשִׁים בִּכְנָפַיִם. וּכְשֶׁשּׁוֹאֵל אוֹתָם הַקָּדוֹשׁ בָּרוּךְ הוּא וְלֹא מְשִׁיבִין, וְשׁוֹתְקִין, אָז חַיּוֹת הַקֹּדֶשׁ מַה כָּתוּב? (יחזקאל א) בְּעָמְדָם תְּרַפֶּינָה כַנְפֵיהֶן, כְּמוֹ שֶׁנֶּאֱמַר (איוב לב) כִּי עָמְדוּ לֹא עָנוּ עוֹד. (נחמיה ח) וּכְפִתְחוֹ עָמְדוּ כָּל הָעָם."],[8,"","וְאִם תֹּאמַר, לָמָּה לַשְּׁתִיקָה קָרְאוּ עֲמִידָה? אֶלָּא בַּדִּבּוּר יֵשׁ שִׁבְעָה אֵיבָרִים שֶׁמִּתְנַעְנְעִים יַחַד אִתּוֹ: לֵב, רֵאָה, קָנֶה, לָשׁוֹן, שִׁנַּיִם, שְׂפָתַיִם, בָּשָׂר. וּבַשְּׁתִיקָה עוֹמְדִים בְּעָמְדָם לְלֹא נִעְנוּעַ, וְעַל זֶה קוֹרְאִים לַשְּׁתִיקָה עֲמִידָה."],[9,"","שֶׁהֲרֵי רַב הַמְנוּנָא סָבָא אָמַר, (תהלים כ) יִשְׁלַח עֶזְרְךְ מִקֹּדֶשׁ וְגוֹ'. מִקֹּדֶשׁ - זֶה קִדּוּשׁ יָדַיִם. וּמִצִּיּוֹן יִסְעָדֶךָּ - זֶה הַמּוֹצִיא, שֶׁהוּא סוֹעֵד לֵב הָאָדָם. יִזְכֹּר כָּל מִנְחֹתֶיךְ, כָּל - לְרַבּוֹת דָּבָר אַחֵר, זוֹ נְטִילַת יָדַיִם אַחֲרוֹנָה. וְעוֹלָתְךְ יְדַשְּׁנֶה סֶלָה - זוֹ בִּרְכַּת הַמָּזוֹן בְּזִמּוּן. אִם אַתָּה עוֹשֶׂה כֵן, יִתֶּן לְךְ כִלְבָבֶךְ וְכָל עֲצָתְךְ יְמַלֵּא. וּבְשַׁבָּת מְקַדֵּשׁ, זֶה קִדּוּשׁ הַגָּדוֹל. וְעַל דָּבָר זֶה הִתְעַטְּרוּ הַצַּדִּיקִים בְּגַן עֵדֶן מִשַּׁבָּת לְשַׁבָּת אַחֶרֶת."]]],[["תּוּ פָּתַח וְאָמַר, (ישעיהו מ׳:ט׳) עַל הַר גָּבוֹהַּ עֲלִי לָךְ מְבַשֶּׂרֶת צִיּוֹן וְגוֹ'. עַל הַר גָּבוֹהַּ, הַאי וַדַּאי הַר הָעֲבָרִים, אֲתָר דְּמֹשֶׁה אִתְקְבַר. וְהָא אוּקְמוּהָ, דִּשְׁכִינְתָּא תְּסַלֵּק לְתַמָן, וּתְבַשֵּׂר עָלְמָא. אֲבָל כֹּלָּא אִיהוּ, מְבַשֶּׂרֶת צִיּוֹן, דָּא אִיהִי חֶפְצִי בָּהּ, אִתְּתָא דְּנָתָן בַּר דָּוִד. אִימָּא אִיהִי דִּמְשִׁיחָא, מְנַחֵם בַּ\"ר עַמִּיאֵ\"ל, וְאִיהִי תִּיפּוּק וּתְבַשֵּׂר, וְאִיהִי בִּכְלָלָא דִּמְבַשֶּׂרֶת צִיּוֹן.","קָלָא יִשְׁתְּמַע בְּעָלְמָא, וּתְרֵין מַלְכִין יִתְּעֲרוּן בְּעָלְמָא, לְאַגָּחָא קְרָבָא, וְיִפּוּק שְׁמָא קַדִּישָׁא עַל עָלְמָא. מַה תְּבַשֵּׂר וְתֵימָא. (ישעיהו מ׳:י׳) הִנֵּה יְיָ אֱלֹהִים בְּחָזָק יָבֹא וּזְרוֹעוֹ מוֹשְׁלָה לּוֹ. הִנֵּה שְׂכָרוֹ אִתּוֹ וּפְעוּלָּתוֹ לְפָנָיו. הִנֵּה שְׂכָרוֹ אִתּוֹ, דְקוּדְשָׁא בְּרִיךְ הוּא כָּרִיז בְּכָל פָּמַלְיָא דִּלְעֵילָּא, וְיֵימָא לוֹן, אִתְכְּנָשׁוּ וְדָאִינוּ דִּינָא. מַאן דְּמָסַר נִשְׁמָתֵיהּ עַל קְדוּשַׁת שְׁמִי, אַגְרֵיהּ מַאי הוּא. וְאִינּוּן יֵימְרוּן כַּךְ וְכַךְ. מַאן דְּסָבִיל כַּמָה חֵרוּפִין וְגִדּוּפִין בְּכָל יוֹמָא עָלַי, מַהוּ אַגְרֵיהּ. אִינּוּן אַמְרֵי כַּךְ. מַאן דְּאִתְעֲנָשׁ בְּכָל יוֹמָא עָלַי, מַהוּ אַגְרֵיהּ. אִינּוּן אַמְרֵי כַּךְ. הֲדָא הוּא דִכְתִיב, הִנֵּה שְׂכָרוֹ אִתּוֹ וּפְעוּלָּתוֹ לְפָנָיו.","מַהוּ וּפְעוּלָּתוֹ. אֶלָּא כְּמָה דִּכְתִּיב, (תהילים ל״א:כ׳) מָה רַב טוּבְךָ וְגוֹ'. פָּעַלְתָּ לַחוֹסִים בָּךְ. דָּא הוּא פְּעוּלָּתוֹ. נֶגֶד בְּנֵי אָדָם מַהוּ. אֶלָּא נֶגֶד עוֹבְדֵי כּוֹכָבִים וּמַזָּלוֹת. אֲשֶׁר צָפַנְתָּ לִּירֵאֶיךָ, מַהוּ אֲשֶׁר צָפַנְתָּ. וְכִי מַאן יִגְזוֹל וְיִטּוֹל מִן יְדוֹי, מַה דְּהוּא בָּעֵי לְמֵיהַב, דִּכְתִּיב צָפַנְתָּ.","אֶלָּא פּוּק וְחָמֵי עוֹבָדִין דְּרַחֲמָנוּ דְּעָבַד קוּדְשָׁא בְּרִיךְ הוּא, בְּמַה דְּאִיהוּ מָחֵי, בֵּיהּ יָהִיב אַסְוָותָא. בְּמַה מָחֵי בִּשְׂמָאלָא, בִּימִינָא קָרִיב, וּבִשְׂמָאלָא מָחֵי. בְּמָה דְּמָחֵי, בֵּיהּ יָהִיב אַסְוָותָא לְעוֹלָם, כְּתִיב (ירמיהו א׳:י״ד) מִצָּפוֹן תִּפָּתַח הָרָעָה, וּבְצָפוֹן מָחֵי. דְּמִתַּמָּן נָפְקֵי כָּל דִּינִין וְכָל גְּזִירֵי קַשְׁיָין. וּבֵיהּ שָׁרֵי כָּל אֲגָר טַב, וְכָל טִיבוּ, דְּזַמִּין קוּדְשָׁא בְּרִיךְ הוּא לְמֵיהַב לְיִשְׂרָאֵל. לְזִמְנָא דְּאָתֵי, קָרֵי קוּדְשָׁא בְּרִיךְ הוּא לַצָּפוֹן, וְיֵימָּא לֵיהּ, בָּךְ יָהַבִית כָּל טִיבוּ, וְכָל אֲגָר טוֹב לִבַנַי, דְּסַבְלוּ כַּמָה בִּישִׁין בְּהַאי עָלְמָא, עַל קְדוּשַׁת שְׁמִי. הַב אַגְרִין טָבִין דְּיָהֲבִית בָּךְ.","הֲדָא הוּא דִכְתִיב, (ישעיהו מ״ג:ו׳) אוֹמַר לַצָּפוֹן תֵּנִי וּלְתֵימָן אַל תִּכְלָאִי וְגוֹ'. וְכִי אָרְחָא הָכִי הוּא דְּדָרוֹם, לְמִמְנַע בִּרְכָאן, וְהָא כָּל בִּרְכָאן מִסִּטְרָא דְּדָרוֹם, וְכָל טָבִין דְּעָלְמָא מִדָּרוֹם נָפְקֵי, וְאִיהוּ אָמַר לְתֵימָן אַל תִּכְלָאִי.","אֶלָּא בְּהַהִיא שַׁעֲתָא, יִתְּעַר קוּדְשָׁא בְּרִיךְ הוּא לְאַבְרָהָם, וְיֵימָא לֵיהּ קוּם, דְּהָא מָטָא זִמְנָא דַּאֲנָא פָּרִיק לִבְנַךְ, לְמֵיהַב לוֹן אֲגָר טַב, עַל כָּל מַה דְּסַבְלוּ בְּגָלוּתָא. וּמִגּוֹ דְּאַבְרָהָם הֲוָה בִּזְבִינוּ דִּלְהוֹן, דִּכְתִּיב, (דברים ל״ב:ל׳) אִם לֹא כִּי צוּרָם מְכָרָם, דָּא אַבְרָהָם. הֲוָה לֵיהּ כְּמַאן דְּלָא טַב בְּעֵינוֹי, וְאַחְמֵי גַּרְמֵיהּ, כְּמַאן דְּבָעֵי דְּיִלְקוּן עַל חוֹבֵיהוֹן יַתִּיר, וְיֵימָּא גְּבוּ מֵחוֹבֵיהוֹן, גְּבוּ מֵחֲטָאֵיהוֹן. אָמַר לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא לְאַבְרָהָם, יְדַעְנָא כֹּלָּא אִיהוּ מַה דְּאַמְרַת לְאַנְפִּין. אֲנָא אוּף הָכִי לְאַנְפִּין. אַל תִּכְלָאִי, אֲנָא בָּעֵי לְפַיְּיסָא לָךְ עַל בָּנֶךָ. לָא תִּמְנָע טִיבוּ מִנְּהוֹן, לָא תִּמְנָע אֲגָר טַב מִנְּהוֹן, כַּמָה וְכַמָּה סַבְלוּ עַל חוֹבֵיהוֹן, וּבְגִינֵי כַּךְ אוֹמַר לַצָּפוֹן תֵּנִי. וְהַיְינוּ אֲשֶׁר צָפַנְתָּ, וְדָא הוּא מִלָּה (ס\"א דתהא) דְּהַהִיא מְבַשֶּׂרֶת.","וְתוּ תְּבַשֵּׂר זִמְנָא תִּנְיָינָא, בְּשַׁעֲתָא דִּשְׁכִינְתָּא תְּסַלֵּק עַל הַהוּא טוּרָא עִלָּאָה, וְתֵהַךְ וּתְבַשֵּׂר לַאֲבָהָן, מִיַּד תֵּהַךְ לִיְרוּשָׁלַ ם, וְתֶחמֵי לָהּ בְּחָרְבָּנָא. תֵּיעוּל לְצִיּוֹן, וְתַמָּן תְּקַרְקֵר קִירָא כְּמִלְּקַדְּמִין, עַל אֲתָר בֵּי מוֹתְבָה, וְעַל יְקָרָא דִּילָהּ בְּהַהוּא אֲתָר. וְתַמָּן אוֹמִיאַת, דְּלָא תִּיטוֹל מִתַּמָּן, וְלָא תִּפּוּק, עַד דְקוּדְשָׁא בְּרִיךְ הוּא יִפְרוּק לִבְנָהָא, וְדָא חֶפְצִי בָּהּ. תְּבַשֵּׂר כְּמִלְּקַדְּמִין וְאַמְרַת, (ישעיהו י״ב:ו׳) צַהֲלִי וָרֹנִּי יוֹשֶׁבֶת צִיּוֹן כִּי גָּדוֹל בְּקִרְבֵּךְ וְגוֹ'. מַאי גָּדוֹל בְּקִרְבֵּךְ. דָּא קוּדְשָׁא בְּרִיךְ הוּא דְּאִיהוּ אָתֵי לְגַבָּהּ, לְאַקָּמָא לָהּ מֵעַפְרָא, וְיֵימָא לָהּ (ישעיהו נ״ב:ב׳) הִתְנַעֲרִי מֵעָפָר קוּמִי שְׁבִי יְרוּשָׁלַם. יְרוּשָׁלַם אִיהִי, וִיְרוּשָׁלַם שְׁמָהּ וַדַּאי.","וּבְדָא אוּף הָכִי, כַּמָה חֵדּוּ עַל חֵדּוּ הֲוִי לְצַדִּיקַיָּיא בְּגַן עֵדֶן. וּבְגִין כָּךְ זַכָּאָה אִיהוּ, מַאן דְּנִשְׁמָתֵיהּ בְּשַׁבָּת אַסְהִידַת קָמֵי מַלְכָּא, עַל חִדּוּשָׁא דְּאוֹרַיְיתָא, דְקוּדְשָׁא בְּרִיךְ הוּא, וְכָל פָּמַלְיָא דִּילֵיהּ, וְכָל אִינּוּן נִשְׁמָתִין דְּצַדִּיקַיָּיא דַּהֲווֹ בְּגַן עֵדֶן, כֻּלְּהוּ מִתְעַטְּרִין בְּהַהוּא מִלָּה."],[[0,"תו פתח ואמר וכו׳:","עוד פתח ואמר, על הר גבוה עלי לך מבשרת ציון וגו׳. \u0003על הר גבוה,\u0004 היינו ודאי הר העברים, המקום שמשה נקבר בו. והרי העמדנו, שהשכינה תעלה שמה, ותבשר אל העולם. אבל הכל היא, כלומר שכל הפשטים כוללת המלה מבשרת ציון, \u0003מבשרת ציון\u0004 זו היא, חפצי בה, שהיא אשת נתן בן דוד, שהיא אמו של משיח, מנחם בן עמיאל. שהוא יצא מחלציה, והיא תצא ותבשר על הגאולה, והיא בכלל מבשרת ציון."],[1,"קלא ישתמע בעלמא וכו׳:","קול ישמע בעולם, ושני מלכים יתעוררו בעולם לערוך מלחמה, ואז יצא השם הקדוש למלוך על העולם. מה תבשר ותאמר. היינו, הנה ה׳ אלקים בחזק יבא וזרועו מושלה לו. הנה שכרו אתו ופעולתו לפניו. \u0003הנה שכרו אתו,\u0004 היינו שהקב\"ה יכריז בכל הפמליא של מעלה, ויאמר להם התאספו ודונו דין. מי שמסר נשמתו על קדושת שמי מהו שכרו. והם יאמרו כך וכך. מי שסבל כמה חרופים וגדופים עלי בכל יום, מהו שכרו. והם יאמרו כך. מי שנענש בכל יום עלי, מהו שכרו. הם יאמרו כך. ז\"ש הנה שכרו אתו ופעולתו לפניו."],[2,"מהו ופעולתו וכו׳:","שואל, מהו ופעולתו. ומשיב, אלא כמו שכתוב, מה רב טובך אשר צפנת ליראיך \u0003פעלת\u0004 לחוסים בך. זו היא פעולתו. \u0003נגד בני אדם\u0004 מהו. ומשיב, אלא כנגד עכו״ם, שבולט יראו השכר הטוב של הצדיקים. \u0003אשר צפנת ליראיך,\u0004 מהו, אשר צפנת. וכי מי יגזול ויטול מידיו מה שהוא רוצה לתת, שכתוב צפנת. ולמה לו לצפון."],[3,"אלא פוק וחמי וכו׳:","ומשיב, אלא צא וראה פעולת הרחמים שעושה הקב\"ה, כי במה שהוא מכה, בו נותן הרפואה. במה הוא מכה. בשמאל, כי בימין הוא מקרב ובשמאל מכה, הנה במה שהוא מכה בו נותן רפואה לעולם. כי כתוב, מצפון תפתח הרעה, שהוא השמאל, שבצפון הוא מכה, כי משם יוצאים כל הדינים וכל גזירות הקשות. ובו שורה כל שכר טוב וכל חסד שעתיד הקב״ה לתת לישראל. כי לעתיד לבא קורא הקב״ה לצפון, שהוא השמאל, ויאמר לו בך נתתי כל טוב וכל שכר טוב לבני שסבלו כמה רעות בעולם הזה על קדושת שמי. תן כל שכר הטוב שנתתי בך."],[4,"הה״ד אומר לצפון וגו׳:","ז״ש, אומר לצפון תני ולתימן אל תכלאי וגו'. שואל, וכי כך הוא הדרך של הדרום, שהוא ימין, למנוע ברכות, והרי כל הברכות הם מצד דרום, וכל טוב שבעולם יוצא מדדום, והוא אומר לתימן אל תכלאי."],[5,"אלא בההיא שעתא וכו׳:","ומשיב, אלא בשעה ההיא יעורר הקב״ה את אברהם, ויאמר לו, קום, כי הגיע הזמן שאני גואל את בניך ולתת להם שכר טוב על כל מה שסבלו בגלות. ומתוך שאברהם היה במכירה שלהם לגלות, שכתוב, אם לא כי צורם מכרם, שזהו אברהם. ע״כ היה לו כמי שאינו טוב בעיניו, והראה את עצמו כמי שרוצה שיוכו יותר על עונותיהם, ויאמר, תהיה נפרע מעונותיהם, תהיה נפרע מחטאיהם. א\"ל הקב״ה לאברהם אני יודע שהכל מה שאמרת הוא רק לפנים, ולא מאמיתיות הלב, אני גם כן אנהג עמך לפנים, ואומר לך, \u0003אל תכלאי,\u0004 אני רוצה לרצות אותך בשביל בניך, אל תמנע חסד מהם, אל תמנע שכר טוב מהם, כמה וכמה סבלו על עונותיהם. ומשום זה, \u0003אומר לצפון תני,\u0004 שהצפון יתן שכר הטוב והכל, והדרום אל ימנע, והיינו \u0003אשר צפנת\u0004 שהיא לשון צפון, שהוא הנותן הכל, וזה הוא הדבר של אותה מבשרת. דהיינו מ״ש לעיל על הר גבוה עלי לך מבשרת ציון וגו'."],[5,"","ביאור המאמר. כבר ידעת שאין ג״ר אלא ע״י הארת החכמה שבשמאל, והיינו רק על ידי התכללות הימין עם השמאל ביחד, שאז מתלבשת החכמה בחסדים ומאירים הג״ר. וכל השכר וכל הטוב שלעתיד לבא, הוא רק בהארת הג\"ר. אמנם אם ע\"י חטאי התחתונים מתגבר השמאל על הימין ורוצה לשלוט בלבדו, אז נעשה מחלוקת בין ימין לשמאל, וקו הימין מסיר החסדים שלו מקו השמאל, שאז השמאל מתכבה, כי אין החכמה יכולה להאיר בלי חסדים, ומתגלים דינים הקשים שבו, וכן הימין נשאר בו״ק בלי ג״ר, כי אין ג״ר אלא מהארת החכמה שבשמאל. ומחמת זה נחרב בית המקדש וישראל נגלו בין האומות."],[5,"","ונודע מה שאמרו חז״ל על הכתוב אני ה׳ בעתה אחישנה אם זכו אחישנה, אם לא זכו בעתה (סנהדרין צח.) ויש להבין, איך אפשר זה, שיגאלו ישראל אפילו אם לא זכו, ועוד עומדים במרדם. והענין הוא, כי הגלות היה מחמת שע״י חטאיהם גרמו שיתגבר השמאל על הימין וישלוט לבדו, שאז מסיר הימין החסדים ממנו וכו' כנ״ל. וע״כ כשישראל עושים תשובה, ומתדבקים בהקב״ה שהוא קו האמצעי, אז חוזר קו האמצעי, ומיחד הימין עם השמאל ומקיים אורות שניהם והחכמה מתלבשת בחסדים, ומתגלים הג״ר, שישראל נגאלים עם הארתם, ומקבלים כל שכרם הטוב. שז״ס אם זכו אחישנה. שעל זה אין זמן קצוב. אלא מתי שעושים תשובה נגאלים. אמנם אם אינם עושים תשובה, יש זמן קצוב המביא את הגאולה אע״פ שלא עשו תשובה. והוא, אחר שאפשר לקבץ כל הדינים הקשים שסבלו ישראל בזמן הגלות, לשיעור שלם, דהיינו באפן שיספיקו, שישראל יפחדו ולא יחטאו עוד, להגביר את השמאל על הימין, כמו שעשו בעת החרבן, אז הם ראוים לגאולה אפילו בלי תשובה. כי גם בלי תשובה מובטחים שלא ישובו לכסלה עוד, דהיינו מחמת רוב הדינים הקשים שסבלו. וז\"ס, \u0003לא זכו בעתו.\u0004 שזה נעשה מאליו עם גילוי הדינים שבגלות לשיעור מספיק, ואין צריכים כלל להתעוררות ישראל לתשובה."],[5,"","וזה אמרו (באות ש״א) \u0003ובצפון מחי דמתמן נפקי כל דינין וכל גזירי קשיין,\u0004 כי כל הגלות, ודינים הקשים שבגלות, באים משליטת שמאל בלי ימין, שה״ס צד צפון. כמו שנתבאר. \u0003וביה שרי כל אגר טב וכל טיבו דזמין קב״ה למיהב לישראל,\u0004 דהיינו שעל ידי השמאל מתגלות הג״ר, שמשם כל השכר וכל הטוב העתיד לבא לישראל. וז\"ש (באות ש״ג) \u0003בההיא שעתא,\u0004 דהיינו בזמן הגאולה, \u0003יתער קב״ה לאברהם,\u0004 שה״ס קו ימין, וסוד דרום, \u0003ויימא ליה קום, דהא מטא זמנא דאנא פריק\u0004 וכו' דהיינו, אע״פ שלא זכו, שלא עשו תשובה להדבק בקו האמצעי, כבר, \u0003מטא זמנא דאנא פריק,\u0004 שהגיע הזמן, לגאלם אפילו בלא תשובה. \u0003ומגו דאברהם הוה בזבינו דלהון,\u0004 כי כל הגלות היה, מחמת שקו הימין הסיר החסדים שלו מן קו השמאל, שע״כ נסתלקו הג״ר ונגלו הדינים של הגלות כנ״ל. \u0003הוה ליה כמאן דלא טב בעינוי\u0004 וכו', שהיה בשורת הגאולה לא טוב בעיניו, שהרי עוד לא עשו תשובה מחטאם, ועלולים להגביר שוב השמאל על הימין, וע״כ, \u0003ויימא גבו מחוביהון גבו מחטאיהון,\u0004 דהיינו שיכבד עליהם הגלות עד שיעשו תשובה, ואז יתיחדו הימין עם השמאל כנ״ל. \u0003א׳׳ל קב\"ה לאברהם ידענא כלא איהו מה דאמרת, לאנפין,\u0004 שהקב״ה העירו, שאומר כל זה לא מלב שלם, שהרי גם הקו ימין חסר ג״ר בימי הגלות, וגם הוא משתוקק להתיחד עם השמאל ולגלות הג״ר. \u0003אנא אוף הכי לאנפין,\u0004 כלומר, שאשיב לך על דבריך, ולא לפי לבך, \u0003אנא בעי לפייסא לך\u0004 כי הקב״ה, שה״ס קו האמצעי בא לעשות שלום בין ימין לשמאל, ולפייס הימין שלא יפחד עוד מהתגברות השמאל, \u0003לא תמנע טיבו מנהון,\u0004 שאל תמנע מהם החסד, דהיינו שאל תסיר עוד החסד מן השמאל, \u0003ולא תמנע אגר טב מנהון,\u0004 דהיינו, שאל יעכב הארת הג״ר, עם הסרת חסדו, שמן הג״ר הוא כל אגר טב כנ״ל. וכל זה הוא, מטעם שכבר הגיע הזמן, לגאלם אפילו בלי תשובה, כנ״ל, וז״ש, \u0003כמה וכמה סבלו על חוביהון,\u0004 דהיינו שכבר קבלו עונשים קשים על עונותיהם בשיעור המספיק שלא ישובו לכסלה עוד. וע״כ הגיע קצם. \u0003ובגין כך, אומר לצפון תני,\u0004 שיתן הארת חכמה שלו ויתגלה הג״ר. \u0003ולתימן אל תכלאי,\u0004 ולדרום, שהוא אברהם, וקו הימין, אומר, שלא יעכב זה, דהיינו שלא ימנע ממנו החסדים, אלא שיתיחד עמו. כנ״ל. \u0003והיינו אשר צפנת,\u0004 מטעם שכל שכר הטוב המקווה הוא ב \u0003צפון.\u0004 וע״כ אומר מה רב טובך אשר \u0003צפנת,\u0004 כלומר הגנוז ברוח צפון."],[5,"","וז״ש, \u0003ודא הוא מלה דההיא מבשרת,\u0004 שאומר, על הר גבוה עלי לך מבשרת וגו' הנה שכרו אתו ופעולתו לפניו (כנ״ל באות רצ״ט), כלומר, שמתוך \u0003שפעולתו לפניו,\u0004 דהיינו כל העונשים שסבלו ישראל בגלות עד שנתקבץ לשיעור המספיק לגאלם כנ״ל, ע״כ \u0003שכרו אתו,\u0004 שיוכל ליחד הימין עם השמאל ולגלות הג״ר, שמשם כל שכרו הטוב וגאולת ישראל, כי עתה אין עוד פחד שישיבו לכסלה. כנ״ל. וז״ש (באות רצ״ט) \u0003דקב\"ה כריז\u0004 וכו', \u0003מאן דמסר נשמתיה\u0004 וכו', \u0003מאן דסביל כמה חרופין\u0004 וכו' \u0003מאן דאתענש בכל יומא\u0004 וכו', דהיינו שקבץ כל העונשים והדינים הקשים שסבלו ישראל בגלות והוכיח להם שכבר קבלו שיעור המספיק לגאלם. \u0003הה״ד הנה שכרו אתו ופעולתו לפניו.\u0004 שמתוך שפעולתו לפניו שהם העונשים ע״כ שכרו אתו, כי מתגלים בבת אחת. כמבואר."],[6,"ותו תבשר, זמנא וכו':","ועוד היא \u0003תבשר\u0004 פעם שניה, בשעה שהשכינה תעלה על הר גבוה ההוא, ותלך ותבשר אל האבות, מיד השכינה תלך לירושלים, ותראה אותה בחורבנה. תכנס לציון, ושם תקרקר קיר כבתחילה, על מקום בית ישיבתה ועל יקר שלה שהיה לה באותו מקום. ושם נשבעת, שלא תלך משם, ולא תצא, עד שהקב״ה יגאל את בניה. וחפצי בה זו (הנ״ל באות רצ״ח) תבשר כבתחילה, ואמרת, צהלי ורני יושבת ציון כי גדול בקרבך וגו'. מהו \u0003גדול בקרבך,\u0004 זהו הקב״ה, שהוא בא אליה להקימה מעפר, ויאמר לה התנערי מעפר קומי שבי ירושלים. השכינה היא ירושלים, וירושלים הוא שמה ודאי."],[7,"ובדא אוף הכי וכו':","(זה סיום המאמר שלעיל מאות ר״צ מד אות רצ״ו) ובזה גם כן, כמה שמחה על שמחה יש לצדיקים בגן עדן. ומשום זה, אשרי הוא, מי שנשמתו מעידה בשבת לפני המלך על חידושי תורה שאמרה שהקב״ה וכל הפמליא שלו, וכל אלו נשמות הצדיקים שהם בגן עדן, כולם מתעטרים בדבר חידוש ההוא."]],[[0,"","עוֹד פָּתַח וְאָמַר, (ישעיה מ) עַל הַר גָּבֹהַּ עֲלִי לָךְ מְבַשֶּׂרֶת צִיּוֹן וְגוֹ'. עַל הַר גָּבהַּ - זֶה וַדַּאי הַר הָעֲבָרִים, מָקוֹם שֶׁמֹּשֶׁה נִקְבַּר בּוֹ. וַהֲרֵי פֵּרְשׁוּהָ, שֶׁשְּׁכִינָה תַעֲלֶה לְשָׁם וּתְבַשֵּׂר לָעוֹלָם. אֲבָל הַכֹּל הוּא מְבַשֶּׂרֶת צִיּוֹן, זוֹהִי חֶפְצִי בָהּ, אֵשֶׁת נָתָן בֶּן דָּוִד, אֵם הַמָּשִׁיחַ, מְנַחֵם בַּ\"ר עַמִּיאֵ\"ל, וְהִיא תֵצֵא וּתְבַשֵּׂר, וְהִיא בִּכְלַל מְבַשֶּׂרֶת צִיּוֹן."],[1,"","קוֹל יִשָּׁמַע בָּעוֹלָם, וּשְׁנֵי מְלָכִים יִתְעוֹרְרוּ בָעוֹלָם לַעֲרֹךְ קְרָב, וְיֵצֵא שֵׁם הַקָּדוֹשׁ עַל הָעוֹלָם. מַה תְּבַשֵּׂר וְתֹאמַר? (שם) הִנֵּה ה' אֱלֹהִים בְּחָזָק יָבֹא וּזְרֹעוֹ מֹשְׁלָה לוֹ הִנֵּה שְׂכָרוֹ אִתּוֹ וּפְעֻלָּתוֹ לְפָנָיו. הִנֵּה שְׂכָרוֹ אִתּוֹ - שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא מַכְרִיז בְּכָל פָּמַלְיָה שֶׁל מַעְלָה וְיֹאמַר לָהֶם: הִתְכַּנְּסוּ וְדוּנוּ דִין, מִי שֶׁמָּסַר נִשְׁמָתוֹ עַל קְדֻשַּׁת שְׁמִי מַהוּ שְּׂכָרוֹ? וְאֵלּוּ יֹאמְרוּ כָּךְ וְכָךְ. מִי שֶׁסָּבַל כַּמָּה חֵרוּפִים וְגִדּוּפִים בְּכָל יוֹם עָלַי מַה שְּׂכָרוֹ? הֵם יֹאמְרוּ כָּךְ. מִי שֶׁנֶּעֱנָשׁ בְּכָל יוֹם יוֹם עָלַי מַה שְּׂכָרוֹ? הֵם יֹאמְרוּ כָּךְ. זֶהוּ שֶׁכָּתוּב הִנֵּה שְׂכָרוֹ אִתּוֹ וּפְעֻלָּתוֹ לְפָנָיו."],[2,"","מַהוּ וּפְעֻלָּתוֹ? אֶלָּא כְּמוֹ שֶׁכָּתוּב, (תהלים לא) מָה רַב טוּבְךְ וְגוֹ', פָּעַלְתָּ לַחוֹסִים בָּךְ. זֶהוּ פְּעֻלָּתוֹ. נֶגֶד בְּנֵי אָדָם מַה זֶּה? אֶלָּא נֶגֶד עוֹבְדֵי כוֹכָבִים וּמַזָּלוֹת. אֲשֶׁר צָפַנְתָּ לִּירֵאֶיךְ, מַה זֶּה אֲשֶׁר צָפַנְתָּ? וְכִי מִי יִגְזֹל וְיִטֹּל מִיָּדוֹ מַה שֶּׁהוּא רוֹצֶה לָתֵת, שֶׁכָּתוּב צָפַנְתָּ?"],[3,"","אֶלָּא צֵא וּרְאֵה מַעֲשֵׂי הָרַחֲמָנוּת שֶׁעוֹשֶׂה הַקָּדוֹשׁ בָּרוּךְ הוּא. בְּמַה שֶּׁהוּא מַכֶּה - בּוֹ נוֹתֵן רְפוּאָה. בַּמֶּה מַכֶּה? בִּשְׂמֹאל. בְּיָמִין מְקָרֵב וּבִשְׂמֹאל מַכֶּה. בְּמַה שֶּׁמַּכֶּה - בּוֹ נוֹתֵן רְפוּאָה לָעוֹלָם. כָּתוּב (ירמיה א) מִצָּפוֹן תִּפָּתַח הָרָעָה, וּבְצָפוֹן מַכֶּה, שֶׁמִּשָּׁם יוֹצְאִים כָּל הַדִּינִים וְכָל הַגְּזֵרוֹת הַקָּשׁוֹת - וּבוֹ שׁוֹרֶה כָּל שָׂכָר טוֹב וְכָל טוֹב שֶׁעָתִיד הַקָּדוֹשׁ בָּרוּךְ הוּא לָתֵת לְיִשְׂרָאֵל. לֶעָתִיד לָבֹא קוֹרֵא הַקָּדוֹשׁ בָּרוּךְ הוּא לַצָּפוֹן וְיֹאמַר לוֹ: בְּךְ נָתַתִּי כָּל טוֹב וְכָל שָׂכָר טוֹב לְבָנַי שֶׁסָּבְלוּ כַּמָּה רָעוֹת בָּעוֹלָם הַזֶּה עַל קְדֻשַּׁת שְׁמִי, תֵּן שְׂכָרִים טוֹבִים שֶׁנָּתַתִּי בְךְ."],[4,"","זֶהוּ שֶׁכָּתוּב, (ישעיה מג) אֹמַר לַצָּפוֹן תֵּנִי וּלְתֵימָן אַל תִּכְלָאִי וְגוֹ'. וְכִי דֶרֶךְ הַדָּרוֹם כָּךְ הוּא, לִמְנֹעַ בְּרָכוֹת? וַהֲרֵי כָּל הַבְּרָכוֹת מִצַּד דָּרוֹם, וְכָל טוֹבוֹת הָעוֹלָם מִדָּרוֹם יוֹצְאוֹת, וְהוּא אוֹמֵר לְתֵימָן אַל תִּכְלָאִי?!"],[5,"","אֶלָּא בְּאוֹתָהּ שָׁעָה יְעוֹרֵר הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת אַבְרָהָם וְיֹאמַר לוֹ: קוּם, שֶׁהֲרֵי הִגִּיעַ זְמַן שֶׁאֲנִי גּוֹאֵל אֶת בָּנֶיךְ לָתֵת לָהֶם שָׂכָר טוֹב עַל כָּל מַה שֶּׁסָּבְלוּ בַגָּלוּת. וּמִתּוֹךְ שֶׁאַבְרָהָם הָיָה בִמְכִירָתָם, שֶׁכָּתוּב (דברים לב) אִם לֹא כִּי צוּרָם מְכָרָם - זֶה אַבְרָהָם, הָיָה לוֹ כְּמִי שֶׁלֹּא טוֹב בְּעֵינָיו, וּמַרְאֶה עַצְמוֹ כְּמִי שֶׁרוֹצֶה שֶׁיִּלְקוּ עַל חֲטָאֵיהֶם יוֹתֵר וְיֹאמַר: גְּבוּ מֵעֲונוֹתֵיהֶם! גְּבוּ מֵחֲטָאֵיהֶם! אָמַר לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא לְאַבְרָהָם: יָדַעְתִּי כָּל מַה שֶּׁאָמַרְתָּ לְפָנִים. אֲנִי גַּם כֵּן לְפָנִים. אַל תִּכְלָאִי. אֲנִי רוֹצֶה לְפַיֶּסְךְ עַל בָּנֶיךְ, אַל תִּמְנַע מֵהֶם טוֹבוֹת, אַל תִּמְנַע מֵהֶם שָׂכָר טוֹב, כַּמָּה וְכַמָּה סָבְלוּ עַל חֲטָאֵיהֶם. וּמִשּׁוּם כָּךְ - אֹמַר לַצָּפוֹן תֵּנִי. וְהַיְנוּ אֲשֶׁר צָפַנְתָּ, וְזֶהוּ הַדָּבָר (שתהא) שֶׁל אוֹתָהּ מְבַשֶּׂרֶת."],[6,"","וְעוֹד תְּבַשֵּׂר פַּעַם שְׁנִיָּה, בְּשָׁעָה שֶׁהַשְּׁכִינָה תַעֲלֶה עַל אוֹתוֹ הַר עֶלְיוֹן, וְתֵלֵךְ וּתְבַשֵּׂר לָאָבוֹת. מִיָּד תֵּלֵךְ לִירוּשָׁלַיִם וְתִרְאֶה אוֹתָהּ בְּחֻרְבָּנָהּ. תִּכָּנֵס לְצִיּוֹן, וְשָׁם תְּקַרְקֵר קִיר כְּמִקֹּדֶם עַל מְקוֹם בֵּית מוֹשָׁבָהּ וְעַל כְּבוֹדָהּ בְּאוֹתוֹ מָקוֹם. וְשָׁם נִשְׁבַּעְתָּ שֶׁלֹּא תִקַּח מִשָּׁם וְלֹא תֵצֵא עַד שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא יִגְאַל אֶת בָּנֶיהָ, וְחֶפְצִי בָהּ זוֹ תְּבַשֵּׂר כְּמִקֹּדֶם וְאוֹמֶרֶת: (ישעיה יב) צַהֲלִי וָרֹנִּי יוֹשֶׁבֶת צִיּוֹן כִּי גָדוֹל בְּקִרְבֵּךְ וְגוֹ'. מַה זֶּה גָּדוֹל בְּקִרְבֵּךְ? זֶה הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁבָּא אֵלֶיהָ לַהֲקִימָהּ מִן הֶעָפָר, וְיֹאמַר לָהּ: (שם נב) הִתְנַעֲרִי מֵעָפָר קוּמִי שְׁבִי יְרוּשָׁלם. יְרוּשָׁלַיִם הִיא, וִירוּשָׁלַיִם שְׁמָהּ בְּוַדַּאי."],[7,"","וּבָזְהִ גַּם כָּךְ כַּמָּה שִׂמְחָה עַל שִׂמְחָה תִּהְיֶה לַצַּדִּיקִים בְּגַן עֵדֶן. וּמִשּׁוּם זֶה אַשְׁרָיו מִי שֶׁנִּשְׁמָתוֹ בְּשַׁבָּת מְעִידָה לִפְנֵי הַמֶּלֶךְ עַל חִדּוּשׁ הַתּוֹרָה, שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא וְכָל פָּמַלְיָתוֹ וְכָל אוֹתָן נִשְׁמוֹת הַצַּדִּיקִים שֶׁהָיוּ בְּגַן עֵדֶן, כֻּלָּם מִתְעַטְּרִים בְּאוֹתוֹ דָבָר."]]],[["תּוּ שְׁמַעְנָא בּוּצִינָא קַדִּישָׁא, דְּכַמָּה יְקָר עַל יְקָר, וַעֲטָרָה עַל עֲטָרָה, מְעַטְּרָן לַאֲבוּהָ דְּהַהוּא בַּר נָשׁ תַּמָּן, בְּשַׁעֲתָא דְּאָמַר קוּדְשָׁא בְּרִיךְ הוּא, אִתְכְּנָשִי לְמִשְׁמַע חִדּוּשָׁא וּמִלִּין חַדְתִּין דְּאוֹרַיְיתָא, מִשְּׁמֵיהּ דִּפְלוֹנִי בַּר פְּלוֹנִי, כַּמָה אִינּוּן דְּנַשְׁקִין עַל רֵישֵׁיהּ. כַּמָה צַדִּיקַיָּיא מְעַטְּרִין לֵיהּ, כַּד נַחְתִּין. זַכָּאָה חוּלָקֵיהוֹן דְּכָל אִינּוּן דְּמִשְׁתַּדְּלִין בְּאוֹרַיְיתָא, יוֹמָא דְּשַׁבְּתָא מִשְּׁאַר יוֹמִין. (עד כאן)","\u0003רעיא מהימנא\u0004 (במדבר ט״ו:כ׳) רֵאשִׁית עֲרִיסוֹתֵיכֶם חַלָּה תָּרִימוּ וְגוֹ', פִּקּוּדָא דָּא לְהַפְרִישׁ חַלָּה לַכֹּהֵן. חַלָּ\"ה הָכִי חוּשְׁבָּנֵיהּ, מ\"ג בֵּיצִּים, וְחוֹמֶשׁ בֵּיצָּה, חַד מֵחֲמֵשׁ. וְאִית חוֹמֶשׁ חַד מִן חַמְשִׁין, דְּאִיהוּ ן'. וְדָא סִימַן מָגֵ\"ן, דְּאִיהוּ מִיכָאֵ\"ל גַּבְרִיאֵ\"ל נוּרִיאֵ\"ל. חַלָה, שְׁכִינְתָּא. דִּבַאֲתָר דְּאִלֵּין מַלְאֲכִין תַּמָּן, אֲבָהָן תַּמָּן. וּבְאַתְרָא דַּאֲבָהָן תַּמָּן, שְׁכִינְתָּא תַּמָּן. וּבָה וַיְחַל, בָּהּ צַּלֵּינָא, הֲדָא הוּא דִכְתִיב, (שמות ל״ב:י״א) וַיְחַל מֹשֶׁה אֶת פְּנֵי יְיָ אֱלֹהָיו. (דברים ג׳:כ״ד) אֲדֹנָי יֶדוִֹד אַתָּה הַחִלּוֹתָ לְהַרְאוֹת אֶת עַבְדְּךָ. וּבָהּ חָלָה זְכוּת אָבוֹת. וּבָהּ תָּמָה זְכוּת אָבוֹת לָרְשָׁעִים. דַּהֲווֹ מְקַבְּלִים אַגְרַיְיהוּ בְּהַאי עָלְמָא.","דְּמִסִטְרָא דִּימִינָא, דְּתַמָּן י' דְּאִיהוּ חָכְמָה, שֵׁרוּתָא דִּשְׁמָא דַּיְדוָֹד, דְּאִיהוּ אַחְזֵי זְכוּתָא עַל בְּנָהָא מִימִינָא, דְּתַמָּן רמ\"ח פִּקוּדִין דַּעֲשֵׂה. מִסִּטְרָא דְּאָת ה' בַּתְרָאָה, דְּאִיהִי לִשְׂמָאלָא דִּגְבוּרָה, דְּתַמָּן לֹא תַּעֲשֶׂה, דְּאִינּוּן שס\"ה, דְּתַמָּן נִדוֹנִין רְשָׁעִים גְּמוּרִים, תָּמָה לוֹן זְכוּת אָבוֹת, וְאִתְהַפָּךְ לוֹן שֵׁם יְהוָֹ\"ה, הוה\"י. וְאוֹלִיפְנָא מֵהָמָן הָרָשָׁע, (אסתר ה׳:י״ג) וְכָל זֶה אֵינֶנּוּ שׁוְֹה לִי. (ע\"כ רעיא מהימנא)\\","(במדבר ט״ו:א׳-ב׳) וַיֹּאמֶר יְיָ אֶל מֹשֶׁה לֵאמֹר דַּבֵּר אֶל בְּנֵי יִשְׂרָאֵל וְגוֹ' וְעָשׂוּ לָהֶם צִיצִית עַל כַּנְפֵי בִגְדֵיהֶם לְדוֹרוֹתָם וְגוֹ'. רִבִּי חִזְקִיָּה פָּתַח, (זכריה ג׳:א׳) וַיַּרְאֵנִי אֶת יְהוֹשֻׁעַ הַכֹּהֵן הַגָּדוֹל וְגוֹ'. כַּמָה זַכָּאִין אִינּוּן יִשְׂרָאֵל, דְקוּדְשָׁא בְּרִיךְ הוּא בָּעֵי בִּיקָרֵהוֹן עַל כָּל בְּנֵי עָלְמָא, וְיָהַב לוֹן אוֹרַיְיתָא קַדִּישָׁא, וְיָהַב לוֹן נְבִיאֵי מְהֵימְנֵי, דִּמְדַבְּרֵי לְהוּ בְּאוֹרַיְיתָא, בְּאֹרַח קְשׁוֹט.","תָּא חֲזֵי, כָּל נְבִיאֵי וּנְבִיאֵי דְּאוֹקִים קוּדְשָׁא בְּרִיךְ הוּא לְיִשְׂרָאֵל, כֻּלְּהוּ אִתְגְּלֵי קוּדְשָׁא בְּרִיךְ הוּא עָלַיְיהוּ, בְּדַרְגִּין עִלָּאִין קַדִּישִׁין, וְחָמוּ זִיו יְקָרָא קַדִּישָׁא דְּמַלְכָּא מֵאֲתָר עִלָּאָה, אֲבָל לָא קָרִיב כְּמֹשֶׁה, דְּהֲוָה קָרִיב לְמַלְכָּא יַתִּיר מִכֹּלָּא, דְּהָא זַכָּאָה חוּלָקֵיהּ יַתִּיר מִכָּל בְּנֵי עָלְמָא, דְּעָלֵיהּ כְּתִיב, (במדבר י״ב:ח׳) פֶּה אֶל פֶּה אֲדַבֶּר בּוֹ וּמַרְאֶה וְלֹא בְחִידוֹת. וּשְׁאַר נְבִיאֵי, הֲווֹ חָמָאן מֵאֲתָר רְחִיקָא, כְּמָה דְּאַתְּ אָמֵר (ירמיהו ל״א:ג׳) מֵרָחוֹק יְיָ נִרְאָה לִי.","(שמות י\"א ע\"ב) אָמַר רִבִּי חִזְקִיָּה, הָכִי אוֹלִיפְנָא, כְּתִיב (שמות ב׳:א׳) וַיֵּלֶךְ אִישׁ מִבֵּית לֵוִי וַיִּקַּח אֶת בַּת לֵוִי. וַיֵּלֶךְ אִישׁ: דָּא קוּדְשָׁא בְּרִיךְ הוּא כְּמָה דְאַתְּ אָמֵר (שמות ט״ו:ג׳) יְיָ אִישׁ מִלְחָמָה. מִבֵּית לֵוִי: דָּא קוּדְשָׁא בְּרִיךְ הוּא, אֲתָר דְּחָכְמָה עִלָּאָה, וְהַהוּא זוֹהַר (ס\"א נהר) מִתְחַבְּרָן כַּחֲדָא, דְּלָא מִתְפָּרְשָׁן לְעָלְמִין. מִבֵּית לֵוִי: דְּאַשְׁרֵי לִוְיָתָן (ס\"א כל חידו) בִּלְחוֹדוֹי בְּעָלְמָא, הֲדָא הוּא דִכְתִיב (תהילים ק״ד:כ״ו) לִוְיָתָן זֶה יָצַרְתָּ לְשַׂחֶק בּוֹ. וַיִּקַּח אֶת בַּת לֵוִי, דָּא קוּדְשָׁא בְּרִיךְ הוּא, אֲתָר דִּנְהִירוּ דְּסִיהֲרָא נָהִיר.","וַתַּהַר הָאִשָּׁה וַתֵּלֶד בֵּן. הָאִשָּׁה וַדַּאי, כְּמָה דְאַתְּ אָמֵר (בראשית ב׳:כ״ג) לְזֹאת יִקָּרֵא אִשָּׁה. בְּקַדְמִיתָא בַּת לֵוִי, הָכִי הוּא וַדַּאי. וְכִי בַּת לֵוִי בְּקַדְמִיתָא, וְהַשְׁתָּא אִשָׁה. אֶלָּא הָכִי אוֹלִיפְנָא, אִתְּתָא עַד לָא אִזְדַּוְּוגַת, אִתְקְרִיאַת בַּת פְּלוֹנִי, בָּתַר דְּאִזְדַּוְּוגַת. אִתְקְרֵי אִשָׁה, וְהָכָא, בַּת וְאִשָּׁה, כֹּלָּא בְּחַד דַּרְגָּא הוּא.","וַתִּצְפְּנֵהוּ ג' יְרָחִים, אִלֵּין תְּלַת יַרְחִין דְּדִינָא קַשְׁיָא שַׁרְיָא בְּעָלְמָא. וּמַאי נִינְהוּ. תַּמּוּ\"ז וְאָ\"ב וְטֵבֵ\"ת. מַאי קָא מַשְׁמַע לָן. דְּעַד דְּלָא נָחַת מֹשֶׁה לְעָלְמָא, שְׁכִיחַ הֲוָה הוּא לְעֵילָּא, וְעַל דָּא אִזְדַּוְּוגַת בֵּיהּ שְׁכִינְתָּא מִן יוֹמָא דְּאִתְיְלִיד. מִכָּאן אָמַר רִבִּי שִׁמְעוֹן, רוּחֵיהוֹן דְּצַדִּיקַיָּיא שְׁכִיחִין אִינּוּן לְעֵילָּא, עַד לָא יֶחתוּן לְעָלְמָא.","וְלֹא יָכְלָה עוֹד הַצְּפִינוֹ וַתִּקַּח לּוֹ וְגוֹ' מַאי וַתִּקַּח לּוֹ תֵּיבַת גֹּמֶא. דְּחָפַת לֵיהּ בְּסִימָנָהָא, לְמֶהֱוִי נָטִיר מֵאִינּוּן נוּנֵי יַמָּא, דְּשָׁאטִין בְּיַמָּא רַבָּא, כְּמָה דִּכְתִּיב, (תהילים ק״ד:כ״ה) שָׁם רֶמֶשׂ וְאֵין מִסְפָּר. וְהִיא חָפַת לֵיהּ לְמֶהֱוִי נָטִיר מִנַּיְיהוּ בְּחָפוּ (ס\"א דסטרא דיובלא יקירא) דִּבְנֵי יַמָּא בְּלָא יַקִּירָא בִּתְרֵי גַּוְונִין, בְּחִיוָּור וְאוּכָּם, וְאָנַח לֵיהּ לְמֹשֶׁה לְמֵישַׁט בֵּינַיְיהוּ, לְאִשְׁתְּמוֹדַע בֵּינֵיהוֹן, בְּגִין דְּזַמִּין הוּא לְסַלְּקָא בֵּינַיְיהוּ, זִמְנָא אַחֲרָא, לְקַבְּלָא אוֹרַיְיתָא."],[[0,"תו שמענא וכו':","עוד שמעתי: מאור הקדוש. שכמה יקר על יקר ועטרה על עטרה מעטרים שם את אביו של אותו אדם, שנשמתו מעידה לפני המלך על חידושי תורה שלו, בשעה שהקב״ה אומר לפמליא שלו התאספו לשמוע חידושים ודברים חדשים בתורה של פלוני בן פלוני, שאז מזכיר הקב״ה את אביו של המחדש, כמה הם שנושקים על ראשו, של אבי המחדש, כמה צדיקים מעטרים איתו כשיורדים. אשרי חלקם של כל אלו העוסקים בתורה, וביום השבת יותר מבשאר ימים. (ע״כ רב מתיבתא)."],[1,"ראשית עריסותיכם חלה וגו׳:","מצוה זו, הוא להפריש חלה לכהן. \u0003חלה\u0004 חשבון שלה הוא מ״ג. שזה מראה שאין עיסה חייבת בחלה אלא אם כן יש בה מ״ג ביצים, וחומש ביצה, דהיינו אחד מחמשה שבביצה. ויש חומש אחד מן המשים, שהוא \u0003ן'.\u0004 והסימן, \u0003מ״גן\u0004 שהוא \u0003מ\"ג\u0004 עם \u0003ן׳\u0004 ארוכה. והוא ראשי תיבות מיכאל גבריאל נוריאל, שהם כנגד חג״ת דז״א, \u0003חלה,\u0004 היא השכינה, כי במקום שאלו מלאכים מג״נ שם, שם הם האבות, שהם חג״ת, ובמקום שהאבות שם, דהיינו חג\"ת, שם היא השכינה. כי חג״ת ה״ס ג׳ קוין, והמלכות היא המקבלת מהם. ובה, במלכות, \u0003ויחל\u0004 כי בה מתפללים, שהיא נקראת תפלה, ז״ש \u0003ויחל\u0004 משה את פני ה׳ אלקיו, אדני אלקים אתה \u0003החילות\u0004 להראות את עבדך. ובה \u0003חלה,\u0004 דהיינו מתחלת זכות אבות שהוא מלשון החילות, ובה מסתיימת זכות אבות לרשעים, שזכות אבות אינה עומדת להם, כי הם מקבלים שכרם בעולם הזה."],[2,"דמסטרא דימינא דתמן וכו׳:","כי מצד ימין, ששם \u0003י׳\u0004 שהיא חכמה, כי החכמה בימין והבינה בשמאל, שהם י״ה. שהוא ראשית שם הויה, השכינה, מראה זכות על בניה, בשעת שמקבלת מימין, ששם רמ״ח מצות עשה, שה״ס חסדים. ומצד אות \u0003ה׳\u0004 אחרונה של הויה, שהיא לשמאל מגבורה, כי המלכות נבנית מצד שמאל, ומטרם שמקבלת מימין, ששם לא תעשה, שהם שס״ה, שהם בשמאל, ששם רשעים גמורים נדונים, להם תמה להם זכות אבות, שאין להם חסדים מחג״ת הנקראים אבות. ומתהפך להם שם הויה, אל \u0003הוה\"י,\u0004 דהיינו למפרע הרומז על דין, ולמדנו מהמן הרשע, שאמר וכל ז \u0003ה\u0004 איננ \u0003ו\u0004 שו \u0003ה\u0004 ל \u0003י.\u0004 שבסופי תיבות מרומז הוה״י. מכאן שמורה על דינים (ע״כ רעיא מהימנא)."],[3,"ויאמר","וגו׳ \u0003ועשו להם ציצית\u0004 וגו׳: ר׳ חזקיה פתח, ויראני את יהושע הכהן הגדול וגו׳. כמה מאושרים הם ישראל, שהקב״ה רוצה ביקרם על כל בני העולם, ונתן להם התורה הקדושה, ונתן להם נביאים נאמנים המנהיגים אותם בתורה בדרך אמת."],[4,"תא חזי כל וכו׳:","בוא וראה, כל נביאים ונביאים שהקב״ה הקים לישראל, כולם נגלה הקב״ה עליהם במדרגות עליונות קדושות, וראו זיו יקר הקדוש של המלך ממקום עליון, אבל לא קרוב כמשה, שהיה קרוב למלך יותר מכולם, כי חלקו היה מאושר יותר מכל בני העולם, שעליו כתוב, פה אל פה אדבר בו ומראה ולא בחידות. ושאר הנביאים היו רואים ממקום רחוק, כמו שאתה אומר, מרחוק ה׳ נראה לי."],[5,"א״ר חזקיה וכו׳:","אר״ח, כך למדתי, כתוב, וילך איש מבית לוי ויקח את בת לוי. \u0003וילך איש,\u0004 זה הקב״ה, שהוא ז״א, כש״א ה׳ \u0003איש\u0004 מלחמה. \u0003מבית לוי,\u0004 זה הקב״ה, שהלך מן המקום שחכמה העליונה וזוהר ההוא שהוא בינה עליונה, מתחברים יחד ואינם נפרדים לעולם. ודריש \u0003לוי,\u0004 מלשון דבקות, מלשון לויות. ופירוש אחר, \u0003מבית לוי,\u0004 שהלויתן שהוא יסוד דז״א, השרה כל שמחה בעולם, ודורש, לוי, מלשון לויתן. ז״ש לויתן זה יצרת לשחק בו. \u0003ויקח את בת לוי,\u0004 זהו הקב׳״ה, שהוא המקום שאור הלבנה מאיר, שהיא המלכות. ושיעור הכתוב הוא, וילך איש, שהוא ז״א, מבית לוי, שהוא או״א עלאין, ויקח את בת לוי, שהיא המלכות, דהיינו שז״א השפיע אורות דאו״א עלאין אל המלכות."],[6,"ותהר האשה ותלד בן:","האשה, ודאי, שהיא המלכות, כש״א ל \u0003זאת\u0004 יקרא אשה. ו \u0003זאת\u0004 היא שם המלכות. בתחילה קראה בת לוי, וכך הוא ודאי, ולמה קראה תחילה בת לוי ועתה אשה. ומשיב, אלא כך למדנו, אשה, מטרם שנשאת נקראת \u0003בת\u0004 פלוני, ואחר שנשאת נקראת \u0003אשה.\u0004 אף כאן בת ואשה מדרגה אחת היא. דהיינו מלכות, אלא מטרם שלקחה לזווג, נקראת בת לוי, ואח״כ אשה."],[7,"ותצפנהו ג׳ ירחים:","אלו הם ג׳ ירחים שדין קשה שורה בעולם, ומה הם, תמוז, אב, וטבת. וע״כ השכינה הצפינה אותו. שואל, מה משמיענו בזה. ומשיב, שמשמיענו, שמטרם שירד משה לעולם היה נמצא למעלה, וע״כ נתחברה עמו השכינה מיום שנולד, ושמרה אותו. מכאן אמר ר׳ שמעון, שהרוחות של הצדיקים נמצאים למעלה מטרם שירדו לעולם."],[8,"ולא יכלה עוד הצפינו וגו׳:","שואל, מהו ותקח לו תיבת גמא. ומשיב, שצפתה אותו בסמנים, שיהיה נשמר מאלו דגי הים, דהיינו מלאכים עליונים, השטים בים הגדול. שכתוב, שם רמש ואין מספר, והיא כסתה אותו, שיהי׳ נשמר מהם, בצפוי מצד יובל היקר, שהיא בינה, בב׳ גוונים, לבן ושחור, שה״ס חמר וזפת. כנגד ב׳ קוין ימין ושמאל. כי זפת ה״ס שמאל, אלא שמעורב עם המלכות דמדת הדין, וע״כ האדום שבשמאל נעשה שחור (כנ״ל באד״ר נשא אות רי״ד) שז״ס האי שחור אדום היא אלא שלקה. והניחה את משה לשוט ביניהם, בין המלאכים, ולהיות נודע ביניהם משום שהוא עתיד לעלות ביניהם בזמן אחר, לקבל התורה."]],[[0,"","עוֹד שָׁמַעְתִּי מְנוֹרָה הַקְּדוֹשָׁה, שֶׁכַּמָּה כָבוֹד עַל כָּבוֹד וַעֲטָרָה עַל עֲטָרָה מְעַטְּרִים לַאֲבִי אוֹתוֹ אָדָם שָׁם בְּשָׁעָה שֶׁאָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא: הִתְכַּנְּסוּ לִשְׁמֹעַ חִדּוּשׁ וּדְבָרִים חֲדָשִׁים בַּתּוֹרָה מִשֵּׁם פְּלוֹנִי בֶּן פְּלוֹנִי. כַּמָּה הֵם שֶׁמְּנַשְּׁקִים אֶת רֹאשׁוֹ. כַּמָּה צַדִּיקִים מְעַטְּרִים אוֹתוֹ כְּשֶׁיּוֹרְדִים. אַשְׁרֵי חֶלְקָם שֶׁל כָּל אֵלּוּ שֶׁמִּשְׁתַּדְּלִים בַּתּוֹרָה בְּיוֹם הַשַּׁבָּת מִשְּׁאָר יָמִים. (עד כאן)"],[1,"","רֵאשִׁית עֲרִסֹתֵכֶם חַלָּה תָּרִימוּ וְגוֹ'. מִצְוָה לוֹ לְהַפְרִישׁ חַלָּה לַכֹּהֵן. חַלָּ\"ה כָּךְ חֶשְׁבּוֹנָהּ: מ\"ג בֵּיצִים וְחֹמֶשׁ בֵּיצָה, אֶחָד מֵחָמֵשׁ. וְיֵשׁ חֹמֶשׁ אֶחָד מֵחֲמִשִּׁים, שֶׁהוּא ן'. וְזֶה סִימַן מָגֵ\"ן, שֶׁהוּא מִיכָאֵ\"ל גַּבְרִיאֵ\"ל נוּרִיאֵ\"ל. חַלָּה - שְׁכִינָה. שֶׁבְּמָקוֹם שֶׁמַּלְאָכִים אֵלֶּה שָׁם - הָאָבוֹת שָׁם. וּבְמָקוֹם שֶׁהָאָבוֹת שָׁם - שְׁכִינָה שָׁם. וּבָהּ וַיְחַל, בָּהּ אָנוּ מִתְפַּלְלִים. זֶהוּ שֶׁכָּתוּב (שמות לב) וַיְחַל מֹשֶׁה אֶת פְּנֵי ה' אֱלֹהָיו. (דברים ג) אֲדנָי אֱלֹהִים אַתָּה הַחִלּוֹתָ לְהַרְאוֹת אֶת עַבְדְּךְ. וּבָה חָלָה זְכוּת אָבוֹת, וּבָהּ תַּמָּה זְכוּת אָבוֹת לָרְשָׁעִים, שֶׁהָיוּ מְקַבְּלִים שְׂכָרָם בָּעוֹלָם הַזֶּה."],[2,"","שֶׁמִּצַד יָמִין שֶׁשָּׁם י', שֶׁהִיא חָכְמָה, רֵאשִׁית שֵׁם ה', שֶׁהִיא מַרְאָה זְכוּת עַל בָּנֶיהָ מִיָּמִין, שֶׁשָּׁם רמ\"ח מִצְווֹת עֲשֵׂה מִצַּד אוֹת ה' אַחֲרוֹנָה, שֶׁהִיא שְׂמֹאל שֶׁל גְּבוּרָה, שֶׁשָּׁם לֹא תַעֲשֶׂה, שֶׁהֵם שס\"ה, שֶׁשָּׁם נִדּוֹנִים רְשָׁעִים גְּמוּרִים, תַּמָּה לָהֶם זְכוּת אָבוֹת, וּמִתְהַפֵּךְ לָהֶם שֵׁם יְהֹוָ\"ה - הוה\"י. וְלָמַדְנוּ מֵהָמָן הָרָשָׁע, (אסתר ה) וְכָל זֶה אֵינֶנּוּ שּוֶה לִי."],[3,"","וַיֹּאמֶר ה' אֶל מֹשֶׁה לֵּאמֹר. דַּבֵּר אֶל בְּנֵי יִשְׂרָאֵל וְגוֹ' וְעָשׂוּ לָהֶם צִיצִת עַל כַּנְפֵי בִגְדֵיהֶם לְדֹרֹתָם וְגוֹ'. רַבִּי חִזְקִיָּה פָּתַח, (זכריה ג) וַיַּרְאֵנִי אֶת יְהוֹשֻׁעַ הַכֹּהֵן הַגָּדוֹל וְגוֹ'. כַּמָּה צַדִּיקִים הֵם יִשְׂרָאֵל שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא רוֹצֶה בִכְבוֹדָם עַל כָּל בְּנֵי הָעוֹלָם, וְנָתַן לָהֶם תּוֹרָה קְדוֹשָׁה, וְנָתַן לָהֶם נְבִיאֵי אֱמֶת שֶׁמַּנְהִיגִים אוֹתָם בַּתּוֹרָה בְּדֶרֶךְ אֱמֶת."],[4,"","בֹּא וּרְאֵה, כָּל נְבִיאִים וּנְבִיאִים שֶׁהֶעֱמִיד הַקָּדוֹשׁ בָּרוּךְ הוּא לְיִשְׂרָאֵל, עַל כֻּלָּם הִתְגַּלָּה הַקָּדוֹשׁ בָּרוּךְ הוּא בִּדְרָגוֹת עֶלְיוֹנוֹת קְדוֹשׁוֹת, וְרָאוּ זִיו כָּבוֹד קָדוֹשׁ שֶׁל הַמֶּלֶךְ מִמָּקוֹם עֶלְיוֹן, אֲבָל לֹא קָרוֹב כְּמֹשֶׁה, שֶׁהָיָה קָרוֹב לַמֶּלֶךְ יוֹתֵר מֵהַכֹּל, שֶׁהֲרֵי אַשְׁרֵי חֶלְקוֹ יוֹתֵר מִכָּל בְּנֵי הָעוֹלָם, שֶׁעָלָיו כָּתוּב (במדבר יב) פֶּה אֶל פֶּה אֲדַבֶּר בּוֹ וּמַרְאֶה וְלֹא בְחִידת. וּשְׁאָר נְבִיאִים הָיוּ רוֹאִים מִמָּקוֹם רָחוֹק, כְּמוֹ שֶׁנֶּאֱמַר (ירמיה לא) מֵרָחוֹק ה' נִרְאָה לִי."],[5,"","אָמַר רַבִּי חִזְקִיָּה, כָּךְ לָמַדְנוּ, כָּתוּב (שמות ב) וַיֵּלֶךְ אִישׁ מִבֵּית לֵוִי וַיִּקַּח אֶת בַּת לֵוִי. וַיֵּלֶךְ אִישׁ - זֶה הַקָּדוֹשׁ בָּרוּךְ הוּא, כְּמוֹ שֶׁנֶּאֱמַר (שמות טו) ה' אִישׁ מִלְחָמָה. מִבֵּית לֵוִי - זֶה הַקָּדוֹשׁ בָּרוּךְ הוּא, מָקוֹם שֶׁחָכְמָה עֶלְיוֹנָה וְאוֹתוֹ זֹּהַר (נהר) מִתְחַבְּרִים כְּאֶחָד, שֶׁלֹּא נִפְרָדִים לְעוֹלָמִים. מִבֵּית לֵוִי - שֶׁהִשְׁרָה לִוְיָתָן (כל שמחה) בִּלְבַדּוֹ בָּעוֹלָם, זֶהוּ שֶׁכָּתוּב (תהלים קד) לִוְיָתָן זֶה יָצַרְתָּ לְשַׂחֶק בּוֹ. וַיִּקַּח אֶת בַּת לֵוִי - זֶה הַקָּדוֹשׁ בָּרוּךְ הוּא, מָקוֹם שֶׁאוֹר הַלְּבָנָה מֵאִיר."],[6,"","וַתַּהַר הָאִשָּׁה וַתֵּלֶד בֵּן. הָאִשָּׁה וַדַּאי, כְּמוֹ שֶׁנֶּאֱמַר (בראשית ב) לְזֹּאת יִקָּרֵא אִשָּׁה. בַּהַתְחָלָה בַּת לֵוִי, כָּךְ הוּא בְּוַדַּאי. וְכִי בַּת לֵוִי בַּהַתְחָלָה וְכָעֵת אִשָּׁה? אֶלָּא כָּךְ לָמַדְנוּ, אִשָּׁה עַד שֶׁלֹּא מִזְדַּוֶּגֶת נִקְרֵאת בַּת פְּלוֹנִי. אַחַר שֶׁהִזְדַּוְּגָה נִקְרֵאת אִשָּׁה. וְכָאן בַּת וְאִשָּׁה, הַכֹּל בְּדַרְגָּה אַחַת הִיא."],[7,"","וַתִּצְפְּנֵהוּ שְׁלֹשָׁה יְרָחִים - אֵלּוּ שְׁלֹשֶׁת הֶחֳדָשִׁים שֶׁהַדִּין הַקָּשֶׁה שָׁרוּי בָּעוֹלָם. וּמָהֵם? תַּמּוּ\"ז וְאָ\"ב וְטֵבֵ\"ת. מַה בָּא לְהַשְׁמִיעֵנוּ? שֶׁעַד שֶׁלֹּא יָרַד מֹשֶׁה לָעוֹלָם, מָצוּי הָיָה לְמַעְלָה, וְעַל זֶה הִזְדַּוְּגָה בּוֹ שְׁכִינָה מִיּוֹם שֶׁנּוֹלַד. מִכָּאן אָמַר רַבִּי שִׁמְעוֹן, רוּחוֹת הַצַּדִּיקִים מְצוּיוֹת הֵן לְמַעְלָה עַד שֶׁלֹּא יָרְדוּ לָעוֹלָם."],[8,"","וְלֹא יָכְלָה עוֹד הַצְּפִינוֹ וַתִּקַּח לוֹ וְגוֹ'. מַה זֶּה וַתִּקַּח לוֹ תֵּבַת גֹּמֶא? שֶׁכִּסְּתָה אוֹתוֹ בְּסִימָנֶיהָ לִהְיוֹת שָׁמוּר מֵאוֹתָם דְּגֵי הַיָּם שֶׁשָּׁטִים בַּיָּם הַגָּדוֹל, כְּמוֹ שֶׁכָּתוּב (תהלים קד) שָׁם רֶמֶשׂ וְאֵין מִסְפָּר. וְהִיא כִּסְּתָה אוֹתוֹ לִהְיוֹת שָׁמוּר מֵהֶם בְּכִסּוּי (של צד היובל המכבד) שֶׁבְּנֵי הַיָּם בְּלֹא כָבוֹד בִּשְׁנֵי צְבָעִים, לָבָן וְשָׁחֹר, וְהִנִּיחָה אֶת מֹשֶׁה לָשׁוּט בֵּינֵיהֶם, לִהְיוֹת נוֹדָע בֵּינֵיהֶם, מִשּׁוּם שֶׁעָתִיד הוּא לַעֲלוֹת בֵּינֵיהֶם בְּפַעַם אַחֶרֶת לְקַבֵּל תּוֹרָה."]]],[["וַתֵּרֶד בַּת פַּרְעֹה. דָּא הִיא, דְּאַתְיָא מִסִּטְרָא שְׂמָאלָא דְּדִינָא קַשְׁיָא, כְּמָה דְּאִתְּמַר לִרְחוֹץ עַל הַיְאוֹר. עַל הַיְאוֹר דַּיְיקָא, וְלָא עַל הַיָּם. וְאִי תֵּימָא, הָא כְּתִיב (שמות י״ז:ה׳) וּמַטְּךָ אֲשֶׁר הִכִּיתָ בּוֹ אֶת הַיְאוֹר. וּמֹשֶׁה לָא הִכָּה אֶלָּא בַּיָּם, וְקַרְיֵיהּ קְרָא יְאוֹר. אֶלָּא יְאוֹר הֲוָה דְּמָחָא אַהֲרֹן עַל יְדָא דְּמֹשֶׁה, וְשַׁוְויֵיהּ קְרָא דְּאִיהוּ עֲבַד.","כְּהַאי גַּוְונָא (שמות ז׳:כ״ה) וְיִּמָּלֵא שִׁבְעַת יָמִים אַחֲרֵי הַכּוֹת יְיָ אֶת הַיְאוֹר, וְאַהֲרֹן הִכָּה, אֶלָּא (ס\"א דעל דא) עַד דְּאָתָא מִסִּטְרָא דְקוּדְשָׁא בְּרִיךְ הוּא, קַרְיֵיהּ קְרָא הַכּוֹת יְיָ, לְבָתַר קַרְיֵיהּ בִּשְׁמָא דְּמֹשֶׁה. וְנַעֲרוֹתֶיהָ הוֹלְכוֹת, אִינּוּן שְׁאַר מַשִׁרְיָין דְּאַתְיָין מִסִּטְרָא דָּא.","(שמות ב׳:ו׳) וַתִּפְתַּח וַתִּרְאֵהוּ אֶת הַיֶּלֶד. וַתִּרְאֵהוּ, וַתֵּרֶא מִבָּעֵי לֵיהּ, מַאי וַתִּרְאֵהוּ. וְהָא אָמַר רִבִּי שִׁמְעוֹן לֵית לָךְ מִלָּה בְּאוֹרַיְיתָא, אוֹ אָת חַד בְּאוֹרַיְיתָא, דְּלָא אִית בֵּיהּ רָזִין יַקִירִין וְעִלָאִין. אֶלָּא הָכִי אוֹלִיפְנָא, רְשִׁימָא דְּמַלְכָּא וּמַטְרוֹנִיתָא אִשְׁתְּכַחַת בֵּיהּ, וְאִינּוּן רְשִׁימָא דְּוָא\"ו הֵ\"א, מִיַּד וַתַּחְמוֹל עָלָיו וְגוֹ'. עַד כָּאן לְעֵילָּא. מִכָּאן וּלְהָלְאָה לְתַתָּא, בַּר הַאי קְרָא, דִּכְתִּיב וַתֵּתַצַּב אֲחוֹתוֹ מֵרָחוֹק. אֲחוֹתוֹ דְּמַאן. אֲחוֹתוֹ דְּהַאי אִיהוּ, דְּקָרָא לִכְנֶסֶת יִשְׂרָאֵל אֲחוֹתִי, כְּמָה דְאַתְּ אָמֵר (שיר השירים ה׳:ב׳) פִּתְחִי לִי אֲחוֹתִי. מֵרָחוֹק: כְּמָה דְאַתְּ אָמֵר, (ירמיהו ל״א:ג׳) מֵרָחוֹק יְיָ נִרְאָה לִי.","מַאי מַשְׁמַע. מַשְׁמַע דְּאִינּוּן זַכָּאִין, עַד דְּלָא נַחְתּוּ לְעָלְמָא, אִשְׁתְּמוֹדְעָן אִינּוּן לְעֵילָּא לְגַבֵּי כֹּלָּא, וְכָּל שֶׁכֵּן מֹשֶׁה. וּמַשְׁמַע דְּנִשְׁמָתְהוֹן דְּצַדִּיקַיָּיא, אִתְמְשַׁךְ מֵאֲתָר עִלָּאָה, כְּמָה דְּאוֹקִימְנָא. וְרָזָא דְּמִלָּה אוֹלִיפְנָא, דְּמַשְׁמַע דְּאָב וְאֵם אִית לְנִשְׁמְתָא, כְּמָה דְּאִית אָב וְאֵם לְגוּפָא, בְּאַרְעָא.","וּמַשְׁמַע דִּבְכָל סִטְרִין, בֵּין לְעֵילָּא, בֵּין לְתַתָּא, מִדְּכָר וְנוּקְבָּא כֹּלָּא אַתְיָא וְאִשְׁתְּכַח. וְהָא אוּקְמוּהָ רָזָא דִּכְתִּיב, (בראשית א׳:כ״ד) תּוֹצֵא הָאָרֶץ נֶפֶשׁ חַיָּה. הָאָרֶץ, דָּא כְּנֶסֶת יִשְׂרָאֵל. נֶפֶשׁ חַיָּה, נַפְשָׁא דְּאָדָם קַדְמָאָה עִלָּאָה, כְּמָה דְּאִתְּמַר. אָתָא רִבִּי אַבָּא וּנְשָׁקֵיהּ, אָמַר ודַּאי שַׁפִּיר קָא אַמְרַת, וְהָכָא הוּא כֹּלָּא.","זַכָּאָה חוּלָקֵיהּ דְּמֹשֶׁה נְבִיאָה מְהֵימָנָא, עַל כָּל שְׁאַר נְבִיאֵי עָלְמָא. בְּגִין כַּךְ, לָא אִשְׁתְּדַּל בֵּיהּ כַּד אִסְתַּלָּק מֵעָלְמָא, בַּר קוּדְשָׁא בְּרִיךְ הוּא, דְּאַעֲלֵיהּ לְפַרְגּוֹדֵיהּ. וְעַל דָּא סָלִיק מֹשֶׁה בִּנְּבוּאָה עִלָּאָה, וּבְדַרְגִין יַקִּירִין, מִכָּל נְבִיאֵי עָלְמָא, וּשְׁאַר נְבִיאֵי חָמָאן בָּתַר כּוֹתָלִין סַגִּיאִין.","(זכריה ג׳:א׳) וַיַּרְאֵנִי אֶת יְהוֹשֻׁעַ הַכֹּהֵן הַגָּדוֹל, מַאי קָא חָמָא, דְּהֲוָה קָאִים קָמֵי מַלְאָכָא, וּמִתְלְבַּשׁ בִּלְבוּשִׁין מְלוּכְלָכִין, עַד דְּכָרוֹזָא נָפִיק, וְאָמַר הָסִירוּ הַבְּגָדִים הַצּוֹאִים מֵעָלָיו. אָמַר רִבִּי יִצְחָק, כְּתִיב הָכָא וְעוֹמֵד לִפְנֵי הַמַּלְאָךְ, מַאי לִפְנֵי הַמַּלְאָךְ. דְּהֲוָה דָּאִין דִּינוֹי, הַהוּא דִּכְתִּיב בֵּיהּ, (קהלת ה׳:ה׳) וְאַל תֹּאמַר לִפְנֵי הַמַּלְאָךְ כִּי שְׁגָגָה הִיא. מַאי קָא מַשְׁמַע לָן. דְּכָל בַּר נָשׁ דְּלָא זָכֵי בְּהַאי עָלְמָא, לְאִתְעַטְּפָא בְּעִטּוּפָא דְּמִצְוָה, וּלְאִתְלַבְּשָׁא בִּלְבוּשָׁא דְּמִצְוָה. כַּד עָיֵיל בְּהַהוּא עָלְמָא, קָאִים בִּלְבוּשָׁא טִנּוּפָא, דְּלָא אִצְטְרִיךְ, וְקָאִים בְּדִינָא עָלֵיהּ.","תָּא חֲזֵי, כַּמָה לְבוּשִׁין מִזְדַּמְּנִין בְּהַהוּא עָלְמָא, וְהַהוּא בַּר נָשׁ דְּלָא זָכֵי בְּהַאי עָלְמָא בִּלְבוּשִׁין דְּמִצְוָה, כַּד עָיֵיל לְהַהוּא עָלְמָא, מְלָבְּשִׁין לֵיהּ בְּחַד לְבוּשָׁא דְּאִשְׁתְּמוֹדַע לְגַבֵּי מָארֵיהוֹן דְּגֵיהִנָּם, וְהַהוּא לְבוּשָׁא, וַוי לְמַאן דְּאִתְלְבָּשׁ בֵּיהּ. דְּהָא כַּמָּה גַּרְדִּינֵי נִמוּסִין, זְמִינִין לְאַחֲדָא בֵּיהּ, וְעַיְילֵי לֵיהּ לַגֵּיהִנָם. וּשְׁלֹמֹה מַלְכָּא צָוַוח וְאָמַר (קהלת ט׳:ח׳) בְּכָל עֵת יִהְיוּ בְגָדֶיךָ לְבָנִים."],[[0,"ותרד בת פרעה לרחוץ על היאור:","זו, בת פרעה, שבאה מצד שמאל של דין הקשה. כמש״א, לרחוץ על היאור, על \u0003היאור\u0004 הוא בדיוק, ולא על הים. כי הים רומז על המלכות, אבל היאור היא דין קשה מצד השמאל שהמצרים עשו אותו אלוהי שלהם (כמ\"ש לעיל וארא אות קל״ז) ואם תאמר, הרי כתוב ומטך אשר הכית בו את היאור, ומשה לא הכה אלא הים וקראו הכתוב יאור. הרי שיאור אינו בדיוק, ומשיב, אלא יאור הוא, שהכהו אהרן על ידי משה, ושם אותו הכתוב, כאלו משה הכהו."],[1,"כהאי גוונא וימלא וגו׳:","כעין זה, וימלא שבעת ימים אחרי הכות ה׳ את היאור, אע״פ שאהרן הכה אותו, אלא משום שבא מצד הקב״ה שצוה אותו, קראו הכתוב, הכות ה'. ולאח״כ קראו על שם משה, מאותו הטעם. \u0003ונערותיה הולכות\u0004 הן שאר המחנות הבאות מצד שמאל הזה."],[2,"ותפתח ותראהו את הילד:","שואל, ותראהו, ותרא, היה צריך לומר, מהו ותראהו. והרי אמר ר׳ שמעון, שאין לך דבר בתורה, או אות אחת בתורה, שאין בה סודות עליונים ויקרים. ומשיב, אלא כך למדנו. רושם של המלך ומטדוניתא, שהם ז״א ומלכות שה״ס ו״ה דהויה, נמצא בו, והם הרושם של \u0003ו״ה\u0004 הנוסף על \u0003ותרא,\u0004 וע״כ כתוב \u0003ותראהו.\u0004 מיד, ותחמול עליו וגו׳. ע״כ למעלה. בעולמות עליונים, מכאן ולהלאה מדבר למטה בעולם הזה, חוץ מבכתוב הזה, שכתוב ותתצב אחותו מרחוק. שואל, אחותו של מי, ומשיב, אחותו של ההוא דהיינו ז״א, שקרא את כנסת ישראל אחותי, כש״א פתחי לי אחותי. \u0003מרחוק,\u0004 פירושו כש״א, מרחוק ה׳ נראה לי. ושיעור הכתוב, ותתצב אחותו של ז״א, שהוא המלכות, על משה, מרחוק, בסו\"ה מרחוק ה׳ נראה לי. שנראית למשה אז מרחוק."],[3,"מאי משמע וכו׳:","שואל, מה משמע מכל המאמר הזה. ומשיב, שמשמע שאלו הצדיקים מטרם שיורדים לעולם הם נודעים לכל למעלה, וזהו לכל הצדיקים, וכל שכן משה (דהיינו כמ״ש באות שי״ג) ומשמע שנשמותיהם של צדיקים נמשכות ממקום עליון כי \u0003מבית לוי\u0004 רומז מחו\"ב עליונים. כמו שהעמדנו (באות שי״א) וסוד הדבר למדנו, שמשמע שיש אב ואם לנשמה, כמו שיש אב ואם לגוף בארץ, (כמ״ש באות שי״א) כי \u0003איש\u0004 זה ז״א, \u0003בת לוי,\u0004 זו היא המלכות, שמזווגם נולד נשמת משה."],[4,"ומשמע דבכל סטרין וכו׳:","ומשמע שבכל הצדדים בין למעלה שהם זו״ן, ובין למטה שהם או\"א דעוה״ז, הכל בא ונמצא מדכר ונוקבא, וכן העמידו סוד הכתוב, תוצא הארץ נפש חיה. \u0003הארץ,\u0004 זו היא כנסת ישראל, שהיא המלכות. \u0003נפש חיה\u0004 זו היא נפש של אדם הראשון, העליון. כמו שלמדנו. כי המלכות היא אם של נפשו דאדה״ר. בא ר׳ אבא ונשקו. אמר ודאי יפה אמרת, וכך הוא הכל."],[5,"זכאה חולקיה דמשה וכו׳:","אשרי חלקו של משה נביא הנאמן על כל שאר הנביאים שבעולם. משום זה כשנפטר מן העולם לא נתעסק ביה חוץ מהקב״ה, שהעלו למחיצתו. וע״כ עלה משה בנבואה עליונה ובמדרגות יקרות מכל נביאי העולם. ושאר הנביאים ראו מאחורי קירות רבים."],[6,"ויראני את יהושע הכהן הגדול:","שואל, מה ראה, ומשיב, שהיה עומד לפני המלאך ומתלבש בלבושים צואים, עד שיצא הכרוז ואמר, הסירו הבגדים הצואים מעליו. אמר ר׳ יצחק, כתוב כאן ועומד לפני המלאך. מהו לפני המלאך. היינו שהיה דן דיניו, אותו שכתוב בו, ואל תאמר לפני המלאך כי שגגה היא. שהוא המלכות. מהו משמיענו. היינו, שכל אדם שלא זכה בעולם הזה להתעטף בעטוף של מצוה, ולהתלבש בלבוש של מצוה, דהיינו בציצית, כשנכנס בעולם ההוא, עומד בלבוש מטונף, שאינו צריך להיות כך, ועומד עליו בדין."],[7,"ת״ח כמה לבושין וכו׳:","בוא וראה, כמה לבושים מזדמנים בעולם ההוא, ואותו האדם שלא זכה בעולם הזה בלבושים של מצוה, דהיינו בטלית בצצית, כשנכנס לעולם ההוא, מלבישים אותו בלבוש אחד הנודע לאדוני הגיהנם. ואותו הלבוש, אוי למי שנתלבש בו, כי כמה חוקרי הדין עתידים לאחוז בו, ומכניסים אותו לגיהנם. ושלמה המלך צוח ואמר, בכל עת יהיו בגדיך לבנים."]],[[0,"","וַתֵּרֶד בַּת פַּרְעֹה - זוֹהִי שֶׁבָּאָה מִצַּד שְׂמֹאל שֶׁל דִּין הַקָּשֶׁה, כְּמוֹ שֶׁנֶּאֱמַר לִרְחֹץ עַל הַיְאֹר. עַל הַיְאוֹר דַּוְקָא, וְלֹא עַל הַיָּם. וְאִם תֹּאמַר, הֲרֵי כָּתוּב (שמות יז) וּמַטְּךְ אֲשֶׁר הִכִּיתָ בּוֹ אֶת הַיְאֹר, וּמֹשֶׁה לֹא הִכָּה אֶלָּא בַּיָּם, וּקְרָאוֹ הַכָּתוּב יְאוֹר! אֶלָּא יְאוֹר הָיָה שֶׁהִכָּה אַהֲרֹן עַל יְדֵי מֹשֶׁה, וְשָׂמוֹ הַכָּתוּב שֶׁהוּא עָשָׂה."],[1,"","כְּמוֹ זֶה, (שם ז) וַיִּמָּלֵא שִׁבְעַת יָמִים אַחֲרֵי הַכּוֹת ה' אֶת הַיְאֹר. וְאַהֲרֹן הִכָּה. אֶלָּא (שעל זה) עַד שֶׁבָּא מִצַּד הַקָּדוֹשׁ בָּרוּךְ הוּא קְרָאוֹ הַכָּתוּב הַכּוֹת ה'. אַחַר כָּךְ קְרָאוֹ בַשֵּׁם שֶׁל מֹשֶׁה. וְנַעֲרֹתֶיהָ הֹלְכֹת - אוֹתָן שְׁאָר מֶרְכָּבוֹת שֶׁבָּאוֹת מִצַּד זֶה."],[2,"","וַתִּפְתַּח וַתִּרְאֵהוּ אֶת הַיֶּלֶד. וַתִּרְאֵהוּ?! וַתֵּרֶא הָיָה צָרִיךְ לוֹ לִכְתֹּב! מַה זֶּה וַתִּרְאֵהוּ? וַהֲרֵי אָמַר רַבִּי שִׁמְעוֹן, אֵין לְךְ דָּבָר בַּתּוֹרָה אוֹ אוֹת אַחַת בַּתּוֹרָה שֶׁאֵין בָּהּ סוֹדוֹת נִכְבָּדִים וְעֶלְיוֹנִים. אֶלָּא כָּךְ לָמַדְנוּ, רֹשֶׁם הַמֶּלֶךְ וְהַמַּלְכָּה נִמְצָא בּוֹ, וְהֵם רֹשֶׁם שֶׁל וָא\"ו הֵ\"א. מִיָּד - וַתַּחְמֹל עָלָיו וְגוֹ'. עַד כָּאן לְמַעְלָה. מִכָּאן וָהָלְאָה לְמַטָּה, פְּרָט לְפָסוּק זֶה שֶׁכָּתוּב וַתֵּתַצַּב אֲחֹתוֹ מֵרָחֹק. אָחוֹת שֶׁל מִי? אָחוֹת שֶׁל אוֹתוֹ שֶׁקָּרָא לִכְנֶסֶת יִשְׂרָאֵל אֲחוֹתִי, כְּמוֹ שֶׁנֶּאֱמַר (שיר ה) פִּתְחִי לִי אֲחוֹתִי. מֵרָחֹק, כְּמוֹ שֶׁנֶּאֱמַר (ירמיה לא) מֵרָחוֹק ה' נִרְאָה לִי."],[3,"","מַה מַּשְׁמָע? מַשְׁמָע שֶׁאוֹתָם צַדִּיקִים, עַד שֶׁלֹּא יָרְדוּ לָעוֹלָם, נוֹדָעִים הֵם לְמַעְלָה לְגַבֵּי הַכֹּל, וְכָל שֶׁכֵּן מֹשֶׁה. וּמַשְׁמָע שֶׁנִּשְׁמוֹת הַצַּדִּיקִים נִמְשָׁכוֹת מִמָּקוֹם עֶלְיוֹן, כְּמוֹ שֶׁבֵּאַרְנוּ. וְסוֹד הַדָּבָר לָמַדְנוּ, שֶׁמַּשְׁמָע שֶׁאָב וָאֵם יֵשׁ לַנְּשָׁמָה, כְּמוֹ שֶׁיֵּשׁ אָב וָאֵם לַגּוּף בָּאָרֶץ."],[4,"","וּמַשְׁמָע שֶׁבְּכָל הַצְּדָדִים, בֵּין לְמַעְלָה בֵּין לְמַטָּה, הַכֹּל בָּא וְנִמְצָא מִזָּכָר וּנְקֵבָה. וַהֲרֵי בֵּאֲרוּ הַסּוֹד, שֶׁכָּתוּב (בראשית א) תּוֹצֵא הָאָרֶץ נֶפֶשׁ חַיָּה. הָאָרֶץ - זוֹ כְּנֶסֶת יִשְׂרָאֵל. נֶפֶשׁ חַיָּה - נֶפֶשׁ אָדָם הָרִאשׁוֹן הָעֶלְיוֹן, כְּמוֹ שֶׁנִּתְבָּאֵר. בָּא רַבִּי אַבָּא וּנְשָׁקוֹ. אָמַר, וַדַּאי נָאֶה אָמַרְתָּ, וְכָּאן הוּא הַכֹּל."],[5,"","אַשְׁרֵי חֶלְקוֹ שֶׁל מֹשֶׁה נָבִיא הַנֶּאֱמָן עַל כָּל שְׁאָר נְבִיאֵי הָעוֹלָם. בִּגְלַל זֶה לֹא הִשְׁתַּדֵּל בּוֹ כְּשֶׁהִסְתַּלֵּק מֵהָעוֹלָם, רַק הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁהֶעֱלָהוּ לְפַרְגּוֹדוֹ. וְעַל כָּךְ עָלָה מֹשֶׁה בִּנְבוּאָה עֶלְיוֹנָה וּבִדְרָגוֹת נִכְבָּדוֹת מִכָּל נְבִיאֵי הָעוֹלָם, וּשְׁאָר הַנְּבִיאִים רָאוּ אַחַר כְּתָלִים גְּדוֹלִים."],[6,"","וַיַּרְאֵנִי אֶת יְהוֹשֻׁעַ הַכֹּהֵן הַגָּדוֹל (זכריה ג). מָה רָאָה? שֶׁהָיָה עוֹמֵד לִפְנֵי מַלְאָךְ וּמִתְלַבֵּשׁ בִּלְבוּשִׁים מְלֻכְלָכִים, עַד שֶׁיָּצָא הַכָּרוֹז וְאָמַר: הָסִירוּ הַבְּגָדִים הַצֹּאִים מֵעָלָיו. אָמַר רַבִּי יִצְחָק, כָּתוּב כָּאן וְעֹמֵד לִפְנֵי הַמַּלְאָךְ. מַה זֶּה לִפְנֵי הַמַּלְאָךְ? שֶׁהָיָה דָּן דִּינוֹ, אוֹתוֹ שֶׁכָּתוּב בּוֹ (קהלת ה) וְאַל תֹּאמַר לִפְנֵי הַמַּלְאָךְ כִּי שְׁגָגָה הִיא. מַה בָּא לְהַשְׁמִיעֵנוּ? שֶׁכָּל בֶּן אָדָם שֶׁלֹּא זוֹכֶה בָּעוֹלָם הַזֶּה לְהִתְעַטֵּף בְּעִטּוּף מִצְוָה וּלְהִתְלַבֵּשׁ בִּלְבוּשׁ מִצְוָה, כְּשֶׁנִּכְנָס בָּעוֹלָם הַהוּא עוֹמֵד בִּלְבוּשׁ טִנֹּפֶת שֶׁלֹּא צָרִיךְ, וְעוֹמֵד בַּדִּין עָלָיו."],[7,"","בֹּא וּרְאֵה, כַּמָּה לְבוּשִׁים מִזְדַּמְּנִים בְּאוֹתוֹ עוֹלָם, וְאוֹתוֹ הָאִישׁ שֶׁלֹּא זוֹכֶה בָּעוֹלָם הַזֶּה בִּלְבוּשֵׁי מִצְוָה, כְּשֶׁנִּכְנָס לָעוֹלָם הַהוּא מַלְבִּישִׁים אוֹתוֹ בִּלְבוּשׁ נוֹדָע אֶחָד לִפְנֵי בַּעֲלֵי הַגֵּיהִנֹּם, וְאוֹתוֹ לְבוּשׁ אוֹי לְמִי שֶׁמִּתְלַבֵּשׁ בּוֹ. שֶׁהֲרֵי כַּמָּה שׁוֹמְרֵי הַחֻקִּים עֲתִידִים לֶאֱחֹז בּוֹ, וּמַכְנִיסִים אוֹתוֹ לַגֵּיהִנֹּם. וּשְׁלֹמֹה הַמֶּלֶךְ צוֹוֵחַ וְאוֹמֵר: (קהלת ט) בְּכָל עֵת יִהְיוּ בְגָדֶיךְ לְבָנִים."]]],[["תָּאנָא בְּרָזָא דְּסִפְרָא דִּצְנִיעוּתָא, אַרְבַּע מַלְכִין נָפְקִין לְקַדְמוּת אַרְבַּע. בְּהוּ תַּלְיָין כַּעֲנָבִים בְּאִתְכְּלָא, צְרִירָן בְּהוּ ז' רְהִיטִין, סָהֲדִין סַהֲדוּתָא. וְלָא קַיְימִין בְּדוּכְתַּיְיהוּ.","\u0003רעיא מהימנא\u0004 צִּיצִּית פִּקּוּדָא דָּא אִיהוּ לְאַדְכָּרָא כָּל פִּקּוּדֵי אוֹרַיְיתָא בְגִינָהּ כְּמָה דְאַתְּ אָמֵר וּרְאִיתֶם אֹתוֹ וּזְכַרְתֶּם אֶת כָּל מִצְּוֹת יְיָ וַעֲשִׂיתֶם אֹתָם דָּא אִיהוּ סִימָנָא דְּמַלִכָּא לְאַדְכָּרָא וּלְמַעַבְּדָא.","כְּתִֹיב (שמות כ״ח:ל״ו) וְעָשִׂיתָ צִּיץ זָהָב, וְהָא אוֹקִימְנָא רָזָא דְּצִּיץ לְאִתְעַטְרָא בֵּיהּ כַּהֲנָא רַבָּא. וְדָא אִיהוּ צִּיץ, לְאִסְתַּכְּלָא בֵּיהּ עַיְינִין, דְּאִיהוּ סִימַן דְּעָלְמָא עִלָּאָה, דְּאִתְעַטָר בֵּיהּ כַּהֲנָא רַבָּא.","וּבְגִין כַּךְ אִסְתַּכְּלוּתָא דִּילֵיהּ מְכַפְּרָא עַל עַזּוּת פָּנִים, דְּלָא קַיְּימָא לְקַמֵּיהּ, אֶלָּא פָּנִים דְּקְשׁוֹט, רָזָא דְּכָל אִינּוּן פָּנִים עִלָּאִין, דְּאִינּוּן פָּנִים דִּקְשׁוֹט, פָּנִים דֶּאֱמֶת. דִּכְלִילָן בֶּאֱמֶת דְּיַעֲקֹב.","צִּיצִּית אִיהוּ נוּקְבָא, רָזָא דְּעַלְמָא תַּתָּאָה. אִסְתַּכְּלוּתָא לְאַדְכְּרָא. צִּיץ דְּכַר, צִּיצִּית נוּקְבָא, וְדָא לְכָל בַר נַשׁ. צִּיץ לְכַהַנָא.","וְתָנֵינָן, אָסוּר לְאִסְתַּכְּלָא בִּשְׁכִינְתָּא, בְּגִין כָּךְ אִית תְּכֵלָא, בְּגִין דִּתְכֵלֶת, אִיהוּ כֻּרְסְיָיא לְבֵית דָּוִד, וְתִקּוּנָא דִּילֵיהּ. וְדָא אִיהוּ דַּחֲלָא מִן קֳדָם יְיָ לְדַחֲלָא מֵהַהוּא אֲתָר. וְעַל דָּא וּרְאִיתֶם אוֹתוֹ וּזְּכַרְתֶּם אֶת כָּל מִצְּוֹת יְיָ, וְדָא כֻּרְסְיָיא דְּדַיְינִין בָּהּ דִּינֵי נְפָשׁוֹת, כְּמָה דְּאוֹקְמוּהָ, דְּכָל גַּוְונִין טָבִין לְחֶלְמָא, בַּר תְּכֵלָא, דְּאִיהוּ כֻּרְסְיָיא דְּסָלִיק בְּדִינָא דִּנְפָשׁוֹת.","כְּתִיב וְנָתְנוּ עַל צִּיצִּית הַכָּנָף פְּתִיל תְּכֵלֶת. וְנָתְנוּ עַל הַכָּנָף לָא כְּתִיב, אֶלָּא וְנָתְנוּ עַל צִּיצִּית. דְּדָא אִיהוּ דְּחָפֵי עַל שְׁאַר חוּטִין.","וּרְאִיתֶם אוֹתוֹ וּזְּכַרְתֶּם, וּכְתִיב, (דברים כ״ה:י״ז) זָכוֹר אֵת אֲשֶׁר עָשָׂה לְךָ עֲמָלֵק. מַאי טַעְמָא דָּא. אֶלָּא לִבְרָא דְּפָרִיץ גִּדְרָא, וּנְשָׁכֵיהּ כַּלְבָּא. כָּל זִמְנָא דַּאֲבוֹי בָּעֵי לְאוֹכָחָא לִבְרֵיהּ, הֲוָה אָמַר הֲוִי דָּכִיר כַּד נָשִׁיךְ לָךְ כַּלְבָא. אוּף הָכָא וּרְאִיתֶם אוֹתוֹ וּזְּכַרְתֶּם, דְּדָא אִיהוּ אֲתָר דְּסַלְּקִין נִשְׁמָתִין לְמֵידָן.","כְּגַוְונָא דָּא, (במדבר כ״א:ח׳) וְהָיָה כָּל הַנָּשׁוּךְ וְרָאָה אֹתוֹ וָחָי, אֲמַאי. אֶלָּא כַּד סָלִיק לְעֵינוֹי, וְחָמֵי דִּיּוּקְנָא דְּהַהוּא דְּנָשִׁיךְ לֵיהּ, הֲוָה דָּחִיל, וְצַּלֵּי קֳדָם יְיָ, וַהֲוָה יָדַע דְּאִיהוּ עוֹנְשָׁא דְּחַיָּיבַיָּא. כָּל זְמַן דִּבְרָא חָמֵי רְצּוּעָה דַּאֲבוֹי, דָּחִיל מֵאֲבוֹי. אִשְׁתְּזִיב מִרְצּוּעָה, אִשְׁתְּזִיב מִכֹּלָּא. מַאן גָּרִים לֵיהּ לְאִשְׁתְּזָבָא. הַהוּא דְּחָמֵי בְּעֵינוֹי הַהוּא רְצּוּעָה, הַהוּא רְצּוּעָה גָרִים לֵיהּ לְאִשְׁתַּזְבָא. וְעַל דָּא וְרָאָה אֹתוֹ וָחַי, חַמֵי רְצּוּעָה דְּאַלְקֵי לֵיהּ, וְאִיהוּ עָבִיד לֵיהּ לְאִשְׁתְּזָבָא. אוּף הָכָא וּרְאִיתֶם אוֹתוֹ וּזְּכַרְתֶּם, וַעֲשִׂיתֶם וַדַּאי. וְאִי לָאו, הָא רְצּוּעָה, דְּהַאי יִגְרוֹם לְכוֹן, לְמֶהֱוִי תָּבִין לְפוּלְחָנָא דִּילִי תָּדִיר, וּכְדֵין וַעֲשִׂיתֶם.","וְלֹא תָתוּרוּ אַחֲרֵי לְבַבְכֶם, יִמְנַע מִנְּכוֹן בִּישִׁין אֹרְחִין אַחֲרָנִין, וַדַּאי, לֹא תָתוּרוּ, וְלָא תַעֲבְדוּ בִּישִׁין. וְעַל דָּא סַלְּקָא גּוָֹון תְּכֵלָא. דָּא תְּכֵלֶת, דַּמְיָא לְכִּסֵּא הַכָּבוֹד, מַה כִּסֵּא הַכָּבוֹד, עָבִיד לְבַר נָשׁ לְמֵהַךְ לְאָרְחָא דְּמֵישָׁר, לְדַכְּאָה לֵיהּ. אוּף הַאי תְּכֵלֶת, עָבִיד לְבַּר נָשׁ לְמֵהַךְ בְּאֹרַח מֵישָׁר, וַדַּאי דְּכֹלָּא אִית לְדַחֲלָא מֵהַאי אֲתָר, לְמֵיהַךְ בְּמֵישָׁר.","כְּתִיב (ישעיהו כ״ד:ט״ז) מִכְּנַף הָאָרֶץ זְמִירוֹת שָׁמַעְנוּ צְּבִי לַצַּדִיק וָאוֹמַר רָזִי לִי וְגוֹ'. מִכְּנַף הָאָרֶץ, דָּא כָּנָף דְּצִּיצִּית, דְּאִיהוּ כָּנָף הָאָרֶץ. זְמִירוֹת שָׁמַעְנוּ, אִלֵּין שְׁאַר חוּטִין, דְּנָפְקִין וְתַּלְיָין מֵאֲתָר עִלָּאָה, גּוֹ אִינּוּן שְׁבִילִין עִלָּאִין, דְּנָפְקִין מֵחָכְמָה עִלָּאָה. צְּבִי לַצַּדִּיק, דָּא צַּדִּיק חַי הָעוֹלָמִים, דְּאִינּוּן חוּטִין אִינּוּן שְׁפִּירוּ דִּילֵיהּ, דְּהָא מִנֵּיהּ נָפְקִין, וְכָל חוּטָא כְּלִילָא בִּתְרֵין סִטְרִין. וְכַד אִסְתַּכַּלְנָא, אֲמֵינָא רָזִי לִי רָזִי לִי, דְּהָא מִגּוֹ רָזָא עִלָּאָה דְּכָל מְהֵימְנוּתָא נָפְקִין. וְכַד אִסְתַּכַּלְנָא בִּתְכֵלֶת, וַחֲמֵינָא רְצּוּעָה לְאַלְקָאָה, אֲתָר דְּחִילוּ לְמִדְחַל, אֲמֵינָא אוֹי לִי, דִּבְנֵי נָשָׁא לָא יַדְעֵי לְאַשְׁגְּחָא וּלְאִסְתַּכְּלָא עַל מַה מִתְעָנְשִׁין לְשַׁקְרָא, בְּהַאי בּוֹגְדִים בָּגָדוּ, דְּהָא קוֹרִין קְרִיאַת שְׁמַע בְּלָא צִּיצִּית, וְסָהֲדִין סַהֲדוּתָא דְּשִׁקְרָא, וְאִלֵּין אִינּוּן בּוֹגְדִים דְּבָּגָדוּ, מְשַׁקְּרֵי דְּגַרְמַיְיהוּ.","וּבֶגֶד בּוֹגְדִים בָּגָדוּ, לְבוּשָׁא דִּלְהוֹן בְּלָא צִּיצִּית, אִקְרֵי בֶּגֶד בּוֹגְדִים. לְבוּשָׁא דְּאִינּוּן בּוֹגְדִים דְּבָגְדוּ, דִּמְשַׁקְרֵי וְסָהֲדִין סַהֲדוּתָא דְּשִׁקְרָא בְּכָל יוֹמָא. וַוי לוֹן, וַוי לְנַפְשֵׁיהוֹן, דְּסַלְקֵי בְּהַהוּא כֻּרְסְיָיא דְּתִכְלָא לְמֵידָן. וְעָלַיְיהוּ כְּתִיב, (תהילים ק״א:ז׳) דּוֹבֵר שְׁקָרִים לֹא יִכּוֹן לְנֶגֶד עֵינָי, הַהוּא בֶּגֶד דִּלְהוֹן אִשְׁתְּמוֹדַע לְגַבֵּי כָּל מָארֵיהוֹן דְּדִינִין. וַוי לוֹן, דְּלֵית לוֹן חוּלָקָא בְּעָלְמָא דְּאָתֵי. זַכָּאִין אִינּוּן צַּדִּיקַיָּיא, דְּמַלְבּוּשֵׁיהוֹן וְתִקּוּנֵיהוֹן אִשְׁתְּמוֹדְעָן לְעֵילָּא, לְאוֹטָבָא לוֹן בְּהַאי עָלְמָא וּבְעָלְמָא דְּאָתֵי. (ע\"כ) (שמות מ\"ג ע\"א והיה לאות וכו')","פִּקּוּדָא דָּא מִצְוַת צִיצִית, כָּלִיל תְּכֵלֶת וְלָבָן, דִּינָא וְרַחֲמֵי בְּנוּרָא. אֶשָּׁא חִוָּורָא לָא אָכִיל, תְּכֵלָא אָכִיל וְשָׁצֵי. (דברי הימים ב ז׳:א׳) וַתֹּאכַל הָעוֹלָה, חִוָּור מִימִינָא, תְּכֵלֶת מִשְּׂמָאלָא. עַמּוּדָא דְּאֶמְצָעִיתָא יִחוּד בֵּין תַּרְוַיְיהוּ, יָרוֹק. וּבְגִין דָּא אוּקְמוּהָ מָארֵי מַתְנִיתִין, מֵאֵימָתַי קוֹרִין אֶת שְׁמַע בְּשַׁחֲרִית, מִשֶּׁיַּכִּיר בֵּין תְּכֵלֶת לְלָבָן. וּבְגִין דָּא תַּקִּינוּ פָּרָשַׁת צִיצִית לְמִקְרֵי לָהּ בְּיִחוּדָא."],[[0,"תאנא ברזא דספרא וכו׳:","למדנו בסוד ספרא דצניעותא, (אות ס״ו ס״ז) ארבעה מלכים שהם חגת״ם דז״א, יוצאים ונאצלים לפני ארבעה, שהם חכמה, ובינה, וימין דדעת, ושמאל דדעת. חסד מחכמה, גבורה מבינה, ת״ת מימין דדעת, מלכות משמאל דדעת. וחגת״ם תלוים בחב״ד כענבים באשכול. כלומר שנמשכים ויונקים מהם, כל אחד מהבחינה שכנגדו. ונכללים בהם, בחגת״ם, ז׳ רצים שבד' ספירות חגת״ם, יש ז״ס חג״ת נהי״מ. מעירים עדות, שמגלים הארת חכמה שנקראת עדות, ואינם עומדים במקומם, בשעה שמעידים עדות. כלומר בשעה שמגלים הארת חכמה אינם עומדים במקומם, בז״א, אלא במקום המלכות. שאין חכמה מגולה אלא במלכות (כנ״ל ב״א דף רע״ו ד\"ה ועוד כמה)."],[0,"","פירוש. \u0003ארבע מלכין,\u0004 שהם חגת״ם דז״א, הם רומזים על ד׳ ציצית, ודי' כנפות שהציצית תלויות בהם, הם רומזים על ד׳ בחינות מוחין, חו״ב, וימין דדעת, ושמאל דדעת, שחגת״ם, שהם ד׳ ציצית, תלויות בהם כענבים באשכול, וז׳ כריכות שאנו עושים בכל ציצה, רומזים על ז״ס הכלולות בחגת״ם. ואע״פ שאלו ד׳ מלכים חגת״ם, הם בז״א, וציצית הם בחינת מלכות, ולא ז״א. הטעם הוא, מפני שחגת\"ם דז״א אינם מאירים בהארת החכמה במקומם עצמם בז״א, אלא במקום המלכות, וע״כ מרומזים במקום המלכות שה״ס ציצית. וז״ש, \u0003ולא קיימין בדוכתייהו.\u0004 כי הן כנפי הבגדים והן הציצית והן הכריכות, הכל הוא בחינת מלכות. כי אין להם גילוי במקום ז״א. ועי׳ להלן (אות של״ג)."],[1,"ציצית פקודא דא וכו׳:","הציצית, מצוה זו היא לזכור כל מצות התורה בשבילה. כש״א וראיתם אותו וזכרתם את כל מצות ה׳, ועשיתם אותם. זה הוא סימן המלך לזכור ולעשות."],[2,"כתיב, ועשית ציץ וכו׳:","כתוב, ועשית ציץ זהב, והרי העמדנו סוד הציץ לעטר בו כהן גדול. וזה הוא שנקרא \u0003ציץ,\u0004 שפירושו ראיה, מלשון הציץ ונפגע (חגיגה יד) שיסתכלו בו העינים. שהוא סימן של עולם העליון שהוא ז״א, ששם סוד ההשפעה של הארת החכמה המכונה הסתכלות עינים שנתעטר בו הכהן הגדול."],[3,"ובגין כך אסתכלותא וכו':","ומשום זה ההסתכלות שלו, של הציץ, מכפרת על עזות פנים, משום שאין עומד לפניו, אלא פנים של אמת, כי הסוד של כל אלו פנים העליונים, שה״ס הארת חכמה המלובשת בחסדים, שנקרא פנים. שהם פנים של אמת, היינו פנים של אמת הכלולים באמת של יעקב, שהוא ז״א. בסו\"ה תתן אמת ליעקב."],[4,"ציצית איהי נוקבא וכו׳:","ציצית היא נקבה, שהיא סוד עולם התחתון, דהיינו מלכות. שהיא הסתכלות לזכור. דהיינו כמ״ש, וראיתם וגו' וזכרתם. ציץ הוא זכר, דהיינו ז״א. ציצית היא נקבה, שהיא מלכות. וזה ציצית, היא לכל אדם. ציץ, הוא רק לכהן."],[5,"ותנינן אסור לאסתכלא וכו׳:","ולמדנו, אסור להסתכל בשכינה. משום זה יש תכלת בציצית, משום שתכלת הוא כסא לבית דוד שהוא המלכות, ותקון שלו. וזה הוא כדי לירא מפני ה', לירא ממקום ההוא, וע״כ, וראיתם אותו וזכרתם את כל מצות ה'. ותכלת, הוא כסא שדנים בו דיני נפשות, כמו שהעמידוהו, שכל הצבעים טובים לחלום חוץ מתכלת, שהוא כסא העולה בדיני נפשות."],[5,"","פירוש. תכלת, ה״ס התכללות בגוון אוכמא, שהיא כח המסך דנקודה דמנעולא שה\"ס מלכות דצמצום א׳ הבלתי ממותקת בבינה, וכיון שיש התכללות הזו בתכלת, ע״כ ה״ס כסא, שדנים בה דיני נפשות, שהיא שומרת על המלכות, שלא להמשיך החכמה ממנה ממעלה למטה, ומי שממשיך החכמה ממעלה למטה היא מתעוררת עליו ולוקחת נשמתו. וז״ש, \u0003אסור לאסתכלא בשכינתא,\u0004 החכמה נקראת הסתכלות עינים, שאסור להמשיך אותה ממעלה למטה כנ״ל, \u0003בגין כך אית תכלא,\u0004 משום זה יש תכלת בצצית, בגין \u0003דתכלת איהו כרסיא לבית דוד,\u0004 שהוא כסא דין אל המלכות הנקראת בית דוד, \u0003ותקונא דיליה,\u0004 שהתכלת הוא תקון המלכות, לשמרה שלא ימשיכו ממנה החכמה, ממעלה למטה. וכיון שסוד הציצית ה\"ס הארת החכמה, כנ״ל בסוד ציץ וציצית, ע״כ צריכים לשום עליהם תכלת לשמירה. שלא ימשכוה רק ממטה למעלה. וז״ש, \u0003וע״ד, וראיתם אותו וזכרתם את כל מצות ה׳\u0004 וגו׳ שמפחד התכלת תזכרו לקיים כל מצות ה׳ כהלכתן. ועי׳ היטב לעיל (אות קכ\"ד) בהסולם, ששם הארכנו."],[6,"כתיב, ונתנו על וגו׳:","כתוב, ונתנו על ציצית הכנף פתיל תכלת. ונתנו על הכנף לא כתיב, אלא ונתנו על ציצית, כי זה הוא המכסה על שאר החוטים. כלומר, שציצית, רומזת על הארת חכמה, ע״כ רק הם צריכים כיסוי ושמירה מן פתיל התכלת, וע״כ כתוב ונתנו על ציצית."],[7,"וראיתם אותו וזכרתם:","הוא כמו שכתוב, זכור אשר עשה לך עמלק. מה זה הטעם. אלא בדומה, לבן שפרץ גדר ונשכו כלב. כל פעם שאביו רוצה להוכיח את בנו, הוא אומר, הוי זוכר, כשנשך אותך הכלב. אף כאן וראיתם אותו וזכרתם. כי התכלת הוא מקום שהנשמות עולות בו לדון אותם. וע״כ הוא דומה להכתוב, זכור אשר עשה לך עמלק."],[8,"כגוונא דא, והיה וגו׳:","כעין זה, והיה כל הנשוך וראה אותו וחי. למה. אלא, כשמעלה לפני עיניו ורואה הצורה של אותו שנשכו הי׳ מפחד והתפלל לפני ה׳. והי׳ יודע שזה היא עונש לרשעים. כל זמן שהבן רואה הרצועה של אביו הוא מפחד מאביו, ניצל מן הרצועה ניצל מכל. מי גרם לו להנצל, הוא מה שראה בעיניו אותה רצועה, נמצא שאותה הרצועה גרמה לו להנצל. וע\"כ, וראה אותו וחי, ראה הרצועה שהכה אותו, והיא גורמת לו להנצל. אף כאן, וראיתם אותו וזכרתם, ועשיתם ודאי. ואם לא, הרי הרצועה, דהיינו התכלת, שזה יגרום לכם שתשובו אל העבודה שלי תמיד. ואז \u0003ועשיתם.\u0004"],[9,"ולא תתורו אחרי לבבכם:","שראית התכלת תמנע מכם דרכים רעים אחרים, ודאי לא תתורו ולא תעשו רעות. וע״כ עולה על הציצית מראה תכלת. תכלת זה, דומה לכסא הכבוד. מה כסא הכבוד עושה את האדם שילך בדרך הישר לטהר אותו, כן תכלת זו עושה את האדם ללכת בדרך הישר, ודאי שלכל אדם יש לפחד ממקום זה ללכת בדרך הישר."],[10,"כתיב, מכנף הארץ וגו׳:","כתוב, מכנף הארץ זמירות שמענו צבי לצדיק ואומר רזי לי וגו׳. \u0003מכנף הארץ,\u0004 זהו הכנף של ציצית, שהוא כנף הארץ, דהיינו כנף המלכות שנקראת ארץ. זמירות שמענו אלו כל החוטים היוצאים ותלוים ממקום עליון, תוך אלו השבילים העליונים היוצאים מחכמה עליונה, כי החוטים, ה״ס חגת״מ דז״א, היוצאים מחב״ד העליונים (כנ״ל אות שכ״ג ע״ש) \u0003צבי לצדיק,\u0004 דא צדיק חי העולמים, שהוא יסוד דז״א, שאלו החוטים דציצית שהם חגת״ם דז״א, הם היופי שלו. משום שממנו יצאו ונתנו אל המלכות. וכל חוט כלול בב׳ צדדים, דהיינו מחסדים וחכמה, שהם ימין ושמאל. וכשאני מסתכל אני \u0003אומר, רזי לי רזי לי.\u0004 כי מתוך סוד העליון של כל האמונה הם יוצאים. שהם כללות כל אורות המלכות, הנקראת אמונה. וכשאני מסתכל בתכלת, ואני רואה רצועה להכות, שהוא מקום היראה כדי לירא, אני אומר אוי לי שבני אדם אינם יודעים להשגיח ולהסתכל על מה הם נענשים לשקר, בזה \u0003בוגדים בגדו.\u0004 כי קוראים קריאת שמע בלא ציצית, ומעידים עדות שקר, ואלו הם בוגדים שבגדו. שמשקרים בעצמם."],[11,"ובגד בוגדים בגדו וכו׳:","הלבוש שלהם כשהוא בלא ציצית נקרא \u0003בגד בוגדים,\u0004 דהיינו, לבוש של אלו בוגדים שבגדו שמשקרים ומעידים עדות שקר בכל יום. אוי להם אוי לנפשם, כי עולים אל כסא התכלת לדון אותם, ועליהם כתוב, דובר שקרים לא יכון לנגד עיני. בגד ההוא שלהם נודע ליל בעלי הדין. אוי להם שאין להם חלק בעולם הבא. אשריהם הצדיקים שמלבושיהם ותקוניהם נודעים למעלה להטיב להם בעולם הזה ובעולם הבא."],[12,"פקודא דא מצות וכו׳:","מצוה זו היא מצות ציצית, כלולה תכלת ולבן, דהיינו ד׳ חוטים לבנים, וחוט א׳ של תכלת, שהם דין ורחמים באש. אש לבנה אינה אוכלת, תכלת אוכלת ומכלה את הכל. ותאכל העולה, היינו אש לבנה מימין, ואש תכלת משמאל. עמוד האמצעי, דהיינו קו האמצעי המיחד ימין ושמאל, הוא יחוד בין שתיהן, והוא אש ירוקה. ומשום זה העמידו בעלי המשנה, מאימתי קורין את שמע בשחרית, משיכיר בין תכלת ללבן. דהיינו שיבחין בין דין לחסד, כי אז יתדבק בחסד, שה״ס קריאת שמע. ומשום זה התקינו פרשת ציצית לקרות אותה ביחוד (חסר הסיום). (ע״כ רעיא מהימנא)"]],[[0,"","לָמַדְנוּ בְּסוֹד סִפְרָא דִצְנִיעוּתָא, אַרְבָּעָה מְלָכִים יוֹצְאִים לְמוּל אַרְבָּעָה. תְּלוּיִים בָּהֶם כַּעֲנָבִים בְּאֶשְׁכּוֹל, צְרוּרִים בָּהֶם שִׁבְעָה רָצִים, מְעִידִים עֵדוּת, וְלֹא עוֹמְדִים בִּמְקוֹמָם."],[1,"","צִיצִית, מִצְוָה זוֹ הִיא לְהַזְכִּיר כָּל מִצְווֹת הַתּוֹרָה בִּשְׁבִילָהּ, כְּמוֹ שֶׁנֶּאֱמַר וּרְאִיתֶם אֹתוֹ וּזְכַרְתֶּם אֶת כָּל מִצְות ה' וַעֲשִׂיתֶם אֹתָם (במדבר טו). זֶהוּ סִימַן הַמֶּלֶךְ לְהַזְכִּיר וְלַעֲשׂוֹת."],[2,"","כָּתוּב (שמות כח) וְעָשִׂיתָ צִּיץ זָהָב, וַהֲרֵי בֵּאַרְנוּ - סוֹד הַצִּיץ לְהִתְעַטֵּר בּוֹ כֹּהֵן גָּדוֹל. וְזֶהוּ צִיץ לְהִסְתַּכֵּל בּוֹ בָּעֵינַיִם, שֶׁהוּא סִימָן שֶׁל עוֹלָם הָעֶלְיוֹן שֶׁהִתְעַטֵּר בּוֹ כֹּהֵן גָּדוֹל."],[3,"","וּמִשּׁוּם זֶה הִסְתַּכְּלוּתוֹ מְכַפֶּרֶת עַל עַזּוּת פָּנִים, שֶׁלֹּא עוֹמֶדֶת לְפָנָיו אֶלָּא פְּנֵי אֱמֶת, סוֹד שֶׁל כָּל אֵלּוּ הַפָּנִים הָעֶלְיוֹנִים, שֶׁהֵם פְּנֵי אֱמֶת, פָּנִים שֶׁל אֱמֶת, שֶׁכְּלוּלִים בָּאֱמֶת שֶׁל יַעֲקֹב."],[4,"","צִיצִית הִיא נְקֵבָה, סוֹד עוֹלַם הַתַּחְתּוֹן, הִסְתַּכְּלוּת לְהַזְכִּיר. צִיץ זָכָר. צִיצִית נְקֵבָה, וְזֶה לְכָל אָדָם. צִיץ לַכֹּהֵן."],[5,"","וְשָׁנִינוּ, אָסוּר לְהִסְתַּכֵּל בַּשְּׁכִינָה, בִּגְלַל זֶה יֵשׁ תְּכֵלֶת, מִשּׁוּם שֶׁתְּכֵלֶת הִיא כִּסֵּא לְבֵית דָּוִד וְתִקּוּנוֹ. וְזֶהוּ פַּחַד מִלִּפְנֵי ה' לִפְחֹד מֵאוֹתוֹ מָקוֹם. וְעַל זֶה וּרְאִיתֶם אֹתוֹ וּזְכַרְתֶּם אֶת כָּל מִצְות ה'. וְזֶה הַכִּסֵּא שֶׁדָּנִים בּוֹ דִּינֵי נְפָשׁוֹת, כְּמוֹ שֶׁפֵּרְשׁוּהָ, וְכָל הַגְּוָנִים טוֹבִים לַחֲלוֹם, פְּרָט לִתְכֵלֶת, שֶׁהוּא כִּסֵּא שֶׁעוֹלֶה בְּדִין הַנְּפָשׁוֹת."],[6,"","כָּתוּב וְנָתְנוּ עַל צִיצִת הַכָּנָף פְּתִיל תְּכֵלֶת. וְנָתְנוּ עַל הַכָּנָף לֹא כָתוּב, אֶלָּא וְנָתְנוּ עַל צִיצִת. שֶׁזֶּהוּ שֶׁמְּכַסֶּה עַל שְׁאָר הַחוּטִים."],[7,"","וּרְאִיתֶם אֹתוֹ וּזְכַרְתֶּם. וְכָתוּב (דברים כה) זָכוֹר אֵת אֲשֶׁר עָשָׂה לְךְ עֲמָלֵק. מָה הַטַּעַם זֶה? אֶלָּא מָשָׁל לְבֵן שֶׁפָּרַץ גָּדֵר וּנְשָׁכוֹ כֶלֶב - כָּל זְמַן שֶׁאָבִיו רוֹצֶה לְהוֹכִיחַ אֶת בְּנוֹ, הָיָה אוֹמֵר: זָכוֹר כְּשֶׁנָּשַׁךְ אוֹתְךְ הַכֶּלֶב! גַּם כָּאן - וּרְאִיתֶם אֹתוֹ וּזְכַרְתֶּם, שֶׁזֶּהוּ מָקוֹם שֶׁעוֹלוֹת הַנְּשָׁמוֹת לְהִדּוֹן."],[8,"","כְּמוֹ זֶה - (במדבר כא) וְהָיָה כָּל הַנָּשׁוּךְ וְרָאָה אֹתוֹ וָחָי. לָמָּה? אֶלָּא כְּשֶׁמַּעֲלֶה אֶת עֵינָיו וְרוֹאֶה דְמוּת אוֹתוֹ שֶׁנְּשָׁכוֹ, הָיָה פּוֹחֵד וּמִתְפַּלֵּל לִפְנֵי ה', וְהָיָה יוֹדֵעַ שֶׁהוּא עֹנֶשׁ הָרְשָׁעִים. כָּל זְמַן שֶׁהַבֵּן רוֹאֶה רְצוּעַת אָבִיו, פּוֹחֵד מֵאָבִיו. נִצּוֹל מֵהָרְצוּעָה - נִצּוֹל מֵהַכֹּל. מִי גָרַם לוֹ לְהִנָּצֵל? זֶה שֶׁרָאָה בְעֵינָיו אוֹתָהּ רְצוּעָה - אוֹתָהּ רְצוּעָה גָרְמָה לוֹ לְהִנָּצֵל. וְלָכֵן, וְרָאָה אֹתוֹ וָחָי. רָאָה רְצוּעָה שֶׁמַּלְקָה אוֹתוֹ, וְהִיא עָשְׂתָה לוֹ לְהִנָּצֵל. גַּם כָּךְ וּרְאִיתֶם אֹתוֹ וּזְכַרְתֶּם - וַעֲשִׂיתֶם וַדַּאי. וְאִם לֹא - הֲרֵי הָרְצוּעָה, שֶׁזּוֹ תִגְרֹם לָכֶם לָשׁוּב לַעֲבוֹדָתִי תָמִיד, וְאָז וַעֲשִׂיתֶם."],[9,"","וְלֹא תָתוּרוּ אַחֲרֵי לְבַבְכֶם, יִמְנַע מִכֶּם דְּרָכִים רָעִים אֲחֵרִים, וַדַּאי לֹא תָתוּרוּ וְלֹא תַעֲשׂוּ רָעוֹת. וְעַל זֶה עוֹלֶה גָוֶן תְּכֵלֶת. זוֹ תְכֵלֶת דּוֹמָה לְכִסֵּא הַכָּבוֹד. מַה כִּסֵּא הַכָּבוֹד עוֹשֶׂה אֶת הָאָדָם לָלֶכֶת בְּדֶרֶךְ יָשָׁר לְזַכּוֹתוֹ, גַּם תְּכֵלֶת זוֹ עוֹשָׂה אֶת הָאָדָם לָלֶכֶת בְּדֶרֶךְ יָשָׁר. וַדַּאי שֶׁהַכֹּל יֵשׁ לִפְחֹד מִמָּקוֹם זֶה לָלֶכֶת יָשָׁר."],[10,"","כָּתוּב (ישעיה כד) מִכְּנַף הָאָרֶץ זְמִרֹת שָׁמַעְנוּ פְּרִי לַצַּדִּיק וָאֹמַר רָזִי לִי וְגוֹ'. מִכְּנַף הָאָרֶץ - זֶה כְּנַף הַצִּיצִית, שֶׁהוּא כְּנַף הָאָרֶץ. זְמִרֹת שָׁמַעְנוּ - אֵלּוּ שְׁאָר הַחוּטִים שֶׁיּוֹצְאִים וּתְלוּיִים מִמָּקוֹם עֶלְיוֹן תּוֹךְ אוֹתָם שְׁבִילִים עֶלְיוֹנִים שֶׁיּוֹצְאִים מֵחָכְמָה עֶלְיוֹנָה. צְבִי לַצַּדִּיק - זֶה צַדִּיק חַי הָעוֹלָמִים, שֶׁאוֹתָם חוּטִים אֵלּוּ יָפְיוֹ, שֶׁהֲרֵי מִמֶּנּוּ יוֹצְאִים, וְכָל חוּט כָּלוּל בִּשְׁנֵי צְדָדִים. וּכְשֶׁהִסְתַּכַּלְתִּי, אָמַרְתִּי: רָזִי לִי רָזִי לִי. שֶׁהֲרֵי מִתּוֹךְ סוֹד עֶלְיוֹן שֶׁל כָּל הָאֱמוּנָה יוֹצְאִים. וּכְשֶׁהִסְתַּכַּלְתִּי בַתְּכֵלֶת וְרָאִיתִי רְצוּעָה לְהַלְקוֹת, מָקוֹם יִרְאָה לִפְחֹד, אָמַרְתִּי: אוֹי לִי שֶׁבְּנֵי אָדָם לֹא יוֹדְעִים לְהַשְׁגִּיחַ וּלְהִסְתַּכֵּל עַל מַה נֶּעֱנָשִׁים לַשֶּׁקֶר. בָּזֶה בֹּגְדִים בָּגָדוּ, שֶׁהֲרֵי קוֹרְאִים קְרִיאַת שְׁמַע לְלֹא צִיצִית וּמְעִידִים עֵדוּת שֶׁקֶר, וְאֵלּוּ הֵם בּוֹגְדִים שֶׁבָּגָדוּ, מְשַׁקְּרִים בְּעַצְמָם."],[11,"","וּבֶגֶד בּוֹגְדִים בָּגָדוּ - לְבוּשָׁם בְּלִי צִיצִית, נִקְרָא בֶּגֶד בּוֹגְדִים. לְבוּשׁ שֶׁל אוֹתָם בּוֹגְדִים שֶׁבָּגָדוּ, שֶׁמְּשַׁקְּרִים וּמְעִידִים עֵדוּת שֶׁקֶר בְּכָל יוֹם. אוֹי לָהֶם! אוֹי לְנַפְשָׁם! שֶׁעוֹלִים בְּאוֹתוֹ כִּסֵּא תְכֵלֶת לְהִדּוֹן, וַעֲלֵיהֶם כָּתוּב (תהלים קא) דֹּבֵר שְׁקָרִים לֹא יִכּוֹן לְנֶגֶד עֵינָי. אוֹתוֹ בֶּגֶד שֶׁלָּהֶם נוֹדָע לְכָל בַּעֲלֵי הַדִּינִים. אוֹי לָהֶם! שֶׁאֵין לָהֶם חֵלֶק בָּעוֹלָם הַבָּא. אַשְׁרֵיהֶם הַצַּדִּיקִים שֶׁלְּבוּשֵׁיהֶם וְתִקּוּנֵיהֶם נוֹדָעִים לְמַעְלָה לְהֵיטִיב לָהֶם בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא."],[12,"","מִצְוָה זוֹ מִצְוַת צִיצִית, כּוֹלֶלֶת תְּכֵלֶת וְלָבָן, דִּין וְרַחֲמִים בְּאֵשׁ. אֵשׁ לְבָנָה לֹא אוֹכֶלֶת, תְּכֵלֶת אוֹכֶלֶת וּמַשְׁמִידָה. (דברי הימים ב ז) וַתֹּאכַל הָעֹלָה. לָבָן מִיָּמִין, תְּכֵלֶת מִשְּׂמֹאל. הָעַמּוּד הָאֶמְצָעִי מְיַחֵד בֵּין שְׁנֵיהֶם - יָרֹק. וּמִשּׁוּם זֶה פֵּרְשׁוּהָ בַּעֲלֵי הַמִּשְׁנָה, מֵאֵימָתַי קוֹרִין אֶת שְׁמַע בְּשַׁחֲרִית? מִשֶּׁיַּכִּיר בֵּין תְּכֵלֶת לְלָבָן. וּמִשּׁוּם זֶה הִתְקִינוּ לְקָרְאָהּ בְּיִחוּד."]]],[["אָמַר רִבִּי יְהוּדָה, כַּמָּה סַהֲדֵי עָבִיד קוּדְשָׁא בְּרִיךְ הוּא לְאַסְהֲדָא בְּהוּ בִּבְנֵי נָשָׁא, וְכֻלְּהוּ בְּעֵיטָא וּבְסַהֲדוּתָא קַיְימִין לָקֳבְלֵיהּ. קָם בְּצַפְרָא אוֹשִׁיט רַגְלוֹי לְמֵהַךְ, סָהֲדַיָּיא קַיְימִין לָקֳבְלֵיהּ, מַכְרִיזִין וְאָמְרִין, (שמואל א ב׳:ט׳) רַגְלֵי חֲסִידָיו יִשְׁמוֹר וְגוֹ'. (קהלת ד׳:י״ז) שְׁמוֹר רַגְלְךָ כַּאֲשֶׁר תֵּלֵךְ. (משלי ד׳:כ״ו) פַּלֵּס מַעְגַּל רַגְלֶךָ. אַפְתַּח עֵינוֹי לְאִסְתַּכְּלָא בְּעָלְמָא, סָהֲדַיָּיא אָמְרֵי, (משלי ד׳:כ״ה) עֵינֶיךָ לְנֹכַח יַבִּיטוּ. קָם לְמַלְּלָא, סָהֲדַיָּיא אָמְרֵי (תהילים ל״ד:י״ד) נְצוֹר לְשׁוֹנְךָ מֵרָע וְגוֹ'. אוֹשִׁיט יְדוֹי בְּמִלֵּי עָלְמָא, סָהֲדַיָּיא אָמְרֵי (תהילים ל״ד:ט״ו) סוּר מֵרָע וַעֲשֵׂה טוֹב.","אִי צַיִית לְהוּ, יָאוּת. וְאִי לָא, כְּתִיב (זכריה ג׳:א׳) וְהַשָּׂטָן עוֹמֵד עַל יְמִינוֹ לְשִׂטְנוֹ. כֻּלְּהוּ סָהֲדִין עָלֵיהּ בְּחוֹבוֹי לְעֵילָּא. אִי בָּעֵי בַּר נָשׁ לְאִשְׁתַּדְּלָא בְּפוּלְחָנָא דְקוּדְשָׁא בְּרִיךְ הוּא, כֻּלְּהוּ סָהֲדִין סַנֵּיגוֹרִין קַמֵּיהּ, וְקַיְימִין לְאַסְהֲדָא עָלֵיהּ טָבָאן, בְּשַׁעֲתָא דְּאִצְטְרִיךְ לֵיהּ.","קָם בְּצַפְרָא, מְבָרֵךְ כַּמָה בִּרְכָאן. אֲנָח תְּפִילִין בְּרֵישֵׁיהּ בֵּין עֵינוֹי. בָּעֵי לְזַקְפָא רֵישֵׁיהּ, חָמֵי שְׁמָא קַדִּישָׁא עִלָּאָה, אָחִיד וְרָשִׁים עַל רֵישֵׁיהּ. וּרְצוּעִין תַּלְיָין מֵהַאי גִּיסָא וּמֵהַאי גִּיסָא עָל לִבֵּיהּ. הָא אֶסְתָּכַּל בִּיקָרָא דְּמָארֵיהּ. אוֹשִׁיט יְדוֹי, חָמֵי יְדָא אַחֲרָא, מִתְקַשְּׁרָא בְּקִשּׁוּרָא דִּשְׁמָא קַדִּישָׁא. אַהְדָּר יְדֵיהּ וְאִסְתָּכַּל בִּיקָרֵיהּ דְּמָארֵיהּ. אִתְעֲטָּף בְּעִטּוּפָא דְּמִצְוָה, בְּאַרְבַּע זִיוְיָין דִּכְסוּתֵיהּ, אַרְבַּע מַלְכִין נָפְקִין לְקַדְמוּת אַרְבַּע. אַרְבַּע סַהֲדֵי קְשׁוֹט דְּמַלְכָּא, תַּלְיָיא מֵאַרְבַּע זִיוְיָין, וְתַלְיָין בְּהוּ כַּעֲנָבִים בְּאִתְכְּלָא.","מָה אַתְכְּלָא, דְּאִיהוּ חַד, וְתַּלְיָין בֵּיהּ כַּמָה עֲנָבִים, מֵהַאי סְטָר וּמֵהַאי סְטָר. כַּךְ הַאי, מִצְוָה חֲדָא, וְתַּלְיָין בֵּיהּ כַּמָה עֲנָבִים, וְזָגִין וּזְמוֹרִין צְרִירִין בְּהוּ, שִׁבְעָה רְהִיטִין אִלֵּין אִינּוּן שִׁבְעָה צְרִירִין דִּתְכֶלְתָּא, דְּבָעֵי לְכַרְכָא בֵּיהּ בְּכָל חַד וְחָד, אוֹ לְאַסְגָּאָה עַד תְּלֵיסַר, מַאן דְּיוֹסִיף, לָא יוֹסִיף עָלַיְיהוּ עַל תְּלֵיסַר. מַאן דְּיִמְעַט, לָא יִמְעַט מִשִּׁבְעָה.","וְתָאנָא, הַאי תְּכֵלֶת, הוּא רָזָא דְּדָוִד מַלְכָּא. וְדָא חוּטָא דְּאַבְרָהָם, דְּזָכָה בֵּיהּ לִבְנוֹי בַּתְרוֹי. מַאי תְּכֵלֶת. תַּכְלִית דְּכֹלָּא. (ודאי) רִבִּי יְהוּדָה אוֹמֵר, כִּסֵּא הַכָּבוֹד אִקְרֵי.","רִבִּי יִצְחָק אָמַר, שִׁבְעָה כְּרִיכָן דְּאִיהִי שְׁכִינְתָּא שְׁבִיעָתָא דְּכֹלָּא וַדַּאי. דְּהָא הִיא מִתְבָּרְכָא מִשִׁיתָּא אַחֲרָנִין, עַל יְדָא דְּצַדִּיק. וְאִי תְּלַת עֲשַׂר, תְּלַת עֲשַׂר אִינּוּן, כְּמָה דְּאוּקְמוּהָ בִּתְלַת עֲשַׂר מְכִילָן. וְהַאי הִיא פִּתְחָא דְּכֻלְּהוּ.","וְהִיא חוּטָא חַד, וּרְשִׁימָא בִּגְוָונָהָא, וּגְוָונָא דִּילָהּ נָפִיק, מֵחַד נוּנָא דְּאָזִיל בְּיַם כִּנֶּרֶת. וְכִנֶּרֶת עַל שְׁמָהּ אִתְקְרֵי. וְעַל דָּא, כִּנּוֹר הֲוָה תָּלוּי לְעֵילָּא מֵעַרְסָא דְּדָוִד, דְּהָא (דדוד) וַדַּאי אִיהוּ כִּנּוֹר דְּדָוִד מְנַגֵּן מֵאֵלָיו, לְמַלְכָּא קַדִּישָׁא עִלָּאָה. וּבְגִין כָּךְ, גְּוָונוֹי עָיֵיל עַד רְקִיעָא, וּמֵרְקִיעָא עַד כּוּרְסְיָיא.","וְהָכָא כְּתִיב מִצְוָה, כְּמָה דְאַתְּ אָמֵר (מלכים ב י״ח:ל״ו) מִצְוַת הַמֶּלֶךְ הִיא. (אסתר ג׳:ג׳) מַדוּעַ אַתָּה עוֹבֵר אֵת מִצְוַת הַמֶּלֶךְ. (נחמיה י״א:כ״ג) כִּי מִצְוַת הַמֶּלֶךְ. וְתָאנָא, יְסוֹדָא וְשָׁרְשָׁא בְּמַלְכָּא מִתְעַטְּרִין כַּחֲדָא. וְהַאי הוּא כִּתְרָא וּפִתְחָא לְכָל שְׁאַר כִּתְרִין. דִּכְתִּיב, (תהילים קי״ח:י״ט) פִּתְחוּ לִי שַׁעֲרֵי צֶדֶק. וּכְתִיב, (תהילים קי״ח:י״ט) זֶה הַשַּׁעַר לַיְיָ. וְעַל דָּא כְּתִיב, וּרְאִיתֶם אוֹתוֹ וּזְּכַרְתֶּם אֶת כָּל מִצְוֹת יְיָ, לְאַכְלְלָא בְּהַאי כָּל שְׁאַר כִּתְרִין. וְעַל דָּא אִינּוּן סַהֲדֵי סַהֲדוּתָא, וְלָא קַיְימֵי בְּדוּכְתַּיְיהוּ בְּגִין דְּאִיהִי מִצְוַת.","וְתָנֵינָן, תַּשְׁמִישֵׁי מִצְוָה, נִזְרָקִין. וְאִי תֵּימָא, הָא לוּלָב וַעֲרָבָה וְכוּ', תַּשְׁמִישֵׁי קְדוּשָּׁה אִינּוּן, אֲמַאי נִזְרָקִין. אֶלָּא תַּשְׁמִישֵׁי קְדוּשָּׁה, בְּגִין דִּרְשִׁימִין בַּכְּתִיבָה דִּשְׁמָא קַדִּישָׁא.","אָמַר רִבִּי יִצְחָק, אִינּוּן חוּטִין, לְאַחֲזָאָה הֵיךְ תַּלְיָין מִכָּאן וּמִכָּאן, לְד' סִטְרֵי עָלְמָא, מֵהַאי אֲתָר. וְאִיהִי שַׁלְטָא עַל כֹּלָּא. בְּרָזָא דְּלֵב, דְּאִיהִי לִבָּא דְּכָל הַאי עָלְמָא, וְלִבָּא דְּעִלָּאֵי, וְתַלְיָא בַּלֵּב עִלָּאָה. וְכֹלָּא הוּא בַּלֵּב, דְּנָפַק מֵחָכְמָה עִלָּאָה. אָמַר רִבִּי יִצְחָק, שִׁעוּרָא דְּהַאי, (ס\"א ואורכא) דְּהַאי, אִתְּמַר בְּאַתְוָון גְּלִיפָן דְּרִבִּי אֶלְעָזָר.","אָמַר רִבִּי יְהוּדָה, אָמַר קוּדְשָׁא בְּרִיךְ הוּא, מַאן דְּבָעֵי לְמֵהַךְ בָּתַר דָּחַלְתִּי, יְהַךְ בָּתַר לִבָּא דָּא, וּבָתַר עַיְינִין דְּקַיְימִין עָלָהּ. מַאן אִינּוּן עַיְינִין. כְּמָה דְאַתְּ אָמֵר, (תהלים לא) עֵינֵי יְיָ אֶל צַדִּיקִים אֲבָל אַתֶּם לֹא תָתוּרוּ אַחֲרֵי לְבַבְכֶם וְאַחֲרֵי עֵינֵיכֶם. מַאי טַעְמָא בְּגִין דְּאַתֶּם זוֹנִים אַחֲרֵיהֶם."],[[0,"אמר רבי יהודה וכו׳:","אר״י, כמה עדים עשה הקב״ה להעיד בבני האדם, וכולם בעצה, ובעדות עומדים כנגדו. קם בבוקר ופושט את רגלו ללכת, העדים עומדים כנגדו ומכריזים ואומרים, רגלי חסידיו ישמור וגו'. שמור רגלך כאשר תלך. פלס מעגל רגלך. פותח עיניו להסתכל בעולם, אומרים העדים, עיניך לנכח יביטו. קם לדבר, אומרים העדים, נצור לשונך מרע וגו׳. מושיט ידיו לדברי העולם, אומרים העדים, סור מרע ועשה טוב."],[1,"אי ציית להו וכו׳:","אם שומע להם, טוב. ואם לא, כתוב, והשטן עומד על ימינו לשמנו. כולם מעידים עליו על עונותיו למעלה. ואם רוצה האדם לעסוק בעבודת הקב״ה, כל העדים נעשים מליצים טובים עליו, ועומדים להעיד עליו עדות טובה בשעה שצריך לה."],[2,"קם בצפרא מברך וכו׳:","קם בבוקר, מברך כמה ברכות, מניח תפלין בראשו בין עיניו. רוצה לזקוף ראשו, רואה שם הקדוש העליון אחוז ונרשם על ראשו, ורצועות תלויות מצד זה ומצד זה על לבו, הרי מסתכל בכבוד אדונו. פושט ידיו, רואה יד השניה מתקשרת בקשר של שם הקדוש. מחזיר ידיו ומסתכל בכבוד אדונו. מתעטף בעטוף של מצוה, בארבע כנפות כסותו, ארבעה מלכים יוצאים לפני ארבע, דהיינו ד׳ עדי אמת של המלך, שהם ד׳ ציצית, תלויות מארבע כנפות, ותלויות בהם כענבים באשכול, (וכבר נתבאר כל זה באות שכ״ג)."],[3,"מה אתכלא דאיהו וכו׳:","מה אשכיל, שהוא אחד, ותלוים בו כמה ענבים מצד זה ומצד זה, כך זה, הציצית, הם מצוה אחת ותלוים בו כמה ענבים וזגים וזמורות. דהיינו כמה מיני מדרגות כנ״ל. כרוכים בהם ז׳ רצים. אלו הם, ז׳ כריכות של תכלת, שצריכים לכרוך בכל אחת ואחת (כנ״ל אות שכ״ג) או להרבות עד י״ג כריכות, מי שמוסיף אל יוסיף עליהם על י״ג. ומי שממעט אל ימעט משבע."],[4,"ותאנא האי תכלת וכו׳:","ולמדנו, תכלת זו היא סוד דוד המלך. דהיינו מלכות, וזה החוט של אברהם. דהיינו בחינת המסך דקו ימין בסוד נקודת החולם (ב״א ט״ו ד״ה ההיא) ששם הוא נמתק בבינה, שזכה בו לבניו אחריו. מהו תכלת. היינו תכלית הכל. כי תקונה, הוא תכלית כל העולמות. ר׳ יהודה אומר היא נקראת כסא הכבוד. שהוא מלכות."],[5,"ר׳ יצחק אמר וכו׳:","רי״א ז׳ כריכות שכורכים על הציצית, היא השכינה, שהיא שביעית הכל ודאי, כי היא מתברכת משש ספירות האחרות חג״ת נה״י על ידי הצדיק, שהוא יסוד, וע״כ כוללת כל הז'. ואם עושים י״ג כריכות, י״ג הן כמו שהעמידוהו בי״ג מדות הרחמים. והמלכות היא הפתח של כולם וע״כ כוללת י״ג."],[6,"והיא חוטא חד וכו':","והיא, התכלת, היא חוט אחד ורשום בצבעיה, יהצבע שלה יוצא מדג אחד ההולך בים כנרת, ונקרא כנרת, על שם המלכות. ועל זה כנור היה תלוי למעלה מממתו של דוד, אשר כנור ה״ס המלכות, כי היא ודאי כנור של דוד המנגן מאליו למלך הקדוש העליון, שהוא ז״א. וע״כ צבעיו של תכלת, עולה עד לרקיע, שהוא ז״א, ומרקיע עד הכסא, שהיא בינה."],[7,"והכא כתיב מצוה וכו׳:","וכאן כתוב מצוה, דהיינו וזכרתם את כל מצות ה׳. משום שהמלכות נקראת \u0003מצוה,\u0004 כש״א, מצות המלך היא. \u0003הרומז למלכות.\u0004 מדוע אתה עובר את מצות המלך. כי מצות המלך. שכל אלו רומזים על המלכות הנקראת מצות המלך. ולמדנו, היסוד, שהיא ספירה אחרונה דז״א, והשורש, שהוא הכתר, שהוא שורש כל, מתעטרים יחד במלכות. וזו המלכות, היא הזכרון והפתח לכל שאר הספירות. שכתוב, פתחו לי שערי צדק. שהיא מלכות הנקראת צדק. וכתוב אחריו, זה השער לה׳. להיותה השער לכל הספירות. וע״כ כתוב וראיתם אותו וזכרתם את \u0003כל מצות ה׳,\u0004 שהכתוב בא לכלול בזה, במלכות, כל שאר הספירות אשר במלכות הנקראת מצות, נקראות כל הספירות הנכללות בה בשם \u0003מצות\u0004 וע״כ למדנו (לעיל אות שכ״ג) \u0003סהדי סהדותא ולא קיימי בדוכתייהו,\u0004 שהספירות דז״א מעידים עדות, שמגלים הארת חכמה הנקראת עדות. ואינם עומדים במקומם בז״א, משום שהיא \u0003מצות,\u0004 כי הציצית ה״ס המלכות נקראות מצוה, והספירות דז״א הכלולות בה נקראות מצות. וע״כ הם שלא במקומם, בז״א, אלא במלכות."],[8,"ותנינן תשמישי מצוה וכו׳:","ולמדנו תשמישי מצוה, דהיינו של המלכות, נזרקים. ואם תאמר, הרי לולב וערבה, אשר לולב רומז על יסוד דז״א, והערבות לנו״ה דז״א, וא״כ אינם תשמישי מצוה, אלא תשמישי קדושה, דהיינו בז״א, ולמה הם נזרקים. ומשיב. אלא תשמישי קדושה היינו משום שרשומים בכתב של שם הקדוש. אבל לולב וערבה, אע״פ שרומזים על ז״א, מ״מ הם כתשמישי מצוה, ונזרקים."],[9,"א״ר יצחק אינון וכו׳:","אר״י, אלו החוטים, דציצית, הם להראות, איך הם תלוים מכאן ומכאן לד׳ דוחות העולם ממקום זה, והיא, המלכות, שולטת על כולם בסוד \u0003לב,\u0004 שהיא הלב של כל עולם הזה, ולב העליונים, דהיינו מג׳ עולמות בי״ע, ותלויה בלב העליון, דז״א, והכל הוא בסוד הל״ב היוצא מחכמה העליונה, דהיינו ש \u0003לב\u0004 רומז, על ל״ב נתיבות החכמה המאירים בו. א״ר יצחק, שיעור של זה והאורך של זה, של הציצית, למדנו באותיות חקוקות של ר' אלעזר."],[10,"אמר ר׳ יהודה וכו׳:","אר״י, אמר הקב״ה, מי שרוצה ללכת אחר יראתי, ילך אחר לב הזה, שהוא המלכות, ואחרי העינים העומדות עליה. מי הן העינים. הוא כש״א, עיני הויה אל צדיקים. דהיינו עיני ז״א. אבל אתם לא תתורו אחרי לבבכם ואחרי עיניכם. מהו הטעם. משום שאתם זונים אחריהם."]],[[0,"","אָמַר רַבִּי יְהוּדָה, כַּמָּה עֵדִים עָשָׂה הַקָּדוֹשׁ בָּרוּךְ הוּא לְהָעִיד בָּהֶם בְּנֵי אָדָם, וְכֻלָּם בְּעֵצָה וּבְעֵדוּת עוֹמְדִים מוּלוֹ. קָם בַּבּקֶר, מוֹשִׁיט רַגְלָיו לָלֶכֶת - עֵדִים עוֹמְדִים מוּלוֹ, מַכְרִיזִים וְאוֹמְרִים: (שמואל א ב) רַגְלֵי חֲסִידָיו יִשְׁמֹר וְגוֹ'. (קהלת ד) שְׁמֹר רַגְלְךְ כַּאֲשֶׁר תֵּלֵךְ. (משלי ד) פַּלֵּס מַעְגַּל רַגְלֶךְ. פּוֹתֵחַ עֵינָיו לְהִסְתַּכֵּל בָּעוֹלָם - הָעֵדִים אוֹמְרִים: (שם) עֵינֶיךְ לְנֹכַח יַבִּיטוּ. קָם לְדַבֵּר - הָעֵדִים אוֹמְרִים: (תהלים לד) נְצֹר לְשׁוֹנְךְ מֵרָע וְגוֹ'. מוֹשִׁיט יָדָיו בְּדִבְרֵי הָעוֹלָם - הָעֵדִים אוֹמְרִים: (שם) סוּר מֵרָע וַעֲשֵׂה טוֹב."],[1,"","אִם מְצַיֵּת לָהֶם - יָפֶה, וְאִם לֹא - כָּתוּב (זכריה ג) וְהַשָּׂטָן עֹמֵד עַל יְמִינוֹ לְשִׂטְנוֹ. כֻּלָּם מְעִידִים עָלָיו בַּחֲטָאָיו לְמַעְלָה. אִם רוֹצֶה הָאִישׁ לְהִשְׁתַּדֵּל בַּעֲבוֹדַת הַקָּדוֹשׁ בָּרוּךְ הוּא - כֻּלָּם מְעִידִים סָנֵגוֹרְיָא לְפָנָיו, וְעוֹמְדִים לְהָעִיד עָלָיו טוֹבוֹת בְּשָׁעָה שֶׁצָּרִיךְ לוֹ."],[2,"","קָם בַּבּקֶר, מְבָרֵךְ כַּמָּה בְרָכוֹת. מֵנִיחַ תְּפִלִּין בְּרֹאשׁוֹ בֵּין עֵינָיו - רוֹצֶה לְהָרִים רֹאשׁוֹ, רוֹאֶה שֵׁם הַקָּדוֹשׁ הָעֶלְיוֹן אָחוּז וְרָשׁוּם עַל רֹאשׁוֹ. וּרְצוּעוֹת תְּלוּיוֹת לוֹ מִצַּד זֶה וּמִצַּד זֶה עַל לִבּוֹ. הֲרֵי מִסְתַּכֵּל בִּכְבוֹד רִבּוֹנוֹ. מוֹשִׁיט יָדָיו, רוֹאֶה יָד אַחֶרֶת מִתְקַשֶּׁרֶת בְּקֶשֶׁר הַשֵּׁם הַקָּדוֹשׁ, מַחֲזִיר יָדוֹ וּמִסְתַּכֵּל בִּכְבוֹד רִבּוֹנוֹ. מִתְעַטֵּף בְּעִטּוּף שֶׁל מִצְוָה בְּאַרְבַּע זָוִיּוֹת כְּסוּתוֹ, אַרְבָּעָה מְלָכִים יוֹצְאִים לִכְנֶגֶד אַרְבָּעָה. אַרְבָּעָה עֵדֵי אֱמֶת שֶׁל הַמֶּלֶךְ, תְּלוּיִים מֵאַרְבַּע זָוִיּוֹת, וּתְלוּיִים בָּהֶם כַּעֲנָבִים בָּאֶשְׁכּוֹל."],[3,"","מָה אֶשְׁכּוֹל שֶׁהוּא אֶחָד וּתְלוּיִים בּוֹ כַּמָּה עֲנָבִים, מִצַּד זֶה וּמִצַּד זֶה, כָּךְ זֶה מִצְוָה אַחַת, וּתְלוּיִים בָּהּ כַּמָּה עֲנָבִים זַגִּים וּזְמוֹרוֹת צְרוּרִים בָּהֶם. שִׁבְעָה רָצִים אֵלּוּ הֵם שִׁבְעָה צְרוֹרוֹת שֶׁל תְּכֵלֶת שֶׁצָּרִיךְ לִכְרֹךְ בָּהּ בְּכָל אֶחָד וְאֶחָד, אוֹ לְהַגְדִּיל עַד שְׁלֹשָׁה עָשָׂר. מִי שֶׁיּוֹסִיף, לֹא יוֹסִיף עַל שְׁלֹשָׁה עָשָׂר. מִי שֶׁיְּמַעֵט, לֹא יְמַעֵט מִשִּׁבְעָה."],[4,"","וְלָמַדְנוּ, תְּכֵלֶת זוֹ הִיא סוֹד דָּוִד הַמֶּלֶךְ, וְזֶה חוּט אַבְרָהָם שֶׁזָּכָה בּוֹ לְבָנָיו אַחֲרָיו. מַה זֶּה תְּכֵלֶת? תַּכְלִית הַכֹּל. (ודאי) רַבִּי יְהוּדָה אוֹמֵר, כִּסֵּא הַכָּבוֹד נִקְרָא."],[5,"","רַבִּי יִצְחָק אָמַר, שֶׁבַע כְּרִיכוֹת שֶׁהִיא שְׁכִינָה שְׁבִיעִית הַכֹּל בְּוַדַּאי. שֶׁהֲרֵי הִיא מִתְבָּרֶכֶת מִשִּׁשָּׁה אֲחֵרִים עַל יְדֵי הַצַּדִּיק. וְאִם שְׁלֹשָׁה עָשָׂר, שְׁלֹשָׁה עָשָׂר הֵם, כְּמוֹ שֶׁבֵּאֲרוּהָ בִּשְׁלֹשׁ עֶשְׂרֵה מִדּוֹת, וְזֶהוּ פֶּתַח הַכֹּל."],[6,"","וְהִיא חוּט אֶחָד, וּרְשׁוּמָה בִגְוָנֶיהָ, וְצִבְעָהּ יוֹצֵא מִדָּג אֶחָד שֶׁהוֹלֵךְ בְּיָם כִּנֶּרֶת. וְכִנֶּרֶת נִקְרֵאת עַל שְׁמָהּ. וְעַל זֶה כִּנּוֹר הָיָה תָלוּי מֵעַל מִטַּת דָּוִד, שֶׁהֲרֵי (של דוד) וַדַּאי הוּא כִּנּוֹר דָּוִד מְנַגֵּן מֵאֵלָיו לַמֶּלֶךְ הַקָּדוֹשׁ הָעֶלְיוֹן, וְלָכֵן גְּוָנָיו עוֹלִים עַד הָרָקִיעַ, וּמֵהָרָקִיעַ עַד הַכִּסֵּא."],[7,"","וְכָאן כָּתוּב מִצְוָה, כְּמוֹ שֶׁנֶּאֱמַר (מלכים ביח) מִצְוַת הַמֶּלֶךְ הִיא. (אסתר ג) מַדּוּעַ אַתָּה עוֹבֵר אֵת מִצְוַת הַמֶּלֶךְ. כִּי מִצְוַת הַמֶּלֶךְ. וְלָמַדְנוּ, יְסוֹד וְשֹׁרֶשׁ בַּמֶּלֶךְ מִתְעַטְּרִים כְּאֶחָד, וְזוֹהִי זִכָּרוֹן וּפֶתַח לְכָל שְׁאָר הַכְּתָרִים, שֶׁכָּתוּב (תהלים קיח) פִּתְחוּ לִי שַׁעֲרֵי צֶדֶק. וְכָתוּב זֶה הַשַּׁעַר לַה'. וְעַל זֶה כָּתוּב וּרְאִיתֶם אֹתוֹ וּזְכַרְתֶּם אֶת מִצְות ה', לְהַכְלִיל בָּזֶה כָּל שְׁאָר הַכְּתָרִים. וְלָכֵן הֵם מְעִידִים עֵדוּת וְלֹא עוֹמְדִים בִּמְקוֹמָם, מִשּׁוּם שֶׁהִיא מִצְוַת."],[8,"","וְשָׁנִינוּ, תַּשְׁמִישֵׁי מִצְוָה נִזְרָקִין. וְאִם תֹּאמַר, הֲרֵי לוּלָב וַעֲרָבָה תַּשְׁמִישֵׁי קְדֻשָּׁה הֵם, לָמָּה נִזְרָקִים? אֶלָּא תַּשְׁמִישֵׁי קְדֻשָּׁה, מִשּׁוּם שֶׁרְשׁוּמִים בִּכְתִיבַת הַשֵּׁם הַקָּדוֹשׁ."],[9,"","אָמַר רַבִּי יִצְחָק, אוֹתָם חוּטִים, לְהַרְאוֹת אֵיךְ תְּלוּיִים מִכָּאן וּמִכָּאן לְאַרְבָּעָה צִדְדֵי הָעוֹלָם מִמָּקוֹם זֶה, וְהִיא שׁוֹלֶטֶת עַל הַכֹּל בְּסוֹד הַלֵּב, שֶׁהִיא לֵב כָּל הָעוֹלָם הַזֶּה וְלֵב הָעֶלְיוֹנִים, וּתְלוּיָה בַּלֵּב הָעֶלְיוֹן, וְהַכֹּל הוּא בַּלֵּב שֶׁיּוֹצֵא מֵחָכְמָה עֶלְיוֹנָה. אָמַר רַבִּי יִצְחָק, שִׁעוּר שֶׁל זֶה (וארך) שֶׁל זֶה נִתְבָּאֵר בְּאוֹתִיּוֹת חֲקוּקוֹת שֶׁל רַבִּי אֶלְעָזָר."],[10,"","אָמַר רַבִּי יְהוּדָה, אָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא: מִי שֶׁרוֹצֶה לָלֶכֶת אַחַר יִרְאָתִי, יֵלֵךְ אַחַר הַלֵּב הַזֶּה וְאַחֲרֵי הָעֵינַיִם שֶׁעוֹמְדִים עָלֶיהָ. מִי הֵם עֵינַיִם אֵלֶּה? כְּמוֹ שֶׁנֶּאֱמַר (תהלים לד) עֵינֵי ה' אֶל צַדִּיקִים. אֲבָל אַתֶּם, לֹא תָתוּרוּ אַחֲרֵי לְבַבְכֶם וְאַחֲרֵי עֵינֵיכֶם. מָה הַטַּעַם? מִשּׁוּם שֶׁאַתֶּם זֹּנִים אַחֲרֵיהֶם."]]],[["אָמַר רִבִּי חִיָיא, מַאי טַעֲמָא הָכָא יְצִיאַת מִצְרַיִם, דִּכְתִּיב אֲשֶׁר הוֹצֵאתִי אֶתְכֶם מֵאֶרֶץ מִצְרַיִם. אֶלָּא, בְּגִין דְּכַד נַפְקוּ מִמִּצְרָיִם, בְּהַאי חוּלָקָא עָאל. וּבְהַאי, קָטִיל קוּדְשָׁא בְּרִיךְ הוּא קָטוּלָא דְּמִצְרַיִם. וְעַל דָּא בְּאַתְרֵיהּ אִתְדְּכַר, וּבְאַתְרֵיהּ אִזְדְּהַר לְהוּ בְּדָא. מַאי בְּאַתְרֵיהּ. בְּגִין דְּהַאי מִצְוָה, הִיא אֲתָר דִּילָהּ.","תָּאנֵי רִבִּי יֵיסָא, כְּתִיב (מיכה ז׳:ט״ו) כִּימֵי צֵאתְךָ מֵאֶרֶץ מִצְרַיִם אַרְאֶנּוּ נִפְלָאוֹת. כִּימֵי, כַּיּוֹם מִבָּעֵי לֵיהּ, דְּהָא בְּחַד זִמְנָא נַפְקוּ וְלָא אִתְעַכְּבוּ. אֶלָּא כְּאִינּוּן יוֹמִין עִלָּאִין, דְּאִתְבָּרְכָא בְּהוּ כְּנֶסֶת יִשְׂרָאֵל. כַּךְ זַמִּין קוּדְשָׁא בְּרִיךְ הוּא לְאַפָּקָא לְהוּ לְיִשְׂרָאֵל מִן גָּלוּתָא, וּכְדֵין כְּתִיב (ישעיהו י״ב:ד׳) וַאֲמַרְתֶּם בַּיוֹם הַהוּא הוֹדוּ לַיְיָ קִרְאוּ וְגוֹ', זַמְּרוּ יְיָ כִּי גֵּאוּת עָשָׂה מוּדַעַת זֹאת בְּכָל הָאָרֶץ. מַאי מוּדַעַת זֹאת. בְּגִין דְּהַשְׁתָּא אִשְׁתְּמוֹדְעָא זֹאת בְּעִטּוּפָא דְּמִצְוָה. בְּהַהוּא זִמְנָא אִשְׁתְּמוֹדְעָא זֹאת, בְּכַמָּה נִמוּסִין דִּילָהּ, דְּיַעֲבֵיד קוּדְשָׁא בְּרִיךְ הוּא אָתִין וְנִסִּין בְּעָלְמָא, כְּדֵין כְּתִיב (זכריה י״ד:ט׳) בַּיוֹם הַהוּא יִהְיֶה יְיָ אֶחָד וּשְׁמוֹ אֶחָד. בָּרוּךְ יְיָ לְעוֹלָם אָמֵן וְאָמֵן. יִמְלוֹךְ יְיָ לְעוֹלָם אָמֵן וְאָמֵן."],[[0,"אמר ר׳ חייא וכו׳:","אר״ח, מהו הטעם שנזכר כאן יציאת מצרים, שכתוב, אשר הוצאתי אתכם מארץ מצרים. ומשיב, אלא משום כשיצאו ממצרים נכנסו בחלק הזה שהוא המלכות. ובזה במלכות, הרג הקב״ה הרוגי מצרים. ועל כן נזכרת יציאת מצרים במקומו, ובמקומו הזהיר להם בזה שכתוב אני ה׳ אשר הוצאתי וגו׳. מהו במקומו. הוא משום שמצוה זו דציצית, היא מקום שלה. של המלכות."],[1,"תאני ר׳ ייסא וכו׳:","למד ר׳ ייסא, כתוב, כימי צאתך מארץ מצרים אראנו נפלאות. שואל, כימי, כיום היה צריך לומר. שהרי בפעם אחת יצאו ולא נתעכבו. ומשיב, אלא הפירוש הוא, \u0003כימים\u0004 האלו העליונים, חג״ת נה״י דז״א, שנתברכה בהם כנסת ישראל. כך עתיד הקב״ה להוציא את ישראל מן הגלות, ע״י ימים דז״א, ואז כתוב ואמרתם ביום ההוא הודו לה׳ קראו וגו׳ זמרו ה׳ כי גאות עשה מודעת זאת בכל הארץ. מהו מודעת זאת. ומשיב, משום שעתה נודעת \u0003זאת,\u0004 שהיא המלכות, בעטוף טלית של מצוה, דהיינו בציצית. בעת ההיא תהיה נודעת \u0003זאת\u0004 בכמה דרכים שלה, שיעשה הקב״ה אותות ונסים בעולם, אז כתוב, ביום ההוא יהיה ה׳ אחד ושמו אחד. ברוך ה׳ לעולם אמן ואמן. ימלוך ה׳ לעולם אמן ואמן."]],[[0,"","אָמַר רַבִּי חִיָּיא, מָה הַטַּעַם כָּאן יְצִיאַת מִצְרַיִם, שֶׁכָּתוּב אֲשֶׁר הוֹצֵאתִי אֶתְכֶם מֵאֶרֶץ מִצְרַיִם? אֶלָּא מִשּׁוּם שֶׁכְּשֶׁיָּצְאוּ מִמִּצְרַיִם, נִכְנְסוּ בְּחֵלֶק זֶה, וּבָזֶה הָרַג הַקָּדוֹשׁ בָּרוּךְ הוּא הֶרֶג בְּמִצְרַיִם. וְלָכֵן בִּמְקוֹמוֹ נִזְכַּר, וּבִמְקוֹמוֹ הִזְהִירָם בָּזֶה. מַה זֶּה בִּמְקוֹמוֹ? מִשּׁוּם שֶׁמִּצְוָה זוֹ הִיא מְקוֹמָהּ."],[1,"","שָׁנָה רַבִּי יֵיסָא, כָּתוּב (מיכה ז) כִּימֵי צֵאתְךְ מֵאֶרֶץ מִצְרָיִם אַרְאֶנּוּ נִפְלָאוֹת. כִּימֵי?! כַּיּוֹם הָיָה צָרִיךְ לוֹ לִכְתֹּב, שֶׁהֲרֵי בִּזְמַן אֶחָד יָצְאוּ, וְלֹא הִתְעַכְּבוּ! אֶלָּא כְּמוֹ אוֹתָם יָמִים עֶלְיוֹנִים שֶׁהִתְבָּרְכָה בָהֶם כְּנֶסֶת יִשְׂרָאֵל, כָּךְ עָתִיד הַקָּדוֹשׁ בָּרוּךְ הוּא לְהוֹצִיא אֶת יִשְׂרָאֵל מֵהַגָּלוּת, וְאָז כָּתוּב (ישעיה יב) וַאֲמַרְתֶּם בַּיּוֹם הַהוּא הוֹדוּ לַה' קִרְאוּ וְגוֹ', זַמְּרוּ ה' כִּי גֵאוּת עָשָׂה מוּדַעַת זֹּאת בְּכָל הָאָרֶץ. מַה זֶּה מוּדַעַת זֹּאת? מִשּׁוּם שֶׁעַכְשָׁו נוֹדְעָה זֹּאת בְּעִטּוּף מִצְוָה. בְּאוֹתוֹ זְמַן תִּוָּדַע זֹּאת בְּכַמָּה מִנְהָגִים שֶׁלָּהּ שֶׁיַּעֲשֶׂה הַקָּדוֹשׁ בָּרוּךְ הוּא אוֹתוֹת וְנִסִּים בָּעוֹלָם, אָז כָּתוּב (זכריה יד) בַּיּוֹם הַהוּא יִהְיֶה ה' אֶחָד וּשְׁמוֹ אֶחָד. בָּרוּךְ ה' לְעוֹלָם אָמֵן וְאָמֵן. יִמְלֹךְ ה' לְעוֹלָם אָמֵן וְאָמֵן."]]]]};
